--
-- Name: _swap_spots_generate_product_json(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._swap_spots_generate_product_json(p_product_id bigint, p_spot_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    product_data RECORD;
BEGIN
    -- This query joins product, its type, and the spot (if provided)
    -- to get all data needed for the JSON object.
    SELECT
        p.id,
        p.price,
        p.title,
        p.description,
        p.currency_code,
        pt.title AS type_title,
        pt.type AS type,
        s.title AS spot_title
    INTO
        product_data
    FROM
        eshop.products AS p
    JOIN
        eshop.product_types AS pt ON p.product_type = pt.id
    LEFT JOIN
        eshop.spots AS s ON s.id = p_spot_id -- Use p_spot_id for spot_title
    WHERE
        p.id = p_product_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product data not found for product_id %', p_product_id;
    END IF;

    -- Build the JSON object.
    -- jsonb_strip_nulls ensures that if 'spot_title' is NULL
    -- (because p_spot_id was NULL), the key is removed entirely.
    RETURN jsonb_strip_nulls(jsonb_build_object(
        'id', product_data.id,
        'type', product_data.type,
        'price', product_data.price,
        'title', product_data.title,
        'spot_title', product_data.spot_title,
        'type_title', product_data.type_title,
        'description', product_data.description,
        'currency_code', product_data.currency_code
    )) || coalesce(public.order_spot_metadata_internal(p_spot_id), '{}'::jsonb);
END;
$$;


ALTER FUNCTION public._swap_spots_generate_product_json(p_product_id bigint, p_spot_id bigint) OWNER TO postgres;

--
-- Name: _swap_spots_update_ticket(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._swap_spots_update_ticket(p_opt_id bigint, p_new_product_id bigint, p_new_spot_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    opt RECORD;
    ord RECORD;
    original_product_id BIGINT;
    original_product_json JSONB;
    original_price NUMERIC;

    new_product_json JSONB;
    new_price NUMERIC;
    new_data JSONB;
    new_order_price NUMERIC;
    new_state TEXT;

    price_delta NUMERIC;
    history_needed BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Get current ticket and order data
    SELECT * INTO opt FROM eshop.order_product_ticket WHERE id = p_opt_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order Product Ticket % not found', p_opt_id; END IF;

    PERFORM public.check_ticket_is_mutable(opt.ticket);
    PERFORM public.check_batch_ticket_print_immutable_internal(ARRAY[opt.ticket]);
    SELECT * INTO ord FROM eshop.orders WHERE id = opt."order" FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order % not found', opt."order"; END IF;

    original_product_id := opt.product;

    -- 2. Find the *original* product JSON and price from the order_ids.data
    SELECT prod, (prod->>'price')::numeric
    INTO original_product_json, original_price
    FROM jsonb_array_elements(ord.data->'tickets') tckt,
         jsonb_array_elements(tckt->'products') prod
    WHERE (tckt->>'id')::bigint = opt.ticket
      AND (prod->>'id')::bigint = original_product_id;

    IF original_price IS NULL THEN
        RAISE EXCEPTION 'Could not find original price for product % on ticket %', original_product_id, opt.ticket;
    END IF;

    -- 3. Generate the *new* product JSON
    new_product_json := public._swap_spots_generate_product_json(p_new_product_id, p_new_spot_id);
    new_price := (new_product_json->>'price')::numeric;
    IF new_product_json->>'currency_code' IS DISTINCT FROM ord.currency_code THEN
      RAISE EXCEPTION 'BLUEPRINT_CURRENCY_MISMATCH'; END IF;

    -- 4. Check if an update is even needed.
    -- If the new JSON is identical to the old, nothing needs to be done.
    IF original_product_json = new_product_json THEN
        RETURN;
    END IF;

    -- 5. Calculate financials and state
    price_delta := new_price - original_price;
    history_needed := (original_product_id IS DISTINCT FROM p_new_product_id);
    new_order_price := COALESCE(ord.price, 0) + price_delta;

    -- Recalculate order state
    SELECT CASE
        WHEN COALESCE(pi.paid, 0) >= new_order_price AND new_order_price > 0 THEN 'paid'
        WHEN new_order_price <= 0 THEN 'paid'
        ELSE 'ordered'
    END INTO new_state
    FROM (SELECT COALESCE((SELECT paid FROM eshop.payment_info WHERE id=ord.payment_info),0) AS paid) pi;

    -- 6. Build the new order_ids.data JSON
    new_data := jsonb_set(
        ord.data,
        '{tickets}',
        (SELECT jsonb_agg(
            -- Find the matching ticket
            CASE WHEN (tckt->>'id')::bigint = opt.ticket
            THEN jsonb_set(
                tckt,
                '{products}',
                (SELECT jsonb_agg(
                    -- Find the matching product and replace it
                    CASE
                        WHEN (prod->>'id')::bigint = original_product_id
                        THEN new_product_json -- Swap in the new product JSON
                        ELSE prod
                    END
                ) FROM jsonb_array_elements(tckt->'products') prod)
            )
            ELSE tckt
            END
        ) FROM jsonb_array_elements(ord.data->'tickets') tckt)
    );

    -- 7. Perform all database updates

    -- Update payment info
    IF price_delta <> 0 THEN
        IF EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=ord.payment_info AND public.payment_method_is_online_internal(payment_method)) THEN
            RAISE EXCEPTION 'STRIPE_ORDER_PRICE_IMMUTABLE'; END IF;
        UPDATE eshop.payment_info SET amount = amount + price_delta WHERE id = ord.payment_info;
    END IF;

    -- Update the order itself
    UPDATE eshop.orders
    SET
        price = new_order_price,
        data = new_data,
        state = new_state,
        updated_at = now_time
    WHERE id = ord.id;

    -- Update the link table
    UPDATE eshop.order_product_ticket
    SET
        product = p_new_product_id
    WHERE id = p_opt_id;

    -- 8. Create history log *only if* the product ID actually changed
    IF history_needed THEN
        INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
        VALUES (ord.id, new_data, new_state, new_order_price, ord.currency_code);
    END IF;

END;
$$;


ALTER FUNCTION public._swap_spots_update_ticket(p_opt_id bigint, p_new_product_id bigint, p_new_spot_id bigint) OWNER TO postgres;

--
-- Name: abort_fakturoid_ticket_order_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_fakturoid_ticket_order_v1(p_order_id bigint, p_command_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_state text;
  v_occasion bigint;
  v_queue_id bigint;
  v_before_users uuid[];
  v_abort_command uuid := extensions.gen_random_uuid();
  v_hash text;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
  IF EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command_id AND target_order_id=p_order_id AND state='aborted') THEN RETURN; END IF;
  SELECT o.state,o.occasion INTO v_state,v_occasion
  FROM eshop.orders o WHERE o.id=p_order_id FOR UPDATE;
  IF v_state='storno' THEN RETURN; END IF;
  IF v_state IS DISTINCT FROM 'preparing_payment' OR p_command_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order is not pending';
  END IF;
  SELECT q.id INTO v_queue_id FROM public.email_messages q
  WHERE q.code='TICKET_ORDER_CONFIRMATION'
    AND q.data->>'command_id'=p_command_id::text
    AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order_id
    AND q.data->>'fakturoid_pending'='true'
  FOR UPDATE;
  IF v_queue_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order confirmation claim missing';
  END IF;
  SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
  FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order_id,'reason','fakturoid_failed')::text,'UTF8'),'sha256'),'hex');
  PERFORM public.begin_anonymous_client_mutation_v1(v_abort_command,
    'inventory.order.fakturoid_abort',v_occasion,extensions.gen_random_uuid(),v_hash);
  UPDATE public.email_messages SET workflow_state='cancelled',last_error='fakturoid_aborted' WHERE id=v_queue_id;
  IF NOT public.abort_waitlist_acceptance_internal(p_order_id,p_command_id) THEN
    UPDATE eshop.orders SET state='ordered' WHERE id=p_order_id;
    PERFORM public.cancel_order_domain_internal_v1(p_order_id,false);
  END IF;
  PERFORM public.complete_profile_inventory_membership_mutation_v1(
    v_abort_command,v_occasion,'inventory.order.fakturoid_abort',
    jsonb_build_array(jsonb_build_object('entityType','order',
      'entityId',p_order_id,'operation','update','safeLabel','Failed order',
      'changedFields',jsonb_build_array('state','tickets','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order_id),'service');
END;
$$;


ALTER FUNCTION public.abort_fakturoid_ticket_order_v1(p_order_id bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: abort_waitlist_acceptance_internal(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_waitlist_acceptance_internal(p_order bigint, p_command uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a eshop.waitlist_acceptance_attempts; s jsonb; p jsonb; expiry timestamptz;
 original_ticket eshop.tickets; restored_outcome text; original_id bigint;
BEGIN
 SELECT * INTO a FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command AND target_order_id=p_order;
 IF a.command_id IS NULL THEN RETURN false; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[a.source_order_id,a.target_order_id]);
 SELECT * INTO STRICT a FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command FOR UPDATE;
 IF a.state='aborted' THEN RETURN true; END IF;
 IF a.state<>'preparing' THEN RAISE EXCEPTION 'Acceptance attempt already completed'; END IF;
 SELECT expires_at INTO expiry FROM eshop.waitlist_offers WHERE id=a.offer_id FOR UPDATE;
 PERFORM public.cancel_order_email_intents(p_order);
 PERFORM public.internal_storno_tickets_221(a.ticket_ids);
 DELETE FROM eshop.order_product_ticket WHERE "order"=a.target_order_id AND ticket=ANY(a.ticket_ids);
 IF a.conversion='in_place' THEN
  -- The restored order may be accepted again with a new confirmation payload.
  -- Keep the cancelled attempt immutable and allocate a new email identity once.
  UPDATE eshop.orders SET state='waitlisted',price=NULL,payment_info=NULL,data=a.previous_order_data->'data',
   email_payment_version=email_payment_version+1,updated_at=clock_timestamp() WHERE id=a.target_order_id;
 ELSE
  UPDATE eshop.orders SET state='storno',price=0,payment_info=NULL,updated_at=clock_timestamp() WHERE id=a.target_order_id;
 END IF;
 -- Only the selected tickets are fenced by the preparing target. Never restore
 -- unselected/displaced answers or resurrect a concurrently withdrawn remainder.
 FOR p IN SELECT * FROM jsonb_array_elements(a.previous_tickets) LOOP
  IF NOT (p->>'id')::bigint=ANY(a.ticket_ids) THEN CONTINUE; END IF;
  UPDATE eshop.tickets SET state=p->>'state',ticket_symbol=p->>'ticket_symbol',data=p->'data',note=p->>'note',
   note_hidden=p->>'note_hidden',waitlist_queue_at=(p->>'waitlist_queue_at')::timestamptz,updated_at=clock_timestamp() WHERE id=(p->>'id')::bigint;
 END LOOP;
 INSERT INTO eshop.order_product_ticket SELECT * FROM jsonb_populate_recordset(NULL::eshop.order_product_ticket,a.previous_links);
 UPDATE eshop.waitlist_offer_slots SET outcome='accepted' WHERE id=ANY(a.slot_ids);
 FOR s IN SELECT * FROM jsonb_array_elements(a.previous_slots) LOOP
  original_id:=(s->>'ticket_id')::bigint;
  SELECT * INTO STRICT original_ticket FROM eshop.tickets WHERE id=original_id FOR UPDATE;
  restored_outcome:=CASE
   WHEN original_ticket.state<>'waitlisted' OR NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=original_id AND x."order"=a.source_order_id)
    OR EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots other WHERE other.ticket_id=original_id AND other.outcome='pending' AND NOT other.id=ANY(a.slot_ids)) THEN 'cancelled'
   WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots other JOIN eshop.waitlist_offers ow ON ow.id=other.offer_id
     WHERE other.ticket_id=original_id AND other.outcome IN ('declined','cancelled')
     AND ow.created_at>(SELECT created_at FROM eshop.waitlist_offers WHERE id=a.offer_id)) THEN 'cancelled'
   WHEN expiry<=clock_timestamp() THEN 'expired' ELSE 'pending' END;
  UPDATE eshop.waitlist_offer_slots SET ticket_id=original_id,outcome=restored_outcome,resulting_order_id=NULL,updated_at=clock_timestamp() WHERE id=(s->>'id')::uuid;
  IF restored_outcome='expired' AND original_ticket.state='waitlisted' THEN
   UPDATE eshop.tickets SET waitlist_queue_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=original_id;
  END IF;
 END LOOP;
 UPDATE eshop.waitlist_acceptance_attempts SET state='aborted',updated_at=clock_timestamp() WHERE command_id=p_command;
 UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=(SELECT form FROM eshop.orders WHERE id=a.source_order_id);
 INSERT INTO eshop.orders_history("order",state,data) VALUES(a.source_order_id,'waitlisted',jsonb_build_object('action','acceptance_aborted','commandId',p_command,'targetOrderId',a.target_order_id));
 PERFORM public.notification_center_order_capacity_internal(a.source_order_id);
 PERFORM public.notification_center_order_state_internal(p_order);
 RETURN true;
END $$;


ALTER FUNCTION public.abort_waitlist_acceptance_internal(p_order bigint, p_command uuid) OWNER TO postgres;

--
-- Name: abuse_charge_v1(jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abuse_charge_v1(p_policy jsonb, p_scopes jsonb, p_costs jsonb DEFAULT '{}'::jsonb, p_attempt boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r jsonb; s text; n bigint; used bigint; lim bigint; bucket timestamptz;
 t timestamptz:=statement_timestamp(); allowed boolean:=true; cost bigint; failed_rule text;
 retry_seconds integer:=0; needs_change boolean:=false; release_at timestamptz;
BEGIN
 IF p_policy IS NULL OR jsonb_array_length(p_policy->'rules')=0 THEN
  RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_policy->'rules') ORDER BY value->>'rule_key' LOOP
  s:=p_scopes->>(r->>'scope_kind');
  IF s IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='abuse_scope_missing'; END IF;
  IF r->>'kind' IN ('bytes','duration','items') THEN CONTINUE; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||s,0));
 END LOOP;
 -- Check every rule before changing any accepted-operation counter.
 FOR r IN SELECT value FROM jsonb_array_elements(p_policy->'rules') ORDER BY value->>'rule_key' LOOP
  s:=p_scopes->>(r->>'scope_kind');
  cost:=coalesce((p_costs->>(r->>'rule_key'))::bigint,1);
  IF cost<0 THEN RAISE invalid_parameter_value USING MESSAGE='negative abuse cost'; END IF;
  lim:=least((r->>'hard_cap')::bigint,(r->>'base_limit')::bigint+
   least(coalesce((p_costs->>'growth')::bigint,0),1000000000)*(r->>'growth_increment')::bigint);
  IF r->>'kind'='rolling' THEN
   bucket:=to_timestamp(floor(extract(epoch FROM t)/(r->>'bucket_seconds')::int)*(r->>'bucket_seconds')::int);
   SELECT coalesce(sum(amount),0) INTO used FROM public.abuse_budget_usage
    WHERE rule_key=r->>'rule_key' AND scope_id=s
     AND bucket_at>=bucket-make_interval(secs=>(r->>'window_seconds')::int);
  ELSIF r->>'kind'='cumulative' THEN
   bucket:='epoch'::timestamptz;
   SELECT coalesce(sum(amount),0) INTO used FROM public.abuse_budget_usage WHERE rule_key=r->>'rule_key' AND scope_id=s;
  ELSE used:=0; END IF;
  IF used+cost>lim THEN
   allowed:=false; failed_rule:=coalesce(failed_rule,r->>'rule_key');
   IF NOT p_attempt AND r->>'kind'='rolling' AND cost<=lim THEN
    SELECT q.bucket_at INTO release_at FROM (
     SELECT bucket_at,sum(amount) OVER(ORDER BY bucket_at) AS released FROM public.abuse_budget_usage
     WHERE rule_key=r->>'rule_key' AND scope_id=s AND bucket_at>=bucket-make_interval(secs=>(r->>'window_seconds')::int)
    ) q WHERE q.released>=used+cost-lim ORDER BY q.bucket_at LIMIT 1;
    retry_seconds:=greatest(retry_seconds,ceil(extract(epoch FROM release_at+make_interval(secs=>(r->>'window_seconds')::int+(r->>'bucket_seconds')::int)-t))::integer);
   ELSIF r->>'kind'='cumulative' OR (cost>lim AND r->>'kind' IN ('bytes','items','duration')) THEN needs_change:=true;
   ELSE retry_seconds:=greatest(retry_seconds,60); END IF;
  END IF;
 END LOOP;
 IF NOT allowed AND NOT p_attempt THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded',DETAIL=jsonb_build_object('retryAfterSeconds',CASE WHEN needs_change THEN NULL ELSE greatest(retry_seconds,1) END,'needsPolicyChange',needs_change,'policyRevision',p_policy->'revision','ruleKey',failed_rule)::text,HINT='Capacity is limited. Retry later or request a reviewed policy increase.'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_policy->'rules') ORDER BY value->>'rule_key' LOOP
  IF r->>'kind' NOT IN ('rolling','cumulative') THEN CONTINUE; END IF;
  s:=p_scopes->>(r->>'scope_kind'); cost:=coalesce((p_costs->>(r->>'rule_key'))::bigint,1);
  IF cost=0 THEN CONTINUE; END IF;
  bucket:=CASE WHEN r->>'kind'='cumulative' THEN 'epoch'::timestamptz ELSE to_timestamp(floor(extract(epoch FROM t)/(r->>'bucket_seconds')::int)*(r->>'bucket_seconds')::int) END;
  INSERT INTO public.abuse_budget_usage VALUES(r->>'rule_key',s,bucket,cost,
   CASE WHEN r->>'kind'='cumulative' THEN 'infinity'::timestamptz ELSE bucket+make_interval(secs=>(r->>'window_seconds')::int+(r->>'bucket_seconds')::int) END)
  ON CONFLICT(rule_key,scope_id,bucket_at) DO UPDATE SET amount=least(1000000000001,public.abuse_budget_usage.amount+excluded.amount);
 END LOOP;
 RETURN allowed;
END $$;


ALTER FUNCTION public.abuse_charge_v1(p_policy jsonb, p_scopes jsonb, p_costs jsonb, p_attempt boolean) OWNER TO postgres;

--
-- Name: abuse_effective_rules_v1(text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abuse_effective_rules_v1(p_budget text, p_unit bigint, p_org bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object('revision',v.revision,'rules',coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object(
 'base_limit',coalesce(u.base_limit,o.base_limit,r.base_limit)) ORDER BY r.rule_key),'[]'::jsonb))
 FROM public.abuse_policy_revision v CROSS JOIN public.abuse_policy_rules r
 LEFT JOIN public.abuse_policy_overrides o ON o.rule_key=r.rule_key AND o.target_kind='organization'
  AND o.target_id=p_org AND r.scope_kind IN ('unit','organization') AND o.expires_at>statement_timestamp()
 LEFT JOIN public.abuse_policy_overrides u ON u.rule_key=r.rule_key AND u.target_kind='unit'
  AND u.target_id=p_unit AND r.scope_kind='unit' AND u.expires_at>statement_timestamp()
 WHERE r.budget_key=p_budget GROUP BY v.revision
 HAVING count(*)=CASE p_budget WHEN 'occasion.creation' THEN 8 WHEN 'occasion.copy' THEN 2 WHEN 'occasion.draft' THEN 7
  WHEN 'unit.creation' THEN 3 WHEN 'email.ordinary' THEN 4 WHEN 'email.auth' THEN 4
  WHEN 'email.backlog' THEN 4 WHEN 'email.auth.backlog' THEN 1 WHEN 'email.payload' THEN 1
  WHEN 'email.prepare' THEN 2 WHEN 'email.actor' THEN 1 WHEN 'email.dispatch' THEN 1 WHEN 'ticket.document' THEN 4 WHEN 'ticket.preview' THEN 4 WHEN 'bank.operation' THEN 3 WHEN 'stripe.connect' THEN 3 WHEN 'stripe.checkout' THEN 3 WHEN 'barion.checkout' THEN 3 WHEN 'order.creation' THEN 4 WHEN 'qr.global' THEN 1 WHEN 'qr.proof' THEN 1 WHEN 'qr.payload' THEN 1 WHEN 'spot.hold' THEN 3 WHEN 'image.upload' THEN 5 WHEN 'image.fetch' THEN 5 WHEN 'sync.snapshot' THEN 2 WHEN 'sync.work' THEN 1 WHEN 'hold.duration' THEN 1 WHEN 'auth.reset.source' THEN 2 WHEN 'organization.creation' THEN 1 WHEN 'auth.reset.account' THEN 1
  WHEN 'auth.google.source' THEN 1 WHEN 'auth.google.client' THEN 1 WHEN 'auth.google.global' THEN 1 WHEN 'auth.google.attempt' THEN 1 WHEN 'auth.google.proof' THEN 1
  WHEN 'scan.operation' THEN 2 WHEN 'scan.invalid.global' THEN 1 WHEN 'scan.invalid.source' THEN 1 WHEN 'scan.password' THEN 2 WHEN 'scan.export' THEN 2
  WHEN 'reception.create' THEN 1 WHEN 'reception.issue' THEN 1 WHEN 'reception.revoke' THEN 1 WHEN 'reception.cancel' THEN 1
  WHEN 'order.mutation' THEN 4 WHEN 'batch-create' THEN 1 WHEN 'batch-document' THEN 2
  WHEN 'push.delivery' THEN 10
  WHEN 'cleaning.report' THEN 3
  WHEN 'push.dispatch' THEN 2
  WHEN 'image.records' THEN 9 WHEN 'auth.password' THEN 2 WHEN 'document.output' THEN 4 WHEN 'image.storage' THEN 3 WHEN 'monitor.thresholds' THEN 6 WHEN 'auth.password.change' THEN 3
  WHEN 'email.send.ordinary' THEN 2 WHEN 'email.send.auth' THEN 2 WHEN 'email.send.commitment' THEN 2
  ELSE -1 END;
$$;


ALTER FUNCTION public.abuse_effective_rules_v1(p_budget text, p_unit bigint, p_org bigint) OWNER TO postgres;

--
-- Name: abuse_health_internal_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abuse_health_internal_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE queues jsonb; expired_at timestamptz; evidence_at timestamptz; capacity jsonb;
BEGIN
 SELECT jsonb_object_agg(class,stats) INTO queues FROM (
  SELECT class,jsonb_build_object(
   'pendingCount',least(5000,(SELECT count(*) FROM (
     SELECT 1 FROM public.email_messages WHERE admission_class=class
      AND workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown') LIMIT 5001
    ) q)),
   'countCappedAt',5000,
   'oldestCreatedAt',(SELECT created_at FROM public.email_messages WHERE admission_class=class
     AND workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown') ORDER BY created_at LIMIT 1),
   -- Historical uncertain sends and future schedules remain visible in counts,
   -- but only runnable work can age into a stalled-delivery alert.
   'oldestDueAt',(SELECT min(greatest(created_at,target_time)) FROM public.email_messages WHERE admission_class=class
     AND workflow_state IN ('pending','preparing','sending','retry_wait') AND target_time<=statement_timestamp())
  ) stats FROM unnest(ARRAY['ordinary','auth','commitment']) class
 ) q;
 SELECT expires_at INTO expired_at FROM public.abuse_budget_usage WHERE expires_at<statement_timestamp() ORDER BY expires_at LIMIT 1;
 SELECT measured_at INTO evidence_at FROM public.abuse_unit_evidence ORDER BY measured_at LIMIT 1;
 SELECT jsonb_build_object('paused',paused,'quotaMeasuredAt',quota_at,'circuitUntil',circuit_until,
   'nextSendAt',next_send_at,'providerOutageStreak',provider_outage_streak) INTO capacity FROM public.email_capacity LIMIT 1;
 RETURN jsonb_build_object('measuredAt',statement_timestamp(),
  'policyRevision',(SELECT revision FROM public.abuse_policy_revision WHERE singleton),
  'queue',queues,'oldestExpiredUsageAt',expired_at,'oldestGrowthEvidenceAt',evidence_at,'provider',capacity);
END $$;


ALTER FUNCTION public.abuse_health_internal_v1() OWNER TO postgres;

