--
-- Name: admit_ticket_document_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admit_ticket_document_internal_v1(p_occasion bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o public.occasions; policy jsonb;
BEGIN
 SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
 policy:=public.abuse_effective_rules_v1('ticket.document',o.unit,o.organization);
 IF auth.uid() IS NULL THEN
  policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(value) FROM jsonb_array_elements(policy->'rules') WHERE value->>'scope_kind'<>'actor'));
 END IF;
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization));
END $$;


ALTER FUNCTION public.admit_ticket_document_internal_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: admit_ticket_preview_limits_v1(bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admit_ticket_preview_limits_v1(p_occasion bigint, p_bytes bigint, p_read_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o public.occasions;
BEGIN
 IF p_read_only THEN
  IF NOT public.can_preview_ticket_readonly(p_occasion) THEN RETURN NULL; END IF;
  IF p_bytes IS NULL OR p_bytes<=0 THEN RAISE invalid_parameter_value USING MESSAGE='preview bytes required'; END IF;
  SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
  PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('ticket.preview',o.unit,o.organization),jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization),jsonb_build_object('ticket.preview.payload.bytes',p_bytes));
 ELSIF NOT public.admit_ticket_preview_v1(p_occasion,p_bytes) THEN RETURN NULL; END IF;
 RETURN public.bound_document_data_v1('{}');
END $$;


ALTER FUNCTION public.admit_ticket_preview_limits_v1(p_occasion bigint, p_bytes bigint, p_read_only boolean) OWNER TO postgres;

--
-- Name: admit_ticket_preview_v1(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admit_ticket_preview_v1(p_occasion bigint, p_bytes bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o public.occasions;
BEGIN
 IF public.can_edit_ticket_layout(p_occasion) IS NOT TRUE THEN RETURN false; END IF;
 IF p_bytes IS NULL OR p_bytes<=0 THEN RAISE invalid_parameter_value USING MESSAGE='preview bytes required'; END IF;
 SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('ticket.preview',o.unit,o.organization),
  jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization),jsonb_build_object('ticket.preview.payload.bytes',p_bytes));
 RETURN true;
END $$;


ALTER FUNCTION public.admit_ticket_preview_v1(p_occasion bigint, p_bytes bigint) OWNER TO postgres;

