--
-- Name: assert_form_primary_products_internal(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assert_form_primary_products_internal(p_form bigint, p_preserve bigint[] DEFAULT '{}'::bigint[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM unnest(p_preserve) required(id) WHERE NOT EXISTS(
   SELECT 1 FROM public.form_fields ff JOIN eshop.product_types pt ON pt.id=ff.product_type
   WHERE ff.form=p_form AND pt.id=required.id AND pt.type='spot' AND ff.type='product_type' AND NOT ff.is_hidden))
 OR EXISTS(SELECT 1 FROM public.form_fields ff JOIN eshop.product_types pt ON pt.id=ff.product_type
   WHERE ff.form=p_form AND pt.type='spot' AND (ff.is_hidden OR NOT EXISTS(
     SELECT 1 FROM eshop.products p WHERE p.product_type=pt.id AND NOT p.is_hidden)))
 OR (EXISTS(SELECT 1 FROM public.form_fields WHERE form=p_form AND type='ticket')
   AND EXISTS(SELECT 1 FROM public.form_fields WHERE form=p_form AND type='product_type' AND NOT is_hidden)
   AND NOT EXISTS(SELECT 1 FROM public.form_fields ff JOIN eshop.product_types pt ON pt.id=ff.product_type
     WHERE ff.form=p_form AND pt.type='spot' AND NOT ff.is_hidden)) THEN
   RAISE EXCEPTION 'FORM_DELETE_primary_product';
 END IF;
END $$;


ALTER FUNCTION public.assert_form_primary_products_internal(p_form bigint, p_preserve bigint[]) OWNER TO postgres;

--
-- Name: assert_form_seating_source_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assert_form_seating_source_internal(p_form bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.forms f JOIN public.form_fields ff ON ff.form=f.id AND NOT ff.is_hidden
 JOIN eshop.products p ON p.product_type=ff.product_type AND NOT p.is_hidden
 JOIN eshop.spots s ON s.product=p.id JOIN eshop.blueprint_seat_bindings sb ON sb.spot=s.id
 JOIN public.form_seating_transitions t ON t.blueprint=sb.blueprint AND t.state='published'
 WHERE f.id=p_form AND f.is_open AND f.blueprint IS DISTINCT FROM t.blueprint) THEN RAISE EXCEPTION 'ADMISSION_SOURCE_REQUIRES_SEATING'; END IF;
END $$;


ALTER FUNCTION public.assert_form_seating_source_internal(p_form bigint) OWNER TO postgres;

--
-- Name: assert_group_place_owner_internal_v1(bigint, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assert_group_place_owner_internal_v1(p_occasion bigint, p_group bigint, p_place bigint, p_removing boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM 1 FROM public.places p WHERE p.id=p_place AND p.occasion=p_occasion AND p.type='group' AND p.is_hidden FOR UPDATE;
 IF NOT FOUND OR (SELECT count(*) FROM public.user_group_info WHERE place=p_place)<>1 OR NOT EXISTS(SELECT 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion AND place=p_place)
 OR EXISTS(SELECT 1 FROM public.activity_assignment_places WHERE place_id=p_place)
 OR EXISTS(SELECT 1 FROM public.activity_places WHERE place_id=p_place)
 OR EXISTS(SELECT 1 FROM public.events WHERE place=p_place)
 OR EXISTS(SELECT 1 FROM public.resources WHERE place=p_place)
 OR (p_removing AND (EXISTS(SELECT 1 FROM public.cleaning_reports WHERE place=p_place) OR EXISTS(SELECT 1 FROM public.cleaning_public_state WHERE place=p_place))) THEN
 RAISE invalid_parameter_value USING MESSAGE='private group place has ambiguous or external ownership'; END IF;
END $$;


ALTER FUNCTION public.assert_group_place_owner_internal_v1(p_occasion bigint, p_group bigint, p_place bigint, p_removing boolean) OWNER TO postgres;

