--
-- Name: attach_event_live_projection_v1(uuid, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_event_live_projection_v1(p_commit_id uuid, p_occasion bigint, p_event_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_revision bigint;
BEGIN
  IF p_commit_id IS NULL OR p_occasion IS NULL OR p_event_ids IS NULL
     OR cardinality(p_event_ids)=0 OR array_position(p_event_ids,NULL) IS NOT NULL
     OR NOT EXISTS (SELECT 1 FROM public.client_commits c
                    WHERE c.commit_id=p_commit_id AND c.occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid event live projection attachment';
  END IF;
  IF EXISTS (SELECT 1 FROM public.client_commit_components c
             WHERE c.commit_id=p_commit_id AND c.component='live_public'
               AND c.scope_type='occasion' AND c.scope_id=p_occasion) THEN
    RETURN;
  END IF;
  INSERT INTO public.client_sync_scopes(component,scope_type,scope_id,source_revision)
  VALUES ('live_public','occasion',p_occasion,1)
  ON CONFLICT (component,scope_type,scope_id) DO UPDATE
    SET source_revision=public.client_sync_scopes.source_revision+1,updated_at=now()
  RETURNING source_revision INTO v_revision;
  INSERT INTO public.client_commit_components
    (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
  VALUES (p_commit_id,'live_public','occasion',p_occasion,NULL,v_revision);
  INSERT INTO public.client_projection_dirty_keys
    (component,scope_type,scope_id,entity_id,source_revision)
  SELECT 'live_public','occasion',p_occasion,id,v_revision
  FROM (SELECT DISTINCT unnest(p_event_ids) id) ids
  ON CONFLICT (component,scope_type,scope_id,entity_id) DO UPDATE
    SET source_revision=GREATEST(public.client_projection_dirty_keys.source_revision,
        EXCLUDED.source_revision),dirty_since=now(),claimed_at=NULL,claim_token=NULL;
  PERFORM public.refresh_event_public_state_internal_v1(p_occasion,p_event_ids);
END; $$;


ALTER FUNCTION public.attach_event_live_projection_v1(p_commit_id uuid, p_occasion bigint, p_event_ids bigint[]) OWNER TO postgres;

--
-- Name: attach_provider_order_source_internal(bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_provider_order_source_internal(p_order bigint, p_command uuid, p_input jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE method text; field text;
BEGIN
 SELECT p.payment_method INTO method FROM eshop.orders o JOIN eshop.payment_info p ON p.id=o.payment_info WHERE o.id=p_order;
 IF NOT public.payment_method_is_online_internal(method) THEN RETURN; END IF;
 SELECT source_field INTO STRICT field FROM eshop.payment_providers WHERE provider_key=method;
 PERFORM public.payment_provider_call_internal(method,'attach_source',jsonb_build_object('orderId',p_order,'commandId',p_command,'source',p_input->field));
END $$;


ALTER FUNCTION public.attach_provider_order_source_internal(p_order bigint, p_command uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: attach_stripe_handoff_internal(bigint, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_stripe_handoff_internal(p_order bigint, p_command uuid, p_token_hash text, p_livemode boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE a eshop.stripe_checkout_attempts; cap eshop.stripe_capabilities;
BEGIN
 PERFORM public.require_service_role();
 IF p_token_hash IS NULL OR p_token_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE order_id=p_order ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 IF a.livemode IS DISTINCT FROM p_livemode OR NOT EXISTS(SELECT 1 FROM eshop.stripe_payment_link_sources s
  JOIN eshop.stripe_capabilities pc USING(token_hash) WHERE s.command_id=p_command AND pc.order_id=p_order AND pc.scope='order_pay'
   AND pc.revoked_at IS NULL AND pc.expires_at>clock_timestamp() AND s.expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 INSERT INTO eshop.stripe_capabilities(token_hash,scope,order_id,attempt_id,expires_at)
 VALUES(p_token_hash,'handoff',p_order,a.id,least(a.reservation_expires_at,a.created_at+interval '30 minutes'))
 ON CONFLICT(token_hash) DO NOTHING;
 SELECT * INTO STRICT cap FROM eshop.stripe_capabilities WHERE token_hash=p_token_hash;
 IF cap.scope<>'handoff' OR cap.order_id<>p_order OR cap.attempt_id<>a.id THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 -- Replaying creation must never renew, unconsume or un-revoke a handoff.
END $_$;


ALTER FUNCTION public.attach_stripe_handoff_internal(p_order bigint, p_command uuid, p_token_hash text, p_livemode boolean) OWNER TO postgres;

--
-- Name: attach_stripe_order_pay_source_internal(bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_stripe_order_pay_source_internal(p_order bigint, p_command uuid, p_source jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE a eshop.stripe_checkout_attempts; expiry timestamptz:=clock_timestamp()+interval '30 days';
BEGIN
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE order_id=p_order FOR UPDATE;
 IF p_command IS NULL OR p_source->>'tokenHash' IS NULL OR p_source->>'tokenHash' !~ '^[a-f0-9]{64}$'
  OR p_source->>'returnHash' IS NULL OR p_source->>'returnHash' !~ '^[a-f0-9]{64}$'
  OR p_source->>'tokenHash'=p_source->>'returnHash'
  OR p_source->>'contentHash' IS NULL OR p_source->>'contentHash' !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(p_source->'sealed') IS DISTINCT FROM 'object'
  OR p_source#>>'{sealed,v}' IS DISTINCT FROM '1'
  OR nullif(p_source#>>'{sealed,ciphertext}','') IS NULL OR nullif(p_source#>>'{sealed,iv}','') IS NULL THEN
  RAISE EXCEPTION 'STRIPE_PAYMENT_SOURCE_REQUIRED'; END IF;
 INSERT INTO eshop.stripe_capabilities(token_hash,scope,order_id,attempt_id,expires_at)
 VALUES(p_source->>'tokenHash','order_pay',p_order,NULL,expiry),
  (p_source->>'returnHash','return_read',p_order,a.id,a.reservation_expires_at+interval '1 day');
 INSERT INTO eshop.stripe_payment_link_sources(token_hash,sealed,content_hash,expires_at,command_id)
 VALUES(p_source->>'tokenHash',p_source->'sealed',p_source->>'contentHash',expiry,p_command);
END $_$;


ALTER FUNCTION public.attach_stripe_order_pay_source_internal(p_order bigint, p_command uuid, p_source jsonb) OWNER TO postgres;

