--
-- Name: authorize_authoring_export(bigint, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_authoring_export(p_occasion bigint, p_organization bigint, p_unit bigint, p_dataset text, p_columns jsonb DEFAULT '[]'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF p_dataset IN ('report','orders') THEN
  IF NOT public.can_read_orders(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order report/export denied'; END IF;
 ELSIF p_dataset='people' THEN
  IF NOT public.can_manage_occasion_participants(p_occasion) OR ((p_columns ?| ARRAY['email','phone','birthDate']) AND NOT public.can_read_participant_contacts(p_occasion)) THEN
   RAISE insufficient_privilege USING MESSAGE='participant export denied'; END IF;
 ELSIF p_dataset IN ('events','speakers','places') THEN PERFORM public.require_program_domain_internal_v1(p_occasion,p_dataset,false);
 ELSIF p_dataset='feedback' THEN
  IF NOT public.can_read_schedule_feedback(p_occasion) OR NOT public.get_is_event_feedback_enabled_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='feedback export denied'; END IF;
 ELSE RAISE invalid_parameter_value USING MESSAGE='unsupported export dataset'; END IF;
 RETURN true;
END $$;


ALTER FUNCTION public.authorize_authoring_export(p_occasion bigint, p_organization bigint, p_unit bigint, p_dataset text, p_columns jsonb) OWNER TO postgres;

--
-- Name: authorize_image_deletion(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_image_deletion(p_links text[]) RETURNS TABLE(link text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_requested_count integer;
  v_found_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '42501';
  END IF;

  v_requested_count := cardinality(p_links);
  IF v_requested_count IS NULL OR v_requested_count < 1 OR v_requested_count > 50
     OR array_position(p_links, NULL) IS NOT NULL
     OR v_requested_count <> (SELECT count(DISTINCT requested) FROM unnest(p_links) AS requested) THEN
    RAISE EXCEPTION 'Image link batch must contain 1-50 unique non-null links.'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(DISTINCT image.link) INTO v_found_count
  FROM public.images AS image
  WHERE image.link = ANY(p_links);

  IF v_found_count <> v_requested_count THEN
    RAISE EXCEPTION 'Every image link must exist.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.images AS image
    WHERE image.link = ANY(p_links)
      AND NOT (
        (image.unit IS NOT NULL AND public.can_upload_unit_media(image.unit))
        OR
        (image.occasion IS NOT NULL AND public.can_upload_occasion_media(image.occasion))
      )
  ) THEN
    RAISE EXCEPTION 'Permission denied for image deletion.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS(SELECT 1 FROM public.blueprint_image_assets a WHERE a.url=ANY(p_links)) THEN
    RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_IMMUTABLE'; END IF;

  RETURN QUERY
  SELECT DISTINCT image.link
  FROM public.images AS image
  WHERE image.link = ANY(p_links)
  ORDER BY image.link;
END;
$$;


ALTER FUNCTION public.authorize_image_deletion(p_links text[]) OWNER TO postgres;

--
-- Name: authorize_stripe_capability_internal(text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_stripe_capability_internal(p_token text, p_scope text, p_order bigint, p_attempt uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_cap eshop.stripe_capabilities;
BEGIN
 PERFORM public.require_service_role();
 IF p_token IS NULL OR p_token !~ '^[a-f0-9]{64}$' OR p_scope IS NULL OR p_scope NOT IN ('order_pay','handoff','return_read') THEN
  RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 SELECT * INTO v_cap FROM eshop.stripe_capabilities
 WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') AND scope=p_scope
 AND order_id=p_order AND revoked_at IS NULL AND expires_at>clock_timestamp()
 AND (p_attempt IS NULL OR attempt_id=p_attempt)
 AND (scope<>'handoff' OR consumed_at IS NULL) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 IF p_scope='handoff' THEN UPDATE eshop.stripe_capabilities SET consumed_at=clock_timestamp() WHERE token_hash=v_cap.token_hash; END IF;
 RETURN jsonb_build_object('orderId',v_cap.order_id,'attemptId',v_cap.attempt_id,'scope',v_cap.scope,'expiresAt',v_cap.expires_at);
END $_$;


ALTER FUNCTION public.authorize_stripe_capability_internal(p_token text, p_scope text, p_order bigint, p_attempt uuid) OWNER TO postgres;

