--
-- Name: begin_email_send(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_email_send(p_attempt uuid, p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_attempt public.email_attempts; v_row public.email_messages; v_cap public.email_capacity; v_rate numeric; v_daily numeric; v_used numeric; v_detail text; v_retry integer;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.forms f JOIN public.sale_opening_campaigns c ON c.form_id=f.id
  JOIN public.email_messages m ON m.data->>'campaign_id'=c.id::text
  JOIN public.email_attempts a ON a.message_id=m.message_id
  WHERE a.attempt_id=p_attempt AND m.message_kind IN ('sale_opening_opened') FOR UPDATE OF f;
 SELECT * INTO v_cap FROM public.email_capacity FOR UPDATE;
 SELECT * INTO v_attempt FROM public.email_attempts WHERE attempt_id=p_attempt;
 SELECT * INTO v_row FROM public.email_messages WHERE message_id=v_attempt.message_id;
 IF v_row.order_id IS NOT NULL THEN PERFORM 1 FROM eshop.orders WHERE id=v_row.order_id FOR UPDATE; END IF;
 SELECT * INTO v_attempt FROM public.email_attempts WHERE attempt_id=p_attempt FOR UPDATE;
 SELECT * INTO v_row FROM public.email_messages WHERE message_id=v_attempt.message_id FOR UPDATE;
 IF v_attempt.lease_token IS DISTINCT FROM p_token OR v_row.lease_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'stale_email_attempt'; END IF;
 IF v_attempt.state<>'preparing' THEN RETURN jsonb_build_object('disposition','replay','state',v_attempt.state); END IF;
 IF v_row.workflow_state<>'preparing' OR v_row.lease_until<=now() OR v_row.prepared IS NULL THEN RAISE EXCEPTION 'stale_email_attempt'; END IF;
 IF NOT public.email_intent_valid(v_row) OR EXISTS(SELECT 1 FROM public.email_suppressions WHERE recipient=lower(v_row.recipient)) THEN
  UPDATE public.email_messages SET last_error=CASE WHEN v_row.message_kind='sale_opening_opened' THEN 'intent_invalid' ELSE last_error END,workflow_state=CASE WHEN EXISTS(SELECT 1 FROM public.email_suppressions WHERE recipient=lower(v_row.recipient)) THEN 'suppressed' ELSE 'cancelled' END WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now() WHERE attempt_id=p_attempt;
  PERFORM public.notification_center_email_internal(v_row.message_id);
  RETURN jsonb_build_object('disposition','cancelled');
 END IF;
 -- A partial acceptance can change a queued offer after its rendered snapshot
 -- was cached. Re-render within this same queue before granting a send permit.
 IF v_row.message_kind='waitlist_offer' AND
  (v_row.post_action->>'waitlist_pending_count')::bigint IS DISTINCT FROM
  (SELECT count(*) FROM eshop.waitlist_offer_slots
   WHERE offer_id=(v_row.data->>'offer_id')::uuid AND outcome='pending') THEN
  UPDATE public.email_messages SET workflow_state='pending',target_time=now(),
   prepared=NULL,prepared_hash=NULL,prepared_at=NULL,
   post_action=post_action-'waitlist_pending_count',lease_token=NULL,lease_until=NULL,
   last_error='offer_snapshot_changed' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),
   error_code='offer_snapshot_changed' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END IF;
 v_rate:=CASE WHEN v_cap.shared_account THEN least(v_cap.max_rate*0.8,v_cap.allocated_rate) ELSE v_cap.max_rate*0.8 END*v_cap.rate_factor;
 v_daily:=CASE WHEN v_cap.shared_account THEN least(v_cap.daily_quota,v_cap.allocated_daily) ELSE v_cap.daily_quota END*0.9;
 -- Count all local starts since snapshot plus provider's rolling usage; conservative during drift.
 SELECT count(*) INTO v_used FROM public.email_attempts WHERE began_at>now()-interval '24 hours' AND (began_at>v_cap.quota_at OR state IN ('sending','unknown')) AND state IN ('sending','accepted','unknown');
 IF v_cap.paused OR v_cap.quota_at IS NULL OR v_cap.quota_at<now()-interval '15 minutes' OR v_rate IS NULL OR v_rate<=0 OR v_daily IS NULL
 OR (v_cap.shared_account AND (v_cap.allocated_rate IS NULL OR v_cap.allocated_daily IS NULL)) OR v_cap.provider_sent_24h+v_used>=v_daily
 OR v_cap.next_send_at>now() OR v_cap.circuit_until>now()
 OR (v_cap.provider_outage_streak>0 AND v_cap.probe_until>now())
 OR (SELECT count(*) FROM public.email_messages WHERE workflow_state='sending' AND lease_until>now())>=v_cap.max_sending THEN
  UPDATE public.email_messages SET workflow_state='pending',target_time=greatest(now()+interval '1 second',coalesce(v_cap.next_send_at,now()),coalesce(v_cap.circuit_until,now()),coalesce(v_cap.probe_until,now())),lease_token=NULL,lease_until=NULL,last_error='capacity_deferred' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),error_code='capacity_deferred' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END IF;
 -- Recipient admission at enqueue does not protect against many future intents
 -- converging on one date. Meter the actual fenced send, with separate essential
 -- classes so ordinary bulk cannot consume Auth or accepted-order capacity.
 BEGIN
  PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('email.send.'||v_row.admission_class,v_row.unit,v_row.organization),
   jsonb_build_object('recipient',public.abuse_recipient_key_v1(v_row.recipient)));
 EXCEPTION WHEN SQLSTATE 'PT429' THEN
  GET STACKED DIAGNOSTICS v_detail=PG_EXCEPTION_DETAIL;
  v_retry:=greatest(coalesce((v_detail::jsonb->>'retryAfterSeconds')::integer,60),1);
  UPDATE public.email_messages SET workflow_state='pending',target_time=now()+make_interval(secs=>v_retry),lease_token=NULL,lease_until=NULL,last_error='recipient_deferred' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),error_code='recipient_deferred' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END;
 UPDATE public.email_capacity SET next_send_at=clock_timestamp()+make_interval(secs=>(1/v_rate)::double precision),
 probe_until=CASE WHEN provider_outage_streak>0 THEN now()+interval '90 seconds' ELSE NULL END,
 probe_attempt=CASE WHEN provider_outage_streak>0 THEN p_attempt ELSE NULL END WHERE singleton;
 UPDATE public.email_attempts SET state='sending',began_at=now() WHERE attempt_id=p_attempt;
 UPDATE public.email_messages SET workflow_state='sending',attempt_count=attempt_count+1 WHERE id=v_row.id;
 RETURN jsonb_build_object('disposition','send','message',to_jsonb(v_row));
END $$;


ALTER FUNCTION public.begin_email_send(p_attempt uuid, p_token uuid) OWNER TO postgres;

--
-- Name: begin_stripe_connection_flow(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_stripe_connection_flow(p_unit bigint, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE nonce text; flow uuid; org bigint; previous uuid; deadline timestamptz;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF NOT public.stripe_unit_feature_enabled_internal(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='STRIPE_FEATURE_DISABLED'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.stripe_disconnect_intents intent JOIN eshop.stripe_connections c ON c.id=intent.connection_id
  WHERE c.unit_id=p_unit AND c.livemode=p_livemode AND intent.state<>'completed') THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_PENDING'; END IF;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('stripe.connect',p_unit,org),
  jsonb_build_object('actor',auth.uid(),'unit',p_unit,'organization',org));
 SELECT id INTO previous FROM eshop.stripe_connections WHERE unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted');
 nonce:=encode(extensions.gen_random_bytes(32),'hex');
 deadline:=clock_timestamp()+interval '10 minutes';
 INSERT INTO eshop.stripe_connection_flows(state_hash,actor,organization_id,unit_id,livemode,previous_connection_id,expires_at)
 VALUES(encode(extensions.digest(nonce,'sha256'),'hex'),auth.uid(),org,p_unit,p_livemode,previous,deadline) RETURNING id INTO flow;
 RETURN jsonb_build_object('flowId',flow,'state',nonce,'expiresAt',deadline);
END $$;


ALTER FUNCTION public.begin_stripe_connection_flow(p_unit bigint, p_livemode boolean) OWNER TO postgres;

--
-- Name: begin_stripe_disconnect(bigint, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_stripe_disconnect(p_unit bigint, p_livemode boolean, p_expected_connection uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c eshop.stripe_connections; intent eshop.stripe_disconnect_intents;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 PERFORM 1 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion WHERE o.unit=p_unit ORDER BY f.id FOR UPDATE OF f;
 PERFORM 1 FROM public.units WHERE id=p_unit FOR UPDATE;
 -- Completed intents also retain their binding. A lost final response must
 -- resume that same intent after the connection was retired, not dispatch again.
 SELECT i.* INTO intent FROM eshop.stripe_disconnect_intents i
 JOIN eshop.stripe_connections stored ON stored.id=i.connection_id
 WHERE i.connection_id=p_expected_connection AND i.actor=auth.uid()
  AND stored.unit_id=p_unit AND stored.livemode=p_livemode
 ORDER BY i.created_at DESC LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('intentId',intent.id); END IF;
 SELECT * INTO c FROM eshop.stripe_connections WHERE id=p_expected_connection AND unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_RECIPIENT_CHANGED'; END IF;
 SELECT * INTO intent FROM eshop.stripe_disconnect_intents WHERE connection_id=c.id AND state<>'completed';
 IF FOUND THEN
  IF intent.actor<>auth.uid() THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_PENDING'; END IF;
  RETURN jsonb_build_object('intentId',intent.id);
 END IF;
 IF EXISTS(SELECT 1 FROM eshop.stripe_connection_flows WHERE unit_id=p_unit AND livemode=p_livemode AND expires_at>clock_timestamp() AND state IN ('pending','claimed','uncertain')) THEN RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_PENDING'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.stripe_checkout_attempts WHERE connection_id=c.id AND
  (state IN ('preparing','open','uncertain') OR lease_expires_at>clock_timestamp() OR refund_cursor IS NOT NULL OR session_lookup_cursor IS NOT NULL)) THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_OPEN_ATTEMPTS'; END IF;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('stripe.connect',p_unit,c.organization_id),jsonb_build_object('actor',auth.uid(),'unit',p_unit,'organization',c.organization_id));
 INSERT INTO eshop.stripe_disconnect_intents(connection_id,actor) VALUES(c.id,auth.uid()) RETURNING * INTO intent;
 UPDATE eshop.stripe_connections SET paused=true,next_check_at=clock_timestamp() WHERE id=c.id;
 INSERT INTO eshop.stripe_connection_audit(connection_id,actor,action) VALUES(c.id,auth.uid(),'paused');
 RETURN jsonb_build_object('intentId',intent.id);
END $$;


ALTER FUNCTION public.begin_stripe_disconnect(p_unit bigint, p_livemode boolean, p_expected_connection uuid) OWNER TO postgres;

--
-- Name: begin_stripe_disconnect_client_sync_v1(bigint, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_stripe_disconnect_client_sync_v1(p_unit bigint, p_livemode boolean, p_expected_connection uuid, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE begun jsonb; hash text; result jsonb;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit,'live',p_livemode,'connection',p_expected_connection)::text,'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.cards.disconnect',p_unit,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 result:=public.begin_stripe_disconnect(p_unit,p_livemode,p_expected_connection);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.cards.disconnect','unit',p_unit,'update',result);
END $$;


ALTER FUNCTION public.begin_stripe_disconnect_client_sync_v1(p_unit bigint, p_livemode boolean, p_expected_connection uuid, p_command_id uuid) OWNER TO postgres;

--
-- Name: begin_unit_client_mutation_v1(uuid, text, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT (CASE WHEN p_command_name IN ('occasion.create','occasion.setup.finalize')
       THEN public.can_create_occasion(p_unit)
       WHEN p_command_name='occasion.delete' THEN public.can_delete_occasion_in_unit(p_unit)
       WHEN p_command_name IN ('unit.information.save','unit.information.delete')
         THEN public.can_write_unit_information(p_unit)
       WHEN p_command_name IN ('unit.icon.save','unit.icon.delete')
         THEN public.can_write_unit_icons(p_unit)
       WHEN p_command_name IN ('unit.email_template.save','unit.email_template.reset','unit.email_banner.save')
         THEN public.can_write_unit_email_templates(p_unit)
       WHEN p_command_name IN ('profile.unit_access.delete','profile.unit_user.save') THEN public.can_manage_unit_users(p_unit)
       WHEN p_command_name='unit.config.save' THEN public.can_manage_unit_configuration(p_unit)
       WHEN p_command_name IN ('unit.cards.pause','unit.cards.disconnect') THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name='unit.order_history.delete' THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name='unit.delete' THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name IN ('unit.legal.save','unit.legal.submit') THEN public.can_manage_unit_legal_profile(p_unit)
       WHEN p_command_name IN ('unit.bank.save','unit.bank.link','unit.bank.user') THEN public.can_manage_unit_bank_accounts(p_unit)
       WHEN p_command_name='occasion.duplicate' THEN public.can_copy_occasion_target(p_unit)
       ELSE false END) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $_$;


ALTER FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text) OWNER TO postgres;

--
-- Name: block_blueprint_seats(bigint, bigint, bigint, bigint, bigint[], bigint[], bigint, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.block_blueprint_seats(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_affected_spots bigint[], p_expected_revision bigint, p_blocked boolean, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid();started jsonb;fingerprint text;bp eshop.blueprints;ids bigint[];changes jsonb;request jsonb;result jsonb;users uuid[];reason text;
BEGIN
 PERFORM public.check_blueprint_admin_scope_internal(p_occasion,p_organization,p_unit,true);
 IF p_command_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_blocked IS NULL
  OR coalesce(cardinality(p_affected_spots),0)=0 OR cardinality(p_affected_spots)>1000 OR array_position(p_affected_spots,NULL) IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='confirmed block intention required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='blueprint unavailable'; END IF;
 fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'blueprint',p_blueprint,'spots',p_spots,
  'affected',p_affected_spots,'revision',p_expected_revision,'blocked',p_blocked)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.blueprint.block',p_occasion,actor,fingerprint);
 IF started->>'disposition'='replay' THEN result:=started->'response';
 ELSE
  PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
  -- Same product/blueprint lock order as the full aggregate owner.
  PERFORM 1 FROM eshop.products WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  SELECT * INTO bp FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='blueprint unavailable'; END IF;
  BEGIN
   IF bp.layout_revision<>p_expected_revision OR bp.layout IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_REVISION_CONFLICT'; END IF;
   ids:=public.blueprint_block_selection_internal(p_occasion,p_blueprint,p_spots);
   IF ids IS DISTINCT FROM ARRAY(SELECT x FROM unnest(p_affected_spots)x ORDER BY x) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SELECTION_CHANGED'; END IF;
   PERFORM public.lock_blueprint_inventory_internal(p_occasion,p_blueprint);
   IF EXISTS(SELECT 1 FROM public.blueprint_spot_facts_internal(p_occasion,ids,clock_timestamp()) WHERE is_protected) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_PROTECTED'; END IF;
   SELECT coalesce(jsonb_agg(jsonb_build_object('operation','upsert','blocked',p_blocked,'nodeId',b.node_id,
    'spotId',b.spot,'productId',s.product,'title',s.title,'groupNodeId',b.group_node,'selectionUnitId',b.selection_unit,
    'productAssignmentMode',b.product_assignment_mode) ORDER BY b.spot),'[]') INTO changes
   FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot WHERE b.blueprint=p_blueprint AND b.spot=ANY(ids);
   request:=jsonb_build_object('id',bp.id,'occasion',bp.occasion,'organization',bp.organization,'title',bp.title,
    'expected_layout_revision',p_expected_revision,'layout',bp.layout,'textResourceIds',to_jsonb(public.blueprint_text_resource_ids_internal(bp.layout,bp.occasion)),
    'seatChanges',changes,'groupProductChanges','[]'::jsonb,'areaBindingChanges','[]'::jsonb);
   result:=public.save_blueprint_layout_internal_v1(request);
  EXCEPTION WHEN check_violation OR raise_exception OR invalid_text_representation OR not_null_violation OR unique_violation OR foreign_key_violation THEN
   GET STACKED DIAGNOSTICS reason=MESSAGE_TEXT;
   result:=public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason',reason,'layoutRevision',bp.layout_revision));
  END;
  IF result->>'status' IS NULL THEN
   SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO users FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
   result:=public.complete_private_inventory_mutation_v1(p_command_id,p_occasion,'inventory.blueprint.block',
    jsonb_build_array(jsonb_build_object('entityType','blueprint','entityId',bp.id,'operation','update','safeLabel',left(bp.title,240),'changedFields',jsonb_build_array('blocked'))),users,
    jsonb_build_object('blueprintId',bp.id,'layoutRevision',(result->>'layout_revision')::bigint,'affectedSpotIds',ids,'blocked',p_blocked));
  END IF;
 END IF;
 PERFORM public.check_blueprint_admin_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='blueprint unavailable'; END IF;
 RETURN result-'sync';
END $$;


ALTER FUNCTION public.block_blueprint_seats(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_affected_spots bigint[], p_expected_revision bigint, p_blocked boolean, p_command_id uuid) OWNER TO postgres;

--
-- Name: blueprint_admin_seat_rows_internal(bigint, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_admin_seat_rows_internal(p_occasion bigint, p_blueprint bigint, p_ids bigint[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',f.id,'nodeId',b.node_id,'title',f.title,'productId',f.product,
  'productTitle',p.title,'selectionUnitId',b.selection_unit,'groupNodeId',b.group_node,'blocked',b.blocked,
  'state',f.state,'canBlock',NOT f.is_protected) ORDER BY f.id),'[]')
 FROM eshop.blueprint_seat_bindings b JOIN public.blueprint_spot_facts_internal(p_occasion,p_ids) f ON f.id=b.spot
 LEFT JOIN eshop.products p ON p.id=f.product AND p.occasion=p_occasion WHERE b.blueprint=p_blueprint
$$;


ALTER FUNCTION public.blueprint_admin_seat_rows_internal(p_occasion bigint, p_blueprint bigint, p_ids bigint[]) OWNER TO postgres;

--
-- Name: blueprint_area_availability_internal(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_area_availability_internal(p_blueprint bigint, p_form bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('nodeId',b.node_id,'productId',b.product,'inventoryContextId',b.inventory_context)||
  CASE WHEN p_form IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.forms f WHERE f.id=p_form AND f.blueprint=b.blueprint)
  THEN jsonb_build_object('capacity',(public.blueprint_product_availability_internal(b.product)->'capacity'),'available',0,'reason','PRODUCT_NOT_IN_FORM')
  ELSE public.blueprint_product_availability_internal(b.product) END ORDER BY b.node_id),'[]')
 FROM eshop.blueprint_area_bindings b WHERE b.blueprint=p_blueprint
$$;


ALTER FUNCTION public.blueprint_area_availability_internal(p_blueprint bigint, p_form bigint) OWNER TO postgres;

--
-- Name: blueprint_binding_projection_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_binding_projection_internal(p_blueprint bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object(
 'seatBindings',coalesce((SELECT jsonb_agg(jsonb_build_object('nodeId',b.node_id,'spotId',b.spot,'productId',s.product,'title',s.title,'selectionUnitId',b.selection_unit,'groupNodeId',b.group_node,'blocked',b.blocked,'productAssignmentMode',b.product_assignment_mode) ORDER BY b.node_id)
  FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot WHERE b.blueprint=p_blueprint),'[]'),
 'groupProducts',coalesce((SELECT jsonb_agg(jsonb_build_object('groupNodeId',group_node,'productId',product) ORDER BY group_node) FROM eshop.blueprint_group_products WHERE blueprint=p_blueprint),'[]'),
 'areaBindings',coalesce((SELECT jsonb_agg(jsonb_build_object('nodeId',node_id,'inventoryContextId',inventory_context,'productId',product) ORDER BY node_id) FROM eshop.blueprint_area_bindings WHERE blueprint=p_blueprint),'[]'))
$$;


ALTER FUNCTION public.blueprint_binding_projection_internal(p_blueprint bigint) OWNER TO postgres;

--
-- Name: blueprint_block_selection_internal(bigint, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_block_selection_internal(p_occasion bigint, p_blueprint bigint, p_spots bigint[]) RETURNS bigint[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];
BEGIN
 IF coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>100 OR array_position(p_spots,NULL) IS NOT NULL
  OR (SELECT count(DISTINCT x) FROM unnest(p_spots)x)<>cardinality(p_spots) THEN RAISE invalid_parameter_value USING MESSAGE='invalid seat selection'; END IF;
 IF (SELECT count(*) FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot AND s.occasion=p_occasion
  WHERE b.blueprint=p_blueprint AND b.spot=ANY(p_spots))<>cardinality(p_spots) THEN RAISE insufficient_privilege USING MESSAGE='seat selection unavailable'; END IF;
 SELECT array_agg(DISTINCT member ORDER BY member) INTO ids FROM unnest(p_spots) selected
 CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(selected))member;
 IF cardinality(ids)>1000 THEN RAISE program_limit_exceeded USING MESSAGE='expanded selection exceeds operation limit'; END IF;
 IF (SELECT count(*) FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot AND s.occasion=p_occasion
  WHERE b.blueprint=p_blueprint AND b.spot=ANY(ids))<>cardinality(ids) THEN RAISE insufficient_privilege USING MESSAGE='expanded selection unavailable'; END IF;
 RETURN ids;
END $$;


ALTER FUNCTION public.blueprint_block_selection_internal(p_occasion bigint, p_blueprint bigint, p_spots bigint[]) OWNER TO postgres;

--
-- Name: blueprint_canonical_asset_resources_internal(jsonb, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_canonical_asset_resources_internal(p_layout jsonb, p_occasion bigint, p_unit bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_object_agg(a.asset_ref,jsonb_build_object('hash',a.hash,'url',a.url,'width',a.width,'height',a.height,'mimeType',a.mime_type,'byteLength',a.byte_length)),'{}')
 FROM public.blueprint_image_assets a WHERE (a.occasion=p_occasion OR a.unit=p_unit) AND a.organization=(SELECT organization FROM public.occasions WHERE id=p_occasion UNION ALL SELECT organization FROM public.units WHERE id=p_unit)
  AND a.state='ready' AND EXISTS(SELECT 1 FROM public.blueprint_layout_asset_refs_internal(p_layout) r WHERE r.asset_ref=a.asset_ref AND r.hash=a.hash)
$$;


ALTER FUNCTION public.blueprint_canonical_asset_resources_internal(p_layout jsonb, p_occasion bigint, p_unit bigint) OWNER TO postgres;

--
-- Name: blueprint_canonical_surface_projection_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_canonical_surface_projection_internal(p_node jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE surface jsonb:=p_node->'surface';ring jsonb;a jsonb;b jsonb;projected jsonb:='[]';rings jsonb;points jsonb;module numeric;area numeric; min_x numeric:=1e9;min_y numeric:=1e9;max_x numeric:=0;max_y numeric:=0;vertices int:=0;i int;j int;k int;other jsonb;c jsonb;d jsonb;
BEGIN
 IF jsonb_typeof(surface) IS DISTINCT FROM 'object' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SURFACE';END IF;
 IF surface->>'type' IN ('rect','circle') THEN
  IF surface-'type'<>'{}' OR (surface->>'type'='circle' AND (abs((p_node->>'width')::numeric-(p_node->>'height')::numeric)>1.0/1024 OR p_node->>'furniture'='bar')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SURFACE';END IF;
  RETURN (p_node-'surface')||jsonb_build_object('shape',surface->'type');
 END IF;
 IF surface->>'type' IS DISTINCT FROM 'grid' OR EXISTS(SELECT 1 FROM jsonb_object_keys(surface) key WHERE key NOT IN ('type','moduleSize','outer','holes')) OR jsonb_typeof(surface->'moduleSize') IS DISTINCT FROM 'number' OR jsonb_typeof(surface->'outer') IS DISTINCT FROM 'array' OR jsonb_typeof(surface->'holes') IS DISTINCT FROM 'array' OR jsonb_array_length(surface->'holes')>128 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID';END IF;
 module:=(surface->>'moduleSize')::numeric;
 IF module<=0 OR module>1000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID';END IF;
 rings:=jsonb_build_array(surface->'outer')||(surface->'holes');
 FOR k IN 0..jsonb_array_length(rings)-1 LOOP
  ring:=rings->k;area:=0;points:='[]';
  IF jsonb_typeof(ring)<>'array' OR jsonb_array_length(ring)<4 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID_RING';END IF;
  PERFORM public.validate_blueprint_polygon_internal(ring,true);
  vertices:=vertices+jsonb_array_length(ring);
  FOR i IN 0..jsonb_array_length(ring)-1 LOOP
   a:=ring->i;b:=ring->((i+1)%jsonb_array_length(ring));
   IF (a->>0)::numeric<>trunc((a->>0)::numeric) OR (a->>1)::numeric<>trunc((a->>1)::numeric) OR abs((a->>0)::numeric)>16384 OR abs((a->>1)::numeric)>16384 OR ((a->0=b->0)=(a->1=b->1)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_NON_ORTHOGONAL_GRID';END IF;
   area:=area+(a->>0)::numeric*(b->>1)::numeric-(b->>0)::numeric*(a->>1)::numeric;
   IF k=0 THEN min_x:=least(min_x,(a->>0)::numeric);min_y:=least(min_y,(a->>1)::numeric);max_x:=greatest(max_x,(a->>0)::numeric);max_y:=greatest(max_y,(a->>1)::numeric);END IF;
   points:=points||jsonb_build_array(jsonb_build_array((a->>0)::numeric*module-(p_node->>'width')::numeric/2,(a->>1)::numeric*module-(p_node->>'height')::numeric/2));
  END LOOP;
  IF (k=0 AND area<=0) OR (k>0 AND area>=0) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_WINDING';END IF;
  IF k>0 AND NOT public.blueprint_grid_contains_internal(rings->0,(ring#>>'{0,0}')::numeric,(ring#>>'{0,1}')::numeric) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_HOLE_OUTSIDE';END IF;
  FOR j IN 0..k-1 LOOP
   other:=rings->j;
   IF j>0 AND (public.blueprint_grid_contains_internal(other,(ring#>>'{0,0}')::numeric,(ring#>>'{0,1}')::numeric) OR public.blueprint_grid_contains_internal(ring,(other#>>'{0,0}')::numeric,(other#>>'{0,1}')::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_HOLES_OVERLAP';END IF;
   FOR i IN 0..jsonb_array_length(ring)-1 LOOP
    a:=ring->i;b:=ring->((i+1)%jsonb_array_length(ring));
    FOR c,d IN SELECT value,other->((ordinality::int)%jsonb_array_length(other)) FROM jsonb_array_elements(other) WITH ORDINALITY LOOP
     IF greatest(least((a->>0)::numeric,(b->>0)::numeric),least((c->>0)::numeric,(d->>0)::numeric))<=least(greatest((a->>0)::numeric,(b->>0)::numeric),greatest((c->>0)::numeric,(d->>0)::numeric)) AND greatest(least((a->>1)::numeric,(b->>1)::numeric),least((c->>1)::numeric,(d->>1)::numeric))<=least(greatest((a->>1)::numeric,(b->>1)::numeric),greatest((c->>1)::numeric,(d->>1)::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_RINGS_TOUCH';END IF;
    END LOOP;
   END LOOP;
  END LOOP;
  projected:=projected||jsonb_build_array(points);
 END LOOP;
 IF vertices>512 OR min_x<>0 OR min_y<>0 OR max_x*max_y>16384 OR abs((p_node->>'width')::numeric-max_x*module)>1.0/1024 OR abs((p_node->>'height')::numeric-max_y*module)>1.0/1024 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_DIMENSIONS';END IF;
 RETURN (p_node-'surface')||jsonb_build_object('shape','polygon','points',projected->0,'holes',projected-0);
END $$;


ALTER FUNCTION public.blueprint_canonical_surface_projection_internal(p_node jsonb) OWNER TO postgres;

--
-- Name: blueprint_canonical_text_resources_internal(jsonb, bigint, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_canonical_text_resources_internal(p_layout jsonb, p_occasion bigint, p_setup_draft uuid DEFAULT NULL::uuid, p_presets boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH requests AS (SELECT * FROM public.blueprint_layout_text_requests_internal(p_layout,p_presets)),
 prepared AS (SELECT DISTINCT r.resource_id,r.resource_kind,r.payload FROM public.blueprint_text_resources r JOIN requests q
  ON r.scope_key=CASE WHEN p_occasion IS NOT NULL THEN 'occasion:'||p_occasion::text ELSE 'setup:'||p_setup_draft::text END
   AND r.payload->'descriptor' @> q.descriptor AND r.payload->'descriptor'=q.descriptor)
 SELECT jsonb_build_object('protocol',2,
  'fontFamilies',coalesce((SELECT jsonb_object_agg(f.id,f.manifest) FROM public.ticket_font_families f WHERE f.id IN (SELECT font_family_id FROM requests UNION SELECT font_family_id FROM public.blueprint_declared_font_families_internal(p_layout,p_presets))),'{}'),
  'textLayouts',coalesce((SELECT jsonb_object_agg(resource_id,payload) FROM prepared WHERE resource_kind='text'),'{}'),
  'numberSymbols',coalesce((SELECT jsonb_object_agg(payload->>'fontFaceId',payload) FROM prepared WHERE resource_kind='number'),'{}'))
$$;


ALTER FUNCTION public.blueprint_canonical_text_resources_internal(p_layout jsonb, p_occasion bigint, p_setup_draft uuid, p_presets boolean) OWNER TO postgres;

