ALTER FUNCTION public.blueprint_contract_metadata_internal() OWNER TO postgres;

--
-- Name: blueprint_declared_font_families_internal(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_declared_font_families_internal(p_layout jsonb, p_presets boolean DEFAULT false) RETURNS TABLE(font_family_id text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH RECURSIVE documents(doc) AS (
  SELECT p_layout UNION ALL
  SELECT preset->'document' FROM documents CROSS JOIN LATERAL jsonb_array_elements(coalesce(doc->'presets','[]')) preset WHERE p_presets
 ), styles(style) AS (
  SELECT doc->'styles' FROM documents
  UNION ALL SELECT kind_style.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(doc#>'{styles,kinds}','{}')) kind_style
  UNION ALL SELECT node->'style' FROM documents CROSS JOIN LATERAL jsonb_array_elements(doc->'nodes') node
  UNION ALL SELECT child_style.value FROM documents CROSS JOIN LATERAL jsonb_array_elements(doc->'nodes') node
   CROSS JOIN LATERAL jsonb_each(coalesce(node->'childStyles','{}')) child_style
 ) SELECT DISTINCT style#>>'{label,fontFamilyId}' FROM styles WHERE style#>>'{label,fontFamilyId}' IS NOT NULL
$$;


ALTER FUNCTION public.blueprint_declared_font_families_internal(p_layout jsonb, p_presets boolean) OWNER TO postgres;

--
-- Name: blueprint_form_product_catalog_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_form_product_catalog_internal(p_form bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'type_title',pt.title,'price',p.price,
  'currency_code',p.currency_code,'maximum',p.maximum,
  'ordered_count',(SELECT count(*) FROM eshop.order_product_ticket opt WHERE opt.product=p.id),
  'is_dynamically_available',public.is_product_dynamically_available(p.id),
  'isAvailable',(availability.value->>'available')::bigint>0 AND public.is_product_dynamically_available(p.id)
 ) ORDER BY p.id),'[]'::jsonb)
 FROM public.blueprint_form_products_internal(p_form) offered JOIN eshop.products p ON p.id=offered.product
 LEFT JOIN eshop.product_types pt ON pt.id=p.product_type
 CROSS JOIN LATERAL (SELECT public.blueprint_product_availability_internal(p.id) AS value) availability
 WHERE NOT p.is_hidden
$$;


ALTER FUNCTION public.blueprint_form_product_catalog_internal(p_form bigint) OWNER TO postgres;

--
-- Name: blueprint_form_products_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_form_products_internal(p_form bigint) RETURNS TABLE(product bigint, has_seats boolean, has_capacity boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT offered.product,bool_or(offered.has_seats),bool_or(offered.has_capacity)
 FROM public.forms f JOIN eshop.blueprints b ON b.id=f.blueprint AND b.occasion=f.occasion
 CROSS JOIN LATERAL (
  SELECT s.product,true AS has_seats,false AS has_capacity
  FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots s ON s.id=sb.spot
  WHERE sb.blueprint=b.id AND s.blueprint=b.id AND s.occasion=f.occasion
  UNION ALL
  SELECT ab.product,false,true FROM eshop.blueprint_area_bindings ab WHERE ab.blueprint=b.id
 ) offered
 JOIN eshop.products p ON p.id=offered.product AND p.occasion=f.occasion
 WHERE f.id=p_form GROUP BY offered.product
$$;


ALTER FUNCTION public.blueprint_form_products_internal(p_form bigint) OWNER TO postgres;

--
-- Name: blueprint_grid_cell_filled_internal(jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_grid_cell_filled_internal(p_surface jsonb, p_x numeric, p_y numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(p_surface->>'type'='grid'
  AND public.blueprint_grid_contains_internal(p_surface->'outer',p_x+0.5,p_y+0.5)
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_surface->'holes') hole WHERE public.blueprint_grid_contains_internal(hole,p_x+0.5,p_y+0.5)),false)
$$;


ALTER FUNCTION public.blueprint_grid_cell_filled_internal(p_surface jsonb, p_x numeric, p_y numeric) OWNER TO postgres;

--
-- Name: blueprint_grid_contains_internal(jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_grid_contains_internal(p_ring jsonb, p_x numeric, p_y numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a jsonb;b jsonb; crossings int:=0;i int;size int:=jsonb_array_length(p_ring);
BEGIN
 FOR i IN 0..size-1 LOOP
  a:=p_ring->i;b:=p_ring->((i+1)%size);
  IF p_x BETWEEN least((a->>0)::numeric,(b->>0)::numeric) AND greatest((a->>0)::numeric,(b->>0)::numeric)
   AND p_y BETWEEN least((a->>1)::numeric,(b->>1)::numeric) AND greatest((a->>1)::numeric,(b->>1)::numeric) THEN RETURN false;END IF;
  IF ((a->>1)::numeric>p_y)<>((b->>1)::numeric>p_y) AND p_x<(a->>0)::numeric THEN crossings:=crossings+1;END IF;
 END LOOP;
 RETURN crossings%2=1;
END $$;


ALTER FUNCTION public.blueprint_grid_contains_internal(p_ring jsonb, p_x numeric, p_y numeric) OWNER TO postgres;

--
-- Name: blueprint_hold_admission_internal(bigint, bigint[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_hold_admission_internal(p_form bigint, p_spots bigint[], p_secret uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE item record; counts jsonb; requested bigint; occupied bigint; physical bigint; cap bigint;
BEGIN
 PERFORM public.lock_blueprint_hold_scope_internal(p_spots);
 FOR item IN SELECT p.*,count(*) AS requested FROM eshop.spots s JOIN eshop.products p ON p.id=s.product
  WHERE s.id=ANY(p_spots) AND NOT coalesce(s.secret=p_secret AND s.secret_expiration_time>clock_timestamp(),false)
  GROUP BY p.id ORDER BY p.id LOOP
  IF item.is_hidden THEN RETURN jsonb_build_object('code',409,'reason','PRODUCT_HIDDEN'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.blueprint_form_products_internal(p_form) offered WHERE offered.product=item.id AND offered.has_seats) THEN
   RETURN jsonb_build_object('code',409,'reason','PRODUCT_NOT_IN_FORM'); END IF;
  IF coalesce(item.maximum,0)>0 THEN
   SELECT count(*) INTO occupied FROM eshop.order_product_ticket WHERE product=item.id;
   SELECT occupied+count(*) INTO occupied FROM eshop.spots WHERE product=item.id AND order_product_ticket IS NULL
    AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp();
   IF occupied+item.requested>item.maximum THEN RETURN jsonb_build_object('code',409,'reason','PRODUCT_CAPACITY_EXCEEDED'); END IF;
  END IF;
  counts:=public.blueprint_product_availability_internal(item.id);
  IF (counts->>'available')::bigint<item.requested THEN RETURN jsonb_build_object('code',409,'reason',coalesce(counts->>'reason','PRODUCT_CAPACITY_EXCEEDED')); END IF;
 END LOOP;
 -- Two differently priced products can consume the same context. Sum their
 -- quantities before holding either member, rather than checking them alone.
 FOR item IN SELECT pic.inventory_context,ip.sellable_capacity,sum(pic.quantity)::bigint AS requested
  FROM eshop.spots s JOIN eshop.product_inventory_contexts pic ON pic.product=s.product
  JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
  WHERE s.id=ANY(p_spots) AND NOT coalesce(s.secret=p_secret AND s.secret_expiration_time>clock_timestamp(),false)
  GROUP BY pic.inventory_context,ip.sellable_capacity ORDER BY pic.inventory_context LOOP
  SELECT count(*),count(*) FILTER(WHERE order_product_ticket IS NOT NULL OR
   (secret IS NOT NULL AND secret_expiration_time>clock_timestamp())) INTO physical,occupied
   FROM eshop.spots WHERE inventory_context=item.inventory_context;
  -- Addressed seats usually have no inventory_context. Their existing spot
  -- holds nevertheless promise all PIC quantities at checkout. Count that
  -- same hold record, subtracting any physical occupancy already counted.
  SELECT occupied+coalesce(sum(greatest(pic.quantity-CASE
    WHEN held.inventory_context=item.inventory_context THEN 1 ELSE 0 END,0)),0)
   INTO occupied FROM eshop.spots held JOIN eshop.product_inventory_contexts pic ON pic.product=held.product
   WHERE pic.inventory_context=item.inventory_context AND held.blueprint IS NOT NULL
    AND held.order_product_ticket IS NULL AND held.secret IS NOT NULL
    AND held.secret_expiration_time>clock_timestamp();
  cap:=least(physical,coalesce(item.sellable_capacity,physical));
  IF occupied+item.requested>cap THEN RETURN jsonb_build_object('code',409,'reason','PRODUCT_CAPACITY_EXCEEDED'); END IF;
 END LOOP;
 RETURN jsonb_build_object('code',200);
END $$;


ALTER FUNCTION public.blueprint_hold_admission_internal(p_form bigint, p_spots bigint[], p_secret uuid) OWNER TO postgres;

--
-- Name: blueprint_hold_selection_internal(bigint, bigint, bigint[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_hold_selection_internal(p_occasion bigint, p_blueprint bigint, p_spots bigint[], p_max integer) RETURNS bigint[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];
BEGIN
 IF coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>256 OR array_position(p_spots,NULL) IS NOT NULL
  OR (SELECT count(DISTINCT x) FROM unnest(p_spots)x)<>cardinality(p_spots) THEN RAISE invalid_parameter_value USING MESSAGE='invalid hold selection'; END IF;
 IF (SELECT count(*) FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot AND s.occasion=p_occasion
  WHERE b.blueprint=p_blueprint AND b.spot=ANY(p_spots))<>cardinality(p_spots) THEN RAISE insufficient_privilege USING MESSAGE='hold selection unavailable'; END IF;
 SELECT array_agg(DISTINCT member ORDER BY member) INTO ids FROM unnest(p_spots) selected
 CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(selected))member;
 IF cardinality(ids)>p_max THEN RAISE program_limit_exceeded USING MESSAGE='expanded hold selection exceeds operation limit'; END IF;
 IF (SELECT count(*) FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot AND s.occasion=p_occasion
  WHERE b.blueprint=p_blueprint AND b.spot=ANY(ids))<>cardinality(ids) THEN RAISE insufficient_privilege USING MESSAGE='expanded hold selection unavailable'; END IF;
 RETURN ids;
END $$;


ALTER FUNCTION public.blueprint_hold_selection_internal(p_occasion bigint, p_blueprint bigint, p_spots bigint[], p_max integer) OWNER TO postgres;

--
-- Name: blueprint_hold_snapshot_internal(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_hold_snapshot_internal(p_occasion bigint, p_ids bigint[]) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT encode(extensions.digest(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'blueprint',blueprint,'secret',secret,
  'expires',extract(epoch FROM secret_expiration_time),'orderItem',order_product_ticket) ORDER BY id),'[]')::text,'UTF8'),'sha256'),'hex')
 FROM eshop.spots WHERE occasion=p_occasion AND id=ANY(p_ids)
$$;


ALTER FUNCTION public.blueprint_hold_snapshot_internal(p_occasion bigint, p_ids bigint[]) OWNER TO postgres;

--
-- Name: blueprint_layout_asset_refs_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_layout_asset_refs_internal(p_layout jsonb) RETURNS TABLE(asset_ref text, hash text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH RECURSIVE documents(doc) AS (SELECT p_layout UNION ALL SELECT preset->'document' FROM documents CROSS JOIN LATERAL jsonb_array_elements(coalesce(doc->'presets','[]')) preset)
 SELECT doc#>>'{background,assetRef}',doc#>>'{background,hash}' FROM documents WHERE doc#>>'{background,assetRef}' IS NOT NULL
 UNION SELECT node#>>'{graphic,assetRef}',node#>>'{graphic,hash}' FROM documents CROSS JOIN LATERAL jsonb_array_elements(coalesce(doc->'nodes','[]')) node WHERE node->>'kind'='image'
$$;


ALTER FUNCTION public.blueprint_layout_asset_refs_internal(p_layout jsonb) OWNER TO postgres;

--
-- Name: blueprint_layout_resources_internal(jsonb, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_layout_resources_internal(p_layout jsonb, p_occasion bigint, p_unit bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF p_layout->>'schemaVersion' IS DISTINCT FROM '2' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_MIGRATION_REQUIRED';END IF;
 RETURN public.blueprint_canonical_text_resources_internal(p_layout,p_occasion,NULL,true)||jsonb_build_object('assets',public.blueprint_canonical_asset_resources_internal(p_layout,p_occasion,p_unit));
END $$;


