--
-- Name: blueprint_layout_text_requests_internal(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_layout_text_requests_internal(p_layout jsonb, p_presets boolean DEFAULT false) RETURNS TABLE(node_key text, font_family_id text, font_face_id text, role text, descriptor jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH RECURSIVE documents(doc,prefix) AS (
  SELECT p_layout,''::text UNION ALL
  SELECT preset->'document',prefix||(preset->>'id')||'/' FROM documents
   CROSS JOIN LATERAL jsonb_array_elements(coalesce(doc->'presets','[]')) preset WHERE p_presets
 ), roles AS (
  SELECT doc,prefix||(node->>'id') AS node_key,node,
   public.blueprint_resolved_label_internal(doc,node) AS label,
   CASE WHEN node->>'kind'='text' THEN 'text' ELSE 'label' END AS role,
   CASE WHEN node->>'kind'='text' THEN coalesce(node->>'text','') ELSE coalesce(node->>'label','') END AS source
  FROM documents CROSS JOIN LATERAL jsonb_array_elements(doc->'nodes') node
  WHERE node->>'kind' NOT IN ('group','seat','vector','image')
   AND (node->>'kind'<>'furniture' OR node->>'furniture' IS DISTINCT FROM 'couch')
   AND (node->>'kind'<>'table' OR node->>'furniture' IS DISTINCT FROM 'bar')
  UNION ALL
  SELECT doc,prefix||(node->>'id')||':number',node,
   (public.blueprint_contract_metadata_internal()->'labelDefaults')||(doc->'textPolicy')||coalesce(doc#>'{styles,label}','{}'),
   'number','' FROM documents CROSS JOIN LATERAL jsonb_array_elements(doc->'nodes') node
  WHERE node->>'kind'='capacityArea' OR (node->>'kind'='furniture' AND node->>'furniture' IS DISTINCT FROM 'couch' AND EXISTS(
   SELECT 1 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) unit WHERE jsonb_array_length(unit->'nodeIds')>1
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(unit->'nodeIds') member
     WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(doc->'nodes') child WHERE child->>'id'=member AND child->>'parentId'=node->>'id'))))
 ), requests AS (
  SELECT roles.*,f.manifest->'faces'->>((label->>'weight')||':'||CASE WHEN label->>'italic'='true' THEN 'italic' ELSE 'normal' END) AS face_id
   FROM roles LEFT JOIN public.ticket_font_families f ON f.id=label->>'fontFamilyId'
 )
 SELECT node_key,label->>'fontFamilyId',face_id,role,
  CASE WHEN role='number' THEN jsonb_build_object('layoutResourceProtocol',2,'policy',public.blueprint_contract_metadata_internal()->'textPolicy','role','number','fontFaceId',face_id)
  ELSE jsonb_build_object('layoutResourceProtocol',2,'policy',public.blueprint_contract_metadata_internal()->'textPolicy',
   'request',jsonb_build_object('text',source,'role',role,'fontFamilyId',label->>'fontFamilyId','fontFaceId',face_id,
    'size',label->'size','language',label->'language','direction',label->'direction','lineHeight',label->'lineHeight','align',label->'align',
    'box',jsonb_build_object('x',-(node->>'width')::numeric/2,'y',-(node->>'height')::numeric/2,'width',node->'width','height',node->'height'),
    'fit',CASE WHEN role='text' THEN 'wrap' ELSE 'shrink' END)) END
 FROM requests WHERE role='number' OR source<>''
$$;


ALTER FUNCTION public.blueprint_layout_text_requests_internal(p_layout jsonb, p_presets boolean) OWNER TO postgres;

--
-- Name: blueprint_order_affected_spots_internal(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_order_affected_spots_internal(p_spots bigint[]) RETURNS bigint[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT ARRAY(SELECT id FROM (
  SELECT unnest(p_spots) id UNION SELECT s.id FROM eshop.spots s
  JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
  WHERE i.ticket IN(SELECT selected.ticket FROM eshop.spots target
   JOIN eshop.order_product_ticket selected ON selected.id=target.order_product_ticket WHERE target.id=ANY(p_spots))) affected ORDER BY id)
$$;


ALTER FUNCTION public.blueprint_order_affected_spots_internal(p_spots bigint[]) OWNER TO postgres;

--
-- Name: blueprint_order_conflicts_internal(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_order_conflicts_internal(p_analysis jsonb, p_effects jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH tickets AS MATERIALIZED(SELECT c FROM jsonb_array_elements(coalesce(p_analysis->'conflicts','[]')) c),
 grouped AS(SELECT (c->>'order_id')::bigint id,min(c->>'email') email,min(c->>'name') name,min(c->>'surname') surname,
  count(DISTINCT c->>'ticket_id') selected_count,
  jsonb_agg(jsonb_build_object('ticketId',c->'ticket_id','selectedSpotIds',c->'selected_spot_ids',
   'ticketSymbol',c->'ticket_symbol','ticketAmount',c->>'total_price','products',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('productId',p->'id','title',p->'title',
     'amount',p->>'price','currencyCode',upper(btrim(p->>'currency_code')))),'[]')
     FROM jsonb_array_elements(CASE WHEN jsonb_typeof(c->'products')='array' THEN c->'products' ELSE '[]'::jsonb END) p))
   ORDER BY (c->>'ticket_id')::bigint) rows
 FROM tickets GROUP BY (c->>'order_id')::bigint),
 money AS MATERIALIZED(SELECT (e->>'orderId')::bigint id,e->>'afterState' state FROM jsonb_array_elements(coalesce(p_effects,'[]')) e)
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',g.id,'selectedTicketCount',g.selected_count,
  'stateAfter',m.state,'customer',jsonb_build_object('email',g.email,'name',g.name,'surname',g.surname),
  'tickets',g.rows) ORDER BY g.id),'[]') FROM grouped g LEFT JOIN money m ON m.id=g.id
$$;


ALTER FUNCTION public.blueprint_order_conflicts_internal(p_analysis jsonb, p_effects jsonb) OWNER TO postgres;

--
-- Name: blueprint_order_input_internal(bigint[], jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_order_input_internal(p_spots bigint[], p_input jsonb, p_analysis jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE form_key uuid; tickets jsonb;
BEGIN
 IF coalesce(p_input->>'email','')='' THEN RAISE EXCEPTION 'Email is required in input data.'; END IF;
 form_key:=(p_analysis#>>'{order_form,key}')::uuid;
 IF p_input->>'form_key' IS NOT NULL AND p_input->>'form_key' IS DISTINCT FROM form_key::text THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_ORDER_FORM_CHANGED',
   DETAIL='{"code":409,"reason":"BLUEPRINT_ORDER_FORM_CHANGED"}'; END IF;
 IF form_key IS NULL OR NOT EXISTS(SELECT 1 FROM public.forms f WHERE f.key=form_key
  AND f.blueprint=(SELECT blueprint FROM eshop.spots WHERE id=p_spots[1]))
  OR EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spots) AND blueprint IS DISTINCT FROM
   (SELECT blueprint FROM eshop.spots WHERE id=p_spots[1])) THEN
  RAISE EXCEPTION 'No open form found for this occasion to create the new order.'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('spot',s.id,'fields',
  coalesce(p_input->'ticket_fields'->s.id::text,'[]'::jsonb)) ORDER BY s.id),'[]')
 INTO tickets FROM eshop.spots s WHERE s.id=ANY(p_spots);
 RETURN jsonb_build_object('form',form_key,'ticket',tickets,'lang','cs')
  ||(p_input-'ticket_fields'-'form_key'-'form'-'ticket');
END $$;


ALTER FUNCTION public.blueprint_order_input_internal(p_spots bigint[], p_input jsonb, p_analysis jsonb) OWNER TO postgres;

--
-- Name: blueprint_order_rejection_internal(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_order_rejection_internal(p_message text, p_detail text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE failure jsonb:='{}';reason text;result jsonb;
BEGIN
 BEGIN
  IF left(p_detail,1)='{' THEN failure:=p_detail::jsonb;
  ELSIF left(p_message,1)='{' THEN failure:=p_message::jsonb; END IF;
 EXCEPTION WHEN invalid_text_representation THEN failure:='{}';
 END;
 reason:=coalesce(failure->>'errorCode',failure->>'message',p_message);
 IF reason IS NULL OR NOT reason=ANY(ARRAY['REQUIRED_FIELD_MISSING','PRODUCT_CAPACITY_EXCEEDED','FORM_CAPACITY_EXCEEDED',
  'PRODUCT_SCOPE_MISMATCH','FORM_FIELD_SCOPE_MISMATCH','FORM_FIELD_TYPE_MISMATCH','FORM_FIELD_AMBIGUOUS','FORM_FIELD_VALUE_CONFLICT',
  'BATCH_TICKET_PRINT_IMMUTABLE','BLUEPRINT_ORDER_MONEY_UNAVAILABLE','BLUEPRINT_SEAT_PROTECTED','BLUEPRINT_SELECTION_UNIT_USED',
  'BLUEPRINT_INCOMPLETE_SELECTION_UNIT','STRIPE_REPLACEMENT_UNSUPPORTED','BLUEPRINT_CURRENCY_MISMATCH',
  'BLUEPRINT_ORDER_FORM_CHANGED']) THEN
  reason:='BLUEPRINT_ORDER_INPUT_OR_STATE_REJECTED'; END IF;
 result:=jsonb_build_object('code',409,'reason',reason);
 IF reason='REQUIRED_FIELD_MISSING' AND coalesce(failure->>'fieldId','')~'^[1-9][0-9]{0,14}$' THEN
  result:=result||jsonb_build_object('fieldId',(failure->>'fieldId')::bigint); END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.blueprint_order_rejection_internal(p_message text, p_detail text) OWNER TO postgres;

--
-- Name: blueprint_product_availability_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_product_availability_internal(p_product bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE p eshop.products; c record; total bigint; occupied bigint; cap bigint; available bigint:=2147483647; capacity bigint:=2147483647;
BEGIN
 SELECT * INTO p FROM eshop.products WHERE id=p_product;
 IF NOT FOUND THEN RETURN jsonb_build_object('capacity',0,'available',0,'reason','PRODUCT_NOT_FOUND'); END IF;
 IF coalesce(p.maximum,0)>0 THEN
  capacity:=p.maximum;
  available:=greatest(0,p.maximum-(SELECT count(*) FROM eshop.order_product_ticket WHERE product=p.id));
 END IF;
 FOR c IN SELECT pic.inventory_context,pic.quantity,ip.sellable_capacity FROM eshop.product_inventory_contexts pic
  JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool WHERE pic.product=p.id LOOP
  SELECT count(*),count(*) FILTER(WHERE order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>statement_timestamp()))
   INTO total,occupied FROM eshop.spots WHERE inventory_context=c.inventory_context;
  cap:=least(total,coalesce(c.sellable_capacity,total));
  capacity:=least(capacity,cap/greatest(c.quantity,1));
  available:=least(available,greatest(0,cap-occupied)/greatest(c.quantity,1));
 END LOOP;
 RETURN jsonb_build_object('capacity',capacity,'available',CASE WHEN p.is_hidden THEN 0 ELSE available END,
  'reason',CASE WHEN p.is_hidden THEN 'PRODUCT_HIDDEN' WHEN available=0 THEN 'PRODUCT_CAPACITY_EXCEEDED' ELSE NULL END);
END $$;


ALTER FUNCTION public.blueprint_product_availability_internal(p_product bigint) OWNER TO postgres;

--
-- Name: blueprint_public_binding_projection_internal(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.blueprint_public_binding_projection_internal(p_blueprint bigint, p_secret uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.blueprint_binding_projection_internal(p_blueprint)||jsonb_build_object('seatBindings',coalesce(
 (SELECT jsonb_agg(jsonb_build_object('nodeId',b.node_id,'spotId',b.spot,'productId',s.product,'title',s.title,'selectionUnitId',b.selection_unit,'groupNodeId',b.group_node,'blocked',b.blocked,'productAssignmentMode',b.product_assignment_mode,'status',CASE
 WHEN b.blocked OR s.product IS NULL THEN 'unavailable' WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
 WHEN s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp() THEN CASE WHEN s.secret=p_secret THEN 'selected_by_me' ELSE 'selected' END
 ELSE 'available' END) ORDER BY b.node_id) FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot WHERE b.blueprint=p_blueprint),'[]'))
$$;


