--
-- Name: cancel_blueprint_tickets(bigint, bigint, bigint, bigint, bigint[], bigint[], text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_blueprint_tickets(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_tickets bigint[], p_confirmation_hash text, p_command_id uuid, p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 IF p_editor IS NULL OR p_confirmation_hash IS NULL OR p_confirmation_hash!~'^[a-f0-9]{64}$'
 OR coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>1000 OR coalesce(cardinality(p_tickets),0)=0 OR cardinality(p_tickets)>1000 THEN
 RAISE invalid_parameter_value USING MESSAGE='confirmed ticket cancellation required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion)
 OR (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion AND blueprint=p_blueprint)<>cardinality(p_spots)
 OR (SELECT count(*) FROM eshop.tickets WHERE id=ANY(p_tickets) AND occasion=p_occasion)<>cardinality(p_tickets) THEN RAISE insufficient_privilege; END IF;
 result:=public.cancel_tickets_command_internal(p_tickets,p_command_id,jsonb_build_object('occasion',p_occasion,'blueprint',p_blueprint,'spots',p_spots,'hash',p_confirmation_hash));
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT p_editor THEN result:=result-'sync'; END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.cancel_blueprint_tickets(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_tickets bigint[], p_confirmation_hash text, p_command_id uuid, p_editor boolean) OWNER TO postgres;

--
-- Name: cancel_order_domain_internal_v1(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_order_domain_internal_v1(order_id bigint, p_notify boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    ticket_ids BIGINT[];
    updated_order_data jsonb;
    v_order eshop.orders;
    v_occasion public.occasions;
    v_notice jsonb;
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=order_id)]);
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    SELECT * INTO v_order FROM eshop.orders WHERE id=order_id FOR UPDATE;
    IF v_order.id IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
    IF v_order.state='storno' THEN RETURN; END IF;
    PERFORM public.check_order_is_mutable(order_id);
    -- Card finances and admission are resolved by provider facts and the
    -- audited refund decision, never by resetting an order's original price.
    IF EXISTS(SELECT 1 FROM eshop.payment_info pi
      WHERE pi.id=v_order.payment_info AND public.payment_method_is_online_internal(pi.payment_method)) THEN
        RAISE EXCEPTION 'STRIPE_USE_REFUND_ADMISSION_DECISION';
    END IF;
    PERFORM public.cancel_order_email_intents(order_id);
    -- Retrieve all ticket ids associated with the order
    SELECT ARRAY_AGG(t.id) INTO ticket_ids
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    WHERE opt."order" = order_id;

    -- Check if the order exists and has associated tickets
    IF ticket_ids IS NULL THEN
        -- This is not an error, just an order with no tickets yet.
        -- But we can still storno the order itself.
        RAISE NOTICE 'No tickets found for order %, proceeding to storno order shell.', order_id;
    END IF;

    -- Call the helper to storno all tickets and their relations
    -- The helper function gracefully handles an empty/NULL array
    PERFORM internal_storno_tickets_221(ticket_ids);

    -- Set the order state to 'storno', price to 0, and update the data field
    UPDATE eshop.orders
    SET state = 'storno',
        price = 0,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object('tickets', '[]'::jsonb),
        updated_at = NOW()
    WHERE id = order_id
    RETURNING data INTO updated_order_data;
    PERFORM public.notification_center_order_state_internal(order_id);

    -- Finish the original email recovery task in the same cancellation transaction.
    -- Keep provider messages and delivery history intact.
    UPDATE public.notification_center_events e SET status='recovered'
    FROM public.email_messages m
    WHERE m.order_id=v_order.id AND m.occasion=v_order.occasion
      AND m.message_kind<>'order_storno' AND e.organization=m.organization
      AND e.kind='email_problem' AND e.source_key='email:'||m.message_id;


    -- Save the change to orders_history by inserting the updated order row
    INSERT INTO eshop.orders_history (
        "order",
        state,
        price,
        data,
        created_at
    )
    VALUES (
        order_id,
        'storno',
        0,
        updated_order_data,
        NOW()
    );

    -- The full transition owns the durable automatic commitment for every caller.
    SELECT * INTO v_occasion FROM public.occasions WHERE id=v_order.occasion;
    IF p_notify AND position('@' in v_order.data->>'email')>0
      AND length(v_order.data->>'email')<=320 THEN
      v_notice:=public.enqueue_order_email('TICKET_ORDER_STORNO',
        jsonb_build_object('order_id',order_id),v_occasion.organization,
        v_occasion.id,v_occasion.unit);
    END IF;
END;
$$;


ALTER FUNCTION public.cancel_order_domain_internal_v1(order_id bigint, p_notify boolean) OWNER TO postgres;

--
-- Name: cancel_order_email_intents(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_order_email_intents(p_order bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 UPDATE public.email_messages SET workflow_state='cancelled',last_error='payment_changed',lease_token=NULL,lease_until=NULL
 WHERE order_id=p_order AND message_kind IN ('order_payment_notice','order_tickets','order_reminder') AND workflow_state IN ('pending','retry_wait','blocked','preparing');
END $$;


