--
-- Name: cancel_product_price_change(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_product_price_change(p_product_id bigint, p_change_id bigint, p_expected_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_occasion bigint; v_change eshop.planned_changes%ROWTYPE;
BEGIN
  SELECT pt.occasion INTO STRICT v_occasion FROM eshop.products p JOIN eshop.product_types pt
    ON pt.id=p.product_type WHERE p.id=p_product_id FOR UPDATE OF p;
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.occasions o JOIN public.user_info ui
    ON ui.organization=o.organization WHERE o.id=v_occasion AND ui.id=auth.uid()) THEN
    RAISE insufficient_privilege USING MESSAGE='ORDER_EDITOR_REQUIRED'; END IF;
  PERFORM public.check_is_editor_order_on_occasion(v_occasion);
  SELECT * INTO v_change FROM eshop.planned_changes WHERE id=p_change_id FOR UPDATE;
  IF NOT FOUND OR v_change.subject_id<>p_product_id OR v_change.change_type<>'products.price'
    OR v_change.applied OR v_change.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  DELETE FROM eshop.planned_changes WHERE id=p_change_id;
END; $$;


ALTER FUNCTION public.cancel_product_price_change(p_product_id bigint, p_change_id bigint, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: cancel_product_price_wave(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_product_price_wave(p_wave_id bigint, p_expected_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  PERFORM 1 FROM eshop.products WHERE id IN(SELECT subject_id FROM eshop.planned_changes
    WHERE wave_id=p_wave_id AND NOT applied) ORDER BY id FOR UPDATE;
  DELETE FROM eshop.planned_changes WHERE wave_id=p_wave_id AND NOT applied;
  DELETE FROM eshop.product_price_waves WHERE id=p_wave_id;
END; $$;


ALTER FUNCTION public.cancel_product_price_wave(p_wave_id bigint, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: cancel_reception_registration_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_reception_registration_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_r public.reception_registrations%rowtype; v_actor uuid:=auth.uid(); v_impacts jsonb;
BEGIN
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  SELECT * INTO v_r FROM public.reception_registrations WHERE occasion=p_occasion AND "user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','registration_unavailable'); END IF;
  IF NOT public.get_can_use_reception(p_occasion) OR NOT (public.can_manage_occasion_participants(p_occasion) OR (v_r.created_by=v_actor AND (v_r.status='cancelled' OR v_r.created_at>now()-interval '30 minutes'))) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  IF v_r.status='cancelled' THEN RETURN jsonb_build_object('code',200,'status',CASE WHEN v_r.auth_revoked_at IS NULL THEN 'domain_blocked_auth_revocation_pending' ELSE 'cancelled' END,'targetUser',p_user); END IF;
  IF NOT public.reception_rate_limit_v1('cancel') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  UPDATE public.reception_registrations SET status='cancelled',cancelled_by=v_actor,cancelled_at=now() WHERE occasion=p_occasion AND "user"=p_user;
  v_impacts:=public.remove_occasion_user_domain_internal_v1(p_occasion,p_user);
  INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision)
  SELECT x->>'component',p_occasion,(x->>'userId')::uuid,1 FROM jsonb_array_elements(v_impacts) x ORDER BY x->>'component',x->>'userId'
  ON CONFLICT(component,occasion,user_id) DO UPDATE SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp();
  RETURN jsonb_build_object('code',200,'status','domain_blocked_auth_revocation_pending','targetUser',p_user);
END $$;


ALTER FUNCTION public.cancel_reception_registration_v1(p_occasion bigint, p_user uuid) OWNER TO postgres;

--
-- Name: cancel_seating_configuration(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_seating_configuration(p_transition uuid, p_expected_revision bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; started jsonb; original_form bigint; original_bp bigint;
BEGIN
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition;
 IF tr.id IS NULL OR NOT public.can_author_forms(tr.occasion) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[tr.occasion]);
 started:=public.begin_client_mutation_v1(p_command_id,'seating.configuration.cancel',tr.occasion,auth.uid(),encode(extensions.digest(jsonb_build_array(p_transition,p_expected_revision)::text,'sha256'),'hex'));
 IF NOT public.can_author_forms(tr.occasion) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 PERFORM 1 FROM public.forms WHERE id=tr.form FOR UPDATE;
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition FOR UPDATE;
 IF tr.state<>'organizer_managed' OR tr.revision IS DISTINCT FROM p_expected_revision THEN
 RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','CONTEXT_CHANGED')); END IF;
 IF EXISTS(SELECT 1 FROM eshop.spots s JOIN eshop.order_product_ticket x ON x.id=s.order_product_ticket JOIN eshop.orders o ON o.id=x."order" WHERE o.form=tr.form AND s.blueprint=tr.blueprint)
 OR EXISTS(SELECT 1 FROM eshop.spots WHERE blueprint=tr.blueprint AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN
 RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','ASSIGNMENTS_EXIST')); END IF;
 UPDATE public.form_seating_transitions SET state='cancelled',revision=revision+1,finished_by=auth.uid(),finished_at=clock_timestamp() WHERE id=tr.id;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,tr.occasion,'seating.configuration.cancel',
 jsonb_build_array(jsonb_build_object('entityType','form','entityId',tr.form,'operation','update','safeLabel','Seating configuration removed','changedFields',jsonb_build_array('seating'))),
 ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=tr.occasion),jsonb_build_object('transitionId',tr.id,'sourceFormId',tr.form,'targetBlueprintId',tr.blueprint,'context',jsonb_set(public.get_seating_transition_context(tr.id)->'data','{items}','[]'::jsonb)));
END $$;


ALTER FUNCTION public.cancel_seating_configuration(p_transition uuid, p_expected_revision bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: cancel_tickets_command_internal(bigint[], uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_tickets_command_internal(p_tickets bigint[], p_command_id uuid, p_confirmation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_request_tickets bigint[]:=p_tickets; v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_unchanged boolean:=false; v_before_users uuid[]; v_changed_orders bigint[]; v_cancelled jsonb; v_updated jsonb; v_effect jsonb;
BEGIN
  p_tickets:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(p_tickets)));
  IF cardinality(p_tickets)>(SELECT hard_cap FROM public.abuse_policy_rules WHERE rule_key='order.mutation.items') THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded'; END IF;
  SELECT min(t.occasion) INTO v_occasion FROM eshop.tickets t
    WHERE t.id=ANY(p_tickets);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_tickets)=0
    OR (SELECT count(*) FROM eshop.tickets t
      WHERE t.id=ANY(p_tickets) AND t.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id))
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to((jsonb_build_object(
    'tickets',v_request_tickets)||CASE WHEN p_confirmation IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('confirmation',p_confirmation) END)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.tickets.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF p_confirmation IS NULL AND NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=ANY(p_tickets) AND state IS DISTINCT FROM 'storno') THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  BEGIN
  PERFORM public.admit_order_mutation_v1(v_occasion,cardinality(p_tickets));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_tickets)));
  -- Lock in the same order as the bulk mutation, then capture only actual changes.
  PERFORM o.id FROM eshop.orders o WHERE o.id IN (
    SELECT opt."order" FROM eshop.order_product_ticket opt
    JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets)) ORDER BY o.id FOR UPDATE;
  SELECT array_agg(DISTINCT opt."order") INTO v_changed_orders
    FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets) AND t.state IS DISTINCT FROM 'storno';
  IF coalesce(cardinality(v_changed_orders),0)=0 THEN
    IF p_confirmation IS NOT NULL THEN RAISE SQLSTATE 'BC002' USING MESSAGE='confirmed cancellation changed'; END IF;
    RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
  IF p_confirmation IS NULL THEN
    PERFORM public.storno_tickets_bulk_internal_v1(p_tickets, false);
  ELSE
    v_effect:=public.apply_blueprint_ticket_cancellation_internal(v_occasion,(p_confirmation->>'blueprint')::bigint,
      ARRAY(SELECT value::bigint FROM jsonb_array_elements_text(p_confirmation->'spots')));
    IF v_effect->>'confirmationHash' IS DISTINCT FROM p_confirmation->>'hash' OR v_effect->'ticketIds' IS DISTINCT FROM to_jsonb(p_tickets) THEN
      RAISE SQLSTATE 'BC002' USING MESSAGE='confirmed cancellation changed'; END IF;
  END IF;
  SELECT coalesce(jsonb_agg(o.id ORDER BY o.id) FILTER(WHERE o.state='storno'),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('id',o.id,'email',o.data->>'email') ORDER BY o.id)
      FILTER(WHERE o.state IS DISTINCT FROM 'storno'),'[]'::jsonb)
    INTO v_cancelled,v_updated FROM eshop.orders o WHERE o.id=ANY(v_changed_orders);
  EXCEPTION WHEN SQLSTATE 'BC002' THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_CANCELLATION_CHANGED'));
  WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.tickets.cancel',
    jsonb_build_array(jsonb_build_object('entityType','ticket','entityId',NULL,
      'operation','update','safeLabel','Ticket cancellation',
      'changedFields',jsonb_build_array('state','membership','allocations'))),
    v_before_users,jsonb_build_object('ticketIds',to_jsonb(p_tickets),
      'cancelledOrderIds',v_cancelled,'updatedOrders',v_updated)||coalesce(v_effect,'{}'::jsonb));
END; $$;


ALTER FUNCTION public.cancel_tickets_command_internal(p_tickets bigint[], p_command_id uuid, p_confirmation jsonb) OWNER TO postgres;

--
-- Name: canonical_payment_reference_account_internal(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.canonical_payment_reference_account_internal(p_account text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE account text:=upper(regexp_replace(coalesce(p_account,''),'[[:space:]]','','g'));
 parts text[]; bban text; digits text; checksum integer;
BEGIN
 parts:=regexp_match(account,'^(?:([0-9]{1,6})-)?([0-9]{1,10})/([0-9]{4})$');
 IF parts IS NOT NULL THEN
  bban:=parts[3]||lpad(coalesce(parts[1],'0'),6,'0')||lpad(parts[2],10,'0');
  checksum:=98-mod((bban||'123500')::numeric,97)::integer;
  account:='CZ'||lpad(checksum::text,2,'0')||bban;
 END IF;
 IF account='' OR NOT public.is_valid_iban(account) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_ACCOUNT_INVALID'; END IF;
 RETURN account;
END $_$;


ALTER FUNCTION public.canonical_payment_reference_account_internal(p_account text) OWNER TO postgres;

