-- Name: catalog_includes_occasion_internal(bigint, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.catalog_includes_occasion_internal(p_organization bigint, p_owner bigint, p_source text, p_legacy_external boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organizations o WHERE o.id=p_organization AND (
      p_owner=p_organization OR CASE WHEN o.data->>'CATALOG_SOURCE_POLICY'='explicit'
      THEN EXISTS (SELECT 1 FROM public.external_sync_maps m
        WHERE m.target_org_id=p_organization AND m.source_name=p_source)
      ELSE p_legacy_external AND p_source IS NOT NULL END
    )
  );
$$;


