--
-- Name: check_blueprint_block_changes_internal(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_blueprint_block_changes_internal(p_blueprint bigint, p_layout jsonb, p_changes jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE incomplete boolean;protected_member boolean;
BEGIN
 -- Parse incoming changes and selection membership once, then join by identity.
 -- A whole-plan UI save must not scan every unit/JSON change for every member.
 WITH changes AS MATERIALIZED (
  SELECT (c->>'nodeId')::uuid node,(c->>'blocked')::boolean blocked,c->>'operation' operation
  FROM jsonb_array_elements(coalesce(p_changes,'[]'))c
 ), members AS MATERIALIZED (
  SELECT (u->>'id')::uuid unit,member::uuid node FROM jsonb_array_elements(coalesce(p_layout->'selectionUnits','[]'))u
  CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds')member
 ), targets AS MATERIALIZED (
  SELECT DISTINCT m.unit,c.blocked FROM changes c
  JOIN eshop.blueprint_seat_bindings old ON old.blueprint=p_blueprint AND old.node_id=c.node
  JOIN members m ON m.node=c.node
  WHERE c.operation='upsert' AND coalesce(old.blocked,false) IS DISTINCT FROM c.blocked
 )
 SELECT coalesce(bool_or(c.node IS NULL OR c.operation IS DISTINCT FROM 'upsert' OR c.blocked IS DISTINCT FROM t.blocked),false),
  coalesce(bool_or(s.order_product_ticket IS NOT NULL OR s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()),false)
 INTO incomplete,protected_member
 FROM targets t JOIN members m ON m.unit=t.unit LEFT JOIN changes c ON c.node=m.node
 LEFT JOIN eshop.blueprint_seat_bindings b ON b.blueprint=p_blueprint AND b.node_id=m.node
 LEFT JOIN eshop.spots s ON s.id=b.spot;
 IF incomplete THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INCOMPLETE_BLOCK_SELECTION_UNIT'; END IF;
 IF protected_member THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_PROTECTED'; END IF;
END $$;


ALTER FUNCTION public.check_blueprint_block_changes_internal(p_blueprint bigint, p_layout jsonb, p_changes jsonb) OWNER TO postgres;

--
-- Name: check_blueprint_image_resource_internal(jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_blueprint_image_resource_internal(p_layout jsonb, p_occasion bigint) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b jsonb:=p_layout->'background'; a public.blueprint_image_assets; field text; value jsonb;
BEGIN
 IF b IS NULL OR b='null'::jsonb THEN RETURN; END IF;
 IF jsonb_typeof(b)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(b) key WHERE key NOT IN ('assetRef','hash','x','y','rotation','width','height','scale','opacity','crop')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND'; END IF;
 SELECT * INTO a FROM public.blueprint_image_assets WHERE occasion=p_occasion AND asset_ref=b->>'assetRef' AND organization=(SELECT organization FROM public.occasions WHERE id=p_occasion) AND state='ready';
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='BLUEPRINT_ASSET_RESOURCE_NOT_READY'; END IF;
 IF b->>'hash' IS DISTINCT FROM a.hash OR (b->>'width')::numeric IS DISTINCT FROM a.width::numeric OR (b->>'height')::numeric IS DISTINCT FROM a.height::numeric THEN RAISE check_violation USING MESSAGE='BLUEPRINT_ASSET_MANIFEST_MISMATCH'; END IF;
 FOREACH field IN ARRAY ARRAY['x','y','rotation','width','height','scale'] LOOP
  value:=b->field;
  IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR abs(value::numeric)>1000000000 OR field IN ('width','height','scale') AND value::numeric<=0 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND'; END IF;
 END LOOP;
 IF b ? 'opacity' AND (jsonb_typeof(b->'opacity')<>'number' OR (b->>'opacity')::numeric NOT BETWEEN 0 AND 1) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND'; END IF;
 IF jsonb_typeof(b->'crop') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(b->'crop') key WHERE key NOT IN ('x','y','width','height')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND_CROP'; END IF;
 FOREACH field IN ARRAY ARRAY['x','y','width','height'] LOOP
  value:=b->'crop'->field;
  IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR value::numeric NOT BETWEEN 0 AND 1 OR field IN ('width','height') AND value::numeric<=0 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND_CROP'; END IF;
 END LOOP;
 IF (b#>>'{crop,x}')::numeric+(b#>>'{crop,width}')::numeric>1 OR (b#>>'{crop,y}')::numeric+(b#>>'{crop,height}')::numeric>1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND_CROP'; END IF;
END $$;


ALTER FUNCTION public.check_blueprint_image_resource_internal(p_layout jsonb, p_occasion bigint) OWNER TO postgres;

--
-- Name: check_blueprint_selection_units_internal(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_blueprint_selection_units_internal(p_spots bigint[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings selected
   JOIN eshop.blueprint_seat_bindings member ON member.blueprint=selected.blueprint AND member.selection_unit=selected.selection_unit
   WHERE selected.spot=ANY(p_spots) AND selected.selection_unit IS NOT NULL
   AND NOT member.spot=ANY(coalesce(p_spots,'{}'::bigint[]))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INCOMPLETE_SELECTION_UNIT';
 END IF;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings selected
   JOIN eshop.blueprint_seat_bindings member ON member.blueprint=selected.blueprint AND member.selection_unit=selected.selection_unit
   JOIN eshop.spots s ON s.id=member.spot JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket JOIN eshop.tickets t ON t.id=opt.ticket
   WHERE selected.spot=ANY(p_spots) AND selected.selection_unit IS NOT NULL AND t.state='used') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SELECTION_UNIT_USED';
 END IF;
END $$;


ALTER FUNCTION public.check_blueprint_selection_units_internal(p_spots bigint[]) OWNER TO postgres;

--
-- Name: check_blueprint_swap_scope_internal(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_blueprint_swap_scope_internal(p_occasion bigint, p_spots bigint[]) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion)<>cardinality(p_spots)
  OR EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprints b ON b.id=s.blueprint
   LEFT JOIN eshop.products p ON p.id=s.product LEFT JOIN eshop.product_types pt ON pt.id=p.product_type
   LEFT JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
   LEFT JOIN eshop.orders o ON o.id=i."order" LEFT JOIN eshop.tickets t ON t.id=i.ticket
   WHERE s.id=ANY(p_spots) AND (
    (s.blueprint IS NOT NULL AND b.occasion IS DISTINCT FROM p_occasion)
    OR (s.product IS NOT NULL AND (p.occasion IS DISTINCT FROM p_occasion OR pt.occasion IS DISTINCT FROM p_occasion))
    OR (s.order_product_ticket IS NOT NULL AND (o.occasion IS DISTINCT FROM p_occasion OR t.occasion IS DISTINCT FROM p_occasion)))) THEN
  RAISE insufficient_privilege USING MESSAGE='swap assignment scope unavailable'; END IF;
END $$;


ALTER FUNCTION public.check_blueprint_swap_scope_internal(p_occasion bigint, p_spots bigint[]) OWNER TO postgres;

--
-- Name: check_blueprint_text_resources_internal(jsonb, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_blueprint_text_resources_internal(p_layout jsonb, p_occasion bigint, p_setup_draft uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.blueprint_layout_text_requests_internal(p_layout,true) q
  WHERE q.font_face_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.blueprint_text_resources r
   WHERE r.scope_key=CASE WHEN p_occasion IS NOT NULL THEN 'occasion:'||p_occasion::text ELSE 'setup:'||p_setup_draft::text END
    AND r.payload->'descriptor' @> q.descriptor AND r.payload->'descriptor'=q.descriptor)) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_NOT_READY';
 END IF;
END $$;


