--
-- Name: check_companion_relation_invariants_v1(bigint, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_companion_relation_invariants_v1(p_occasion bigint, p_owner uuid, p_companion uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_policy jsonb; v_count bigint;
BEGIN
  IF p_owner IS NULL OR p_companion IS NULL OR p_owner=p_companion THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid companion relation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||p_occasion::text||':'||least(p_owner::text,p_companion::text),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||p_occasion::text||':'||greatest(p_owner::text,p_companion::text),0));
  IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_owner)
    OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_companion) THEN
    RAISE invalid_parameter_value USING MESSAGE='both users must be occasion participants';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_companions uc WHERE uc.occasion=p_occasion
      AND (uc.companion=p_owner OR uc."user"=p_companion)) THEN
    RAISE check_violation USING MESSAGE='companion relations cannot be chained';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_companions uc WHERE uc.occasion=p_occasion
      AND uc.companion=p_companion AND uc."user"<>p_owner) THEN
    RAISE unique_violation USING MESSAGE='participant already has an owner';
  END IF;
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  SELECT count(*) INTO v_count FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=p_owner;
  IF v_count >= (v_policy->>'max_companions')::integer
    AND NOT EXISTS (SELECT 1 FROM public.user_companions uc
      WHERE uc.occasion=p_occasion AND uc."user"=p_owner
        AND uc.companion=p_companion) THEN
    RAISE check_violation USING MESSAGE='maximum companions reached';
  END IF;
END $$;


ALTER FUNCTION public.check_companion_relation_invariants_v1(p_occasion bigint, p_owner uuid, p_companion uuid) OWNER TO postgres;

--
-- Name: check_configuration_scope_internal_v1(text, bigint, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_configuration_scope_internal_v1(kind text, entity_id bigint, organization_id bigint, unit_id bigint, writing boolean) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR organization_id IS DISTINCT FROM (SELECT organization FROM public.user_info WHERE id=auth.uid()) THEN
  RAISE insufficient_privilege USING MESSAGE='configuration tenant mismatch'; END IF;
 IF kind='occasion' THEN
  IF NOT EXISTS(SELECT FROM public.occasions WHERE id=entity_id AND organization=organization_id AND (unit_id IS NULL OR unit=unit_id))
   OR NOT (CASE WHEN writing THEN public.can_edit_occasion(entity_id) ELSE public.can_read_occasion_editor_data(entity_id) OR public.can_edit_occasion(entity_id) END) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion configuration scope denied'; END IF;
 ELSIF kind='unit' THEN
  IF entity_id IS DISTINCT FROM unit_id OR NOT EXISTS(SELECT FROM public.units WHERE id=entity_id AND organization=organization_id)
   OR NOT public.can_manage_unit_configuration(entity_id) THEN
   RAISE insufficient_privilege USING MESSAGE='unit configuration scope denied'; END IF;
 ELSE RAISE invalid_parameter_value USING MESSAGE='unsupported configuration entity'; END IF;
END $$;


ALTER FUNCTION public.check_configuration_scope_internal_v1(kind text, entity_id bigint, organization_id bigint, unit_id bigint, writing boolean) OWNER TO postgres;

--
-- Name: check_delegated_order_deletion_scope_internal_v1(bigint, bigint, bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_delegated_order_deletion_scope_internal_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_delete_orders(p_occasion) OR NOT EXISTS(
  SELECT 1 FROM public.occasions o JOIN public.user_info viewer ON viewer.id=auth.uid() AND viewer.organization=o.organization
  WHERE o.id=p_occasion AND o.organization=p_organization AND (p_unit IS NULL OR o.unit=p_unit)) OR NOT (
  EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion)
  OR EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND occasion=p_occasion AND actor_id=auth.uid() AND command_name='inventory.order.delete'
   AND request_sha256=encode(extensions.digest(convert_to(jsonb_build_object('order',p_order)::text,'UTF8'),'sha256'),'hex'))) THEN RAISE insufficient_privilege USING MESSAGE='order deletion unavailable'; END IF;
END $$;


ALTER FUNCTION public.check_delegated_order_deletion_scope_internal_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: check_delegated_render_scope(bigint, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_delegated_render_scope(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF (CASE WHEN p_blueprint THEN NOT public.can_prepare_layout_resources(p_occasion) ELSE NOT public.can_read_ticket_layout(p_occasion) END) THEN
  RAISE insufficient_privilege USING MESSAGE='render scope denied'; END IF;
 RETURN jsonb_build_object('actorId',auth.uid());
END $$;


ALTER FUNCTION public.check_delegated_render_scope(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint boolean) OWNER TO postgres;

--
-- Name: check_email_template_scope_internal(text, bigint, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_email_template_scope_internal(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_write boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o bigint; u bigint; c bigint;
BEGIN
 IF auth.uid() IS NULL OR p_organization IS NULL OR p_entity_id IS NULL THEN
  RAISE insufficient_privilege USING MESSAGE='email template scope required'; END IF;
 IF p_entity_type='occasion' THEN
  SELECT organization,unit,id INTO o,u,c FROM public.occasions WHERE id=p_entity_id;
  IF NOT FOUND OR (CASE WHEN p_write THEN public.can_write_occasion_email_templates(c)
     ELSE public.can_read_occasion_email_templates(c) END) IS NOT TRUE THEN
   RAISE insufficient_privilege USING MESSAGE='email template access denied'; END IF;
 ELSIF p_entity_type='unit' THEN
  SELECT organization,id INTO o,u FROM public.units WHERE id=p_entity_id;
  IF NOT FOUND OR (CASE WHEN p_write THEN public.can_write_unit_email_templates(u)
     ELSE public.can_read_unit_email_templates(u) END) IS NOT TRUE THEN
   RAISE insufficient_privilege USING MESSAGE='email template access denied'; END IF;
 ELSE RAISE invalid_parameter_value USING MESSAGE='invalid email template entity'; END IF;
 IF o IS DISTINCT FROM p_organization OR (p_unit IS NOT NULL AND u IS DISTINCT FROM p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='email template hierarchy changed'; END IF;
 RETURN jsonb_build_object('occasion',c,'unit',u,'organization',o);
END $$;


ALTER FUNCTION public.check_email_template_scope_internal(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_write boolean) OWNER TO postgres;

