--
-- Name: check_waitlist_scope_internal(bigint, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_waitlist_scope_internal(p_order bigint, p_offer uuid, p_token text, p_actor uuid, p_operation text) RETURNS bigint
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; c eshop.waitlist_capabilities; occ public.occasions;
BEGIN
 SELECT * INTO o FROM eshop.orders WHERE id=p_order; SELECT * INTO occ FROM public.occasions WHERE id=o.occasion;
 IF o.id IS NULL OR o.form IS NULL THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 IF p_actor IS NOT NULL AND public.order_editor_membership_as_actor_internal(p_actor,o.occasion) THEN
  IF p_offer IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE id=p_offer AND order_id=p_order AND form_id=o.form) THEN
   RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF; RETURN o.form;
 END IF;
 IF p_operation IN ('send','cancel','proposal') OR p_token IS NULL OR length(p_token)<>64 THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 SELECT * INTO c FROM eshop.waitlist_capabilities WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
 AND organization_id=occ.organization AND form_id=o.form AND order_id=o.id AND (revoked_at IS NULL OR p_operation='read')
 AND ((p_operation='withdraw' AND kind='manage' AND o.state='waitlisted') OR
 (p_operation IN ('read','accept','decline') AND kind='offer' AND offer_id=p_offer));
 IF c.token_hash IS NULL THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 -- Expired offer links may read their own terminal state; writers recheck time under locks.
 IF p_operation<>'read' AND c.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'OFFER_EXPIRED'; END IF;
 RETURN o.form;
END $$;


ALTER FUNCTION public.check_waitlist_scope_internal(p_order bigint, p_offer uuid, p_token text, p_actor uuid, p_operation text) OWNER TO postgres;

--
-- Name: checkpoint_stripe_session_lookup_internal(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.checkpoint_stripe_session_lookup_internal(p_attempt uuid, p_lease uuid, p_cursor text, p_found text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE a eshop.stripe_checkout_attempts;
BEGIN
 PERFORM public.require_service_role();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT order_id FROM eshop.stripe_checkout_attempts WHERE id=p_attempt));
 PERFORM 1 FROM eshop.orders WHERE id=(SELECT order_id FROM eshop.stripe_checkout_attempts WHERE id=p_attempt) FOR UPDATE;
 PERFORM 1 FROM eshop.payment_info WHERE id=(SELECT payment_info_id FROM eshop.stripe_checkout_attempts WHERE id=p_attempt) FOR UPDATE;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE id=p_attempt FOR UPDATE;
 IF p_lease IS NULL OR p_lease IS DISTINCT FROM a.lease_token OR a.lease_expires_at<=clock_timestamp()
  OR a.session_id IS NOT NULL OR p_cursor IS NULL OR p_cursor !~ '^cs_[A-Za-z0-9_]+$' OR p_cursor=a.session_lookup_cursor
  OR (p_found IS NOT NULL AND p_found !~ '^cs_[A-Za-z0-9_]+$')
  OR (a.session_lookup_found IS NOT NULL AND a.session_lookup_found IS DISTINCT FROM p_found) THEN RAISE EXCEPTION 'STRIPE_SESSION_LOOKUP_INVALID'; END IF;
 IF a.reservation_expires_at<=clock_timestamp() THEN
  PERFORM public.defer_stripe_recovery_internal(p_attempt,p_lease,10);
 END IF;
 UPDATE eshop.stripe_checkout_attempts SET session_lookup_cursor=p_cursor,session_lookup_found=p_found,
  lease_token=NULL,lease_expires_at=NULL,reconcile_failures=0,next_reconcile_at=clock_timestamp()+interval '10 seconds' WHERE id=a.id;
END $_$;


ALTER FUNCTION public.checkpoint_stripe_session_lookup_internal(p_attempt uuid, p_lease uuid, p_cursor text, p_found text) OWNER TO postgres;

--
-- Name: claim_account_deletion(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_account_deletion(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_request public.account_deletion_requests%ROWTYPE;
  v_completion_email text;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO v_request FROM public.account_deletion_requests
  WHERE token_hash = p_token_hash OR used_token_hash = p_token_hash
  LIMIT 1 FOR UPDATE;
  IF v_request.id IS NULL THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.status = 'completed' THEN RETURN jsonb_build_object('status', 'already_completed'); END IF;
  IF v_request.status IN ('deletion_pending','failed') AND v_request.used_token_hash = p_token_hash THEN
    RETURN jsonb_build_object('status','processing','requestId',v_request.id,
      'userId',v_request.user_id,'organization',v_request.organization,
      'publicDeleted',v_request.public_deleted,'authDeleted',v_request.auth_deleted,
      'onesignalDeleted',v_request.onesignal_deleted);
  END IF;
  IF v_request.status <> 'email_sent' THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.expires_at <= clock_timestamp() THEN RETURN jsonb_build_object('status', 'expired'); END IF;

  v_completion_email := public.get_user_delivery_email(v_request.user_id);

  UPDATE public.account_deletion_requests SET
    status='deletion_pending', used_token_hash=token_hash, token_hash=NULL,
    masked_email=NULL, claimed_at=clock_timestamp(), attempt_count=attempt_count+1,
    updated_at=clock_timestamp()
  WHERE id=v_request.id RETURNING * INTO v_request;
  -- The claim and first-party cleanup share one transaction. Consequently an
  -- already-issued JWT cannot regain domain access between confirmation and a
  -- later Edge call; its public.user_info row is gone before claim commits.
  PERFORM public.cleanup_account_deletion_domain(v_request.id);
  RETURN jsonb_build_object('status','processing','requestId',v_request.id,
    'userId',v_request.user_id,'organization',v_request.organization,
    'completionEmail',v_completion_email,
    'publicDeleted',true,'authDeleted',false,'onesignalDeleted',false);
END;
$$;


ALTER FUNCTION public.claim_account_deletion(p_token_hash text) OWNER TO postgres;

--
-- Name: claim_bank_sync_operation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_bank_sync_operation(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_op eshop.bank_sync_operations%ROWTYPE; v_account eshop.bank_accounts%ROWTYPE; v_conn eshop.bank_sync_connections%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  UPDATE eshop.bank_sync_operations SET state='running',lease_token=gen_random_uuid(),updated_at=now() WHERE id=p_id
    AND (state IN ('pending','uncertain','failed') OR (state='running' AND updated_at<now()-interval '5 minutes'))
    RETURNING * INTO v_op;
  IF NOT FOUND THEN RAISE EXCEPTION 'BANK_SYNC_OPERATION_BUSY'; END IF;
  SELECT * INTO STRICT v_account FROM eshop.bank_accounts WHERE id=v_op.bank_account_id;
  SELECT * INTO v_conn FROM eshop.bank_sync_connections WHERE bank_account_id=v_op.bank_account_id;
  RETURN jsonb_build_object('lease_token',v_op.lease_token,'account_number',v_account.account_number,'provider',COALESCE(v_conn.provider,public.bank_sync_provider_for_account(v_account.account_number)),'title',v_account.title,
    'connection_id',v_conn.id,'remote_id',v_conn.remote_bank_account_id,'pairing_code',v_conn.pairing_code,
    'state',v_conn.state,'mode',v_conn.mode,'barrier',v_conn.legacy_blocked_at,'manifest_sha256',v_conn.manifest_sha256,'request',v_op.request,'token_cipher',v_op.token_cipher);
END;
$$;


ALTER FUNCTION public.claim_bank_sync_operation(p_id uuid) OWNER TO postgres;

--
-- Name: claim_client_projection_dirty_internal_v1(bigint[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_client_projection_dirty_internal_v1(p_scope_ids bigint[], p_limit integer) RETURNS TABLE(component text, scope_type text, scope_id bigint, entity_id bigint, source_revision bigint, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  RETURN QUERY
  WITH claimed AS (
    SELECT d.component, d.scope_type, d.scope_id, d.entity_id
    FROM public.client_projection_dirty_keys d
    JOIN public.occasions o
      ON d.scope_type = 'occasion'
     AND o.id = d.scope_id
     AND NOT o.is_hidden
    WHERE (p_scope_ids IS NULL OR d.scope_id = ANY(p_scope_ids))
      AND (d.claimed_at IS NULL
        OR d.claimed_at < now() - interval '2 minutes')
    ORDER BY d.dirty_since
    FOR UPDATE OF d SKIP LOCKED
    LIMIT LEAST(p_limit, 1000)
  ), updated AS (
    UPDATE public.client_projection_dirty_keys d
    SET claimed_at = now(), claim_token = gen_random_uuid()
    FROM claimed c
    WHERE (d.component, d.scope_type, d.scope_id, d.entity_id) =
          (c.component, c.scope_type, c.scope_id, c.entity_id)
    RETURNING d.*
  )
  SELECT u.component, u.scope_type, u.scope_id, u.entity_id,
         u.source_revision, u.claim_token
  FROM updated u;
END;
$$;


ALTER FUNCTION public.claim_client_projection_dirty_internal_v1(p_scope_ids bigint[], p_limit integer) OWNER TO postgres;

--
-- Name: claim_client_projection_dirty_scopes_v1(bigint[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_client_projection_dirty_scopes_v1(p_scope_ids bigint[], p_limit integer DEFAULT 200) RETURNS TABLE(component text, scope_type text, scope_id bigint, entity_id bigint, source_revision bigint, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_scope_ids IS NULL OR cardinality(p_scope_ids) = 0 THEN
    RAISE EXCEPTION 'at least one publication scope is required';
  END IF;
  RETURN QUERY
  SELECT *
  FROM public.claim_client_projection_dirty_internal_v1(p_scope_ids, p_limit);
END;
$$;


