--
-- Name: claim_email(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_email() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_row public.email_messages; v_cap public.email_capacity; v_attempt uuid; v_token uuid:=extensions.gen_random_uuid(); v_wait integer;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO v_cap FROM public.email_capacity FOR UPDATE;
 PERFORM public.recover_email_leases();
 UPDATE public.email_capacity SET heartbeat_at=now() WHERE singleton;
 IF v_cap.paused OR v_cap.quota_at IS NULL OR v_cap.quota_at<now()-interval '15 minutes' OR v_cap.circuit_until>now()
  OR (SELECT count(*) FROM public.email_messages WHERE workflow_state='preparing' AND lease_until>now())>=v_cap.max_preparing THEN RETURN NULL; END IF;
 SELECT (x->>'base_limit')::integer INTO v_wait FROM jsonb_array_elements(public.abuse_effective_rules_v1('email.dispatch',NULL,NULL)->'rules') x;
 IF v_wait IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 SELECT * INTO v_row FROM public.email_messages m
 WHERE workflow_state IN ('pending','retry_wait') AND target_time<=now()
 AND (m.prepared IS NOT NULL OR m.message_kind IN ('registration','sign_in','reset_password','google_mailbox','gotrue','order_confirmation')
  OR (SELECT count(*) FROM public.email_messages heavy WHERE heavy.workflow_state='preparing' AND heavy.lease_until>now() AND heavy.prepared IS NULL
   AND heavy.message_kind NOT IN ('registration','sign_in','reset_password','google_mailbox','gotrue','order_confirmation'))<greatest(1,v_cap.max_preparing-1))
 AND NOT EXISTS(SELECT 1 FROM public.email_messages prior WHERE prior.order_id=m.order_id AND prior.message_kind='order_confirmation'
  AND m.message_kind<>'order_confirmation' AND prior.workflow_state NOT IN ('accepted','cancelled','expired'))
 ORDER BY CASE WHEN m.created_at<=now()-make_interval(secs=>v_wait) THEN 0 ELSE priority END,
 (SELECT max(served.last_claimed_at) FROM public.email_messages served WHERE served.organization=m.organization AND served.last_claimed_at IS NOT NULL) NULLS FIRST,
 CASE WHEN m.unit IS NULL THEN (SELECT max(served.last_claimed_at) FROM public.email_messages served WHERE served.organization=m.organization AND served.unit IS NULL AND served.last_claimed_at IS NOT NULL)
 ELSE (SELECT max(served.last_claimed_at) FROM public.email_messages served WHERE served.unit=m.unit AND served.last_claimed_at IS NOT NULL) END NULLS FIRST,target_time,id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF v_row.id IS NULL THEN RETURN NULL; END IF;
 IF NOT public.email_intent_valid(v_row) THEN
  UPDATE public.email_messages SET workflow_state=CASE WHEN expires_at<=now() THEN 'expired' ELSE 'cancelled' END,last_error='intent_invalid' WHERE id=v_row.id;
  RETURN jsonb_build_object('skipped',true);
 END IF;
 UPDATE public.email_messages SET workflow_state='preparing',last_claimed_at=now(),lease_token=v_token,lease_until=now()+interval '90 seconds' WHERE id=v_row.id RETURNING * INTO v_row;
 INSERT INTO public.email_attempts(message_id,lease_token,state) VALUES(v_row.message_id,v_token,'preparing') RETURNING attempt_id INTO v_attempt;
 RETURN to_jsonb(v_row)||jsonb_build_object('attempt_id',v_attempt);
END $$;


ALTER FUNCTION public.claim_email() OWNER TO postgres;

--
-- Name: claim_notification_center_bank_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_notification_center_bank_health(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.notification_center_require_service();
 INSERT INTO public.notification_center_bank_health(connection_id)
 SELECT DISTINCT c.id FROM eshop.bank_sync_connections c JOIN eshop.unit_bank_accounts uba ON uba.bank_account=c.bank_account_id OR uba.bank_account IN
 (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id)
 JOIN public.units u ON u.id=uba.unit JOIN public.notification_center_organizations a ON a.organization=u.organization
 WHERE c.mode='api' AND c.state IN ('connected','degraded') ON CONFLICT DO NOTHING;
 -- A newly connected source starts against the activation boundary, not its first failed refresh.
 INSERT INTO public.notification_center_source_state(organization,source_key,state)
 SELECT DISTINCT a.organization,'bank:'||c.id,jsonb_build_object('problem',c.created_at<a.initialized_at AND
  (c.last_error IS NOT NULL OR coalesce(c.bank_pull_at,c.created_at)<a.initialized_at-interval '30 minutes'))
 FROM eshop.bank_sync_connections c JOIN eshop.unit_bank_accounts uba ON uba.bank_account=c.bank_account_id OR uba.bank_account IN
  (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id)
 JOIN public.units u ON u.id=uba.unit JOIN public.notification_center_organizations a ON a.organization=u.organization
 WHERE c.mode='api' AND c.state IN ('connected','degraded') ON CONFLICT DO NOTHING;
 WITH selected AS (SELECT h.connection_id FROM public.notification_center_bank_health h JOIN eshop.bank_sync_connections c ON c.id=h.connection_id
 WHERE h.next_at<=clock_timestamp() AND (h.lease_until IS NULL OR h.lease_until<clock_timestamp()) AND c.mode='api' AND c.state IN ('connected','degraded')
 AND EXISTS(SELECT 1 FROM eshop.unit_bank_accounts uba JOIN public.units u ON u.id=uba.unit
 JOIN public.notification_center_organizations a ON a.organization=u.organization WHERE uba.bank_account=c.bank_account_id
 OR uba.bank_account IN(SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id))
 ORDER BY h.next_at,h.connection_id LIMIT greatest(1,least(p_limit,20)) FOR UPDATE OF h SKIP LOCKED), claimed AS (
 UPDATE public.notification_center_bank_health h SET lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '2 minutes'
 FROM selected s WHERE s.connection_id=h.connection_id RETURNING h.*)
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',h.connection_id,'token',h.lease_token,'remoteId',c.remote_bank_account_id)),'[]') INTO result
 FROM claimed h JOIN eshop.bank_sync_connections c ON c.id=h.connection_id;
 RETURN result;
END $$;


ALTER FUNCTION public.claim_notification_center_bank_health(p_limit integer) OWNER TO postgres;

--
-- Name: claim_replacement_invoice_preparation(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_replacement_invoice_preparation(p_order bigint, p_command uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE attempt eshop.replacement_invoice_preparations;receipt jsonb;token uuid:=extensions.gen_random_uuid();state text;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 SELECT o.state INTO state FROM eshop.orders o WHERE o.id=p_order FOR UPDATE;
 SELECT r.response INTO receipt FROM public.client_mutation_receipts r
  WHERE r.command_id=p_command AND (r.command_name='inventory.order.replace' OR (r.command_name IN('inventory.order.create','inventory.waitlist.accept') AND r.response#>'{data,adminQuote}' IS NOT NULL)) AND r.status='completed'
  AND r.response->>'status'='applied' AND (r.response#>>'{data,order,id}')::bigint=p_order;
 IF receipt IS NULL AND NOT EXISTS(SELECT 1 FROM eshop.replacement_invoice_preparations a
  WHERE a.command_id=p_command AND a.order_id=p_order) THEN
  RAISE insufficient_privilege USING MESSAGE='replacement receipt unavailable'; END IF;
 IF state IN('ordered','paid') THEN RETURN jsonb_build_object('status','complete'); END IF;
 IF state IS DISTINCT FROM 'preparing_payment' THEN RETURN jsonb_build_object('status','closed'); END IF;
 PERFORM 1 FROM public.email_messages q WHERE q.code='TICKET_ORDER_CONFIRMATION'
  AND q.data->>'command_id'=p_command::text AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order
  AND q.data->>'fakturoid_pending'='true' FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='invoice preparation claim unavailable'; END IF;
 SELECT * INTO attempt FROM eshop.replacement_invoice_preparations WHERE command_id=p_command FOR UPDATE;
 IF NOT FOUND THEN
  -- Legacy pending receipts may already have dispatched an invoice. They are
  -- lookup-only; absence in one GET is not proof that a POST never executed.
  INSERT INTO eshop.replacement_invoice_preparations(command_id,order_id,state,dispatch_started)
   VALUES(p_command,p_order,'retryable',receipt#>>'{data,paymentPreparationPolicy}' IS DISTINCT FROM 'leased_keep_pending');
  SELECT * INTO STRICT attempt FROM eshop.replacement_invoice_preparations WHERE command_id=p_command FOR UPDATE;
 END IF;
 IF attempt.order_id<>p_order THEN RAISE insufficient_privilege USING MESSAGE='invoice order mismatch'; END IF;
 IF attempt.state='complete' THEN RETURN jsonb_build_object('status','complete'); END IF;
 IF attempt.lease_until>clock_timestamp() THEN RETURN jsonb_build_object('status','busy'); END IF;
 UPDATE eshop.replacement_invoice_preparations SET state='claimed',lease_token=token,
  lease_until=clock_timestamp()+interval '180 seconds',attempts=attempts+1,updated_at=clock_timestamp()
 WHERE command_id=p_command;
 RETURN jsonb_build_object('status','claimed','token',token,'allowCreate',NOT attempt.dispatch_started);
END $$;


ALTER FUNCTION public.claim_replacement_invoice_preparation(p_order bigint, p_command uuid) OWNER TO postgres;

--
-- Name: claim_stripe_checkout_internal(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_stripe_checkout_internal(p_token text, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE cap eshop.stripe_capabilities; a eshop.stripe_checkout_attempts; o eshop.orders; pi eshop.payment_info;
 c eshop.stripe_connections; source jsonb; lease uuid; projection jsonb;
BEGIN
 PERFORM public.require_service_role();
 IF p_token IS NULL OR p_token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 SELECT * INTO cap FROM eshop.stripe_capabilities WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
  AND scope='order_pay' AND revoked_at IS NULL AND expires_at>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[cap.order_id]);
 PERFORM public.authorize_stripe_capability_internal(p_token,'order_pay',cap.order_id);
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=cap.order_id;
 SELECT * INTO STRICT pi FROM eshop.payment_info WHERE id=o.payment_info FOR UPDATE;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE order_id=o.id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 SELECT * INTO STRICT c FROM eshop.stripe_connections WHERE id=a.connection_id;
 IF a.livemode IS DISTINCT FROM p_livemode OR pi.payment_method<>'stripe' OR pi.stripe_connection_id<>a.connection_id
  OR pi.amount*100<>a.amount_minor OR pi.currency_code<>a.currency OR o.currency_code<>a.currency
  OR coalesce(pi.paid_externally,0)<>0 THEN RAISE EXCEPTION 'STRIPE_ORDER_SNAPSHOT_INVALID'; END IF;
 projection:=public.stripe_order_payment_projection_internal(o.id);
 IF projection->>'status' NOT IN ('open','preparing') THEN RETURN jsonb_build_object('disposition','read','payment',projection); END IF;
 IF o.price*100<>a.amount_minor THEN RAISE EXCEPTION 'STRIPE_ORDER_SNAPSHOT_INVALID'; END IF;
 IF a.lease_expires_at>clock_timestamp() OR a.reservation_expires_at<=clock_timestamp() THEN
  RETURN jsonb_build_object('disposition','busy','payment',projection); END IF;
 -- Admission precedes any provider work, keyed by the hashed pay capability.
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('stripe.checkout',a.unit_id,a.organization_id),
  jsonb_build_object('actor',cap.token_hash,'unit',a.unit_id,'organization',a.organization_id));
 SELECT jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash) INTO source
 FROM eshop.stripe_payment_link_sources s JOIN eshop.stripe_capabilities pc USING(token_hash)
 WHERE pc.order_id=o.id AND pc.scope='order_pay' AND pc.revoked_at IS NULL AND pc.expires_at>clock_timestamp()
 ORDER BY s.created_at DESC LIMIT 1;
 IF source IS NULL OR a.return_base_url IS NULL THEN RAISE EXCEPTION 'STRIPE_PAYMENT_SOURCE_UNAVAILABLE'; END IF;
 lease:=extensions.gen_random_uuid();
 UPDATE eshop.stripe_checkout_attempts SET lease_token=lease,lease_expires_at=clock_timestamp()+interval '120 seconds',
  state=CASE WHEN session_id IS NULL THEN 'uncertain' ELSE state END WHERE id=a.id;
 RETURN jsonb_build_object('disposition','dispatch','lease',lease,'source',source,'payment',projection,
  'snapshot',jsonb_build_object('attemptId',a.id,'accountId',c.account_id,'livemode',a.livemode,
   'amountMinor',a.amount_minor,'currency',a.currency,'orderReference','Order '||o.order_symbol,
   'createdAt',extract(epoch FROM a.created_at)::bigint,'expiresAt',extract(epoch FROM a.reservation_expires_at)::bigint,
   'idempotencyKey',a.idempotency_key,'locale',a.checkout_locale,'returnBaseUrl',a.return_base_url,'sessionId',a.session_id,'refundCursor',a.refund_cursor));
END $_$;


ALTER FUNCTION public.claim_stripe_checkout_internal(p_token text, p_livemode boolean) OWNER TO postgres;

--
-- Name: claim_stripe_connection_flow_internal(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_stripe_connection_flow_internal(p_state text, p_actor uuid, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE f eshop.stripe_connection_flows; lease uuid;
BEGIN
 PERFORM public.require_service_role();
 IF p_state IS NULL OR p_state !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_INVALID'; END IF;
 SELECT * INTO f FROM eshop.stripe_connection_flows WHERE state_hash=encode(extensions.digest(p_state,'sha256'),'hex')
  AND actor=p_actor AND livemode=p_livemode AND expires_at>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_INVALID'; END IF;
 PERFORM public.check_stripe_unit_manager_internal(f.unit_id,p_actor);
 IF NOT EXISTS(SELECT 1 FROM public.units WHERE id=f.unit_id AND organization=f.organization_id) THEN
  RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_INVALID'; END IF;
 IF f.state='completed' THEN RETURN jsonb_build_object('disposition','replay','result',f.result); END IF;
 IF f.state<>'pending' THEN RETURN jsonb_build_object('disposition','uncertain'); END IF;
 lease:=extensions.gen_random_uuid();
 UPDATE eshop.stripe_connection_flows SET state='claimed',lease_token=lease WHERE id=f.id;
 RETURN jsonb_build_object('disposition','claimed','flowId',f.id,'lease',lease,'unitId',f.unit_id,'organizationId',f.organization_id);
END $_$;


ALTER FUNCTION public.claim_stripe_connection_flow_internal(p_state text, p_actor uuid, p_livemode boolean) OWNER TO postgres;

--
-- Name: claim_stripe_connection_status_internal(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_stripe_connection_status_internal(p_account text, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c eshop.stripe_connections; lease uuid;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO c FROM eshop.stripe_connections WHERE account_id=p_account AND livemode=p_livemode FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('disposition','unrelated'); END IF;
 IF c.status_lease_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('disposition','busy'); END IF;
 lease:=extensions.gen_random_uuid();
 UPDATE eshop.stripe_connections SET status_lease=lease,status_lease_expires_at=clock_timestamp()+interval '120 seconds' WHERE id=c.id;
 RETURN jsonb_build_object('disposition','dispatch','connectionId',c.id,'lease',lease);
END $$;


ALTER FUNCTION public.claim_stripe_connection_status_internal(p_account text, p_livemode boolean) OWNER TO postgres;

--
-- Name: claim_stripe_disconnect_internal(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_stripe_disconnect_internal(p_intent uuid, p_actor uuid, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE intent eshop.stripe_disconnect_intents; c eshop.stripe_connections;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT intent FROM eshop.stripe_disconnect_intents WHERE id=p_intent AND actor=p_actor FOR UPDATE;
 SELECT * INTO STRICT c FROM eshop.stripe_connections WHERE id=intent.connection_id AND livemode=p_livemode;
 PERFORM public.check_stripe_unit_manager_internal(c.unit_id,p_actor);
 IF intent.state='completed' THEN RETURN jsonb_build_object('disposition','replay','result',intent.result); END IF;
 IF intent.state<>'pending' THEN RETURN jsonb_build_object('disposition','uncertain'); END IF;
 UPDATE eshop.stripe_disconnect_intents SET state='claimed',claimed_at=clock_timestamp() WHERE id=intent.id;
 RETURN jsonb_build_object('disposition','dispatch','accountId',c.account_id);
END $$;


ALTER FUNCTION public.claim_stripe_disconnect_internal(p_intent uuid, p_actor uuid, p_livemode boolean) OWNER TO postgres;

--
-- Name: claim_stripe_sync_internal(text, boolean, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_stripe_sync_internal(p_account text, p_livemode boolean, p_attempt uuid DEFAULT NULL::uuid, p_session text DEFAULT NULL::text, p_intent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a eshop.stripe_checkout_attempts; c eshop.stripe_connections; o eshop.orders; lease uuid; source jsonb;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO c FROM eshop.stripe_connections WHERE account_id=p_account AND livemode=p_livemode;
 IF NOT FOUND THEN RETURN jsonb_build_object('disposition','unrelated'); END IF;
 SELECT * INTO a FROM eshop.stripe_checkout_attempts WHERE connection_id=c.id AND
  ((p_attempt IS NOT NULL AND id=p_attempt) OR (p_session IS NOT NULL AND session_id=p_session) OR (p_intent IS NOT NULL AND payment_intent_id=p_intent))
 ORDER BY created_at DESC LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('disposition','unrelated'); END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[a.order_id]);
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE id=a.id FOR UPDATE;
 IF a.lease_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('disposition','busy'); END IF;
 IF (p_session IS NOT NULL AND a.session_id IS NOT NULL AND p_session<>a.session_id)
  OR (p_intent IS NOT NULL AND a.payment_intent_id IS NOT NULL AND p_intent<>a.payment_intent_id) THEN RAISE EXCEPTION 'STRIPE_SYNC_IDENTITY_MISMATCH'; END IF;
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=a.order_id;
 SELECT jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash) INTO source
 FROM eshop.stripe_payment_link_sources s JOIN eshop.stripe_capabilities pc USING(token_hash)
 WHERE pc.order_id=o.id AND pc.scope='order_pay' ORDER BY s.created_at DESC LIMIT 1;
 -- Historical reads need no bearer secret. Creation still requires its source.
 IF a.return_base_url IS NULL OR (source IS NULL AND coalesce(a.session_id,p_session) IS NULL AND a.reservation_expires_at>clock_timestamp()) THEN
  RAISE EXCEPTION 'STRIPE_PAYMENT_SOURCE_UNAVAILABLE'; END IF;
 lease:=extensions.gen_random_uuid();
 UPDATE eshop.stripe_checkout_attempts SET lease_token=lease,lease_expires_at=clock_timestamp()+interval '120 seconds' WHERE id=a.id;
 RETURN jsonb_build_object('disposition','dispatch','lease',lease,'source',source,
  'snapshot',jsonb_build_object('attemptId',a.id,'accountId',c.account_id,'livemode',a.livemode,
   'amountMinor',a.amount_minor,'currency',a.currency,'orderReference','Order '||o.order_symbol,
   'createdAt',extract(epoch FROM a.created_at)::bigint,'expiresAt',extract(epoch FROM a.reservation_expires_at)::bigint,
   'idempotencyKey',a.idempotency_key,'locale',a.checkout_locale,'returnBaseUrl',a.return_base_url,'sessionId',coalesce(a.session_id,p_session),'refundCursor',a.refund_cursor,
   'sessionLookupCursor',a.session_lookup_cursor,'sessionLookupFound',a.session_lookup_found));
END $$;


ALTER FUNCTION public.claim_stripe_sync_internal(p_account text, p_livemode boolean, p_attempt uuid, p_session text, p_intent text) OWNER TO postgres;

--
-- Name: claim_ticket_batch_document(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_ticket_batch_document(p_batch uuid, p_part uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; part eshop.ticket_batch_document_parts; token uuid:=extensions.gen_random_uuid();
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch FOR UPDATE;
 IF auth.uid() IS NULL OR public.can_read_orders(b.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 PERFORM public.admit_ticket_batch_document_internal(b.occasion);
 IF b.manifest_hash IS NULL THEN
  IF b.resource_lease_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('state','pending'); END IF;
  UPDATE eshop.ticket_batches SET resource_lease_token=token,resource_lease_actor=auth.uid(),
   resource_lease_expires_at=clock_timestamp()+interval '2 minutes',resource_error_code=NULL WHERE id=b.id;
  RETURN public.bound_document_data_v1(jsonb_build_object('state','claimed','kind','resources','lease',token,'snapshot',b.snapshot,'batchId',b.id));
 END IF;
 IF p_part IS NULL THEN
  SELECT * INTO part FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready'
   AND (lease_expires_at IS NULL OR lease_expires_at<=clock_timestamp()) ORDER BY kind,part_key LIMIT 1 FOR UPDATE;
 ELSE SELECT * INTO STRICT part FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND id=p_part FOR UPDATE;
 END IF;
 IF part.id IS NULL THEN RETURN jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready') THEN 'pending' ELSE 'ready' END); END IF;
 IF part.state='ready' THEN RETURN jsonb_build_object('state','ready','partId',part.id,'objectKey',part.object_key,'digest',part.content_digest,'bytes',part.byte_count); END IF;
 IF part.lease_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('state','pending'); END IF;
 UPDATE eshop.ticket_batch_document_parts SET state='rendering',lease_token=token,lease_actor=auth.uid(),
 lease_expires_at=clock_timestamp()+interval '2 minutes',error_code=NULL WHERE id=part.id;
 RETURN public.bound_document_data_v1(jsonb_build_object('state','claimed','kind',part.kind,'lease',token,'partId',part.id,
 'ticketIds',part.ticket_ids,'batchId',b.id,'manifestHash',b.manifest_hash,'manifest',b.resource_manifest,
 'objectKey',b.id::text||'/'||b.manifest_hash||'/'||part.part_key||'.pdf'));
END $$;


ALTER FUNCTION public.claim_ticket_batch_document(p_batch uuid, p_part uuid) OWNER TO postgres;

--
-- Name: claim_wix_billing_delivery(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_wix_billing_delivery(p_app uuid, p_receipt text, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE row public.wix_billing_deliveries; token uuid:=extensions.gen_random_uuid();
BEGIN
 PERFORM public.require_service_role();
 -- Activation changes serialize with claims. There is intentionally no enable RPC.
 PERFORM 1 FROM public.wix_billing_activation WHERE app_id=p_app AND enabled FOR SHARE;
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='WIX_BILLING_NOT_ACTIVATED'; END IF;
 SELECT * INTO STRICT row FROM public.wix_billing_deliveries WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind FOR UPDATE;
 IF row.payload->>'agreementReference' IS DISTINCT FROM (SELECT signed_addendum_reference FROM public.wix_billing_activation WHERE app_id=p_app) THEN
  RAISE check_violation USING MESSAGE='WIX_ACTIVATED_TERMS_MISMATCH'; END IF;
 IF row.state='sending' AND row.lease_until<=clock_timestamp() THEN
  UPDATE public.wix_billing_deliveries SET state='unknown',lease_until=NULL WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind;
  UPDATE public.wix_billing_attempts SET outcome='unknown',finished_at=clock_timestamp(),evidence='{"reason":"expired-attempt"}' WHERE id=row.attempt_id;
  RETURN jsonb_build_object('state','unknown');
 END IF;
 IF row.state<>'prepared' THEN RETURN jsonb_build_object('state',row.state); END IF;
 IF p_kind='REFUND' AND NOT EXISTS(SELECT 1 FROM public.wix_billing_deliveries
  WHERE app_id=p_app AND receipt_id=row.payload#>>'{basis,chargeReceiptId}' AND kind='CHARGE'
   AND instance_id=row.instance_id AND state='confirmed') THEN
  RAISE check_violation USING MESSAGE='WIX_ORIGINAL_CHARGE_UNCONFIRMED'; END IF;
 INSERT INTO public.wix_billing_attempts(id,app_id,receipt_id,kind) VALUES(token,p_app,p_receipt,p_kind);
 UPDATE public.wix_billing_deliveries SET state='sending',attempt_id=token,lease_until=clock_timestamp()+interval '60 seconds'
  WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind;
 RETURN jsonb_build_object('state','claimed','attemptId',token,'payload',row.payload,'instanceId',row.instance_id,'digest',row.payload_digest);
END $$;


ALTER FUNCTION public.claim_wix_billing_delivery(p_app uuid, p_receipt text, p_kind text) OWNER TO postgres;

