--
-- Name: complete_client_mutation_applied_v1(uuid, bigint, text, text, jsonb, text[], jsonb, jsonb, jsonb, text[], jsonb, text, text, jsonb, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_client_mutation_applied_v1(p_command_id uuid, p_occasion bigint, p_source text, p_change_class text, p_items jsonb, p_public_components text[], p_private_impacts jsonb, p_dirty_keys jsonb, p_data jsonb, p_immediate_public_components text[] DEFAULT '{}'::text[], p_extra_replacements jsonb DEFAULT '[]'::jsonb, p_actor_kind text DEFAULT 'user'::text, p_reason text DEFAULT NULL::text, p_immediate_private_replacements jsonb DEFAULT '[]'::jsonb, p_unit_catalog_fanout_units bigint[] DEFAULT '{}'::bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_commit jsonb;
  v_component text;
  v_component_data jsonb;
  v_private_replacement jsonb;
  v_private_revision bigint;
  v_replacements jsonb := COALESCE(p_extra_replacements, '[]'::jsonb);
  v_response jsonb;
  v_fanout_unit bigint;
BEGIN
  IF p_data IS NULL OR octet_length(p_data::text) > 4194304
    OR jsonb_typeof(v_replacements) <> 'array'
    OR jsonb_typeof(COALESCE(p_immediate_private_replacements, '[]')) <> 'array'
    OR NOT COALESCE(p_immediate_public_components, '{}')
      <@ COALESCE(p_public_components, '{}')
  THEN
    RAISE invalid_parameter_value USING MESSAGE = 'invalid applied mutation result';
  END IF;

  v_commit := public.record_client_sync_commit_v1(
    p_occasion,
    p_source,
    p_change_class,
    p_items,
    p_public_components,
    p_private_impacts,
    p_dirty_keys,
    p_actor_kind,
    p_reason
  );
  FOR v_fanout_unit IN
    SELECT DISTINCT id
    FROM unnest(COALESCE(p_unit_catalog_fanout_units, '{}')) id
  LOOP
    PERFORM public.fanout_unit_catalog_v1(
      (v_commit->>'commitId')::uuid,
      v_fanout_unit
    );
  END LOOP;

  FOREACH v_component IN ARRAY COALESCE(p_immediate_public_components, '{}')
  LOOP
    v_component_data := public.get_public_client_sync_component_core_v1(
      v_component,
      'occasion',
      p_occasion
    );
    v_replacements := v_replacements || jsonb_build_array(jsonb_build_object(
      'component', v_component,
      'revision', v_component_data->'revision',
      'payload', v_component_data->'payload'
    ));
  END LOOP;

  FOR v_private_replacement IN
    SELECT value
    FROM jsonb_array_elements(COALESCE(p_immediate_private_replacements, '[]'))
  LOOP
    IF v_private_replacement->>'component' NOT LIKE 'private\_%'
      OR NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(COALESCE(p_private_impacts, '[]')) impact
        WHERE impact->>'component' = v_private_replacement->>'component'
          AND impact->>'userId' = v_private_replacement->>'userId'
      )
    THEN
      RAISE invalid_parameter_value
        USING MESSAGE = 'invalid immediate private replacement';
    END IF;
    SELECT s.source_revision INTO STRICT v_private_revision
    FROM public.client_sync_private_scopes s
    WHERE s.component = v_private_replacement->>'component'
      AND s.occasion = p_occasion
      AND s.user_id = (v_private_replacement->>'userId')::uuid;
    v_replacements := v_replacements || jsonb_build_array(jsonb_build_object(
      'component', v_private_replacement->>'component',
      'revision', v_private_revision,
      'payload', v_private_replacement->'payload'
    ));
  END LOOP;

  v_response := jsonb_build_object(
    'status', 'applied',
    'code', 200,
    'data', p_data,
    'mutation', jsonb_build_object(
      'commandId', p_command_id,
      'receiptId', p_command_id,
      'commitId', v_commit->>'commitId',
      'replayed', false,
      'occurredAt', v_commit->>'occurredAt'
    ),
    'sync', jsonb_build_object('replacements', v_replacements)
  );
  RETURN public.finish_client_mutation_v1(
    p_command_id,
    v_response,
    (v_commit->>'commitId')::uuid
  );
END;
$$;


ALTER FUNCTION public.complete_client_mutation_applied_v1(p_command_id uuid, p_occasion bigint, p_source text, p_change_class text, p_items jsonb, p_public_components text[], p_private_impacts jsonb, p_dirty_keys jsonb, p_data jsonb, p_immediate_public_components text[], p_extra_replacements jsonb, p_actor_kind text, p_reason text, p_immediate_private_replacements jsonb, p_unit_catalog_fanout_units bigint[]) OWNER TO postgres;

--
-- Name: complete_client_mutation_outcome_v1(uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_client_mutation_outcome_v1(p_command_id uuid, p_status text, p_code integer, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_response jsonb;
BEGIN
  IF p_status NOT IN ('unchanged','rejected','conflict')
    OR p_code NOT BETWEEN 100 AND 599 OR p_data IS NULL
    OR octet_length(p_data::text)>4194304 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid mutation outcome';
  END IF;
  v_response:=jsonb_build_object('status',p_status,'code',p_code,'data',p_data,
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
    'sync',jsonb_build_object('replacements','[]'::jsonb));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
END; $$;


ALTER FUNCTION public.complete_client_mutation_outcome_v1(p_command_id uuid, p_status text, p_code integer, p_data jsonb) OWNER TO postgres;

--
-- Name: complete_client_sync_publication_classes_v1(text, bigint, bigint, jsonb, text, text, bigint, jsonb, jsonb, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_client_sync_publication_classes_v1(p_scope_type text, p_scope_id bigint, p_release_revision bigint, p_manifest jsonb, p_manifest_url text, p_manifest_sha256 text, p_manifest_bytes bigint, p_live jsonb, p_head_json jsonb, p_head_etag text, p_catalog_claim_tokens uuid[], p_live_claim_tokens uuid[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_head public.client_sync_public_heads%ROWTYPE; v_component record;
  v_next_catalog bigint := (p_head_json#>>'{catalog,revision}')::bigint;
  v_next_live bigint := (p_head_json#>>'{live,revision}')::bigint;
  v_content_revision bigint; v_notification uuid;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  SELECT * INTO v_head FROM public.client_sync_public_heads
    WHERE scope_type=p_scope_type AND scope_id=p_scope_id FOR UPDATE;
  IF FOUND AND (v_next_catalog < COALESCE(v_head.release_revision,-1)
      OR COALESCE(v_next_live,-1) < COALESCE(v_head.live_revision,-1)
      OR (v_next_catalog = v_head.release_revision
          AND v_next_live IS NOT DISTINCT FROM v_head.live_revision
          AND v_head.head_json IS DISTINCT FROM p_head_json)) THEN
    RETURN false;
  END IF;
  IF p_release_revision IS NOT NULL THEN
    IF p_manifest IS NULL OR p_manifest_sha256 IS NULL
       OR p_release_revision <> v_next_catalog THEN RAISE EXCEPTION 'invalid catalog completion'; END IF;
    INSERT INTO public.client_sync_release_manifests
      (scope_type,scope_id,release_revision,manifest,artifact_url,sha256,byte_size)
    VALUES (p_scope_type,p_scope_id,p_release_revision,p_manifest,p_manifest_url,
      p_manifest_sha256,p_manifest_bytes) ON CONFLICT DO NOTHING;
    FOR v_component IN SELECT key,value FROM jsonb_each(p_manifest->'components') LOOP
      INSERT INTO public.client_sync_publications
        (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
      VALUES (v_component.key,p_scope_type,p_scope_id,
        (v_component.value->>'revision')::bigint,v_component.value->>'mediaType',
        v_component.value->>'url',v_component.value->>'sha256',(v_component.value->>'bytes')::bigint)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  IF p_live IS NOT NULL THEN
    INSERT INTO public.client_sync_publications
      (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
    VALUES ('live_public',p_scope_type,p_scope_id,(p_live->>'revision')::bigint,
      p_live->>'mediaType',p_live->>'url',p_live->>'sha256',(p_live->>'bytes')::bigint)
    ON CONFLICT DO NOTHING;
  END IF;
  INSERT INTO public.client_sync_public_heads
    (scope_type,scope_id,release_revision,manifest_sha256,live_revision,live_sha256,head_etag,head_json)
  VALUES (p_scope_type,p_scope_id,v_next_catalog,p_head_json#>>'{catalog,sha256}',
    v_next_live,p_head_json#>>'{live,sha256}',p_head_etag,p_head_json)
  ON CONFLICT (scope_type,scope_id) DO UPDATE SET
    release_revision=EXCLUDED.release_revision,manifest_sha256=EXCLUDED.manifest_sha256,
    live_revision=EXCLUDED.live_revision,live_sha256=EXCLUDED.live_sha256,
    head_etag=EXCLUDED.head_etag,head_json=EXCLUDED.head_json,updated_at=now();

  -- R2 artifacts and the accepted public head already exist at this point.
  -- Moving ready rows into log_notifications is atomic with recording that head;
  -- explicit dispatch therefore cannot outrun content_catalog.
  v_content_revision:=(p_manifest#>>'{components,content_catalog,revision}')::bigint;
  IF p_scope_type='occasion' AND v_content_revision IS NOT NULL THEN
    FOR v_notification IN WITH ready AS (
      DELETE FROM public.news_notification_outbox q
      WHERE q.occasion=p_scope_id
        AND q.required_content_revision<=v_content_revision
      RETURNING q.*
    )
    INSERT INTO public.log_notifications
      (id,occasion,organization,user_id,"to",heading,content,data,created_at,abuse_admitted_at)
    SELECT r.id,r.occasion,r.organization,r.user_id,r."to",r.heading,r.content,
      r.data,r.created_at,r.abuse_admitted_at
    FROM ready r
    ON CONFLICT (id) DO NOTHING RETURNING id LOOP
      PERFORM public.dispatch_log_notification_v1(v_notification);
    END LOOP;
  END IF;

  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_catalog_claim_tokens,'{}')) AND component<>'live_public';
  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_live_claim_tokens,'{}')) AND component='live_public';
  RETURN true;
END; $$;


ALTER FUNCTION public.complete_client_sync_publication_classes_v1(p_scope_type text, p_scope_id bigint, p_release_revision bigint, p_manifest jsonb, p_manifest_url text, p_manifest_sha256 text, p_manifest_bytes bigint, p_live jsonb, p_head_json jsonb, p_head_etag text, p_catalog_claim_tokens uuid[], p_live_claim_tokens uuid[]) OWNER TO postgres;

--
-- Name: complete_fakturoid_ticket_order_v1(bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_fakturoid_ticket_order_v1(p_order_id bigint, p_command_id uuid, p_variable_symbol bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_state text;
  v_currency text;
  v_payment_id bigint;
  v_existing_vs bigint;
  v_occasion bigint;
  v_queue_id bigint;
  v_impacts jsonb;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
  IF EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE target_order_id=p_order_id AND command_id=p_command_id AND state='aborted') THEN
    RAISE EXCEPTION 'Acceptance attempt aborted'; END IF;
  SELECT o.state,trim(o.currency_code),o.payment_info,o.occasion,pi.variable_symbol
  INTO v_state,v_currency,v_payment_id,v_occasion,v_existing_vs
  FROM eshop.orders o JOIN eshop.payment_info pi ON pi.id=o.payment_info
  WHERE o.id=p_order_id FOR UPDATE OF o,pi;
  IF v_state IS NULL OR p_command_id IS NULL OR p_variable_symbol NOT BETWEEN 1 AND 9999999999 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid Fakturoid completion';
  END IF;
  IF v_state IN ('ordered','paid') THEN
    RETURN v_existing_vs;
  END IF;
  IF v_state<>'preparing_payment' THEN
    RAISE check_violation USING MESSAGE='Fakturoid order is not pending';
  END IF;
  SELECT q.id INTO v_queue_id FROM public.email_messages q
  WHERE q.code='TICKET_ORDER_CONFIRMATION'
    AND q.data->>'command_id'=p_command_id::text
    AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order_id
    AND q.data->>'fakturoid_pending'='true'
  FOR UPDATE;
  IF v_queue_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order confirmation claim missing';
  END IF;
  IF v_currency NOT IN ('CZK','EUR') OR v_existing_vs IS DISTINCT FROM p_variable_symbol THEN
    RAISE check_violation USING MESSAGE='Fakturoid symbol differs from application payment reference';
  END IF;
  UPDATE eshop.waitlist_acceptance_attempts SET state='completed',updated_at=clock_timestamp()
   WHERE target_order_id=p_order_id AND command_id=p_command_id AND state='preparing';
  UPDATE eshop.orders SET state='ordered',updated_at=now() WHERE id=p_order_id;
  UPDATE public.email_messages SET target_time=now(),workflow_state='pending',
    data=jsonb_set(data-'fakturoid_pending','{ticket_order,order,payment_info,variable_symbol}',to_jsonb(p_variable_symbol))
  WHERE id=v_queue_id;
  PERFORM public.wake_email_worker();
  SELECT coalesce(jsonb_agg(jsonb_build_object('component',component,
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
  FROM public.occasion_users ou CROSS JOIN unnest(
    ARRAY['private_profile','private_inventory']) component
  WHERE ou.occasion=v_occasion;
  PERFORM public.record_client_sync_commit_v1(v_occasion,
    'fakturoid.order.complete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',p_order_id,'operation','update',
      'safeLabel','Order payment ready','changedFields',
      jsonb_build_array('state','payment_info'))),'{}',v_impacts,'[]',
    'service',NULL);
  RETURN p_variable_symbol;
END;
$$;


ALTER FUNCTION public.complete_fakturoid_ticket_order_v1(p_order_id bigint, p_command_id uuid, p_variable_symbol bigint) OWNER TO postgres;

--
-- Name: complete_notification_center_bank_health(bigint, uuid, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_notification_center_bank_health(p_connection bigint, p_token uuid, p_success_at timestamp with time zone, p_reason text, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE h public.notification_center_bank_health; c eshop.bank_sync_connections; scope record; old public.notification_center_source_state;
 nc_reason text; key text:='bank:'||p_connection; ev uuid; ep bigint; affected bigint[];
BEGIN
 PERFORM public.notification_center_require_service();
 SELECT * INTO h FROM public.notification_center_bank_health WHERE connection_id=p_connection AND lease_token=p_token AND lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'notification_health_lease_lost'; END IF;
 SELECT * INTO STRICT c FROM eshop.bank_sync_connections WHERE id=p_connection;
 IF p_reason NOT IN ('fio_token_invalid_or_inactive','fio_receiving_account_mismatch','bank_sync_retry_required','transport_unavailable') AND p_reason IS NOT NULL THEN RAISE EXCEPTION 'notification_health_reason_invalid'; END IF;
 nc_reason:=p_reason;
 IF c.state='suspended' THEN nc_reason:=NULL;
 ELSIF nc_reason IS NULL AND coalesce(p_success_at,h.last_success,c.bank_pull_at,c.created_at)<p_at-interval '30 minutes' THEN nc_reason:='stale_health'; END IF;
 h.failures:=CASE WHEN nc_reason IS NULL THEN 0 ELSE h.failures+1 END;
 h.failure_since:=CASE WHEN nc_reason IS NULL THEN NULL ELSE coalesce(h.failure_since,p_at) END;
 UPDATE public.notification_center_bank_health SET failures=h.failures,failure_since=h.failure_since,reason=nc_reason,last_success=greatest(last_success,p_success_at),
 lease_token=NULL,lease_until=NULL,next_at=p_at+CASE WHEN p_reason='transport_unavailable' THEN interval '10 minutes' ELSE interval '5 minutes' END WHERE connection_id=p_connection;
 FOR scope IN SELECT DISTINCT u.organization FROM eshop.unit_bank_accounts uba JOIN public.units u ON u.id=uba.unit
 JOIN public.notification_center_organizations a ON a.organization=u.organization
 WHERE uba.bank_account=c.bank_account_id OR uba.bank_account IN(SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id) LOOP
  PERFORM 1 FROM public.notification_center_organizations WHERE organization=scope.organization FOR SHARE;
  SELECT array_agg(DISTINCT f.occasion) INTO affected FROM public.forms f JOIN public.occasions oc ON oc.id=f.occasion
  WHERE oc.organization=scope.organization AND (f.bank_account=c.bank_account_id OR f.bank_account IN(SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id)
   OR EXISTS(SELECT 1 FROM eshop.orders o JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.form=f.id AND (pi.bank_account=c.bank_account_id OR pi.bank_account IN(SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id))));
  SELECT * INTO old FROM public.notification_center_source_state WHERE organization=scope.organization AND source_key=key FOR UPDATE;
  IF NOT FOUND THEN
   INSERT INTO public.notification_center_source_state(organization,source_key,state) VALUES(scope.organization,key,jsonb_build_object('problem',nc_reason IS NOT NULL,'reason',nc_reason));
   CONTINUE;
  END IF;
  ep:=old.episode;
  IF nc_reason IS NOT NULL AND (nc_reason='fio_token_invalid_or_inactive' OR (h.failures>=2 AND h.failure_since<=p_at-interval '15 minutes')) THEN
   IF NOT coalesce((old.state->>'problem')::boolean,false) THEN
    PERFORM public.notification_center_prepared_invalidate((old.state->>'eventId')::uuid);
    ep:=ep+1;
    ev:=public.notification_center_publish_internal(scope.organization,NULL,'bank_problem',key||':episode:'||ep,
     jsonb_build_object('reason',nc_reason,'bankConnectionId',c.id),NULL,p_at,coalesce(affected,'{}'));
    old.state:=jsonb_build_object('problem',true,'reason',nc_reason,'eventId',ev);
   ELSE
    -- New confirmed evidence refines the same episode. A transport timeout does
    -- not erase a previously confirmed token/account failure before recovery.
    IF old.state->>'reason' IN ('fio_token_invalid_or_inactive','fio_receiving_account_mismatch')
     AND nc_reason IN ('transport_unavailable','bank_sync_retry_required','stale_health') THEN nc_reason:=old.state->>'reason'; END IF;
    UPDATE public.notification_center_events SET data=data||jsonb_build_object('reason',nc_reason) WHERE id=(old.state->>'eventId')::uuid;
    old.state:=old.state||jsonb_build_object('reason',nc_reason);
   END IF;
  ELSIF nc_reason IS NULL AND p_success_at IS NOT NULL AND (old.observed_at<p_success_at OR NOT coalesce((old.state->>'problem')::boolean,false)) THEN
   PERFORM public.notification_center_prepared_invalidate((old.state->>'eventId')::uuid);
   UPDATE public.notification_center_events SET status='recovered' WHERE id=(old.state->>'eventId')::uuid;
   old.state:=old.state||jsonb_build_object('problem',false,'reason',NULL);
  END IF;
  UPDATE public.notification_center_source_state SET state=old.state,episode=ep,observed_at=p_at WHERE organization=scope.organization AND source_key=key;
 END LOOP;
END $$;


ALTER FUNCTION public.complete_notification_center_bank_health(p_connection bigint, p_token uuid, p_success_at timestamp with time zone, p_reason text, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: complete_private_inventory_mutation_v1(uuid, bigint, text, jsonb, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_private_inventory_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_impacted_users uuid[], p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',u.id) ORDER BY u.id),'[]'::jsonb) INTO v_impacts
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_impacted_users,'{}')) id) u
  JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id;
  IF v_actor IS NOT NULL AND v_actor=ANY(COALESCE(p_impacted_users,'{}'))
    AND EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'inventory',p_items,'{}',v_impacts,'[]',p_data,
    '{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION public.complete_private_inventory_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_impacted_users uuid[], p_data jsonb) OWNER TO postgres;

--
-- Name: complete_private_profile_mutation_v1(uuid, bigint, text, jsonb, uuid[], text[], jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_private_profile_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_impacted_users uuid[], p_public_components text[], p_dirty_keys jsonb, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,u.id::text,1
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_impacted_users,'{}')) id) u
  JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',u.id) ORDER BY u.id),'[]'::jsonb) INTO v_impacts
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_impacted_users,'{}')) id) u
  JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id;
  IF v_actor IS NOT NULL AND v_actor=ANY(COALESCE(p_impacted_users,'{}'))
    AND EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'profile',p_items,p_public_components,v_impacts,p_dirty_keys,p_data,
    '{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION public.complete_private_profile_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_impacted_users uuid[], p_public_components text[], p_dirty_keys jsonb, p_data jsonb) OWNER TO postgres;

--
-- Name: complete_profile_inventory_membership_mutation_v1(uuid, bigint, text, jsonb, uuid[], jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_profile_inventory_membership_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_before_users uuid[], p_data jsonb, p_actor_kind text DEFAULT 'user'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_after_users uuid[]; v_removed uuid[];
  v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
  v_public text[]:='{}'; v_dirty jsonb:='[]'::jsonb;
BEGIN
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_after_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT ARRAY(SELECT id FROM unnest(COALESCE(p_before_users,'{}')) id
    WHERE NOT id=ANY(v_after_users)) INTO v_removed;
  DELETE FROM public.client_sync_private_scopes s WHERE s.occasion=p_occasion
    AND s.user_id=ANY(v_removed);
  DELETE FROM public.client_aggregate_versions v
    WHERE v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=ANY(
        ARRAY(SELECT id::text FROM unnest(v_removed) id));
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,id::text,1
    FROM unnest(v_after_users) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component',component,
    'userId',id) ORDER BY id,component),'[]'::jsonb) INTO v_impacts
  FROM unnest(v_after_users) id CROSS JOIN unnest(
    ARRAY['private_profile','private_inventory']) component;
  IF cardinality(v_removed)>0 THEN
    v_public:=ARRAY['live_public'];
    SELECT COALESCE(jsonb_agg(jsonb_build_object('component','live_public',
      'entityId',e.id)),'[]'::jsonb) INTO v_dirty
      FROM public.events e WHERE e.occasion=p_occasion;
  END IF;
  IF v_actor IS NOT NULL AND v_actor=ANY(v_after_users) THEN
    v_replacements:=jsonb_build_array(
      jsonb_build_object('component','private_profile','userId',v_actor,
        'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)),
      jsonb_build_object('component','private_inventory','userId',v_actor,
        'payload',public.get_user_inventory_for_occasion_v1(p_occasion)));
  END IF;
  IF p_source='profile.tickets.import' AND cardinality(v_removed)>0 THEN
    v_impacts:=v_impacts||COALESCE((SELECT jsonb_agg(jsonb_build_object('component','private_activity','userId',id) ORDER BY id) FROM unnest(v_after_users) id),'[]'::jsonb);
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'inventory',p_items,v_public,v_impacts,v_dirty,p_data,
    '{}','[]',p_actor_kind,NULL,v_replacements);
END; $$;


ALTER FUNCTION public.complete_profile_inventory_membership_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_before_users uuid[], p_data jsonb, p_actor_kind text) OWNER TO postgres;

--
-- Name: complete_replacement_invoice_preparation(bigint, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_replacement_invoice_preparation(p_order bigint, p_command uuid, p_token uuid, p_variable_symbol bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE symbol bigint;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 PERFORM 1 FROM public.email_messages q WHERE q.code='TICKET_ORDER_CONFIRMATION'
  AND q.data->>'command_id'=p_command::text AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order FOR UPDATE;
 PERFORM 1 FROM eshop.replacement_invoice_preparations WHERE command_id=p_command AND order_id=p_order
  AND lease_token=p_token AND lease_until>clock_timestamp() AND state='claimed' FOR UPDATE;
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='invoice completion lease unavailable'; END IF;
 symbol:=public.complete_fakturoid_ticket_order_v1(p_order,p_command,p_variable_symbol);
 UPDATE eshop.replacement_invoice_preparations SET state='complete',lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order;
 RETURN symbol;
END $$;


ALTER FUNCTION public.complete_replacement_invoice_preparation(p_order bigint, p_command uuid, p_token uuid, p_variable_symbol bigint) OWNER TO postgres;

--
-- Name: complete_stripe_connection_flow_internal(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_stripe_connection_flow_internal(p_flow uuid, p_lease uuid, p_account jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE f eshop.stripe_connection_flows; c eshop.stripe_connections; current_connection uuid; v_result jsonb;
 occasion_scope bigint; mutation uuid; members uuid[]; changed_forms jsonb;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO f FROM eshop.stripe_connection_flows WHERE id=p_flow AND state='claimed' AND lease_token=p_lease FOR UPDATE;
 IF NOT FOUND OR f.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_INVALID'; END IF;
 PERFORM public.check_stripe_unit_manager_internal(f.unit_id,f.actor);
 -- Checkout and form saves take form before unit. Keep that order while
 -- replacing future recipients; immutable attempts never participate here.
 IF f.previous_connection_id IS NOT NULL THEN
  PERFORM 1 FROM public.forms form JOIN public.occasions occasion ON occasion.id=form.occasion
   WHERE occasion.unit=f.unit_id AND occasion.organization=f.organization_id ORDER BY form.id FOR UPDATE OF form;
 END IF;
 PERFORM 1 FROM public.units WHERE id=f.unit_id AND organization=f.organization_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_CONNECTION_FLOW_INVALID'; END IF;
 IF p_account->>'accountId' IS NULL OR p_account->>'accountId' !~ '^acct_[A-Za-z0-9]+$'
  OR p_account->'modelVerified' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'STRIPE_ACCOUNT_MODEL_UNVERIFIED'; END IF;
 -- Serialize the global identity before checking ownership, without exposing another organizer.
 PERFORM pg_advisory_xact_lock(hashtextextended((p_account->>'accountId')||':'||f.livemode::text,7351));
 SELECT * INTO c FROM eshop.stripe_connections WHERE account_id=p_account->>'accountId' AND livemode=f.livemode FOR UPDATE;
 IF FOUND AND (c.unit_id<>f.unit_id OR c.organization_id<>f.organization_id) THEN RAISE EXCEPTION 'STRIPE_ACCOUNT_UNAVAILABLE'; END IF;
 SELECT id INTO current_connection FROM eshop.stripe_connections WHERE unit_id=f.unit_id AND livemode=f.livemode AND state IN ('connected','restricted') FOR UPDATE;
 IF current_connection IS DISTINCT FROM f.previous_connection_id AND current_connection IS DISTINCT FROM c.id THEN
  RAISE EXCEPTION 'STRIPE_CONNECTION_CHANGED'; END IF;
 IF current_connection IS NOT NULL AND current_connection IS DISTINCT FROM c.id THEN
  UPDATE eshop.stripe_connections SET state='retired',paused=true WHERE id=current_connection;
 END IF;
 IF c.id IS NULL THEN
  INSERT INTO eshop.stripe_connections(organization_id,unit_id,account_id,livemode,state,paused)
  VALUES(f.organization_id,f.unit_id,p_account->>'accountId',f.livemode,'candidate',true) RETURNING * INTO c;
 END IF;
 UPDATE eshop.stripe_connections SET business_name=nullif(left(p_account->>'businessName',200),''),country=p_account->>'country',
  charges_enabled=coalesce((p_account->>'chargesEnabled')::boolean,false),payouts_enabled=coalesce((p_account->>'payoutsEnabled')::boolean,false),
  card_payments_active=coalesce((p_account->>'cardPaymentsActive')::boolean,false),model_verified=true,
  state=CASE WHEN p_account->'ready'='true'::jsonb THEN 'connected' ELSE 'restricted' END,
  checked_at=clock_timestamp(),next_check_at=clock_timestamp()+interval '15 minutes',status_failures=0,status_lease=NULL,status_lease_expires_at=NULL WHERE id=c.id;
 IF current_connection IS NOT NULL AND current_connection IS DISTINCT FROM c.id THEN
  FOR occasion_scope IN SELECT DISTINCT form.occasion FROM public.forms form JOIN public.occasions occasion ON occasion.id=form.occasion
   WHERE occasion.unit=f.unit_id AND occasion.organization=f.organization_id
    AND public.payment_provider_connection_internal(form.data->'payments','stripe')=current_connection ORDER BY form.occasion LOOP
   mutation:=substr(encode(extensions.digest(f.id::text||':forms:'||occasion_scope::text,'sha256'),'hex'),1,32)::uuid;
   PERFORM public.begin_anonymous_client_mutation_v1(mutation,'inventory.form.stripe_recipient',occasion_scope,mutation,
    encode(extensions.digest(f.id::text||':'||c.id::text||':'||occasion_scope::text,'sha256'),'hex'));
   SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO members FROM public.occasion_users ou WHERE ou.occasion=occasion_scope;
   WITH updated AS (
    UPDATE public.forms SET data=jsonb_set(data,'{payments}',public.merge_form_payments_internal(data->'payments',NULL)||jsonb_build_object('providerConnections',
      coalesce(public.merge_form_payments_internal(data->'payments',NULL)->'providerConnections','{}')||jsonb_build_object('stripe',c.id))),updated_at=clock_timestamp()
     WHERE occasion=occasion_scope AND public.payment_provider_connection_internal(data->'payments','stripe')=current_connection RETURNING id
   ), versions AS (
    INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
     SELECT 'form','occasion',occasion_scope,id::text,1 FROM updated
     ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
      SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp() RETURNING aggregate_id
   ) SELECT coalesce(jsonb_agg(jsonb_build_object('entityType','form','entityId',aggregate_id::bigint,'operation','update',
     'safeLabel','Card payment recipient','changedFields',jsonb_build_array('configuration'))),'[]'::jsonb) INTO changed_forms FROM versions;
   PERFORM public.complete_profile_inventory_membership_mutation_v1(mutation,occasion_scope,'inventory.form.stripe_recipient',
    changed_forms,members,jsonb_build_object('connectionId',c.id),'service');
  END LOOP;
 END IF;
 -- Existing card forms follow a verified replacement; bank-only forms and
 -- the tenant's payment switch are unchanged. New recipients remain paused.
 v_result:=jsonb_build_object('connectionId',c.id,'unitId',f.unit_id,'connected',true);
 UPDATE eshop.stripe_connection_flows SET state='completed',result=v_result WHERE id=f.id;
 INSERT INTO eshop.stripe_connection_audit(connection_id,flow_id,actor,action)
 VALUES(c.id,f.id,f.actor,CASE WHEN current_connection=c.id THEN 'reconnected' WHEN current_connection IS NOT NULL THEN 'replaced' ELSE 'connected' END);
 RETURN v_result;
END $_$;


ALTER FUNCTION public.complete_stripe_connection_flow_internal(p_flow uuid, p_lease uuid, p_account jsonb) OWNER TO postgres;

--
-- Name: complete_ticket_batch_document_internal(uuid, uuid, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_ticket_batch_document_internal(p_part uuid, p_lease uuid, p_digest text, p_bytes bigint, p_pages integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; part eshop.ticket_batch_document_parts;
BEGIN
 PERFORM public.require_service_role();
 SELECT b0.* INTO STRICT b FROM eshop.ticket_batches b0 JOIN eshop.ticket_batch_document_parts p ON p.batch_id=b0.id WHERE p.id=p_part FOR UPDATE OF b0;
 SELECT * INTO STRICT part FROM eshop.ticket_batch_document_parts WHERE id=p_part FOR UPDATE;
 IF part.state='ready' THEN
  IF part.content_digest IS DISTINCT FROM p_digest THEN RAISE EXCEPTION 'BATCH_DOCUMENT_IMMUTABLE'; END IF; RETURN; END IF;
 IF part.state<>'rendering' OR part.lease_token IS DISTINCT FROM p_lease OR part.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'BATCH_STALE_LEASE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=b.occasion AND "user"=part.lease_actor AND is_editor_order_view) THEN RAISE insufficient_privilege; END IF;
 IF p_pages<>cardinality(part.ticket_ids) THEN RAISE EXCEPTION 'BATCH_DOCUMENT_PAGE_COUNT'; END IF;
 UPDATE eshop.ticket_batch_document_parts SET state='ready',object_key=b.id::text||'/'||b.manifest_hash||'/'||part.part_key||'.pdf',
 content_digest=p_digest,byte_count=p_bytes,page_count=p_pages,lease_token=NULL,lease_expires_at=NULL,error_code=NULL WHERE id=p_part;
END $$;


ALTER FUNCTION public.complete_ticket_batch_document_internal(p_part uuid, p_lease uuid, p_digest text, p_bytes bigint, p_pages integer) OWNER TO postgres;

--
-- Name: complete_ticket_batch_resources_internal(uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_ticket_batch_resources_internal(p_batch uuid, p_lease uuid, p_manifest jsonb, p_part_size integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; hash text;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch FOR UPDATE;
 IF b.manifest_hash IS NOT NULL THEN RETURN b.manifest_hash; END IF;
 IF b.resource_lease_token IS DISTINCT FROM p_lease OR b.resource_lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'BATCH_STALE_LEASE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=b.occasion AND "user"=b.resource_lease_actor AND is_editor_order_view) THEN RAISE insufficient_privilege; END IF;
 IF jsonb_typeof(p_manifest) IS DISTINCT FROM 'object' OR octet_length(p_manifest::text)>4194304 OR p_part_size NOT BETWEEN 1 AND 20 THEN
  RAISE invalid_parameter_value; END IF;
 hash:=encode(extensions.digest(p_manifest::text,'sha256'),'hex');
 UPDATE eshop.ticket_batches SET resource_manifest=p_manifest,manifest_hash=hash,resource_lease_token=NULL,
 resource_lease_expires_at=NULL WHERE id=b.id;
 INSERT INTO eshop.ticket_batch_document_parts(batch_id,part_key,kind,ticket_ids,manifest_hash)
 SELECT b.id,'single-'||lpad(ordinal::text,3,'0'),'single',ARRAY[ticket_id],hash FROM eshop.ticket_batch_items WHERE batch_id=b.id;
 INSERT INTO eshop.ticket_batch_document_parts(batch_id,part_key,kind,ticket_ids,manifest_hash)
 SELECT b.id,'print-'||lpad(part::text,3,'0'),'print',array_agg(ticket_id ORDER BY ordinal),hash
 FROM (SELECT *,1+(ordinal-1)/p_part_size part FROM eshop.ticket_batch_items WHERE batch_id=b.id) i GROUP BY part;
 RETURN hash;
END $$;


ALTER FUNCTION public.complete_ticket_batch_resources_internal(p_batch uuid, p_lease uuid, p_manifest jsonb, p_part_size integer) OWNER TO postgres;

--
-- Name: complete_unit_mutation_internal_v1(uuid, bigint, text, text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_unit_mutation_internal_v1(p_command_id uuid, p_unit bigint, p_source text, p_entity_type text, p_entity_id bigint, p_operation text, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c public.client_commits%ROWTYPE;
BEGIN
 INSERT INTO public.client_commits(unit,actor_id,actor_display,actor_kind,source,change_class)
 SELECT p_unit,auth.uid(),nullif(concat_ws(' ',u.name,u.surname),''),'user',p_source,'configuration'
 FROM public.user_info u WHERE u.id=auth.uid() RETURNING * INTO c;
 INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
 VALUES(c.commit_id,0,p_entity_type,p_entity_id::text,p_operation,'Unit configuration',ARRAY['aggregate']);
 PERFORM public.fanout_unit_catalog_v1(c.commit_id,p_unit);
 RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object('status','applied','code',200,'data',p_data,
  'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',c.commit_id,
  'replayed',false,'occurredAt',c.occurred_at),'sync',jsonb_build_object('replacements','[]'::jsonb)),c.commit_id);
END $$;


ALTER FUNCTION public.complete_unit_mutation_internal_v1(p_command_id uuid, p_unit bigint, p_source text, p_entity_type text, p_entity_id bigint, p_operation text, p_data jsonb) OWNER TO postgres;

