--
-- Name: configure_bank_sync_health_monitor(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_bank_sync_health_monitor(p_organization_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_url text;
BEGIN
  PERFORM public.require_service_role();
  IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=p_organization_id) THEN RAISE EXCEPTION 'ORGANIZATION_NOT_FOUND'; END IF;
  SELECT regexp_replace(worker_url,'/process-email-queue$','/bank-sync-reconcile') INTO v_url FROM public.email_capacity;
  IF v_url IS NULL OR v_url !~ '^https://[^/]+/functions/v1/bank-sync-reconcile$' THEN RAISE EXCEPTION 'BANK_SYNC_MONITOR_URL_REQUIRED'; END IF;
  PERFORM cron.schedule('festapp_bank_sync_health_'||p_organization_id,'*/5 * * * *',
    format('SELECT net.http_post(url:=%L,body:=jsonb_build_object(''requestSecret'',public.generate_request_secret(3600),''monitor_organization_id'',%s),timeout_milliseconds:=360000)',v_url,p_organization_id));
END;
$_$;


ALTER FUNCTION public.configure_bank_sync_health_monitor(p_organization_id bigint) OWNER TO postgres;

--
-- Name: configure_barion_sandbox_connection_internal(bigint, bigint, text, text, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_barion_sandbox_connection_internal(p_organization bigint, p_unit bigint, p_shop text, p_name text, p_forms bigint[], p_enabled boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE existing eshop.barion_connections; connection uuid;
BEGIN
 PERFORM public.require_service_role();
 IF p_shop IS NULL OR p_shop !~ '^[a-f0-9]{32}$' OR nullif(p_name,'') IS NULL OR p_forms IS NULL OR cardinality(p_forms)>20 OR p_enabled IS NULL
  OR NOT EXISTS(SELECT 1 FROM public.units WHERE id=p_unit AND organization=p_organization)
  OR EXISTS(SELECT 1 FROM unnest(p_forms) fid WHERE fid IS NULL OR NOT EXISTS(
   SELECT 1 FROM public.forms f JOIN public.occasions oc ON oc.id=f.occasion WHERE f.id=fid AND oc.unit=p_unit AND oc.organization=p_organization))
  THEN RAISE EXCEPTION 'BARION_SANDBOX_SCOPE_INVALID'; END IF;
 PERFORM 1 FROM public.units WHERE id=p_unit FOR UPDATE;
 SELECT * INTO existing FROM eshop.barion_connections WHERE account_id=p_shop FOR UPDATE;
 IF existing.id IS NOT NULL AND (existing.unit_id<>p_unit OR existing.organization_id<>p_organization) THEN RAISE EXCEPTION 'BARION_SANDBOX_SCOPE_INVALID'; END IF;
 INSERT INTO eshop.barion_connections(organization_id,unit_id,account_id,business_name,sandbox_form_ids,enabled) VALUES(p_organization,p_unit,p_shop,p_name,p_forms,p_enabled)
 ON CONFLICT(account_id) DO UPDATE SET business_name=excluded.business_name,sandbox_form_ids=excluded.sandbox_form_ids,enabled=excluded.enabled RETURNING id INTO connection;
 RETURN connection;
END $_$;


ALTER FUNCTION public.configure_barion_sandbox_connection_internal(p_organization bigint, p_unit bigint, p_shop text, p_name text, p_forms bigint[], p_enabled boolean) OWNER TO postgres;

--
-- Name: configure_first_login_notifications_v1(bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_first_login_notifications_v1(p_organization bigint, p_recipient text, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.require_service_role();
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('festapp-first-login-notifications',0));
  -- Never send a historical flood when enabling a tenant. Existing users with no
  -- successful login remain eligible for their first real login after activation.
  IF NOT EXISTS(SELECT 1 FROM public.first_login_notification_settings WHERE organization=p_organization) THEN
    INSERT INTO public.first_login_notifications(user_id,organization,baseline)
    SELECT ui.id,ui.organization,true FROM public.user_info ui JOIN auth.users au ON au.id=ui.id
    WHERE ui.organization=p_organization AND au.last_sign_in_at IS NOT NULL ON CONFLICT(user_id) DO NOTHING;
  END IF;
  INSERT INTO public.first_login_notification_settings(organization,recipient,enabled)
  VALUES(p_organization,lower(btrim(p_recipient)),p_enabled)
  ON CONFLICT(organization) DO UPDATE SET recipient=excluded.recipient,enabled=excluded.enabled;
END $$;


ALTER FUNCTION public.configure_first_login_notifications_v1(p_organization bigint, p_recipient text, p_enabled boolean) OWNER TO postgres;

--
-- Name: configure_notification_center_worker(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_notification_center_worker(p_project_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
 PERFORM public.notification_center_require_service();
 IF p_project_url IS NULL OR p_project_url !~ '^https?://[^/?#[:space:]]+/?$' THEN RAISE invalid_parameter_value USING MESSAGE='notification_worker_origin_required'; END IF;
 INSERT INTO public.notification_center_maintenance(name,worker_url) VALUES('delivery-wake',rtrim(p_project_url,'/')||'/functions/v1/process-notification-center')
 ON CONFLICT(name) DO UPDATE SET worker_url=excluded.worker_url,next_at='-infinity',wake_error=NULL;
END $_$;


ALTER FUNCTION public.configure_notification_center_worker(p_project_url text) OWNER TO postgres;

--
-- Name: confirm_blueprint_order_change(bigint[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.confirm_blueprint_order_change(p_spot_ids bigint[], p_input_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN public.confirm_blueprint_order_change_client_sync_v1(
    p_spot_ids,p_input_data,extensions.gen_random_uuid())->'data';
END; $$;


ALTER FUNCTION public.confirm_blueprint_order_change(p_spot_ids bigint[], p_input_data jsonb) OWNER TO postgres;

--
-- Name: confirm_blueprint_order_change_client_sync_v1(bigint[], jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.confirm_blueprint_order_change_client_sync_v1(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before_users uuid[];
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id=ANY(p_spot_ids);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_spot_ids)=0
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id=ANY(p_spot_ids) AND s.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF public.payment_reference_scope_enabled_internal((SELECT id FROM public.forms WHERE occasion=v_occasion ORDER BY id LIMIT 1)) THEN
    RETURN jsonb_build_object('status','rejected','code',409,'data',jsonb_build_object('errorCode','ATOMIC_REPLACEMENT_REQUIRED')); END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spots',p_spot_ids,'input',p_input_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.prepare_replace',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN public.project_local_payment_reference_order_internal(v_begin->'response'); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.confirm_blueprint_order_change_internal_v1(
    p_spot_ids,p_input_data);
  IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',400,v_result); END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.prepare_replace',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',NULL,
      'operation','update','safeLabel','Blueprint order replacement',
      'changedFields',jsonb_build_array('cancellations','allocations'))),
    v_before_users,v_result);
END; $$;


ALTER FUNCTION public.confirm_blueprint_order_change_client_sync_v1(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: confirm_blueprint_order_change_internal_v1(bigint[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.confirm_blueprint_order_change_internal_v1(p_spot_ids bigint[], p_input_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE analysis jsonb;details jsonb;tickets bigint[];occ bigint;
BEGIN
 PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
 PERFORM public.check_blueprint_selection_units_internal(p_spot_ids);
 SELECT occasion INTO occ FROM eshop.spots WHERE id=p_spot_ids[1];
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) AND secret IS NOT NULL
  AND secret_expiration_time>clock_timestamp() AND secret IS DISTINCT FROM (p_input_data->>'secret')::uuid) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_PROTECTED'; END IF;
 analysis:=public.analyze_new_order_spots(p_spot_ids);
 details:=public.blueprint_order_input_internal(p_spot_ids,p_input_data,analysis);
 IF public.payment_method_is_online_internal(p_input_data->>'payment_method') OR EXISTS(
  SELECT 1 FROM eshop.spots s JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
  JOIN eshop.orders o ON o.id=i."order" JOIN eshop.payment_info p ON p.id=o.payment_info
  WHERE s.id=ANY(p_spot_ids) AND public.payment_method_is_online_internal(p.payment_method)) THEN RAISE EXCEPTION 'STRIPE_REPLACEMENT_UNSUPPORTED'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT x."order" FROM eshop.spots s
  JOIN eshop.order_product_ticket x ON x.id=s.order_product_ticket WHERE s.id=ANY(p_spot_ids)));
 PERFORM 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) ORDER BY id FOR UPDATE;
 PERFORM public.check_batch_ticket_print_immutable_internal(ARRAY(SELECT x.ticket FROM eshop.spots s
  JOIN eshop.order_product_ticket x ON x.id=s.order_product_ticket WHERE s.id=ANY(p_spot_ids)));
 SELECT array_agg((e->>'ticket_id')::bigint) INTO tickets FROM jsonb_array_elements(analysis->'conflicts') e
 WHERE e->>'ticket_id' IS NOT NULL;
 IF coalesce(cardinality(tickets),0)>0 THEN PERFORM public.storno_tickets_bulk_internal_v1(tickets); END IF;
 UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL WHERE id=ANY(p_spot_ids);
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 RETURN jsonb_build_object('success',true,'message','Storno performed. Ready to create new order.','orderDetails',details);
EXCEPTION WHEN OTHERS THEN
 RETURN jsonb_build_object('success',false,'message',SQLERRM);
END $$;


ALTER FUNCTION public.confirm_blueprint_order_change_internal_v1(p_spot_ids bigint[], p_input_data jsonb) OWNER TO postgres;

--
-- Name: consume_auth_abuse_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_auth_abuse_v1(p_family text, p_key_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
 PERFORM public.require_service_role();
 IF p_family IS NULL OR p_family NOT IN ('reset.source','reset.account','google.source','google.client','google.global','google.attempt','google.proof')
  OR p_key_hash IS NULL OR p_key_hash !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.'||p_family,NULL,NULL),
  jsonb_build_object('recipient',public.abuse_recipient_key_v1(p_key_hash),'global','all'),'{}',true);
END $_$;


ALTER FUNCTION public.consume_auth_abuse_v1(p_family text, p_key_hash text) OWNER TO postgres;

--
-- Name: consume_password_reset_rate_limit_v1(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_password_reset_rate_limit_v1(p_key_hash text, p_limit integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_limit IS NULL OR p_limit NOT IN (3,20) OR p_window_seconds IS DISTINCT FROM 900 THEN RETURN false; END IF;
 RETURN public.consume_auth_abuse_v1(CASE p_limit WHEN 20 THEN 'reset.source' ELSE 'reset.account' END,p_key_hash);
END $$;


ALTER FUNCTION public.consume_password_reset_rate_limit_v1(p_key_hash text, p_limit integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: consume_qr_login_attempt_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_qr_login_attempt_v1(p_occasion bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE accepted boolean; policy jsonb; cap bigint;
BEGIN
 PERFORM public.require_service_role();
 IF p_occasion IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion) THEN
  RETURN jsonb_build_object('allowed',false); END IF;
 policy:=public.abuse_effective_rules_v1(CASE WHEN p_occasion IS NULL THEN 'qr.global' ELSE 'qr.proof' END,NULL,NULL);
 accepted:=public.abuse_charge_v1(policy,jsonb_build_object('global','all','recipient',p_occasion::text),'{}',true);
 SELECT base_limit INTO cap FROM public.abuse_policy_rules WHERE rule_key='qr.payload.bytes';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 RETURN jsonb_build_object('allowed',accepted,'maxBodyBytes',cap);
END $$;


ALTER FUNCTION public.consume_qr_login_attempt_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: consume_selected_activity_draft_internal_v1(bigint, uuid, bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_selected_activity_draft_internal_v1(p_occasion bigint, p_actor uuid, p_parent bigint, p_selection jsonb, p_graph jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE n integer;
BEGIN
 DELETE FROM public.activity_history h WHERE h.occasion_id=p_occasion
  AND h.user_id=p_actor AND h.history_type='AUTOSAVE'
  AND CASE WHEN p_selection IS NULL THEN
   h.parent_history_id IS NOT DISTINCT FROM p_parent AND
   public.activity_history_graph_internal_v1(p_occasion,h.activities_data)=p_graph
  ELSE h.id=(p_selection->>'id')::bigint
   AND (p_selection->>'created_at' IS NULL OR h.created_at=(p_selection->>'created_at')::timestamptz)
  END;
 GET DIAGNOSTICS n=ROW_COUNT;
 RETURN n;
END $$;


ALTER FUNCTION public.consume_selected_activity_draft_internal_v1(p_occasion bigint, p_actor uuid, p_parent bigint, p_selection jsonb, p_graph jsonb) OWNER TO postgres;

--
-- Name: consume_sign_in_code_v1(text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_sign_in_code_v1(p_email text, p_organization bigint, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_code public.sign_in_codes; v_user uuid; v_email text;
BEGIN
 PERFORM public.require_service_role();
 IF p_code IS NULL OR p_code !~ '^[0-9]{6}$' THEN RETURN NULL; END IF;
 SELECT ui.id,au.email INTO v_user,v_email FROM public.user_info ui JOIN auth.users au ON au.id=ui.id
 WHERE ui.organization=p_organization AND lower(ui.email_readonly)=lower(trim(p_email));
 IF v_user IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO v_code FROM public.sign_in_codes WHERE user_id=v_user FOR UPDATE;
 IF NOT FOUND OR v_code.expires_at<=now() OR v_code.consumed_at IS NOT NULL OR v_code.attempts>=5 THEN RETURN NULL; END IF;
 -- Return rather than raise: failed attempts must commit.
 UPDATE public.sign_in_codes SET attempts=attempts+1 WHERE user_id=v_user;
 IF extensions.crypt(p_code,v_code.code_hash) IS DISTINCT FROM v_code.code_hash THEN RETURN NULL; END IF;
 UPDATE public.sign_in_codes SET consumed_at=now() WHERE user_id=v_user;
 RETURN jsonb_build_object('userId',v_user,'authEmail',v_email);
END $_$;


ALTER FUNCTION public.consume_sign_in_code_v1(p_email text, p_organization bigint, p_code text) OWNER TO postgres;

