--
-- Name: convert_form_presale_content(bigint, bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.convert_form_presale_content(p_form bigint, p_expected_version bigint, p_source_hash text, p_html text, p_conversion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occasion_id bigint; organization_id bigint;
BEGIN
 SELECT source_form.occasion,source_occasion.organization INTO occasion_id,organization_id
 FROM public.forms source_form JOIN public.occasions source_occasion ON source_occasion.id=source_form.occasion WHERE source_form.id=p_form;
 IF auth.uid() IS NULL OR NOT coalesce(public.can_author_forms(occasion_id),false) THEN
  RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 RETURN public.convert_form_presale_content_internal(organization_id,p_form,p_expected_version,p_source_hash,p_html,p_conversion_id);
END $$;


ALTER FUNCTION public.convert_form_presale_content(p_form bigint, p_expected_version bigint, p_source_hash text, p_html text, p_conversion_id uuid) OWNER TO postgres;

--
-- Name: convert_form_presale_content_internal(bigint, bigint, bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.convert_form_presale_content_internal(p_organization bigint, p_form bigint, p_expected_version bigint, p_source_hash text, p_html text, p_conversion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f public.forms%ROWTYPE; occasion_id bigint; organization_id bigint; version_now bigint; saved public.form_presale_content_archive%ROWTYPE;
 d jsonb; html_hash text; snapshot jsonb;
BEGIN
 SELECT source_form.occasion,source_occasion.organization INTO occasion_id,organization_id
 FROM public.forms source_form JOIN public.occasions source_occasion ON source_occasion.id=source_form.occasion WHERE source_form.id=p_form;
 IF p_organization IS NULL OR organization_id IS DISTINCT FROM p_organization THEN
  RAISE insufficient_privilege USING MESSAGE='presale conversion organization mismatch'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occasion_id]);
 SELECT * INTO f FROM public.forms WHERE id=p_form FOR UPDATE;
 html_hash:=encode(extensions.digest(convert_to(p_html,'UTF8'),'sha256'),'hex');
 SELECT * INTO saved FROM public.form_presale_content_archive WHERE form=p_form;
 IF FOUND THEN
  IF saved.conversion_id IS DISTINCT FROM p_conversion_id OR saved.source_hash IS DISTINCT FROM p_source_hash
    OR saved.converted_html_hash IS DISTINCT FROM html_hash THEN
   RAISE invalid_parameter_value USING MESSAGE='presale conversion identity mismatch'; END IF;
  RETURN jsonb_build_object('form',p_form,'version',saved.result_version,'replayed',true);
 END IF;
 IF p_html IS NULL OR p_conversion_id IS NULL OR p_expected_version IS NULL OR
    encode(extensions.digest(convert_to(coalesce(f.data,'{}')::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_source_hash THEN
  RAISE invalid_parameter_value USING MESSAGE='presale source changed'; END IF;
 IF f.data#>>'{design,presale_header}' IS NOT NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='form already uses canonical presale content'; END IF;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('form','occasion',f.occasion,p_form::text,0) ON CONFLICT DO NOTHING;
 SELECT version INTO version_now FROM public.client_aggregate_versions WHERE aggregate_type='form'
  AND scope_type='occasion' AND scope_id=f.occasion AND aggregate_id=p_form::text FOR UPDATE;
 IF version_now<>p_expected_version THEN RAISE serialization_failure USING MESSAGE='presale version conflict'; END IF;
 d:=public.normalize_form_metadata_internal(f.data);
 d:=jsonb_set(d,'{schedule}',coalesce(d->'schedule','{}')-'before_start_message'-'show_before_start_message'||jsonb_build_object('countdown_title',p_html));
 d:=jsonb_set(d,'{design}',coalesce(d->'design','{}')||jsonb_build_object('presale_header',
  CASE WHEN coalesce((d#>>'{schedule,enable_countdown}')::boolean,false) THEN 'date' ELSE 'none' END));
 -- Preflight uses the same byte budgets; recheck against the real saved
 -- snapshot before commit. A failed check rolls back archive and page together.
 PERFORM public.apply_form_settings_internal(d,jsonb_build_object('schedule',jsonb_build_object('countdown_title',p_html)));
 INSERT INTO public.form_presale_content_archive(form,conversion_id,original_version,source_hash,original_data,converted_html_hash,result_version)
 VALUES(p_form,p_conversion_id,version_now,p_source_hash,f.data,html_hash,version_now+1);
 UPDATE public.forms SET data=d,updated_at=clock_timestamp() WHERE id=p_form;
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp()
 WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=f.occasion AND aggregate_id=p_form::text;
 snapshot:=public.get_form_authoring_snapshot_internal(p_form);
 IF (public.presale_conversion_budgets_internal(d,p_html,snapshot)->>'blocked')::boolean THEN
  RAISE program_limit_exceeded USING MESSAGE='PRESALE_SIZE_BLOCKED'; END IF;
 RETURN jsonb_build_object('form',p_form,'version',version_now+1,'replayed',false);
END $$;


ALTER FUNCTION public.convert_form_presale_content_internal(p_organization bigint, p_form bigint, p_expected_version bigint, p_source_hash text, p_html text, p_conversion_id uuid) OWNER TO postgres;

--
-- Name: copy_blueprint_canonical_bitmap_resources_internal(bigint, bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_blueprint_canonical_bitmap_resources_internal(p_source bigint, p_unit bigint, p_target bigint, p_layout jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ref record; asset public.blueprint_image_assets; target_org bigint; target_unit bigint;
BEGIN
 SELECT organization,unit INTO target_org,target_unit FROM public.occasions WHERE id=p_target;
 IF target_org IS NULL OR (p_source IS NOT NULL AND (SELECT organization FROM public.occasions WHERE id=p_source) IS DISTINCT FROM target_org)
  OR (p_unit IS NOT NULL AND p_unit IS DISTINCT FROM target_unit) THEN RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_INVALID_ASSET_COPY_SCOPE';END IF;
 FOR ref IN SELECT * FROM public.blueprint_layout_asset_refs_internal(p_layout) LOOP
  SELECT * INTO asset FROM public.blueprint_image_assets a WHERE a.organization=target_org AND a.asset_ref=ref.asset_ref AND a.hash=ref.hash AND a.state='ready'
   AND (a.occasion=p_source OR a.unit=p_unit OR a.occasion=p_target) ORDER BY a.occasion NULLS LAST LIMIT 1;
  IF NOT FOUND THEN RAISE check_violation USING MESSAGE='BLUEPRINT_IMAGE_RESOURCE_NOT_READY';END IF;
  INSERT INTO public.blueprint_image_assets(occasion,organization,asset_ref,hash,url,width,height,mime_type,byte_length,state)
  VALUES(p_target,target_org,asset.asset_ref,asset.hash,asset.url,asset.width,asset.height,asset.mime_type,asset.byte_length,asset.state)
  ON CONFLICT(occasion,asset_ref) WHERE occasion IS NOT NULL DO NOTHING;
 END LOOP;
 PERFORM public.check_blueprint_bitmap_resources_internal(p_layout,p_target);
END $$;


ALTER FUNCTION public.copy_blueprint_canonical_bitmap_resources_internal(p_source bigint, p_unit bigint, p_target bigint, p_layout jsonb) OWNER TO postgres;

--
-- Name: copy_blueprint_image_resources_internal(bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_blueprint_image_resources_internal(p_source_occasion bigint, p_target_occasion bigint, p_layout jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF p_layout->>'schemaVersion'='2' THEN
  PERFORM public.copy_blueprint_canonical_bitmap_resources_internal(p_source_occasion,NULL,p_target_occasion,p_layout);RETURN;
 END IF;
 IF p_source_occasion=p_target_occasion THEN
  PERFORM public.check_blueprint_image_resource_internal(p_layout,p_source_occasion);RETURN;
 END IF;
 PERFORM public.check_blueprint_image_resource_internal(p_layout,p_source_occasion);
 IF (SELECT organization FROM public.occasions WHERE id=p_source_occasion) IS DISTINCT FROM (SELECT organization FROM public.occasions WHERE id=p_target_occasion) THEN RAISE insufficient_privilege USING MESSAGE='same organization image copy required';END IF;
 INSERT INTO public.blueprint_image_assets(occasion,organization,asset_ref,hash,url,width,height,mime_type,byte_length,state)
 SELECT p_target_occasion,o.organization,a.asset_ref,a.hash,a.url,a.width,a.height,a.mime_type,a.byte_length,a.state
 FROM public.blueprint_image_assets a JOIN public.occasions o ON o.id=p_target_occasion
 WHERE a.occasion=p_source_occasion AND a.asset_ref=p_layout#>>'{background,assetRef}'
 ON CONFLICT(occasion,asset_ref) WHERE occasion IS NOT NULL DO NOTHING;
 PERFORM public.check_blueprint_image_resource_internal(p_layout,p_target_occasion);
END $$;


ALTER FUNCTION public.copy_blueprint_image_resources_internal(p_source_occasion bigint, p_target_occasion bigint, p_layout jsonb) OWNER TO postgres;

--
-- Name: copy_blueprint_text_resources_internal(bigint, uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_blueprint_text_resources_internal(p_source_occasion bigint, p_source_draft uuid, p_target bigint, p_layout jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE entry record;old jsonb;scope text:='occasion:'||p_target::text;
BEGIN
 IF (p_source_occasion IS NULL)=(p_source_draft IS NULL) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_TEXT_COPY_SCOPE';END IF;
 FOR entry IN SELECT DISTINCT r.resource_id,r.resource_kind,r.payload FROM public.blueprint_text_resources r JOIN public.blueprint_layout_text_requests_internal(p_layout,true) q
  ON r.payload->'descriptor' @> q.descriptor AND r.payload->'descriptor'=q.descriptor
  WHERE r.scope_key=CASE WHEN p_source_occasion IS NOT NULL THEN 'occasion:'||p_source_occasion::text ELSE 'setup:'||p_source_draft::text END LOOP
  SELECT payload INTO old FROM public.blueprint_text_resources WHERE scope_key=scope AND resource_id=entry.resource_id;
  IF FOUND AND old IS DISTINCT FROM entry.payload THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_IMMUTABLE';END IF;
  INSERT INTO public.blueprint_text_resources(scope_key,occasion,resource_id,resource_kind,payload) VALUES(scope,p_target,entry.resource_id,entry.resource_kind,entry.payload) ON CONFLICT DO NOTHING;
 END LOOP;
END $$;


ALTER FUNCTION public.copy_blueprint_text_resources_internal(p_source_occasion bigint, p_source_draft uuid, p_target bigint, p_layout jsonb) OWNER TO postgres;

--
-- Name: copy_blueprint_unit_image_resources_internal(bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_blueprint_unit_image_resources_internal(p_source_unit bigint, p_target_occasion bigint, p_layout jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a public.blueprint_image_assets;
BEGIN
 IF p_layout->>'schemaVersion'='2' THEN
  PERFORM public.copy_blueprint_canonical_bitmap_resources_internal(NULL,p_source_unit,p_target_occasion,p_layout);RETURN;
 END IF;
 IF p_layout->'background' IS NULL OR p_layout->'background'='null'::jsonb THEN RETURN;END IF;
 SELECT * INTO a FROM public.blueprint_image_assets WHERE unit=p_source_unit AND asset_ref=p_layout#>>'{background,assetRef}' AND state='ready';
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.occasions o WHERE o.id=p_target_occasion AND o.unit=p_source_unit AND o.organization=a.organization) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_ASSET_RESOURCE_NOT_READY';END IF;
 INSERT INTO public.blueprint_image_assets(occasion,organization,asset_ref,hash,url,width,height,mime_type,byte_length,state)
 VALUES(p_target_occasion,a.organization,a.asset_ref,a.hash,a.url,a.width,a.height,a.mime_type,a.byte_length,a.state)
 ON CONFLICT(occasion,asset_ref) WHERE occasion IS NOT NULL DO NOTHING;
 PERFORM public.check_blueprint_image_resource_internal(p_layout,p_target_occasion);
END $$;


ALTER FUNCTION public.copy_blueprint_unit_image_resources_internal(p_source_unit bigint, p_target_occasion bigint, p_layout jsonb) OWNER TO postgres;

--
-- Name: copy_empty_inventory_spot_internal(bigint, bigint, bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_empty_inventory_spot_internal(p_source bigint, p_occasion bigint, p_product bigint, p_blueprint bigint, p_context bigint, p_resource bigint, p_slot bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE source eshop.spots; new_id bigint;
BEGIN
 SELECT * INTO source FROM eshop.spots WHERE id=p_source;
 IF source.id IS NULL OR NOT public.can_copy_occasion_source(source.occasion)
  OR (SELECT organization FROM public.occasions WHERE id=p_occasion) IS DISTINCT FROM
     (SELECT organization FROM public.occasions WHERE id=source.occasion) THEN RAISE insufficient_privilege USING MESSAGE='Inventory copy source denied'; END IF;
 IF public.can_copy_inventory_target(p_occasion) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='Inventory copy target denied'; END IF;
 IF (p_product IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=p_product AND occasion=p_occasion))
  OR (p_blueprint IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion))
  OR (p_context IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.inventory_contexts c JOIN public.inventory_pools p ON p.id=c.inventory_pool WHERE c.id=p_context AND p.occasion=p_occasion))
  OR (p_resource IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resources WHERE id=p_resource AND occasion=p_occasion))
  OR (p_slot IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resource_slots WHERE id=p_slot AND resource=p_resource)) THEN RAISE check_violation USING MESSAGE='Inventory copy target denied'; END IF;
 INSERT INTO eshop.spots(created_at,occasion,product,updated_at,secret,secret_expiration_time,title,order_product_ticket,blueprint,inventory_context,resource,resource_slot)
 VALUES(now(),p_occasion,p_product,now(),NULL,NULL,source.title,NULL,p_blueprint,p_context,p_resource,p_slot) RETURNING id INTO new_id;
 RETURN new_id;
END $$;


ALTER FUNCTION public.copy_empty_inventory_spot_internal(p_source bigint, p_occasion bigint, p_product bigint, p_blueprint bigint, p_context bigint, p_resource bigint, p_slot bigint) OWNER TO postgres;

