--
-- Name: create_form_ws(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_form_ws(input_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_response jsonb;
BEGIN
  IF input_data IS NULL OR jsonb_typeof(input_data)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(input_data) k
      WHERE k NOT IN ('occasion_link','link','title')) THEN
    RETURN jsonb_build_object('code',4000,'message','Invalid form input'); END IF;
  v_response:=public.create_form_client_sync_v1(input_data->>'occasion_link',
    input_data->>'link',input_data->>'title',extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',CASE WHEN v_response->>'status'='applied'
      THEN 201 ELSE (v_response->>'code')::integer END,
    'message',CASE WHEN v_response->>'status'='applied'
      THEN 'Form created successfully' ELSE v_response#>>'{data,message}' END,
    'data',v_response#>'{data,form}');
END; $$;


ALTER FUNCTION public.create_form_ws(input_data jsonb) OWNER TO postgres;

--
-- Name: create_initial_occasion_form_internal_v1(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_initial_occasion_form_internal_v1(p_occasion_id bigint, p_link text, p_title text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_unit bigint;
BEGIN
  SELECT unit INTO v_unit FROM public.occasions WHERE id=p_occasion_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(v_unit)
    OR EXISTS(SELECT 1 FROM public.forms WHERE occasion=p_occasion_id) THEN
    RAISE insufficient_privilege USING MESSAGE='initial occasion form creation unavailable';
  END IF;
  PERFORM public.check_occasion_writable(p_occasion_id);
  RETURN public.insert_form_for_occasion_internal_v1(p_occasion_id,p_link,p_title);
END $$;


