--
-- Name: create_occasion_client_sync_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_occasion_client_sync_v1(p_command_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_config jsonb; v_data jsonb;
BEGIN
  v_data:=CASE WHEN jsonb_typeof(p_config->'data')='object'
    THEN p_config->'data' ELSE '{}'::jsonb END;
  v_config:=jsonb_set(p_config,'{data}',
    jsonb_set(v_data,'{client_sync_v1}','false'::jsonb,true),true);
  RETURN public.create_occasion_domain_command_internal_v1(p_command_id,v_config);
END; $$;


ALTER FUNCTION public.create_occasion_client_sync_v1(p_command_id uuid, p_config jsonb) OWNER TO postgres;

--
-- Name: create_occasion_domain_command_internal_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_occasion_domain_command_internal_v1(p_command_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_unit bigint; v_organization bigint;
  v_occasion bigint; v_begin jsonb; v_hash text; v_commit public.client_commits%ROWTYPE;
  v_entity jsonb;
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object'
    OR octet_length(p_config::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_config) key WHERE key NOT IN
      ('id','start_time','end_time','is_open','is_hidden','is_promoted','link','title',
       'description','data','services','organization','unit','features','form_link',
       'has_orders','stats'))
    OR p_config->>'id' IS NOT NULL
    OR nullif(btrim(p_config->>'title'),'') IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid occasion aggregate'; END IF;
  v_unit:=NULLIF(p_config->>'unit','')::bigint;
  v_organization:=NULLIF(p_config->>'organization','')::bigint;
  PERFORM 1 FROM public.units u WHERE u.id=v_unit FOR SHARE;
  IF v_actor IS NULL OR v_unit IS NULL OR v_organization IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.units u
      WHERE u.id=v_unit AND u.organization=v_organization)
    OR NOT public.can_create_occasion(v_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(p_config::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'occasion.create',v_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_occasion_creation_v1(v_actor,v_unit,v_organization);
  PERFORM public.update_occasion_internal_v1(p_config);
  SELECT o.id,to_jsonb(o)||jsonb_build_object('aggregate_version',1)
    INTO v_occasion,v_entity FROM public.occasions o
    WHERE o.id=currval(pg_get_serial_sequence('public.occasions','id'));
  IF v_occasion IS NULL THEN
    RAISE data_exception USING MESSAGE='occasion create returned no aggregate'; END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion','occasion',v_occasion,v_occasion::text,1);
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT v_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'occasion.create','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'occasion',v_occasion::text,'insert',
    left(v_entity->>'title',240),ARRAY['aggregate']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object(
      'occasionId',v_occasion,'occasion',v_entity),
    'mutation',jsonb_build_object('commandId',p_command_id,
      'receiptId',p_command_id,'commitId',v_commit.commit_id,'replayed',false,
      'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $$;


ALTER FUNCTION public.create_occasion_domain_command_internal_v1(p_command_id uuid, p_config jsonb) OWNER TO postgres;

--
-- Name: create_occasion_setup_draft(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_occasion_setup_draft(p_id uuid, p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts; configuration jsonb; is_new boolean; policy jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  -- Serialize identical UUIDs before inspecting existence, without charging retries.
  PERFORM pg_advisory_xact_lock(hashtextextended('draft:'||p_id::text,0));
  is_new:=NOT EXISTS(SELECT 1 FROM public.occasion_setup_drafts WHERE id=p_id);
  IF is_new THEN
    policy:=public.abuse_effective_rules_v1('occasion.draft',p_unit,(SELECT organization FROM public.units WHERE id=p_unit));
    PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,
      (SELECT organization FROM public.units WHERE id=p_unit),0,true,true,policy);
  END IF;
  INSERT INTO public.occasion_setup_drafts(id,unit,organization,author)
    SELECT p_id,id,organization,auth.uid() FROM public.units WHERE id = p_unit
    ON CONFLICT (id) DO NOTHING;
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF d.unit IS DISTINCT FROM p_unit OR d.author IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF NOT (d.data ? 'defaultConfiguration') THEN
    IF NOT is_new THEN
      policy:=public.abuse_effective_rules_v1('occasion.draft',p_unit,d.organization);
      PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,d.organization,0,false,true,policy);
    END IF;
    configuration := public.build_occasion_setup_configuration(p_unit,p_id);
    UPDATE public.occasion_setup_drafts SET data =
      public.normalize_setup_payments_internal(jsonb_build_object('defaultConfiguration',configuration,
        'formDraft',configuration->'forms'->0,'formDefaultsFollowEvent',true,
        'paymentMethod',(SELECT CASE WHEN public.payment_method_registered_internal(data->>'DEFAULT_FORM_PAYMENT_METHOD') AND data->>'DEFAULT_FORM_PAYMENT_METHOD'<>'bank' THEN data->>'DEFAULT_FORM_PAYMENT_METHOD' END FROM public.organizations WHERE id=d.organization),
        'paymentChoicesEnabled',EXISTS(SELECT 1 FROM jsonb_each(public.provider_unit_features_internal(d.unit)) x WHERE x.value='true'::jsonb))
      || d.data) WHERE id = p_id RETURNING * INTO d;
    PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,d.organization,octet_length(d.data::text),false,false,policy);
  END IF;
  RETURN jsonb_set(to_jsonb(d),'{data}',public.normalize_setup_payments_internal(d.data));
END $$;


ALTER FUNCTION public.create_occasion_setup_draft(p_id uuid, p_unit bigint) OWNER TO postgres;

--
-- Name: create_occasion_user_client_sync_v1(bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_occasion_user_client_sync_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_user uuid; v_begin jsonb; v_hash text;
  v_version bigint;
  v_result jsonb; v_profile jsonb; v_entity jsonb;
BEGIN
  PERFORM public.lock_people_scope_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT (public.can_manage_occasion_participants(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR p_profile->>'user' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid new occasion user profile'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  BEGIN
  v_result:=public.update_user_internal_v1(jsonb_build_object(
    'occasion',p_occasion,'user',NULL,'data',p_profile->'data'));
  IF COALESCE((v_result->>'code')::integer,500) NOT IN (200,201) THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  v_user:=(v_result->>'user')::uuid;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,v_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  v_profile:=p_profile||jsonb_build_object('user',v_user);
  v_result:=public.save_occasion_user_for_edit_internal_v1(v_profile);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0P01' THEN
    -- All domain writes, including an account/membership created earlier, rolled back.
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      coalesce((v_result->>'code')::integer,400),jsonb_build_object('version',0,'profile',NULL,'message',v_result->>'message'));
  END;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,v_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  SELECT public.get_occasion_user_command_data_v1(p_occasion,v_user) INTO v_entity;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',v_user,'operation','insert',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
    'userId',v_user)),'[]',jsonb_build_object('version',v_version,'userId',v_user,
      'profile',v_entity));
END; $$;


ALTER FUNCTION public.create_occasion_user_client_sync_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb) OWNER TO postgres;

--
-- Name: create_product_price_wave(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_product_price_wave(p_occasion_link text, p_change_time timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_occasion bigint; v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT o.id INTO STRICT v_occasion FROM public.occasions o JOIN public.user_info ui
    ON ui.organization=o.organization WHERE o.id=public.resolve_occasion_link_internal(p_occasion_link) AND ui.id=auth.uid();
  PERFORM public.check_product_wave_editor(v_occasion);
  IF p_change_time IS NULL OR NOT isfinite(p_change_time) OR p_change_time<=clock_timestamp() THEN
    RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  INSERT INTO eshop.product_price_waves(occasion,change_time) VALUES(v_occasion,p_change_time)
    ON CONFLICT(occasion,change_time) DO NOTHING;
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves
    WHERE occasion=v_occasion AND change_time=p_change_time FOR UPDATE;
  -- Adopt existing unambiguous targets at this shared term without repricing.
  PERFORM 1 FROM eshop.products p WHERE p.occasion=v_occasion AND EXISTS(
    SELECT 1 FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.occasion=v_occasion
      AND pc.change_time=p_change_time AND pc.change_type IN('products.price','products.is_hidden') AND NOT pc.applied)
    ORDER BY p.id FOR UPDATE;
  UPDATE eshop.planned_changes pc SET wave_id=v_wave.id
    WHERE pc.occasion=v_occasion AND pc.change_time=p_change_time AND NOT pc.applied AND pc.wave_id IS NULL
      AND pc.change_type IN('products.price','products.is_hidden') AND EXISTS(
        SELECT 1 FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
        WHERE p.id=pc.subject_id AND p.occasion=v_occasion AND pt.occasion=v_occasion)
      AND (SELECT count(*) FROM eshop.planned_changes other WHERE other.subject_id=pc.subject_id
        AND other.change_type=pc.change_type AND other.change_time=pc.change_time AND NOT other.applied)=1;
  IF p_change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  RETURN to_jsonb(v_wave);
END; $$;


ALTER FUNCTION public.create_product_price_wave(p_occasion_link text, p_change_time timestamp with time zone) OWNER TO postgres;

--
-- Name: create_reception_user_v1(bigint, uuid, jsonb, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_reception_user_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb, p_group_id bigint DEFAULT NULL::bigint, p_accommodation_code text DEFAULT NULL::text, p_confirm_same_name boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_org bigint; v_user uuid; v_hash text; v_existing public.reception_registrations%rowtype;
  v_name text:=btrim(p_profile->>'name'); v_surname text:=btrim(p_profile->>'surname'); v_email text:=lower(btrim(p_profile->>'email'));
  v_sex text:=p_profile->>'sex'; v_matches jsonb; v_services jsonb:='{}'::jsonb; v_catalog jsonb;
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN RETURN jsonb_build_object('code',403,'message','reception_unavailable'); END IF;
  IF NOT public.reception_rate_limit_v1('create') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_profile) k WHERE k NOT IN('name','surname','email','sex','phone','birthDate'))
  THEN RETURN jsonb_build_object('code',400,'message','invalid_profile_fields'); END IF;
  IF COALESCE(v_name,'')='' OR COALESCE(v_surname,'')='' OR COALESCE(v_email,'')='' OR position('@' IN v_email)<=1 OR v_sex NOT IN('male','female','unspecified')
  THEN RETURN jsonb_build_object('code',400,'message','required_profile_fields'); END IF;
  v_hash:=encode(digest(jsonb_build_object('profile',p_profile,'group',p_group_id,'accommodation',p_accommodation_code)::text,'sha256'),'hex');
  SELECT * INTO v_existing FROM public.reception_registrations WHERE occasion=p_occasion AND created_by=v_actor AND command_id=p_command_id;
  IF FOUND THEN
    IF v_existing.request_hash<>v_hash THEN RETURN jsonb_build_object('code',409,'message','command_conflict'); END IF;
    SELECT ui.email_readonly INTO v_email FROM public.user_info ui WHERE ui.id=v_existing."user";
    RETURN jsonb_build_object('code',200,'userId',v_existing."user",'email',v_email,'replayed',true);
  END IF;
  SELECT o.organization,COALESCE(o.services,'{}'::jsonb) INTO v_org,v_catalog FROM public.occasions o WHERE o.id=p_occasion FOR SHARE;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('reception-email:'||v_org::text||':'||v_email,0));
  SELECT ui.id INTO v_user
  FROM public.user_info ui
  WHERE ui.organization=v_org AND lower(btrim(ui.email_readonly))=v_email;
  IF v_user IS NOT NULL THEN
    IF (public.can_manage_occasion_participants(p_occasion))
      AND EXISTS(SELECT 1 FROM public.occasion_users ou
        WHERE ou.occasion=p_occasion AND ou."user"=v_user) THEN
      RETURN jsonb_build_object('code',200,'userId',v_user,'email',v_email,
        'existing',true,'replayed',false);
    END IF;
    RETURN jsonb_build_object('code',409,'message','email_already_exists');
  END IF;
  SELECT COALESCE(jsonb_agg(candidate),'[]'::jsonb) INTO v_matches FROM (
    SELECT jsonb_build_object('name',ui.name,'surname',ui.surname,'sex',ui.sex,
      'birthYear',CASE WHEN ui.birth_date IS NULL THEN NULL ELSE extract(year FROM ui.birth_date)::int END,
      'email',CASE WHEN position('@' IN ui.email_readonly)>2 THEN left(ui.email_readonly,1)||'***@'||split_part(ui.email_readonly,'@',2) ELSE '***' END,
      'onOccasion',EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND ou."user"=ui.id)) candidate
    FROM public.user_info ui WHERE ui.organization=v_org AND public.f_unaccent(btrim(ui.name))=public.f_unaccent(v_name)
      AND public.f_unaccent(btrim(ui.surname))=public.f_unaccent(v_surname) ORDER BY ui.created_at NULLS LAST LIMIT 10) q;
  IF jsonb_array_length(v_matches)>0 AND NOT p_confirm_same_name THEN RETURN jsonb_build_object('code',409,'message','same_name_confirmation_required','candidates',v_matches); END IF;
  IF p_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_group_info g WHERE g.id=p_group_id AND g.occasion=p_occasion AND g.type IS NULL FOR SHARE)
  THEN RETURN jsonb_build_object('code',400,'message','invalid_group'); END IF;
  IF p_accommodation_code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_catalog->'accommodation')='array' THEN v_catalog->'accommodation' ELSE '[]'::jsonb END) x WHERE x->>'code'=p_accommodation_code)
  THEN RETURN jsonb_build_object('code',400,'message','invalid_accommodation'); END IF;
  v_user:=public.create_user_in_organization_with_data_pure(v_org,v_email,v_email,encode(gen_random_bytes(32),'hex'),p_profile-'email');
  IF p_accommodation_code IS NOT NULL THEN v_services:=jsonb_build_object('accommodation',jsonb_build_object(p_accommodation_code,'paid')); END IF;
  PERFORM public.notification_center_prepared_invalidate_user(v_user,p_occasion);
  INSERT INTO public.occasion_users(occasion,"user",data,services) VALUES(p_occasion,v_user,p_profile,v_services);
  IF p_group_id IS NOT NULL THEN INSERT INTO public.user_groups("user","group",is_admin) VALUES(v_user,p_group_id,false); END IF;
  INSERT INTO public.reception_registrations(occasion,"user",created_by,command_id,request_hash) VALUES(p_occasion,v_user,v_actor,p_command_id,v_hash);
  RETURN jsonb_build_object('code',200,'userId',v_user,'email',v_email,'replayed',false);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('code',409,'message','email_or_command_conflict');
END $$;


ALTER FUNCTION public.create_reception_user_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb, p_group_id bigint, p_accommodation_code text, p_confirm_same_name boolean) OWNER TO postgres;

--
-- Name: create_service_item(bigint, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_service_item(oc bigint, type text, code text, title text, reference bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN RETURN public.create_service_item_client_sync_v1(
  oc,type,code,title,reference,extensions.gen_random_uuid())->'data'; END; $$;


ALTER FUNCTION public.create_service_item(oc bigint, type text, code text, title text, reference bigint) OWNER TO postgres;

--
-- Name: create_service_item_client_sync_v1(bigint, text, text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_title text, p_reference bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.can_write_service_items(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.create',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.create_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      400,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.create','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $$;


ALTER FUNCTION public.create_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_title text, p_reference bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: create_service_item_internal_v1(bigint, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_service_item_internal_v1(oc bigint, type text, code text, title text, reference bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  existing_codes JSONB;
  new_service_item JSONB;
BEGIN

  IF (SELECT can_write_service_items(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Check if the code already exists within the specified type
  SELECT jsonb_agg(item)
  INTO existing_codes
  FROM public.occasions,
       jsonb_array_elements(COALESCE(occasions.services->type, '[]'::jsonb)) AS item
  WHERE occasions.id = oc
    AND (item->>'code') = code;

  IF existing_codes IS NOT NULL THEN
    -- If code exists, return an error response
    RETURN jsonb_build_object(
      'code', 400,
      'message', 'Code must be unique within the specified type'
    );
  END IF;

  -- Build the new service item JSON
  new_service_item := jsonb_build_object(
    'code', code,
    'title', title,
    'reference', reference
  );

  -- Update the occasion to add the new item to the specified type array in services.
  -- Guard against `services` being SQL NULL *or* a JSON scalar/`null` (which
  -- COALESCE does not catch and which makes jsonb_set raise
  -- "cannot set path in scalar"). Same guard for the per-type array.
  UPDATE public.occasions
  SET services = jsonb_set(
    CASE WHEN jsonb_typeof(services) = 'object' THEN services ELSE '{}'::jsonb END,
    ARRAY[type],
    CASE WHEN jsonb_typeof(services->type) = 'array' THEN services->type ELSE '[]'::jsonb END || new_service_item,
    true
  )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Service item created successfully'
  );
END;
$$;


ALTER FUNCTION public.create_service_item_internal_v1(oc bigint, type text, code text, title text, reference bigint) OWNER TO postgres;

--
-- Name: create_stripe_order_attempt_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_stripe_order_attempt_internal(p_order bigint) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; pi eshop.payment_info; c eshop.stripe_connections; attempt uuid:=extensions.gen_random_uuid(); stamp timestamptz:=date_trunc('second',clock_timestamp());
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order FOR UPDATE;
 SELECT * INTO STRICT pi FROM eshop.payment_info WHERE id=o.payment_info FOR UPDATE;
 SELECT * INTO STRICT c FROM eshop.stripe_connections WHERE id=pi.stripe_connection_id;
 IF pi.payment_method<>'stripe' OR pi.amount<=0 OR pi.amount<>o.price OR pi.currency_code<>o.currency_code
  OR pi.amount*100<>trunc(pi.amount*100) OR o.state<>'ordered' OR o.form IS NULL OR EXISTS(
   SELECT 1 FROM eshop.stripe_checkout_attempts WHERE order_id=o.id) THEN RAISE EXCEPTION 'STRIPE_ORDER_SNAPSHOT_INVALID'; END IF;
 INSERT INTO eshop.stripe_checkout_attempts(id,order_id,payment_info_id,organization_id,unit_id,connection_id,livemode,
  amount_minor,currency,order_revision,idempotency_key,created_at,reservation_expires_at,return_base_url,checkout_locale)
 VALUES(attempt,o.id,pi.id,c.organization_id,c.unit_id,c.id,c.livemode,
  (pi.amount*100)::bigint,pi.currency_code,1,'festapp:checkout:'||attempt,stamp,stamp+make_interval(secs=>(public.payment_sale_policy_internal()->>'reservationSeconds')::integer),
  (SELECT rtrim(data->>'DEFAULT_URL','/')||'/stripe/return' FROM public.organizations WHERE id=c.organization_id),
  (SELECT CASE WHEN data->>'DEFAULT_LANGUAGE' IN ('cs','en','de','pl','sk') THEN data->>'DEFAULT_LANGUAGE' ELSE 'en' END FROM public.organizations WHERE id=c.organization_id));
 UPDATE eshop.payment_info SET deadline=stamp+make_interval(secs=>(public.payment_sale_policy_internal()->>'reservationSeconds')::integer) WHERE id=pi.id;
 RETURN attempt;
END $$;


ALTER FUNCTION public.create_stripe_order_attempt_internal(p_order bigint) OWNER TO postgres;

--
-- Name: create_ticket_batch_client_sync_v1(bigint, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_ticket_batch_client_sync_v1(p_form bigint, p_title text, p_selection jsonb, p_secret uuid, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f public.forms; o public.occasions; claimed jsonb; selection jsonb; oid bigint; tid bigint; symbol text;
 item jsonb; products jsonb; tickets jsonb:='[]'; currency text; result jsonb; bid uuid; ordinal integer:=0; snap jsonb;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form;
 IF auth.uid() IS NULL OR public.can_write_orders(f.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 IF length(trim(p_title)) NOT BETWEEN 1 AND 200 OR p_title IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='BATCH_TITLE_INVALID'; END IF;
 selection:=public.normalize_ticket_batch_selection_internal(f.id,p_selection);
 claimed:=public.begin_client_mutation_v1(p_command_id,'inventory.ticket_batch.create',f.occasion,auth.uid(),
  encode(extensions.digest(jsonb_build_object('form',f.id,'title',p_title,'selection',selection,'secret',p_secret)::text,'sha256'),'hex'));
 IF claimed->>'disposition'='replay' THEN RETURN claimed->'response'; END IF;
 BEGIN
 PERFORM public.lock_blueprint_scope_internal(ARRAY[f.occasion]);
 PERFORM public.check_blueprint_selection_units_internal(ARRAY(SELECT (t->>'spot')::bigint FROM jsonb_array_elements(selection) t WHERE t->>'spot' IS NOT NULL));
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form FOR UPDATE;
 SELECT * INTO STRICT o FROM public.occasions WHERE id=f.occasion;
 PERFORM public.check_ticket_batch_eligible_internal(f.id);
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('batch-create',o.unit,o.organization),
 jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization),jsonb_build_object('batch-create.items',jsonb_array_length(selection)));
 IF f.participant_capacity IS NOT NULL AND jsonb_array_length(selection)>(public.get_form_capacity_snapshot_internal(f.id)->>'remainingPublic')::bigint THEN
  RAISE EXCEPTION 'FORM_CAPACITY_EXCEEDED'; END IF;
 oid:=public.allocate_ticket_order_identity_internal(f.id);
 PERFORM public.lock_ticket_order_products_internal(oid,jsonb_build_object('ticket',selection));
 PERFORM public.ticket_batch_selection_summary_internal(f.id,selection);
 PERFORM public.hold_ticket_batch_spots_internal(f.id,ARRAY(SELECT (t->>'spot')::bigint FROM jsonb_array_elements(selection) t WHERE t->>'spot' IS NOT NULL ORDER BY (t->>'spot')::bigint),p_secret);
 FOR item IN SELECT value FROM jsonb_array_elements(selection) LOOP
  IF item->>'spot' IS NOT NULL THEN
   PERFORM 1 FROM eshop.spots WHERE id=(item->>'spot')::bigint AND blueprint=f.blueprint AND occasion=f.occasion
    AND secret=p_secret AND secret_expiration_time>clock_timestamp() AND order_product_ticket IS NULL FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'BATCH_SPOT_HOLD_REQUIRED'; END IF;
  END IF;
  symbol:=public.generate_ticket_symbol(o.organization,o.id);
  INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(o.id,'ordered',symbol) RETURNING id INTO tid;
  products:=public.materialize_ticket_products_internal_v1(oid,f.id,tid,item,p_secret);
  IF currency IS NULL THEN currency:=products->>'currency_code';
  ELSIF currency IS DISTINCT FROM products->>'currency_code' THEN RAISE EXCEPTION 'BATCH_CURRENCY_MISMATCH'; END IF;
  tickets:=tickets||jsonb_build_object('id',tid,'ticket_symbol',symbol,'products',products->'products');
 END LOOP;
 PERFORM public.apply_allocations(oid);
 tickets:=public.order_tickets_with_seating_internal(oid,tickets);
 UPDATE eshop.orders SET state='stock',price=NULL,payment_info=NULL,currency_code=currency,data=jsonb_build_object('tickets',tickets),updated_at=clock_timestamp() WHERE id=oid;
 SELECT jsonb_build_object('occasion',to_jsonb(o),'catalog',public.get_products_and_types(o.id)::jsonb,
 'tickets',tickets,'documentData',(SELECT jsonb_agg(jsonb_set(d,'{ticket,price_decimal_digits}',to_jsonb(CASE WHEN (d#>>'{ticket,price}')::numeric=trunc((d#>>'{ticket,price}')::numeric) THEN 0 ELSE 2 END),true) ORDER BY (x->>'id')::bigint)
 FROM jsonb_array_elements(tickets) x CROSS JOIN LATERAL (SELECT public.get_ticket_details_for_generating((x->>'id')::bigint) d) frozen),'renderContractVersion',1) INTO snap;
 INSERT INTO eshop.ticket_batches(occasion,form,stock_order_id,title,created_by,currency_code,snapshot)
 VALUES(o.id,f.id,oid,trim(p_title),auth.uid(),currency,snap) RETURNING id INTO bid;
 INSERT INTO eshop.ticket_batch_items(batch_id,ticket_id,ordinal)
 SELECT bid,(value->>'id')::bigint,n FROM jsonb_array_elements(tickets) WITH ORDINALITY x(value,n);
 UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=f.id;
 INSERT INTO eshop.orders_history("order",state,data,currency_code) VALUES(oid,'stock',jsonb_build_object('batchId',bid),currency);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,o.id,'inventory.ticket_batch.create',
 jsonb_build_array(jsonb_build_object('entityType','order','entityId',oid,'operation','insert','safeLabel','Ticket batch',
 'changedFields',jsonb_build_array('tickets','allocations'))),ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=o.id AND is_editor_order_view),
 jsonb_build_object('batchId',bid,'stockOrderId',oid,'count',jsonb_array_length(selection)));
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM=ANY(ARRAY['FORM_CAPACITY_EXCEEDED','PRODUCT_CAPACITY_EXCEEDED','BATCH_SPOT_UNAVAILABLE','BATCH_SPOT_HOLD_REQUIRED','BATCH_CURRENCY_MISMATCH','BATCH_PRODUCT_UNAVAILABLE','BATCH_ADMISSION_PRODUCT_REQUIRED','CASH_SALE_INVOICE_WORKFLOW_REQUIRED','BATCH_ANONYMOUS_TEMPLATE_REQUIRED','BATCH_PERSONAL_REGISTRATION_UNSUPPORTED']) THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('errorCode',SQLERRM));
  END IF;
  RAISE;
 END;
END $$;


ALTER FUNCTION public.create_ticket_batch_client_sync_v1(p_form bigint, p_title text, p_selection jsonb, p_secret uuid, p_command_id uuid) OWNER TO postgres;

--
-- Name: create_ticket_order(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_ticket_order(input_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF public.payment_reference_scope_enabled_internal((SELECT id FROM public.forms WHERE key=(input_data->>'form')::uuid)) THEN
    RETURN jsonb_build_object('code',409,'errorCode','COMMAND_IDENTITY_REQUIRED'); END IF;
  RETURN public.create_ticket_order_client_sync_v1(input_data,
    extensions.gen_random_uuid(),COALESCE(auth.uid(),extensions.gen_random_uuid()))->'data';
END; $$;


ALTER FUNCTION public.create_ticket_order(input_data jsonb) OWNER TO postgres;

--
-- Name: create_ticket_order_client_sync_v1(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_ticket_order_client_sync_v1(p_order jsonb, p_command_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.create_ticket_order_command_internal(p_order,p_command_id,p_client_id,NULL);
$$;


ALTER FUNCTION public.create_ticket_order_client_sync_v1(p_order jsonb, p_command_id uuid, p_client_id uuid) OWNER TO postgres;

--
-- Name: create_ticket_order_command_internal(jsonb, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_ticket_order_command_internal(p_order jsonb, p_command_id uuid, p_client_id uuid, p_context jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_symbol text; v_before_users uuid[]; v_actor_kind text; v_origin jsonb; v_form bigint;
BEGIN
  IF p_order IS NULL OR jsonb_typeof(p_order)<>'object'
    OR octet_length(p_order::text)>4194304 OR p_command_id IS NULL
    OR (v_actor IS NULL AND p_client_id IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid ticket order command'; END IF;
  SELECT f.occasion INTO v_occasion FROM public.forms f
    WHERE f.key=NULLIF(p_order->>'form','')::uuid;
  IF v_occasion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='ticket order form not found'; END IF;
  v_hash:=encode(extensions.digest(convert_to((jsonb_build_object(
    'occasion',v_occasion,'order',public.strip_payment_sources_internal(p_order))
      ||CASE WHEN p_context IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('administration',p_context) END)::text,'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'inventory.order.create',v_occasion,p_client_id,v_hash);
    v_actor_kind:='unknown';
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,
      'inventory.order.create',v_occasion,v_actor,v_hash);
    v_actor_kind:='user';
  END IF;
  IF v_begin->>'disposition'='replay' THEN
    v_result := v_begin->'response';
    IF v_result#>'{data,order}' IS NOT NULL AND v_result#>>'{data,order,order_symbol}' IS NULL THEN
      v_symbol := public.read_order_identity((v_result#>>'{data,order,id}')::bigint,
        v_occasion, (SELECT organization FROM public.occasions WHERE id=v_occasion));
      IF v_symbol IS NOT NULL THEN
        v_result := jsonb_set(v_result, '{data,order,order_symbol}', to_jsonb(v_symbol));
      END IF;
    END IF;
    IF v_actor IS NULL AND p_context IS NULL THEN
      v_result:=jsonb_set(v_result,'{data,analytics}',coalesce(public.form_conversion_datalayer_internal((v_result#>>'{data,order,id}')::bigint,CASE WHEN (v_result#>>'{data,order,payment_info,amount}')::numeric=0 THEN 'free_registration' ELSE 'purchase' END),'null'::jsonb));
    END IF;
    RETURN public.project_local_payment_reference_order_internal(v_result);
  END IF;
  IF p_order ? 'checkoutOrigin' THEN
    SELECT id INTO v_form FROM public.forms WHERE key=(p_order->>'form')::uuid;
    v_origin:=public.read_checkout_origin_internal(p_order->>'checkoutOrigin',v_form);
    IF v_origin IS NULL THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',400,
        jsonb_build_object('code',400,'errorCode','CHECKOUT_CONTEXT_EXPIRED'));
    END IF;
  END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.create_ticket_order_internal_v1(public.strip_payment_sources_internal(p_order)-'checkoutOrigin');
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,500) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  PERFORM public.attach_checkout_origin_internal((v_result#>>'{order,id}')::bigint,v_origin);
  PERFORM public.attach_provider_order_source_internal((v_result#>>'{order,id}')::bigint,p_command_id,p_order);
  PERFORM public.enqueue_ticket_order_confirmation_v1(
    p_command_id,v_occasion,v_result,p_order->>'lang');
  IF p_context IS NOT NULL THEN v_result:=v_result||jsonb_build_object('adminQuote',p_context->'quote','paymentPreparationPolicy','leased_keep_pending'); END IF;
  v_result:=public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.create',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',v_result#>>'{order,id}','operation','insert',
      'safeLabel','Ticket order','changedFields',jsonb_build_array(
        'tickets','products','allocations','membership'))),v_before_users,v_result,
    v_actor_kind);
  -- The receipt remains frozen; first response and authorized replay project the
  -- same immutable facts, filtered through current stored form policy.
  IF v_actor IS NULL AND p_context IS NULL THEN
    PERFORM public.record_form_conversion_internal((v_result#>>'{data,order,id}')::bigint);
    v_result:=jsonb_set(v_result,'{data,analytics}',coalesce(
      public.form_conversion_datalayer_internal((v_result#>>'{data,order,id}')::bigint,CASE WHEN (v_result#>>'{data,order,payment_info,amount}')::numeric=0 THEN 'free_registration' ELSE 'purchase' END),'null'::jsonb));
  END IF;
  RETURN v_result;
END; $$;


ALTER FUNCTION public.create_ticket_order_command_internal(p_order jsonb, p_command_id uuid, p_client_id uuid, p_context jsonb) OWNER TO postgres;

--
-- Name: create_ticket_order_internal_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_ticket_order_internal_v1(input_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f bigint; target bigint; result jsonb;
BEGIN
 PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM public.forms WHERE key=(input_data->>'form')::uuid)]);
 PERFORM public.check_occasion_writable((SELECT occasion FROM public.forms WHERE key=(input_data->>'form')::uuid));
 BEGIN
  SELECT id INTO f FROM public.forms WHERE key=(input_data->>'form')::uuid FOR UPDATE;
  IF f IS NULL THEN RAISE EXCEPTION 'Form not found'; END IF;
  target:=public.allocate_ticket_order_identity_internal(f);
  result:=public.finalize_ticket_order_internal_v1(target,input_data,false);
  IF coalesce((result->>'code')::integer,500)<>200 THEN RAISE EXCEPTION '%',result::text; END IF;
  PERFORM public.notification_center_order_internal(target,'order_created','created');
  RETURN result;
 EXCEPTION WHEN SQLSTATE 'PT429' THEN
  RETURN jsonb_build_object('code',429,'errorCode','ABUSE_LIMIT_EXCEEDED','message','Capacity is temporarily limited. Try again later.');
 WHEN OTHERS THEN
  RETURN CASE WHEN left(SQLERRM,1)='{' THEN SQLERRM::jsonb ELSE jsonb_build_object('code',1013,'message',SQLERRM) END;
 END;
END $$;


ALTER FUNCTION public.create_ticket_order_internal_v1(input_data jsonb) OWNER TO postgres;

--
-- Name: create_unit_and_assign_manager(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_unit_and_assign_manager(title text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user_id uuid;
  v_org_id bigint;
  v_email text;
  v_new_unit_id bigint;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Unauthorized');
  END IF;

  SELECT organization, email_readonly 
  INTO v_org_id, v_email
  FROM public.user_info 
  WHERE id = v_user_id;

  IF v_org_id IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'User info or organization not found');
  END IF;

  -- Check if unit creation is enabled for organization
  DECLARE
      v_is_enabled boolean;
  BEGIN
      SELECT (data->>'IS_UNIT_CREATION_ENABLED')::boolean 
      INTO v_is_enabled
      FROM public.organizations 
      WHERE id = v_org_id;
      
      IF v_is_enabled IS NOT TRUE THEN
          RETURN jsonb_build_object('code', 403, 'message', 'Unit creation is disabled for this organization');
      END IF;
  END;

  PERFORM public.admit_unit_creation_v1(v_user_id,v_org_id);

  INSERT INTO public.units (title, organization, data)
  VALUES (
    title, 
    v_org_id,
    jsonb_build_object(
        'reply_to', lower(trim(COALESCE(v_email, ''))),
        'timezone', 'Europe/Prague'
    )
  )
  RETURNING id INTO v_new_unit_id;

  INSERT INTO public.unit_users (unit, "user", is_manager, is_editor, is_editor_view)
  VALUES (v_new_unit_id, v_user_id, true, true, true);

  RETURN jsonb_build_object(
    'code', 200, 
    'message', 'Unit created successfully', 
    'data', jsonb_build_object('id', v_new_unit_id)
  );

EXCEPTION WHEN SQLSTATE 'PT429' THEN
  RETURN jsonb_build_object('code',429,'message','Capacity is temporarily limited. Try again later.');
WHEN OTHERS THEN
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.create_unit_and_assign_manager(title text) OWNER TO postgres;

--
-- Name: create_user_for_test(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user_for_test(test_user_alias text, test_email text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_id uuid := gen_random_uuid();
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS _test_user_aliases (alias text PRIMARY KEY, id uuid);
    INSERT INTO auth.users (id, instance_id, email, email_confirmed_at, aud, role, created_at, updated_at)
    VALUES (new_id, '00000000-0000-0000-0000-000000000000', test_email, now(), 'authenticated', 'authenticated', now(), now());
    INSERT INTO public.user_info (id, name, surname, sex) VALUES (new_id, 'Test', 'User', 'male');
    INSERT INTO _test_user_aliases (alias, id) VALUES (test_user_alias, new_id);
END;
$$;


ALTER FUNCTION public.create_user_for_test(test_user_alias text, test_email text) OWNER TO postgres;

--
-- Name: create_user_from_registration(bigint, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user_from_registration(org bigint, email text, password text, data jsonb, unit_title text DEFAULT 'Moje akce'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    is_registration_enabled BOOLEAN;
    new_user_id uuid;
    v_new_unit_id bigint;
BEGIN
    -- Retrieve IS_REGISTRATION_ENABLED value from organizations.data JSON
    SELECT (organizations.data->>'IS_REGISTRATION_ENABLED')::boolean
      INTO is_registration_enabled
    FROM organizations
    WHERE id = org;

    -- Public registration policy is independent of any caller's manager roles.
    IF is_registration_enabled IS DISTINCT FROM true THEN
        RETURN jsonb_build_object('code', 403, 'error', 'Registration is disabled for this organization');
    END IF;

    -- Call the PURE function to create the user
    new_user_id := create_user_in_organization_with_data_pure(org, email, password, data);

    PERFORM public.initialize_registration_unit_v1(new_user_id, org, email, unit_title);

    RETURN jsonb_build_object('code', 200, 'id', new_user_id);
END;
$$;


ALTER FUNCTION public.create_user_from_registration(org bigint, email text, password text, data jsonb, unit_title text) OWNER TO postgres;

--
-- Name: create_user_in_organization_with_data_pure(bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user_in_organization_with_data_pure(org bigint, email text, password text, data jsonb) RETURNS uuid
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT public.create_user_in_organization_with_data_pure(
        org, email, email, password, data
    );
$$;


ALTER FUNCTION public.create_user_in_organization_with_data_pure(org bigint, email text, password text, data jsonb) OWNER TO postgres;

--
-- Name: create_user_in_organization_with_data_pure(bigint, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user_in_organization_with_data_pure(org bigint, email text, email_delivery text, password text, data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    usr uuid;
    encrypted_pw text;
    user_meta_data jsonb := '{}';
    _key   text;
    _value text;
    trimmed_data jsonb := '{}';
    original_email text;
    normalized_delivery_email text;
BEGIN
    original_email := lower(trim(email));
    normalized_delivery_email := COALESCE(
        NULLIF(lower(trim(email_delivery)), ''), original_email
    );

    IF original_email IS NULL OR original_email = ''
       OR normalized_delivery_email IS NULL OR normalized_delivery_email = ''
       OR position('@' IN original_email) <= 1
       OR position('@' IN normalized_delivery_email) <= 1 THEN
        RAISE EXCEPTION 'INVALID_USER_EMAIL';
    END IF;

    -- All application writers serialize identity creation per organization.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('user-sign-in-email:' || org::text, 0)
    );

    IF EXISTS (
        SELECT 1 FROM public.user_info ui
         WHERE ui.organization = org
           AND lower(btrim(ui.email_readonly)) = original_email
    ) THEN
        RAISE EXCEPTION 'SIGN_IN_EMAIL_ALREADY_EXISTS';
    END IF;

    -- Add organization prefix to the email for auth tables
    email := public.format_auth_email(org, original_email);

    -- Trim all values in the data JSONB object and build a new trimmed_data JSONB object
    FOR _key, _value IN
        SELECT key, value FROM jsonb_each_text(data)
    LOOP
        IF _value IS NOT NULL THEN
            trimmed_data := jsonb_set(trimmed_data, array[_key], to_jsonb(trim(_value)), true);
        ELSE
            trimmed_data := jsonb_set(trimmed_data, array[_key], 'null'::jsonb, true);
        END IF;
    END LOOP;

    usr := gen_random_uuid();
    encrypted_pw := crypt(password, gen_salt('bf'));

    -- Insert into auth.users with the email prefixed with organization
    INSERT INTO auth.users
      (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, recovery_sent_at, last_sign_in_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token)
    VALUES
      ('00000000-0000-0000-0000-000000000000', usr, 'authenticated', 'authenticated', email, encrypted_pw, now(), NULL, NULL,
      '{"provider":"email","providers":["email"]}', user_meta_data, now(), now(), '', '', '', '');

    -- Insert into auth.identities with the email prefixed with organization
    INSERT INTO auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES
      (gen_random_uuid(), usr, usr, format('{"sub":"%s","email":"%s"}', usr::text, email)::jsonb, 'email', NULL, now(), now());

    -- The account email is canonical; store only a distinct delivery override.
    INSERT INTO user_info (
      id, email_readonly, email_delivery, name, surname, sex, phone, birth_date, data,
      organization
    )
    VALUES (
      usr,
      original_email,
      NULLIF(normalized_delivery_email, original_email),
      COALESCE(trimmed_data->>'name', ''),
      COALESCE(trimmed_data->>'surname', ''),
      COALESCE(trimmed_data->>'sex', ''),
      trimmed_data->>'phone',
      NULLIF(trimmed_data->>'birthDate', '')::date,
      trimmed_data,
      org
    );

    RETURN usr;
END;
$$;


ALTER FUNCTION public.create_user_in_organization_with_data_pure(org bigint, email text, email_delivery text, password text, data jsonb) OWNER TO postgres;

--
-- Name: create_user_in_organization_with_data_ws(bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user_in_organization_with_data_ws(org bigint, email text, password text, data jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    new_user_id uuid;
BEGIN
    -- Internal helper. The scoped parent (update_user_internal_v1) owns admission.
    -- No client EXECUTE: public registration has its own atomic email owner.
    -- Call the PURE function
    new_user_id := create_user_in_organization_with_data_pure(org, email, password, data);

    -- Return success in JSON format
    RETURN jsonb_build_object('code', 200, 'id', new_user_id);
END;
$$;


ALTER FUNCTION public.create_user_in_organization_with_data_ws(org bigint, email text, password text, data jsonb) OWNER TO postgres;

