--
-- Name: decide_stripe_partial_refund_client_sync_v1(bigint, text, bigint[], text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decide_stripe_partial_refund_client_sync_v1(p_order bigint, p_action text, p_tickets bigint[], p_note text, p_expected_refunded_minor bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid(); o eshop.orders; a eshop.stripe_checkout_attempts; totals record; v_occasion bigint;
 hash text; claim jsonb; ids bigint[]; before_users uuid[]; revision text; decision uuid; card_refunded bigint;
BEGIN
 SELECT ord.occasion INTO v_occasion FROM eshop.orders ord WHERE ord.id=p_order;
 IF actor IS NULL OR v_occasion IS NULL OR NOT coalesce(public.can_write_orders(v_occasion),false)
  OR NOT EXISTS(SELECT 1 FROM public.occasions occasion JOIN public.user_info viewer ON viewer.organization=occasion.organization AND viewer.id=actor WHERE occasion.id=v_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 IF p_action IS NULL OR p_action NOT IN ('keep','cancel_selected') OR p_command_id IS NULL
  OR nullif(trim(p_note),'') IS NULL OR length(trim(p_note)) NOT BETWEEN 3 AND 500
  OR p_expected_refunded_minor IS NULL THEN RAISE EXCEPTION 'STRIPE_REFUND_DECISION_INVALID'; END IF;
 ids:=ARRAY(SELECT DISTINCT id FROM unnest(coalesce(p_tickets,'{}'::bigint[])) id ORDER BY id);
 IF (p_action='keep' AND cardinality(ids)<>0) OR (p_action='cancel_selected' AND cardinality(ids) NOT BETWEEN 1 AND 1000) THEN
  RAISE EXCEPTION 'STRIPE_REFUND_DECISION_INVALID'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('order',p_order,'action',p_action,'tickets',ids,
  'note',trim(p_note),'refundedMinor',p_expected_refunded_minor)::text,'sha256'),'hex');
 claim:=public.begin_client_mutation_v1(p_command_id,'inventory.order.stripe_refund_decision',v_occasion,actor,hash);
 IF claim->>'disposition'='replay' THEN RETURN claim->'response'; END IF;
 PERFORM public.admit_order_mutation_v1(v_occasion,greatest(cardinality(ids),1));
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE order_id=p_order ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 PERFORM 1 FROM eshop.payment_info WHERE id=a.payment_info_id FOR UPDATE;
 SELECT * INTO STRICT totals FROM public.payment_financial_totals_internal(a.payment_info_id);
 SELECT coalesce(sum(amount_minor),0) INTO card_refunded FROM eshop.stripe_payment_movements WHERE attempt_id=a.id AND kind='refund';
 IF card_refunded IS DISTINCT FROM p_expected_refunded_minor THEN RAISE EXCEPTION 'STRIPE_REFUND_REVISION_CHANGED'; END IF;
 IF card_refunded<=0 OR card_refunded>=a.amount_minor OR a.state<>'paid' OR o.state NOT IN ('paid','sent')
  OR totals.invalid_identity OR a.refund_cursor IS NOT NULL OR a.session_lookup_cursor IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=o.payment_info AND id=a.payment_info_id AND payment_method='stripe' AND stripe_connection_id=a.connection_id) THEN
  RAISE EXCEPTION 'STRIPE_PARTIAL_REFUND_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ids) selected(id) WHERE selected.id IS NULL OR NOT EXISTS(
  SELECT 1 FROM public.get_order_tickets_internal(o.id) person JOIN eshop.tickets t ON t.id=person.id
  WHERE t.id=selected.id AND t.state IN ('paid','sent','ordered'))) THEN RAISE EXCEPTION 'STRIPE_REFUND_TICKET_UNAVAILABLE'; END IF;
 PERFORM 1 FROM eshop.tickets WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO before_users FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
 SELECT encode(extensions.digest(coalesce(jsonb_agg(jsonb_build_array(provider_id,amount_minor) ORDER BY provider_id)::text,'[]'),'sha256'),'hex')
 INTO revision FROM eshop.stripe_payment_movements WHERE attempt_id=a.id AND kind='refund';
 claim:=public.apply_provider_payment_effects_internal('stripe',a.id,revision,public.stripe_order_payment_projection_internal(o.id),false,false,p_action,ids);
 decision:=(claim->>'decisionId')::uuid;
 INSERT INTO eshop.orders_history("order",state,price,data) VALUES(o.id,o.state,o.price,jsonb_build_object('action','stripe_partial_refund_decision',
  'decisionId',decision,'actor',actor,'ticketIds',ids,'note',trim(p_note),'providerRevision',revision));
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,v_occasion,'inventory.order.stripe_refund_decision',
  jsonb_build_array(jsonb_build_object('entityType','order','entityId',o.id,'operation','update','safeLabel','Refund admission decision',
   'changedFields',jsonb_build_array('tickets','admission','allocations'))),before_users,
  jsonb_build_object('decisionId',decision,'payment',public.stripe_order_payment_projection_internal(o.id)));
END $$;


ALTER FUNCTION public.decide_stripe_partial_refund_client_sync_v1(p_order bigint, p_action text, p_tickets bigint[], p_note text, p_expected_refunded_minor bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: defer_stripe_recovery_internal(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.defer_stripe_recovery_internal(p_attempt uuid, p_lease uuid, p_retry_seconds integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a eshop.stripe_checkout_attempts; o eshop.orders; before_users uuid[]; before_projection jsonb; result jsonb;
 command uuid:=extensions.gen_random_uuid(); claim jsonb;
BEGIN
 PERFORM public.require_service_role();
 IF p_retry_seconds IS NULL OR p_retry_seconds NOT BETWEEN 1 AND 3600 THEN RAISE EXCEPTION 'STRIPE_RECOVERY_LIMIT_INVALID'; END IF;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE id=p_attempt;
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=a.order_id;
 claim:=public.begin_anonymous_client_mutation_v1(command,'inventory.order.stripe_sync',o.occasion,command,
  encode(extensions.digest(p_attempt::text||p_lease::text,'sha256'),'hex'));
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[a.order_id]);
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=a.order_id FOR UPDATE;
 PERFORM 1 FROM eshop.payment_info WHERE id=o.payment_info FOR UPDATE;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE id=p_attempt FOR UPDATE;
 IF p_lease IS NULL OR a.lease_token IS DISTINCT FROM p_lease OR a.lease_expires_at IS NULL OR a.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'STRIPE_SYNC_LEASE_INVALID'; END IF;

 SELECT coalesce(array_agg("user"),'{}'::uuid[]) INTO before_users FROM public.occasion_users WHERE occasion=o.occasion;
 before_projection:=public.stripe_order_payment_projection_internal(o.id);
 result:=public.apply_provider_payment_effects_internal('stripe',a.id,'unresolved:'||p_lease::text,before_projection,false,true);
 UPDATE eshop.stripe_checkout_attempts SET lease_token=NULL,lease_expires_at=NULL,
  reconcile_failures=least(reconcile_failures+1,1000),next_reconcile_at=clock_timestamp()+make_interval(secs=>greatest(p_retry_seconds,least(3600,30*power(2,least(reconcile_failures,7)))::integer)) WHERE id=a.id;
 PERFORM public.complete_profile_inventory_membership_mutation_v1(command,o.occasion,'inventory.order.stripe_sync',
  CASE WHEN result->'changed'='true'::jsonb THEN jsonb_build_array(jsonb_build_object('entityType','order','entityId',o.id,'operation','update','safeLabel','Payment recovery','changedFields',jsonb_build_array('payment','state','tickets','admission','allocations'))) ELSE '[]'::jsonb END,
  before_users,jsonb_build_object('committed',true,'payment',result->'payment'),'service');
 PERFORM public.notification_center_order_state_internal(o.id);
 PERFORM public.notification_center_order_capacity_internal(o.id);
END $$;


ALTER FUNCTION public.defer_stripe_recovery_internal(p_attempt uuid, p_lease uuid, p_retry_seconds integer) OWNER TO postgres;

--
-- Name: delete_autosave_history(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_autosave_history(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE draft bigint; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.can_write_activity_plan(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_activity_editor_internal_v1(p_occasion_id);
 SELECT id INTO draft FROM public.activity_history WHERE occasion_id=p_occasion_id
  AND user_id=auth.uid() AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
 result:=public.discard_activity_draft_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),draft);
 RETURN jsonb_build_object('code',result->'code','message',result->>'status');
END $$;


ALTER FUNCTION public.delete_autosave_history(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: delete_client_sync_artifact_metadata_v1(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_client_sync_artifact_metadata_v1(p_artifact_url text, p_cutoff timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_deleted integer:=0; v_part integer;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.require_client_sync_artifact_cutoff_v1(p_cutoff);
  IF p_artifact_url IS NULL
     OR p_artifact_url NOT LIKE 'https://assets.festapp.net/client-sync/v1/%'
     OR p_artifact_url LIKE '%?%' OR p_artifact_url LIKE '%#%'
     OR p_artifact_url LIKE '%/../%' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid client-sync artifact URL';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.client_sync_public_heads h
    WHERE h.head_json#>>'{live,url}'=p_artifact_url
       OR EXISTS (SELECT 1 FROM jsonb_each(COALESCE(h.head_json#>'{catalog,components}','{}')) c
                  WHERE c.value->>'url'=p_artifact_url)
  ) OR EXISTS (
    SELECT 1 FROM public.client_sync_release_manifests m
    JOIN public.client_sync_public_heads h
      ON h.scope_type=m.scope_type AND h.scope_id=m.scope_id
    WHERE m.artifact_url=p_artifact_url
      AND (m.release_revision=h.release_revision OR m.release_revision=(
        SELECT max(previous.release_revision)
        FROM public.client_sync_release_manifests previous
        WHERE previous.scope_type=m.scope_type AND previous.scope_id=m.scope_id
          AND previous.release_revision<h.release_revision))
  ) THEN
    RETURN false;
  END IF;
  DELETE FROM public.client_sync_publications p
  WHERE p.artifact_url=p_artifact_url
    AND p.published_at<p_cutoff;
  GET DIAGNOSTICS v_deleted=ROW_COUNT;
  DELETE FROM public.client_sync_release_manifests m
  WHERE m.artifact_url=p_artifact_url
    AND m.published_at<p_cutoff;
  GET DIAGNOSTICS v_part=ROW_COUNT;
  RETURN v_deleted+v_part>0;
END; $$;


ALTER FUNCTION public.delete_client_sync_artifact_metadata_v1(p_artifact_url text, p_cutoff timestamp with time zone) OWNER TO postgres;

--
-- Name: delete_counseling_slot(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_counseling_slot(p_speaker bigint, p_event bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF public.resolve_counseling_slot_delete_occasion_internal_v1(p_speaker, p_event) IS NULL THEN
    RETURN jsonb_build_object('code', 400, 'message', 'counseling slot required');
  END IF;
  RETURN public.delete_event(p_event);
END;
$$;


ALTER FUNCTION public.delete_counseling_slot(p_speaker bigint, p_event bigint) OWNER TO postgres;

--
-- Name: delete_counseling_slot_client_sync_v1(bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_counseling_slot_client_sync_v1(p_speaker bigint, p_event_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion BIGINT;
BEGIN
  v_occasion := public.resolve_counseling_slot_delete_occasion_internal_v1(
    p_speaker, p_event_id);
  IF v_occasion IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'rejected',
      'code', 400,
      'data', jsonb_build_object('eventId', p_event_id, 'deleted', FALSE),
      'mutation', jsonb_build_object(
        'commandId', p_command_id, 'receiptId', p_command_id,
        'commitId', NULL, 'replayed', FALSE, 'occurredAt', clock_timestamp()),
      'sync', jsonb_build_object('replacements', '[]'::jsonb));
  END IF;
  RETURN public.delete_event_client_sync_v1(
    v_occasion, p_event_id, p_command_id, p_expected_version);
END;
$$;


ALTER FUNCTION public.delete_counseling_slot_client_sync_v1(p_speaker bigint, p_event_id bigint, p_command_id uuid, p_expected_version bigint) OWNER TO postgres;

--
-- Name: delete_delegated_order_client_sync_v1(bigint, bigint, bigint, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_delegated_order_client_sync_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid, p_expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 IF p_expected_revision IS NULL OR p_expected_revision !~ '^[a-f0-9]{64}$' THEN RAISE invalid_parameter_value USING MESSAGE='original deletion revision required'; END IF;
 result:=public.get_delegated_order_deletion_context(p_occasion,p_organization,p_unit,p_order,p_command_id,p_expected_revision);
 IF result ? 'response' THEN RETURN result->'response'; END IF;
 RETURN public.delete_order_client_sync_v1(p_order,p_command_id);
END $_$;


ALTER FUNCTION public.delete_delegated_order_client_sync_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid, p_expected_revision text) OWNER TO postgres;

--
-- Name: delete_empty_counseling_slots(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_empty_counseling_slots(p_speaker bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r jsonb;
BEGIN
 IF NOT public.can_write_speakers((SELECT occasion FROM public.speakers WHERE id=p_speaker))
 THEN RETURN jsonb_build_object('code',403); END IF;
 r:=public.delete_empty_counseling_slots_client_sync_v1(p_speaker,p_from,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',r->'code','data',r->'data');
END $$;


ALTER FUNCTION public.delete_empty_counseling_slots(p_speaker bigint, p_from timestamp with time zone) OWNER TO postgres;

--
-- Name: delete_empty_counseling_slots_client_sync_v1(bigint, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_empty_counseling_slots_client_sync_v1(p_speaker bigint, p_from timestamp with time zone, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_ids bigint[]; v_users uuid[]; v_impacts jsonb;
  v_publishable boolean;
BEGIN
  SELECT s.occasion,NOT o.is_hidden INTO v_occasion,v_publishable
    FROM public.speakers s JOIN public.occasions o ON o.id=s.occasion
    WHERE s.id=p_speaker;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.can_write_speakers(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('speaker',p_speaker,
    'from',p_from)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.counseling.delete_empty',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(e.id ORDER BY e.id),'{}'::bigint[]) INTO v_ids
    FROM public.events e JOIN public.event_speakers es ON es.event=e.id
    WHERE es.speaker=p_speaker AND (e.data->>'is_counseling_slot')::boolean IS TRUE
      AND (p_from IS NULL OR e.start_time>=p_from)
      AND NOT EXISTS (SELECT 1 FROM public.event_users eu WHERE eu.event=e.id);
  PERFORM public.lock_event_deletion_scope_internal_v1(v_occasion,v_ids);
  PERFORM 1 FROM public.speakers WHERE id=p_speaker FOR NO KEY UPDATE;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_speaker);
  IF EXISTS(SELECT 1 FROM public.events e JOIN public.event_speakers es ON es.event=e.id
    WHERE es.speaker=p_speaker AND (e.data->>'is_counseling_slot')::boolean IS TRUE
    AND (p_from IS NULL OR e.start_time>=p_from) AND NOT e.id=ANY(v_ids)
    AND NOT EXISTS(SELECT 1 FROM public.event_users WHERE event=e.id)) THEN
    RAISE serialization_failure USING MESSAGE='counseling slots changed; retry the same command'; END IF;
  -- A booking can commit while we wait for the event lock. Keep its metadata.
  v_ids:=ARRAY(SELECT id FROM public.events WHERE id=ANY(v_ids)
    AND NOT EXISTS(SELECT 1 FROM public.event_users WHERE event=events.id) ORDER BY id);
  PERFORM 1 FROM public.event_users_saved eus WHERE eus.event=ANY(v_ids)
    ORDER BY eus.event,eus."user" FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT eus."user"),'{}'::uuid[]) INTO v_users
    FROM public.event_users_saved eus WHERE eus.event=ANY(v_ids);
  v_result:=public.delete_empty_counseling_slots_internal_v1(p_speaker,p_from);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')); END IF;
  IF cardinality(v_ids)=0 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,v_result->'data'); END IF;
  DELETE FROM public.client_aggregate_versions v WHERE v.aggregate_type='event'
    AND v.scope_type='occasion' AND v.scope_id=v_occasion
    AND v.aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(v_ids) id));
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_program',
    'userId',id)),'[]'::jsonb) INTO v_impacts FROM unnest(v_users) id
    JOIN public.occasion_users ou ON ou.occasion=v_occasion AND ou."user"=id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'program.counseling.delete_empty','program',jsonb_build_array(jsonb_build_object(
      'entityType','counseling_slot','entityId',NULL,'operation','delete',
      'safeLabel','Empty counseling slots','changedFields',jsonb_build_array('events'))),
    CASE WHEN v_publishable THEN ARRAY['program_catalog','content_catalog','live_public']
      ELSE '{}'::text[] END,v_impacts,CASE WHEN v_publishable THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object('component','live_public','entityId',id))
      FROM unnest(v_ids) id),'[]'::jsonb) ELSE '[]'::jsonb END,v_result->'data');
END; $$;


ALTER FUNCTION public.delete_empty_counseling_slots_client_sync_v1(p_speaker bigint, p_from timestamp with time zone, p_command_id uuid) OWNER TO postgres;

--
-- Name: delete_empty_counseling_slots_internal_v1(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_empty_counseling_slots_internal_v1(p_speaker bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion BIGINT;
    v_deleted INT;
    v_ids bigint[]; v_effects jsonb;
BEGIN
    SELECT occasion INTO v_occasion
    FROM public.speakers
    WHERE id = p_speaker;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    IF NOT public.can_write_speakers(v_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    SELECT ARRAY(SELECT e.id FROM public.events e JOIN public.event_speakers es ON es.event=e.id
      WHERE es.speaker=p_speaker AND (e.data->>'is_counseling_slot')::boolean IS TRUE
      AND (p_from IS NULL OR e.start_time>=p_from)
      AND NOT EXISTS(SELECT 1 FROM public.event_users WHERE event=e.id) ORDER BY e.id) INTO v_ids;
    v_effects:=public.delete_events_domain_internal_v1(v_occasion,v_ids);
    v_deleted:=(v_effects->>'deleted')::integer;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('deleted', v_deleted)
    );
END;
$$;


ALTER FUNCTION public.delete_empty_counseling_slots_internal_v1(p_speaker bigint, p_from timestamp with time zone) OWNER TO postgres;

--
-- Name: delete_entity_email_template(text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_entity_email_template(p_entity_type text, p_entity_id bigint, p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
    if p_entity_type = 'occasion' then
        if public.can_write_occasion_email_templates(p_entity_id) IS NOT TRUE then
            perform public.raise_error('permission_denied');
        end if;

        PERFORM public.lock_email_template_hierarchy_internal(CASE WHEN p_entity_type='occasion' THEN
          (SELECT jsonb_build_object('occasion',id,'unit',unit,'organization',organization) FROM public.occasions WHERE id=p_entity_id)
          ELSE (SELECT jsonb_build_object('unit',id,'organization',organization) FROM public.units WHERE id=p_entity_id) END);

        delete from public.email_templates
        where occasion = p_entity_id 
          and code = p_code;

    elsif p_entity_type = 'unit' then
        if (public.can_write_unit_email_templates(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        PERFORM public.lock_email_template_hierarchy_internal(CASE WHEN p_entity_type='occasion' THEN
          (SELECT jsonb_build_object('occasion',id,'unit',unit,'organization',organization) FROM public.occasions WHERE id=p_entity_id)
          ELSE (SELECT jsonb_build_object('unit',id,'organization',organization) FROM public.units WHERE id=p_entity_id) END);

        delete from public.email_templates
        where unit = p_entity_id
          and occasion is null
          and code = p_code;
    else
        raise exception 'Invalid entity type: %', p_entity_type;
    end if;
end;
$$;


ALTER FUNCTION public.delete_entity_email_template(p_entity_type text, p_entity_id bigint, p_code text) OWNER TO postgres;

--
-- Name: delete_event(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_event(p_event bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint; ver bigint; r jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.events WHERE id=p_event;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF auth.uid() IS NULL OR NOT public.can_write_schedule(oc) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_event_deletion_scope_internal_v1(oc,ARRAY[p_event]);
 PERFORM 1 FROM public.events WHERE id=p_event AND occasion=oc FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_event::text;
 r:=public.delete_event_client_sync_v1(oc,p_event,extensions.gen_random_uuid(),ver);
 RETURN jsonb_build_object('code',r->'code');
END $$;


ALTER FUNCTION public.delete_event(p_event bigint) OWNER TO postgres;

--
-- Name: delete_event_client_sync_v1(bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_event_client_sync_v1(p_occasion bigint, p_event_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_version bigint; v_event jsonb;
  v_commit jsonb; v_program jsonb; v_response jsonb; v_hash text;
  v_is_publishable boolean; v_users uuid[]; v_private_impacts jsonb;
  v_had_speakers boolean; v_effects jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_schedule(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'eventId',p_event_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.delete',p_occasion,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.lock_event_deletion_scope_internal_v1(p_occasion,ARRAY[p_event_id]);
  PERFORM 1 FROM public.events e WHERE e.id=p_event_id AND e.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('eventId',p_event_id,'deleted',false),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('event','occasion',p_occasion,p_event_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='event' AND scope_type='occasion' AND scope_id=p_occasion
      AND aggregate_id=p_event_id::text FOR UPDATE;
  v_event:=public.get_event_command_data_v1(p_event_id);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    v_response:=jsonb_build_object('status','conflict','code',409,
      'data',jsonb_build_object('version',v_version,'event',v_event),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;
  SELECT ARRAY(SELECT DISTINCT id FROM (
    SELECT eu."user" id FROM public.event_users eu WHERE eu.event=p_event_id
    UNION SELECT eus."user" FROM public.event_users_saved eus
      WHERE eus.event=p_event_id) users ORDER BY id) INTO v_users;
  v_effects:=public.delete_events_domain_internal_v1(p_occasion,ARRAY[p_event_id]);
  v_had_speakers:=(v_effects->>'hadSpeakers')::boolean;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_program',
    'userId',id)),'[]'::jsonb) INTO v_private_impacts
    FROM unnest(COALESCE(v_users,'{}'::uuid[])) id
    JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'event.delete','program',jsonb_build_array(jsonb_build_object(
      'entityType','event','entityId',p_event_id,'operation','delete',
      'safeLabel',left(v_event->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['program_catalog','live_public']||
      CASE WHEN v_had_speakers THEN ARRAY['content_catalog'] ELSE '{}'::text[] END
      ELSE '{}'::text[] END,v_private_impacts,
    CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
      'component','live_public','entityId',p_event_id))||coalesce((SELECT jsonb_agg(jsonb_build_object('component','live_public','entityId',value::bigint)) FROM jsonb_array_elements_text(v_effects->'childIds')),'[]'::jsonb) ELSE '[]'::jsonb END,
    jsonb_build_object('eventId',p_event_id,'deleted',true));
END; $$;


ALTER FUNCTION public.delete_event_client_sync_v1(p_occasion bigint, p_event_id bigint, p_command_id uuid, p_expected_version bigint) OWNER TO postgres;

--
-- Name: delete_event_feedback(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_event_feedback(p_event bigint, p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE p_occasion bigint; r jsonb;
BEGIN
 SELECT occasion INTO p_occasion FROM public.events WHERE id=p_event;
 IF p_occasion IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 r:=public.delete_event_feedback_client_sync_v1(p_occasion,p_event,p_client_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',r->'code','data',jsonb_build_object('deleted',CASE WHEN (r#>>'{data,deleted}')::boolean THEN 1 ELSE 0 END),'message',r#>'{data,message}');
END $$;


ALTER FUNCTION public.delete_event_feedback(p_event bigint, p_client_id uuid) OWNER TO postgres;

--
-- Name: delete_event_feedback_client_sync_v1(bigint, bigint, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_event_feedback_client_sync_v1(p_occasion bigint, p_event bigint, p_client_id uuid, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_client uuid; v_begin jsonb; v_hash text;
  v_before public.event_feedback%ROWTYPE; v_result jsonb;
  v_private_impacts jsonb:='[]'::jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.events e
    WHERE e.id=p_event AND e.occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='feedback event outside occasion'; END IF;
  v_client:=CASE WHEN v_actor IS NULL THEN p_client_id ELSE NULL END;
  IF v_actor IS NULL AND v_client IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='anonymous client id required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'event',p_event,'clientId',v_client)::text,
    'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'feedback.delete',p_occasion,v_client,v_hash);
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,'feedback.delete',
      p_occasion,v_actor,v_hash);
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=p_event FOR UPDATE;
  IF v_actor IS NULL THEN
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user" IS NULL AND f.client_id=v_client
      FOR UPDATE;
  ELSE
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user"=v_actor FOR UPDATE;
  END IF;
  IF v_before.id IS NULL THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('deleted',false)); END IF;
  v_result:=public.delete_event_feedback_internal_v1(p_event,v_client);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,400) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,
      jsonb_build_object('message',v_result->>'message'));
  END IF;
  IF v_actor IS NOT NULL AND EXISTS (SELECT 1 FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_private_impacts:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor));
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor,
      'payload',public.get_private_feedback_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'feedback.delete','feedback',jsonb_build_array(jsonb_build_object(
      'entityType','event_feedback','entityId',v_before.id,'operation','delete',
      'safeLabel','Event feedback','changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('deleted',true),
    '{}','[]',CASE WHEN v_actor IS NULL THEN 'unknown' ELSE 'user' END,NULL,
    v_replacements);
END; $$;


ALTER FUNCTION public.delete_event_feedback_client_sync_v1(p_occasion bigint, p_event bigint, p_client_id uuid, p_command_id uuid) OWNER TO postgres;

--
-- Name: delete_event_feedback_for_edit_client_sync_v1(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_event_feedback_for_edit_client_sync_v1(p_occasion bigint, p_feedback bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_actor uuid := auth.uid();
    v_organization bigint;
    v_begin jsonb;
    v_hash text;
    v_feedback public.event_feedback%ROWTYPE;
    v_private_impacts jsonb := '[]'::jsonb;
    v_replacements jsonb := '[]'::jsonb;
BEGIN
    SELECT o.organization
    INTO v_organization
    FROM public.occasions o
    WHERE o.id = p_occasion;

    IF v_actor IS NULL
       OR v_organization IS NULL
       OR NOT public.can_delete_schedule_feedback(p_occasion) THEN
        RAISE insufficient_privilege
            USING MESSAGE = 'occasion admin required';
    END IF;

    v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
        'occasion', p_occasion,
        'feedback', p_feedback
    )::text, 'UTF8'), 'sha256'), 'hex');
    v_begin := public.begin_client_mutation_v1(
        p_command_id,
        'feedback.admin_delete',
        p_occasion,
        v_actor,
        v_hash
    );
    IF v_begin->>'disposition' = 'replay' THEN
        RETURN v_begin->'response';
    END IF;

    SELECT f.*
    INTO v_feedback
    FROM public.event_feedback f
    WHERE f.id = p_feedback
      AND f.occasion = p_occasion
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN public.complete_client_mutation_outcome_v1(
            p_command_id,
            'unchanged',
            200,
            jsonb_build_object('deleted', false)
        );
    END IF;

    DELETE FROM public.event_feedback
    WHERE id = v_feedback.id;

    IF v_feedback."user" IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.occasion_users ou
        WHERE ou.occasion = p_occasion
          AND ou."user" = v_feedback."user"
    ) THEN
        v_private_impacts := jsonb_build_array(jsonb_build_object(
            'component', 'private_feedback',
            'userId', v_feedback."user"
        ));
        IF v_feedback."user" = v_actor THEN
            v_replacements := jsonb_build_array(jsonb_build_object(
                'component', 'private_feedback',
                'userId', v_actor,
                'payload', public.get_private_feedback_payload_v1(
                    p_occasion,
                    v_actor
                )
            ));
        END IF;
    END IF;

    RETURN public.complete_client_mutation_applied_v1(
        p_command_id,
        p_occasion,
        'feedback.admin_delete',
        'feedback',
        jsonb_build_array(jsonb_build_object(
            'entityType', 'event_feedback',
            'entityId', v_feedback.id,
            'operation', 'delete',
            'safeLabel', 'Event feedback',
            'changedFields', jsonb_build_array('aggregate')
        )),
        '{}'::text[],
        v_private_impacts,
        '[]'::jsonb,
        jsonb_build_object('deleted', true),
        '{}'::text[],
        '[]'::jsonb,
        'user',
        NULL,
        v_replacements
    );
END;
$$;


ALTER FUNCTION public.delete_event_feedback_for_edit_client_sync_v1(p_occasion bigint, p_feedback bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: delete_event_feedback_internal_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_event_feedback_internal_v1(p_event bigint, p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_user UUID := auth.uid();
    v_deleted INTEGER := 0;
BEGIN
    IF v_user IS NULL AND p_client_id IS NULL THEN
        RETURN jsonb_build_object('code', 401, 'message', 'Client id is required for anonymous feedback');
    END IF;

    IF v_user IS NOT NULL THEN
        DELETE FROM public.event_feedback
        WHERE event = p_event
          AND "user" = v_user;
    ELSE
        DELETE FROM public.event_feedback
        WHERE event = p_event
          AND "user" IS NULL
          AND client_id = p_client_id;
    END IF;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('deleted', v_deleted)
    );
END;
$$;


ALTER FUNCTION public.delete_event_feedback_internal_v1(p_event bigint, p_client_id uuid) OWNER TO postgres;

--
-- Name: delete_events_domain_internal_v1(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_events_domain_internal_v1(p_occasion bigint, p_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE children bigint[]; groups bigint[]; had_speakers boolean; deleted integer;
BEGIN
 IF EXISTS(SELECT 1 FROM public.events WHERE id=ANY(p_ids) AND occasion<>p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='event deletion outside occasion'; END IF;
 children:=public.lock_event_deletion_scope_internal_v1(p_occasion,p_ids);
 SELECT ARRAY(SELECT DISTINCT "group" FROM public.exclusive_events WHERE event=ANY(p_ids) ORDER BY "group") INTO groups;
 IF EXISTS(SELECT 1 FROM public.exclusive_groups WHERE id=ANY(groups) AND occasion<>p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='exclusive group outside occasion'; END IF;
 PERFORM 1 FROM public.exclusive_groups WHERE id=ANY(groups) ORDER BY id FOR UPDATE;
 SELECT EXISTS(SELECT 1 FROM public.event_speakers WHERE event=ANY(p_ids)) INTO had_speakers;
 DELETE FROM public.event_users WHERE event=ANY(p_ids);
 DELETE FROM public.event_users_saved WHERE event=ANY(p_ids);
 DELETE FROM public.exclusive_events WHERE event=ANY(p_ids);
 DELETE FROM public.event_roles WHERE event=ANY(p_ids);
 DELETE FROM public.event_groups WHERE event_parent=ANY(p_ids) OR event_child=ANY(p_ids);
 DELETE FROM public.event_speakers WHERE event=ANY(p_ids);
 DELETE FROM public.events WHERE id=ANY(p_ids) AND occasion=p_occasion;
 GET DIAGNOSTICS deleted=ROW_COUNT;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'event','occasion',p_occasion,id::text,1 FROM unnest(children) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'exclusive_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='event' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(p_ids) id));
 RETURN jsonb_build_object('deleted',deleted,'childIds',to_jsonb(children),'exclusiveGroupIds',to_jsonb(groups),'hadSpeakers',had_speakers);
END $$;


ALTER FUNCTION public.delete_events_domain_internal_v1(p_occasion bigint, p_ids bigint[]) OWNER TO postgres;

--
-- Name: delete_exclusive_group_client_sync_v1(bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_exclusive_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'groupId',p_group_id,
    'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'schedule.exclusive_group.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.exclusive_groups g WHERE g.id=p_group_id
    AND g.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'group',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('exclusive_group','occasion',p_occasion,p_group_id::text,0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='exclusive_group' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_group_id::text FOR UPDATE;
  v_entity:=public.get_exclusive_group_command_data_v1(p_group_id);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'group',v_entity)); END IF;
  DELETE FROM public.exclusive_events WHERE "group"=p_group_id;
  DELETE FROM public.exclusive_groups WHERE id=p_group_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='exclusive_group'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'schedule.exclusive_group.delete','schedule_constraints',
    jsonb_build_array(jsonb_build_object('entityType','exclusive_group',
      'entityId',p_group_id,'operation','delete','safeLabel',left(v_entity->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    '{}','[]','[]',jsonb_build_object('version',v_version,'group',NULL));
END; $$;


ALTER FUNCTION public.delete_exclusive_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint) OWNER TO postgres;

