CREATE FUNCTION public.delete_service_item(oc bigint, type text, code text, force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN public.delete_service_item_client_sync_v1(
    oc,type,code,force,extensions.gen_random_uuid());
END; $$;


ALTER FUNCTION public.delete_service_item(oc bigint, type text, code text, force boolean) OWNER TO postgres;

--
-- Name: delete_service_item_client_sync_v1(bigint, text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_force boolean, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_users uuid[];
BEGIN
  IF v_actor IS NULL OR p_force IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR NOT public.can_write_service_items(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,
    'force',p_force)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.delete',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.occasions WHERE id=p_occasion FOR UPDATE;
  PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion ORDER BY "user" FOR UPDATE;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND (
    (p_force AND ou.services->p_type->>p_code IS NOT NULL
      AND ou.services->p_type->>p_code<>'none') OR
    (NOT p_force AND (ou.services->p_type->>p_code IS NULL
      OR ou.services->p_type->>p_code='none')));
  v_result:=public.delete_service_item_internal_v1(
    p_occasion,p_type,p_code,p_force);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),v_result); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,
    'occasion.service.delete',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','delete',
      'safeLabel',p_code,'changedFields',jsonb_build_array('services'))),
    v_users,ARRAY['occasion_config'],'[]',v_result);
END; $$;


ALTER FUNCTION public.delete_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_force boolean, p_command_id uuid) OWNER TO postgres;

--
-- Name: delete_service_item_internal_v1(bigint, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_service_item_internal_v1(oc bigint, type text, code text, force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  in_use BOOLEAN;
BEGIN
  IF (SELECT can_write_service_items(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Check if the code is in use in occasion_users for the same occasion and type
  SELECT EXISTS(
    SELECT 1
    FROM public.occasion_users
    WHERE occasion_users.occasion = oc
      AND (occasion_users.services->type->>code IS NOT NULL AND occasion_users.services->type->>code <> 'none')
  ) INTO in_use;

  -- If the code is in use and force is not true, return an error response
  IF in_use AND NOT force THEN
    RETURN jsonb_build_object(
      'code', 400,
      'message', 'Service item is in use and cannot be deleted without force'
    );
  END IF;

  -- If force is true, remove the same code from any matching occasion_user records
  IF force AND in_use THEN
    UPDATE public.occasion_users
    SET services = jsonb_set(
      services,
      ARRAY[type],
      (services->type) - code
    )
    WHERE occasion_users.occasion = oc
      AND (occasion_users.services->type->>code IS NOT NULL AND occasion_users.services->type->>code <> 'none');
  END IF;

  IF NOT force AND NOT in_use THEN
    UPDATE public.occasion_users
    SET services = jsonb_set(
      services,
      ARRAY[type],
      (services->type) - code
    )
    WHERE occasion_users.occasion = oc
      AND (occasion_users.services->type->>code IS NULL OR occasion_users.services->type->>code = 'none');
  END IF;

  -- Remove the item from the occasions.services->type array
  UPDATE public.occasions
  SET services = jsonb_set(
    services,
    ARRAY[type],
    coalesce((SELECT jsonb_agg(item)
     FROM jsonb_array_elements(services->type) AS item
     WHERE item->>'code' IS DISTINCT FROM code),'[]'::jsonb),
    true
  )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Service item deleted successfully'
  );
END;
$$;


ALTER FUNCTION public.delete_service_item_internal_v1(oc bigint, type text, code text, force boolean) OWNER TO postgres;

--
-- Name: delete_speaker(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_speaker(p_speaker_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint; ver bigint; r jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.speakers WHERE id=p_speaker_id;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF auth.uid() IS NULL OR NOT public.can_write_speakers(oc) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_speaker_event_dependencies_internal_v1(p_speaker_id);
 PERFORM 1 FROM public.speakers WHERE id=p_speaker_id AND occasion=oc FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker'
 AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_speaker_id::text;
 r:=public.delete_speaker_client_sync_v1(oc,p_speaker_id,extensions.gen_random_uuid(),ver);
 RETURN jsonb_build_object('code',r->'code');
END $$;


ALTER FUNCTION public.delete_speaker(p_speaker_id bigint) OWNER TO postgres;

--
-- Name: delete_speaker_client_sync_v1(bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_speaker_client_sync_v1(p_occasion bigint, p_speaker_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_event_ids bigint[];
  v_entity jsonb; v_publishable boolean; v_hidden boolean; v_has_public_events boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_speakers(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'speakerId',p_speaker_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.speaker.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_event_ids:=public.lock_speaker_event_dependencies_internal_v1(p_speaker_id);
  SELECT public.get_speaker_command_data_v1(s.id),s.is_hidden INTO v_entity,v_hidden
    FROM public.speakers s WHERE s.id=p_speaker_id AND s.occasion=p_occasion FOR UPDATE;
  IF v_entity IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
    'unchanged',200,jsonb_build_object('version',0,'speaker',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('speaker','occasion',p_occasion,p_speaker_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='speaker' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_speaker_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'speaker',v_entity)); END IF;
  SELECT EXISTS (SELECT 1 FROM public.event_speakers es JOIN public.events e
    ON e.id=es.event WHERE es.speaker=p_speaker_id AND NOT e.is_hidden)
    INTO v_has_public_events;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'event','occasion',p_occasion,id::text,1 FROM unnest(v_event_ids) id
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  DELETE FROM public.speakers WHERE id=p_speaker_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='speaker'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_speaker_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.speaker.delete','content',jsonb_build_array(jsonb_build_object(
      'entityType','speaker','entityId',p_speaker_id,'operation','delete',
      'safeLabel',left(v_entity->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_publishable THEN CASE WHEN NOT v_hidden THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END||CASE WHEN NOT v_hidden
      AND v_has_public_events THEN ARRAY['program_catalog'] ELSE '{}'::text[] END
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'speaker',NULL));
END; $$;


ALTER FUNCTION public.delete_speaker_client_sync_v1(p_occasion bigint, p_speaker_id bigint, p_command_id uuid, p_expected_version bigint) OWNER TO postgres;

