CREATE FUNCTION public.delete_speaker_topic_client_sync_v1(p_occasion bigint, p_topic_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
