--
-- Name: delete_unit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit(p_unit_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_manager_count integer;
BEGIN
    PERFORM public.check_is_manager_on_unit(p_unit_id);

    IF EXISTS (SELECT 1 FROM public.occasions WHERE unit = p_unit_id) THEN
        RAISE EXCEPTION 'UNIT_HAS_OCCASIONS';
    END IF;

    SELECT count(*)
      INTO v_manager_count
      FROM public.unit_users
     WHERE "user" = auth.uid()
       AND is_manager = true;

    IF v_manager_count <= 1 THEN
        RAISE EXCEPTION 'CANNOT_DELETE_LAST_UNIT';
    END IF;

    -- Preserve notification history without retaining a deleted unit or live intent.
    UPDATE public.email_messages
       SET unit = NULL,
           workflow_state = CASE WHEN workflow_state IN ('pending','retry_wait','blocked','preparing')
                                 THEN 'cancelled' ELSE workflow_state END
     WHERE unit = p_unit_id AND message_kind = 'custom' AND code = 'UNIT_VERIFICATION_REQUEST';

    DELETE FROM public.unit_users WHERE unit = p_unit_id;
    DELETE FROM public.units WHERE id = p_unit_id;
END;
$$;


ALTER FUNCTION public.delete_unit(p_unit_id bigint) OWNER TO postgres;

--
-- Name: delete_unit_client_sync_v1(bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_organization bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE hash text; receipt public.client_mutation_receipts; organization_id bigint; begun jsonb;
BEGIN
 IF auth.uid() IS NULL OR p_command_id IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated command required'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit)::text,'sha256'),'hex');
 SELECT * INTO receipt FROM public.client_mutation_receipts WHERE command_id=p_command_id AND command_name='unit.delete' AND unit=p_unit AND actor_id=auth.uid() AND request_sha256=hash;
 IF FOUND AND receipt.status IN ('completed','expired') THEN
  organization_id:=(receipt.response#>>'{data,organizationId}')::bigint;
  IF (p_organization IS NOT NULL AND p_organization IS DISTINCT FROM organization_id)
   OR NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=auth.uid() AND organization=organization_id)
   OR (EXISTS(SELECT 1 FROM public.units WHERE id=p_unit) AND NOT public.can_manage_unit_configuration(p_unit)) THEN RAISE insufficient_privilege USING MESSAGE='organizer tombstone unavailable'; END IF;
  IF receipt.status='expired' THEN RETURN public.expired_client_mutation_response_v1(receipt); END IF;
  RETURN receipt.response;
 END IF;
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 SELECT organization INTO organization_id FROM public.units WHERE id=p_unit FOR UPDATE;
 IF organization_id IS NULL OR NOT public.can_manage_unit_configuration(p_unit) OR public.is_demo_unit(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.delete',p_unit,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 PERFORM public.delete_unit(p_unit);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.delete','unit',p_unit,'delete',jsonb_build_object('unitId',p_unit,'organizationId',organization_id));
END $$;


ALTER FUNCTION public.delete_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_organization bigint) OWNER TO postgres;

--
-- Name: delete_unit_icon_client_sync_v1(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit_icon_client_sync_v1(p_unit bigint, p_icon_id bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_actor uuid:=auth.uid();  v_icon public.icons%ROWTYPE;
  v_begin jsonb; v_hash text; v_commit jsonb; v_response jsonb;
  v_places bigint; v_paths bigint; v_types bigint; v_refs jsonb;
BEGIN
  PERFORM 1 FROM public.units WHERE id=p_unit;
  IF v_actor IS NULL OR p_unit IS NULL OR NOT public.can_write_unit_icons(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,
    'iconId',p_icon_id)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.icon.delete',p_unit,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT i.* INTO v_icon FROM public.icons i WHERE i.id=p_icon_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('icon',NULL));
  END IF;
  IF v_icon.unit IS NULL OR v_icon.unit IS DISTINCT FROM p_unit THEN
    RAISE insufficient_privilege USING MESSAGE='icon belongs to another unit or is legacy';
  END IF;
  SELECT count(*) INTO v_places FROM public.places p WHERE p.icon=p_icon_id;
  SELECT count(*) INTO v_paths FROM public.path_groups pg WHERE pg.icon=p_icon_id;
  SELECT count(*) INTO v_types FROM public.place_types pt WHERE pt.icon=p_icon_id;
  IF v_places+v_paths+v_types>0 THEN
    v_refs:=jsonb_build_object('places',v_places,'path_groups',v_paths,
      'place_types',v_types);
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'rejected',409,jsonb_build_object('icon',to_jsonb(v_icon),'refs',v_refs));
  END IF;
  DELETE FROM public.icons WHERE id=p_icon_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='icon'
    AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=p_icon_id::text;
  v_response:=public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.icon.delete','icon',p_icon_id,'delete',jsonb_build_object('icon',NULL));
  PERFORM public.fanout_unit_map_catalog_internal_v1((v_response#>>'{mutation,commitId}')::uuid,p_unit);
  RETURN v_response;
END; $$;


ALTER FUNCTION public.delete_unit_icon_client_sync_v1(p_unit bigint, p_icon_id bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: delete_unit_information_client_sync_v1(bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit_information_client_sync_v1(p_unit bigint, p_information_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid(); ver bigint; old_row jsonb; begun jsonb; hash text;
BEGIN
 IF actor IS NULL OR NOT public.can_write_unit_information(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'id',p_information_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.information.delete',p_unit,actor,hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 SELECT to_jsonb(i) INTO old_row FROM public.information i WHERE id=p_information_id AND unit=p_unit AND occasion IS NULL FOR UPDATE;
 IF old_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,'{}'); END IF;
 IF old_row->>'type'='game' OR old_row->>'information_hidden' IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('information','unit',p_unit,p_information_id::text,0) ON CONFLICT DO NOTHING;
 SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=p_information_id::text FOR UPDATE;
 IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver,'information',old_row)); END IF;
 DELETE FROM public.information WHERE id=p_information_id;
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=p_information_id::text;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.information.delete','information',p_information_id,'delete',jsonb_build_object('version',ver,'information',NULL));
END $$;


ALTER FUNCTION public.delete_unit_information_client_sync_v1(p_unit bigint, p_information_id bigint, p_command_id uuid, p_expected_version bigint) OWNER TO postgres;

--
-- Name: delete_unit_user(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit_user(usr uuid, unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_response jsonb;
BEGIN
  v_response:=public.delete_unit_user_client_sync_v1(
    usr,unit_id,extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',(v_response->>'code')::integer)
    ||COALESCE(v_response->'data','{}'::jsonb);
END; $$;


ALTER FUNCTION public.delete_unit_user(usr uuid, unit_id bigint) OWNER TO postgres;

--
-- Name: delete_unit_user_client_sync_v1(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit_user_client_sync_v1(p_user uuid, p_unit bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_commit public.client_commits%ROWTYPE;

BEGIN
  IF v_actor IS NULL OR p_user IS NULL
    OR NOT public.can_manage_unit_users(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
  PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
  IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'profile.unit_access.delete',p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_before;
  v_result:=public.delete_unit_user_internal_v1(p_user,p_unit);
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_after;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('userId',p_user)); END IF;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'profile.unit_access.delete','profile' FROM public.user_info ui
    WHERE ui.id=v_actor RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit_user',p_user::text,'delete','Unit access',
    ARRAY['rights']);
  PERFORM public.publish_unit_user_access_change_internal_v1(v_commit.commit_id,p_unit,p_user);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('userId',p_user),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $$;


ALTER FUNCTION public.delete_unit_user_client_sync_v1(p_user uuid, p_unit bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: delete_unit_user_internal_v1(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_unit_user_internal_v1(usr uuid, unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF NOT public.can_manage_unit_users(unit_id) THEN
      RAISE insufficient_privilege USING MESSAGE='unit manager required';
    END IF;
    DELETE FROM unit_users
    WHERE "user" = usr AND unit = unit_id;

    UPDATE occasion_users
    SET is_editor = false,
        is_manager = false,
        is_editor_view = false
    WHERE "user" = usr
      AND occasion IN (SELECT id FROM occasions WHERE unit = unit_id);

    RETURN jsonb_build_object('code', 200);
END;
$$;


ALTER FUNCTION public.delete_unit_user_internal_v1(usr uuid, unit_id bigint) OWNER TO postgres;

--
-- Name: delete_user_group_client_sync_v1(bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_user_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb; v_users uuid[]; v_place bigint; v_private_place boolean;
  v_private_impacts jsonb; v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
  PERFORM public.lock_people_scope_internal_v1(p_occasion);
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'groupId',p_group_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.group.delete',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.user_group_info g WHERE g.id=p_group_id
    AND g.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'group',NULL)); END IF;
  SELECT public.get_user_group_command_data_v1(g.id),g.place,
    COALESCE(p.is_hidden AND p.type='group',false)
    INTO v_entity,v_place,v_private_place
  FROM public.user_group_info g LEFT JOIN public.places p ON p.id=g.place
  WHERE g.id=p_group_id;
  SELECT COALESCE(array_agg(ug."user" ORDER BY ug."user"),'{}'::uuid[])
    INTO v_users FROM public.user_groups ug WHERE ug."group"=p_group_id;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('user_group','occasion',p_occasion,p_group_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='user_group' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_group_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'group',v_entity)); END IF;
  IF v_private_place THEN PERFORM public.assert_group_place_owner_internal_v1(p_occasion,p_group_id,v_place,true); END IF;
  DELETE FROM public.user_groups WHERE "group"=p_group_id;
  DELETE FROM public.user_group_info WHERE id=p_group_id;
  IF v_private_place THEN
    DELETE FROM public.places WHERE id=v_place;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type='place'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_place::text;
  END IF;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='user_group'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group_id::text;
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,v_users);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.group.delete','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',p_group_id,'operation','delete',
      'safeLabel',left(v_entity->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('version',v_version,'group',NULL),
    '{}','[]','user',NULL,v_actor_replacements);
END; $$;


ALTER FUNCTION public.delete_user_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint) OWNER TO postgres;

--
-- Name: demo_entity_is_protected(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.demo_entity_is_protected(p_kind text, p_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT CASE p_kind
 WHEN 'occasion' THEN public.is_demo_occasion(p_id)
 WHEN 'bank' THEN public.is_demo_bank_account(p_id)
 WHEN 'order' THEN EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'ticket' THEN EXISTS(SELECT 1 FROM eshop.tickets WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'form' THEN EXISTS(SELECT 1 FROM public.forms WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'event' THEN EXISTS(SELECT 1 FROM public.events WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'pool' THEN EXISTS(SELECT 1 FROM public.inventory_pools WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'context' THEN EXISTS(SELECT 1 FROM public.inventory_contexts c JOIN public.inventory_pools p ON p.id=c.inventory_pool
   WHERE c.id=p_id AND public.is_demo_occasion(p.occasion))
 WHEN 'resource' THEN EXISTS(SELECT 1 FROM public.resources WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'product' THEN EXISTS(SELECT 1 FROM eshop.products WHERE id=p_id AND public.is_demo_occasion(occasion))
 WHEN 'payment' THEN EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=p_id AND public.is_demo_bank_account(bank_account))
 ELSE false END;
$$;


ALTER FUNCTION public.demo_entity_is_protected(p_kind text, p_id bigint) OWNER TO postgres;

