--
-- Name: export_wix_service_fee_receipts(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.export_wix_service_fee_receipts(p_organization bigint, p_partner_terms text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 IF p_partner_terms IS NULL OR length(btrim(p_partner_terms))=0 THEN RAISE invalid_parameter_value USING MESSAGE='PARTNER_TERMS_REQUIRED'; END IF;
 RETURN jsonb_build_object('schemaVersion',2,'receipts',(SELECT coalesce(jsonb_agg(jsonb_build_object(
  'id',a.id,'kind',s.kind,'sourceReference',s.source_reference,
  'productName','Ticketing service fee','instanceId',a.instance_id,'instanceVerificationReference',a.instance_verification_reference,
  'occurredAt',to_char(s.settled_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'currency',s.currency,'amountBasis','settled-service-fee-excluding-tax','feeMinor',a.fee_minor::text,
  'refundSequence',a.refund_sequence::text,'agreedExpensesMinor',a.agreed_expenses_minor::text,'expenseApprovalReference',a.expense_approval_reference,
  'organizerAgreementReference',g.source_reference,'organizerFeeRateBps',g.fee_rate_bps,
  'customerOrigin',c.channel,'customerOriginEvidenceReference',c.evidence_reference,
  'fx',a.fx,'wixShareBps',a.wix_share_bps,'chargeReceiptId',a.original_allocation_id
 ) ORDER BY s.settled_at,a.id),'[]'::jsonb)
 FROM public.service_fee_allocations a JOIN public.service_fee_settlements s ON s.id=a.settlement_id
 JOIN public.service_fee_agreements g ON g.id=s.agreement_id JOIN public.units u ON u.id=g.unit_id
 JOIN public.service_fee_customer_acquisitions c ON c.unit_id=u.id
 LEFT JOIN public.service_fee_allocations original ON original.id=a.original_allocation_id

 WHERE g.organization_id=p_organization AND c.channel='wix' AND c.acquired_at<=a.order_created_at
  AND a.instance_id IS NOT NULL AND coalesce(original.partner_terms_reference,a.partner_terms_reference)=p_partner_terms));
END $$;


ALTER FUNCTION public.export_wix_service_fee_receipts(p_organization bigint, p_partner_terms text) OWNER TO postgres;

--
-- Name: extract_history_product_ids(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.extract_history_product_ids(history_data jsonb) RETURNS integer[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(
    -- Aggregate distinct product IDs into an array, sorting them for consistency
    ARRAY_AGG(DISTINCT (p->>'id')::int ORDER BY (p->>'id')::int),
    -- If aggregation results in NULL (i.e., no products found), return an empty integer array
    '{}'::int[]
  )
  FROM jsonb_array_elements(history_data->'tickets') AS t,
       jsonb_array_elements(t->'products') AS p;
$$;


ALTER FUNCTION public.extract_history_product_ids(history_data jsonb) OWNER TO postgres;

--
-- Name: extract_history_products_with_price(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.extract_history_products_with_price(history_data jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(
    -- Step 2: Aggregate the distinct product objects into a single JSONB array,
    -- ordering them by the 'id' field cast to an integer.
    jsonb_agg(p.product_object ORDER BY (p.product_object->>'id')::int),

    -- If the aggregation is null (no products found), return an empty array.
    '[]'::jsonb
  )
  FROM (
    -- Step 1: Create a derived table (subquery) of distinct product objects.
    -- This subquery unnests the tickets and products, builds the desired
    -- {'id': ..., 'price': ...} object, and returns only the unique ones.
    SELECT DISTINCT
      jsonb_build_object('id', product->>'id', 'price', product->>'price') AS product_object
    FROM
      jsonb_array_elements(history_data->'tickets') AS ticket,
      jsonb_array_elements(ticket->'products') AS product
  ) AS p;
$$;


ALTER FUNCTION public.extract_history_products_with_price(history_data jsonb) OWNER TO postgres;

--
-- Name: extract_ticket_answers_internal(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.extract_ticket_answers_internal(p_form bigint, p_ticket jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object('fields',coalesce(jsonb_agg(jsonb_build_object(answer.key,answer.value)
   ORDER BY definition."order" NULLS LAST,definition.id),'[]'))
 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_ticket->'fields')='array' THEN p_ticket->'fields' ELSE '[]' END) field
 CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(field)='object' THEN field ELSE '{}' END) answer
 JOIN public.form_fields definition ON definition.id::text=answer.key
 WHERE definition.form=p_form AND definition.is_ticket_field AND NOT definition.is_hidden
  AND definition.type NOT IN ('product_type','spot','ticket','html');
$$;


ALTER FUNCTION public.extract_ticket_answers_internal(p_form bigint, p_ticket jsonb) OWNER TO postgres;

--
-- Name: f_html_snippet(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.f_html_snippet(p_html text, p_limit integer DEFAULT 160) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
    WITH cleaned AS (
        SELECT btrim(
                 regexp_replace(
                   regexp_replace(
                     regexp_replace(coalesce(p_html, ''), '<[^>]*>', ' ', 'g'),
                     '<[^>]*$', '', 'g'
                   ),
                   '\s+', ' ', 'g'
                 )
               ) AS t
    )
    SELECT CASE
             WHEN length(t) <= p_limit THEN t
             ELSE btrim(regexp_replace(LEFT(t, p_limit), '\s\S*$', '')) || '…'
           END
    FROM cleaned;
$_$;


ALTER FUNCTION public.f_html_snippet(p_html text, p_limit integer) OWNER TO postgres;

