--
-- Name: fail_stripe_connection_status_internal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_stripe_connection_status_internal(p_connection uuid, p_lease uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 UPDATE eshop.stripe_connections SET status_failures=least(status_failures+1,1000),status_lease=NULL,status_lease_expires_at=NULL,
  next_check_at=clock_timestamp()+make_interval(secs=>least(3600,30*power(2,least(status_failures,7)))::integer)
 WHERE id=p_connection AND status_lease=p_lease AND p_lease IS NOT NULL;
END $$;


ALTER FUNCTION public.fail_stripe_connection_status_internal(p_connection uuid, p_lease uuid) OWNER TO postgres;

--
-- Name: fail_stripe_reconciliation_internal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_stripe_reconciliation_internal(p_attempt uuid, p_lease uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 -- A stale worker cannot clear another worker's lease or reset its cursor.
 UPDATE eshop.stripe_checkout_attempts SET reconcile_failures=least(reconcile_failures+1,1000),
  next_reconcile_at=clock_timestamp()+make_interval(secs=>least(3600,30*power(2,least(reconcile_failures,7)))::integer),
  lease_token=NULL,lease_expires_at=NULL WHERE id=p_attempt AND lease_token=p_lease AND p_lease IS NOT NULL;
END $$;


ALTER FUNCTION public.fail_stripe_reconciliation_internal(p_attempt uuid, p_lease uuid) OWNER TO postgres;

