--
-- Name: form_order_input_internal(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.form_order_input_internal(p_form bigint, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>1048576
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input) k WHERE k NOT IN ('email','fields','ticket','lang','form','payment_method','client_capabilities'))
  OR jsonb_typeof(p_input->'ticket') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'ticket') NOT BETWEEN 1 AND 1000
  OR nullif(p_input->>'email','') IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invalid administrative order'; END IF;
 IF p_input ? 'form' AND p_input->>'form' IS DISTINCT FROM (SELECT key::text FROM public.forms WHERE id=p_form) THEN
  RAISE insufficient_privilege USING MESSAGE='foreign order form key'; END IF;
 IF p_input ? 'payment_method' AND public.payment_method_is_online_internal(p_input->>'payment_method') THEN
  RAISE invalid_parameter_value USING MESSAGE='administrative card payment unsupported'; END IF;
 RETURN p_input||jsonb_build_object('form',(SELECT key FROM public.forms WHERE id=p_form),'client_capabilities','["cash_reservations","no_payment_deadline"]'::jsonb);
END $$;


ALTER FUNCTION public.form_order_input_internal(p_form bigint, p_input jsonb) OWNER TO postgres;

--
-- Name: form_order_quote_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.form_order_quote_internal(p_order bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object('newOrder',jsonb_build_object('amount',o.price::text,'currencyCode',o.currency_code,
  'state',o.state,'paymentMethod',p.payment_method,'paymentPolicy',p.data->'payment_policy','bankAccountId',p.bank_account,
  'bankAccountNumber',ba.account_number,'bankAccountDisplay',ba.account_number_human_readable,
  'ticketCount',(SELECT count(DISTINCT ticket) FROM eshop.order_product_ticket WHERE "order"=o.id)))
 FROM eshop.orders o LEFT JOIN eshop.payment_info p ON p.id=o.payment_info LEFT JOIN eshop.bank_accounts ba ON ba.id=p.bank_account WHERE o.id=p_order;
$$;


ALTER FUNCTION public.form_order_quote_internal(p_order bigint) OWNER TO postgres;

--
-- Name: form_payment_availability_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.form_payment_availability_internal(p_form bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r record; current jsonb; providers jsonb:='{}'; available jsonb:='[]'; config jsonb; bank boolean; cash boolean; configured boolean; enabled boolean;
BEGIN
 SELECT data->'payments' INTO config FROM public.forms WHERE id=p_form;
 bank:=FOUND AND coalesce(config->'bankEnabled','true'::jsonb)='true'::jsonb;
 cash:=config->'cashEnabled'='true'::jsonb;
 bank:=bank AND EXISTS(SELECT 1 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
   JOIN eshop.unit_bank_accounts link ON link.unit=o.unit JOIN eshop.bank_accounts b ON b.id=link.bank_account
   WHERE f.id=p_form AND (f.bank_account IS NULL OR f.bank_account=b.id) AND b.type IS DISTINCT FROM 'CASH'
   AND NOT EXISTS(SELECT 1 FROM public.form_fields ff JOIN eshop.products p ON p.product_type=ff.product_type
    WHERE ff.form=f.id AND NOT coalesce(ff.is_hidden,false) AND NOT coalesce(p.is_hidden,false)
    AND p.price>0 AND NOT coalesce(b.supported_currencies,'{}'::text[]) @> ARRAY[trim(p.currency_code)]));
 IF bank THEN available:=jsonb_build_array('bank'); END IF;
 IF cash THEN available:=jsonb_build_array('cash'); END IF;
 FOR r IN SELECT provider_key,legacy_connection_field FROM eshop.payment_providers WHERE handler IS NOT NULL ORDER BY provider_key LOOP
  configured:=nullif(config#>>ARRAY['providerConnections',r.provider_key],'') IS NOT NULL OR nullif(config->>r.legacy_connection_field,'') IS NOT NULL;
  BEGIN
   PERFORM public.payment_provider_connection_internal(config,r.provider_key);
   current:=public.payment_provider_call_internal(r.provider_key,'form_availability',jsonb_build_object('formId',p_form));
   IF jsonb_typeof(current) IS DISTINCT FROM 'object' OR current->>'providerId' IS DISTINCT FROM r.provider_key
    OR jsonb_typeof(current->'available') IS DISTINCT FROM 'boolean' OR jsonb_typeof(current->'configured') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(current->'supportedSurfaces') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PAYMENT_PROVIDER_PROJECTION_INVALID'; END IF;
   enabled:=configured AND current->'available'='true'::jsonb AND current->'configured'='true'::jsonb;
   current:=current||jsonb_build_object('available',enabled,'configured',configured,'policy',public.payment_sale_policy_internal());
  EXCEPTION WHEN OTHERS THEN
   current:=jsonb_build_object('providerId',r.provider_key,'configured',configured,'available',false,
    'reason',jsonb_build_object('code',CASE WHEN configured THEN 'provider_unavailable' ELSE 'not_configured' END),
    'supportedSurfaces','[]'::jsonb,'recipient',NULL,'policy',public.payment_sale_policy_internal());
   enabled:=false;
  END;
  providers:=providers||jsonb_build_object(r.provider_key,current);
  IF enabled THEN available:=available||jsonb_build_array(r.provider_key); END IF;
 END LOOP;
 -- Only this Stripe compatibility boundary projects released mobile root fields.
 RETURN jsonb_build_object('cash',jsonb_build_object('configured',coalesce(cash,false),'available',coalesce(cash,false),'instructions',config->>'cashInstructions'), 'deadlinePolicy',public.resolve_form_payment_policy_internal(p_form,CASE WHEN cash THEN 'cash' ELSE 'bank' END), 'bank',jsonb_build_object('configured',bank,'available',bank),'available',available,'providers',providers,
  'policy',public.payment_sale_policy_internal(),'reservationSeconds',public.payment_sale_policy_internal()->'reservationSeconds',
  'configured',jsonb_build_object('bank',bank,'stripe',coalesce(providers#>'{stripe,configured}','false')),
  'stripeUnavailableReason',providers#>'{stripe,reason,code}','recipient',providers#>'{stripe,recipient}',
  'supportedSurfaces',coalesce(providers#>'{stripe,supportedSurfaces}','[]'));
END $$;


ALTER FUNCTION public.form_payment_availability_internal(p_form bigint) OWNER TO postgres;

--
-- Name: form_settings_from_metadata_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.form_settings_from_metadata_internal(p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb:='{}'; d jsonb:=public.normalize_form_metadata_internal(p_data); spec record; k text; section jsonb;
BEGIN
 FOR spec IN SELECT * FROM jsonb_each(public.form_settings_keys_internal()) LOOP
  IF spec.key IN ('payments','sale_opening_notifications','analytics') AND NOT d ? spec.key THEN CONTINUE; END IF;
  IF spec.value='null'::jsonb OR NOT d ? spec.key OR d->spec.key='null'::jsonb THEN
   result:=result||jsonb_build_object(spec.key,coalesce(d->spec.key,'null'::jsonb));
  ELSE
   IF spec.key='payments' THEN result:=result||jsonb_build_object(spec.key,d->spec.key); CONTINUE; END IF;
   IF jsonb_typeof(d->spec.key)<>'object' THEN RAISE invalid_parameter_value USING MESSAGE='invalid form settings section: '||spec.key; END IF;
   section:='{}';
   FOR k IN SELECT jsonb_array_elements_text(spec.value) LOOP
    IF spec.key<>'analytics' OR (d->spec.key) ? k THEN
     section:=section||jsonb_build_object(k,coalesce(d->spec.key->k,'null'::jsonb));
    END IF;
   END LOOP;
   result:=result||jsonb_build_object(spec.key,section);
  END IF;
 END LOOP;
 RETURN result;
END $$;


ALTER FUNCTION public.form_settings_from_metadata_internal(p_data jsonb) OWNER TO postgres;

--
-- Name: form_settings_keys_internal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.form_settings_keys_internal() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT '{"is_reminder_enabled":null,"reminder_interval_seconds":null,"communication_tone":null,
 "variable_symbol":["type","starting_number"],"payment_message":["type"],
 "payments":["bankEnabled","stripeConnectionId","providerConnections","cashEnabled","cashInstructions"],
 "payment_deadline":["mode"],
 "analytics":["enabled"],
 "design":["embed_inherit_style","is_card_design","primary_color","secondary_color","background_mode","theme_mode","font_family","countdown_style","presale_header"],
 "sale_opening_notifications":["enabled","collection_paused"],
 "schedule":["start_time","end_time","enable_countdown","countdown_title"]}'::jsonb;
$$;


ALTER FUNCTION public.form_settings_keys_internal() OWNER TO postgres;

--
-- Name: format_auth_email(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.format_auth_email(p_organization bigint, p_sign_in_email text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_email text := lower(btrim(p_sign_in_email)); v_result text;
BEGIN
  IF p_organization IS NULL OR p_organization <= 0 OR v_email IS NULL
     OR v_email = '' OR position('@' IN v_email) <= 1 THEN
    RAISE EXCEPTION 'INVALID_USER_EMAIL';
  END IF;
  v_result := p_organization::text || '+' || v_email;
  IF octet_length(v_result) > 254 THEN RAISE EXCEPTION 'INVALID_USER_EMAIL'; END IF;
  RETURN v_result;
END $$;


ALTER FUNCTION public.format_auth_email(p_organization bigint, p_sign_in_email text) OWNER TO postgres;

--
-- Name: format_occasion_report_text(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.format_occasion_report_text(report jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result text; item jsonb; section text;
BEGIN
  result := (report->'occasion'->>'title') || E'\n' || (report->>'generated_at') || E'\n';
  FOREACH section IN ARRAY ARRAY['orders','tickets'] LOOP
    result := result || CASE section WHEN 'orders' THEN 'Počet objednávek celkem: ' ELSE 'Počet vstupenek celkem: ' END || (report->section->>'total') || E'\n';
    FOR item IN SELECT value FROM jsonb_array_elements(report->section->'by_state') LOOP
      result := result || '  ' || (item->>'state') || ': ' || (item->>'count') || E'\n';
    END LOOP;
  END LOOP;
  result := result || 'Místa (obsazená / celkem): ' || (report->'spots'->>'occupied') || ' / ' || (report->'spots'->>'total') || E'\n';
  IF coalesce((report#>>'{ticket_batches,total}')::bigint,0)>0 THEN
    result:=result||'Předgenerované - neprodáno: '||(report#>>'{ticket_batches,available}')||E'\n'
      ||'Předgenerované - prodáno: '||(report#>>'{ticket_batches,sold_active}')||E'\n'
      ||'Předgenerované - zneplatněno: '||(report#>>'{ticket_batches,voided_unsold}')||E'\n';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(report->'money_by_currency') LOOP
    result := result || E'\n' || (item->>'currency') || E'\n'
      || 'Aktuální hodnota objednávek: ' || (item->>'current_order_value') || E'\n'
      || 'Přijato: ' || (item->>'received') || E'\n'
      || 'Vráceno: ' || (item->>'returned') || E'\n'
      || 'Čistý příjem: ' || (item->>'net_received') || E'\n'
      || 'Ručně evidováno: ' || (item->>'manual_received') || E'\n'
      || 'Ostatní příjmy: ' || (item->>'other_received') || E'\n';
    IF item ? 'stripe_received' THEN
      result:=result||'Z toho přijato platební bránou: '||(item->>'stripe_received')||E'\n'
       ||'Z toho vráceno platební bránou: '||(item->>'stripe_refunded')||E'\n'
       ||'Částka ve sporu (není vratka): '||(item->>'disputed')||E'\n'
       ||'Dostupné po odečtení sporů: '||(item->>'available_after_disputes')||E'\n';
    END IF;
    IF item ? 'external_unattributed' THEN
      result:=result||'Externí částka bez doloženého přiřazení: '||(item->>'external_unattributed')||E'\n';
    END IF;
    IF (item->>'has_deposits')::boolean THEN
      result := result || 'Přijaté zálohy (hrubé): ' || (item->>'deposit_received_gross') || E'\n'
        || 'Přijato nad zálohu (hrubé): ' || (item->>'beyond_deposit_received_gross') || E'\n';
    END IF;
  END LOOP;
  IF report ? 'timeline' THEN
    result := result || E'\nNové objednávky po dnech (Europe/Prague, včetně později stornovaných):\n';
    FOR item IN SELECT value FROM jsonb_array_elements(report->'timeline'->'orders') LOOP
      result := result || (item->>'day') || ' ' || (item->>'currency') || ': ' || (item->>'count') || E'\n';
    END LOOP;
    result := result || E'\nZaevidované platby po dnech (datum bankovní transakce nebo čas pohybu Stripe v Europe/Prague; včetně částečných plateb):\n';
    FOR item IN SELECT value FROM jsonb_array_elements(report->'timeline'->'payments') LOOP
      result := result || (item->>'day') || ' ' || (item->>'currency') || ': přijato ' || (item->>'received') || ', vráceno ' || (item->>'returned') || E'\n';
    END LOOP;
  END IF;
  result := result || E'\nProdukty v potvrzených objednávkách (paid/sent/used, včetně záloh):\n';
  FOR item IN SELECT value FROM jsonb_array_elements(report->'products') LOOP
    result := result || coalesce(item->>'type_title','Bez typu') || ' / ' || (item->>'product_title') || ': ' || (item->>'confirmed_count') || E'\n';
  END LOOP;
  result := result || E'\nSouhrn stavů odpovídá aktuálnímu stavu, nikoli historickým přechodům. Denní platby obsahují pouze zaevidované transakce. Stav paid může znamenat jen uhrazenou zálohu.\nMísta nezahrnují dočasné blokace. Ruční příjmy nejsou nutně hotovost; ostatní nejsou nutně banka.\nZálohy jsou hrubé platby před vratkami, pouze u plateb se zálohou.\n';
  FOR item IN SELECT value FROM jsonb_array_elements(report->'warnings') LOOP
    result := result || 'Upozornění: ' || (item->>'code') || ' (' || (item->>'count') || E')\n';
  END LOOP;
  RETURN result;
END;
$$;


ALTER FUNCTION public.format_occasion_report_text(report jsonb) OWNER TO postgres;

--
-- Name: game_get_correctly_guessed_checkpoints(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.game_get_correctly_guessed_checkpoints(oc bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    user_group_data JSONB;
BEGIN
    -- Retrieve the `data` field for the user's first group where `type = 'game'` and matches the given occasion
    SELECT data
    INTO user_group_data
    FROM user_group_info ug
    JOIN user_groups ug_rel ON ug.id = ug_rel.group
    WHERE ug_rel.user = auth.uid()
      AND ug.type = 'game'
      AND ug.occasion = oc
    LIMIT 1;

    -- Extract each checkpoint as a JSON object with key "check_point" from the "game" array
    RETURN jsonb_build_object(
        'code', 200,
        'data', COALESCE(
            (SELECT jsonb_agg(jsonb_build_object('check_point', (game_entry->>'check_point')::INT))
             FROM jsonb_array_elements(user_group_data->'game') AS game_entry),
            '[]'::JSONB
        )
    );
END;
$$;


ALTER FUNCTION public.game_get_correctly_guessed_checkpoints(oc bigint) OWNER TO postgres;

--
-- Name: game_guess(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.game_guess(check_point_id bigint, guess text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=public.game_guess_client_sync_v1(check_point_id,guess,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code')||result->'data';
END $$;


ALTER FUNCTION public.game_guess(check_point_id bigint, guess text) OWNER TO postgres;

--
-- Name: game_guess_client_sync_v1(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.game_guess_client_sync_v1(p_checkpoint bigint, p_guess text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_group bigint;
  v_begin jsonb; v_hash text; v_result jsonb; v_before jsonb; v_after jsonb;
  v_version bigint; v_impacts jsonb; v_replacements jsonb;
  v_domain_code integer;
BEGIN
  SELECT ih.occasion INTO v_occasion FROM public.information i
    JOIN public.information_hidden ih ON ih.id=i.information_hidden
    WHERE i.id=p_checkpoint;
  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='occasion participant required'; END IF;
  SELECT ug."group" INTO v_group FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    WHERE ug."user"=v_actor AND g.occasion=v_occasion AND g.type='game'
    ORDER BY g.id LIMIT 1;
  IF v_group IS NULL THEN RAISE insufficient_privilege USING MESSAGE='game group required'; END IF;
  IF p_guess IS NULL OR length(p_guess)>2000 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid game guess'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'checkpoint',p_checkpoint,'guess',p_guess)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.game.guess',
    v_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(v_occasion);
  IF NOT EXISTS(SELECT 1 FROM public.user_groups WHERE "group"=v_group AND "user"=v_actor) THEN RAISE insufficient_privilege USING MESSAGE='game group required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.user_groups WHERE "group"=v_group AND "user"=v_actor) THEN RAISE insufficient_privilege USING MESSAGE='game group required'; END IF;
  SELECT g.data INTO v_before FROM public.user_group_info g WHERE g.id=v_group FOR UPDATE;
  v_result:=public.game_guess_internal_v1(p_checkpoint,p_guess);
  v_domain_code:=COALESCE((v_result->>'code')::integer,500);
  IF v_domain_code<>200 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',CASE WHEN v_domain_code BETWEEN 4030 AND 4039 THEN 403
      WHEN v_domain_code BETWEEN 4040 AND 4049 THEN 404 ELSE 400 END,
    jsonb_build_object('domainCode',v_domain_code,'message',v_result->>'message'));
  END IF;
  SELECT g.data INTO v_after FROM public.user_group_info g WHERE g.id=v_group;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('user_group','occasion',v_occasion,v_group::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='user_group' AND scope_type='occasion'
      AND scope_id=v_occasion AND aggregate_id=v_group::text FOR UPDATE;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('domainCode',200,'correct',true,'version',v_version)); END IF;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='user_group'
    AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_group::text
    RETURNING version INTO v_version;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',ug."user")),'[]'::jsonb) INTO v_impacts FROM public.user_groups ug
    WHERE ug."group"=v_group;
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(v_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'profile.game.guess','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',v_group,'operation','update',
      'safeLabel','Game checkpoint','changedFields',jsonb_build_array('game'))),
    '{}',v_impacts,'[]',jsonb_build_object('domainCode',200,'correct',true,
      'version',v_version),'{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION public.game_guess_client_sync_v1(p_checkpoint bigint, p_guess text, p_command_id uuid) OWNER TO postgres;

--
-- Name: game_guess_internal_v1(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.game_guess_internal_v1(check_point_id bigint, guess text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    hidden_value TEXT;
    correct_reference BIGINT;
    user_occasion BIGINT;
    user_in_group BOOLEAN;
    current_time TIMESTAMPTZ := NOW() AT TIME ZONE 'UTC';
    game_start TIMESTAMPTZ;
    game_end TIMESTAMPTZ;
    user_id UUID := auth.uid();  -- Retrieve the user ID from the authentication context
    existing_game_data JSONB;
BEGIN
    -- Step 1: Get the reference to `information_hidden` in `information` and check if it exists
    SELECT information_hidden::BIGINT INTO correct_reference
    FROM information
    WHERE id = check_point_id;

    IF correct_reference IS NULL THEN
        RETURN jsonb_build_object('code', 4041, 'message', 'Correct reference not found in information');
    END IF;

    -- Step 2: Retrieve the correct answer from `information_hidden.data` under the "correct" key and the occasion
    SELECT data->>'correct', occasion INTO hidden_value, user_occasion
    FROM information_hidden
    WHERE id = correct_reference;

    IF hidden_value IS NULL THEN
        RETURN jsonb_build_object('code', 4042, 'message', 'Hidden info not found or correct answer missing');
    END IF;

    -- Step 3: Retrieve game start and end times from the occasion data JSON, casting directly to TIMESTAMPTZ
    SELECT
        COALESCE((data->'game'->>'start')::TIMESTAMPTZ, NULL),
        COALESCE((data->'game'->>'end')::TIMESTAMPTZ, NULL)
    INTO game_start, game_end
    FROM occasions
    WHERE id = user_occasion;

    -- Step 4: Check if the current time is within the game time window
    IF game_start IS NOT NULL AND game_end IS NOT NULL THEN
        IF (CURRENT_DATE + current_time)::TIMESTAMPTZ < game_start OR (CURRENT_DATE + current_time)::TIMESTAMPTZ > game_end THEN
            RETURN jsonb_build_object('code', 4033, 'message', 'Guessing is only allowed within the game time window');
        END IF;
    END IF;

    -- Step 5: Check if the user is part of the occasion
    IF NOT EXISTS (
        SELECT 1
        FROM occasion_users
        WHERE "user" = user_id
          AND occasion = user_occasion
    ) THEN
        RETURN jsonb_build_object('code', 4031, 'message', 'User not in occasion');
    END IF;

    -- Step 6: Check if user is in a "game" type user group associated with the occasion
    user_in_group := EXISTS (
        SELECT 1
        FROM user_groups ug
        JOIN user_group_info ugi ON ug."group" = ugi.id
        WHERE ug."user" = user_id
          AND ugi.occasion = user_occasion
          AND ugi.type = 'game'
    );

    IF NOT user_in_group THEN
        RETURN jsonb_build_object('code', 4032, 'message', 'User not part of a game group');
    END IF;

    -- Step 7: Compare `guess` with `hidden_value` (ignoring diacritics, case, and trimming whitespace)
    IF unaccent(LOWER(TRIM(guess))) = unaccent(LOWER(TRIM(hidden_value))) THEN

        -- Step 8: Retrieve existing `game` array from `data` JSON and check if checkpoint already exists
        SELECT COALESCE(data->'game', '[]'::jsonb) INTO existing_game_data
        FROM user_group_info
        WHERE id = (
            SELECT "group"
            FROM user_groups
            WHERE "user" = user_id
              AND "group" IN (SELECT id FROM user_group_info WHERE occasion = user_occasion AND type = 'game')
            LIMIT 1
        );

        -- If `game` array does not exist, initialize it as an empty array
        IF existing_game_data IS NULL OR existing_game_data = 'null'::jsonb THEN
            existing_game_data := '[]'::jsonb;
        END IF;

        -- Append the new checkpoint if it does not already exist in the `game` array
        IF NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(existing_game_data) AS elem
            WHERE (elem->>'check_point')::INT = check_point_id
        ) THEN
            existing_game_data := existing_game_data || jsonb_build_array(
                jsonb_build_object('check_point', check_point_id, 'time', current_time)
            );

            -- Update the `data` JSON with the modified `game` array
            UPDATE user_group_info
            SET data = jsonb_set(COALESCE(data, '{}'::jsonb), '{game}', existing_game_data, true)
            WHERE id = (
                SELECT "group"
                FROM user_groups
                WHERE "user" = user_id
                  AND "group" IN (SELECT id FROM user_group_info WHERE occasion = user_occasion AND type = 'game')
                LIMIT 1
            );
        END IF;

        RETURN jsonb_build_object('code', 200, 'message', 'Correct answer');
    ELSE
        RETURN jsonb_build_object('code', 4001, 'message', 'Incorrect guess');
    END IF;
END;
$$;


ALTER FUNCTION public.game_guess_internal_v1(check_point_id bigint, guess text) OWNER TO postgres;

--
-- Name: game_update_settings(bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.game_update_settings(oc bigint, new_start_time timestamp with time zone, new_end_time timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN RETURN public.game_update_settings_client_sync_v1(
  oc,new_start_time,new_end_time,extensions.gen_random_uuid())->'data'; END; $$;


