CREATE FUNCTION public.game_update_settings_client_sync_v1(p_occasion bigint, p_start timestamp with time zone, p_end timestamp with time zone, p_command_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.save_game_settings_command_internal_v1(p_occasion,p_start,p_end,p_command_id,NULL);
$$;


