--
-- Name: game_update_settings_internal_v1(bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.game_update_settings_internal_v1(oc bigint, new_start_time timestamp with time zone, new_end_time timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  existing_data JSONB;
  updated_game_data JSONB;
BEGIN
  -- Check if the user is an editor on the occasion
  IF (SELECT public.can_edit_game_settings(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
  END IF;

  IF new_start_time>new_end_time THEN RAISE invalid_parameter_value USING MESSAGE='game start must precede end'; END IF;

  -- Retrieve existing data JSON if any
  SELECT data INTO existing_data FROM public.occasions WHERE id = oc;

  -- Create or update the "game" object with new start and end times, preserving other keys in "game"
  updated_game_data := COALESCE(existing_data->'game', '{}'::jsonb) || jsonb_build_object(
    'start', CASE WHEN new_start_time IS NOT NULL THEN to_jsonb(new_start_time) ELSE 'null'::jsonb END,
    'end', CASE WHEN new_end_time IS NOT NULL THEN to_jsonb(new_end_time) ELSE 'null'::jsonb END
  );

  -- Update the data JSON with the updated "game" data
  UPDATE public.occasions
  SET data = jsonb_set(
      COALESCE(data, '{}'::jsonb),                          -- Ensure data is an empty JSON if NULL
      ARRAY['game'],                                        -- Path to the "game" key
      updated_game_data,                                    -- Updated game data with merged start and end times
      true
    )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Game settings updated successfully'
  );
END;
$$;


ALTER FUNCTION public.game_update_settings_internal_v1(oc bigint, new_start_time timestamp with time zone, new_end_time timestamp with time zone) OWNER TO postgres;

--
-- Name: generate_creditor_reference(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_creditor_reference(p_variable_symbol bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_payload text;
  v_expanded text := '';
  v_char text;
  v_remainder integer := 0;
  v_index integer;
  v_result text;
BEGIN
  IF p_variable_symbol <= 0 OR p_variable_symbol > 9999999999 THEN
    RAISE EXCEPTION 'PAYMENT_REFERENCE_INVALID_VARIABLE_SYMBOL';
  END IF;
  v_payload := p_variable_symbol::text;

  FOR v_index IN 1..length(v_payload || 'RF00') LOOP
    v_char := substring(v_payload || 'RF00' FROM v_index FOR 1);
    IF v_char ~ '[0-9]' THEN
      v_expanded := v_expanded || v_char;
    ELSE
      v_expanded := v_expanded || (ascii(v_char) - 55)::text;
    END IF;
  END LOOP;
  FOR v_index IN 1..length(v_expanded) LOOP
    v_remainder := (v_remainder * 10 + substring(v_expanded FROM v_index FOR 1)::integer) % 97;
  END LOOP;
  v_result := 'RF' || lpad((98 - v_remainder)::text, 2, '0') || v_payload;
  IF NOT public.is_valid_creditor_reference(v_result) THEN
    RAISE EXCEPTION 'PAYMENT_REFERENCE_GENERATION_FAILED';
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.generate_creditor_reference(p_variable_symbol bigint) OWNER TO postgres;

--
-- Name: generate_order_symbol(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_order_symbol() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    alphabets text[] := ARRAY['123456789', 'ACEFGHIJKLMNPQRUVWXY'];
    bytes bytea := extensions.gen_random_bytes(64);
    pos integer := 0;
    b integer;
    alphabet text;
    symbol text := '';
BEGIN
    FOR pair IN 1..5 LOOP
        FOREACH alphabet IN ARRAY alphabets LOOP
            LOOP
                IF pos = length(bytes) THEN
                    bytes := extensions.gen_random_bytes(64);
                    pos := 0;
                END IF;
                b := get_byte(bytes, pos);
                pos := pos + 1;
                EXIT WHEN b < 256 - (256 % length(alphabet));
            END LOOP;
            symbol := symbol || substr(alphabet, (b % length(alphabet)) + 1, 1);
        END LOOP;
    END LOOP;
    RETURN symbol;
END;
$$;


ALTER FUNCTION public.generate_order_symbol() OWNER TO postgres;

--
-- Name: generate_payment_variable_symbol(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_payment_variable_symbol(p_bank_account_id bigint, p_form_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    -- Variables for form configuration
    v_form_data JSONB;
    v_vs_config JSONB;
    v_vs_type TEXT;
    v_starting_number BIGINT;
    v_max_symbol_for_form BIGINT;

    -- General variable for the symbol to be returned
    v_candidate_symbol BIGINT;

    -- Variables for the random generation fallback
    v_digit_count INT := 4;
    v_attempt_count INT := 0;
    v_max_attempts INT := 1;
    v_safety_counter INT := 0; -- Safety break for the sequential loop
BEGIN
    IF public.payment_reference_scope_enabled_internal(p_form_id) THEN
      RAISE EXCEPTION 'PAYMENT_REFERENCE_RESERVATION_REQUIRED'; END IF;
    IF EXISTS(SELECT 1 FROM eshop.payment_reference_namespaces n
      WHERE n.canonical_account=public.try_payment_reference_account_internal((SELECT account_number FROM eshop.bank_accounts WHERE id=p_bank_account_id))
      AND (n.allocation_enabled OR EXISTS(SELECT 1 FROM eshop.payment_reference_reservations r WHERE r.namespace_id=n.id))) THEN
      RAISE EXCEPTION 'PAYMENT_REFERENCE_SHARED_ACCOUNT_REQUIRES_ENROLLMENT'; END IF;
    -- 1. Fetch the configuration data for the given form
    SELECT data INTO v_form_data FROM public.forms WHERE id = p_form_id;

    -- Raise an error if the form does not exist
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Form with ID % not found.', p_form_id;
    END IF;

    -- 2. Check for custom variable symbol configuration within the JSONB data
    -- We use COALESCE to default to 'random' if the setting is missing, making the function robust.
    v_vs_config := v_form_data -> 'variable_symbol';
    v_vs_type := COALESCE(v_vs_config ->> 'type', 'random');

    -- 3. Main logic: Choose between 'sequence' and 'random' generation
    IF v_vs_type = 'sequence' THEN
        ----------------------------------------------------
        -- LOGIC FOR SEQUENTIAL VARIABLE SYMBOL GENERATION --
        ----------------------------------------------------

        -- Get the defined starting number from the form's configuration
        v_starting_number := (v_vs_config ->> 'starting_number')::BIGINT;
        IF v_starting_number IS NULL THEN
            RAISE EXCEPTION 'Form with ID % is configured for sequential variable symbols, but "starting_number" is missing in its data.', p_form_id;
        END IF;

        -- Find the highest existing variable symbol used for this specific form.
        -- We must join through the orders table to link payments to a form.
        SELECT MAX(pi.variable_symbol)
        INTO v_max_symbol_for_form
        FROM eshop.payment_info pi
        JOIN eshop.orders o ON pi.id = o.payment_info
        WHERE o.form = p_form_id;

        -- Determine the first candidate for our new variable symbol.
        -- If no previous symbol exists for this form, use the starting number.
        -- Otherwise, take the highest existing symbol and add 1.
        -- The GREATEST function handles the edge case where the starting_number was increased after symbols were already generated.
        IF v_max_symbol_for_form IS NULL THEN
            v_candidate_symbol := v_starting_number;
        ELSE
            v_candidate_symbol := GREATEST(v_max_symbol_for_form + 1, v_starting_number);
        END IF;

        -- Loop to ensure the candidate symbol is unique for the target bank account.
        -- If the symbol is already taken, increment and check again.
        LOOP
            IF NOT EXISTS (
                SELECT 1
                FROM eshop.payment_info
                WHERE variable_symbol = v_candidate_symbol AND bank_account = p_bank_account_id
            ) THEN
                RETURN v_candidate_symbol; -- The symbol is unique, return it.
            END IF;

            -- The symbol was taken, so we increment and try the next one.
            v_candidate_symbol := v_candidate_symbol + 1;

            -- Add a safety break to prevent an infinite loop in unusual circumstances.
            v_safety_counter := v_safety_counter + 1;
            IF v_safety_counter > 1000 THEN
                RAISE EXCEPTION 'Could not find a unique sequential variable symbol for bank account % after 1000 attempts.', p_bank_account_id;
            END IF;
        END LOOP;

    ELSE
        ------------------------------------------------
        -- LOGIC FOR RANDOM VARIABLE SYMBOL GENERATION --
        ------------------------------------------------

        LOOP
            -- Generate a random number with the current digit count
            v_candidate_symbol := FLOOR(RANDOM() * (POWER(10, v_digit_count) - POWER(10, v_digit_count - 1))) + POWER(10, v_digit_count - 1);

            -- Ensure uniqueness within the bank_account
            IF NOT EXISTS (
                SELECT 1
                FROM eshop.payment_info
                WHERE variable_symbol = v_candidate_symbol AND bank_account = p_bank_account_id
            ) THEN
                RETURN v_candidate_symbol; -- Return the unique variable symbol
            END IF;

            -- Increment attempt count and adjust digit count after each failure
            v_attempt_count := v_attempt_count + 1;

            -- Extend digit count after reaching max attempts
            IF v_attempt_count >= v_max_attempts THEN
                v_digit_count := v_digit_count + 1;
                v_attempt_count := 0; -- Reset attempt count for the extended digit count
            END IF;

            -- Fail entirely if the system cannot generate a unique symbol after too many attempts
            IF v_digit_count > 10 THEN -- Arbitrary upper limit for digit count
                RAISE EXCEPTION 'Failed to generate a unique random variable symbol after too many attempts.';
            END IF;
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION public.generate_payment_variable_symbol(p_bank_account_id bigint, p_form_id bigint) OWNER TO postgres;

--
-- Name: generate_request_secret(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_request_secret(p_ttl_seconds integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_secret text;
BEGIN
  -- Clean up expired secrets
  DELETE FROM public.request_secrets
  WHERE created_at < (now() - (interval '1 second' * ttl_seconds));

  -- Generate a new secret using a random UUID
  v_secret := gen_random_uuid()::text;

  INSERT INTO public.request_secrets(secret, ttl_seconds)
  VALUES (v_secret, p_ttl_seconds);

  RETURN v_secret;
END;
$$;


ALTER FUNCTION public.generate_request_secret(p_ttl_seconds integer) OWNER TO postgres;

--
-- Name: generate_schema_ddl(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_schema_ddl(p_schema text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
WITH table_info AS (
  SELECT
    t.table_schema,
    t.table_name,
    CASE
      WHEN COALESCE(pg.tablespace, '') = '' THEN ' TABLESPACE pg_default'
      ELSE ' TABLESPACE ' || pg.tablespace
    END AS tablespace_clause
  FROM information_schema.tables t
  LEFT JOIN pg_catalog.pg_tables pg
    ON t.table_schema = pg.schemaname
   AND t.table_name = pg.tablename
  WHERE t.table_schema = p_schema
    AND t.table_type = 'BASE TABLE'
),
table_columns AS (
  SELECT
    c.table_schema,
    c.table_name,
    string_agg(
      '  ' || quote_ident(c.column_name) || ' ' ||
      (
        CASE
          -- Identity columns: type + identity clause
          WHEN c.is_identity = 'YES' THEN
            c.data_type ||
            CASE
              WHEN c.data_type IN ('character varying','character')
                   AND c.character_maximum_length IS NOT NULL
              THEN '(' || c.character_maximum_length || ')'
              WHEN c.data_type = 'numeric' AND c.numeric_precision IS NOT NULL
              THEN '(' || c.numeric_precision || ', ' || c.numeric_scale || ')'
              ELSE ''
            END ||
            ' generated ' || lower(c.identity_generation) || ' as identity'
          -- Serial columns (if not identity)
          WHEN c.data_type = 'integer' AND c.column_default LIKE 'nextval(%' THEN
            'serial'
          -- Numeric columns with precision/scale
          WHEN c.data_type = 'numeric' AND c.numeric_precision IS NOT NULL THEN
            'numeric(' || c.numeric_precision || ', ' || c.numeric_scale || ')'
          ELSE
            c.data_type ||
              CASE
                WHEN c.data_type IN ('character varying','character')
                     AND c.character_maximum_length IS NOT NULL
                THEN '(' || c.character_maximum_length || ')'
                ELSE ''
              END
        END
      ) ||
      ' ' || (CASE WHEN c.is_nullable = 'NO' THEN 'not null' ELSE 'null' END) ||
      CASE
         WHEN c.is_identity <> 'YES'
              AND NOT (c.data_type = 'integer' AND c.column_default LIKE 'nextval(%')
              AND c.column_default IS NOT NULL
         THEN ' default ' || c.column_default
         ELSE ''
      END,
      E',\n'
      ORDER BY c.ordinal_position
    ) AS columns_definition
  FROM information_schema.columns c
  WHERE c.table_schema = p_schema
  GROUP BY c.table_schema, c.table_name
),
constraints_pk AS (
  SELECT
    tc.table_schema,
    tc.table_name,
    '  constraint ' || quote_ident(tc.constraint_name) || ' primary key (' ||
      string_agg(quote_ident(kcu.column_name), ', ' ORDER BY kcu.ordinal_position) || ')' AS constraint_def
  FROM information_schema.table_constraints tc
  JOIN information_schema.key_column_usage kcu
    ON tc.constraint_name = kcu.constraint_name
   AND tc.table_schema = kcu.table_schema
  WHERE tc.constraint_type = 'PRIMARY KEY'
    AND tc.table_schema = p_schema
  GROUP BY tc.table_schema, tc.table_name, tc.constraint_name
),
constraints_fk AS (
  SELECT
    tc.table_schema,
    tc.table_name,
    '  constraint ' || quote_ident(tc.constraint_name) || ' foreign KEY (' ||
      string_agg(quote_ident(kcu.column_name), ', ' ORDER BY kcu.ordinal_position) || ') references ' ||
      (
        -- Invert the condition: if the referenced schema is different, qualify the name.
        CASE
          WHEN reftable_ns.nspname <> p_schema
          THEN quote_ident(reftable_ns.nspname) || '.' || quote_ident(reftable.relname)
          ELSE quote_ident(reftable.relname)
        END
      ) || ' (' ||
      (
        SELECT string_agg(quote_ident(att.attname), ', ' ORDER BY u.ordinality)
        FROM unnest(pgc.confkey) WITH ORDINALITY AS u(attnum, ordinality)
        JOIN pg_attribute att
          ON att.attrelid = pgc.confrelid AND att.attnum = u.attnum
      )
      || ')' ||
      CASE
         WHEN pgc.confdeltype = 'c' THEN ' on delete cascade'
         WHEN pgc.confdeltype = 'n' THEN ' on delete set null'
         WHEN pgc.confdeltype = 'd' THEN ' on delete set default'
         WHEN pgc.confdeltype = 'r' THEN ' on delete restrict'
         ELSE ''
      END AS constraint_def
  FROM information_schema.table_constraints tc
  JOIN information_schema.key_column_usage kcu
    ON tc.constraint_name = kcu.constraint_name
   AND tc.table_schema = kcu.table_schema
  JOIN pg_constraint pgc
    ON pgc.conname = tc.constraint_name
       AND pgc.conrelid = (
            SELECT oid FROM pg_class
            WHERE relname = tc.table_name
              AND relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = tc.table_schema)
       )
  JOIN pg_class reftable ON reftable.oid = pgc.confrelid
  JOIN pg_namespace reftable_ns ON reftable_ns.oid = reftable.relnamespace
  WHERE tc.constraint_type = 'FOREIGN KEY'
    AND tc.table_schema = p_schema
  GROUP BY tc.table_schema, tc.table_name, tc.constraint_name,
           reftable_ns.nspname, reftable.relname, pgc.confdeltype, pgc.confkey, pgc.confrelid
),
all_constraints AS (
  SELECT
    table_schema,
    table_name,
    string_agg(constraint_def, E',\n') AS constraints_def
  FROM (
    SELECT * FROM constraints_pk
    UNION ALL
    SELECT * FROM constraints_fk
  ) sub
  GROUP BY table_schema, table_name
),
create_statements AS (
  SELECT
    'create table if not exists ' || quote_ident(t.table_schema) || '.' || quote_ident(t.table_name) || E' (\n' ||
    COALESCE(tc.columns_definition, '') ||
    CASE
      WHEN ac.constraints_def IS NOT NULL THEN E',\n' || ac.constraints_def
      ELSE ''
    END ||
    E'\n) ' ||
    COALESCE(t.tablespace_clause, '') ||
    ';' AS create_table_statement
  FROM table_info t
  LEFT JOIN table_columns tc
    ON t.table_schema = tc.table_schema AND t.table_name = tc.table_name
  LEFT JOIN all_constraints ac
    ON t.table_schema = ac.table_schema AND t.table_name = ac.table_name
)
SELECT string_agg(create_table_statement, E'\n\n') AS ddl_all
FROM create_statements;
$$;


ALTER FUNCTION public.generate_schema_ddl(p_schema text) OWNER TO postgres;

--
-- Name: generate_schema_policies_ddl(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_schema_policies_ddl(p_schema text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
WITH policies AS (
  SELECT schemaname,
         tablename,
         policyname,
         permissive,
         cmd,
         roles,
         qual,
         with_check
  FROM pg_policies
  WHERE schemaname = p_schema
),
formatted_policies AS (
  SELECT
    (
      'DROP POLICY IF EXISTS ' || quote_ident(policyname) || ' ON ' ||
        quote_ident(schemaname) || '.' || quote_ident(tablename) || ';' || E'\n' ||
      'CREATE POLICY ' || quote_ident(policyname) || ' ON ' ||
        quote_ident(schemaname) || '.' || quote_ident(tablename) || E'\n' ||
      (CASE WHEN lower(permissive) = 'permissive'
            THEN 'AS PERMISSIVE '
            ELSE 'AS RESTRICTIVE ' END) ||
      'FOR ' || upper(cmd) || E'\n' ||
      (CASE
         WHEN roles IS NOT NULL AND array_length(roles,1) > 0
         THEN 'TO ' || (SELECT string_agg(quote_ident(r), ', ')
                      FROM unnest(roles) AS r) || E'\n'
         ELSE ''
       END) ||
      (CASE WHEN qual IS NOT NULL AND qual <> ''
            THEN 'USING (' || qual || ')' || E'\n'
            ELSE '' END) ||
      (CASE WHEN with_check IS NOT NULL AND with_check <> ''
            THEN 'WITH CHECK (' || with_check || ')' || E'\n'
            ELSE '' END)
    ) AS raw_policy_ddl
  FROM policies
)
SELECT string_agg(rtrim(raw_policy_ddl, E'\n') || ';', E'\n\n') AS ddl_all
FROM formatted_policies;
$$;


ALTER FUNCTION public.generate_schema_policies_ddl(p_schema text) OWNER TO postgres;

--
-- Name: generate_schema_rls_enable_ddl(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_schema_rls_enable_ddl(p_schema text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
WITH tables AS (
  SELECT n.nspname AS schemaname,
         c.relname AS tablename
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = p_schema
    AND c.relkind IN ('r', 'p')  -- regular and partitioned tables
)
SELECT string_agg(
         'ALTER TABLE ' || quote_ident(schemaname) || '.' || quote_ident(tablename) ||
         ' ENABLE ROW LEVEL SECURITY;', E'\n'
       ) AS ddl_all
FROM tables;
$$;


ALTER FUNCTION public.generate_schema_rls_enable_ddl(p_schema text) OWNER TO postgres;

--
-- Name: generate_schema_triggers_ddl(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_schema_triggers_ddl(p_schema text) RETURNS text
    LANGUAGE sql STABLE
    AS $$
WITH aggregated_triggers AS (
  SELECT
    trigger_schema,
    trigger_name,
    event_object_schema,
    event_object_table,
    action_timing,
    action_orientation,
    string_agg(event_manipulation, ' or ') AS events,
    max(action_condition) AS action_condition,
    max(action_statement) AS action_statement
  FROM information_schema.triggers
  WHERE trigger_schema = p_schema
  GROUP BY trigger_schema, trigger_name, event_object_schema, event_object_table, action_timing, action_orientation
),
formatted_triggers AS (
  SELECT
    -- Drop statement
    'DROP TRIGGER IF EXISTS ' || quote_ident(trigger_name) || ' ON '
    || CASE
         WHEN event_object_schema = p_schema
           THEN quote_ident(event_object_table)
         ELSE quote_ident(event_object_schema) || '.' || quote_ident(event_object_table)
       END || ';' || E'\n'
    ||
    -- Create statement
    'CREATE TRIGGER ' || quote_ident(trigger_name) || E'\n'
    || upper(action_timing) || ' ' || lower(events) || ' ON '
    || CASE
         WHEN event_object_schema = p_schema
           THEN quote_ident(event_object_table)
         ELSE quote_ident(event_object_schema) || '.' || quote_ident(event_object_table)
       END
    || E'\nFOR EACH ' || lower(action_orientation) || E'\n'
    || CASE
         WHEN action_condition IS NOT NULL
           THEN 'WHEN (' || action_condition || ')' || E'\n'
         ELSE ''
       END
    || 'EXECUTE ' || action_statement || ';'
    AS trigger_ddl
  FROM aggregated_triggers
)
SELECT string_agg(trigger_ddl, E'\n\n') AS ddl_all
FROM formatted_triggers;
$$;


ALTER FUNCTION public.generate_schema_triggers_ddl(p_schema text) OWNER TO postgres;

--
-- Name: generate_ticket_symbol(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_ticket_symbol(organization_id bigint, occasion_id bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    visible_id TEXT;
    org_suffix TEXT;
    occasion_suffix TEXT;
    numeric_part TEXT := '123456789';
    alphabetic_part TEXT := 'ACEFGHIJKLMNPQRUVWXY';
    attempt_count INT := 0;
BEGIN
    -- Extract last two digits of organization_id and occasion_id
    org_suffix := LPAD((organization_id % 100)::TEXT, 2, '0');  -- Ensure 2 digits
    occasion_suffix := LPAD((occasion_id % 100)::TEXT, 2, '0'); -- Ensure 2 digits

    -- Replace '0' with 'X' in the suffixes
    org_suffix := REPLACE(org_suffix, '0', 'X');
    occasion_suffix := REPLACE(occasion_suffix, '0', 'X');

    LOOP
        -- Generate alternating numeric and alphabetic parts
        visible_id := org_suffix || occasion_suffix ||
                      SUBSTRING(numeric_part FROM FLOOR(RANDOM() * 9 + 1)::INT FOR 1) ||
                      SUBSTRING(alphabetic_part FROM FLOOR(RANDOM() * 20 + 1)::INT FOR 1) ||
                      SUBSTRING(numeric_part FROM FLOOR(RANDOM() * 9 + 1)::INT FOR 1) ||
                      SUBSTRING(alphabetic_part FROM FLOOR(RANDOM() * 20 + 1)::INT FOR 1) ||
                      SUBSTRING(numeric_part FROM FLOOR(RANDOM() * 9 + 1)::INT FOR 1) ||
                      SUBSTRING(alphabetic_part FROM FLOOR(RANDOM() * 20 + 1)::INT FOR 1);

        -- Ensure uniqueness in the database (within the occasion)
        IF NOT EXISTS (
            SELECT 1
            FROM eshop.tickets
            WHERE ticket_symbol = visible_id AND occasion = occasion_id
        ) THEN
            RETURN visible_id; -- Return the unique visible ID
        END IF;

        -- Increment attempt count and fail after a fixed number of attempts
        attempt_count := attempt_count + 1;
        IF attempt_count > 10 THEN
            RAISE EXCEPTION 'Failed to generate unique visible ID after 10 attempts';
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION public.generate_ticket_symbol(organization_id bigint, occasion_id bigint) OWNER TO postgres;

--
-- Name: generate_variable_symbol(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_variable_symbol(bank_account_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_symbol BIGINT;
    digit_count INT := 4; -- Start with 4 digits
    attempt_count INT := 0;
    max_attempts INT := 1; -- Maximum allowed attempts per digit count
BEGIN
    LOOP
        -- Generate a random number with the current digit count
        v_symbol := FLOOR(RANDOM() * (POWER(10, digit_count) - POWER(10, digit_count - 1))) + POWER(10, digit_count - 1);

        -- Ensure uniqueness within the bank_account
        IF NOT EXISTS (
            SELECT 1
            FROM eshop.payment_info
            WHERE variable_symbol = v_symbol AND bank_account = bank_account_id
        ) THEN
            RETURN v_symbol; -- Return the unique variable symbol
        END IF;

        -- Increment attempt count and adjust digit count after each failure
        attempt_count := attempt_count + 1;

        -- Extend digit count after reaching max attempts
        IF attempt_count >= max_attempts THEN
            digit_count := digit_count + 1;
            attempt_count := 0; -- Reset attempt count for the extended digit count
        END IF;

        -- Fail entirely if the system cannot generate a unique symbol after too many attempts
        IF digit_count > 10 THEN -- Arbitrary upper limit for digit count
            RAISE EXCEPTION 'Failed to generate unique variable symbol after too many attempts.';
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION public.generate_variable_symbol(bank_account_id bigint) OWNER TO postgres;

