--
-- Name: get_account_deletion_asset_batch(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_account_deletion_asset_batch(p_request_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE job public.account_deletion_requests%ROWTYPE; result jsonb;
BEGIN
 PERFORM public.require_service_role();
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 THEN
  RAISE invalid_parameter_value USING MESSAGE='asset_batch_limit';
 END IF;
 IF NOT COALESCE((SELECT active FROM public.canonical_asset_cutover WHERE singleton),false) THEN
  RAISE object_not_in_prerequisite_state USING MESSAGE='asset_cutover_not_active';
 END IF;
 SELECT * INTO job FROM public.account_deletion_requests WHERE id=p_request_id FOR UPDATE;
 IF job.id IS NULL OR job.user_id IS NULL OR job.status NOT IN ('deletion_pending','failed') THEN
  RAISE object_not_in_prerequisite_state USING MESSAGE='account_deletion_request_state_conflict';
 END IF;
 INSERT INTO public.account_deletion_assets(request_id,asset_id)
 SELECT job.id,a.id FROM public.canonical_assets a
 WHERE a.owner_id=job.user_id::text AND a.deleted_at IS NULL
 ON CONFLICT DO NOTHING;
 UPDATE public.account_deletion_requests SET assets_prepared=true WHERE id=job.id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('assetId',a.id,'bucket',a.bucket,
  'key',a.object_key,'sha256',a.sha256) ORDER BY a.id),'[]'::jsonb) INTO result
 FROM (SELECT q.asset_id FROM public.account_deletion_assets q
  WHERE q.request_id=job.id AND q.deleted_at IS NULL ORDER BY q.asset_id LIMIT p_limit) q
 JOIN public.canonical_assets a ON a.id=q.asset_id AND a.owner_id=job.user_id::text;
 RETURN result;
END $$;


ALTER FUNCTION public.get_account_deletion_asset_batch(p_request_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_activities_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_activities_for_edit(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    eventsData              JSONB;
    placesData              JSONB;
    activitiesData          JSONB;
    assignmentPlaceLinksData JSONB;
    assignmentEventLinksData JSONB;
    aaData                  JSONB;
    usersData               JSONB;
BEGIN

   -- Authorization check
    IF (SELECT get_is_editor_view_on_occasion(p_occasion)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this occasion''s edit data');
    END IF;

    -- (a) all events
    SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'created_at', e.created_at, 'title', e.title, 'start_time', e.start_time,
        'end_time', e.end_time, 'max_participants', e.max_participants, 'description', e.description,
        'place', e.place, 'split_for_men_women', e.split_for_men_women, 'is_group_event', e.is_group_event,
        'updated_at', e.updated_at, 'is_hidden', e.is_hidden, 'occasion', e.occasion, 'type', e.type, 'data', e.data
    )) INTO eventsData
    FROM public.events e WHERE e.occasion = p_occasion;

    -- (b) all places for this occasion, sorted by places.order
    -- The jsonb_agg function will respect the order of the rows it aggregates.
    SELECT jsonb_agg(place_obj ORDER BY place_order ASC)
    INTO placesData
    FROM (
        SELECT jsonb_build_object(
            'id', p.id, 'title', p.title, 'description', p.description, 'type', p.type, 'created_at', p.created_at,
            'coordinates', p.coordinates, 'is_hidden', p.is_hidden, 'updated_at', p.updated_at, 'occasion', p.occasion,
            'order', p."order"
        ) AS place_obj,
        p."order" AS place_order
        FROM public.places p
        WHERE p.occasion = p_occasion
    ) AS ordered_places;


    -- (c) all activities
    SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'created_at', a.created_at, 'updated_at', a.updated_at, 'title', a.title,
        'description', a.description, 'type', a.type, 'occasion', a.occasion, 'unit', a.unit,
        'is_hidden', a.is_hidden, 'order', a."order", 'data', a.data
    )) INTO activitiesData
    FROM public.activities a WHERE a.occasion = p_occasion;

    -- (d) activity_assignment_places links (now assignment_id <-> place_id)
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', apl.assignment_id,
        'place_id',      apl.place_id
    )) INTO assignmentPlaceLinksData
    FROM public.activity_assignment_places apl
    JOIN public.activity_assignments aa ON apl.assignment_id = aa.id
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (e) activity_assignment_events links (now assignment_id <-> event_id)
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', ael.assignment_id,
        'event_id',      ael.event_id
    )) INTO assignmentEventLinksData
    FROM public.activity_assignment_events ael
    JOIN public.activity_assignments aa ON ael.assignment_id = aa.id
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (f) activity_assignments
    SELECT jsonb_agg(jsonb_build_object(
        'id', aa.id, 'activity_id', aa.activity_id, 'user', aa."user", 'start_time', aa.start_time,
        'end_time', aa.end_time, 'title', aa.title, 'description', aa.description, 'data', aa.data
    )) INTO aaData
    FROM public.activity_assignments aa
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (g) users for this occasion who are volunteers
    SELECT jsonb_agg(jsonb_build_object(
        'id', ui.id, 'name', ui.name, 'surname', ui.surname, 'sex', ui.sex, 'email', ui.email_readonly
    )) INTO usersData
    FROM public.user_info ui
    JOIN public.occasion_users ou ON ui.id = ou."user"
    WHERE ou.occasion = p_occasion AND (ou.data->>'is_volunteer')::boolean = TRUE;

    -- (h) assemble
    RETURN jsonb_build_object(
      'code', 200,
      'message', 'Data for editing activities retrieved successfully.',
      'data', jsonb_build_object(
        'events',                  COALESCE(eventsData, '[]'::jsonb),
        'places',                  COALESCE(placesData, '[]'::jsonb),
        'activities',              COALESCE(activitiesData, '[]'::jsonb),
        'assignment_place_links',  COALESCE(assignmentPlaceLinksData, '[]'::jsonb),
        'assignment_event_links',  COALESCE(assignmentEventLinksData, '[]'::jsonb),
        'activity_assignments',    COALESCE(aaData, '[]'::jsonb),
        'user_info',               COALESCE(usersData, '[]'::jsonb),
        'aggregate_version',       COALESCE((SELECT av.version
          FROM public.client_aggregate_versions av
          WHERE av.aggregate_type='activities' AND av.scope_type='occasion'
            AND av.scope_id=p_occasion AND av.aggregate_id=p_occasion::text),0)
      )
    );
END;
$$;


ALTER FUNCTION public.get_activities_for_edit(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_activity_editor_session_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_activity_editor_session_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT CASE WHEN auth.uid() IS NULL OR NOT public.can_read_activity_editor(p_occasion) THEN jsonb_build_object('code',403) ELSE
 jsonb_build_object('code',200,'liveVersion',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text),0),
 'latestPublishId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1),
 'draftId',d.id,'draftParentHistoryId',d.parent_history_id,'draftData',CASE WHEN d.id IS NOT NULL THEN public.activity_graph_history_internal_v1(public.activity_history_graph_internal_v1(p_occasion,d.activities_data,false)) ELSE NULL END,
 'editBundle',jsonb_build_object(
 'events',COALESCE((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.events e WHERE e.occasion=p_occasion),'[]'),
 'places',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p."order",p.id) FROM public.places p WHERE p.occasion=p_occasion),'[]'),
 'activities',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.activities a WHERE a.occasion=p_occasion),'[]'),
 'activity_assignments',COALESCE((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.activity_assignments x JOIN public.activities a ON a.id=x.activity_id WHERE a.occasion=p_occasion),'[]'),
 'assignment_place_links',COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM public.activity_assignment_places l JOIN public.activity_assignments x ON x.id=l.assignment_id JOIN public.activities a ON a.id=x.activity_id WHERE a.occasion=p_occasion),'[]'),
 'assignment_event_links',COALESCE((SELECT jsonb_agg(to_jsonb(l)) FROM public.activity_assignment_events l JOIN public.activity_assignments x ON x.id=l.assignment_id JOIN public.activities a ON a.id=x.activity_id WHERE a.occasion=p_occasion),'[]'),
 'user_info',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.name,'surname',u.surname,'sex',u.sex,'email',u.email_readonly)) FROM public.user_info u JOIN public.occasion_users ou ON ou."user"=u.id WHERE ou.occasion=p_occasion AND (ou.data->>'is_volunteer')::boolean),'[]'))) END
 FROM (SELECT 1) root LEFT JOIN LATERAL (SELECT id,parent_history_id,activities_data FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=auth.uid() AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1) d ON true;
$$;


ALTER FUNCTION public.get_activity_editor_session_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_activity_history_version(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_activity_history_version(p_history_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id BIGINT;
    history_data JSONB;
BEGIN
    SELECT occasion_id INTO v_occasion_id FROM public.activity_history WHERE id = p_history_id AND (history_type<>'AUTOSAVE' OR user_id=auth.uid());

    IF v_occasion_id IS NULL OR (SELECT get_is_editor_on_occasion(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this history version');
    END IF;

    -- Select the single history record into a JSON object
    SELECT jsonb_build_object(
        'id', id,
        'created_at', created_at,
        'activities_data', public.activity_graph_history_internal_v1(public.activity_history_graph_internal_v1(v_occasion_id,activities_data,false)),
        'parent_history_id', parent_history_id
    )
    INTO history_data
    FROM public.activity_history
    WHERE id = p_history_id AND (history_type<>'AUTOSAVE' OR user_id=auth.uid());

    -- Return the object wrapped in a standard response
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'History version retrieved.',
        'data', history_data
    );
END;
$$;


ALTER FUNCTION public.get_activity_history_version(p_history_id bigint) OWNER TO postgres;

--
-- Name: get_all_email_templates(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_email_templates(p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  email_data jsonb;
  v_occ  bigint;
  v_unit bigint;
  v_org  bigint;

  v_effective_org bigint;
  v_actual_unit bigint;
  v_actual_org bigint;
  is_app_supported boolean := false;
  show_waitlist_templates boolean := false;
  show_sale_opening_templates boolean := false;
BEGIN
  -- 1. Extract context values from the JSON parameter
  v_occ  := CASE
              WHEN p_context ? 'occasion' AND (p_context->>'occasion') IS NOT NULL
              THEN (p_context->>'occasion')::bigint
              ELSE NULL
            END;
  v_unit := CASE
              WHEN p_context ? 'unit' AND (p_context->>'unit') IS NOT NULL
              THEN (p_context->>'unit')::bigint
              ELSE NULL
            END;
  v_org  := CASE
              WHEN p_context ? 'organization' AND (p_context->>'organization') IS NOT NULL
              THEN (p_context->>'organization')::bigint
              ELSE NULL
            END;

  -- Resolve ancestors from the requested object; never trust mixed tenant IDs.
  IF v_occ IS NOT NULL THEN
    SELECT unit, organization INTO v_actual_unit, v_actual_org
    FROM public.occasions WHERE id = v_occ;
    IF NOT FOUND OR (v_unit IS NOT NULL AND v_unit IS DISTINCT FROM v_actual_unit)
        OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE insufficient_privilege USING MESSAGE = 'Invalid email template hierarchy';
    END IF;
    IF NOT public.is_service_role()
       AND public.can_read_occasion_email_templates(v_occ) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE = 'Occasion template access denied';
    END IF;
    v_unit := v_actual_unit;
    v_org := v_actual_org;
  ELSIF v_unit IS NOT NULL THEN
    SELECT organization INTO v_actual_org FROM public.units WHERE id = v_unit;
    IF NOT FOUND OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE insufficient_privilege USING MESSAGE = 'Invalid email template hierarchy';
    END IF;
    IF NOT public.is_service_role()
       AND public.can_read_unit_email_templates(v_unit) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE = 'Unit template access denied';
    END IF;
    v_org := v_actual_org;
  ELSIF NOT public.is_service_role() THEN
    IF v_org IS NULL OR public.can_manage_organization_email_templates(v_org) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE = 'Organization template access denied';
    END IF;
  END IF;
  v_effective_org := v_org;

  -- 3. Check if App is Supported for the effective organization
  IF v_effective_org IS NOT NULL THEN
    SELECT COALESCE((data->>'IS_APP_SUPPORTED')::BOOLEAN, false)
    INTO is_app_supported
    FROM public.organizations
    WHERE id = v_effective_org;
  END IF;

  -- The catalog follows the requested scope; stored templates and queue rendering
  -- remain available independently of whether the feature is currently enabled.
  SELECT EXISTS (
    SELECT 1 FROM public.forms f
    JOIN public.occasions o ON o.id = f.occasion
    WHERE o.organization = v_effective_org
      AND (v_occ IS NULL OR o.id = v_occ)
      AND (v_unit IS NULL OR o.unit = v_unit)
      AND f.participant_capacity > 0
      AND f.waitlist_enabled IS TRUE
  ) INTO show_waitlist_templates;

  SELECT EXISTS(SELECT 1 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
   WHERE o.organization=v_org AND (v_occ IS NULL OR o.id=v_occ) AND (v_unit IS NULL OR o.unit=v_unit)
   AND coalesce((public.normalize_form_metadata_internal(f.data)#>>'{sale_opening_notifications,enabled}')::boolean,false)) INTO show_sale_opening_templates;
  -- 5. Retrieve email templates
  SELECT jsonb_agg(public.get_email_template_state_internal(
    jsonb_build_object('occasion',v_occ,'unit',v_unit,'organization',v_org),result.code) ORDER BY result.code)
    INTO email_data
  FROM (
    SELECT DISTINCT et.code
    FROM public.email_templates et
    WHERE
      -- A. Filter based on context (Scope)
      (
           (v_occ IS NOT NULL AND et.occasion = v_occ)
        OR (v_unit IS NOT NULL AND et.unit = v_unit AND et.occasion IS NULL)
        OR (v_org IS NOT NULL  AND et.organization = v_org AND et.unit IS NULL AND et.occasion IS NULL)
        OR (et.organization IS NULL AND et.unit IS NULL AND et.occasion IS NULL)
      )
      AND et.code <> 'ORDER_OVERVIEW'
      -- Explicit editor catalog: internal and unknown codes are never enabled
      -- merely by adding a global default. Keep feature visibility below.
      AND (
        et.code IN (
          'TICKET_ORDER_CONFIRMATION', 'TICKET_ORDER_PAYMENT_DONE',
          'TICKET_ORDER_REMINDER', 'TICKET_ORDER_STORNO', 'TICKET_ORDER_UPDATE',
          'waitlist_confirmation', 'waitlist_offer', 'sale_opening_opened'
        )
        OR (is_app_supported IS TRUE AND et.code IN (
          'SIGN_IN_CODE', 'RESET_PASSWORD', 'APP_LINKS',
          'ACCOUNT_DELETION_CONFIRM', 'ACCOUNT_DELETION_COMPLETE'
        ))
      )
      AND (show_sale_opening_templates OR et.code NOT IN ('sale_opening_opened'))
      AND (show_waitlist_templates OR et.code NOT IN
        ('waitlist_confirmation', 'waitlist_offer'))
  ) result;

  IF email_data IS NULL THEN
    email_data := '[]'::jsonb;
  END IF;

  RETURN email_data;
END;
$$;


ALTER FUNCTION public.get_all_email_templates(p_context jsonb) OWNER TO postgres;

--
-- Name: get_all_email_templates_via_form_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_email_templates_via_form_link(form_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    occasion_id   bigint;
    v_unit        bigint;
    v_org         bigint;
    email_data    jsonb;
    context       jsonb;
    occasion_data jsonb;
    unit_data     jsonb;
    org_data      jsonb;
    final_result  jsonb;
BEGIN
    -- Retrieve the occasion ID from the forms table using the provided form link.
    SELECT f.occasion
      INTO occasion_id
      FROM public.forms f
      WHERE f.id = public.resolve_form_link_internal(form_link);

    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Form not found or no associated occasion.';
    END IF;

    -- Retrieve unit and organization IDs from the occasion.
    SELECT o.unit, o.organization
      INTO v_unit, v_org
      FROM public.occasions o
      WHERE o.id = occasion_id;

    -- Build a JSON context with the occasion, unit, and organization.
    context := jsonb_build_object(
                  'occasion', occasion_id,
                  'unit', v_unit,
                  'organization', v_org
               );

    -- Call the updated function with the context parameter to retrieve templates.
    email_data := public.get_all_email_templates(context);

    -- Retrieve occasion details (id and title).
    SELECT jsonb_build_object('id', o.id, 'title', o.title)
      INTO occasion_data
      FROM public.occasions o
      WHERE o.id = occasion_id;

    -- Retrieve unit details (id and title).
    SELECT jsonb_build_object('id', u.id, 'title', u.title)
      INTO unit_data
      FROM public.units u
      WHERE u.id = v_unit;

    -- Retrieve organization details (id and title).
    SELECT jsonb_build_object('id', org.id, 'title', org.title)
      INTO org_data
      FROM public.organizations org
      WHERE org.id = v_org;

    -- Build final result JSON object containing the separate objects.
    final_result := jsonb_build_object(
                      'occasion',     occasion_data,
                      'unit',         unit_data,
                      'organization', org_data,
                      'templates',    email_data
                    );

    RETURN final_result;
END;
$$;


ALTER FUNCTION public.get_all_email_templates_via_form_link(form_link text) OWNER TO postgres;

--
-- Name: get_all_email_templates_via_occasion_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_email_templates_via_occasion_link(occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
BEGIN
    -- Canonical merges may contain the same legacy link in multiple tenants.
    SELECT o.id
    INTO v_occasion_id
    FROM public.occasions o
    WHERE o.id = public.resolve_occasion_link_internal(occasion_link)
      AND o.organization = (
        SELECT ui.organization
        FROM public.user_info ui
        WHERE ui.id = auth.uid()
      );

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion not found for link: %', occasion_link;
    END IF;

    -- Call Unified Function
    RETURN public.get_entity_email_templates('occasion', v_occasion_id);
END;
$$;


ALTER FUNCTION public.get_all_email_templates_via_occasion_link(occasion_link text) OWNER TO postgres;

--
-- Name: get_all_events_for_datagrid(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_events_for_datagrid(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result_jsonb jsonb;
BEGIN
    -- 1. Security Check: Ensures the calling user has editor permissions.
    IF NOT get_is_editor_view_on_occasion(p_occasion_id) THEN
        RAISE EXCEPTION 'Insufficient permissions. User requires editor view rights for this occasion.'
            USING ERRCODE = '42501'; -- insufficient_privilege
    END IF;

    -- 2. Data Retrieval and JSON Aggregation
    SELECT
        COALESCE(jsonb_agg(event_row.data), '[]'::jsonb)
    INTO
        result_jsonb
    FROM (
        SELECT
            jsonb_build_object(
                'id', e.id,
                'aggregate_version', COALESCE(av.version, 0),
                'is_hidden', e.is_hidden,
                'title', e.title,
                'start_time', e.start_time,
                'end_time', e.end_time,
                'max_participants', e.max_participants,
                'split_for_men_women', e.split_for_men_women,
                'is_group_event', e.is_group_event,
                'type', e.type,
                'data', e.data,
                'places', CASE
                    WHEN p.id IS NULL THEN NULL::jsonb
                    ELSE jsonb_build_object('id', p.id, 'title', p.title)
                END,
                'event_groups', (
                    SELECT COALESCE(jsonb_agg(jsonb_build_object('event_parent', eg.event_parent)), '[]'::jsonb)
                    FROM public.event_groups eg
                    WHERE eg.event_child = e.id
                ),
                'event_roles', (
                    SELECT COALESCE(jsonb_agg(jsonb_build_object('role', er.role)), '[]'::jsonb)
                    FROM public.event_roles er
                    WHERE er.event = e.id
                ),
                'event_users_saved', (
                    SELECT jsonb_agg(jsonb_build_object('count', T.c))
                    FROM (SELECT count(*) AS c FROM public.event_users_saved eus WHERE eus.event = e.id) AS T
                ),
                'event_users', (
                    SELECT jsonb_agg(jsonb_build_object('count', T.c))
                    FROM (SELECT count(*) AS c FROM public.event_users eu WHERE eu.event = e.id) AS T
                )
            ) AS data
        FROM
            public.events AS e
        LEFT JOIN
            public.places AS p ON e.place = p.id
        LEFT JOIN public.client_aggregate_versions av
            ON av.aggregate_type = 'event'
           AND av.scope_type = 'occasion'
           AND av.scope_id = p_occasion_id
           AND av.aggregate_id = e.id::text
        WHERE
            e.occasion = p_occasion_id
        ORDER BY
            e.start_time ASC
    ) AS event_row;

    -- 3. Return the final JSONB array
    RETURN result_jsonb;
END;
$$;


ALTER FUNCTION public.get_all_events_for_datagrid(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_all_form_fields(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_form_fields(form_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_form_id BIGINT;
    v_occasion_id BIGINT;
    formFieldsData JSONB;
BEGIN
    -- Retrieve form ID and occasion ID
    SELECT id, occasion INTO v_form_id, v_occasion_id
    FROM public.forms
    WHERE id = public.resolve_form_link_internal(form_link);

    -- Check if form exists
    IF v_form_id IS NULL THEN
        RAISE EXCEPTION 'Form not found.';
    END IF;

    -- Check permissions
    IF NOT public.can_read_orders(v_occasion_id) THEN
        RAISE EXCEPTION 'Access Denied';
    END IF;

    -- Fetch form fields
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ff.id,
            'created_at', ff.created_at,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'form', ff.form,
            'is_hidden', ff.is_hidden,
            'order', ff."order",
            'product_type', ff.product_type,
            'is_ticket_field', ff.is_ticket_field
        ) ORDER BY COALESCE(ff."order", 0)
    ), '[]'::jsonb)
    INTO formFieldsData
    FROM public.form_fields ff
    WHERE ff.form = v_form_id
      AND ff.is_ticket_field = false
      AND ff.type <> 'ticket';

    RETURN formFieldsData;
END;
$$;


ALTER FUNCTION public.get_all_form_fields(form_link text) OWNER TO postgres;

--
-- Name: get_all_forms(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_forms(occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- Step 2: If no occasion is found, return a 404 error.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion not found'
        );
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- This assumes a function `get_is_editor_on_occasion` exists.
    IF NOT get_is_editor_view_on_occasion(v_occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view forms for this occasion.'
        );
    END IF;

    -- Step 4: Aggregate forms for the occasion into a JSONB array.
    -- The subquery for 'response_count' is now corrected to count responses from the 'eshop.orders' table.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', f.occasion,
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'response_count', (
                SELECT COUNT(*)
                FROM eshop.orders o
                WHERE (o.data->>'form')::uuid = f.key -- Correctly join forms.key with the UUID in orders.data
            )
        ) ORDER BY f.created_at
    )
    INTO forms_data
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Step 5: If no forms were found, return an empty array.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the aggregated JSON response with a 200 code.
    RETURN jsonb_build_object(
        'code', 200,
        'data', forms_data
    );
END;
$$;


ALTER FUNCTION public.get_all_forms(occasion_link text) OWNER TO postgres;

--
-- Name: get_all_forms_with_fields(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_forms_with_fields(occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    -- Find the ID of the occasion using its unique link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link)
      AND organization=(SELECT organization FROM public.user_info WHERE id=auth.uid());

    -- Step 2: If no occasion is found, return a 404 'Not Found' error.
    -- This handles cases where the occasion_link does not exist.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion not found'
        );
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- This assumes a function `get_is_editor_view_on_occasion` exists to check permissions.
    IF NOT public.can_read_form_catalog(v_occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view forms for this occasion.'
        );
    END IF;

    -- Shared administrator summary projection; transport-specific secrets are
    -- retained here for the existing UI, and removed by the bounded MCP reader.
    forms_data := public.get_form_catalog_rows_internal(v_occasion_id);

    -- Step 5: If no forms were found for the occasion, return an empty JSON array.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the aggregated JSON response with a 200 'OK' status code.
    RETURN jsonb_build_object(
        'code', 200,
        'data', forms_data
    );
END;
$$;


ALTER FUNCTION public.get_all_forms_with_fields(occasion_link text) OWNER TO postgres;

--
-- Name: get_all_occasions(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_occasions(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  occasion_data jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'description', o.description,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'form', (
         SELECT row_to_json(f)
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
  )
  INTO occasion_data
  FROM public.occasions o
  WHERE o.unit = unit_id
    AND o.is_hidden = false;

  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', occasion_data
  );
END;
$$;


ALTER FUNCTION public.get_all_occasions(unit_id bigint) OWNER TO postgres;

--
-- Name: get_all_occasions_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_occasions_for_edit(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  occasion_data jsonb;
BEGIN
  -- Step 1: Verify that the unit exists
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  -- Step 2: Check if the caller is a manager or editor of the unit
  IF NOT public.can_read_legacy_unit_occasion_catalog(unit_id) THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Step 3: Aggregate occasions for the unit including the first form for each occasion.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'description', o.description,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'form', (
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', f.blueprint,
           'header', f.header,
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o
  WHERE o.unit = unit_id;

  -- Step 4: If no occasions were found, return an empty array.
  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON response with a 200 code.
  RETURN jsonb_build_object(
    'code', 200,
    'data', occasion_data
  );
END;
$$;


ALTER FUNCTION public.get_all_occasions_for_edit(unit_id bigint) OWNER TO postgres;

--
-- Name: get_all_occasions_for_edit_v182(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_occasions_for_edit_v182(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  occasion_data jsonb;
BEGIN
  -- Step 1: Verify that the unit exists. If not, raise a 'not found' exception.
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'PGRST001';
  END IF;

  -- Step 2: Check if the caller has sufficient permissions. If not, raise an 'insufficient privilege' exception.
  IF NOT public.can_read_legacy_unit_occasion_catalog(unit_id) THEN
    RAISE EXCEPTION 'Insufficient permissions for this unit' USING ERRCODE = '42501';
  END IF;

  -- Step 3: Aggregate occasions for the unit, including forms, order stats, and user data.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'stats', jsonb_build_object(
          'total', COALESCE(order_stats.total, 0),
          'storno', COALESCE(order_stats.storno, 0),
          'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
          'ordered', COALESCE(order_stats.ordered, 0),
          'used', COALESCE(order_stats.used, 0),
          'users', COALESCE(user_stats.user_count, 0)
      ),
      'form', (
         -- This subquery fetches the first associated form for the occasion.
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', f.blueprint,
           'header', f.header,
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o
  LEFT JOIN (
      -- This subquery calculates all required order counts in a single pass over the orders table.
      SELECT
          occasion,
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE state = 'storno') AS storno,
          COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
          COUNT(*) FILTER (WHERE state = 'ordered') AS ordered,
          COUNT(*) FILTER (WHERE state = 'used') AS used
      FROM eshop.orders
      WHERE occasion IS NOT NULL
      GROUP BY occasion
  ) AS order_stats ON o.id = order_stats.occasion
  LEFT JOIN (
      -- New: This subquery aggregates occasion users and provides their count.
      SELECT
          occasion,
          COUNT(*) as user_count
      FROM public.occasion_users
      GROUP BY occasion
  ) AS user_stats ON o.id = user_stats.occasion
  WHERE o.unit = unit_id;

  -- Step 4: If no occasions were found, return an empty JSON array.
  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON data directly.
  RETURN occasion_data;
END;
$$;


ALTER FUNCTION public.get_all_occasions_for_edit_v182(unit_id bigint) OWNER TO postgres;

--
-- Name: get_all_occasions_for_edit_v212(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_occasions_for_edit_v212(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  occasion_data jsonb;
  org_id bigint;
  unit_catalog_reader boolean;
BEGIN
  -- Step 1: Verify that the unit exists and retrieve its Organization ID.
  SELECT organization INTO org_id
  FROM public.units
  WHERE id = unit_id;

  -- If org_id is null, the unit does not exist.
  IF org_id IS NULL THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'PGRST001';
  END IF;

  -- Step 2: Check permissions
  IF NOT public.can_read_unit_occasion_catalog(unit_id) THEN
    RAISE EXCEPTION 'Insufficient permissions for this unit' USING ERRCODE = '42501';
  END IF;

  -- One actor/unit fact for the whole catalogue, not a permission query
  -- repeated for each occasion. Occasion membership remains row scoped.
  SELECT coalesce((SELECT public.unit_discovery_rule(m.is_editor,m.is_manager,m.is_editor_view)
    FROM public.unit_users m WHERE m.unit=unit_id AND m."user"=auth.uid()),false)
    INTO unit_catalog_reader;

  -- Scope all aggregate work before counting tickets/users in other units.
  WITH visible_occasions AS MATERIALIZED (
    SELECT o.* FROM public.occasions o
    WHERE o.unit = unit_id AND (unit_catalog_reader OR EXISTS (
      SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=o.id
        AND ou."user"=auth.uid()
        AND public.occasion_staff_navigation_rule(ou.is_manager,ou.is_editor,
          ou.is_editor_view,ou.is_editor_order,ou.is_editor_order_view)))
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data #- '{heavy_field}', -- OPTIMIZATION: Remove heavy_field
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', (
          SELECT jsonb_agg(
              jsonb_build_object('code',elem->'code','is_enabled',elem->'is_enabled')
          )
          FROM jsonb_array_elements(o.features) elem
      ),
      'stats', jsonb_build_object(
          'total', COALESCE(ticket_stats.total, 0),
          'storno', COALESCE(ticket_stats.storno, 0),
          'paid_or_sent', COALESCE(ticket_stats.paid_or_sent, 0),
          'ordered', COALESCE(ticket_stats.ordered, 0),
          'used', COALESCE(ticket_stats.used, 0),
          'users', COALESCE(user_stats.user_count, 0)
      ),
      'sale_forms', public.get_occasion_sale_forms_internal(o.id),
      'form', (
         -- This subquery fetches the first associated form for the occasion.
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', NULL, -- OPTIMIZATION: Remove blueprint
           'header', NULL, -- OPTIMIZATION: Remove header
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM visible_occasions o

  -- Ticket Stats
  LEFT JOIN (
      SELECT
          occasion,
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE state = 'storno') AS storno,
          COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
          COUNT(*) FILTER (WHERE state = 'ordered') AS ordered,
          COUNT(*) FILTER (WHERE state = 'used') AS used
      FROM eshop.tickets
      WHERE occasion IN (SELECT id FROM visible_occasions)
      GROUP BY occasion
  ) AS ticket_stats ON o.id = ticket_stats.occasion

  -- User Stats
  LEFT JOIN (
      SELECT
          ou.occasion,
          COUNT(*) as user_count
      FROM public.occasion_users ou
      LEFT JOIN public.organization_users org_u
          ON ou."user" = org_u."user"
          AND org_u.organization = org_id
      WHERE ou.occasion IN (SELECT id FROM visible_occasions)
        AND (org_u.is_hidden IS NOT TRUE)
      GROUP BY ou.occasion
  ) AS user_stats ON o.id = user_stats.occasion
;

  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  RETURN occasion_data;
END;
$$;


ALTER FUNCTION public.get_all_occasions_for_edit_v212(unit_id bigint) OWNER TO postgres;

--
-- Name: get_all_service_items(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_service_items(oc bigint, type text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  result JSONB;
BEGIN
  result := jsonb_build_object(
    'code', 200,
    'data', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'code', item->>'code',
          'title', item->>'title',
          'reference', (item->>'reference')::BIGINT
        )
      )
      FROM public.occasions,
           jsonb_array_elements(occasions.services->type) AS item
      WHERE occasions.id = oc
        AND occasions.services ? type
    ), '[]'::jsonb)  -- Use an empty JSON array if no items are found
  );

  RETURN result;
END;
$$;


ALTER FUNCTION public.get_all_service_items(oc bigint, type text) OWNER TO postgres;

--
-- Name: get_all_tickets_for_scan(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_tickets_for_scan(scan_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    occasion_id_val bigint;
    result jsonb; policy jsonb; max_items bigint; max_bytes bigint; found_items bigint;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1(NULL) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    SELECT o.id
    INTO occasion_id_val
    FROM public.occasions o
    JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
    WHERE oh.secret = scan_code
    LIMIT 1;

    IF occasion_id_val IS NULL THEN
         PERFORM public.admit_scan_access_v1(NULL,false);
         RETURN jsonb_build_object('code',401,'message','invalid_scan_code');
    END IF;

    IF NOT public.admit_scan_access_v1(occasion_id_val,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    policy:=public.abuse_effective_rules_v1('scan.export',(SELECT unit FROM public.occasions WHERE id=occasion_id_val),(SELECT organization FROM public.occasions WHERE id=occasion_id_val));
    SELECT (r->>'base_limit')::bigint INTO max_items FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.items';
    SELECT (r->>'base_limit')::bigint INTO max_bytes FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.bytes';
    IF max_items IS NULL OR max_bytes IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
    SELECT count(*) INTO found_items FROM (SELECT id FROM eshop.tickets WHERE occasion=occasion_id_val LIMIT max_items+1) bounded;
    IF found_items>max_items THEN RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded'); END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', t.id,
            'ticket_symbol', t.ticket_symbol,
            'state', t.state,
            'batch', (SELECT jsonb_build_object('title',b.title) FROM eshop.ticket_batch_items i JOIN eshop.ticket_batches b ON b.id=i.batch_id WHERE i.ticket_id=t.id AND b.occasion=occasion_id_val),
            'related_order', jsonb_build_object(
                 'data', t.data
            )
        ) 
    )
    INTO result
    FROM (
        SELECT DISTINCT ON (t.id) t.id, t.ticket_symbol, t.state, o.data
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE o.occasion = occasion_id_val
          AND t.state IS DISTINCT FROM 'storno' AND t.state IS DISTINCT FROM 'waitlisted'
          AND t.ticket_symbol IS NOT NULL AND o.state IS DISTINCT FROM 'waitlisted'
          AND NOT public.provider_ticket_requires_online_internal(t.id)
        ORDER BY t.id
    ) t;

    IF octet_length(result::text)>max_bytes THEN RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded'); END IF;
    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_all_tickets_for_scan(scan_code text) OWNER TO postgres;

--
-- Name: get_all_user_basics_for_scan(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_user_basics_for_scan(scan_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  oid bigint;
  org_id bigint;
  user_basics jsonb;
BEGIN
  -----------------------------------------------------
  -- 1. Validate Code & Get Occasion AND Organization ID
  -----------------------------------------------------
  SELECT o.id, o.organization INTO oid, org_id
  FROM public.get_scanner_occasion_for_scan_code_internal(scan_code) o
  LIMIT 1;

  -- Security Check: If ID is null, the code is invalid
  IF oid IS NULL THEN
      RAISE EXCEPTION 'Invalid scan code';
  END IF;

  -----------------------------------------------------
  -- 2. Retrieve User Data for this Occasion
  -----------------------------------------------------
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'email_readonly', parent_ui.email_readonly
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user" AND public.organization_member_visible_internal(org_id,parent_ui.id)
      )
    )
  ) INTO user_basics
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oid
  JOIN public.occasion_users uo ON ui.id = uo."user"

  -- This keeps the user in the list even if they have no record in organization_users
  LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id

  WHERE uo.occasion = oid

  -- "IS NOT TRUE" covers two cases:
  -- 1. is_hidden is FALSE
  -- 2. is_hidden is NULL (record doesn't exist)
  AND (ou.is_hidden IS NOT TRUE);

  -----------------------------------------------------
  -- 3. Handle Empty Results & Return
  -----------------------------------------------------
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  RETURN user_basics;
END;
$$;


ALTER FUNCTION public.get_all_user_basics_for_scan(scan_code text) OWNER TO postgres;

--
-- Name: get_all_user_basics_from_occasion(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_user_basics_from_occasion(oc bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  org_id bigint;
  user_basics jsonb;
BEGIN
  -----------------------------------------------------
  -- 1. Permission Check
  -----------------------------------------------------
  -- Check if the user is a manager, editor, or approver for the occasion
  IF (SELECT public.can_read_participant_contacts(oc)) <> TRUE THEN
      RETURN jsonb_build_object('code', 403);
  END IF;

  -----------------------------------------------------
  -- 2. Get Organization ID
  -----------------------------------------------------
  -- We need the org_id to check the specific organization_users table
  SELECT organization INTO org_id
  FROM public.occasions
  WHERE id = oc;

  -----------------------------------------------------
  -- 3. Aggregate User Data
  -----------------------------------------------------
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'email_readonly', parent_ui.email_readonly
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user" AND public.organization_member_visible_internal(org_id,parent_ui.id)
      )
    )
  ) INTO user_basics
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oc
  JOIN public.occasion_users uo ON ui.id = uo."user"

  -- LEFT JOIN to check visibility settings
  LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id

  WHERE uo.occasion = oc

  -- FILTER: Exclude only if explicitly hidden
  -- (NULL or FALSE means visible)
  AND (ou.is_hidden IS NOT TRUE);

  -----------------------------------------------------
  -- 4. Handle Empty Results & Return
  -----------------------------------------------------
  -- If no users are found, return an empty array
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', user_basics
  );
END;
$$;


ALTER FUNCTION public.get_all_user_basics_from_occasion(oc bigint) OWNER TO postgres;

--
-- Name: get_all_user_basics_from_occasion_unit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_user_basics_from_occasion_unit(p_unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  user_basics jsonb;
  org_id bigint;
BEGIN
  -- Step 1: Retrieve the organization for the given unit
  SELECT organization INTO org_id
  FROM public.units
  WHERE id = p_unit_id;

  -- If the unit does not exist, return a 404 error
  IF org_id IS NULL THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'P0002'; -- no_data_found
  END IF;

  -- Step 2: Check if the caller is a manager of the unit
  IF public.can_manage_unit_users(p_unit_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501'; -- insufficient_privilege
  END IF;

  -- Step 3: Aggregate user information and roles for sorting
  WITH relevant_occasions AS (
    -- Occasions under the same unit
    SELECT id AS occasion_id FROM public.occasions WHERE unit = p_unit_id
    UNION
    -- Occasions where the current user has privileged rights
    SELECT occasion AS occasion_id
    FROM public.occasion_users
    WHERE "user" = auth.uid()
      AND public.participant_contacts_read_rule(is_editor,is_manager,is_approver)
  ),
  raw_user_roles AS (
    -- Roles from occasion_users in relevant occasions
    SELECT
      uo."user",
      uo.is_manager,
      uo.is_editor,
      uo.is_editor_order,
      uo.is_editor_view,
      uo.is_editor_order_view,
      uo.is_approver
    FROM public.occasion_users uo
    WHERE uo.occasion IN (SELECT occasion_id FROM relevant_occasions)

    UNION ALL

    -- Roles from unit_users (mapping available columns)
    SELECT
      uu."user",
      uu.is_manager,
      uu.is_editor,
      false AS is_editor_order,       -- Not in unit_users
      uu.is_editor_view,
      false AS is_editor_order_view,  -- Not in unit_users
      false AS is_approver            -- Not in unit_users
    FROM public.unit_users uu
    WHERE uu.unit = p_unit_id
  ),
  aggregated_user_roles AS (
    -- Consolidate roles per user (taking true if any occurrence is true)
    SELECT
      "user",
      bool_or(is_manager) AS is_manager,
      bool_or(is_editor) AS is_editor,
      bool_or(is_editor_order) AS is_editor_order,
      bool_or(is_editor_view) AS is_editor_view,
      bool_or(is_editor_order_view) AS is_editor_order_view,
      bool_or(is_approver) AS is_approver
    FROM raw_user_roles
    GROUP BY "user"
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'email_readonly', parent_ui.email_readonly
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user" AND public.organization_member_visible_internal(org_id,parent_ui.id)
      )
    ) ORDER BY
      aur.is_manager DESC,
      aur.is_editor DESC,
      aur.is_editor_order DESC,
      aur.is_editor_view DESC,
      aur.is_editor_order_view DESC,
      aur.is_approver DESC,
      ui.surname ASC NULLS LAST,
      ui.name ASC NULLS LAST
  ) INTO user_basics
  FROM public.user_info ui
  JOIN aggregated_user_roles aur ON ui.id = aur."user"
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion
    AND uc.occasion IN (SELECT id FROM public.occasions WHERE unit=p_unit_id)
  LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id
  WHERE (ou.is_hidden IS NOT TRUE);

  -- Step 4: Handle cases with no users found
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON response
  RETURN user_basics;
END;
$$;


ALTER FUNCTION public.get_all_user_basics_from_occasion_unit(p_unit_id bigint) OWNER TO postgres;

--
-- Name: get_all_user_group_info(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_user_group_info(p_occasion_id bigint, p_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    groups_json jsonb;
    game_defs_json jsonb;
    result_data jsonb;
BEGIN
    -- Authorization Check:
    -- The user must have editor view permissions for the requested occasion.
    -- This function call is the security gate for this entire operation.
    IF NOT get_is_editor_view_on_occasion(p_occasion_id) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to view user groups for this occasion');
    END IF;

    -- If authorized, proceed to fetch the data.
    SELECT
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ugi.id,
                'title', ugi.title,
                'description', ugi.description,
                'type', ugi.type,
                'data', ugi.data,
                'leader', ugi.leader,
                'place', ugi.place,
                'user_info', ( -- Nested leader object
                    SELECT jsonb_build_object('id', ui_leader.id, 'name', ui_leader.name, 'surname', ui_leader.surname)
                    FROM public.user_info ui_leader
                    WHERE ui_leader.id = ugi.leader
                ),
                'places', ( -- Nested place object
                    SELECT jsonb_strip_nulls(jsonb_build_object(
                        'id', p.id,
                        'title', p.title,
                        'description', p.description,
                        'type', p.type,
                        'created_at', p.created_at,
                        'coordinates', p.coordinates,
                        'is_hidden', p.is_hidden,
                        'updated_at', p.updated_at,
                        'occasion', p.occasion,
                        'order', p."order",
                        'icon', p.icon,
                        'unit', p.unit
                    ))
                    FROM public.places p
                    WHERE p.id = ugi.place
                ),
                'user_groups', ( -- Nested array of participants
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'user_info', jsonb_build_object('id', p_ui.id, 'name', p_ui.name, 'surname', p_ui.surname)
                        )
                    ), '[]'::jsonb)
                    FROM public.user_groups ug
                    JOIN public.user_info p_ui ON ug."user" = p_ui.id
                    WHERE ug."group" = ugi.id
                )
            )
        ), '[]'::jsonb)
    INTO groups_json
    FROM public.user_group_info ugi
    WHERE ugi.occasion = p_occasion_id
      AND (p_type IS NULL AND ugi.type IS NULL OR ugi.type = p_type);

    -- If the requested type is 'game', also fetch the game definitions (checkpoints).
    IF p_type = 'game' THEN
        SELECT jsonb_object_agg(info.id, info.title)
        INTO game_defs_json
        FROM public.information info
        WHERE info.type = 'game' AND info.occasion = p_occasion_id;
    END IF;

    -- Combine the results into a single data object.
    result_data := jsonb_build_object(
        'groups', groups_json,
        'game_definitions', game_defs_json
    );

    -- Return the data in a structured response on success.
    RETURN jsonb_build_object('code', 200, 'data', result_data);

EXCEPTION WHEN OTHERS THEN
    -- Catch any unexpected errors during execution.
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_all_user_group_info(p_occasion_id bigint, p_type text) OWNER TO postgres;

--
-- Name: get_all_user_groups(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_user_groups(p_occasion_id bigint, p_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    groups_json jsonb;
    game_defs_json jsonb;
    places_json jsonb;
    result_data jsonb;
BEGIN
    -- Authorization Check: User must have editor view permissions for the occasion.
    IF NOT get_is_editor_view_on_occasion(p_occasion_id) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    SELECT COALESCE(
        jsonb_agg(to_jsonb(p) ORDER BY p."order" NULLS LAST, p.title),
        '[]'::jsonb
    )
    INTO places_json
    FROM public.places p
    WHERE p.occasion = p_occasion_id
      AND NOT p.is_hidden
      AND p.coordinates->'latLng'->>'lat' IS NOT NULL
      AND p.coordinates->'latLng'->>'lng' IS NOT NULL;

    -- If authorized, fetch all matching groups for the occasion.
    SELECT
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ugi.id,
                'title', ugi.title,
                'description', ugi.description,
                'type', ugi.type,
                'data', ugi.data,
                'place', ugi.place,
                'places', ( -- Nested place object
                    SELECT row_to_json(p)::jsonb
                    FROM public.places p
                    WHERE p.id = ugi.place
                ),
                'user_groups', ( -- Nested array of participants with admin status
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'is_admin', ug.is_admin,
                            -- The user_info object now only contains id, name, and surname.
                            'user_info', jsonb_build_object(
                                'id', p_ui.id,
                                'name', p_ui.name,
                                'surname', p_ui.surname
                            )
                        )
                    ), '[]'::jsonb)
                    FROM public.user_groups ug
                    JOIN public.user_info p_ui ON ug."user" = p_ui.id
                    WHERE ug."group" = ugi.id AND public.occasion_member_visible_internal(ugi.occasion,p_ui.id)
                )
            )
        ), '[]'::jsonb)
    INTO groups_json
    FROM public.user_group_info ugi
    WHERE ugi.occasion = p_occasion_id
      AND (p_type IS NULL AND ugi.type IS NULL OR ugi.type = p_type);

    -- If the requested type is 'game', also fetch the game definitions (checkpoints).
    IF p_type = 'game' THEN
        SELECT jsonb_object_agg(info.id, info.title)
        INTO game_defs_json
        FROM public.information info
        WHERE info.type = 'game' AND info.occasion = p_occasion_id;
    END IF;

    -- Combine the results into a single data object.
    result_data := jsonb_build_object(
        'groups', groups_json,
        'game_definitions', game_defs_json,
        'places', places_json
    );

    -- Return the data directly on success.
    RETURN result_data;
END;
$$;


ALTER FUNCTION public.get_all_user_groups(p_occasion_id bigint, p_type text) OWNER TO postgres;

--
-- Name: get_all_users_from_unit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_users_from_unit(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  user_basics jsonb;
  org_id bigint;
BEGIN
  -- Step 1: Get the Organization ID for this Unit
  -- This also serves as a check to see if the unit exists
  SELECT organization INTO org_id
  FROM public.units
  WHERE id = unit_id;

  -- If org_id is null, the unit likely doesn't exist
  -- (Assuming all units belong to an organization)
  IF org_id IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
  END IF;

  -- Step 2: Permission Check
  IF NOT public.can_read_unit_users(unit_id) THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Step 3: Retrieve Users with Hidden Filter
  SELECT jsonb_agg(user_info)
  INTO user_basics
  FROM (
    SELECT jsonb_build_object(
      'user', ui.id,
      'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='unit_user' AND scope_type='unit' AND scope_id=unit_id AND aggregate_id=ui.id::text),0),
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'unit', uu.unit,
      'is_manager', uu.is_manager,
      'is_editor', uu.is_editor,
      'is_editor_view', uu.is_editor_view,
      'data', uu.data
    ) AS user_info
    FROM public.unit_users uu
    JOIN public.user_info ui ON uu."user" = ui.id

    -- Left Join to check organization-wide visibility settings
    LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id

    WHERE uu.unit = unit_id

    -- Filter out hidden users
    -- (ou.is_hidden IS NOT TRUE) includes FALSE (visible) and NULL (no record found, so visible)
    AND (ou.is_hidden IS NOT TRUE)

    ORDER BY uu.created_at DESC
  ) t;

  -- Step 4: Handle Empty Results
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object('code', 200, 'data', user_basics);
END;
$$;


ALTER FUNCTION public.get_all_users_from_unit(unit_id bigint) OWNER TO postgres;

--
-- Name: get_all_viewable_forms_for_copying(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_all_viewable_forms_for_copying() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    forms_data JSONB;
    user_id UUID := auth.uid();
BEGIN
    -- Step 1: Aggregate forms into a JSONB array based on the user's combined permissions.
    -- The user can see forms from occasions where they are a direct editor,
    -- or from any occasion within a unit where they are a unit editor.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', jsonb_build_object(
                'id', o.id,
                'title', o.title,
                'link', o.link,
                'start_time', o.start_time,
                'end_time', o.end_time
            ),
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'stats', jsonb_build_object(
                'total', COALESCE(order_stats.total, 0),
                'storno', COALESCE(order_stats.storno, 0),
                'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
                'ordered', COALESCE(order_stats.ordered, 0)
            )
        ) ORDER BY o.start_time DESC, f.created_at DESC
    )
    INTO forms_data
    FROM public.forms f
    JOIN public.occasions o ON f.occasion = o.id
    LEFT JOIN (
        -- Subquery to calculate order statistics for each form.
        SELECT
            (data->>'form')::uuid AS form_key,
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE state = 'storno') AS storno,
            COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
            COUNT(*) FILTER (WHERE state = 'ordered') AS ordered
        FROM eshop.orders
        WHERE data->>'form' IS NOT NULL
        GROUP BY form_key
    ) AS order_stats ON f.key = order_stats.form_key
    WHERE f.occasion IN (
        -- Subquery to get all occasion IDs the user has editor view access to.
        -- This includes direct occasion permissions.
        SELECT ou.occasion
        FROM public.occasion_users ou
        WHERE ou.user = user_id AND ou.is_editor_view = TRUE

        UNION

        -- And permissions inherited from unit-level roles.
        SELECT o_unit.id
        FROM public.occasions o_unit
        JOIN public.unit_users uu ON o_unit.unit = uu.unit
        WHERE uu.user = user_id AND uu.is_editor_view = TRUE
    );

    -- Step 2: If no forms are found, return an empty JSON array.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 3: Return the aggregated data.
    RETURN forms_data;
END;
$$;


ALTER FUNCTION public.get_all_viewable_forms_for_copying() OWNER TO postgres;

