--
-- Name: get_app_config_v218(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_app_config_v218(data_in jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    org_id bigint := (data_in->>'organization')::bigint;
    link_txt text := data_in->>'link';
    form_link text := data_in->>'form_link';
    unit_id bigint := (data_in->>'unit_id')::bigint;
    platform_info jsonb := data_in->'platform';
    platform_name text := platform_info->>'platform';
    occasionId bigint;
    default_unit bigint;
    editor_unit_id bigint;
    is_open_bool BOOLEAN;
    is_app_supported_bool BOOLEAN := FALSE;
    occasion_user occasion_users%rowtype;
    unit_user unit_users%rowtype;
    is_admin_bool BOOLEAN;
    v_organization_admin boolean := false;
    v_context_organization public.organizations%ROWTYPE;
    v_context_occasion public.occasions%ROWTYPE;
    v_membership_added boolean := false;
    v_demo boolean := false;
    v_demo_read boolean := false;
    v_demo_unit_ids bigint[];
    occasion_link text;
    occasion_unit bigint;
    bank_account_ids bigint[];
    bank_capabilities jsonb;
    occasion_json jsonb;
    unit_json jsonb;
    user_info_json jsonb;
    org_json jsonb;
    user_groups_json jsonb;
    is_editor_view_on_occasion_bool BOOLEAN;
    user_occasions_json jsonb;
    user_units_json jsonb;
    current_user_id UUID := auth.uid();
BEGIN
    -- A direct unit link must stay inside the requested tenant.
    IF unit_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.units u
        WHERE u.id = unit_id AND u.organization = org_id
    ) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;

    SELECT * INTO v_context_organization FROM public.organizations WHERE id=org_id;
    v_organization_admin := public.can_manage_organization_settings(org_id);

    -- Log the request details in log_app_config table
    INSERT INTO public.log_app_config (organization, platform)
    VALUES (org_id, platform_info);

    -- Map "pwa" to "web" for platform consistency
    IF platform_name = 'pwa' THEN
        platform_name := 'web';
    END IF;

    -- =========================================================
    -- RESOLVE CONTEXT (Occasion vs Unit)
    -- Priority: Form/Link > Representative Occasion > Unit ID > Default Occasion
    -- =========================================================

    -- 1. Try to find occasion via form_link
    IF form_link IS NOT NULL AND form_link <> '' THEN
        SELECT o.* INTO v_context_occasion
        FROM public.forms f
        JOIN public.occasions o ON f.occasion = o.id
        WHERE f.id = public.resolve_form_link_internal(form_link)
          AND o.organization = org_id;
        occasionId := v_context_occasion.id;
        occasion_link := v_context_occasion.link;
        IF occasionId IS NULL THEN
            RETURN jsonb_build_object('code',404,'message','Form not found');
        END IF;
    END IF;

    -- 2. If no occasion found yet, try via link_txt
    IF occasionId IS NULL AND link_txt IS NOT NULL AND link_txt <> '' THEN
        SELECT o.* INTO v_context_occasion
        FROM public.occasions o
        WHERE o.id = public.resolve_occasion_link_internal(link_txt,org_id)
          AND o.organization = org_id;
        occasionId := v_context_occasion.id;
        occasion_link := v_context_occasion.link;

        -- If link_txt is provided but *not* found, this is a hard 404.
        IF occasionId IS NULL THEN
            RETURN jsonb_build_object(
                'code', 404,
                'message', 'Occasion not found'
            );
        END IF;
    END IF;

    -- 3. If no specific link found, check for REPRESENTATIVE OCCASION
    IF occasionId IS NULL AND unit_id IS NULL THEN
        occasionId := (v_context_organization.data->>'REPRESENTATIVE_OCCASION')::bigint;

        -- If found, fetch its link for consistency
        IF occasionId IS NOT NULL THEN
            SELECT link INTO occasion_link
            FROM occasions
            WHERE id = occasionId AND organization = org_id;
        END IF;
    END IF;

    -- 4. If no occasion (and no Representative Occasion), try to use unit_id
    IF occasionId IS NULL AND unit_id IS NOT NULL THEN
        occasionId := NULL; -- Ensure no occasion is loaded.

        default_unit := unit_id;

        SELECT jsonb_build_object('id', u.id, 'title', u.title, 'data', public.form_measurement_unit_data_internal(u.id,u.data))
            INTO unit_json
        FROM units u
        WHERE u.id = default_unit;

        SELECT *
            INTO unit_user
        FROM unit_users
        WHERE unit = default_unit
            AND "user" = current_user_id;

    -- If no occasion and no unit found yet, try Default Occasion
    ELSIF occasionId IS NULL THEN
        -- Try to get the DEFAULT_OCCASION (Representative was already checked in step 3)
        occasionId := (v_context_organization.data->>'DEFAULT_OCCASION')::bigint;

        IF occasionId IS NOT NULL THEN
            -- Default occasion exists; fetch its link
            SELECT link
              INTO occasion_link
            FROM occasions
            WHERE id = occasionId AND organization = org_id;
        END IF;
    END IF;

    -- =========================================================
    -- GATHER DATA
    -- =========================================================

    IF occasionId IS NOT NULL THEN
        -- Process occasion-related queries only if an occasion was determined

        -- Link/form resolution already loaded this exact tenant-bound row.
        -- Reuse it within the request instead of reading it a second time.
        IF v_context_occasion.id IS DISTINCT FROM occasionId THEN
          SELECT o.* INTO v_context_occasion FROM public.occasions o
            WHERE o.id=occasionId AND o.organization=org_id;
        END IF;
        IF v_context_occasion.id IS NULL THEN
          RETURN jsonb_build_object('code',404,'message','Occasion not found');
        END IF;
        is_open_bool := v_context_occasion.is_open;
        occasion_unit := v_context_occasion.unit;
        v_demo := public.is_demo_occasion(occasionId);
        v_demo_read := CASE WHEN v_demo THEN public.can_read_demo_occasion(occasionId) ELSE false END;
        IF v_demo AND NOT v_demo_read THEN
            RETURN jsonb_build_object('code',403,'message','Demo access denied');
        END IF;

        -- Get the occasion user record if it exists
        SELECT *
          INTO occasion_user
        FROM occasion_users
        WHERE occasion = occasionId
          AND "user" = current_user_id;

        -- Get the unit user record if it exists
        SELECT *
          INTO unit_user
        FROM unit_users
        WHERE unit = occasion_unit
          AND "user" = current_user_id;

        -- Check if the current user is an admin on the occasion
        is_admin_bool := public.active_membership(
          v_organization_admin,v_demo);

        -- Check if the current user has editor_view permissions on the occasion
        is_editor_view_on_occasion_bool := public.readable_membership(occasion_user.is_editor_view,v_demo,v_demo_read);

        -- Retrieve IS_APP_SUPPORTED from Organization data. Defaults to FALSE.
        is_app_supported_bool := coalesce((v_context_organization.data->>'IS_APP_SUPPORTED')::boolean,false);

        -- If the occasion is not open, enforce access restrictions
        -- BUT bypass this check if is_app_supported_bool is FALSE.
        IF is_open_bool = FALSE AND is_app_supported_bool = TRUE THEN
            IF NOT public.context_private_access_rule(is_editor_view_on_occasion_bool,
               public.can_read_orders(occasionId),public.get_is_editor_on_unit(occasion_unit)) THEN
                RETURN jsonb_build_object(
                    'code', 403,
                    'message', 'Access forbidden',
                    'link', occasion_link,
                    'unit_user', COALESCE(to_jsonb(unit_user)::jsonb, NULL)
                );
            END IF;
        END IF;

        -- If the occasion user record is not found and the user is authenticated, add the user to the occasion
        IF occasion_user IS NULL AND current_user_id IS NOT NULL AND NOT public.is_demo_occasion(occasionId) THEN
            IF is_app_supported_bool IS TRUE
               OR public.unit_discovery_rule(unit_user.is_editor,unit_user.is_manager,unit_user.is_editor_view) THEN
                PERFORM add_user_to_occasion(occasionId, current_user_id);
                v_membership_added := true;

                SELECT *
                  INTO occasion_user
                FROM occasion_users
                WHERE occasion = occasionId
                  AND "user" = current_user_id;
            END IF;
        END IF;
    ELSE
        -- If no occasion is set (because a specific unit was used and no Rep Occasion existed), use the unit as the context
        occasion_unit := default_unit;
        is_admin_bool := false;
    END IF;

    -- Retrieve unit_user again in case the user was added and now belongs to the unit
    IF unit_user IS NULL AND occasion_unit IS NOT NULL AND current_user_id IS NOT NULL THEN
        SELECT *
          INTO unit_user
        FROM unit_users
        WHERE unit = occasion_unit
          AND "user" = current_user_id;
    END IF;

    -- Request-local facts for this projection only. Writers independently
    -- reauthorize against the live registry; this is never a permission cache.
    SELECT coalesce(array_agg(demo.unit_id),'{}'::bigint[]) INTO v_demo_unit_ids
      FROM public.demo_unit_ids_internal() demo;

    -- Fetch list of bank account IDs where the user is an admin
    SELECT array_agg(m.bank_account),jsonb_object_agg(m.bank_account,
      CASE WHEN public.bank_account_write_rule(m.is_admin,managed.bank_account IS NOT NULL,protected.bank_account IS NOT NULL)
        THEN public.bank_context_capabilities(true,true,false)
        ELSE public.bank_context_capabilities(false,false,false) END)
      INTO bank_account_ids,bank_capabilities
    FROM eshop.bank_account_users m
    LEFT JOIN (SELECT DISTINCT link.bank_account FROM eshop.unit_bank_accounts link
      JOIN public.unit_users membership ON membership.unit=link.unit
      WHERE membership."user"=current_user_id AND membership.is_manager
        AND NOT membership.unit=ANY(v_demo_unit_ids)) managed
      ON managed.bank_account=m.bank_account
    LEFT JOIN (SELECT DISTINCT bank_account FROM public.demo_occasions) protected
      ON protected.bank_account=m.bank_account
    WHERE m."user"=current_user_id AND m.is_admin=true;

    -- Fetch full occasion details as a JSON object if an occasion is set
    IF occasionId IS NOT NULL THEN
        IF v_membership_added THEN
            SELECT to_jsonb(o) INTO occasion_json FROM public.occasions o WHERE o.id=occasionId;
        ELSE
            occasion_json := to_jsonb(v_context_occasion);
        END IF;
    ELSE
        occasion_json := '{}'::jsonb;
    END IF;

    -- Fetch full unit details as a JSON object
    IF occasion_unit IS NOT NULL AND unit_json IS NULL THEN
        SELECT jsonb_build_object('id', u.id, 'title', u.title, 'data', public.form_measurement_unit_data_internal(u.id,u.data))
          INTO unit_json
        FROM units u
        WHERE u.id = occasion_unit;
    ELSE
        IF unit_json IS NULL THEN
            unit_json := '{}'::jsonb;
        END IF;
    END IF;

    -- Fetch occasions for the user based on the specified logic
    IF occasion_unit IS NOT NULL AND current_user_id IS NOT NULL THEN
        IF public.occasion_list_read_rule(is_editor_view_on_occasion_bool,
          current_user_id IS NOT NULL AND public.get_is_editor_on_unit(occasion_unit)) THEN
            -- If user is an editor or unit editor, get all occasions for the unit
            SELECT jsonb_agg(jsonb_build_object('id', o.id, 'title', o.title, 'link', o.link, 'start_time', o.start_time, 'end_time', o.end_time) ORDER BY o.start_time DESC)
            INTO user_occasions_json
            FROM (
                SELECT * FROM public.occasions
                WHERE unit = occasion_unit
                ORDER BY start_time DESC
                LIMIT 100
            ) o;
        ELSE
            -- Otherwise, get only occasions the user is explicitly on for that unit
            -- AND where they have privileged access (manager, editor, etc.)
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', o.id,
                    'title', o.title,
                    'link', o.link,
                    'start_time', o.start_time,
                    'end_time', o.end_time
                ) ORDER BY o.start_time DESC
            )
            INTO user_occasions_json
            FROM (
                 SELECT o.*
                 FROM public.occasions o
                 JOIN public.occasion_users ou ON ou.occasion = o.id
                 WHERE ou."user" = current_user_id
                 AND o.unit = occasion_unit
                 AND public.occasion_staff_navigation_rule(ou.is_manager,ou.is_editor,ou.is_editor_view,ou.is_editor_order,ou.is_editor_order_view)
                 ORDER BY o.start_time DESC
                 LIMIT 100
            ) o;
        END IF;
    END IF;

    -- Fetch units for the user based on unit rights or occasion rights
    SELECT jsonb_agg(jsonb_build_object('id', u.id, 'title', u.title) ORDER BY u.title)
    INTO user_units_json
    FROM public.units u
    WHERE u.organization = org_id AND (
        EXISTS (
            SELECT 1
            FROM public.unit_users uu
            WHERE uu.unit = u.id
            AND uu."user" = current_user_id
            AND uu.is_editor_view = TRUE
        )
        OR
        EXISTS (
            SELECT 1
            FROM public.occasions o
            JOIN public.occasion_users ou ON ou.occasion = o.id
            WHERE o.unit = u.id
            AND ou."user" = current_user_id
            AND public.occasion_staff_navigation_rule(ou.is_manager,ou.is_editor,ou.is_editor_view,ou.is_editor_order,ou.is_editor_order_view)
        )
    );

    -- Fetch user information along with associated units and occasions
    SELECT to_jsonb(ui)::jsonb || jsonb_build_object(
            'units', COALESCE(user_units_json, '[]'::jsonb),
            'occasions', COALESCE(user_occasions_json, '[]'::jsonb)
          )
      INTO user_info_json
    FROM public.user_info ui
    WHERE ui.id = current_user_id;

    -- Fetch organization info
    org_json := CASE WHEN v_context_organization.id IS NOT NULL THEN jsonb_build_object(
        'title', v_context_organization.title,
        'APP_NAME', v_context_organization.data->>'APP_NAME',
        'PLATFORMS', v_context_organization.data->'PLATFORMS',
        'DEFAULT_URL', v_context_organization.data->>'DEFAULT_URL',
        'DEFAULT_LANGUAGE', v_context_organization.data->>'DEFAULT_LANGUAGE',
        'IS_REGISTRATION_ENABLED', (v_context_organization.data->>'IS_REGISTRATION_ENABLED')::boolean,
        'IS_UNIT_CREATION_ENABLED', (v_context_organization.data->>'IS_UNIT_CREATION_ENABLED')::boolean,
        'IS_APP_SUPPORTED', (v_context_organization.data->>'IS_APP_SUPPORTED')::boolean,
        'FORM_MEASUREMENT_ENABLED', coalesce(v_context_organization.data->'FORM_MEASUREMENT_ENABLED'='true'::jsonb,false),
        'DEFAULT_UNIT', (v_context_organization.data->>'DEFAULT_UNIT')::int,
        'REPRESENTATIVE_OCCASION', (v_context_organization.data->>'REPRESENTATIVE_OCCASION')::int
    ) ELSE NULL END;

    -- Fetch the user's groups for the specific occasion
    IF occasionId IS NOT NULL THEN
        user_groups_json := public.get_user_groups_for_context_internal_v1(occasionId,
          public.active_membership(occasion_user.is_editor,v_demo),
          public.readable_membership(occasion_user.is_editor_view,v_demo,v_demo_read),NOT v_demo);
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'is_admin', is_admin_bool,
        'capabilities', public.get_context_capabilities_v1(occasionId,occasion_user,unit_user,is_admin_bool,
          v_demo,coalesce(COALESCE(occasion_unit,default_unit)=ANY(v_demo_unit_ids),false),v_demo_read,
          coalesce(jsonb_array_length(user_units_json),0)>0,
          EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(user_units_json,'[]'::jsonb)) listed
            WHERE (listed->>'id')::bigint=occasion_unit),
          public.reception_enabled(occasion_json->'features')) || public.organization_context_capabilities(v_organization_admin),
        'demo_read_only', v_demo_read,
        'occasion_user', COALESCE(to_jsonb(occasion_user)::jsonb, NULL),
        'unit_user', COALESCE(to_jsonb(unit_user)::jsonb, NULL),
        'occasion', COALESCE(occasion_json, '{}'::jsonb),
        'unit', COALESCE(unit_json, '{}'::jsonb) || public.provider_unit_public_fields_internal((unit_json->>'id')::bigint),
        'bank_accounts_admin', COALESCE(bank_account_ids, '{}'),
        'bank_capabilities',coalesce(bank_capabilities,'{}'::jsonb),
        'user_info', COALESCE(user_info_json, '{}'::jsonb),
        'organization', COALESCE(org_json::jsonb, '{}'::jsonb),
        'groups', COALESCE(user_groups_json, '{}'::jsonb)
    );
END;
$$;


ALTER FUNCTION public.get_app_config_v218(data_in jsonb) OWNER TO postgres;

--
-- Name: get_app_config_v219(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_app_config_v219(data_in jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
  v_occasion bigint;
  v_enabled boolean := false;
BEGIN
  v_result := public.get_app_config_v218(data_in);
  v_occasion := (v_result#>>'{occasion,id}')::bigint;
  IF v_occasion IS NOT NULL THEN
    SELECT COALESCE((o.data->>'client_sync_v1')::boolean, false)
      AND NOT EXISTS (
        SELECT 1 FROM public.client_sync_component_sources s
        WHERE s.registry_version=(SELECT max(v.registry_version)
          FROM public.client_sync_component_sources v)
          AND NOT s.cutover_ready)
      INTO v_enabled
    FROM public.occasions o
    WHERE o.id = v_occasion;
  END IF;
  -- A direct unit route receives its catalogue and screen metadata in the
  -- existing context request. Occasion/public contexts keep their old payload.
  IF (v_result->>'code')::integer=200 AND data_in->>'unit_id' IS NOT NULL
     AND public.can_read_unit_occasion_catalog((data_in->>'unit_id')::bigint) THEN
    v_result := v_result || jsonb_build_object('unit_dashboard',
      public.get_unit_occasion_dashboard_internal((data_in->>'unit_id')::bigint));
  END IF;
  RETURN v_result || jsonb_build_object('client_sync_v1', v_enabled);
END;
$$;


ALTER FUNCTION public.get_app_config_v219(data_in jsonb) OWNER TO postgres;

--
-- Name: get_auth_email_context(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_auth_email_context(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 RETURN (SELECT jsonb_build_object('organization',organization,'recipient',public.get_user_delivery_email(id)) FROM public.user_info WHERE id=p_user);
END $$;


ALTER FUNCTION public.get_auth_email_context(p_user uuid) OWNER TO postgres;

--
-- Name: get_authoring_export_page(bigint, bigint, bigint, text, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_authoring_export_page(p_occasion bigint, p_organization bigint, p_unit bigint, p_dataset text, p_columns jsonb, p_after text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE spec jsonb:=public.authoring_export_columns_internal_v1();rows jsonb; result jsonb; next_cursor text;
BEGIN
 PERFORM public.authorize_authoring_export(p_occasion,p_organization,p_unit,p_dataset,p_columns);
 IF (spec ? p_dataset) IS NOT TRUE OR p_limit NOT BETWEEN 1 AND 50 OR jsonb_typeof(p_columns) IS DISTINCT FROM 'array' OR jsonb_array_length(p_columns) NOT BETWEEN 1 AND 20
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_columns) c WHERE NOT(spec->p_dataset->'columns' ? c))
  OR jsonb_array_length(p_columns)<>(SELECT count(DISTINCT c) FROM jsonb_array_elements_text(p_columns) c) THEN
  RAISE invalid_parameter_value USING MESSAGE='closed export columns and page required'; END IF;
 IF p_dataset='orders' THEN
  result:=public.get_operator_orders_v1(p_occasion,p_organization,p_unit,p_limit,p_after::bigint);
  next_cursor:=result->>'nextCursor';
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',r->'id','symbol',r->'symbol','state',r->'state','createdAt',r->'createdAt','ticketCount',r->'ticketCount',
   'price',r->'price','currency',r->'currency','paid',r#>'{payment,paid}') ORDER BY n),'[]'::jsonb) INTO rows FROM jsonb_array_elements(result->'orders') WITH ORDINALITY x(r,n);
 ELSIF p_dataset='people' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."userId"),'[]'::jsonb) INTO rows FROM (
   SELECT ou."user" AS "userId",ui.name,ui.surname,ui.email_readonly AS email,ui.phone,ui.birth_date AS "birthDate",ou.role,
    coalesce((ou.data->>'is_volunteer')::boolean,false) AS "isVolunteer",coalesce(ou.is_approved,false) AS "isApproved",ou.data->>'note' AS note
   FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user" WHERE ou.occasion=p_occasion AND (p_after IS NULL OR ou."user">p_after::uuid) ORDER BY ou."user" LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'userId'; END IF;
 ELSIF p_dataset='events' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb) INTO rows FROM (
   SELECT e.id,e.title,e.start_time AS "startTime",e.end_time AS "endTime",e.max_participants AS "maxParticipants",coalesce(v.version,0) AS "aggregateVersion"
   FROM public.events e LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND (p_after IS NULL OR e.id>p_after::bigint) ORDER BY e.id LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'id'; END IF;
 ELSIF p_dataset='speakers' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb) INTO rows FROM (
   SELECT e.id,e.title,e.subtitle,e.description,coalesce(v.version,0) AS "aggregateVersion" FROM public.speakers e
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND (p_after IS NULL OR e.id>p_after::bigint) ORDER BY e.id LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'id'; END IF;
 ELSIF p_dataset='places' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb) INTO rows FROM (
   SELECT e.id,e.title,e.description,e.type,coalesce(v.version,0) AS "aggregateVersion" FROM public.places e
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND (p_after IS NULL OR e.id>p_after::bigint) ORDER BY e.id LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'id'; END IF;
 ELSIF p_dataset='feedback' THEN
  result:=public.get_event_feedback_export_page_internal_v1(p_occasion,p_after::bigint,p_limit);
  IF result->>'code'<>'200' THEN RAISE insufficient_privilege USING MESSAGE='feedback export denied'; END IF;
  -- Preserve the existing projection, but use stable feedback ID order for export pages.
  SELECT coalesce(jsonb_agg(r ORDER BY (r->>'feedback_id')::bigint),'[]'::jsonb) INTO rows FROM jsonb_array_elements(result->'data') r;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'feedback_id'; END IF;
 END IF;
 -- Drop unselected columns in SQL before any personal data crosses the boundary.
 SELECT coalesce(jsonb_agg((SELECT jsonb_object_agg(k,v) FROM jsonb_each(r) x(k,v) WHERE p_columns ? k) ORDER BY n),'[]'::jsonb) INTO rows
 FROM jsonb_array_elements(coalesce(rows,'[]')) WITH ORDINALITY x(r,n);
 RETURN jsonb_build_object('columns',p_columns,'rows',rows,'nextCursor',next_cursor);
END $$;


ALTER FUNCTION public.get_authoring_export_page(p_occasion bigint, p_organization bigint, p_unit bigint, p_dataset text, p_columns jsonb, p_after text, p_limit integer) OWNER TO postgres;

--
-- Name: get_authoring_history(bigint, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_authoring_history(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; lim int:=coalesce((p_payload->>'limit')::int,50); commit_row public.client_commits%ROWTYPE;
 order_id bigint:=(p_payload->>'orderId')::bigint; include_unit boolean:=coalesce((p_payload->>'includeUnit')::boolean,false);
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF lim NOT BETWEEN 1 AND 100 OR (include_unit AND (p_unit IS NULL OR NOT public.can_read_unit_client_commits(p_unit))) THEN
  RAISE insufficient_privilege USING MESSAGE='invalid history scope'; END IF;
 IF order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=order_id AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='order outside history scope'; END IF;
 IF p_action='commits' THEN
  RETURN public.get_client_commits_scoped_internal_v1(p_occasion,(p_payload#>>'{before,occurredAt}')::timestamptz,(p_payload#>>'{before,commitId}')::uuid,lim,'{}',include_unit,false);
 ELSIF p_action='commit' THEN
  SELECT * INTO commit_row FROM public.client_commits WHERE commit_id=(p_payload->>'commitId')::uuid;
  IF commit_row.commit_id IS NULL OR NOT coalesce(commit_row.occasion=p_occasion OR (include_unit AND commit_row.unit=p_unit),false) THEN
   RAISE insufficient_privilege USING MESSAGE='commit outside history scope'; END IF;
  IF (SELECT count(*) FROM public.client_commit_items WHERE commit_id=commit_row.commit_id)>500 THEN RAISE invalid_parameter_value USING MESSAGE='audit entry exceeds bounded authoring detail; use ordinary UI'; END IF;
  result:=public.get_client_commit_v1(commit_row.commit_id);
  IF result->>'code'<>'200' THEN RAISE insufficient_privilege USING MESSAGE='commit read denied'; END IF;
  -- Fanout metadata must not disclose identities of unrelated scopes.
  result:=jsonb_set(result,'{data,components}',coalesce((SELECT jsonb_agg(c) FROM jsonb_array_elements(result#>'{data,components}') c
   WHERE (c->>'scopeType'='occasion' AND (c->>'scopeId')::bigint=p_occasion) OR (include_unit AND c->>'scopeType'='unit' AND (c->>'scopeId')::bigint=p_unit)),'[]'::jsonb));
  RETURN result;
 ELSIF p_action='activity' THEN
  RETURN public.get_client_activity_v1(p_occasion,(p_payload->>'from')::timestamptz,(p_payload->>'to')::timestamptz);
 ELSIF p_action='orders' THEN
  IF order_id IS NULL OR NOT public.can_read_orders(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order history read denied'; END IF;
  SELECT jsonb_build_object('code',200,'data',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id DESC),'[]'::jsonb)) INTO result FROM (
   SELECT h.id,h.created_at AS "createdAt",h.state,h.price::text AS price,h.currency_code AS currency,
    nullif(concat_ws(' ',u.name,u.surname),'') AS "actorDisplay"
   FROM eshop.orders_history h LEFT JOIN public.user_info u ON u.id=h.created_by WHERE h."order"=order_id
    AND (p_payload->>'beforeId' IS NULL OR h.id<(p_payload->>'beforeId')::bigint) ORDER BY h.id DESC LIMIT lim) page;
  RETURN result;
 ELSIF p_action='email' THEN
  IF NOT coalesce(public.email_report_allowed(p_organization,p_occasion,NULL),false) THEN RAISE insufficient_privilege USING MESSAGE='delivery history read denied'; END IF;
  result:=public.get_email_delivery_page(p_occasion,(p_payload->>'beforeId')::bigint,lim,order_id,p_payload->>'kind',p_payload->>'state',p_organization,NULL,NULL,false);
  RETURN jsonb_build_object('code',200,'data',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r->'id','kind',r->'message_kind','orderId',r->'order_id','createdAt',r->'created_at',
   'acceptedAt',r->'accepted_at','deliveredAt',r->'delivered_at','bouncedAt',r->'bounced_at','complainedAt',r->'complained_at','state',r->'state','postActionState',r->'post_action_state') ORDER BY (r->>'id')::bigint DESC)
   FROM jsonb_array_elements(result) r),'[]'::jsonb));
 ELSIF p_action='feedback' THEN
  RETURN public.get_event_feedback_export_page_internal_v1(p_occasion,(p_payload->>'after')::bigint,lim);
 END IF;
 RAISE invalid_parameter_value USING MESSAGE='unknown history projection';
END $$;


ALTER FUNCTION public.get_authoring_history(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb) OWNER TO postgres;

--
-- Name: get_available_occasions(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_available_occasions(p_organization_id bigint, p_unit_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  result_data jsonb;
  occasions_data jsonb;
BEGIN
  -- 1. Validation
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'organization_not_found: Organization % does not exist.', p_organization_id USING ERRCODE = 'P0002';
  END IF;

  IF p_unit_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = p_unit_id AND organization = p_organization_id) THEN
      RAISE EXCEPTION 'unit_not_found: Unit % not found in Org %.', p_unit_id, p_organization_id USING ERRCODE = 'P0002';
    END IF;
  END IF;

  -- 2. Fetch Occasions with Source Integration
  -- We LEFT JOIN external_occasions_cache to get source metadata
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'title', o.title,
        'description', o.description,
        'link', o.link,
        'start_time', o.start_time,
        'end_time', o.end_time,
        'is_open', o.is_open,
        'is_hidden', o.is_hidden,
        'is_promoted', o.is_promoted, -- Added for frontend filtering
        'features', o.features,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'data', o.data,
        -- New Architectural Fields:
        'source_name', c.source_name,         -- "From Source X"
        'last_synced_at', c.last_synced_at,   -- "Synced 5m ago"
        'is_external', (c.source_name IS NOT NULL),
        -- Form Info (Preserved from original logic)
        'form', (
           SELECT jsonb_build_object(
              'id', f.id,
              'created_at', f.created_at,
              'data', f.data,
              'type', f.type,
              'is_open', f.is_open,
              'link', f.link,
              'header', f.header
           )
           FROM public.forms f
           WHERE f.occasion = o.id
           ORDER BY f.is_open DESC, f.id
           LIMIT 1
        )
      )
      ORDER BY o.start_time DESC
    ),
    '[]'::jsonb
  )
  INTO occasions_data
  FROM public.occasions o
  LEFT JOIN public.external_occasions_cache c ON o.link = c.link
  WHERE 
    -- Preserve the live own-organization catalog; external sources require explicit opt-in.
    public.catalog_includes_occasion_internal(p_organization_id, o.organization, c.source_name)
    -- Unit Filter (Optional)
    AND (p_unit_id IS NULL OR o.unit = p_unit_id)
    -- Visibility Rules
    AND o.is_hidden = false
    -- Promotion Rule: STRICT - Must be promoted, even if external
    AND (p_unit_id IS NOT NULL OR o.is_promoted = true);

  -- 3. Construct Result Object
  IF p_unit_id IS NULL THEN
      result_data := jsonb_build_object(
        'title', 'All Occasions',
        'organization', p_organization_id,
        'occasions', occasions_data
      );
  ELSE
      SELECT jsonb_build_object(
        'id', u.id,
        'title', u.title,
        'organization', u.organization,
        'occasions', occasions_data
      )
      INTO result_data
      FROM public.units u
      WHERE u.id = p_unit_id;
  END IF;

  RETURN result_data;
END;
$$;


ALTER FUNCTION public.get_available_occasions(p_organization_id bigint, p_unit_id bigint) OWNER TO postgres;

