--
-- Name: get_bank_account_users(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_account_users(p_bank_account_id bigint) RETURNS TABLE(user_id uuid, email text, name text, surname text, is_admin boolean, is_support boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT * FROM public.get_bank_account_users(p_bank_account_id, NULL::bigint);
$$;


ALTER FUNCTION public.get_bank_account_users(p_bank_account_id bigint) OWNER TO postgres;

--
-- Name: get_bank_account_users(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_account_users(p_bank_account_id bigint, p_unit_id bigint) RETURNS TABLE(user_id uuid, email text, name text, surname text, is_admin boolean, is_support boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_org_id bigint;
BEGIN
    -- A unit context is meaningful only for an actual account link.
    IF p_unit_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM eshop.unit_bank_accounts link
        WHERE link.unit = p_unit_id AND link.bank_account = p_bank_account_id
    ) THEN
        RAISE insufficient_privilege USING MESSAGE = 'Bank account is not linked to this unit';
    END IF;
    IF NOT public.is_service_role() AND NOT public.can_read_bank_account_users(p_bank_account_id,p_unit_id) THEN
        RAISE insufficient_privilege USING MESSAGE = 'Bank account access denied';
    END IF;
    -- If unit context is provided, find the organization
    IF p_unit_id IS NOT NULL THEN
        SELECT organization INTO v_org_id FROM public.units WHERE id = p_unit_id;
    END IF;

    RETURN QUERY
    SELECT
        u.id,
        u.email_readonly,
        u.name,
        u.surname,
        bau.is_admin,
        bau.is_support
    FROM eshop.bank_account_users bau
    JOIN public.user_info u ON bau."user" = u.id
    LEFT JOIN public.organization_users ou ON u.id = ou."user" AND (v_org_id IS NULL OR ou.organization = v_org_id)
    WHERE bau.bank_account = p_bank_account_id
      AND (v_org_id IS NULL OR ou.is_hidden IS NOT TRUE);
END;
$$;


ALTER FUNCTION public.get_bank_account_users(p_bank_account_id bigint, p_unit_id bigint) OWNER TO postgres;

--
-- Name: get_bank_accounts_for_unit_management(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_accounts_for_unit_management(p_unit_id bigint) RETURNS TABLE(id bigint, account_number text, title text, creditor_name text, type text, is_admin boolean, token_masked text, token_expiry_date timestamp with time zone, supported_currencies text[], last_fio_fetch_time timestamp with time zone, bank_sync jsonb, bank_sync_warning jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_unit_manager boolean;
BEGIN
    v_unit_manager := public.can_manage_unit_bank_accounts(p_unit_id);
    IF NOT public.can_read_unit_bank_accounts(p_unit_id) THEN
      RAISE insufficient_privilege USING MESSAGE='User is not manager.';
    END IF;
    RETURN QUERY
    SELECT
        ba.id,
        ba.account_number,
        ba.title,
        ba.creditor_name,
        ba.type,
        coalesce(membership.is_admin,false) as is_admin,
        NULL::text as token_masked,
        NULL::timestamptz as token_expiry_date,
        ba.supported_currencies,
        ba.last_fio_fetch_time,
        CASE WHEN public.bank_account_write_rule(membership.is_admin,v_unit_manager,protected.bank_account IS NOT NULL)
          THEN public.get_bank_sync_connection(ba.id)
          ELSE (
            SELECT jsonb_build_object('state',connection.state,'mode',connection.mode)
            FROM eshop.bank_sync_connections connection
            WHERE connection.bank_account_id = ba.id
          ) END AS bank_sync,
        public.bank_sync_warning(ba.id) AS bank_sync_warning
    FROM eshop.bank_accounts ba
    JOIN eshop.unit_bank_accounts uba ON ba.id = uba.bank_account
    -- Historical memberships need not be unique. Preserve any active admin
    -- grant while returning one row for each linked bank account.
    LEFT JOIN (
      SELECT grants.bank_account,bool_or(grants.is_admin) AS is_admin
      FROM eshop.bank_account_users grants WHERE grants."user"=auth.uid()
      GROUP BY grants.bank_account
    ) membership ON membership.bank_account=ba.id
    LEFT JOIN (SELECT DISTINCT bank_account FROM public.demo_occasions) protected ON protected.bank_account=ba.id
    WHERE uba.unit = p_unit_id
    AND ba.type != 'CASH'
    -- The entry guard admits a manager or a listed demo reader. Managers are
    -- always outside demo units; demo readers retain the account-level fence.
    AND (v_unit_manager OR EXISTS (SELECT 1 FROM public.demo_occasions demo_bank WHERE demo_bank.bank_account=ba.id AND public.can_read_orders(demo_bank.occasion)));
END;
$$;


ALTER FUNCTION public.get_bank_accounts_for_unit_management(p_unit_id bigint) OWNER TO postgres;

--
-- Name: get_bank_name_from_code(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_name_from_code(p_code text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Common Czech Banks
    RETURN CASE p_code
        WHEN '0100' THEN 'Komerční banka'
        WHEN '0300' THEN 'ČSOB'
        WHEN '0600' THEN 'MONETA Money Bank'
        WHEN '0800' THEN 'Česká spořitelna'
        WHEN '2010' THEN 'Fio banka'
        WHEN '2060' THEN 'Citfin'
        WHEN '2070' THEN 'Markov'
        WHEN '2200' THEN 'Peněžní dům'
        WHEN '2220' THEN 'Artemis'
        WHEN '2240' THEN 'Poštová banka'
        WHEN '2250' THEN 'Banka CREDITAS'
        WHEN '2260' THEN 'Moravský Peněžní Ústav'
        WHEN '2275' THEN 'Podnikatelská družstevní záložna'
        WHEN '2400' THEN 'The Royal Bank of Scotland'
        WHEN '2600' THEN 'Citibank'
        WHEN '2700' THEN 'UniCredit Bank'
        WHEN '3030' THEN 'Air Bank'
        WHEN '3050' THEN 'BNP Paribas'
        WHEN '3060' THEN 'PKO BP'
        WHEN '3500' THEN 'ING Bank'
        WHEN '4000' THEN 'Max banka' -- Formerly Expobank
        WHEN '4300' THEN 'Českomoravská záruční a rozvojová banka'
        WHEN '5500' THEN 'Raiffeisenbank'
        WHEN '6000' THEN 'PPF banka'
        WHEN '6210' THEN 'mBank'
        WHEN '6300' THEN 'BNP Paribas Fortis'
        WHEN '6700' THEN 'Všeobecná úverová banka'
        WHEN '7910' THEN 'Deutsche Bank'
        WHEN '7940' THEN 'Waldviertler Sparkasse Bank'
        WHEN '7950' THEN 'Raiffeisen stavební spořitelna'
        WHEN '7960' THEN 'Českomoravská stavební spořitelna'
        WHEN '7970' THEN 'Wüstenrot - stavební spořitelna'
        WHEN '7980' THEN 'Wüstenrot hypoteční banka'
        WHEN '7990' THEN 'Modrá pyramida'
        WHEN '8030' THEN 'Raiffeisenbank im Stiftland'
        WHEN '8040' THEN 'Oberbank'
        WHEN '8060' THEN 'Stavební spořitelna České spořitelny'
        WHEN '8090' THEN 'Česká exportní banka'
        WHEN '8150' THEN 'HSBC'
        WHEN '8200' THEN 'Privatbanka'
        WHEN '8220' THEN 'Payment Execution'
        WHEN '8230' THEN 'EEP'
        WHEN '8240' THEN 'Družstevní záložna Kredit'
        WHEN '8250' THEN 'Bank of China'
        WHEN '8255' THEN 'Bank of Communications'
        WHEN '8260' THEN 'Industrial and Commercial Bank of China'
        WHEN '8265' THEN 'China Construction Bank'
        ELSE NULL
    END;
END;
$$;


ALTER FUNCTION public.get_bank_name_from_code(p_code text) OWNER TO postgres;

--
-- Name: get_bank_sync_connection(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_sync_connection(p_bank_account_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM public.check_is_admin_for_bank_account(p_bank_account_id);
  SELECT jsonb_build_object('id',c.id,'remote_bank_account_id',c.remote_bank_account_id,'state',c.state,'mode',c.mode,
    'receiving_address',CASE WHEN c.pairing_code IS NOT NULL THEN c.pairing_code||'@banksync.festapp.net' END,
    'bank_pull_at',c.bank_pull_at,'receiver_commit_at',c.receiver_commit_at,'last_error',c.last_error,
    'observation_id',c.observation_id::text,'warning_pending',public.bank_sync_warning_pending(c.id),'token_expiry_at',c.token_expiry_at) INTO v_result FROM eshop.bank_sync_connections c
    WHERE c.bank_account_id=p_bank_account_id OR c.id IN
      (SELECT connection_id FROM eshop.bank_sync_account_aliases WHERE bank_account_id=p_bank_account_id);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_bank_sync_connection(p_bank_account_id bigint) OWNER TO postgres;

--
-- Name: get_bank_sync_connections_for_occasion(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_sync_connections_for_occasion(p_link text) RETURNS TABLE(connection_id bigint, remote_bank_account_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE target_unit bigint; target_occasion bigint;
BEGIN
 SELECT o.id,o.unit INTO target_occasion,target_unit FROM public.occasions o WHERE o.link=p_link FOR SHARE;
 IF auth.uid() IS NULL OR target_occasion IS NULL OR public.is_demo_occasion(target_occasion)
   OR NOT public.can_manage_unit_bank_accounts(target_unit) THEN
   RAISE insufficient_privilege USING MESSAGE='bank account and unit administration required';
 END IF;
 RETURN QUERY SELECT DISTINCT c.id,c.remote_bank_account_id
 FROM eshop.bank_sync_connections c JOIN eshop.unit_bank_accounts link
   ON link.bank_account=c.bank_account_id OR link.bank_account IN
     (SELECT a.bank_account_id FROM eshop.bank_sync_account_aliases a WHERE a.connection_id=c.id)
 JOIN eshop.bank_account_users membership ON membership.bank_account=link.bank_account
   AND membership."user"=auth.uid()
 LEFT JOIN (SELECT DISTINCT d.bank_account FROM public.demo_occasions d) protected
   ON protected.bank_account=link.bank_account
 WHERE link.unit=target_unit AND c.state IN ('connected','degraded') AND c.mode='api'
   AND c.legacy_blocked_at IS NOT NULL
   -- The single unit admission above established the live manager fact for
   -- this actual link. Keep account facts set based, without per-row RPCs.
   AND public.bank_account_write_rule(membership.is_admin,true,protected.bank_account IS NOT NULL);
END $$;


ALTER FUNCTION public.get_bank_sync_connections_for_occasion(p_link text) OWNER TO postgres;

--
-- Name: get_bank_sync_health_targets(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_sync_health_targets(p_organization_id bigint) RETURNS TABLE(connection_id bigint, remote_bank_account_id text, mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.require_service_role();
  RETURN QUERY SELECT c.id,c.remote_bank_account_id,c.mode FROM eshop.bank_sync_connections c
    WHERE c.legacy_blocked_at IS NOT NULL AND c.state IN ('connected','degraded','suspended')
      AND EXISTS (SELECT 1 FROM eshop.unit_bank_accounts ub JOIN public.units u ON u.id=ub.unit
        WHERE u.organization=p_organization_id AND (ub.bank_account=c.bank_account_id
          OR ub.bank_account IN (SELECT a.bank_account_id FROM eshop.bank_sync_account_aliases a WHERE a.connection_id=c.id)))
    ORDER BY (SELECT h.checked_at FROM eshop.bank_sync_health h WHERE h.connection_id=c.id) NULLS FIRST,c.id LIMIT 100;
END;
$$;


ALTER FUNCTION public.get_bank_sync_health_targets(p_organization_id bigint) OWNER TO postgres;

--
-- Name: get_bank_sync_observations(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_sync_observations(p_bank_account_id bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM public.check_is_admin_for_bank_account(p_bank_account_id);
  SELECT COALESCE(jsonb_agg(row_to_json(q)),'[]'::jsonb) INTO v_result FROM (
    SELECT i.delivery_id,i.received_at,i.outcome,i.payload->'data' AS bank_data
      FROM eshop.bank_sync_inbox i JOIN eshop.bank_sync_connections c ON c.id=i.connection_id
      WHERE (c.bank_account_id=p_bank_account_id OR c.id IN
        (SELECT connection_id FROM eshop.bank_sync_account_aliases WHERE bank_account_id=p_bank_account_id))
        AND i.outcome LIKE 'quarantined_%' AND i.resolution IS NULL ORDER BY i.received_at DESC,i.delivery_id LIMIT LEAST(GREATEST(p_limit,1),100)
  ) q;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_bank_sync_observations(p_bank_account_id bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_bank_transaction_history(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_transaction_history(p_bank_account_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF NOT public.can_read_bank_transactions(p_bank_account_id) THEN
  RAISE insufficient_privilege USING MESSAGE='Bank history access denied'; END IF;
 RETURN (SELECT coalesce(jsonb_agg(t ORDER BY t.date DESC,t.id),'[]') FROM eshop.transactions t
  JOIN eshop.bank_accounts b ON b.id=t.bank_account_id
  WHERE b.id=p_bank_account_id AND upper(b.type)<>'CASH');
END $$;


ALTER FUNCTION public.get_bank_transaction_history(p_bank_account_id bigint) OWNER TO postgres;

--
-- Name: get_blueprint(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_blueprint(my_secret uuid, form_key uuid, blueprint_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    blueprintData JSONB;
    spotsData JSONB;
    productsData JSONB;
    valid_spots JSONB;
BEGIN
    -- Validate the form and blueprint association
    IF NOT EXISTS (
        SELECT 1
        FROM public.forms f
        WHERE f.key = form_key
          AND (NOT public.is_demo_occasion(f.occasion) OR public.can_read_demo_occasion(f.occasion))
          AND (f.is_open = true OR public.can_read_orders(f.occasion))
          AND EXISTS (
              SELECT 1
              FROM eshop.blueprints b
              WHERE b.id = blueprint_id
                AND f.blueprint = blueprint_id
          )
    ) THEN
        RETURN jsonb_build_object(
            'code', 400,
            'message', 'Invalid form key or blueprint association.'
        );
    END IF;

    -- Fetch blueprint details
    SELECT jsonb_build_object(
        'id', b.id,
        'occasion', b.occasion,
        'created_at', b.created_at,
        'data', '{}'::jsonb,
        'title', b.title,
        'layout', public.blueprint_public_document_internal(b.layout), 'layout_revision', b.layout_revision,
        'expiresAt', (SELECT min(s.secret_expiration_time) FROM eshop.spots s
          WHERE s.blueprint=b.id AND s.secret=my_secret AND s.order_product_ticket IS NULL
            AND s.secret_expiration_time>clock_timestamp()),
        'layoutResources', public.blueprint_layout_resources_internal(public.blueprint_public_document_internal(b.layout),b.occasion)
    )
    INTO blueprintData
    FROM eshop.blueprints b
    WHERE b.id = blueprint_id;

    -- Every runtime spot belongs to a canonical node binding.
    SELECT coalesce(jsonb_agg(spot),'[]'::jsonb) INTO valid_spots
      FROM eshop.blueprint_seat_bindings WHERE blueprint=blueprint_id;

    -- Fetch enriched spots data
    SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'product', s.product,
        'state', CASE
            WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
            WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN
                CASE
                    WHEN s.secret = my_secret THEN 'selected_by_me'
                    ELSE 'selected'
                END
            ELSE 'available'
        END
    ))
    INTO spotsData
    FROM eshop.spots s
    WHERE s.id = ANY(SELECT jsonb_array_elements_text(valid_spots)::BIGINT)
      AND s.occasion = (
        SELECT occasion FROM public.forms WHERE key = form_key
      );

    -- The associated blueprint is the seat/area offer authority. Product and
    -- inventory availability remain shared with reservation and checkout.
    productsData:=public.blueprint_form_product_catalog_internal(
      (SELECT id FROM public.forms WHERE key=form_key));

    -- Add spots data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{spots}',
        COALESCE(spotsData, '[]'::jsonb)
    );

    -- Add products data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{products}',
        COALESCE(productsData, '[]'::jsonb)
    );

    blueprintData:=blueprintData||public.blueprint_public_binding_projection_internal(blueprint_id,my_secret);

    blueprintData:=blueprintData||jsonb_build_object('areaAvailability',public.blueprint_area_availability_internal(blueprint_id,(SELECT id FROM public.forms WHERE key=form_key)));

    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', blueprintData
    );
END;
$$;


ALTER FUNCTION public.get_blueprint(my_secret uuid, form_key uuid, blueprint_id bigint) OWNER TO postgres;

--
-- Name: get_blueprint_for_authoring_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_blueprint_for_authoring_v1(p_blueprint bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM eshop.blueprints WHERE id=p_blueprint;
 IF auth.uid() IS NULL OR oc IS NULL OR public.can_read_orders(oc) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order editor view required'; END IF;
 SELECT jsonb_build_object('id',b.id,'occasion',b.occasion,'organization',b.organization,'title',b.title,
  'aggregate_version',coalesce(v.version,0),'layout',b.layout,'layout_revision',b.layout_revision,
  'layoutResources',public.blueprint_canonical_text_resources_internal(b.layout,b.occasion,NULL,true)||jsonb_build_object('assets',public.blueprint_canonical_asset_resources_internal(b.layout,b.occasion,NULL)),
  'spots',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'product',s.product,'title',s.title,
   'occupied',s.order_product_ticket IS NOT NULL,'held',s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp()) ORDER BY s.id)
   FROM eshop.spots s WHERE s.blueprint=b.id AND s.occasion=oc),'[]')) INTO result
 FROM eshop.blueprints b LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='blueprint'
 AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=b.id::text WHERE b.id=p_blueprint;
 RETURN result||public.blueprint_binding_projection_internal(p_blueprint);
END $$;


ALTER FUNCTION public.get_blueprint_for_authoring_v1(p_blueprint bigint) OWNER TO postgres;

--
-- Name: get_blueprint_for_edit(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_blueprint_for_edit(occasion_link text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_blueprint_for_edit(occasion_link,NULL::bigint)
$$;


ALTER FUNCTION public.get_blueprint_for_edit(occasion_link text) OWNER TO postgres;

--
-- Name: get_blueprint_for_edit(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_blueprint_for_edit(occasion_link text, p_blueprint_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    blueprint_id BIGINT;
    blueprintData JSONB;
    spotsData JSONB;
    productsData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    orderProductTicketsData JSONB;
    valid_spots JSONB;
    occasion_id BIGINT;
BEGIN
    -- Resolve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion link does not exist');
    END IF;

    -- Authorization check
    IF public.can_read_seating_status(occasion_id) IS NOT TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    IF p_blueprint_id IS NULL AND (SELECT count(*) FROM eshop.blueprints WHERE occasion=occasion_id)>1 THEN
      RETURN jsonb_build_object('code',409,'reason','BLUEPRINT_SELECTION_REQUIRED'); END IF;
    SELECT id INTO blueprint_id FROM eshop.blueprints WHERE occasion=occasion_id AND (p_blueprint_id IS NULL OR id=p_blueprint_id);

    -- Check if a blueprint exists for the occasion
    IF blueprint_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No blueprint found for this occasion');
    END IF;

    -- Fetch blueprint details
    SELECT jsonb_build_object(
        'id', b.id,
        'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='blueprint' AND scope_type='occasion' AND scope_id=b.occasion AND aggregate_id=b.id::text),0),
        'created_at', b.created_at,
        'data', b.data,
        'title', b.title,
        'occasion', b.occasion,
        'organization', b.organization,
        'layout', b.layout, 'layout_revision', b.layout_revision,
        'layoutResources', public.blueprint_layout_resources_internal(b.layout,b.occasion)
    )
    INTO blueprintData
    FROM eshop.blueprints b
    WHERE b.id = blueprint_id;

    -- Every runtime spot belongs to a canonical node binding.
    SELECT coalesce(jsonb_agg(spot),'[]'::jsonb) INTO valid_spots
      FROM eshop.blueprint_seat_bindings WHERE blueprint=blueprint_id;

    -- Shared lifecycle interpretation; only this released/private UI view
    -- includes the order-product relationship ID needed by its order controls.
    SELECT jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'product',f.product,
      'order_product_ticket',CASE WHEN public.can_read_orders(occasion_id) THEN f.order_product_ticket END,'state',f.state) ORDER BY f.id) INTO spotsData
    FROM public.blueprint_spot_facts_internal(occasion_id,ARRAY(SELECT jsonb_array_elements_text(valid_spots)::bigint)) f;

    -- Fetch all products of type "spot", "taxi", "food"
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=p.occasion AND aggregate_id=p.id::text),0),
        'title', p.title,
        'price', p.price,
        'type', pt.type,
        'description', pt.description,
        'product_type', p.product_type,
        'currency_code', p.currency_code
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = occasion_id;

    IF public.can_read_orders(occasion_id) THEN
    -- Fetch relevant tickets associated with the order_product_ticket in spots
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden
    ))
    INTO ticketsData
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    JOIN eshop.spots s ON s.order_product_ticket = opt.id
    WHERE s.id = ANY(SELECT jsonb_array_elements_text(valid_spots)::BIGINT)
      AND t.occasion = occasion_id;

    -- Fetch relevant orders associated with the order_product_ticket in spots
    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'order_symbol', o.order_symbol,
        'order_sequence', o.order_sequence,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'price', o.price,
        'state', o.state,
        'currency_code', o.currency_code,
        'data', jsonb_build_object('name', o.data->>'name', 'surname', o.data->>'surname', 'email', o.data->>'email', 'note', o.data->>'note', 'note_hidden', coalesce(o.note_hidden,o.data->>'note_hidden'))
    ))
    INTO ordersData
    FROM eshop.orders o
    JOIN eshop.order_product_ticket opt ON opt."order" = o.id
    JOIN eshop.spots s ON s.order_product_ticket = opt.id
    WHERE s.id = ANY(SELECT jsonb_array_elements_text(valid_spots)::BIGINT)
      AND o.occasion = occasion_id;

    -- Extract order IDs from ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(ordersData) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object(
            'id', opt.id,
            'order', opt."order",
            'product', opt.product,
            'ticket', opt.ticket,
            'created_at', opt.created_at
        ))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    END IF;

    -- Add spots data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{spots}',
        COALESCE(spotsData, '[]'::jsonb)
    );

    -- Add products data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{products}',
        COALESCE(productsData, '[]'::jsonb)
    );

    -- Add relevant tickets data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{tickets}',
        COALESCE(ticketsData, '[]'::jsonb)
    );

    -- Add relevant orders data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{orders}',
        COALESCE(ordersData, '[]'::jsonb)
    );

    -- Add relevant order-product-ticket data to the blueprint object
    blueprintData = jsonb_set(
        blueprintData,
        '{order_product_ticket}',
        COALESCE(orderProductTicketsData, '[]'::jsonb)
    );

    blueprintData:=blueprintData||public.blueprint_binding_projection_internal(blueprint_id);

    blueprintData:=blueprintData||jsonb_build_object('areaAvailability',public.blueprint_area_availability_internal(blueprint_id,NULL));

    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', blueprintData
    );
END;
$$;


ALTER FUNCTION public.get_blueprint_for_edit(occasion_link text, p_blueprint_id bigint) OWNER TO postgres;

--
-- Name: get_blueprint_image_upload_access(bigint, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_blueprint_image_upload_access(p_occasion bigint, p_project text, p_unit bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT auth.uid() IS NOT NULL AND (p_occasion IS NULL)<>(p_unit IS NULL) AND p_project IN ('default','a','slunovrat')
 AND public.can_upload_blueprint_background(p_occasion,p_unit)
 AND EXISTS(SELECT 1 FROM (SELECT organization FROM public.occasions WHERE id=p_occasion UNION ALL SELECT organization FROM public.units WHERE id=p_unit) o
 WHERE coalesce((SELECT project FROM public.image_project_imports WHERE organization=o.organization),'default')=p_project)
$$;


ALTER FUNCTION public.get_blueprint_image_upload_access(p_occasion bigint, p_project text, p_unit bigint) OWNER TO postgres;

--
-- Name: get_blueprint_seats(bigint, bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_blueprint_seats(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint DEFAULT NULL::bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE bp bigint;meta jsonb;ids bigint[];next_id bigint;rows jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR p_after IS NOT NULL AND p_after<1 THEN RAISE invalid_parameter_value USING MESSAGE='invalid seat page'; END IF;
 PERFORM public.check_blueprint_admin_scope_internal(p_occasion,p_organization,p_unit,false,true);
 SELECT id,jsonb_build_object('id',id,'title',title,'layoutRevision',layout_revision) INTO bp,meta
 FROM eshop.blueprints WHERE occasion=p_occasion AND (p_blueprint IS NULL OR id=p_blueprint) AND layout IS NOT NULL ORDER BY id LIMIT 1 FOR SHARE;
 IF bp IS NULL THEN RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 SELECT coalesce(array_agg(spot ORDER BY spot),'{}'::bigint[]) INTO ids FROM (
  SELECT b.spot FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot AND s.occasion=p_occasion
  WHERE b.blueprint=bp AND (p_after IS NULL OR b.spot>p_after) ORDER BY b.spot LIMIT p_limit+1) selected;
 IF cardinality(ids)>p_limit THEN ids:=ids[1:p_limit];next_id:=ids[p_limit]; END IF;
 rows:=public.blueprint_admin_seat_rows_internal(p_occasion,bp,ids);
 IF octet_length(rows::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='seat page exceeds payload limit'; END IF;
 PERFORM public.check_blueprint_admin_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'blueprint',meta,'seats',rows,'nextCursor',next_id,'readAt',statement_timestamp());
END $$;


ALTER FUNCTION public.get_blueprint_seats(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_after bigint, p_limit integer) OWNER TO postgres;

