--
-- Name: get_can_view_user_auth(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_can_view_user_auth(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT public.is_service_role() OR (
        auth.uid() IS NOT NULL AND (
            auth.uid() = p_user_id
            OR EXISTS (
                SELECT 1 FROM public.user_info target
                JOIN public.organization_users actor ON actor.organization = target.organization
                WHERE target.id = p_user_id AND actor."user" = auth.uid() AND actor.is_admin IS TRUE
            )
            OR EXISTS (
                SELECT 1 FROM public.unit_users target
                JOIN public.unit_users actor ON actor.unit = target.unit
                WHERE target."user" = p_user_id AND actor."user" = auth.uid()
                  AND (actor.is_manager IS TRUE OR actor.is_editor IS TRUE OR actor.is_editor_view IS TRUE)
            )
            OR EXISTS (
                SELECT 1 FROM public.occasion_users target
                JOIN public.occasion_users actor ON actor.occasion = target.occasion
                WHERE target."user" = p_user_id AND actor."user" = auth.uid()
                  AND (actor.is_manager IS TRUE OR actor.is_editor IS TRUE OR actor.is_editor_view IS TRUE)
            )
        )
    );
$$;


ALTER FUNCTION public.get_can_view_user_auth(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_cleaning_reports(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_cleaning_reports(oc bigint, p_include_resolved boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_data jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  IF NOT public.get_is_cleaning_crew_on_occasion(oc) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_data
  FROM (
    SELECT
      r.id,
      r.place,
      p.title AS place_title,
      r.problem_type,
      r.note,
      r.data,
      r.created_at,
      r.created_by,
      TRIM(BOTH ' ' FROM COALESCE(ui.name, '') || ' ' || COALESCE(ui.surname, '')) AS created_by_name,
      COALESCE(ou.is_cleaning_blocked, false) AS created_by_blocked,
      r.resolved_at,
      r.resolved_by
    FROM public.cleaning_reports r
    JOIN public.places p ON p.id = r.place
    LEFT JOIN public.user_info ui ON ui.id = r.created_by
    LEFT JOIN public.occasion_users ou ON ou."user" = r.created_by AND ou.occasion = r.occasion
    WHERE r.occasion = oc
      AND (p_include_resolved OR r.resolved_at IS NULL)
  ) t;

  RETURN jsonb_build_object('code', 200, 'data', v_data);
END;
$$;


ALTER FUNCTION public.get_cleaning_reports(oc bigint, p_include_resolved boolean) OWNER TO postgres;

--
-- Name: get_cleaning_status(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_cleaning_status(oc bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_data jsonb;
  v_blocked boolean;
  v_muted boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  SELECT
    COALESCE(bool_or(is_cleaning_blocked), false),
    COALESCE(bool_or((data->>'cleaning_notifications_off')::boolean), false)
  INTO v_blocked, v_muted
  FROM public.occasion_users
  WHERE occasion = oc AND "user" = auth.uid();

  SELECT COALESCE(jsonb_agg(t ORDER BY t.title), '[]'::jsonb)
  INTO v_data
  FROM (
    SELECT
      p.id AS place,
      p.title AS title,
      -- Severity ranking — keep in sync with the CleaningStatus enum order in
      -- cleaning_status.dart (green < paper < hygiene < contamination).
      CASE COALESCE(MAX(
        CASE r.problem_type
          WHEN 'contamination' THEN 3
          WHEN 'hygiene'       THEN 2
          WHEN 'paper'         THEN 1
          ELSE 0
        END), 0)
        WHEN 3 THEN 'contamination'
        WHEN 2 THEN 'hygiene'
        WHEN 1 THEN 'paper'
        ELSE 'green'
      END AS status,
      MAX(r.created_at) AS last_reported_at
    FROM public.places p
    LEFT JOIN public.cleaning_reports r
      ON r.place = p.id AND r.resolved_at IS NULL
    WHERE p.occasion = oc
      AND p.type = 'toilet'
    GROUP BY p.id, p.title
  ) t;

  RETURN jsonb_build_object(
    'code', 200,
    'data', v_data,
    'is_blocked', v_blocked,
    'notifications_muted', v_muted
  );
END;
$$;


ALTER FUNCTION public.get_cleaning_status(oc bigint) OWNER TO postgres;

--
-- Name: get_client_activity_v1(bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_client_activity_v1(p_occasion bigint, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH scope AS (
    SELECT
      o.unit,
      o.organization,
      coalesce(o.data->>'timezone', 'UTC') AS timezone,
      public.can_read_client_activity(p_occasion) AS can_read
    FROM public.occasions o
    WHERE o.id = p_occasion
  ),
  activity AS (
    SELECT
      (c.occurred_at AT TIME ZONE s.timezone)::date AS activity_day,
      count(*)::bigint AS action_count,
      sum(greatest(coalesce(items.item_count, 0), 1))::bigint
        AS changed_item_count,
      count(DISTINCT c.actor_id)::bigint AS active_actor_count
    FROM public.client_commits c
    CROSS JOIN scope s
    LEFT JOIN LATERAL (
      SELECT count(*)::bigint AS item_count
      FROM public.client_commit_items item
      WHERE item.commit_id = c.commit_id
    ) items ON true
    WHERE c.occurred_at >= p_from
      AND c.occurred_at < p_to
      AND c.occasion = p_occasion
    GROUP BY activity_day
  ),
  calendar AS (
    SELECT generated::date AS activity_day
    FROM scope s
    CROSS JOIN LATERAL generate_series(
      (p_from AT TIME ZONE s.timezone)::date,
      ((p_to - interval '1 microsecond') AT TIME ZONE s.timezone)::date,
      interval '1 day'
    ) generated
  )
  SELECT CASE
    WHEN p_from IS NULL
      OR p_to IS NULL
      OR p_to <= p_from
      OR p_to - p_from > interval '31 days'
      THEN jsonb_build_object('code', 400)
    WHEN NOT EXISTS (
      SELECT 1
      FROM scope s
      WHERE s.can_read
    ) THEN jsonb_build_object('code', 403)
    ELSE jsonb_build_object(
      'code', 200,
      'data', coalesce((
        SELECT jsonb_agg(
          jsonb_build_object(
            'day', c.activity_day,
            'actionCount', coalesce(a.action_count, 0),
            'changedItemCount', coalesce(a.changed_item_count, 0),
            'activeActorCount', coalesce(a.active_actor_count, 0)
          )
          ORDER BY c.activity_day
        )
        FROM calendar c
        LEFT JOIN activity a USING (activity_day)
      ), '[]'::jsonb)
    )
  END;
$$;


ALTER FUNCTION public.get_client_activity_v1(p_occasion bigint, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: get_client_commit_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_client_commit_v1(p_commit_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE WHEN c.commit_id IS NULL THEN jsonb_build_object('code',404)
    WHEN NOT public.can_read_client_commit(c.commit_id) THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object('code',200,'data',jsonb_build_object(
      'commitId',c.commit_id,'occurredAt',c.occurred_at,
      'actorDisplay',c.actor_display,'actorKind',c.actor_kind,
      'source',c.source,'changeClass',c.change_class,'reason',c.reason,
      'items',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'entityType',i.entity_type,'entityId',i.entity_id,
        'operation',i.operation,'safeLabel',i.safe_label,
        'changedFields',i.changed_fields) ORDER BY i.item_index),'[]')
        FROM public.client_commit_items i WHERE i.commit_id=c.commit_id),
      'components',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'component',cc.component,'scopeType',cc.scope_type,
        'scopeId',cc.scope_id,'revision',cc.resulting_revision,
        'publishedRevision',p.published_revision,
        'publicationStatus',CASE
          WHEN p.published_revision>=cc.resulting_revision
            THEN 'published' ELSE 'pending' END)
        ORDER BY cc.component),'[]')
        FROM public.client_commit_components cc
        LEFT JOIN LATERAL (
          SELECT max(cp.published_revision) published_revision
          FROM public.client_sync_publications cp
          WHERE cp.component=cc.component
            AND cp.scope_type=cc.scope_type
            AND cp.scope_id=cc.scope_id
        ) p ON true
        WHERE cc.commit_id=c.commit_id))) END
  FROM (SELECT * FROM public.client_commits WHERE commit_id=p_commit_id) c
  RIGHT JOIN (SELECT 1) seed ON true;
$$;


ALTER FUNCTION public.get_client_commit_v1(p_commit_id uuid) OWNER TO postgres;

--
-- Name: get_client_commits_scoped_internal_v1(bigint, timestamp with time zone, uuid, integer, jsonb, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_client_commits_scoped_internal_v1(p_occasion bigint, p_before_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_filters jsonb DEFAULT '{}'::jsonb, p_include_unit boolean DEFAULT true, p_include_organization boolean DEFAULT true) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH scope AS (
    SELECT o.unit, o.organization,
      public.can_read_occasion_client_commits(p_occasion) AS can_occasion,
      CASE WHEN o.unit IS NULL THEN false
        ELSE (p_include_unit AND public.can_read_unit_client_commits(o.unit)) END AS can_unit,
      CASE WHEN o.organization IS NULL THEN false
        ELSE (p_include_organization AND public.can_read_organization_client_commits(o.organization)) END AS can_organization
    FROM public.occasions o
    WHERE o.id = p_occasion
  )
  SELECT CASE
    WHEN NOT EXISTS (
      SELECT 1 FROM scope s
      WHERE public.client_commit_read_rule(s.can_occasion,s.can_unit,s.can_organization)
    ) THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object('code',200,'data',COALESCE((
      SELECT jsonb_agg(row_data ORDER BY occurred_at DESC, commit_id DESC)
      FROM (
        SELECT c.occurred_at,c.commit_id,jsonb_build_object(
          'commitId',c.commit_id,'occurredAt',c.occurred_at,
          'actorDisplay',c.actor_display,'actorKind',c.actor_kind,
          'source',c.source,'changeClass',c.change_class,
          'itemCount',(SELECT count(*) FROM public.client_commit_items ci
            WHERE ci.commit_id=c.commit_id),
          'components',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'component',cc.component,'revision',cc.resulting_revision,
            'publishedRevision',pub.published_revision,
            'publicationStatus',CASE
              WHEN pub.published_revision>=cc.resulting_revision
                THEN 'published' ELSE 'pending' END)),'[]')
            FROM public.client_commit_components cc
            LEFT JOIN LATERAL (
              SELECT max(cp.published_revision) published_revision
              FROM public.client_sync_publications cp
              WHERE cp.component=cc.component
                AND cp.scope_type=cc.scope_type
                AND cp.scope_id=cc.scope_id
            ) pub ON true
            WHERE cc.commit_id=c.commit_id)
        ) row_data
        FROM public.client_commits c
        CROSS JOIN scope s
        WHERE (
          (s.can_occasion AND c.occasion=p_occasion)
          OR (s.can_unit AND c.unit=s.unit)
          OR (s.can_organization AND c.organization=s.organization)
        )
          AND (p_before_time IS NULL OR
            (c.occurred_at,c.commit_id)<(p_before_time,p_before_id))
          AND (NOT p_filters ? 'source' OR c.source=p_filters->>'source')
          AND (NOT p_filters ? 'changeClass'
            OR c.change_class=p_filters->>'changeClass')
          AND (NOT p_filters ? 'actorKind'
            OR c.actor_kind=p_filters->>'actorKind')
          AND (NOT p_filters ? 'actor'
            OR COALESCE(c.actor_display,'') ILIKE
              '%'||(p_filters->>'actor')||'%')
          AND (NOT p_filters ? 'from'
            OR c.occurred_at >= (p_filters->>'from')::timestamptz)
          AND (NOT p_filters ? 'to'
            OR c.occurred_at < (p_filters->>'to')::timestamptz)
          AND (NOT p_filters ? 'component' OR EXISTS(
            SELECT 1 FROM public.client_commit_components fc
            WHERE fc.commit_id=c.commit_id
              AND fc.component=p_filters->>'component'))
        ORDER BY c.occurred_at DESC,c.commit_id DESC
        LIMIT LEAST(GREATEST(p_limit,1),501)
      ) page
    ), '[]'))
  END
  FROM (SELECT 1) singleton;
$$;


ALTER FUNCTION public.get_client_commits_scoped_internal_v1(p_occasion bigint, p_before_time timestamp with time zone, p_before_id uuid, p_limit integer, p_filters jsonb, p_include_unit boolean, p_include_organization boolean) OWNER TO postgres;

--
-- Name: get_client_commits_v1(bigint, timestamp with time zone, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_client_commits_v1(p_occasion bigint, p_before_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_client_commits_scoped_internal_v1(p_occasion,p_before_time,p_before_id,p_limit,p_filters,true,true);
$$;


ALTER FUNCTION public.get_client_commits_v1(p_occasion bigint, p_before_time timestamp with time zone, p_before_id uuid, p_limit integer, p_filters jsonb) OWNER TO postgres;

--
-- Name: get_client_sync_artifact_retention_candidates_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_client_sync_artifact_retention_candidates_v1(p_cutoff timestamp with time zone, p_limit integer DEFAULT 200) RETURNS TABLE(artifact_url text, published_at timestamp with time zone, byte_size bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.require_client_sync_artifact_cutoff_v1(p_cutoff);
  IF p_limit NOT BETWEEN 1 AND 1000 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid retention candidate limit';
  END IF;
  RETURN QUERY
  WITH protected_urls AS (
    SELECT h.head_json#>>'{live,url}' url
    FROM public.client_sync_public_heads h
    UNION
    SELECT component.value->>'url'
    FROM public.client_sync_public_heads h
    CROSS JOIN LATERAL jsonb_each(COALESCE(h.head_json#>'{catalog,components}','{}')) component
    UNION
    SELECT component.value->>'url'
    FROM public.client_sync_release_manifests m
    JOIN public.client_sync_public_heads h
      ON h.scope_type=m.scope_type AND h.scope_id=m.scope_id
      AND h.release_revision=m.release_revision
    CROSS JOIN LATERAL jsonb_each(COALESCE(m.manifest->'components','{}')) component
  ), protected_manifests AS (
    SELECT m.artifact_url
    FROM public.client_sync_release_manifests m
    JOIN public.client_sync_public_heads h
      ON h.scope_type=m.scope_type AND h.scope_id=m.scope_id
    WHERE m.release_revision=h.release_revision
       OR m.release_revision=(
         SELECT max(previous.release_revision)
         FROM public.client_sync_release_manifests previous
         WHERE previous.scope_type=m.scope_type AND previous.scope_id=m.scope_id
           AND previous.release_revision<h.release_revision
       )
  ), candidates AS (
    SELECT p.artifact_url,p.published_at,p.byte_size
    FROM public.client_sync_publications p
    WHERE p.published_at<p_cutoff
      AND p.artifact_url LIKE 'https://assets.festapp.net/client-sync/v1/%'
      AND NOT EXISTS (SELECT 1 FROM protected_urls u WHERE u.url=p.artifact_url)
    UNION ALL
    SELECT m.artifact_url,m.published_at,m.byte_size
    FROM public.client_sync_release_manifests m
    WHERE m.published_at<p_cutoff
      AND m.artifact_url LIKE 'https://assets.festapp.net/client-sync/v1/%'
      AND NOT EXISTS (SELECT 1 FROM protected_manifests p WHERE p.artifact_url=m.artifact_url)
  )
  SELECT c.artifact_url,c.published_at,c.byte_size FROM candidates c
  ORDER BY c.published_at,c.artifact_url LIMIT p_limit;
END; $$;


ALTER FUNCTION public.get_client_sync_artifact_retention_candidates_v1(p_cutoff timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- Name: get_client_sync_publication_state_v1(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_client_sync_publication_state_v1(p_scope_type text, p_scope_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_scope text; v_head public.client_sync_public_heads%ROWTYPE; v_components jsonb;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_scope_type <> 'occasion' THEN RAISE EXCEPTION 'unsupported scope type'; END IF;
  SELECT o.organization::text||'/'||o.id::text INTO v_scope
  FROM public.occasions o WHERE o.id=p_scope_id AND NOT o.is_hidden;
  IF v_scope IS NULL THEN RAISE EXCEPTION 'scope is not publicly publishable'; END IF;
  SELECT * INTO v_head FROM public.client_sync_public_heads
    WHERE scope_type=p_scope_type AND scope_id=p_scope_id;
  WITH required(component) AS (VALUES ('occasion_config'),('program_catalog'),
    ('map_catalog'),('content_catalog'),('unit_catalog')),
  latest AS (
    SELECT DISTINCT ON (p.component) p.* FROM public.client_sync_publications p
    JOIN required r ON r.component=p.component
    WHERE p.scope_type=p_scope_type AND p.scope_id=p_scope_id
    ORDER BY p.component,p.published_revision DESC
  ) SELECT COALESCE(jsonb_object_agg(component,jsonb_build_object(
      'revision',published_revision,'mediaType',media_type,'url',artifact_url,
      'sha256',sha256,'bytes',byte_size)),'{}') INTO v_components FROM latest;
  RETURN jsonb_build_object('scope',v_scope,'components',v_components,
    'catalog',v_head.head_json->'catalog','live',v_head.head_json->'live',
    'headEtag',v_head.head_etag);
END; $$;


ALTER FUNCTION public.get_client_sync_publication_state_v1(p_scope_type text, p_scope_id bigint) OWNER TO postgres;

--
-- Name: get_companion_feature_policy_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_companion_feature_policy_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT jsonb_build_object(
    'is_enabled',COALESCE((feature->>'is_enabled')::boolean,false),
    'allow_user_create',COALESCE((feature->>'allow_user_create')::boolean,true),
    'allow_admin_assign',COALESCE((feature->>'allow_admin_assign')::boolean,false),
    'max_companions',GREATEST(COALESCE((feature->>'max_companions')::integer,1),1))
  FROM public.occasions o
  LEFT JOIN LATERAL (
    SELECT item AS feature FROM jsonb_array_elements(COALESCE(o.features,'[]')) item
    WHERE item->>'code'='companions' LIMIT 1
  ) configured ON true
  WHERE o.id=p_occasion;
$$;


ALTER FUNCTION public.get_companion_feature_policy_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_configuration_settings(text, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_configuration_settings(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE snapshot jsonb; version bigint;
BEGIN
 IF p_entity_type='occasion' THEN PERFORM 1 FROM public.occasions WHERE id=p_entity_id FOR SHARE;
 ELSE PERFORM 1 FROM public.units WHERE id=p_entity_id FOR SHARE; END IF;
 PERFORM public.check_configuration_scope_internal_v1(p_entity_type,p_entity_id,p_organization,p_unit,false);
 IF p_entity_type='occasion' THEN SELECT to_jsonb(o) INTO snapshot FROM public.occasions o WHERE id=p_entity_id;
 ELSE SELECT to_jsonb(u) INTO snapshot FROM public.units u WHERE id=p_entity_id; END IF;
 SELECT COALESCE(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type=p_entity_type AND v.scope_type=p_entity_type AND v.scope_id=p_entity_id AND v.aggregate_id=p_entity_id::text;
 RETURN public.project_configuration_settings_internal_v1(p_entity_type,snapshot||jsonb_build_object('aggregate_version',version));
END $$;


ALTER FUNCTION public.get_configuration_settings(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint) OWNER TO postgres;

