--
-- Name: get_context_capabilities_v1(bigint, public.occasion_users, public.unit_users, boolean, boolean, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_context_capabilities_v1(p_occasion bigint, p_occasion_user public.occasion_users, p_unit_user public.unit_users, p_admin boolean, p_demo boolean, p_demo_unit boolean, p_demo_read boolean, p_has_units boolean, p_current_unit_listed boolean, p_reception_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
 editor boolean := (NOT (p_demo) AND coalesce((p_occasion_user.is_editor),false));
 viewer boolean := ((p_demo_read) OR (NOT ((p_demo)) AND coalesce(((p_occasion_user.is_editor_view)),false)));
 manager boolean := (NOT (p_demo) AND coalesce((p_occasion_user.is_manager),false));
 unit_editor boolean := (NOT (p_demo_unit) AND coalesce((p_unit_user.is_editor),false));
 unit_manager boolean := (NOT (p_demo_unit) AND coalesce((p_unit_user.is_manager),false));
 admin boolean := coalesce(p_admin,false);
 actor_present boolean := auth.uid() IS NOT NULL;
 order_reader boolean; order_writer boolean; map_reader boolean;
 form_author boolean; layout_author boolean; administration_navigation boolean;
BEGIN
 -- Each repeated operation fact is evaluated once for this request's loaded
 -- rows. These are local booleans, never a persisted or token permission cache.
 SELECT ((((p_demo_read)) OR (NOT (((p_demo))) AND coalesce((((p_occasion_user.is_editor_order_view))),false)))),
   ((NOT ((p_demo)) AND coalesce(((p_occasion_user.is_editor_order)),false))),
   ((viewer) OR (editor)),((editor) OR (unit_editor)),
   p_occasion IS NOT NULL AND ((actor_present) AND coalesce((unit_editor),false)),
   ((p_demo_read) OR (editor) OR (manager) OR coalesce((p_unit_user.is_editor_view),false) OR (admin))
 INTO order_reader,order_writer,map_reader,form_author,layout_author,administration_navigation;
 RETURN jsonb_build_object(
    'ticket_layouts.read',layout_author,
    'ticket_layouts.write',layout_author,
    'orders.read',order_reader,
    'orders.write',order_writer,
    'occasions.delete',p_occasion IS NOT NULL AND unit_manager,
    'bank_accounts.unit.manage',unit_manager,
    'schedule.feedback.delete',admin,
    'navigation.email_history',admin,
    'orders.delete',p_occasion IS NOT NULL AND ((unit_manager) OR (unit_editor) OR (admin)),
    'occasions.create',((unit_manager) OR (unit_editor)),
    'occasions.write',p_occasion IS NOT NULL AND ((unit_editor) AND (unit_editor)),
    'users.write',p_occasion IS NOT NULL AND actor_present AND ((manager) OR (admin) OR (unit_editor)),
    'emails.custom.send',((editor) OR (order_writer)),
    'email_templates.occasion.read',((viewer) OR (order_reader)),
    'email_templates.occasion.write',((editor) OR (order_writer)),
    'email_templates.unit.read',((unit_manager) OR (unit_editor) OR coalesce((p_unit_user.is_editor_view),false)),
    'email_templates.unit.write',unit_editor,
    'media.occasion.write',((editor) OR (order_writer)),
    'media.unit.write',unit_editor,
    'unit.settings.write',unit_manager,
    'unit.legal_profile.write',unit_manager,
    'unit.administration.read',coalesce(p_unit_user.is_editor_view,false),
    'companions.assign',((actor_present) AND (editor)),
    'navigation.schedule_entry_check',(coalesce((p_occasion_user.is_approver),false)),
    'navigation.cleaning_crew',(coalesce((p_occasion_user.is_cleaning_crew),false)),
    'navigation.organization_settings',admin,
    'navigation.occasion_settings',unit_editor OR p_demo_read,
    'forms.create',p_occasion IS NOT NULL AND form_author,
    'forms.write',p_occasion IS NOT NULL AND NOT p_demo AND form_author,
    'forms.measurement.write',p_occasion IS NOT NULL AND (coalesce((form_author),false) AND NOT coalesce((p_demo),true)),
    'forms.delete',p_occasion IS NOT NULL AND form_author,
    'forms.catalog.read',p_occasion IS NOT NULL AND ((viewer) OR (order_reader) OR (form_author)),
    'forms.copy.source',(coalesce((p_occasion_user.is_editor_view),false) OR coalesce((p_unit_user.is_editor_view),false)),
    'forms.copy.target',editor,
    'occasions.editor.read',p_occasion IS NOT NULL AND (coalesce((viewer),false) OR coalesce((manager),false) OR coalesce((admin),false)),
    'news.write',editor) || jsonb_build_object(
    'schedule.write',editor,
    'schedule.editor.read',viewer,
    'schedule.participants.read',((viewer) OR (editor) OR (admin)),
    'schedule.feedback.read',((viewer) OR (admin)),
    'speakers.write',editor,
    'speakers.editor.read',viewer,
    'services.write',manager,
    'participants.write',((manager) OR (admin)),
    'participants.contacts.read',((editor) OR (manager) OR (coalesce(p_occasion_user.is_approver,false))),
    'forms.sale_opening_subscribers.read',((editor) OR (manager) OR (coalesce(p_occasion_user.is_approver,false))),
    'groups.assignments.write',((editor) OR (((manager)) OR ((admin)) OR ((unit_editor)))),
    'blueprints.write',((editor) OR (manager)),
    'inventory.copy.target',((order_writer) OR (unit_manager)),
    'activities.write',editor,
    'activities.editor.read',map_reader,
    'information.write',editor,
    'unit_information.read',coalesce(p_unit_user.is_editor_view,false),
    'unit_information.write',unit_editor,
    'scanner.settings.write',((actor_present) AND ((editor) OR (order_writer))),
    'reception.use',((p_reception_enabled) AND (coalesce((p_occasion_user.is_receptionist),false) OR (manager) OR (admin))),
    'information.editor.read',viewer,
    'map.places.write',editor,
    'groups.editor.read',map_reader,
    'groups.create',editor,
    'map.editor.read',map_reader,
    'reception.participants.manage',((manager) OR (admin)),
    'unit_users.read',(coalesce((p_unit_user.is_manager),false) OR coalesce((p_unit_user.is_editor),false) OR coalesce((p_unit_user.is_editor_view),false)),
    'unit_users.write',unit_manager,
    'navigation.admin_app',administration_navigation,
    'navigation.admin_web',administration_navigation OR p_has_units,
    'navigation.administration',p_demo_read OR coalesce(p_unit_user.is_editor_view,false) OR viewer,
    'navigation.unit_workspace',(coalesce((p_current_unit_listed),false) OR coalesce((unit_editor),false) OR coalesce((unit_manager),false) OR coalesce((p_unit_user.is_editor_view),false)));
END;
$$;


ALTER FUNCTION public.get_context_capabilities_v1(p_occasion bigint, p_occasion_user public.occasion_users, p_unit_user public.unit_users, p_admin boolean, p_demo boolean, p_demo_unit boolean, p_demo_read boolean, p_has_units boolean, p_current_unit_listed boolean, p_reception_enabled boolean) OWNER TO postgres;

--
-- Name: get_counseling_availability(bigint, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_counseling_availability(p_occasion bigint, p_topic bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_uid        UUID := auth.uid();
    v_counselors JSONB;
BEGIN
    -- Feature gate.
    IF NOT public.get_is_counseling_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    -- The chosen topic must belong to the occasion and be visible.
    -- NOTE (decision R3): the topic is only a filter — it is never stored.
    IF NOT EXISTS (
        SELECT 1 FROM public.speaker_topics t
        WHERE t.id = p_topic AND t.occasion = p_occasion AND t.is_hidden = FALSE
    ) THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id',       s.id,
            'title',    s.title,
            'subtitle', s.subtitle,
            'image',    s.image,
            'slots', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                    'id',               e.id,
                    'start_time',       e.start_time,
                    'end_time',         e.end_time,
                    'place',            e.place,
                    'place_title',      (SELECT pl.title FROM public.places pl WHERE pl.id = e.place),
                    'max_participants', e.max_participants,
                    'occupied',         (SELECT count(*) FROM public.event_users eu WHERE eu.event = e.id),
                    'isSignedIn',       (v_uid IS NOT NULL AND EXISTS (
                                            SELECT 1 FROM public.event_users eu2
                                            WHERE eu2.event = e.id AND eu2."user" = v_uid))
                ) ORDER BY e.start_time)
                FROM public.event_speakers es
                JOIN public.events e ON e.id = es.event
                WHERE es.speaker = s.id
                  AND e.occasion = p_occasion
                  AND (e.data->>'is_counseling_slot')::boolean IS TRUE
                  AND e.end_time > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
                  AND (p_from IS NULL OR e.start_time >= p_from)
                  AND (p_to   IS NULL OR e.start_time <  p_to)
            ), '[]'::jsonb)
        ) ORDER BY s."order", s.title
    ), '[]'::jsonb)
    INTO v_counselors
    FROM public.speakers s
    JOIN public.speaker_topic_links stl ON stl.speaker = s.id AND stl.topic = p_topic
    WHERE s.occasion = p_occasion AND s.is_hidden = FALSE
      -- Only counselors who actually have a slot in the window.
      AND EXISTS (
          SELECT 1
          FROM public.event_speakers es
          JOIN public.events e ON e.id = es.event
          WHERE es.speaker = s.id
            AND e.occasion = p_occasion
            AND (e.data->>'is_counseling_slot')::boolean IS TRUE
            AND e.end_time > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
            AND (p_from IS NULL OR e.start_time >= p_from)
            AND (p_to   IS NULL OR e.start_time <  p_to)
      );

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('counselors', v_counselors)
    );
END;
$$;


ALTER FUNCTION public.get_counseling_availability(p_occasion bigint, p_topic bigint, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: get_counseling_topics_overview(bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_counseling_topics_overview(p_occasion bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_topics JSONB;
BEGIN
    IF NOT public.get_is_counseling_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id',                 t.id,
            'title',              t.title,
            'order',              t."order",
            'total_future_slots', COALESCE(fs.total, 0),
            'free_future_slots',  COALESCE(fs.free, 0)
        ) ORDER BY t."order", t.title
    ), '[]'::jsonb)
    INTO v_topics
    FROM public.speaker_topics t
    LEFT JOIN LATERAL (
        SELECT
            count(*) AS total,
            count(*) FILTER (
                WHERE e.max_participants IS NULL
                   OR (SELECT count(*) FROM public.event_users eu WHERE eu.event = e.id) < e.max_participants
            ) AS free
        FROM public.events e
        WHERE e.occasion = p_occasion
          AND (e.data->>'is_counseling_slot')::boolean IS TRUE
          AND e.end_time > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
          AND (p_from IS NULL OR e.start_time >= p_from)
          AND (p_to   IS NULL OR e.start_time <  p_to)
          AND EXISTS (
              SELECT 1
              FROM public.event_speakers es
              JOIN public.speakers s ON s.id = es.speaker
              JOIN public.speaker_topic_links stl ON stl.speaker = s.id
              WHERE es.event = e.id
                AND s.occasion = p_occasion
                AND s.is_hidden = FALSE
                AND stl.topic = t.id
          )
    ) fs ON TRUE
    WHERE t.occasion = p_occasion
      AND t.is_hidden = FALSE;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('topics', v_topics)
    );
END;
$$;


ALTER FUNCTION public.get_counseling_topics_overview(p_occasion bigint, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: get_current_organization_data(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_current_organization_data() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    organization_id bigint;
    org_data jsonb;
    organization_user record;
BEGIN
    -- Retrieve the organization ID associated with the current authenticated user
    SELECT organization INTO organization_id
    FROM organization_users
    WHERE "user" = auth.uid()
      AND is_admin = true
    LIMIT 1;

    -- If the user is not associated with any organization as an admin, return a 403 code
    IF organization_id IS NULL THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Retrieve the organization data as jsonb
    SELECT jsonb_build_object(
        'id', id,
        'title', title,
        'data', data,
        'phone_prefixes', phone_prefixes -- Added phone_prefixes
    ) INTO org_data
    FROM organizations
    WHERE id = organization_id;

    -- Return the organization data with a 200 code
    RETURN jsonb_build_object('code', 200, 'data', org_data);
END;
$$;


ALTER FUNCTION public.get_current_organization_data() OWNER TO postgres;

--
-- Name: get_current_quote(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_current_quote(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    unit_rec RECORD;
    unit_features jsonb;
    quotes_feature jsonb;
    feature_idx int;
    feature jsonb;
    feature_found BOOLEAN := FALSE;
    curr_quote_id bigint;
    curr_quote_date text;  -- stored as 'YYYY-MM-DD'
    curr_quote_rec RECORD;
    next_quote_rec RECORD;
    updated_features jsonb;
    v_current_date text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD');
BEGIN
    -- Lock the unit row to prevent concurrent updates
    SELECT *
    INTO unit_rec
    FROM public.units
    WHERE id = unit_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;

    unit_features := unit_rec.features;
    IF unit_features IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No features configured for this unit');
    END IF;

    -- Find the enabled "quotes" feature in the JSON array
    FOR feature_idx IN 0 .. jsonb_array_length(unit_features) - 1 LOOP
        feature := unit_features -> feature_idx;
        IF (feature ->> 'code') = 'quotes'
           AND (feature ->> 'is_enabled') = 'true' THEN
            quotes_feature := feature;
            feature_found := TRUE;
            EXIT;
        END IF;
    END LOOP;

    IF NOT feature_found THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Quotes feature is not enabled for this unit');
    END IF;

    -- Retrieve stored quote_id and quote_date from the feature
    curr_quote_id := NULL;
    IF quotes_feature ? 'quote_id' THEN
        curr_quote_id := (quotes_feature ->> 'quote_id')::bigint;
    END IF;

    curr_quote_date := NULL;
    IF quotes_feature ? 'quote_date' THEN
        curr_quote_date := quotes_feature ->> 'quote_date';
    END IF;

    -- If a stored quote exists and its date equals today's UTC date, try to fetch it
    IF curr_quote_id IS NOT NULL AND curr_quote_date = v_current_date THEN
        SELECT *
        INTO curr_quote_rec
        FROM public.information
        WHERE id = curr_quote_id
          AND type = 'quote'
          AND occasion IS NULL
          AND unit = unit_id
          AND is_hidden = false
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object('code', 200, 'data', row_to_json(curr_quote_rec));
        END IF;
    END IF;

    -- No valid quote for today; select a new random quote.
    SELECT *
    INTO next_quote_rec
    FROM public.information
    WHERE type = 'quote'
      AND occasion IS NULL
      AND unit = unit_id
      AND is_hidden = false
    ORDER BY random()
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No quotes found for this unit');
    END IF;

    -- Update the feature with the new quote id and today's UTC date
    updated_features := unit_features;
    FOR feature_idx IN 0 .. jsonb_array_length(unit_features) - 1 LOOP
        feature := unit_features -> feature_idx;
        IF (feature ->> 'code') = 'quotes'
           AND (feature ->> 'is_enabled') = 'true' THEN
            updated_features := jsonb_set(
                updated_features,
                ARRAY[feature_idx::text],
                (feature || jsonb_build_object(
                    'quote_id', next_quote_rec.id,
                    'quote_date', v_current_date
                ))
            );
            EXIT;
        END IF;
    END LOOP;

    UPDATE public.units
    SET features = updated_features
    WHERE id = unit_id;

    RETURN jsonb_build_object('code', 200, 'data', row_to_json(next_quote_rec));
END;
$$;


ALTER FUNCTION public.get_current_quote(unit_id bigint) OWNER TO postgres;

--
-- Name: get_customer_order_overview(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_customer_order_overview(input_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; p record;
BEGIN
 result:=public.get_customer_order_overview_internal(input_data->>'token',(input_data->>'order_id')::bigint);
 IF result->>'code'='200' THEN
  FOR p IN SELECT pi.data->'payment_policy' policy,pi.payment_method method FROM eshop.orders o
   JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.id IN(SELECT (x->>'id')::bigint FROM jsonb_array_elements(result->'orders') x) LOOP
   PERFORM public.check_payment_client_capabilities_internal(p.policy,p.method,input_data->'client_capabilities');
  END LOOP;
 END IF;
 RETURN result;
EXCEPTION WHEN raise_exception THEN
 IF left(SQLERRM,1)='{' THEN RETURN SQLERRM::jsonb; END IF; RAISE;
END $$;


ALTER FUNCTION public.get_customer_order_overview(input_data jsonb) OWNER TO postgres;

--
-- Name: get_customer_order_overview(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_customer_order_overview(p_token text, p_order_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_customer_order_overview(jsonb_build_object('token',p_token,'order_id',p_order_id));
$$;


ALTER FUNCTION public.get_customer_order_overview(p_token text, p_order_id bigint) OWNER TO postgres;

--
-- Name: get_customer_order_overview_internal(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_customer_order_overview_internal(p_token text, p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE root eshop.orders; cap eshop.waitlist_capabilities; occ public.occasions; f public.forms;
 ids bigint[]; result jsonb;
BEGIN
 PERFORM set_config('response.headers','[{"Cache-Control":"no-store"},{"Referrer-Policy":"no-referrer"}]',true);
 SELECT * INTO root FROM eshop.orders WHERE id=p_order_id AND source_waitlist_order_id IS NULL;
 SELECT * INTO occ FROM public.occasions WHERE id=root.occasion;
 SELECT * INTO f FROM public.forms WHERE id=root.form AND occasion=occ.id;
 SELECT * INTO cap FROM eshop.waitlist_capabilities WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
 AND kind='order_view' AND order_id=root.id AND form_id=f.id AND organization_id=occ.organization
 AND revoked_at IS NULL AND expires_at>statement_timestamp();
 IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' OR cap.token_hash IS NULL THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 SELECT array_agg(id) INTO ids FROM eshop.orders WHERE id=root.id OR (source_waitlist_order_id=root.id AND NOT (
  NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE "order"=eshop.orders.id)
  AND EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE target_order_id=eshop.orders.id AND source_order_id=root.id AND state='aborted')));
 -- Reject malformed provenance rather than expanding an apparently related scope.
 IF EXISTS(SELECT 1 FROM eshop.orders o WHERE o.id=ANY(ids) AND (o.form IS DISTINCT FROM f.id OR o.occasion IS DISTINCT FROM occ.id))
 OR EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.tickets t ON t.id=x.ticket WHERE x."order"=ANY(ids)
  AND (t.occasion<>occ.id OR EXISTS(SELECT 1 FROM eshop.order_product_ticket y WHERE y.ticket=t.id AND y."order" IS DISTINCT FROM x."order")))
 OR EXISTS(SELECT 1 FROM eshop.orders o WHERE o.id=ANY(ids) AND o.source_waitlist_order_id=root.id AND NOT EXISTS(
  SELECT 1 FROM eshop.waitlist_offer_slots s JOIN eshop.waitlist_offers w ON w.id=s.offer_id
  JOIN eshop.order_product_ticket x ON x.ticket=s.ticket_id AND x."order"=o.id
  WHERE w.order_id=root.id AND w.form_id=f.id AND s.form_id=f.id AND s.outcome='accepted' AND s.resulting_order_id=o.id))
 OR EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x."order"=ANY(ids) AND x."order"<>root.id AND NOT EXISTS(
  SELECT 1 FROM eshop.waitlist_offer_slots s JOIN eshop.waitlist_offers w ON w.id=s.offer_id
  WHERE s.ticket_id=x.ticket AND s.resulting_order_id=x."order" AND s.outcome='accepted' AND w.order_id=root.id AND w.form_id=f.id))
 THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 SELECT jsonb_build_object('code',200,'root',jsonb_build_object('id',root.id,'symbol',root.order_symbol,'createdAt',root.created_at,'state',root.state,'title',occ.title,'formLink',f.link,'hasTickets',EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(occ.features,'[]')) feature WHERE feature->>'code'='ticket' AND feature->>'is_enabled'='true')),
 'timeline',(SELECT coalesce(jsonb_agg(event ORDER BY happened,sort_key),'[]') FROM (
  SELECT root.created_at happened,'0' sort_key,jsonb_build_object('kind',CASE WHEN root.state='waitlisted' THEN 'waitlist_entered' ELSE 'order_ordered' END,'at',root.created_at,'symbol',root.order_symbol) event
  WHERE root.state='waitlisted' OR NOT EXISTS(SELECT 1 FROM eshop.orders_history WHERE "order"=root.id AND state='ordered')
  UNION ALL
  SELECT w.created_at,'1'||w.id::text,jsonb_build_object('kind','places_offered','at',w.created_at)
  FROM eshop.waitlist_offers w WHERE w.order_id=root.id AND w.form_id=f.id
  UNION ALL
  SELECT s.updated_at,'2'||s.id::text,jsonb_build_object('kind','offer_'||s.outcome,'at',s.updated_at)
  FROM eshop.waitlist_offer_slots s JOIN eshop.waitlist_offers w ON w.id=s.offer_id
  WHERE w.order_id=root.id AND w.form_id=f.id AND s.form_id=f.id AND s.outcome IN ('accepted','declined','cancelled','expired')
  UNION ALL
  SELECT t.created_at,'4'||t.id::text,jsonb_build_object('kind',CASE WHEN t.transaction_type='return' THEN 'refund' WHEN t.amount>0 THEN 'payment_received' ELSE 'payment_adjustment' END,
   'at',t.created_at,'timeKind','recorded','amount',t.amount,'currency',trim(t.currency),'symbol',o.order_symbol,
   'paymentMethod',CASE WHEN b.type='CASH' THEN 'cash' WHEN nullif(trim(b.account_number),'') IS NOT NULL THEN 'bank' END,
   'recipientAccount',CASE WHEN b.type<>'CASH' THEN coalesce(nullif(trim(b.account_number_human_readable),''),nullif(trim(b.account_number),'')) END)
  FROM eshop.orders o JOIN eshop.transactions t ON t.payment_info=o.payment_info LEFT JOIN eshop.bank_accounts b ON b.id=t.bank_account_id WHERE o.id=ANY(ids) AND t.created_at IS NOT NULL
  UNION ALL
  SELECT h.created_at,'3'||h.id::text,jsonb_build_object(
   'kind',CASE WHEN h.state IS DISTINCT FROM h.previous_state THEN 'order_'||h.state ELSE 'order_changed' END,
   'at',h.created_at,'symbol',h.order_symbol,'previousState',h.previous_state,'state',h.state,
   'previousTotal',CASE WHEN h.price IS DISTINCT FROM h.previous_price AND h.previous_state IS NOT NULL THEN h.previous_price END,
   'total',h.price,'currency',h.currency_code,
   'itemsChanged',h.previous_state IS NOT NULL AND h.items IS DISTINCT FROM h.previous_items,
   'itemsBefore',CASE WHEN h.previous_state IS NOT NULL AND h.items IS DISTINCT FROM h.previous_items THEN h.previous_items END,
   'itemsAfter',CASE WHEN h.previous_state IS NOT NULL AND h.items IS DISTINCT FROM h.previous_items THEN h.items END,
   'detailsChanged',h.previous_state IS NOT NULL AND h.details IS DISTINCT FROM h.previous_details)
  FROM (SELECT snapshots.*,lag(state) OVER w previous_state,lag(price) OVER w previous_price,
   lag(items) OVER w previous_items,lag(details) OVER w previous_details FROM (
    SELECT h.id,h.created_at,h."order",h.state,h.price,coalesce(h.currency_code,o.currency_code) currency_code,o.order_symbol,
     (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p->'id','ticketId',t->'id','ticketSymbol',t->>'ticket_symbol','title',p->>'title','price',p->'price') ORDER BY t->>'id',p->>'id'),'[]')
      FROM jsonb_array_elements(coalesce(h.data->'tickets','[]')) t
      CROSS JOIN LATERAL jsonb_array_elements(coalesce(t->'products','[]')) p) items,
     jsonb_build_object('fields',coalesce(h.data->'fields',h.data#>'{input_data,fields}'),'tickets',
      (SELECT jsonb_agg(jsonb_build_object('id',t->'id','fields',t->'fields') ORDER BY t->>'id') FROM jsonb_array_elements(coalesce(h.data->'tickets','[]')) t)) details
    FROM eshop.orders_history h JOIN eshop.orders o ON o.id=h."order" WHERE h."order"=ANY(ids)
      AND h.state IN ('ordered','paid','sent','storno') AND (h.price IS NOT NULL OR h.data ? 'tickets')
   ) snapshots WINDOW w AS (PARTITION BY "order" ORDER BY created_at,id)) h
  WHERE h.state IS DISTINCT FROM h.previous_state OR h.price IS DISTINCT FROM h.previous_price
   OR h.items IS DISTINCT FROM h.previous_items OR h.details IS DISTINCT FROM h.previous_details
 ) events),
 'organizationIdentity',CASE WHEN occ.organization=(SELECT organization FROM public.units WHERE id=occ.unit) THEN public.get_verified_unit_identity_internal(occ.unit) END,
 'serverTime',statement_timestamp(),'accessExpiresAt',cap.expires_at,'actions',jsonb_build_array('refresh'),
 'people',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'label',public.customer_ticket_label_internal(t.id,f.id),'symbol',t.ticket_symbol,
  'answers',public.customer_order_answers_internal(f.id,t.data,true),'effectiveLifecycle',CASE WHEN (SELECT state FROM eshop.orders WHERE id=x."order")='preparing_payment' THEN 'preparing' ELSE public.get_effective_waitlist_ticket_lifecycle_internal(t.id) END,'currentOrderId',x."order") ORDER BY t.id),'[]')
  FROM (SELECT DISTINCT "order",ticket FROM eshop.order_product_ticket WHERE "order"=ANY(ids)) x JOIN eshop.tickets t ON t.id=x.ticket),
 'offers',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',w.id,'expiresAt',w.expires_at,
  'pendingPlaces',(SELECT count(*) FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='pending' AND w.expires_at>statement_timestamp()),
  'effectiveStatus',CASE WHEN w.expires_at<=statement_timestamp() THEN 'expired'
   WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='pending') THEN 'pending'
   WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome IN ('declined','cancelled')) THEN 'cancelled' ELSE 'accepted' END)
  ORDER BY w.created_at,w.id),'[]') FROM eshop.waitlist_offers w WHERE w.order_id=root.id AND w.form_id=f.id),
 'orders',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'symbol',o.order_symbol,'state',o.state,'total',o.price,'currency',o.currency_code,
  'payment',public.customer_order_payment_internal(o.id),
  'answers',public.customer_order_answers_internal(f.id,o.data,false),
  'ticketIds',(SELECT coalesce(jsonb_agg(t.id ORDER BY t.id),'[]') FROM public.get_order_tickets_internal(o.id) t),
  'items',CASE WHEN o.state='preparing_payment' THEN '[]'::jsonb ELSE (SELECT coalesce(jsonb_agg(jsonb_build_object(
   'ticketId',t->'id','id',p->'id','title',p->>'title','spotTitle',p->>'spot_title','spotGroupTitle',p->>'spot_group_title','isStanding',coalesce((p->>'is_standing')::boolean,false),'standingAreaTitle',p->>'standing_area_title','price',p->'price','currency',p->>'currency_code') ORDER BY (t->>'id')::bigint,
    (SELECT min(coalesce(ff."order",0)) FROM public.form_fields ff WHERE ff.form=f.id AND ff.product_type=product.product_type) NULLS LAST,
    coalesce(product."order",0),product.id),'[]')
   FROM jsonb_array_elements(public.order_tickets_with_seating_internal(o.id,o.data->'tickets')) t CROSS JOIN LATERAL jsonb_array_elements(coalesce(t->'products','[]')) p
   JOIN eshop.products product ON product.id=(p->>'id')::bigint
   WHERE EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x."order"=o.id AND x.ticket=(t->>'id')::bigint AND x.product=(p->>'id')::bigint)) END,
  'tickets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'label',public.customer_ticket_label_internal(t.id,f.id),'rawState',t.state,
   'displayStatus',CASE t.state WHEN 'ordered' THEN 'awaiting_payment' WHEN 'paid' THEN 'unused' WHEN 'sent' THEN 'unused' WHEN 'used' THEN 'used' WHEN 'storno' THEN 'cancelled' ELSE 'unknown' END,
   'usageStatus',CASE t.state WHEN 'ordered' THEN 'unused' WHEN 'paid' THEN 'unused' WHEN 'sent' THEN 'unused' WHEN 'used' THEN 'used' WHEN 'storno' THEN 'cancelled' ELSE 'unknown' END) ORDER BY t.id),'[]')
   FROM public.get_order_tickets_internal(o.id) t)) ORDER BY o.id),'[]')
  FROM eshop.orders o WHERE o.id=ANY(ids) AND o.state IS DISTINCT FROM 'waitlisted')) INTO result;
 RETURN result;
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('code',403,'errorCode','INVALID_CAPABILITY');
END $_$;


ALTER FUNCTION public.get_customer_order_overview_internal(p_token text, p_order_id bigint) OWNER TO postgres;

--
-- Name: get_delegated_order_deletion_context(bigint, bigint, bigint, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_delegated_order_deletion_context(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid DEFAULT NULL::uuid, p_expected_revision text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 -- Deny unauthorized targets before acquiring a global send fence or foreign locks.
 PERFORM public.check_delegated_order_deletion_scope_internal_v1(p_occasion,p_organization,p_unit,p_order,p_command_id);
 -- Preserve the canonical email -> form -> order/capacity -> occasion order.
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 PERFORM 1 FROM public.forms WHERE id=(SELECT form FROM eshop.orders WHERE id=p_order) FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order) THEN PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]); END IF;
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit,false);
 PERFORM public.check_delegated_order_deletion_scope_internal_v1(p_occasion,p_organization,p_unit,p_order,p_command_id);
 result:=public.get_order_deletion_context_v1(p_order,p_command_id);
 IF result ? 'response' THEN RETURN result; END IF;
 IF p_expected_revision IS NOT NULL AND p_expected_revision IS DISTINCT FROM public.operator_order_revision_internal_v1(p_order) THEN RAISE serialization_failure USING MESSAGE='order changed before deletion'; END IF;
 RETURN result||jsonb_build_object('revision',public.operator_order_revision_internal_v1(p_order));
END $$;


ALTER FUNCTION public.get_delegated_order_deletion_context(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid, p_expected_revision text) OWNER TO postgres;

--
-- Name: get_delegated_ticket_layout_for_authoring_v1(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_delegated_ticket_layout_for_authoring_v1(p_occasion bigint, p_organization bigint, p_unit bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_unit bigint;
BEGIN
  SELECT o.unit INTO v_unit FROM public.occasions o
    WHERE o.id=p_occasion AND o.organization=p_organization
      AND (p_unit IS NULL OR o.unit=p_unit) FOR SHARE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info ui
      WHERE ui.id=auth.uid() AND ui.organization=p_organization) THEN
    RAISE insufficient_privilege USING MESSAGE='delegated occasion context unavailable';
  END IF;
  RETURN public.get_ticket_layout_for_authoring_v1(p_occasion);
END $$;


ALTER FUNCTION public.get_delegated_ticket_layout_for_authoring_v1(p_occasion bigint, p_organization bigint, p_unit bigint) OWNER TO postgres;

--
-- Name: get_demo_occasions(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_demo_occasions(p_organization bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info
   WHERE id=auth.uid() AND organization=p_organization) THEN
  RAISE insufficient_privilege USING MESSAGE='demo tenant access denied';
 END IF;
 RETURN jsonb_build_object(
  'hasOwnWork', EXISTS(SELECT 1 FROM public.occasions o
    WHERE o.organization=p_organization AND NOT public.is_demo_occasion(o.id)
     AND public.demo_own_work_rule(public.get_is_manager_on_unit(o.unit),public.get_is_editor_on_unit(o.unit),
      public.get_is_manager_on_occasion(o.id),public.get_is_editor_on_occasion(o.id)))
   OR EXISTS(SELECT 1 FROM public.occasion_setup_drafts d WHERE d.organization=p_organization
    AND public.can_create_occasion(d.unit)),
  'items', COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',o.id,'link',o.link,'title',o.title,'demoKey',d.demo_key,
    'fixtureVersion',d.fixture_version,'description',d.description,
    'referenceAt',d.reference_at,'image',o.data->>'image',
    'start_time',o.start_time,'end_time',o.end_time,
    'data',jsonb_build_object('timezone',o.data->>'timezone'),
    'features',(SELECT jsonb_agg(jsonb_build_object(
      'code',feature->>'code','is_enabled',(feature->>'is_enabled')::boolean))
      FROM jsonb_array_elements(o.features) feature),
    'stats',(SELECT jsonb_build_object(
      'total',count(*),'storno',count(*) FILTER(WHERE state='storno'),
      'paid_or_sent',count(*) FILTER(WHERE state IN ('paid','sent')),
      'ordered',count(*) FILTER(WHERE state='ordered'),
      'used',count(*) FILTER(WHERE state='used'),
      'users',(SELECT count(*) FROM public.occasion_users ou
        LEFT JOIN public.organization_users org_u
          ON org_u."user"=ou."user" AND org_u.organization=p_organization
        WHERE ou.occasion=o.id AND org_u.is_hidden IS NOT TRUE))
      FROM eshop.tickets t WHERE t.occasion=o.id)) ORDER BY d.sort_order)
   FROM public.demo_occasions d JOIN public.occasions o ON o.id=d.occasion
   WHERE d.organization=p_organization AND d.is_listed),'[]'::jsonb));
END $$;


ALTER FUNCTION public.get_demo_occasions(p_organization bigint) OWNER TO postgres;

--
-- Name: get_effective_form_data(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_effective_form_data(p_form_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT public.effective_form_metadata_internal(f.data,u.data) || jsonb_build_object(
        'analytics',public.form_measurement_runtime_internal(f.id)
    )
    FROM public.forms f
    JOIN public.occasions o ON o.id = f.occasion
    JOIN public.units u ON u.id = o.unit
    WHERE f.id = p_form_id;
$$;


ALTER FUNCTION public.get_effective_form_data(p_form_id bigint) OWNER TO postgres;

--
-- Name: get_effective_waitlist_ticket_lifecycle_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_effective_waitlist_ticket_lifecycle_internal(p_ticket bigint) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT CASE WHEN t.state='storno' THEN CASE WHEN t.ticket_symbol IS NULL THEN 'withdrawn' ELSE 'cancelled' END
 WHEN t.state IS DISTINCT FROM 'waitlisted' THEN 'admitted'
 WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots s JOIN eshop.waitlist_offers w ON w.id=s.offer_id WHERE s.ticket_id=t.id AND s.outcome='pending' AND w.expires_at>clock_timestamp()) THEN 'offered'
 ELSE coalesce((SELECT CASE s.outcome WHEN 'expired' THEN 'offer_expired' WHEN 'declined' THEN 'offer_declined' WHEN 'cancelled' THEN 'offer_cancelled' WHEN 'pending' THEN 'offer_expired' ELSE 'waiting' END
 FROM eshop.waitlist_offer_slots s JOIN eshop.waitlist_offers w ON w.id=s.offer_id WHERE s.ticket_id=t.id ORDER BY w.created_at DESC,s.updated_at DESC,s.id DESC LIMIT 1),'waiting') END
 FROM eshop.tickets t WHERE t.id=p_ticket;
$$;


ALTER FUNCTION public.get_effective_waitlist_ticket_lifecycle_internal(p_ticket bigint) OWNER TO postgres;

--
-- Name: get_email_authoring_payment_accounts(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_authoring_payment_accounts(p_unit_id bigint, p_occasion_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_organization bigint;
  v_linked jsonb;
  v_form_accounts jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  SELECT u.organization INTO v_organization
  FROM public.units u
  JOIN public.organizations o ON o.id = u.organization
  WHERE u.id = p_unit_id;
  IF v_organization IS NULL THEN
    RAISE EXCEPTION 'Invalid email authoring unit' USING ERRCODE = '22023';
  END IF;
  IF p_occasion_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.occasions o
    WHERE o.id = p_occasion_id AND o.unit = p_unit_id
      AND o.organization = v_organization
  ) THEN
    RAISE EXCEPTION 'Invalid email authoring occasion hierarchy' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'priority', uba.priority,
    'bank_accounts', jsonb_build_object(
      'id', ba.id,
      'type', ba.type,
      'account_number', ba.account_number,
      'account_number_human_readable', ba.account_number_human_readable,
      'supported_currencies', ba.supported_currencies
    )
  ) ORDER BY uba.priority, ba.id), '[]'::jsonb)
  INTO v_linked
  FROM eshop.unit_bank_accounts uba
  JOIN eshop.bank_accounts ba ON ba.id = uba.bank_account
  WHERE uba.unit = p_unit_id AND ba.type IS DISTINCT FROM 'CASH';

  SELECT COALESCE(jsonb_agg(account_id ORDER BY account_id), '[]'::jsonb)
  INTO v_form_accounts
  FROM (
    SELECT DISTINCT f.bank_account AS account_id
    FROM public.forms f
    JOIN eshop.unit_bank_accounts uba
      ON uba.bank_account = f.bank_account AND uba.unit = p_unit_id
    JOIN eshop.bank_accounts ba ON ba.id = f.bank_account
    WHERE f.occasion = p_occasion_id AND ba.type IS DISTINCT FROM 'CASH'
  ) configured;

  RETURN jsonb_build_object('linkedAccounts', v_linked, 'formAccountIds', v_form_accounts);
END;
$$;


ALTER FUNCTION public.get_email_authoring_payment_accounts(p_unit_id bigint, p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_email_banner(text, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_banner(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE context jsonb; result jsonb;
BEGIN
 context:=public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit);
 result:=public.get_email_banner_state_internal(context)||jsonb_build_object('entityType',p_entity_type,'entityId',p_entity_id);
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='email banner too large'; END IF;
 PERFORM public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit);
 RETURN result;
END $$;


ALTER FUNCTION public.get_email_banner(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint) OWNER TO postgres;

--
-- Name: get_email_banner_state_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_banner_state_internal(p_context jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object('overrideUrl',own_url,'inheritedUrl',inherited_url,
  'effectiveUrl',coalesce(own_url,inherited_url),'wrapperHtml',resolved->'wrapper'->'html',
  'revision',encode(extensions.digest(convert_to(jsonb_build_object('ownUrl',own_url,
    'inheritedUrl',inherited_url,'wrapper',resolved->'wrapper')::text,'UTF8'),'sha256'),'hex'))
 FROM (SELECT public.get_email_template_and_wrapper('',p_context) resolved,
  CASE WHEN p_context->>'occasion' IS NOT NULL THEN o.data->>'email_banner'
    ELSE u.data->>'email_banner' END own_url,
  CASE WHEN p_context->>'occasion' IS NOT NULL THEN coalesce(u.data->>'email_banner',org.data->>'email_banner')
    ELSE org.data->>'email_banner' END inherited_url
  FROM public.organizations org
  JOIN public.units u ON u.id=(p_context->>'unit')::bigint AND u.organization=org.id
  LEFT JOIN public.occasions o ON o.id=(p_context->>'occasion')::bigint AND o.unit=u.id
  WHERE org.id=(p_context->>'organization')::bigint) s;
$$;


ALTER FUNCTION public.get_email_banner_state_internal(p_context jsonb) OWNER TO postgres;

--
-- Name: get_email_confirmation_status(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_confirmation_status(p_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_message uuid; m public.email_messages;
BEGIN
 PERFORM public.require_service_role();
 UPDATE public.email_confirmation_receipts SET reads=reads+1 WHERE token_hash=p_hash AND expires_at>now() AND reads<15 RETURNING message_id INTO v_message;
 IF v_message IS NULL THEN RETURN 'unavailable'; END IF;
 SELECT * INTO m FROM public.email_messages WHERE message_id=v_message;
 RETURN CASE WHEN EXISTS(SELECT 1 FROM public.email_delivery_events e WHERE e.message_id=m.message_id AND e.invalid_recipient AND e.recipient=lower(m.recipient)) THEN 'invalid_email'
 WHEN m.bounced_at IS NOT NULL OR m.complained_at IS NOT NULL OR m.provider_failure IN ('reject','rendering_failure') THEN 'failed'
 WHEN m.delivered_at IS NOT NULL THEN 'delivered' WHEN m.workflow_state='accepted' THEN 'accepted' WHEN m.workflow_state IN ('unknown','dead','suppressed','expired','cancelled','retry_wait') THEN m.workflow_state ELSE 'queued' END;
END $$;


ALTER FUNCTION public.get_email_confirmation_status(p_hash text) OWNER TO postgres;

--
-- Name: get_email_delivery_detail(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_delivery_detail(p_message uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE m public.email_messages;
BEGIN
 SELECT * INTO m FROM public.email_messages WHERE message_id=p_message;
 IF m.message_id IS NULL THEN RAISE EXCEPTION 'email_detail_not_available'; END IF;
 IF NOT (CASE WHEN m.message_kind IN ('sale_opening_confirmation','sale_opening_opened') THEN public.can_read_sale_opening_subscribers(m.occasion) ELSE coalesce(public.email_report_allowed(m.organization,m.occasion),false) END) THEN RAISE EXCEPTION 'email_read_denied'; END IF;
 RETURN jsonb_build_object('message',jsonb_build_object('id',m.message_id,'kind',m.message_kind,'recipient',m.recipient,'created_at',m.created_at,'state',public.email_reporting_state(m),'tracking_policy',m.tracking_policy,'opened_at',m.opened_at,'clicked_at',m.clicked_at,'post_action',m.post_action_state,'last_error',m.last_error,'provider_id',m.provider_message_id,'requested_by',m.data->>'requested_by'),
 'attempts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',attempt_id,'state',state,'at',created_at,'error',error_code,'provider_id',provider_message_id) ORDER BY created_at),'[]') FROM public.email_attempts WHERE message_id=p_message),
 'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('type',event_type,'at',provider_time) ORDER BY provider_time),'[]') FROM (SELECT event_type,provider_time FROM public.email_delivery_events WHERE message_id=p_message ORDER BY provider_time DESC LIMIT 100) e));
END $$;


ALTER FUNCTION public.get_email_delivery_detail(p_message uuid) OWNER TO postgres;

--
-- Name: get_email_delivery_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_delivery_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c public.email_capacity;v_queue jsonb;v_times jsonb;v_provider jsonb;v_oldest timestamptz;v_post bigint;v_producer_access boolean;v_missing_templates jsonb;
BEGIN
 PERFORM public.require_service_role();
 -- The health RPC runs as its owner; inspect the actual producer role explicitly.
 v_producer_access:=has_schema_privilege('service_role','extensions','USAGE')
   AND has_function_privilege('service_role','extensions.digest(text,text)','EXECUTE')
   AND has_function_privilege('service_role','public.enqueue_order_email(text,jsonb,bigint,bigint,bigint,timestamptz,text)','EXECUTE')
   AND has_function_privilege('service_role','public.enqueue_account_email(text,jsonb,jsonb,text,jsonb,text,text,text,timestamptz)','EXECUTE')
   AND has_function_privilege('service_role','public.enqueue_prepared_email(text,jsonb,text,jsonb,text,text,text,timestamptz)','EXECUTE');
 -- Account routes resolve at organization scope before an email reaches the queue.
 SELECT coalesce(jsonb_agg(jsonb_build_object('organization',organization,'code',code)
   ORDER BY organization,code),'[]'::jsonb) INTO v_missing_templates
 FROM (
   SELECT o.id organization,codes.code,
     public.get_email_template_and_wrapper(codes.code,jsonb_build_object('organization',o.id)) resolved
   FROM public.organizations o CROSS JOIN unnest(ARRAY[
     'RESET_PASSWORD','SIGN_IN_CODE','ACCOUNT_DELETION_CONFIRM','ACCOUNT_DELETION_COMPLETE','APP_LINKS'
   ]) codes(code)
   WHERE o.data ? 'DEFAULT_URL' OR o.data->>'IS_APP_SUPPORTED'='true'
     OR o.data->>'IS_REGISTRATION_ENABLED'='true'
 ) templates
 WHERE jsonb_typeof(resolved->'template') IS DISTINCT FROM 'object'
   OR coalesce(length(btrim(resolved#>>'{template,subject}')),0)=0
   OR coalesce(length(btrim(resolved#>>'{template,html}')),0)=0;
 SELECT * INTO c FROM public.email_capacity;
 SELECT min(created_at) INTO v_oldest FROM public.email_messages WHERE workflow_state IN ('pending','retry_wait') AND target_time<=now();
 SELECT coalesce(jsonb_object_agg(workflow_state,n),'{}') INTO v_queue FROM (SELECT workflow_state,count(*) n FROM public.email_messages GROUP BY workflow_state) s;
 SELECT jsonb_build_object('commit_to_claim_seconds',avg(extract(epoch FROM a.created_at-m.created_at)),
 'preparation_seconds',avg(extract(epoch FROM m.prepared_at-a.created_at)) FILTER(WHERE m.prepared_at>=a.created_at),
 'ready_to_send_seconds',avg(extract(epoch FROM a.began_at-m.prepared_at)) FILTER(WHERE a.began_at>=m.prepared_at),
 'throttles',count(*) FILTER(WHERE error_code='throttled')) INTO v_times
 FROM public.email_attempts a JOIN public.email_messages m USING(message_id) WHERE a.created_at>now()-interval '1 day';
 SELECT jsonb_build_object('unmatched',count(*) FILTER(WHERE message_id IS NULL),'last_event_at',max(received_at),
 'feedback_lag_seconds',avg(extract(epoch FROM received_at-provider_time)) FILTER(WHERE received_at>now()-interval '1 day')) INTO v_provider FROM public.email_delivery_events;
 SELECT count(*) INTO v_post FROM public.email_messages WHERE workflow_state='accepted' AND post_action_state='pending';
 RETURN jsonb_build_object('queue',v_queue,'oldest_due_at',v_oldest,'timings_24h',v_times,'provider',v_provider,'post_action_backlog',v_post,'producer_access_ok',v_producer_access,'missing_account_templates',v_missing_templates,
 'capacity',jsonb_build_object('paused',c.paused,'quota_at',c.quota_at,'quota_fresh',coalesce(c.quota_at>now()-interval '15 minutes',false),
 'heartbeat_at',c.heartbeat_at,'circuit_until',c.circuit_until,'provider_outage_streak',c.provider_outage_streak,'probe_until',c.probe_until,'incident',c.wake_error,
 'effective_rate',CASE WHEN c.shared_account THEN least(c.max_rate*0.8,c.allocated_rate) ELSE c.max_rate*0.8 END*c.rate_factor,
 'allocated_daily',c.allocated_daily,'provider_sent_24h',c.provider_sent_24h),
 'alerts',to_jsonb(array_remove(ARRAY[
 CASE WHEN NOT v_producer_access THEN 'producer_permissions_missing' END,
 CASE WHEN jsonb_array_length(v_missing_templates)>0 THEN 'account_templates_missing' END,
 CASE WHEN NOT c.paused AND (c.quota_at IS NULL OR c.quota_at<now()-interval '15 minutes') THEN 'quota_stale' END,
 CASE WHEN v_oldest<now()-interval '5 minutes' THEN 'oldest_due' END,
 CASE WHEN v_oldest<now()-interval '5 minutes' AND (c.heartbeat_at IS NULL OR c.heartbeat_at<now()-interval '5 minutes') THEN 'worker_heartbeat_stale' END,
 CASE WHEN c.provider_outage_streak>0 THEN 'provider_outage' END,
 CASE WHEN c.wake_error IS NOT NULL THEN 'provider_or_wake_incident' END,
 CASE WHEN EXISTS(SELECT 1 FROM public.email_messages WHERE last_error='post_action_failed') THEN 'post_action_failed' END,
 CASE WHEN EXISTS(SELECT 1 FROM public.email_messages m WHERE accepted_at BETWEEN now()-interval '1 day' AND now()-interval '30 minutes' AND NOT EXISTS(SELECT 1 FROM public.email_delivery_events e WHERE e.message_id=m.message_id)) THEN 'feedback_overdue' END
 ],NULL)));
END $$;


ALTER FUNCTION public.get_email_delivery_health() OWNER TO postgres;

--
-- Name: get_email_delivery_overview(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_delivery_overview(p_occasion bigint, p_organization bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org bigint;
BEGIN
 v_org:=coalesce(p_organization,(SELECT organization FROM public.occasions WHERE id=p_occasion));
 IF NOT coalesce(public.email_report_allowed(v_org,p_occasion),false) THEN RAISE EXCEPTION 'email_read_denied'; END IF;
 RETURN (SELECT jsonb_build_object('messages',count(*),'accepted',count(*) FILTER(WHERE accepted_at IS NOT NULL),
 'delivered',count(*) FILTER(WHERE delivered_at IS NOT NULL),'bounced',count(*) FILTER(WHERE bounced_at IS NOT NULL),
 'complained',count(*) FILTER(WHERE complained_at IS NOT NULL),'opened_messages',count(*) FILTER(WHERE opened_at IS NOT NULL),
 'clicked_messages',count(*) FILTER(WHERE clicked_at IS NOT NULL),'tracking_coverage',count(*) FILTER(WHERE tracking_policy<>'disabled'),
 'unknown',count(*) FILTER(WHERE workflow_state='unknown'),'dead',count(*) FILTER(WHERE workflow_state='dead'),
 'feedback_overdue',count(*) FILTER(WHERE accepted_at BETWEEN now()-interval '1 day' AND now()-interval '30 minutes' AND NOT EXISTS(SELECT 1 FROM public.email_delivery_events e WHERE e.message_id=email_messages.message_id))) FROM public.email_messages WHERE organization=v_org AND (p_occasion IS NULL OR occasion=p_occasion));
END $$;


ALTER FUNCTION public.get_email_delivery_overview(p_occasion bigint, p_organization bigint) OWNER TO postgres;

--
-- Name: get_email_delivery_page(bigint, bigint, integer, bigint, text, text, bigint, uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_delivery_page(p_occasion bigint, p_before bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 30, p_order bigint DEFAULT NULL::bigint, p_kind text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_organization bigint DEFAULT NULL::bigint, p_user uuid DEFAULT NULL::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_orders_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb;v_org bigint;
BEGIN
 v_org:=coalesce(p_organization,(SELECT organization FROM public.occasions WHERE id=p_occasion));
 IF NOT coalesce(public.email_report_allowed(v_org,p_occasion,p_user),false) THEN RAISE EXCEPTION 'email_read_denied'; END IF;
 IF p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid_page_limit'; END IF;
 IF p_order IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion) THEN RAISE EXCEPTION 'email_scope_mismatch'; END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY id DESC),'[]') INTO v_result FROM (
 SELECT id,message_id,message_kind,recipient,order_id,(SELECT o.order_symbol FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion WHERE o.id=m.order_id AND oc.organization=m.organization AND o.occasion=m.occasion) order_symbol,created_at,accepted_at,delivered_at,bounced_at,complained_at,opened_at,clicked_at,
 public.email_reporting_state(m) state,tracking_policy,post_action_state,last_error FROM public.email_messages m
 WHERE organization=v_org AND (p_occasion IS NULL OR occasion=p_occasion OR (p_user IS NOT NULL AND occasion IS NULL))
 AND (p_user IS NULL OR recipient_user=p_user) AND (p_since IS NULL OR created_at>=p_since) AND (p_before IS NULL OR id<p_before) AND (p_order IS NULL OR order_id=p_order)
 AND (m.message_kind NOT IN ('sale_opening_confirmation','sale_opening_opened') OR public.can_read_sale_opening_subscribers(m.occasion))
 AND (NOT coalesce(p_orders_only,false) OR order_id IS NOT NULL)
 AND (p_kind IS NULL OR message_kind=p_kind) AND (p_state IS NULL OR public.email_reporting_state(m)=p_state)
 ORDER BY id DESC LIMIT p_limit) x;
 RETURN v_result;
END $$;


ALTER FUNCTION public.get_email_delivery_page(p_occasion bigint, p_before bigint, p_limit integer, p_order bigint, p_kind text, p_state text, p_organization bigint, p_user uuid, p_since timestamp with time zone, p_orders_only boolean) OWNER TO postgres;

