--
-- Name: get_email_template_and_wrapper(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_template_and_wrapper(p_code text, p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  result jsonb;
  email_template jsonb;
  email_wrapper jsonb;
  v_occ bigint;
  v_unit bigint;
  v_org bigint;
  v_actual_unit bigint;
  v_actual_org bigint;
BEGIN
  -- Extract context values. The ->> operator handles missing keys by returning SQL NULL.
  v_occ := (p_context->>'occasion')::bigint;
  v_unit := (p_context->>'unit')::bigint;
  v_org  := (p_context->>'organization')::bigint;

  -- Resolve ancestors even for an occasion-only context. Missing IDs must never
  -- become wildcards that select another occasion's template or wrapper.
  IF v_occ IS NOT NULL THEN
    SELECT unit, organization INTO v_actual_unit, v_actual_org FROM public.occasions WHERE id=v_occ;
    IF NOT FOUND OR (v_unit IS NOT NULL AND v_unit IS DISTINCT FROM v_actual_unit)
       OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE EXCEPTION 'Invalid email template hierarchy';
    END IF;
    v_unit := v_actual_unit;
    v_org := v_actual_org;
  ELSIF v_unit IS NOT NULL THEN
    SELECT organization INTO v_actual_org FROM public.units WHERE id=v_unit;
    IF NOT FOUND OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE EXCEPTION 'Invalid email template hierarchy';
    END IF;
    v_org := v_actual_org;
  END IF;

  email_template := public.get_resolved_email_template(p_code, jsonb_build_object(
    'occasion',v_occ,'unit',v_unit,'organization',v_org));

  -- Retrieve the most specific email wrapper using the same logic.
  SELECT to_jsonb(t)
  INTO email_wrapper
  FROM (
    SELECT
      ew.id,
      ew.title,
      ew.organization,
      ew.unit,
      ew.html,
      ew.created_at
    FROM public.email_wrappers ew
    WHERE (
      (v_occ IS NOT NULL AND ew.occasion=v_occ)
      OR (v_unit IS NOT NULL AND ew.unit=v_unit AND ew.occasion IS NULL)
      OR (v_org IS NOT NULL AND ew.organization=v_org AND ew.unit IS NULL AND ew.occasion IS NULL)
      OR (ew.organization IS NULL AND ew.unit IS NULL AND ew.occasion IS NULL)
    )
    ORDER BY
         CASE WHEN ew.occasion IS NOT DISTINCT FROM v_occ THEN 0 ELSE 1 END,
         CASE WHEN ew.unit IS NOT DISTINCT FROM v_unit THEN 0 ELSE 1 END,
         CASE WHEN ew.organization IS NOT DISTINCT FROM v_org THEN 0 ELSE 1 END,
         ew.id
    LIMIT 1
  ) t;

  -- Build the final result object, ensuring JSON nulls are used for missing records.
  result := jsonb_build_object(
              'template', COALESCE(email_template, 'null'::jsonb),
              'wrapper',  COALESCE(email_wrapper, 'null'::jsonb)
            );
  RETURN result;
END;
$$;


ALTER FUNCTION public.get_email_template_and_wrapper(p_code text, p_context jsonb) OWNER TO postgres;

--
-- Name: get_email_template_catalog(text, bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_template_catalog(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE context jsonb; templates jsonb; result jsonb;
BEGIN
 context:=public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit);
 SELECT coalesce(jsonb_agg(CASE WHEN p_code IS NULL THEN t-'html' ELSE t END ORDER BY t->>'code'),'[]')
 INTO templates FROM jsonb_array_elements(public.get_all_email_templates(context)) t
 WHERE p_code IS NULL OR t->>'code'=p_code;
 IF p_code IS NOT NULL AND jsonb_array_length(templates)=0 THEN
  RAISE invalid_parameter_value USING MESSAGE='template unavailable in this scope'; END IF;
 result:=jsonb_build_object('entityType',p_entity_type,'entityId',p_entity_id,'templates',templates);
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='email template result too large'; END IF;
 PERFORM public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit);
 RETURN result;
END $$;


ALTER FUNCTION public.get_email_template_catalog(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_code text) OWNER TO postgres;

--
-- Name: get_email_template_preview_context(text, bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_template_preview_context(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE context jsonb; catalog jsonb; result jsonb;
BEGIN
 context:=public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit);
 catalog:=public.get_email_template_catalog(p_entity_type,p_entity_id,p_organization,p_unit,p_code);
 result:=public.get_email_template_and_wrapper(p_code,context)||jsonb_build_object('context',context);
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='email preview too large'; END IF;
 PERFORM public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit);
 RETURN result;
END $$;


ALTER FUNCTION public.get_email_template_preview_context(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_code text) OWNER TO postgres;

--
-- Name: get_email_template_state_internal(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_email_template_state_internal(p_context jsonb, p_code text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT effective || jsonb_build_object('source',jsonb_build_object(
  'type',CASE WHEN effective->>'occasion' IS NOT NULL THEN 'occasion'
    WHEN effective->>'unit' IS NOT NULL THEN 'unit'
    WHEN effective->>'organization' IS NOT NULL THEN 'organization' ELSE 'global' END,
  'id',to_jsonb(coalesce((effective->>'occasion')::bigint,(effective->>'unit')::bigint,(effective->>'organization')::bigint))),
  'revision',encode(extensions.digest(convert_to(jsonb_build_object('effective',effective,
    'override',(SELECT to_jsonb(t) FROM public.email_templates t WHERE t.code=p_code AND
      CASE WHEN p_context->>'occasion' IS NOT NULL THEN t.occasion=(p_context->>'occasion')::bigint
      ELSE t.occasion IS NULL AND t.unit=(p_context->>'unit')::bigint END
      ORDER BY t.id DESC LIMIT 1))::text,'UTF8'),'sha256'),'hex'))
 FROM (SELECT public.get_resolved_email_template(p_code,p_context) effective) s;
$$;


ALTER FUNCTION public.get_email_template_state_internal(p_context jsonb, p_code text) OWNER TO postgres;

--
-- Name: get_entity_email_templates(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_entity_email_templates(p_entity_type text, p_entity_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_unit_id     bigint;
    v_org_id      bigint;

    context       jsonb;
    email_data    jsonb;

    occasion_data jsonb;
    unit_data     jsonb;
    org_data      jsonb;

    final_result  jsonb;
BEGIN
    -- 1. Resolve Hierarchy based on Entity Type
    IF p_entity_type = 'occasion' THEN
        v_occasion_id := p_entity_id;

        -- Get Unit & Org from Occasion
        SELECT unit, organization INTO v_unit_id, v_org_id
        FROM public.occasions WHERE id = v_occasion_id;

        IF v_unit_id IS NULL THEN
            RAISE EXCEPTION 'Occasion not found: %', p_entity_id;
        END IF;

    ELSIF p_entity_type = 'unit' THEN
        v_unit_id := p_entity_id;
        v_occasion_id := NULL;

        -- Get Org from Unit
        SELECT organization INTO v_org_id
        FROM public.units WHERE id = v_unit_id;

        IF v_org_id IS NULL THEN
            RAISE EXCEPTION 'Unit not found: %', p_entity_id;
        END IF;
    ELSE
        RAISE EXCEPTION 'Invalid entity type: %', p_entity_type;
    END IF;

    -- 2. Build Context for Template Retrieval
    context := jsonb_build_object(
        'occasion', v_occasion_id,
        'unit', v_unit_id,
        'organization', v_org_id
    );

    -- 3. Retrieve Templates (using core logic)
    email_data := public.get_all_email_templates(context);

    -- 4. Retrieve Entity Details for Response

    -- Organization
    SELECT jsonb_build_object('id', id, 'title', title, 'data', data)
    INTO org_data
    FROM public.organizations WHERE id = v_org_id;

    -- Unit
    SELECT jsonb_build_object('id', id, 'title', title, 'data', COALESCE(data, '{}'::jsonb), 'email', data->>'reply_to')
    INTO unit_data
    FROM public.units WHERE id = v_unit_id;

    -- Occasion (if applicable)
    IF v_occasion_id IS NOT NULL THEN
        SELECT jsonb_build_object('id', id, 'title', title, 'data', COALESCE(data, '{}'::jsonb), 'email', data->>'reply_to')
        INTO occasion_data
        FROM public.occasions WHERE id = v_occasion_id;
    ELSE
        occasion_data := NULL;
    END IF;

    -- 5. Build Final Result
    final_result := jsonb_build_object(
        'occasion',     occasion_data,
        'unit',         unit_data,
        'organization', org_data,
        'templates',    email_data,
        'banner', public.get_email_banner_state_internal(context)
    );

    RETURN final_result;
END;
$$;


ALTER FUNCTION public.get_entity_email_templates(p_entity_type text, p_entity_id bigint) OWNER TO postgres;

--
-- Name: get_event_attendance_summary(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_attendance_summary(p_events bigint[]) RETURNS TABLE(event bigint, participant_count bigint, is_signed_in boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT e.id, count(eu."user"),
         COALESCE(bool_or(eu."user" = auth.uid()), false)
  FROM public.events e
  LEFT JOIN public.event_users eu ON eu.event = e.id
  WHERE e.id = ANY(p_events)
    AND public.event_attendance_read_rule(public.get_is_event_allowed(e.id),public.get_is_editor_view_on_occasion(e.occasion))
  GROUP BY e.id;
$$;


