--
-- Name: get_event_feedback_export_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_feedback_export_for_edit(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_event_feedback_export_page_internal_v1(p_occasion,NULL,NULL);
$$;


ALTER FUNCTION public.get_event_feedback_export_for_edit(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_event_feedback_export_page_internal_v1(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_feedback_export_page_internal_v1(p_occasion bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_items JSONB;
BEGIN
    IF NOT public.can_read_schedule_feedback(p_occasion) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'Insufficient permissions'
        );
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Feedback feature is not enabled for this occasion'
        );
    END IF;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'event_id', e.id,
                'event_title', e.title,
                'event_start_time', e.start_time,
                'event_end_time', e.end_time,
                'feedback_id', f.id,
                'created_at', f.created_at,
                'updated_at', f.updated_at,
                'rating', f.rating,
                'note', f.note,
                'user_name', NULLIF(
                    btrim(CONCAT_WS(' ', ui.name, ui.surname)), ''
                ),
                'is_anonymous', ui.id IS NULL
            )
            ORDER BY e.start_time ASC, e.title ASC, f.updated_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_items
    FROM (SELECT * FROM public.event_feedback WHERE occasion=p_occasion AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT p_limit) f
    JOIN public.events e ON e.id = f.event
    LEFT JOIN public.user_info ui ON ui.id = f."user" AND public.organization_member_visible_internal(ui.organization,ui.id)
    WHERE f.occasion = p_occasion;

    RETURN jsonb_build_object('code', 200, 'data', v_items);
END;
$$;


ALTER FUNCTION public.get_event_feedback_export_page_internal_v1(p_occasion bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_event_feedback_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_feedback_for_edit(p_event bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion BIGINT;
    v_summary JSONB;
    v_items JSONB;
BEGIN
    SELECT occasion
    INTO v_occasion
    FROM public.events
    WHERE id = p_event;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
    END IF;

    IF NOT public.get_is_editor_view_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'Insufficient permissions'
        );
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Feedback feature is not enabled for this occasion'
        );
    END IF;

    SELECT jsonb_build_object(
        'total', COUNT(*),
        'happy', COUNT(*) FILTER (WHERE rating = 'happy'),
        'neutral', COUNT(*) FILTER (WHERE rating = 'neutral'),
        'sad', COUNT(*) FILTER (WHERE rating = 'sad')
    )
    INTO v_summary
    FROM public.event_feedback
    WHERE event = p_event;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', f.id,
                'created_at', f.created_at,
                'updated_at', f.updated_at,
                'rating', f.rating,
                'note', f.note,
                'user_name', NULLIF(
                    btrim(CONCAT_WS(' ', ui.name, ui.surname)), ''
                ),
                'is_anonymous', ui.id IS NULL
            )
            ORDER BY f.updated_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_items
    FROM public.event_feedback f
    LEFT JOIN public.user_info ui ON ui.id = f."user" AND public.organization_member_visible_internal(ui.organization,ui.id)
    WHERE f.event = p_event;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'summary', v_summary,
            'items', v_items
        )
    );
END;
$$;


ALTER FUNCTION public.get_event_feedback_for_edit(p_event bigint) OWNER TO postgres;

--
-- Name: get_event_participants_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_event_participants_for_edit(p_event bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion bigint;
  v_participants jsonb;
BEGIN
  SELECT e.occasion
  INTO v_occasion
  FROM public.events e
  WHERE e.id = p_event;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
  END IF;

  IF NOT public.can_read_schedule_participants(v_occasion) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Insufficient permissions');
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', ui.id,
        'name', ui.name,
        'surname', ui.surname,
        'companion_parent', (SELECT uc."user" FROM public.user_companions uc WHERE uc.occasion=v_occasion AND uc.companion=ui.id
          AND public.occasion_member_visible_internal(v_occasion,uc."user")
          AND EXISTS(SELECT 1 FROM public.event_users parent WHERE parent.event=p_event AND parent."user"=uc."user") LIMIT 1)
      )
      ORDER BY ui.surname, ui.name, ui.id
    ),
    '[]'::jsonb
  )
  INTO v_participants
  FROM public.event_users eu
  JOIN public.user_info ui ON ui.id = eu."user"
  WHERE eu.event = p_event AND public.occasion_member_visible_internal(v_occasion,ui.id);

  RETURN jsonb_build_object('code', 200, 'data', v_participants);
END;
$$;


ALTER FUNCTION public.get_event_participants_for_edit(p_event bigint) OWNER TO postgres;

--
-- Name: get_events(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_events(p_occasion bigint, p_include_description boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    current_user_id        UUID;
    eventsData             JSONB;
    placesData             JSONB;
    eventGroupsData        JSONB;
    eventRolesData         JSONB;
    eventUsersData         JSONB;
    eventUsersSavedData    JSONB;
BEGIN
    -- grab current_user_id user after entering PL/pgSQL execution
    current_user_id := auth.uid();

    -- (a) all non-hidden events, with per-user flags and conditional fields
    SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id',                   e.id,
        'title',                e.title,
        'start_time',           e.start_time,
        'end_time',             e.end_time,
        'max_participants',     e.max_participants,
        'updated_at',           e.updated_at,
        'description',          CASE WHEN p_include_description THEN e.description ELSE NULL END,
        'type',                 e.type,
        'data',                 (SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
                                   FROM jsonb_each(e.data)
                                  WHERE value <> 'false'::jsonb),
        'place',                e.place,
        'split_for_men_women',  NULLIF(e.split_for_men_women, FALSE),
        'is_group_event',       NULLIF(e.is_group_event, FALSE),
        'isSignedIn',           NULLIF((current_user_id IS NOT NULL
                                   AND EXISTS (
                                     SELECT 1
                                       FROM public.event_users eu
                                      WHERE eu.event = e.id
                                        AND eu."user" = current_user_id
                                   )
                                ), FALSE),
        'isEventInMyProgram',   NULLIF((current_user_id IS NOT NULL
                                   AND EXISTS (
                                     SELECT 1
                                       FROM public.event_users_saved eus
                                      WHERE eus.event = e.id
                                        AND eus."user" = current_user_id
                                   )
                                ), FALSE)
    )))
    INTO eventsData
    FROM public.events e
    WHERE e.occasion   = p_occasion
      AND e.is_hidden = FALSE;

    -- (b) places for this occasion (unchanged)
    SELECT jsonb_agg(jsonb_build_object(
        'id',           p.id,
        'order',        p."order",
        'title',        p.title
    ))
    INTO placesData
    FROM public.places p
    WHERE p.occasion = p_occasion;

    -- (c) event_groups only for non-hidden events (unchanged)
    SELECT jsonb_agg(jsonb_build_object(
        'event_parent', eg.event_parent,
        'event_child',  eg.event_child
    ))
    INTO eventGroupsData
    FROM public.event_groups eg
    JOIN public.events e1 ON eg.event_parent = e1.id
    JOIN public.events e2 ON eg.event_child  = e2.id
    WHERE e1.occasion   = p_occasion AND e1.is_hidden = FALSE
      AND e2.occasion   = p_occasion AND e2.is_hidden = FALSE;

    -- (d) event_roles only on non-hidden events (unchanged)
    SELECT jsonb_agg(jsonb_build_object(
        'event', er.event,
        'role',  er.role
    ))
    INTO eventRolesData
    FROM public.event_roles er
    JOIN public.events e ON er.event = e.id
    WHERE e.occasion   = p_occasion
      AND e.is_hidden = FALSE;

    -- (e) signed-in counts for non-hidden events (unchanged)
    WITH user_counts AS (
      SELECT eu.event AS event, COUNT(*) AS cnt
      FROM public.event_users eu
      JOIN public.events e ON eu.event = e.id
      WHERE e.occasion   = p_occasion
        AND e.is_hidden = FALSE
      GROUP BY eu.event
    )
    SELECT jsonb_agg(jsonb_build_object(
      'event', uc.event,
      'count', uc.cnt
    ))
    INTO eventUsersData
    FROM user_counts uc;

    -- (f) saved-for-later counts for non-hidden events (unchanged)
    WITH saved_counts AS (
      SELECT eus.event AS event, COUNT(*) AS cnt
      FROM public.event_users_saved eus
      JOIN public.events e ON eus.event = e.id
      WHERE e.occasion   = p_occasion
        AND e.is_hidden = FALSE
      GROUP BY eus.event
    )
    SELECT jsonb_agg(jsonb_build_object(
      'event', sc.event,
      'count', sc.cnt
    ))
    INTO eventUsersSavedData
    FROM saved_counts sc;

    -- (g) final assembly (unchanged)
    RETURN jsonb_build_object(
      'code', 200,
      'data', jsonb_build_object(
        'events',            COALESCE(eventsData,          '[]'::jsonb),
        'places',            COALESCE(placesData,          '[]'::jsonb),
        'event_groups',      COALESCE(eventGroupsData,     '[]'::jsonb),
        'event_roles',       COALESCE(eventRolesData,      '[]'::jsonb),
        'event_users',       COALESCE(eventUsersData,      '[]'::jsonb),
        'event_users_saved', COALESCE(eventUsersSavedData, '[]'::jsonb)
      )
    );
END;
$$;


ALTER FUNCTION public.get_events(p_occasion bigint, p_include_description boolean) OWNER TO postgres;

