--
-- Name: get_form_availability_from_config_internal(jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_availability_from_config_internal(p_config jsonb, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH c AS (SELECT (p_config->>'manualOpen')::boolean manual_open,
 (p_config->>'startAt')::timestamptz start_at,(p_config->>'endAt')::timestamptz end_at), gate AS (
 SELECT *,CASE WHEN NOT manual_open THEN 'manual_closed' WHEN p_at<start_at THEN 'before_start'
 WHEN p_at>end_at THEN 'ended' ELSE 'open' END value FROM c)
 SELECT p_config||jsonb_build_object('gate',value,'isWindowOpen',value='open','nextEvaluationAt',
 CASE WHEN manual_open IS NOT FALSE THEN (SELECT min(t) FROM (VALUES(start_at),(end_at+interval '1 microsecond')) b(t) WHERE t>p_at) END) FROM gate;
$$;


ALTER FUNCTION public.get_form_availability_from_config_internal(p_config jsonb, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: get_form_availability_snapshot_internal(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_availability_snapshot_internal(p_form bigint, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH form_config AS MATERIALIZED (
  SELECT f.is_open,public.get_effective_form_data(f.id) AS d
  FROM public.forms f WHERE f.id=p_form
 )
 SELECT public.get_form_availability_from_config_internal(jsonb_build_object('manualOpen',is_open,
 'startAt',nullif(coalesce(d#>>'{schedule,start_time}',d->>'start_time'),'')::timestamptz,
 'endAt',nullif(coalesce(d#>>'{schedule,end_time}',d->>'end_time'),'')::timestamptz),p_at)
 FROM form_config;
$$;


ALTER FUNCTION public.get_form_availability_snapshot_internal(p_form bigint, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: get_form_bank_accounts_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_bank_accounts_internal(p_unit bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',ba.id,'account_number',ba.account_number,
  'account_number_human_readable',ba.account_number_human_readable,'title',ba.title,
  'supported_currencies',ba.supported_currencies,'type',ba.type,
  'bank_sync_warning',public.bank_sync_warning(ba.id)) ORDER BY uba.priority,ba.id),'[]')
 FROM eshop.unit_bank_accounts uba JOIN eshop.bank_accounts ba ON ba.id=uba.bank_account
 WHERE uba.unit=p_unit AND ba.type IS DISTINCT FROM 'CASH';
$$;


ALTER FUNCTION public.get_form_bank_accounts_internal(p_unit bigint) OWNER TO postgres;

--
-- Name: get_form_bundle_internal(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_bundle_internal(p_form_id bigint, p_allow_closed boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    allData JSON;
    generated_secret UUID := gen_random_uuid();
    form_exists BOOLEAN;
    is_editor_view BOOLEAN := false;
    occ_id BIGINT;
BEGIN
    -- Check if the form exists
    SELECT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE id = p_form_id
    ) INTO form_exists;

    IF NOT form_exists THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Form does not exist.'
        );
    END IF;

    SELECT occasion INTO occ_id FROM public.forms WHERE id = p_form_id;
    IF public.is_demo_occasion(occ_id) AND NOT public.can_read_demo_occasion(occ_id) THEN
        RETURN jsonb_build_object('code',404,'message','Form does not exist.');
    END IF;
    is_editor_view := public.can_read_orders(occ_id);


    IF NOT p_allow_closed AND NOT is_editor_view AND NOT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE id = p_form_id AND is_open = true
    ) THEN
        -- If the form is closed, retrieve only the 'header_off' message
        SELECT jsonb_build_object(
            'code', 400,
            'data', jsonb_build_object(
                'organizationIdentity', (SELECT CASE WHEN o.organization=u.organization THEN public.get_verified_unit_identity_internal(u.id) END FROM public.occasions o JOIN public.units u ON u.id=o.unit WHERE o.id=f.occasion),
                'header_off', f.header_off,
                'seo', public.get_occasion_seo_data(f.link, 'form'),
                'is_open', f.is_open
            )
        )
        INTO allData
        FROM public.forms f
        WHERE f.id = p_form_id;

        RETURN allData;
    END IF;

    -- If the form is open, retrieve the full form data including dynamic product availability
    SELECT jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'demo_simulation', public.is_demo_occasion(f.occasion),
            'organizationIdentity', CASE WHEN o.organization=(SELECT organization FROM public.units WHERE id=o.unit) THEN public.get_verified_unit_identity_internal(o.unit) END,
            'payments',public.form_payment_availability_internal(f.id),
            'capacity', public.get_form_capacity_snapshot_internal(f.id),
            'registrationMode',public.get_form_registration_mode_internal(f.id),
            'saleOpeningNotification',public.get_sale_opening_projection_internal(f.id),
            'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
            'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
            'id', f.id,
            'link', f.link,
            'key', f.key,
            'created_at', f.created_at,
            'data', public.get_effective_form_data(f.id),
            'type', f.type,
            'title', f.title,
            'seo', public.get_occasion_seo_data(f.link, 'form'),
            'is_open', f.is_open,
            'header', f.header,
            'header_off', f.header_off,
            'occasion', jsonb_build_object(
                'id', o.id,
                'title', o.title,
                'features', o.features,
                'start_time', o.start_time
            ),
            'blueprint', CASE WHEN jsonb_path_exists(o.features,
                '$[*] ? (@.code == "blueprint" && @.is_enabled == true)') THEN f.blueprint END,
            'deadline_duration_seconds', f.deadline_duration_seconds,
            'account_number', ba.account_number,
            'secret', generated_secret,
            'fields', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ff.id,
                        'title', ff.title,
                        'description', ff.description,
                        'data', ff.data,
                        'type', ff.type,
                        'is_required', ff.is_required,
                        'is_hidden', ff.is_hidden,
                        'is_ticket_field', ff.is_ticket_field,
                        'order', ff."order",
                        'product_type_data', (
                            CASE
                                WHEN ff.product_type IS NOT NULL THEN
                                    jsonb_build_object(
                                        'id', pt.id,
                                        'title', pt.title,
                                        'description', pt.description,
                                        'type', pt.type,
                                        'data', pt.data,
                                        'occasion', pt.occasion,
                                        'products', (
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'id', p.id,
                                                    'title', p.title,
                                                    'description', p.description,
                                                    'price', p.price,
                                                    'currency_code', p.currency_code,
                                                    'data', p.data,
                                                    'order', p."order",
                                                    'ordered_count', (
                                                        SELECT count(*)
                                                        FROM eshop.order_product_ticket opt
                                                        WHERE opt.product = p.id
                                                    ),
                                                    'maximum', p.maximum,
                                                    'is_dynamically_available', is_product_dynamically_available(p.id)
                                                ) ORDER BY COALESCE(p."order", 0)
                                            )
                                            FROM eshop.products p
                                            WHERE p.product_type = pt.id
                                              AND NOT p.is_hidden
                                        )
                                    )
                                ELSE NULL
                            END
                        )
                    ) ORDER BY COALESCE(ff."order", 0)
                )
                FROM public.form_fields ff
                LEFT JOIN eshop.product_types pt ON ff.product_type = pt.id
                -- For the structural ticket field, is_hidden disables ticket
                -- issuance, not the application and its nested price choices.
                WHERE ff.form = f.id AND (ff.is_hidden = false OR ff.type = 'ticket')
            )
        )
    )
    INTO allData
    FROM public.forms f
    LEFT JOIN eshop.bank_accounts ba ON f.bank_account = ba.id
    LEFT JOIN public.occasions o ON f.occasion = o.id
    WHERE f.id = p_form_id;

    RETURN allData;
END;
$_$;


ALTER FUNCTION public.get_form_bundle_internal(p_form_id bigint, p_allow_closed boolean) OWNER TO postgres;

--
-- Name: get_form_by_link(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_by_link(input_data jsonb) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f bigint; policy jsonb; method text;
BEGIN
 f:=public.resolve_form_link_internal(input_data->>'form_link');
 IF f IS NOT NULL THEN
  SELECT CASE WHEN data#>'{payments,cashEnabled}'='true'::jsonb THEN 'cash' ELSE 'bank' END INTO method FROM public.forms WHERE id=f;
  policy:=public.resolve_form_payment_policy_internal(f,method);
  PERFORM public.check_payment_client_capabilities_internal(policy,method,input_data->'client_capabilities');
 END IF;
 RETURN public.get_form_bundle_internal(f,false);
EXCEPTION WHEN raise_exception THEN
 IF left(SQLERRM,1)='{' THEN RETURN SQLERRM::json; END IF; RAISE;
END $$;


ALTER FUNCTION public.get_form_by_link(input_data jsonb) OWNER TO postgres;

--
-- Name: get_form_by_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_by_link(form_link text) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_form_by_link(jsonb_build_object('form_link',form_link));
$$;


ALTER FUNCTION public.get_form_by_link(form_link text) OWNER TO postgres;

--
-- Name: get_form_capacity_snapshot_internal(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_capacity_snapshot_internal(p_form bigint, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH counts AS (
 SELECT f.*, (SELECT count(DISTINCT t.id) FROM eshop.tickets t JOIN eshop.order_product_ticket x ON x.ticket=t.id JOIN eshop.orders o ON o.id=x."order"
  WHERE o.form=f.id AND t.state IS DISTINCT FROM 'storno' AND t.state IS DISTINCT FROM 'waitlisted' AND o.state IS DISTINCT FROM 'storno') occupied,
 (SELECT count(*) FROM eshop.waitlist_offer_slots s JOIN eshop.waitlist_offers w ON w.id=s.offer_id
  WHERE s.form_id=f.id AND s.outcome='pending' AND w.expires_at>p_at) reserved,
 (SELECT count(DISTINCT t.id) FROM eshop.tickets t JOIN eshop.order_product_ticket x ON x.ticket=t.id JOIN eshop.orders o ON o.id=x."order"
  WHERE o.form=f.id AND o.state='waitlisted' AND public.get_effective_waitlist_ticket_lifecycle_internal(t.id)='waiting') waiting
 FROM public.forms f WHERE f.id=p_form), free AS (
 SELECT *,greatest(participant_capacity-occupied-reserved,0) available FROM counts)
 SELECT jsonb_build_object('enabled',participant_capacity IS NOT NULL,'limit',participant_capacity,
 'remainingPublic',CASE WHEN participant_capacity IS NOT NULL THEN greatest(available-waiting,0) END,
 'showRemaining',show_remaining_capacity,'occupiedPeople',occupied,'offeredPlaces',reserved,'waitingPeople',waiting,
 'offerablePlaces',available,'heldForWaiting',least(available,waiting),'revision',capacity_revision,
 'canSendOffers',waitlist_enabled AND available>0,'blockedReason',CASE WHEN NOT waitlist_enabled THEN 'WAITLIST_NOT_AVAILABLE'
 WHEN available=0 THEN 'FORM_CAPACITY_EXCEEDED' END,'serverTime',p_at) FROM free;
$$;


ALTER FUNCTION public.get_form_capacity_snapshot_internal(p_form bigint, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: get_form_catalog_page(bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_catalog_page(p_occasion bigint, p_organization bigint, p_unit bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE rows jsonb; last_id bigint; next_id bigint; result jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR (p_after IS NOT NULL AND p_after<1) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid form page'; END IF;
 PERFORM public.check_form_authoring_scope_internal(p_occasion,p_organization,p_unit,'list',true);
 rows:=public.get_form_catalog_rows_internal(p_occasion,p_after,p_limit);
 SELECT max((r->>'id')::bigint) INTO last_id FROM jsonb_array_elements(rows) r;
 IF EXISTS(SELECT 1 FROM public.forms WHERE occasion=p_occasion AND id>last_id) THEN next_id:=last_id; END IF;
 SELECT coalesce(jsonb_agg(r-ARRAY['key','link','data'] ORDER BY (r->>'id')::bigint),'[]') INTO rows FROM jsonb_array_elements(rows) r;
 result:=jsonb_build_object('occasionId',p_occasion,'forms',rows,'nextCursor',next_id);
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='form page too large'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.get_form_catalog_page(p_occasion bigint, p_organization bigint, p_unit bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_form_catalog_rows_internal(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_catalog_rows_internal(p_occasion bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH selected AS MATERIALIZED (
  SELECT * FROM public.forms WHERE occasion=p_occasion AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT p_limit
 ), usage AS MATERIALIZED (
  SELECT public.get_form_usage_rows_internal(ARRAY(SELECT id FROM selected)) rows
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'data',f.data,'key',f.key,'link',f.link,
  'occasion',f.occasion,'type',f.type,'is_open',f.is_open,'blueprint',f.blueprint,
  'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
  'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
  'capacity',public.get_form_capacity_snapshot_internal(f.id),'registrationMode',public.get_form_registration_mode_internal(f.id),
  'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions v WHERE v.aggregate_type='form' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=f.id::text),0),
  'response_count',usage.rows->f.id::text->'response_count',
  'fields',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',ff.id,'type',ff.type,'is_ticket_field',ff.is_ticket_field) ORDER BY coalesce(ff."order",0),ff.id),'[]') FROM public.form_fields ff WHERE ff.form=f.id)) ORDER BY f.id),'[]')
 FROM selected f CROSS JOIN usage;
$$;


ALTER FUNCTION public.get_form_catalog_rows_internal(p_occasion bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_form_editor_bundle_internal(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_editor_bundle_internal(p_form_id bigint, p_related_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_form_id BIGINT;
    v_occasion_id BIGINT;
    v_unit_id BIGINT;
    formData JSONB;
    formFieldsData JSONB;
    productTypesData JSONB;
    productsData JSONB;
    availableBankAccountsData JSONB;
    canDelete BOOLEAN;
BEGIN
    SELECT
        f.id,
        f.occasion,
        o.unit
    INTO
        v_form_id,
        v_occasion_id,
        v_unit_id
    FROM public.forms f
    JOIN public.occasions o ON f.occasion = o.id
    WHERE f.id = p_form_id;

    IF v_form_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form not found for the provided link.');
    END IF;

    -- Private projection; the checked public reader/command owns authorization.

    -- Use the same reference guard as deletion, including retained history.
    canDelete := (public.get_form_usage_internal(v_form_id)->>'blocking_orders')::bigint=0;

    SELECT jsonb_build_object(
        'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=f.occasion AND aggregate_id=f.id::text),0),
        'id', f.id,'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
        'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
        'organizationIdentity',(SELECT CASE WHEN o.organization=u.organization THEN public.get_verified_unit_identity_internal(u.id) END FROM public.occasions o JOIN public.units u ON u.id=o.unit WHERE o.id=f.occasion),
        'capacity',public.get_form_capacity_snapshot_internal(f.id),'registrationMode',public.get_form_registration_mode_internal(f.id),
        'key', f.key,
        'is_open', f.is_open,
        'created_at', f.created_at,
        'data', public.normalize_form_metadata_internal(f.data),
        'measurement_status', public.form_measurement_status_internal(f.id),
        'type', f.type,
        'title', f.title,
        'header', f.header,
        'header_off', f.header_off,
        'occasion', f.occasion,
        'blueprint', f.blueprint,
        'link', f.link,
        'bank_account', f.bank_account,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'can_delete', canDelete -- Added field
    )
    INTO formData
    FROM public.forms f
    WHERE f.id = v_form_id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', pt.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product_type' AND scope_type='occasion' AND scope_id=pt.occasion AND aggregate_id=pt.id::text),0),
            'title', pt.title,
            'description', pt.description,
            'type', pt.type,
            'data', pt.data,
            'occasion', pt.occasion
        ) ORDER BY pt.title
    ), '[]'::jsonb)
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id
      AND (NOT p_related_only OR pt.id IN (SELECT product_type FROM public.form_fields WHERE form=v_form_id));

    -- Materialize occasion history once rather than scanning it for every
    -- product and every field. Only current orders and current references determine eligibility.
    WITH occasion_orders AS MATERIALIZED (
      SELECT id, data FROM eshop.orders WHERE occasion = v_occasion_id
    ), snapshots AS MATERIALIZED (
      SELECT data FROM occasion_orders
    ), used_products AS MATERIALIZED (
      SELECT opt.product::text AS product FROM eshop.order_product_ticket opt
      JOIN eshop.products p ON p.id = opt.product WHERE p.occasion = v_occasion_id
      UNION
      SELECT value #>> '{}' FROM snapshots s
      CROSS JOIN LATERAL jsonb_path_query(s.data, '$.tickets[*].products[*].id') ids(value)
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', p.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=p.occasion AND aggregate_id=p.id::text),0),
            'can_delete', usage.reason IS NULL,
            'delete_blocked_reason', usage.reason,
            'occasion', p.occasion,
            'title', p.title,
            'description', p.description,
            'price', p.price,
            'currency_code', p.currency_code,
            'is_hidden', p.is_hidden,
            'order', p."order",
            'product_type', p.product_type,
            'ordered_count', (
                SELECT count(*)
                FROM eshop.order_product_ticket opt
                JOIN eshop.orders o ON opt."order" = o.id
                WHERE opt.product = p.id AND o.state <> 'storno'
            ),
            'maximum', p.maximum,
            'data', p.data
        ) ORDER BY COALESCE(p."order", 0)
    ), '[]'::jsonb)
    INTO productsData
    FROM eshop.products p
    CROSS JOIN LATERAL (SELECT CASE
      WHEN public.primary_product_delete_blocked_internal(p.id) THEN 'primary_product'
      WHEN EXISTS (SELECT 1 FROM used_products u WHERE u.product = p.id::text) THEN 'orders'
      WHEN EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product = p.id) THEN 'blueprint'
      WHEN EXISTS (SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product = p.id) THEN 'inventory'
      WHEN (SELECT count(*) FROM public.form_fields ref WHERE ref.product_type = p.product_type) > 1 THEN 'shared'
    END AS reason) usage
    WHERE p.occasion=v_occasion_id AND p.product_type IN (SELECT id FROM eshop.product_types WHERE occasion = v_occasion_id)
      AND (NOT p_related_only OR p.product_type IN (SELECT product_type FROM public.form_fields WHERE form=v_form_id));

    WITH form_orders AS MATERIALIZED (
      SELECT id, data FROM eshop.orders WHERE form = v_form_id
    ), form_snapshots AS MATERIALIZED (
      SELECT data FROM form_orders
    ), form_tickets AS MATERIALIZED (
      SELECT t.note FROM eshop.order_product_ticket opt
      JOIN form_orders o ON o.id = opt."order"
      JOIN eshop.tickets t ON t.id = opt.ticket
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ff.id,
            'can_delete', usage.reason IS NULL,
            'delete_blocked_reason', usage.reason,
            'form', ff.form,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'is_hidden', ff.is_hidden,
            'is_ticket_field', ff.is_ticket_field,
            'order', ff."order",
            'product_type', ff.product_type
        ) ORDER BY COALESCE(ff."order", 0)
    ), '[]'::jsonb)
    INTO formFieldsData
    FROM public.form_fields ff
    CROSS JOIN LATERAL (SELECT CASE
      WHEN EXISTS(SELECT 1 FROM eshop.product_types pt WHERE pt.id=ff.product_type AND pt.type='spot')
        OR (ff.type='ticket' AND EXISTS(SELECT 1 FROM public.form_fields child
          JOIN eshop.product_types pt ON pt.id=child.product_type
          WHERE child.form=ff.form AND child.is_ticket_field AND pt.type='spot')) THEN 'primary_product'
      WHEN EXISTS (
      SELECT 1 FROM form_snapshots s WHERE
        EXISTS (SELECT 1 FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(s.data->'fields') = 'array' THEN s.data->'fields' ELSE '[]'::jsonb END) answer
          WHERE answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb))
        OR (ff.type = 'ticket' AND jsonb_path_exists(s.data, '$.tickets[*]'))
        OR (ff.type = 'note' AND ff.is_ticket_field AND jsonb_path_exists(s.data, '$.tickets[*] ? (@.note != null && @.note != "")'))
    ) OR (ff.type = 'ticket' AND EXISTS (SELECT 1 FROM form_tickets))
      OR (ff.type = 'note' AND ff.is_ticket_field AND EXISTS (SELECT 1 FROM form_tickets WHERE NULLIF(note, '') IS NOT NULL))
      OR EXISTS(SELECT 1 FROM eshop.tickets person CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(person.data->'fields')='array' THEN person.data->'fields' ELSE '[]' END) answer
        WHERE EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket=person.id AND q.form=ff.form) AND answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb))
      OR (ff.type='ticket' AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket IS NOT NULL AND q.form=ff.form))
    THEN 'responses' ELSE (
      SELECT p->>'delete_blocked_reason' FROM public.form_fields member
      JOIN jsonb_array_elements(productsData) p ON (p->>'product_type')::bigint = member.product_type
      WHERE (member.id = ff.id OR (ff.type = 'ticket' AND member.form = ff.form AND member.is_ticket_field))
        AND p->>'delete_blocked_reason' IS NOT NULL
      ORDER BY (p->>'id')::bigint LIMIT 1
    ) END AS reason) usage
    WHERE ff.form = v_form_id;

    availableBankAccountsData:=CASE WHEN p_related_only THEN '[]'::jsonb
        ELSE public.get_form_bank_accounts_internal(v_unit_id) END;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'form', formData,
            'form_fields', formFieldsData,
            'product_types', productTypesData,
            'products', productsData,
            'available_bank_accounts', availableBankAccountsData
        )
    );
END;
$_$;


ALTER FUNCTION public.get_form_editor_bundle_internal(p_form_id bigint, p_related_only boolean) OWNER TO postgres;

--
-- Name: get_form_fields(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_fields(p_form_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    form_id INT;
    fieldsData JSONB;
    productTypesData JSONB;
BEGIN
    PERFORM public.check_is_editor_order_view_via_form_link(p_form_link);
    -- Retrieve the form ID from the form link.
    SELECT id
    INTO form_id
    FROM public.forms
    WHERE id = public.resolve_form_link_internal(p_form_link);

    -- Validate that the form exists.
    IF form_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form not found');
    END IF;

    -- Retrieve the form fields associated with the form.
    -- (Filtering out ticket fields by checking a Boolean column and a specific type value)
    SELECT jsonb_agg(
         jsonb_build_object(
            'id', ff.id,
            'created_at', ff.created_at,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'form', ff.form,
            'is_hidden', ff.is_hidden,
            'order', ff.order,
            'product_type', ff.product_type,
            'is_ticket_field', ff.is_ticket_field
         )
    )
    INTO fieldsData
    FROM public.form_fields ff
    WHERE ff.form = form_id
      AND ff.is_ticket_field = FALSE
      AND ff.type <> 'ticket';

    -- Retrieve product types for those fields.
    SELECT jsonb_agg(
         jsonb_build_object(
            'id', pt.id,
            'name', pt.title,
            'description', pt.description
         )
    )
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.id IN (
        SELECT DISTINCT ff.product_type
        FROM public.form_fields ff
        WHERE ff.form = form_id
    );

    -- Return combined data as JSON.
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'fields', COALESCE(fieldsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION public.get_form_fields(p_form_link text) OWNER TO postgres;

--
-- Name: get_form_for_authoring(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_for_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_form_authoring_scope_internal(p_occasion,p_organization,p_unit,'inspect',true);
 IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=p_form AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign form'; END IF;
 result:=public.get_form_authoring_snapshot_internal(p_form);
 IF octet_length(result::text)>1048576 OR jsonb_array_length(result->'fields')>500 THEN RAISE program_limit_exceeded USING MESSAGE='form snapshot too large'; END IF;
 RETURN jsonb_build_object('occasionId',p_occasion,'authoring',result);
END $$;


ALTER FUNCTION public.get_form_for_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint) OWNER TO postgres;

--
-- Name: get_form_for_authoring_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_for_authoring_v1(p_form bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; link text;
BEGIN
 SELECT f.link INTO link FROM public.forms f WHERE f.id=p_form;
 IF link IS NULL THEN RAISE insufficient_privilege USING MESSAGE='form unavailable'; END IF;
 -- Reuse field/product eligibility and permission rules; omit form capabilities.
 result:=public.get_form_for_edit(link);
 IF result->>'code'<>'200' THEN RETURN result; END IF;
 RETURN jsonb_set(result,'{data,form}',(result#>'{data,form}')-ARRAY['key','secret']);
END $$;


ALTER FUNCTION public.get_form_for_authoring_v1(p_form bigint) OWNER TO postgres;

--
-- Name: get_form_for_edit(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_for_edit(form_link text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE form_id bigint;
BEGIN
 form_id:=public.resolve_form_link_internal(form_link);
 IF form_id IS NULL THEN RETURN jsonb_build_object('code',404,'message','Form not found for the provided link.'); END IF;
 IF public.can_read_form_catalog((SELECT occasion FROM public.forms WHERE id=form_id)) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='form catalog reader required'; END IF;
 RETURN public.get_form_editor_bundle_internal(form_id);
END $$;


ALTER FUNCTION public.get_form_for_edit(form_link text) OWNER TO postgres;

