-- Name: get_form_measurement_policy(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_measurement_policy(p_form_link text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE fid bigint:=public.resolve_form_link_internal(p_form_link);
BEGIN
 IF NOT public.can_read_public_form_measurement(fid) THEN RETURN NULL; END IF;
 RETURN public.form_measurement_runtime_internal(fid)||jsonb_build_object('visitor_role',public.form_measurement_visitor_role_internal(fid));
END $$;


ALTER FUNCTION public.get_form_measurement_policy(p_form_link text) OWNER TO postgres;

--
-- Name: get_form_measurement_runtime_config(text, bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_measurement_runtime_config(p_form_link text, p_organization bigint, p_unit bigint, p_runtime_origin text, p_parent_origin text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE fid bigint:=public.resolve_form_link_internal(p_form_link); result jsonb;
BEGIN
 IF NOT public.can_read_form_measurement_runtime(fid,p_organization,p_unit,p_runtime_origin,p_parent_origin) THEN
  RAISE insufficient_privilege USING MESSAGE='form measurement runtime unavailable';
 END IF;
 SELECT jsonb_build_object('organization',o.organization,'unit',u.id,'form_id',f.id,'form_link',f.link,
  'runtime_origin',r.runtime_origin,'parent_origin',p_parent_origin,'profile',r.runtime_profile,
  'ancestor_origins',r.parent_origins,'collector_origins',r.collector_origins,'policy',public.form_measurement_runtime_internal(f.id)-ARRAY['privacy_url','consent_notice','approved_hosts'],
  'gtm_container',u.data->>'measurement_gtm_container','scripts',u.data->>'measurement_scripts') INTO result
 FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
 JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
 JOIN analytics.unit_runtime r ON r.unit=u.id
 WHERE f.id=fid;
 RETURN result;
END $$;


ALTER FUNCTION public.get_form_measurement_runtime_config(p_form_link text, p_organization bigint, p_unit bigint, p_runtime_origin text, p_parent_origin text) OWNER TO postgres;

--
-- Name: get_form_payment_options(bigint, bigint, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_payment_options(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_form_authoring_scope_internal(p_occasion,p_organization,p_unit,'save');
 IF p_livemode IS NULL OR NOT EXISTS(SELECT 1 FROM public.forms WHERE id=p_form AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='foreign form or missing Stripe environment'; END IF;
 result:=jsonb_build_object('occasionId',p_occasion,'formId',p_form,'livemode',p_livemode,
  'bankAccounts',public.get_form_bank_accounts_internal(p_unit),
  'availability',public.form_payment_availability_internal(p_form))||public.provider_form_editor_fields_internal(p_unit,p_occasion,p_livemode);
 IF octet_length(result::text)>1048576 OR jsonb_array_length(result->'bankAccounts')>100 THEN
  RAISE program_limit_exceeded USING MESSAGE='form payment options too large'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.get_form_payment_options(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint, p_livemode boolean) OWNER TO postgres;

--
-- Name: get_form_presale_archive(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_presale_archive(p_form bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occasion_id bigint; result jsonb;
BEGIN
 SELECT occasion INTO occasion_id FROM public.forms WHERE id=p_form;
 IF auth.uid() IS NULL OR NOT coalesce(public.can_author_forms(occasion_id),false) THEN
  RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 SELECT jsonb_build_object('conversionId',conversion_id,'originalVersion',original_version,
  'secondaryHtml',CASE WHEN coalesce((legacy_data#>>'{schedule,show_before_start_message}')::boolean,false)
    AND (coalesce((legacy_data#>>'{schedule,enable_countdown}')::boolean,false)
      OR coalesce(legacy_data#>>'{schedule,countdown_title}','')<>''
      OR coalesce((legacy_data#>>'{sale_opening_notifications,enabled}')::boolean,false))
    THEN NULL ELSE legacy_data#>>'{schedule,before_start_message}' END) INTO result
 FROM (SELECT *,public.normalize_form_metadata_internal(original_data) legacy_data
  FROM public.form_presale_content_archive WHERE form=p_form) archived;
 RETURN result;
END $$;


ALTER FUNCTION public.get_form_presale_archive(p_form bigint) OWNER TO postgres;

