--
-- Name: get_form_registration_mode_internal(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_registration_mode_internal(p_form bigint, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE f public.forms; c jsonb;
BEGIN
 SELECT * INTO f FROM public.forms WHERE id=p_form;
 IF NOT (public.get_form_availability_snapshot_internal(p_form,p_at)->>'isWindowOpen')::boolean THEN RETURN 'closed'; END IF;
 IF f.blueprint IS NOT NULL AND EXISTS (
  SELECT 1 FROM public.occasions o WHERE o.id=f.occasion
  AND jsonb_path_exists(o.features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)')
 ) THEN RETURN 'blueprint'; END IF;
 c:=public.get_form_capacity_snapshot_internal(p_form,p_at);
 IF f.participant_capacity IS NULL OR (c->>'remainingPublic')::bigint>0 THEN RETURN 'regular'; END IF;
 RETURN CASE WHEN f.waitlist_enabled THEN 'waitlist' ELSE 'full' END;
END $_$;


ALTER FUNCTION public.get_form_registration_mode_internal(p_form bigint, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: get_form_stripe_recipient(bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_stripe_recipient(p_unit bigint, p_occasion bigint, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.can_author_forms(p_occasion),false)
  OR NOT EXISTS(SELECT 1 FROM public.occasions o JOIN public.units u ON u.id=o.unit AND u.organization=o.organization
    JOIN public.user_info actor ON actor.organization=o.organization AND actor.id=auth.uid()
    WHERE o.id=p_occasion AND u.id=p_unit) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 SELECT jsonb_build_object('connectionId',id,'name',business_name,'state',state,'paused',paused,
  'modelVerified',model_verified,'chargesEnabled',charges_enabled,'payoutsEnabled',payouts_enabled,
  'cardPaymentsActive',card_payments_active,'checkedAt',checked_at,
  'unsupportedReason',CASE WHEN EXISTS(SELECT 1 FROM eshop.external_services WHERE unit=p_unit AND type='FAKTUROID') THEN 'fakturoid_unsupported' END) INTO result
 FROM eshop.stripe_connections WHERE unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted');
 RETURN result;
END $$;


ALTER FUNCTION public.get_form_stripe_recipient(p_unit bigint, p_occasion bigint, p_livemode boolean) OWNER TO postgres;

