-- Name: get_form_usage_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_usage_internal(p_form bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_form_usage_rows_internal(ARRAY[p_form])->p_form::text;
$$;


ALTER FUNCTION public.get_form_usage_internal(p_form bigint) OWNER TO postgres;

--
-- Name: get_form_usage_rows_internal(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_usage_rows_internal(p_forms bigint[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH selected AS MATERIALIZED (SELECT id,key FROM public.forms WHERE id=ANY(p_forms)), refs AS (
  SELECT q.form form_id,q.id order_id,true is_response FROM eshop.orders q WHERE q.form=ANY(p_forms)
  UNION ALL
  SELECT f.id,q.id,q.form IS NULL FROM eshop.orders q JOIN selected f ON q.data->>'form'=f.key::text
 ), unique_refs AS (
  SELECT form_id,order_id,bool_or(is_response) is_response FROM refs GROUP BY form_id,order_id
 ), totals AS (
  SELECT form_id,count(*) blocking_orders,count(*) FILTER(WHERE is_response) response_count FROM unique_refs GROUP BY form_id
 )
 SELECT coalesce(jsonb_object_agg(f.id::text,jsonb_build_object('response_count',coalesce(t.response_count,0),
  'blocking_orders',coalesce(t.blocking_orders,0))),'{}') FROM selected f LEFT JOIN totals t ON t.form_id=f.id;
$$;


ALTER FUNCTION public.get_form_usage_rows_internal(p_forms bigint[]) OWNER TO postgres;

--
-- Name: get_form_waitlist_context(bigint, bigint, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_form_waitlist_context(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; offer uuid; oid bigint;
BEGIN
 IF p_operation IS NULL OR p_operation NOT IN('proposal','detail','send','cancel','withdraw','accept','decline') OR jsonb_typeof(p_payload)<>'object' THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid waitlist intent'; END IF;
 PERFORM public.check_form_order_scope_internal(p_occasion,p_organization,p_unit,p_form,p_operation<>'detail');
 IF p_operation IN('detail','withdraw') THEN
  oid:=(p_payload->>'orderId')::bigint;
  IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=oid AND form=p_form AND occasion=p_occasion) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign waiting order'; END IF;
 ELSIF p_operation IN('cancel','accept','decline') THEN
  offer:=(p_payload->>'offerId')::uuid;
  IF NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE id=offer AND form_id=p_form) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign offer'; END IF;
 ELSIF p_operation='send' THEN
  IF (p_payload->>'formId')::bigint IS DISTINCT FROM p_form OR
   jsonb_typeof(p_payload->'recipients') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'recipients') NOT BETWEEN 1 AND 100 OR
   EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'recipients') r WHERE NOT EXISTS(
     SELECT 1 FROM eshop.orders o WHERE o.id=(r->>'orderId')::bigint AND o.form=p_form AND o.occasion=p_occasion)) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign waitlist recipients'; END IF;
 END IF;
 IF p_operation='proposal' THEN
  IF coalesce((p_payload->>'limit')::int,50) NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid waitlist page'; END IF;
  result:=public.get_waitlist_offer_proposal_internal(p_form,(p_payload->>'after')::bigint,coalesce((p_payload->>'limit')::int,50));
 ELSIF p_operation='detail' THEN result:=public.get_waitlist_order_detail(oid);
 ELSE result:='{}'; END IF;
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='waitlist detail too large'; END IF;
 RETURN jsonb_build_object('occasionId',p_occasion,'formId',p_form,'result',result);
END $$;


ALTER FUNCTION public.get_form_waitlist_context(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint, p_operation text, p_payload jsonb) OWNER TO postgres;

--
-- Name: get_forms_by_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_forms_by_link(occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link)
      AND organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid());

    -- Step 2: If no occasion is found, throw a 'no_data_found' exception.
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion not found for link: %', occasion_link USING ERRCODE = 'PGRST001'; -- Custom error for PostgREST
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- If not, throw an 'insufficient_privilege' exception.
    IF NOT public.can_read_form_catalog(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view forms for this occasion.' USING ERRCODE = '42501'; -- insufficient_privilege
    END IF;

    -- Step 4: Aggregate forms for the occasion into a JSONB array.
    -- The order statistics are nested within a 'stats' JSON object.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
            'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
            'capacity',public.get_form_capacity_snapshot_internal(f.id),'registrationMode',public.get_form_registration_mode_internal(f.id),
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', f.occasion,
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'stats', jsonb_build_object(
                'total', COALESCE(order_stats.total, 0),
                'storno', COALESCE(order_stats.storno, 0),
                'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
                'ordered', COALESCE(order_stats.ordered, 0)
            )
        ) ORDER BY f.created_at
    )
    INTO forms_data
    FROM public.forms f
    LEFT JOIN (
        -- This subquery calculates all required counts in a single pass over the orders table.
        SELECT
            (data->>'form')::uuid AS form_key,
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE state = 'storno') AS storno,
            COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
            COUNT(*) FILTER (WHERE state = 'ordered') AS ordered
        FROM eshop.orders
        WHERE data->>'form' IS NOT NULL -- Ensure the key exists before casting
        GROUP BY form_key
    ) AS order_stats ON f.key = order_stats.form_key
    WHERE f.occasion = v_occasion_id;

    -- Step 5: If no forms were found, ensure an empty JSON array is returned.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the data directly.
    RETURN forms_data;
END;
$$;


ALTER FUNCTION public.get_forms_by_link(occasion_link text) OWNER TO postgres;

--
-- Name: get_forms_by_link(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_forms_by_link(occasion_link text, form_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE forms jsonb; target bigint;
BEGIN
 forms := public.get_forms_by_link(occasion_link);
 target := public.resolve_form_link_internal(form_link);
 RETURN (SELECT coalesce(jsonb_agg(f || CASE WHEN (f->>'id')::bigint=target
   THEN jsonb_build_object('requested_link',form_link) ELSE '{}'::jsonb END),'[]')
   FROM jsonb_array_elements(forms) f);
END $$;


ALTER FUNCTION public.get_forms_by_link(occasion_link text, form_link text) OWNER TO postgres;

