-- Name: get_game_settings_for_authoring_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_game_settings_for_authoring_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM 1 FROM public.occasions WHERE id=p_occasion FOR SHARE;
 IF NOT public.can_edit_game_settings(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='game settings scope denied'; END IF;
 RETURN (SELECT jsonb_build_object('game',COALESCE(NULLIF(o.data->'game','null'::jsonb),'{}'),'version',COALESCE(v.version,0)) FROM public.occasions o LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion' AND v.scope_type='occasion' AND v.scope_id=o.id AND v.aggregate_id=o.id::text WHERE o.id=p_occasion);
END $$;


ALTER FUNCTION public.get_game_settings_for_authoring_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_group_places_for_map_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_group_places_for_map_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF NOT public.can_read_group_places(p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='occasion member required'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'title',g.title,'place',g.place,'places',
  jsonb_build_object('id',p.id,'occasion',p.occasion,'unit',p.unit,'title',p.title,'description',p.description,
    'coordinates',p.coordinates,'type',p.type,'is_hidden',p.is_hidden,'order',p."order",'icon',p.icon,'aggregate_version',coalesce(v.version,0))) ORDER BY g.id)
  FROM public.user_group_info g JOIN public.places p ON p.id=g.place AND p.occasion=g.occasion
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p.id::text
  WHERE g.occasion=p_occasion AND (NOT public.is_demo_unit(p.unit) OR public.demo_unit_can_read(p.unit))),'[]'::jsonb);
END $$;


ALTER FUNCTION public.get_group_places_for_map_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_image_project_access_v1(text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_image_project_access_v1(p_project text, p_occasion bigint DEFAULT NULL::bigint, p_unit bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE org bigint;
BEGIN
 IF auth.uid() IS NULL OR p_project IS NULL OR p_project NOT IN ('default','a','slunovrat') OR (p_occasion IS NOT NULL AND p_unit IS NOT NULL) THEN RETURN false; END IF;
 IF p_occasion IS NOT NULL OR p_unit IS NOT NULL THEN
  IF public.check_upload_permission(p_occasion,p_unit) IS NOT TRUE THEN RETURN false; END IF;
  IF p_occasion IS NOT NULL THEN SELECT organization INTO org FROM public.occasions WHERE id=p_occasion;
  ELSE SELECT organization INTO org FROM public.units WHERE id=p_unit; END IF;
  RETURN org IS NOT NULL AND coalesce((SELECT project FROM public.image_project_imports WHERE organization=org),'default')=p_project;
 END IF;
 -- Historical private files are intentionally shared among project editors.
 -- Backend consolidation must never broaden that contract across projects.
 IF p_project='slunovrat' THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.occasions o
  WHERE coalesce((SELECT project FROM public.image_project_imports WHERE organization=o.organization),'default')=p_project
   AND public.get_is_editor_on_occasion(o.id));
END $$;


ALTER FUNCTION public.get_image_project_access_v1(p_project text, p_occasion bigint, p_unit bigint) OWNER TO postgres;

--
-- Name: get_inclusion_type_groups_by_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inclusion_type_groups_by_link(p_occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_occasion_data jsonb;
    v_groups_data jsonb;
    result jsonb;
BEGIN
    -- Find the occasion ID from the provided link.
    SELECT id INTO v_occasion_id FROM public.occasions WHERE id = public.resolve_occasion_link_internal(p_occasion_link);
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with link % not found.', p_occasion_link;
    END IF;

    -- Permission check to ensure the user can view data for this occasion.
    IF NOT can_read_orders(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the occasion details.
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE id = v_occasion_id;

    -- Aggregate all groups for the occasion, and for each group, aggregate its inclusion types.
    SELECT COALESCE(jsonb_agg(groups_with_types), '[]'::jsonb)
    INTO v_groups_data
    FROM (
        SELECT
            jsonb_build_object(
                'id', g.id,
                'created_at', g.created_at,
                'updated_at', g.updated_at,
                'title', g.title,
                'type', g.type,
                'occasion', g.occasion,
                'inclusion_types', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'id', t.id,
                            'created_at', t.created_at,
                            'updated_at', t.updated_at,
                            'title', t.title,
                            'inclusion_type_group', t.inclusion_type_group,
                            'data', t.data
                        ) ORDER BY t.created_at
                    ), '[]'::jsonb)
                    FROM public.inclusion_types t
                    WHERE t.inclusion_type_group = g.id
                )
            ) AS groups_with_types
        FROM public.inclusion_type_groups g
        WHERE g.occasion = v_occasion_id
        ORDER BY g.created_at
    ) AS subquery;

    -- Construct the final bundle.
    result := jsonb_build_object(
        'occasion', v_occasion_data,
        'groups', v_groups_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_inclusion_type_groups_by_link(p_occasion_link text) OWNER TO postgres;

