--
-- Name: get_inventory_catalog(bigint, bigint, bigint, text, bigint, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_catalog(p_organization bigint, p_occasion bigint DEFAULT NULL::bigint, p_unit bigint DEFAULT NULL::bigint, p_occasion_link text DEFAULT NULL::text, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50, p_mode text DEFAULT 'page'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint:=p_occasion; result jsonb;
BEGIN
 IF p_mode IS NULL OR p_mode NOT IN ('page','summary') OR p_mode='page' AND p_limit IS NULL
  OR p_mode='summary' AND (p_limit IS NOT NULL OR p_after IS NOT NULL) THEN
  RAISE invalid_parameter_value USING MESSAGE='explicit inventory read mode required'; END IF;
 IF p_occasion_link IS NOT NULL THEN
  oc:=public.resolve_occasion_link_internal(p_occasion_link);
  IF p_occasion IS NOT NULL AND p_occasion IS DISTINCT FROM oc THEN RAISE insufficient_privilege USING MESSAGE='inventory context unavailable'; END IF;
 END IF;
 PERFORM public.check_product_catalog_scope_internal(oc,p_organization,p_unit,false,true);
 result:=public.get_inventory_catalog_data_internal(oc,p_after,p_limit);
 PERFORM public.check_product_catalog_scope_internal(oc,p_organization,p_unit,false,true);
 RETURN result;
END $$;


ALTER FUNCTION public.get_inventory_catalog(p_organization bigint, p_occasion bigint, p_unit bigint, p_occasion_link text, p_after bigint, p_limit integer, p_mode text) OWNER TO postgres;

--
-- Name: get_inventory_catalog_data_internal(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_catalog_data_internal(p_occasion bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[]; next_id bigint; contexts jsonb:='[]'; occasion_data jsonb;
BEGIN
 IF p_limit IS NOT NULL AND (p_limit<1 OR p_limit>100) OR p_after IS NOT NULL AND p_after<1 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid inventory pool page'; END IF;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO ids FROM (
  SELECT id FROM public.inventory_pools WHERE occasion=p_occasion AND (p_after IS NULL OR id>p_after)
  ORDER BY id LIMIT CASE WHEN p_limit IS NULL THEN NULL ELSE p_limit+1 END) selected;
 IF cardinality(ids)>p_limit THEN ids:=ids[1:p_limit];next_id:=ids[p_limit]; END IF;
 IF p_limit IS NULL THEN contexts:=public.get_inventory_context_rows_internal(p_occasion,ids)->'inventory_contexts'; END IF;
 SELECT jsonb_build_object('id',o.id,'title',o.title) INTO occasion_data FROM public.occasions o WHERE o.id=p_occasion;
 RETURN jsonb_build_object('occasionId',p_occasion,'occasion',occasion_data,'pools',public.get_inventory_pool_rows_internal(p_occasion,ids,p_limit IS NULL),
  'inventory_contexts',contexts,'nextCursor',next_id,'readAt',statement_timestamp());
END $$;


ALTER FUNCTION public.get_inventory_catalog_data_internal(p_occasion bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_inventory_context_catalog(bigint, bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_context_catalog(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_limit IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='bounded context page required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool AND occasion=p_occasion FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='inventory pool unavailable'; END IF;
 result:=jsonb_build_object('occasionId',p_occasion,'poolId',p_pool,'readAt',statement_timestamp())
  ||public.get_inventory_context_rows_internal(p_occasion,ARRAY[p_pool],p_after,p_limit);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN result;
END $$;


ALTER FUNCTION public.get_inventory_context_catalog(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_inventory_context_facts_internal(bigint, bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_context_facts_internal(p_occasion bigint, p_pools bigint[], p_contexts bigint[] DEFAULT NULL::bigint[]) RETURNS TABLE(context_id bigint, inventory_pool bigint, physical_count bigint, allocated_count bigint, unassigned_count bigint, held_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT ic.id,ic.inventory_pool,count(s.id),
   count(s.id) FILTER(WHERE s.order_product_ticket IS NOT NULL),
   count(s.id) FILTER(WHERE s.order_product_ticket IS NOT NULL AND coalesce(s.resource,rs.resource) IS NULL),
   count(s.id) FILTER(WHERE s.order_product_ticket IS NULL AND s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp())
 FROM public.inventory_contexts ic JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
 LEFT JOIN eshop.spots s ON s.inventory_context=ic.id
 LEFT JOIN public.resource_slots rs ON rs.id=s.resource_slot
 WHERE ip.occasion=p_occasion AND ip.id=ANY(p_pools) AND (p_contexts IS NULL OR ic.id=ANY(p_contexts))
 GROUP BY ic.id,ic.inventory_pool
$$;


ALTER FUNCTION public.get_inventory_context_facts_internal(p_occasion bigint, p_pools bigint[], p_contexts bigint[]) OWNER TO postgres;

--
-- Name: get_inventory_context_rows_internal(bigint, bigint[], bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_context_rows_internal(p_occasion bigint, p_pools bigint[], p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[]; next_id bigint; rows jsonb;
BEGIN
 IF p_limit IS NOT NULL AND (p_limit<1 OR p_limit>100) OR p_after IS NOT NULL AND p_after<1 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid inventory context page'; END IF;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO ids FROM (
  SELECT ic.id FROM public.inventory_contexts ic JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
  WHERE ip.occasion=p_occasion AND ip.id=ANY(p_pools) AND (p_after IS NULL OR ic.id>p_after)
  ORDER BY ic.id LIMIT CASE WHEN p_limit IS NULL THEN NULL ELSE p_limit+1 END) selected;
 IF cardinality(ids)>p_limit THEN ids:=ids[1:p_limit];next_id:=ids[p_limit]; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',ic.id,'inventory_pool',ic.inventory_pool,
   'title',ic.title,'block_date',ic.block_date,'order',ic."order",
   'physical_count',f.physical_count,'allocated_count',f.allocated_count,'unassigned_count',f.unassigned_count,'held_count',f.held_count)
   ORDER BY CASE WHEN p_limit IS NULL THEN ic."order" END NULLS LAST,ic.id),'[]') INTO rows
 FROM public.inventory_contexts ic JOIN public.get_inventory_context_facts_internal(p_occasion,p_pools,ids) f ON f.context_id=ic.id;
 RETURN jsonb_build_object('inventory_contexts',rows,'nextCursor',next_id);
END $$;


ALTER FUNCTION public.get_inventory_context_rows_internal(p_occasion bigint, p_pools bigint[], p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_inventory_pool_bundle(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pool_bundle(p_inventory_pool_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_pool_data jsonb;
    v_occasion_data jsonb;
    v_resources_data jsonb;
    v_contexts_data jsonb;
    v_places_data jsonb;
    v_products_data jsonb;
    v_product_inventory_contexts_data jsonb; -- New variable for the join table data
    result jsonb;
    settings jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id FOR SHARE;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check
    IF public.can_read_orders(v_occasion_id) IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Current UI and MCP share the pool/context and resource projections.
    settings:=public.get_inventory_pool_settings_data_internal(p_inventory_pool_id);
    v_pool_data:=settings->'pool';
    v_contexts_data:=settings->'contexts';
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE o.id=v_occasion_id;
    v_resources_data:=public.get_inventory_resource_rows_internal(v_occasion_id,
      ARRAY(SELECT id FROM public.resources WHERE inventory_pool=p_inventory_pool_id),true);

    -- Aggregate all places for the occasion
    SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.order), '[]'::jsonb)
    INTO v_places_data
    FROM public.places p
    WHERE p.occasion = v_occasion_id;

    -- MODIFICATION START
    -- Aggregate products that are linked to the inventory contexts of this specific pool.
    SELECT COALESCE(jsonb_agg(to_jsonb(pr)), '[]'::jsonb)
    INTO v_products_data
    FROM (
        SELECT DISTINCT pr.*
        FROM eshop.products pr
        JOIN eshop.product_inventory_contexts pic ON pr.id = pic.product
        JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
        WHERE ic.inventory_pool = p_inventory_pool_id
    ) pr;

    -- Aggregate the product <-> inventory_context join table entries for this pool's contexts.
    SELECT COALESCE(jsonb_agg(to_jsonb(pic)), '[]'::jsonb)
    INTO v_product_inventory_contexts_data
    FROM eshop.product_inventory_contexts pic
    JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Construct the final bundle object, now including context-specific products and the join table data.
    result := jsonb_build_object(
        'pool', v_pool_data,
        'occasion', v_occasion_data,
        'resources', v_resources_data,
        'contexts', v_contexts_data,
        'places', v_places_data,
        'products', v_products_data,
        'product_inventory_contexts', v_product_inventory_contexts_data
        ,'aggregate_version', COALESCE((SELECT av.version
          FROM public.client_aggregate_versions av
          WHERE av.aggregate_type='inventory_pool' AND av.scope_type='occasion'
            AND av.scope_id=v_occasion_id
            AND av.aggregate_id=p_inventory_pool_id::text),0)
    );
    -- MODIFICATION END

    IF public.can_read_orders(v_occasion_id) IS DISTINCT FROM TRUE THEN
        RAISE insufficient_privilege USING MESSAGE='occasion order viewer required';
    END IF;
    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_inventory_pool_bundle(p_inventory_pool_id bigint) OWNER TO postgres;

--
-- Name: get_inventory_pool_for_edit(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pool_for_edit(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool AND occasion=p_occasion FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='inventory pool unavailable'; END IF;
 result:=public.get_inventory_pool_bundle(p_pool);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 IF result ? 'code' AND (result->>'code')::integer<>200 THEN RAISE EXCEPTION 'inventory editor unavailable'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.get_inventory_pool_for_edit(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint) OWNER TO postgres;

--
-- Name: get_inventory_pool_rows_internal(bigint, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pool_rows_internal(p_occasion bigint, p_ids bigint[], p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH context_totals AS (
  SELECT inventory_pool,count(*) context_count,sum(physical_count) physical_count,sum(allocated_count) allocated_count,
   sum(unassigned_count) unassigned_count,sum(held_count) held_count
  FROM public.get_inventory_context_facts_internal(p_occasion,p_ids) GROUP BY inventory_pool
 ), resource_totals AS (
  SELECT inventory_pool,count(*) resource_count,sum(capacity) resource_capacity FROM public.resources
  WHERE inventory_pool=ANY(p_ids) GROUP BY inventory_pool
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',ip.id,'occasion',ip.occasion,'title',ip.title,
  'created_at',ip.created_at,'updated_at',ip.updated_at,'type',ip.type,'sellable_capacity',ip.sellable_capacity,
  'aggregate_version',coalesce(v.version,0),'context_count',coalesce(c.context_count,0),
  'physical_count',coalesce(c.physical_count,0),'allocated_count',coalesce(c.allocated_count,0),
  'unassigned_count',coalesce(c.unassigned_count,0),'held_count',coalesce(c.held_count,0),
  'resource_count',coalesce(r.resource_count,0),'resource_capacity',coalesce(r.resource_capacity,0)) ORDER BY CASE WHEN p_editor THEN ip.created_at END,ip.id),'[]')
 FROM public.inventory_pools ip LEFT JOIN context_totals c ON c.inventory_pool=ip.id LEFT JOIN resource_totals r ON r.inventory_pool=ip.id
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='inventory_pool' AND v.scope_type='occasion'
  AND v.scope_id=p_occasion AND v.aggregate_id=ip.id::text
 WHERE ip.id=ANY(p_ids) AND ip.occasion=p_occasion
$$;


ALTER FUNCTION public.get_inventory_pool_rows_internal(p_occasion bigint, p_ids bigint[], p_editor boolean) OWNER TO postgres;

--
-- Name: get_inventory_pool_settings(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pool_settings(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool AND occasion=p_occasion FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='inventory pool unavailable'; END IF;
 result:=public.get_inventory_pool_settings_internal(p_pool);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'settings',result,'readAt',statement_timestamp());
END $$;


ALTER FUNCTION public.get_inventory_pool_settings(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint) OWNER TO postgres;

--
-- Name: get_inventory_pool_settings_data_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pool_settings_data_internal(p_pool bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 SELECT jsonb_build_object('pool',jsonb_build_object('id',ip.id,'occasion',ip.occasion,'title',ip.title,
  'created_at',ip.created_at,'updated_at',ip.updated_at,'description',ip.description,'type',ip.type,'sellable_capacity',ip.sellable_capacity,'data',ip.data),
  'contexts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',ic.id,'inventory_pool',ic.inventory_pool,
   'title',ic.title,'block_date',ic.block_date,'order',ic."order",'data',ic.data) ORDER BY ic."order" NULLS LAST,ic.id)
   FROM public.inventory_contexts ic WHERE ic.inventory_pool=ip.id),'[]'),
  'aggregate_version',coalesce(v.version,0)) INTO result
 FROM public.inventory_pools ip LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='inventory_pool'
  AND v.scope_type='occasion' AND v.scope_id=ip.occasion AND v.aggregate_id=ip.id::text WHERE ip.id=p_pool;
 RETURN result;
END $$;


ALTER FUNCTION public.get_inventory_pool_settings_data_internal(p_pool bigint) OWNER TO postgres;

--
-- Name: get_inventory_pool_settings_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pool_settings_internal(p_pool bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 IF (SELECT count(*) FROM public.inventory_contexts WHERE inventory_pool=p_pool)>2000 THEN
  RAISE program_limit_exceeded USING MESSAGE='pool exceeds context authoring limit'; END IF;
 result:=public.get_inventory_pool_settings_data_internal(p_pool);
 result:=jsonb_set(result,'{pool}',(result->'pool')-ARRAY['created_at','updated_at']);
 IF octet_length(result::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='pool exceeds authoring payload limit'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.get_inventory_pool_settings_internal(p_pool bigint) OWNER TO postgres;

--
-- Name: get_inventory_pools_by_occasion_link(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_pools_by_occasion_link(p_occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_occasion_data jsonb;
    v_pools_data jsonb;
    v_inventory_contexts_data jsonb;
    v_spots_data jsonb;
    result jsonb;
    catalog jsonb;
BEGIN
    -- Canonical merges may contain the same legacy link in multiple tenants.
    SELECT o.id
    INTO v_occasion_id
    FROM public.occasions o
    WHERE o.id = public.resolve_occasion_link_internal(p_occasion_link)
      AND o.organization = (
        SELECT ui.organization
        FROM public.user_info ui
        WHERE ui.id = auth.uid()
      );
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with link % not found.', p_occasion_link;
    END IF;

    -- Permission check to ensure the user can view data for this occasion.
    IF NOT COALESCE((
        SELECT ou.is_editor_order_view
        FROM public.occasion_users ou
        WHERE ou."user" = auth.uid()
          AND ou.occasion = v_occasion_id
    ), false) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the full occasion object
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE id = v_occasion_id;

    -- Released clients still need the old raw spot array. Metadata and counts
    -- delegate to the same projection as the current summary UI/MCP readers.
    catalog:=public.get_inventory_catalog_data_internal(v_occasion_id);
    SELECT coalesce(jsonb_agg(p.value||jsonb_build_object('description',ip.description,'data',ip.data)
      ORDER BY ip.created_at,ip.id),'[]') INTO v_pools_data
      FROM jsonb_array_elements(catalog->'pools') p(value) JOIN public.inventory_pools ip ON ip.id=(p.value->>'id')::bigint WHERE ip.occasion=v_occasion_id;
    SELECT coalesce(jsonb_agg(c.value||jsonb_build_object('data',ic.data) ORDER BY ic."order" NULLS LAST,ic.id),'[]') INTO v_inventory_contexts_data
      FROM jsonb_array_elements(catalog->'inventory_contexts') c(value) JOIN public.inventory_contexts ic ON ic.id=(c.value->>'id')::bigint
      JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool WHERE ip.occasion=v_occasion_id;

    -- Aggregate all spots that belong to any context within the occasion's pools
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'secret', s.secret,
        'secret_expiration_time', s.secret_expiration_time,
        'order_product_ticket', s.order_product_ticket,
        'inventory_context', s.inventory_context,
        'resource', s.resource,
        'state', s.state
    ) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inventory_context IN (
        SELECT id FROM public.inventory_contexts WHERE inventory_pool IN (
            SELECT id FROM public.inventory_pools WHERE occasion = v_occasion_id
        )
    );

    -- Construct the final bundle object with the new data
    result := jsonb_build_object(
        'occasion', v_occasion_data,
        'pools', v_pools_data,
        'inventory_contexts', v_inventory_contexts_data,
        'spots', v_spots_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_inventory_pools_by_occasion_link(p_occasion_link text) OWNER TO postgres;

--
-- Name: get_inventory_resource_rows_internal(bigint, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_resource_rows_internal(p_occasion bigint, p_ids bigint[], p_editor boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'inventory_pool',r.inventory_pool,'occasion',r.occasion,
  'title',r.title,'capacity',r.capacity,'booking_rules',CASE WHEN p_editor THEN r.booking_rules ELSE coalesce(r.booking_rules,'{}') END,
  'aggregate_version',coalesce(v.version,0)) || CASE WHEN p_editor THEN jsonb_build_object(
   'created_at',r.created_at,'updated_at',r.updated_at,'description',r.description,'place',r.place,'unit',r.unit,'data',r.data,
   'slots',coalesce((SELECT jsonb_agg(jsonb_build_object('id',rs.id,'resource',rs.resource,'title',rs.title,'data',rs.data) ORDER BY rs.id)
    FROM public.resource_slots rs WHERE rs.resource=r.id),'[]')) ELSE '{}'::jsonb END
  ORDER BY CASE WHEN p_editor THEN r.title END,r.id),'[]')
 FROM public.resources r JOIN public.inventory_pools ip ON ip.id=r.inventory_pool AND ip.occasion=p_occasion
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='resource' AND v.scope_type='occasion'
  AND v.scope_id=p_occasion AND v.aggregate_id=r.id::text WHERE r.id=ANY(p_ids) AND r.occasion=p_occasion
$$;


ALTER FUNCTION public.get_inventory_resource_rows_internal(p_occasion bigint, p_ids bigint[], p_editor boolean) OWNER TO postgres;

--
-- Name: get_inventory_resources(bigint, bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_inventory_resources(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];next_id bigint;rows jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR p_after IS NOT NULL AND p_after<1 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid resource page'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool AND occasion=p_occasion FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='inventory pool unavailable'; END IF;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO ids FROM (
  SELECT id FROM public.resources WHERE inventory_pool=p_pool AND occasion=p_occasion AND (p_after IS NULL OR id>p_after)
  ORDER BY id LIMIT p_limit+1) selected;
 IF cardinality(ids)>p_limit THEN ids:=ids[1:p_limit];next_id:=ids[p_limit]; END IF;
 rows:=public.get_inventory_resource_rows_internal(p_occasion,ids,false);
 IF octet_length(rows::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='resource page exceeds payload limit; use a smaller limit'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'poolId',p_pool,'resources',rows,'nextCursor',next_id,'readAt',statement_timestamp());
END $$;


ALTER FUNCTION public.get_inventory_resources(p_occasion bigint, p_organization bigint, p_unit bigint, p_pool bigint, p_after bigint, p_limit integer) OWNER TO postgres;

