CREATE FUNCTION public.get_is_manager_on_unit(unit_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT NOT public.is_demo_unit(unit_id) AND EXISTS (
    SELECT 1
    FROM public.unit_users membership
    WHERE membership."user" = auth.uid()
      AND membership.unit = unit_id
      AND membership.is_manager
  );
$$;


ALTER FUNCTION public.get_is_manager_on_unit(unit_id bigint) OWNER TO postgres;

--
-- Name: get_is_receptionist_on_occasion(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_is_receptionist_on_occasion(oc bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT COALESCE((SELECT ou.is_receptionist
    FROM public.occasion_users ou
    WHERE ou."user"=auth.uid() AND ou.occasion=oc),false);
$$;


ALTER FUNCTION public.get_is_receptionist_on_occasion(oc bigint) OWNER TO postgres;

--
-- Name: get_last_sign_in_at(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_last_sign_in_at(user_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF public.get_can_view_user_auth(user_id) IS NOT TRUE THEN
    RAISE insufficient_privilege USING MESSAGE = 'User auth metadata access denied';
  END IF;
  RETURN (SELECT au.last_sign_in_at FROM auth.users au WHERE au.id = user_id);
END;
$$;


ALTER FUNCTION public.get_last_sign_in_at(user_id uuid) OWNER TO postgres;

--
-- Name: get_last_sign_in_at_for_users(uuid[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_last_sign_in_at_for_users(user_ids uuid[], oc bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- Check if the user is a manager for the occasion
  IF (SELECT get_is_manager_on_occasion(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Aggregate the last sign-in data as JSON
  RETURN jsonb_build_object(
    'code', 200,
    'data', (
      SELECT jsonb_agg(jsonb_build_object(
        'user_id', au.id,
        'last_sign_in_at', au.last_sign_in_at
      ))
      FROM auth.users au
      JOIN public.occasion_users ou ON au.id = ou."user"
      WHERE au.id = ANY(user_ids)
        AND ou.occasion = oc AND public.occasion_member_visible_internal(oc,au.id)
    )
  );
END;
$$;


ALTER FUNCTION public.get_last_sign_in_at_for_users(user_ids uuid[], oc bigint) OWNER TO postgres;

--
-- Name: get_latest_autosave(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_latest_autosave(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    autosave_record JSONB;
    v_latest_publish_id BIGINT;
BEGIN
 IF auth.uid() IS NULL OR NOT public.get_is_editor_view_on_occasion(p_occasion_id) THEN RETURN jsonb_build_object('code',403); END IF;
    -- Select the single latest autosave record for the current user
    SELECT jsonb_build_object(
        'id', id,
        'created_at', created_at,
        'activities_data', activities_data,
        'parent_history_id', parent_history_id
    )
    INTO autosave_record
    FROM public.activity_history
    WHERE occasion_id = p_occasion_id
      AND user_id = auth.uid()
      AND history_type = 'AUTOSAVE'
    ORDER BY created_at DESC
    LIMIT 1;

    -- Separately, find the ID of the absolute latest published version for the occasion
    SELECT id
    INTO v_latest_publish_id
    FROM public.activity_history
    WHERE occasion_id = p_occasion_id
      AND history_type = 'PUBLISH'
    ORDER BY created_at DESC
    LIMIT 1;

    -- Return an object containing both the autosave data (if found) and the latest publish ID (if found)
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Autosave and publish info retrieved.',
        'data', jsonb_build_object(
            'autosave', autosave_record,
            'latest_publish_id', v_latest_publish_id
        )
    );
END;
$$;


ALTER FUNCTION public.get_latest_autosave(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_latest_order_history(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_latest_order_history(order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT to_jsonb(o) || jsonb_build_object('order_symbol', (SELECT ord.order_symbol FROM eshop.orders ord WHERE ord.id=o."order"), 'order_sequence', (SELECT ord.order_sequence FROM eshop.orders ord WHERE ord.id=o."order"))
    INTO result
  FROM eshop.orders_history o
  WHERE o."order" = order_id AND (o.price <> 0 OR o.state IS DISTINCT FROM 'storno')
  -- Free orders also need cancellation emails; prefer the existing nonzero history.
  ORDER BY (o.price <> 0) DESC NULLS LAST, o.created_at DESC, o.id DESC
  LIMIT 1;

  RETURN result;
END;
$$;


ALTER FUNCTION public.get_latest_order_history(order_id bigint) OWNER TO postgres;

--
-- Name: get_map_editor_bundle_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_map_editor_bundle_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE WHEN public.can_read_map_editor_bundle(p_occasion) IS NOT TRUE
    THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object(
      'code',200,
      'places',COALESCE((SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY p."order" NULLS LAST,p.id)
        FROM public.places p LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='place' AND v.scope_type='occasion'
          AND v.scope_id=p_occasion AND v.aggregate_id=p.id::text
        WHERE p.occasion=p_occasion),'[]'::jsonb),
      'placeTypes',COALESCE((SELECT jsonb_agg(to_jsonb(t)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY t."order" NULLS LAST,t.id)
        FROM public.place_types t LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='place_type' AND v.scope_type='occasion'
          AND v.scope_id=p_occasion AND v.aggregate_id=t.id::text
        WHERE t.occasion=p_occasion),'[]'::jsonb),
      'paths',COALESCE((SELECT jsonb_agg(to_jsonb(pg)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY pg."order" NULLS LAST,pg.id)
        FROM public.path_groups pg LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='path' AND v.scope_type='occasion'
          AND v.scope_id=p_occasion AND v.aggregate_id=pg.id::text
        WHERE pg.occasion=p_occasion),'[]'::jsonb),
      'icons',COALESCE((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY i.link,i.id)
        FROM public.occasions o JOIN public.icons i ON i.organization=o.organization
          AND (i.unit=o.unit OR i.unit IS NULL)
        LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='icon' AND v.scope_type='unit'
          AND v.scope_id=o.unit AND v.aggregate_id=i.id::text
        WHERE o.id=p_occasion),'[]'::jsonb)) END;
$$;


ALTER FUNCTION public.get_map_editor_bundle_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_my_admin_bank_accounts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_admin_bank_accounts() RETURNS TABLE(id bigint, account_number text, account_number_human_readable text, title text, creditor_name text, type text, token_masked text, token_expiry_date timestamp with time zone, supported_currencies text[], linked_units text[], last_fetch_time timestamp with time zone, last_fio_fetch_time timestamp with time zone, bank_sync jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ba.id,
        ba.account_number,
        ba.account_number_human_readable,
        ba.title,
        ba.creditor_name,
        ba.type,
        NULL::text as token_masked,
        CASE WHEN public.can_manage_bank_account(ba.id) THEN
          (public.get_bank_sync_connection(ba.id)->>'token_expiry_at')::timestamptz END as token_expiry_date,
        ba.supported_currencies,
        ARRAY(
            SELECT u.title
            FROM eshop.unit_bank_accounts uba
            JOIN public.units u ON uba.unit = u.id
            WHERE uba.bank_account = ba.id
        ) as linked_units,
        ba.last_fetch_time,
        ba.last_fio_fetch_time,
        CASE WHEN public.can_manage_bank_account(ba.id) THEN
          public.get_bank_sync_connection(ba.id) END AS bank_sync
    FROM eshop.bank_accounts ba
    JOIN eshop.bank_account_users bau ON ba.id = bau.bank_account
    WHERE bau."user" = auth.uid() AND bau.is_admin = true
    AND upper(ba.type) <> 'CASH'
    ORDER BY ba.title;
END;
$$;


ALTER FUNCTION public.get_my_admin_bank_accounts() OWNER TO postgres;

--
-- Name: get_my_admin_organization_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_admin_organization_id() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  org_id bigint;
BEGIN
  SELECT organization INTO org_id
  FROM organization_users
  WHERE "user" = auth.uid()
    AND is_admin = true
  LIMIT 1;

  RETURN org_id;
END;
$$;


