--
-- Name: get_my_events_and_activities(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_events_and_activities(p_occasion bigint, p_include_description boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    current_user_id        UUID := auth.uid();
    event_ids_to_use       BIGINT[];
    eventsData             JSONB;
    eventUsersData         JSONB;
    eventUsersSavedData    JSONB;
    placesData             JSONB;
    eventGroupsData        JSONB;
    activitiesData         JSONB;
    assignmentsData        JSONB;
    assignmentEventsData   JSONB;
    assignmentPlacesData   JSONB;
BEGIN
    -- Select IDs of all events relevant to the user first
    SELECT array_agg(e.id)
    INTO event_ids_to_use
    FROM public.events e
    WHERE e.occasion   = p_occasion
      AND e.is_hidden  = FALSE
      AND (
        EXISTS (
          SELECT 1
          FROM public.event_users eu
          WHERE eu.event = e.id
            AND eu."user" = current_user_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.event_users_saved eus
          WHERE eus.event = e.id
            AND eus."user" = current_user_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.activity_assignment_events aae
          JOIN public.activity_assignments aa
            ON aa.id = aae.assignment_id
          JOIN public.activities a
            ON a.id = aa.activity_id
          WHERE aae.event_id = e.id
            AND aa."user"    = current_user_id
            AND a.occasion   = p_occasion
        )
        OR EXISTS (
          SELECT 1
            FROM public.activity_assignments aa
            JOIN public.activity_assignment_places aap ON aa.id = aap.assignment_id
            JOIN public.activities a ON a.id = aa.activity_id
           WHERE aa."user" = current_user_id
             AND a.occasion = p_occasion
             AND aap.place_id = e.place
             AND ( (aa.start_time <= e.start_time AND e.start_time < aa.end_time) OR (e.start_time <= aa.start_time AND aa.start_time < e.end_time) )
        )
      );

    -- (a) Events related to the current user, using the pre-selected IDs
    SELECT jsonb_agg(jsonb_build_object(
        'id',                   e.id,
        'created_at',           e.created_at,
        'title',                e.title,
        'start_time',           e.start_time,
        'end_time',             e.end_time,
        'max_participants',     e.max_participants,
        'type',                 e.type,
        'data',                 e.data,
        'description',          CASE WHEN p_include_description THEN e.description ELSE NULL END,
        'place',                e.place,
        'split_for_men_women',  e.split_for_men_women,
        'is_group_event',       e.is_group_event,
        'updated_at',           e.updated_at,
        'is_hidden',            e.is_hidden,
        'occasion',             e.occasion,
        'isSignedIn',           (current_user_id IS NOT NULL
                                   AND EXISTS (
                                     SELECT 1
                                       FROM public.event_users eu
                                      WHERE eu.event = e.id
                                        AND eu."user" = current_user_id
                                   )
                                ),
        'isEventInMyProgram',   (current_user_id IS NOT NULL
                                   AND EXISTS (
                                     SELECT 1
                                       FROM public.event_users_saved eus
                                      WHERE eus.event = e.id
                                        AND eus."user" = current_user_id
                                   )
                                )
    ))
    INTO eventsData
    FROM public.events e
    WHERE e.id = ANY(COALESCE(event_ids_to_use, '{}'));

    -- (b) Counts of users signed in for these events
    WITH user_counts AS (
      SELECT eu.event AS event, COUNT(*) AS cnt
      FROM public.event_users eu
      JOIN public.events e ON eu.event = e.id
      WHERE e.occasion   = p_occasion
        AND e.is_hidden = FALSE
      GROUP BY eu.event
    )
    SELECT jsonb_agg(jsonb_build_object('event', uc.event, 'count', uc.cnt))
      INTO eventUsersData
    FROM user_counts uc;

    -- (c) Counts of users who saved these events
    WITH saved_counts AS (
      SELECT eus.event AS event, COUNT(*) AS cnt
      FROM public.event_users_saved eus
      JOIN public.events e ON eus.event = e.id
      WHERE e.occasion   = p_occasion
        AND e.is_hidden = FALSE
      GROUP BY eus.event
    )
    SELECT jsonb_agg(jsonb_build_object('event', sc.event, 'count', sc.cnt))
      INTO eventUsersSavedData
    FROM saved_counts sc;

    -- (d) Places: from events and from activity assignments
    WITH place_ids AS (
      SELECT e.place AS place_id
      FROM public.events e
      WHERE e.id = ANY(COALESCE(event_ids_to_use, '{}')) AND e.place IS NOT NULL
      UNION
      SELECT ap.place_id
      FROM public.activity_assignment_places ap
      JOIN public.activity_assignments aa ON aa.id = ap.assignment_id
      JOIN public.activities a            ON a.id = aa.activity_id
      WHERE aa."user"  = current_user_id
        AND a.occasion = p_occasion
    )
    SELECT jsonb_agg(jsonb_build_object(
        'id',           p.id,
        'title',        p.title,
        'description',  p.description,
        'type',         p.type,
        'created_at',   p.created_at,
        'coordinates',  p.coordinates,
        'is_hidden',    p.is_hidden,
        'updated_at',   p.updated_at,
        'occasion',     p.occasion
    ))
    INTO placesData
    FROM public.places p
    WHERE p.id IN (SELECT place_id FROM place_ids);

    -- (NEW SECTION i for event_groups) Event groups where either parent or child is a user-related, non-hidden event for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'event_parent', eg.event_parent,
        'event_child',  eg.event_child
    ))
    INTO eventGroupsData
    FROM public.event_groups eg
    JOIN public.events e1 ON eg.event_parent = e1.id
    JOIN public.events e2 ON eg.event_child  = e2.id
    WHERE e1.occasion   = p_occasion
      AND e1.is_hidden  = FALSE
      AND e2.occasion   = p_occasion
      AND e2.is_hidden  = FALSE
      AND (e1.id = ANY(COALESCE(event_ids_to_use, '{}')) OR e2.id = ANY(COALESCE(event_ids_to_use, '{}')));

    -- (e) Activities the user is assigned to
    SELECT jsonb_agg(jsonb_build_object(
        'id',           a.id,
        'created_at',   a.created_at,
        'title',        a.title,
        'description',  CASE WHEN p_include_description THEN a.description ELSE NULL END,
        'data',         a.data,
        'type',         a.type,
        'occasion',     a.occasion,
        'unit',         a.unit,
        'is_hidden',    a.is_hidden,
        'order',        a."order",
        'updated_at',   a.updated_at
    ))
    INTO activitiesData
    FROM public.activities a
    JOIN public.activity_assignments aa ON aa.activity_id = a.id
    WHERE aa."user"    = current_user_id
      AND a.occasion   = p_occasion
      AND a.is_hidden  = FALSE;

    -- (f) User's activity assignments
    SELECT jsonb_agg(jsonb_build_object(
        'id',           aa.id,
        'activity_id',  aa.activity_id,
        'start_time',   aa.start_time,
        'end_time',     aa.end_time,
        'title',        aa.title,
        'description',  CASE WHEN p_include_description THEN aa.description ELSE NULL END,
        'data',         aa.data
    ))
    INTO assignmentsData
    FROM public.activity_assignments aa
    JOIN public.activities a ON a.id = aa.activity_id
    WHERE aa."user"    = current_user_id
      AND a.occasion   = p_occasion;

    -- (g) Assignment ↔ Event links
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', aae.assignment_id,
        'event_id',      aae.event_id
    ))
    INTO assignmentEventsData
    FROM public.activity_assignment_events aae
    JOIN public.activity_assignments aa ON aa.id = aae.assignment_id
    JOIN public.activities a            ON a.id = aa.activity_id
    WHERE aa."user"  = current_user_id
      AND a.occasion = p_occasion;

    -- (h) Assignment ↔ Place links
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', ap.assignment_id,
        'place_id',      ap.place_id
    ))
    INTO assignmentPlacesData
    FROM public.activity_assignment_places ap
    JOIN public.activity_assignments aa ON aa.id = ap.assignment_id
    JOIN public.activities a            ON a.id = aa.activity_id
    WHERE aa."user"  = current_user_id
      AND a.occasion = p_occasion;

    -- Final assembly
    RETURN jsonb_build_object(
      'code', 200,
      'data', jsonb_build_object(
        'events',               COALESCE(eventsData,           '[]'::jsonb),
        'event_users',          COALESCE(eventUsersData,       '[]'::jsonb),
        'event_users_saved',    COALESCE(eventUsersSavedData,  '[]'::jsonb),
        'places',               COALESCE(placesData,           '[]'::jsonb),
        'event_groups',         COALESCE(eventGroupsData,      '[]'::jsonb),
        'activities',           COALESCE(activitiesData,       '[]'::jsonb),
        'activity_assignments', COALESCE(assignmentsData,      '[]'::jsonb),
        'assignment_events',    COALESCE(assignmentEventsData, '[]'::jsonb),
        'assignment_places',    COALESCE(assignmentPlacesData, '[]'::jsonb)
      )
    );
END;
$$;


ALTER FUNCTION public.get_my_events_and_activities(p_occasion bigint, p_include_description boolean) OWNER TO postgres;

--
-- Name: get_my_recent_reception_registrations_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_recent_reception_registrations_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
SELECT CASE WHEN public.get_can_use_reception(p_occasion) THEN COALESCE(jsonb_agg(jsonb_build_object('userId',r."user",'name',ui.name,'surname',ui.surname,'email',ui.email_readonly,'createdAt',r.created_at,'qrUsed',c.last_used_at IS NOT NULL) ORDER BY r.created_at DESC),'[]'::jsonb) ELSE '[]'::jsonb END
FROM public.reception_registrations r JOIN public.user_info ui ON ui.id=r."user" LEFT JOIN public.user_login_qr_credentials c ON (c.occasion,c."user")=(r.occasion,r."user")
WHERE r.occasion=p_occasion AND r.created_by=auth.uid() AND r.status='active' AND r.created_at>now()-interval '30 minutes'; $$;


ALTER FUNCTION public.get_my_recent_reception_registrations_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_news_for_context_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_news_for_context_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(n)||jsonb_build_object('aggregate_version',
   coalesce(v.version,0)) ORDER BY n.id DESC),'[]'::jsonb)
 FROM public.get_news_with_views(p_occasion) n
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='news'
 AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=n.id::text;
$$;


ALTER FUNCTION public.get_news_for_context_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_news_read_state_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_news_read_state_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE marker bigint;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_news_data_security_v1(p_occasion)
   OR NOT EXISTS(SELECT 1 FROM public.user_info ui JOIN public.occasions o
     ON o.organization=ui.organization WHERE ui.id=auth.uid() AND o.id=p_occasion) THEN
   RAISE insufficient_privilege USING MESSAGE='news read access required';
 END IF;
 SELECT coalesce(max(news_id),0) INTO marker FROM public.user_news
 WHERE occasion=p_occasion AND "user"=auth.uid();
 RETURN jsonb_build_object('newsId',marker);
END $$;


ALTER FUNCTION public.get_news_read_state_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_news_view_counts_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_news_view_counts_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'newsId',n.id,
    'views',(SELECT count(*) FROM public.user_news un
      WHERE un.occasion=p_occasion AND un.news_id>=n.id)
  ) ORDER BY n.id),'[]'::jsonb)
  FROM public.news n
  WHERE n.occasion=p_occasion;
$$;


ALTER FUNCTION public.get_news_view_counts_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_news_with_versions_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_news_with_versions_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.check_access_to_occasion(p_occasion);
 RETURN coalesce((SELECT jsonb_agg(to_jsonb(n)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) ORDER BY n.id DESC)
  FROM public.get_news_with_views(p_occasion) n LEFT JOIN public.client_aggregate_versions v
  ON v.aggregate_type='news' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=n.id::text),'[]');
END $$;


ALTER FUNCTION public.get_news_with_versions_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_news_with_views(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_news_with_views(oc bigint) RETURNS TABLE(id bigint, created_at timestamp with time zone, message text, name text, surname text, views bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$

BEGIN
    -- Check if the user has access to the occasion
    PERFORM public.get_occasion_for_context_v1(oc);

    -- Return the news data with the total views count, ordered by highest news_id
    RETURN QUERY
    SELECT
        n.id,
        n.created_at,
        n.message,
        -- Return NULL for name and surname if created_by is NULL
        CASE WHEN n.created_by IS NULL THEN NULL ELSE ui.name END AS name,
        CASE WHEN n.created_by IS NULL THEN NULL ELSE ui.surname END AS surname,
        COUNT(un."user") AS views  -- Counting all users who have interacted with the news
    FROM
        public.news n
    LEFT JOIN
        public.user_info ui ON ui.id = n.created_by  -- Join user_info to get the name and surname
    LEFT JOIN
        public.user_news un ON un.news_id = n.id AND un.occasion = oc  -- Join with user_news to count users for the specific occasion
    WHERE
        n.occasion = oc
    GROUP BY
        n.id, ui.name, ui.surname
    ORDER BY
        n.id DESC;  -- Sorting by news_id in descending order (highest first)

END;
$$;


ALTER FUNCTION public.get_news_with_views(oc bigint) OWNER TO postgres;

