--
-- Name: get_occasion_for_context_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_for_context_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o public.occasions; privileged boolean;
BEGIN
 SELECT * INTO o FROM public.occasions WHERE id=p_occasion;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='occasion unavailable'; END IF;
 privileged := public.can_read_occasion_editor_data(o.id);
 IF public.is_demo_occasion(o.id) AND NOT public.can_read_demo_occasion(o.id) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion unavailable';
 END IF;
 IF privileged THEN
   RETURN to_jsonb(o);
 END IF;
 IF auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.occasion_users
     WHERE occasion=o.id AND "user"=auth.uid()) THEN
   RETURN to_jsonb(o)-'occasion_hidden';
 END IF;
 IF o.is_hidden IS DISTINCT FROM false OR o.is_open IS DISTINCT FROM true THEN
   RAISE insufficient_privilege USING MESSAGE='occasion unavailable';
 END IF;
 RETURN jsonb_build_object('id',o.id,'title',o.title,'description',o.description,
   'link',o.link,'start_time',o.start_time,'end_time',o.end_time,
   'is_open',o.is_open,'is_hidden',false,'is_promoted',o.is_promoted,
   'organization',o.organization,'unit',o.unit,
   'data',jsonb_build_object('timezone',o.data->'timezone'));
END $$;


ALTER FUNCTION public.get_occasion_for_context_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_occasion_for_edit_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_for_edit_v1(p_link text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion bigint;
  v_result jsonb;
BEGIN
  SELECT o.id
  INTO v_occasion
  FROM public.occasions o
  WHERE o.id = public.resolve_occasion_link_internal(p_link)
    AND o.organization = (
      SELECT ui.organization
      FROM public.user_info ui
      WHERE ui.id = auth.uid()
    );

  IF v_occasion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE = 'occasion not found';
  END IF;

  IF NOT public.can_read_occasion_editor_data(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor view required';
  END IF;

  SELECT to_jsonb(o) || jsonb_build_object(
    'aggregate_version', COALESCE(v.version, 0)
  )
  INTO v_result
  FROM public.occasions o
  LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type = 'occasion'
    AND v.scope_type = 'occasion'
    AND v.scope_id = o.id
    AND v.aggregate_id = o.id::text
  WHERE o.id = v_occasion;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_occasion_for_edit_v1(p_link text) OWNER TO postgres;

--
-- Name: get_occasion_from_link(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_from_link(org_id bigint, link_txt text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    occasionId bigint;
    is_open_bool BOOLEAN;
    occasion_user occasion_users%rowtype;
    is_admin_bool BOOLEAN;
    occasion_link text;
    version_recommended text;
BEGIN
    -- If no link is provided, get the default occasion from the organization
    IF link_txt = '' THEN
        -- Get the default occasion ID from the organization's data
        SELECT data->>'DEFAULT_OCCASION' INTO occasionId
        FROM organizations
        WHERE id = org_id;

        -- If no default occasion is set, get the first open and non-hidden occasion within the organization
        IF occasionId IS NULL THEN
            SELECT id, link INTO occasionId, occasion_link
            FROM occasions
            WHERE is_open = true
              AND is_hidden = false
              AND organization = org_id
            LIMIT 1;

            -- If no open occasion is found, return a 404 response
            IF occasionId IS NULL THEN
                RETURN json_build_object('code', 404, 'message', 'No open occasion found for the organization');
            END IF;
        ELSE
            -- Get the link for the default occasion
            SELECT link INTO occasion_link
            FROM occasions
            WHERE id = occasionId AND organization = org_id;
        END IF;
    ELSE
        -- Get the occasion ID and link for the provided link within the specified organization
        SELECT id, link INTO occasionId, occasion_link
        FROM occasions
        WHERE id = public.resolve_occasion_link_internal(link_txt,org_id)
          AND is_hidden = false
          AND organization = org_id;

        -- If the occasion ID is not found, return a 404 response
        IF occasionId IS NULL THEN
            RETURN json_build_object('code', 404, 'message', 'Occasion not found');
        END IF;
    END IF;

     -- Retrieve version_recommended from organization's data
    SELECT data->>'VERSION_RECOMMENDED' INTO version_recommended
    FROM organizations
    WHERE id = org_id;

    -- Get the is_open status for the occasion
    SELECT is_open INTO is_open_bool
    FROM occasions
    WHERE id = occasionId;

    -- Get the occasion user record if it exists
    SELECT * INTO occasion_user
    FROM occasion_users
    WHERE occasion = occasionId
      AND "user" = auth.uid();

    -- Check if the current user is an admin on the occasion
    is_admin_bool := get_is_admin_on_occasion(occasionId);

    -- If the occasion is not open, enforce access restrictions
    IF is_open_bool = FALSE THEN
        IF auth.uid() IS NULL THEN
            RETURN json_build_object('code', 403, 'message', 'Access forbidden', 'link', occasion_link, 'version_recommended', version_recommended);
        END IF;
        IF occasion_user IS NULL AND NOT is_admin_bool THEN
            RETURN json_build_object('code', 403, 'message', 'Access forbidden', 'link', occasion_link, 'version_recommended', version_recommended);
        END IF;
        RETURN json_build_object(
            'code', 200,
            'is_admin', is_admin_bool,
            'occasion_user', COALESCE(row_to_json(occasion_user)::jsonb, NULL),
            'link', occasion_link,
            'occasion', occasionId,
            'version_recommended', version_recommended
        );
    END IF;

    -- If the occasion user record is not found, the user is authenticated, and the occasion is open
    IF occasion_user IS NULL AND auth.uid() IS NOT NULL THEN
        -- Add the user to the occasion
        PERFORM add_user_to_occasion(occasionId, auth.uid());

        -- Fetch the updated occasion user record
        SELECT * INTO occasion_user
        FROM occasion_users
        WHERE occasion = occasionId
          AND "user" = auth.uid();
    END IF;

    -- If the occasion user record is still not found and the user is not an admin, return basic occasion data
    IF occasion_user IS NULL THEN
        RETURN json_build_object(
            'code', 200,
            'is_admin', is_admin_bool,
            'link', occasion_link,
            'occasion', occasionId,
            'version_recommended', version_recommended
        );
    END IF;

    -- Return full occasion data including the user and admin status
    RETURN json_build_object(
        'code', 200,
        'is_admin', is_admin_bool,
        'occasion_user', row_to_json(occasion_user)::jsonb,
        'link', occasion_link,
        'occasion', occasionId,
        'version_recommended', version_recommended
    );
END;
$$;


ALTER FUNCTION public.get_occasion_from_link(org_id bigint, link_txt text) OWNER TO postgres;

--
-- Name: get_occasion_media_job(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_media_job(p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE job public.occasion_media_jobs;
BEGIN
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id;
 IF job.command_id IS NULL OR job.actor_id IS DISTINCT FROM auth.uid() THEN RAISE insufficient_privilege USING MESSAGE='lifecycle intent unavailable'; END IF;
 PERFORM public.lock_people_scope_internal_v1(NULL,job.organization,job.source_unit);
 IF job.action='delete' THEN
  IF NOT public.can_delete_occasion_in_unit(job.source_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 ELSE
  PERFORM public.lock_people_scope_internal_v1(NULL,job.organization,job.target_unit);
  IF NOT (public.can_copy_occasion_source(job.source_occasion) OR (NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=job.source_occasion) AND public.can_copy_occasion_target(job.source_unit))) OR NOT public.can_copy_occasion_target(job.target_unit)
   OR (EXISTS(SELECT 1 FROM public.occasions WHERE id=job.target_occasion) AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=job.target_occasion AND unit=job.target_unit AND organization=job.organization)) THEN
   RAISE insufficient_privilege USING MESSAGE='copy scope changed'; END IF;
 END IF;
 RETURN jsonb_build_object('commandId',job.command_id,'unitId',job.source_unit,'targetUnitId',job.target_unit,
  'occasionId',job.target_occasion,'sourceOccasionId',job.source_occasion,'action',job.action,'state',job.state,'media',job.media,
  'assetDisposition',CASE WHEN job.action='delete' THEN 'detached-retained' WHEN job.state='pending' THEN 'copy-pending' ELSE 'copied' END);
END $$;


ALTER FUNCTION public.get_occasion_media_job(p_command_id uuid) OWNER TO postgres;

--
-- Name: get_occasion_membership_for_edit_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_membership_for_edit_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT(auth.uid()=p_user OR public.can_manage_occasion_participants(p_occasion)) THEN RAISE insufficient_privilege USING MESSAGE='profile owner or manager required'; END IF;
 RETURN (SELECT to_jsonb(ou)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) FROM public.occasion_users ou LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text WHERE ou.occasion=p_occasion AND ou."user"=p_user AND (p_user=auth.uid() OR public.occasion_member_visible_internal(p_occasion,p_user)));
END $$;


