--
-- Name: get_occasion_sale_forms_internal(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_sale_forms_internal(p_occasion bigint, p_at timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 -- LATERAL aliases can be expanded once for every JSON field/CASE reference.
 -- Keep each form's configuration and capacity mode as one request-local value.
 WITH form_data AS MATERIALIZED (
  SELECT f.*,public.get_effective_form_data(f.id) AS effective_data
  FROM public.forms f WHERE f.occasion=p_occasion
 ), form_modes AS MATERIALIZED (
  SELECT f.*,public.get_form_registration_mode_internal(f.id,
   greatest(p_at,nullif(coalesce(f.effective_data#>>'{schedule,start_time}',
    f.effective_data->>'start_time'),'')::timestamptz)) AS registration_mode
  FROM form_data f
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'id',f.id,'is_open',f.is_open,
  'has_tickets',EXISTS(SELECT 1 FROM public.form_fields ticket_field WHERE ticket_field.form=f.id AND ticket_field.type='ticket' AND NOT coalesce(ticket_field.is_hidden,false)),
  'is_preparation',coalesce((f.effective_data#>>'{schedule,sale_preparation}')::boolean,false),
  'start_time',nullif(coalesce(f.effective_data#>>'{schedule,start_time}',f.effective_data->>'start_time'),''),
  'end_time',nullif(coalesce(f.effective_data#>>'{schedule,end_time}',f.effective_data->>'end_time'),''),
  'enable_countdown',coalesce((coalesce(f.effective_data#>>'{schedule,enable_countdown}',f.effective_data->>'enable_countdown'))::boolean,false),
  'registration_mode',f.registration_mode,
  'has_availability',CASE
   WHEN f.registration_mode='blueprint' THEN EXISTS (
    -- Resolve the form's small offer before running expensive inventory checks.
    -- Without this boundary a hash join can evaluate every system product.
    WITH offered_products AS MATERIALIZED (
     SELECT p.id,offered.has_capacity
     FROM public.blueprint_form_products_internal(f.id) offered
     JOIN eshop.products p ON p.id=offered.product
     WHERE NOT p.is_hidden
    )
    SELECT 1 FROM offered_products p
    WHERE public.is_product_dynamically_available(p.id)
    AND (public.blueprint_product_availability_internal(p.id)->>'available')::bigint>0
    AND (p.has_capacity OR EXISTS (
     SELECT 1 FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots s ON s.id=sb.spot
     WHERE sb.blueprint=f.blueprint AND s.product=p.id AND NOT sb.blocked
      AND NOT EXISTS (
       SELECT 1 FROM unnest(public.blueprint_selection_unit_spots_internal(s.id)) member(id)
       JOIN eshop.spots occupied ON occupied.id=member.id
       WHERE occupied.order_product_ticket IS NOT NULL OR occupied.state='black'
        OR (occupied.secret IS NOT NULL AND occupied.secret_expiration_time>p_at))
    )))
   WHEN f.registration_mode='regular' THEN NOT EXISTS (
    WITH required_fields AS MATERIALIZED (
     SELECT ff.product_type FROM public.form_fields ff
     JOIN eshop.product_types pt ON pt.id=ff.product_type
     WHERE ff.form=f.id AND NOT coalesce(ff.is_hidden,false)
     AND (pt.type='spot' OR ff.is_required)
    )
    SELECT 1 FROM required_fields ff WHERE NOT EXISTS (
      WITH field_products AS MATERIALIZED (
       SELECT p.id FROM eshop.products p
       WHERE p.product_type=ff.product_type AND NOT p.is_hidden
      )
      SELECT 1 FROM field_products p WHERE public.is_product_dynamically_available(p.id)
      AND (public.blueprint_product_availability_internal(p.id)->>'available')::bigint>0))
   ELSE f.registration_mode='waitlist' END
 ) ORDER BY f.id),'[]'::jsonb)
 FROM form_modes f;
$$;


ALTER FUNCTION public.get_occasion_sale_forms_internal(p_occasion bigint, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: get_occasion_seo_data(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_seo_data(p_link_slug text) RETURNS json
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT coalesce(public.get_occasion_seo_data(p_link_slug, 'form'), public.get_occasion_seo_data(p_link_slug, 'event'));
$$;


ALTER FUNCTION public.get_occasion_seo_data(p_link_slug text) OWNER TO postgres;

--
-- Name: get_occasion_seo_data(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_seo_data(p_link_slug text, p_route_type text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_occasion_id bigint; v_form public.forms%ROWTYPE; v_result json;
BEGIN
    IF p_route_type NOT IN ('form', 'event') OR p_route_type IS NULL THEN
        RAISE invalid_parameter_value USING MESSAGE = 'Invalid public SEO route';
    END IF;
    IF p_route_type = 'form' THEN
        SELECT * INTO v_form FROM public.forms
        WHERE id = public.resolve_form_link_internal(p_link_slug);
        v_occasion_id := v_form.occasion;
    ELSE
        v_occasion_id := public.resolve_occasion_link_internal(p_link_slug);
    END IF;
    SELECT json_build_object(
        'title', o.title, 'description', o.description,
        'form_title', v_form.title, 'form_description', v_form.header,
        'form_link', v_form.link, 'occasion_link', o.link,
        'start_time', o.start_time, 'end_time', o.end_time,
        'image', o.data->>'image', 'org_title', org.title, 'unit_title', u.title
    ) INTO v_result
    FROM public.occasions o
    JOIN public.organizations org ON org.id = o.organization
    LEFT JOIN public.units u ON u.id = o.unit
    WHERE o.id = v_occasion_id;
    RETURN v_result;
END $$;


ALTER FUNCTION public.get_occasion_seo_data(p_link_slug text, p_route_type text) OWNER TO postgres;

--
-- Name: get_occasion_seo_data(text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_seo_data(p_link_slug text, p_route_type text, p_organization_id bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_id bigint; v_owner bigint; v_source text;
BEGIN
  IF p_route_type = 'form' THEN
    SELECT occasion INTO v_id FROM public.forms WHERE id=public.resolve_form_link_internal(p_link_slug);
  ELSIF p_route_type = 'event' THEN
    v_id:=public.resolve_occasion_link_internal(p_link_slug);
  ELSE
    RAISE invalid_parameter_value USING MESSAGE='Invalid public SEO route';
  END IF;
  SELECT o.organization,c.source_name INTO v_owner,v_source
  FROM public.occasions o LEFT JOIN public.external_occasions_cache c ON c.link=o.link WHERE o.id=v_id;
  IF p_organization_id IS NULL OR v_owner IS NULL OR
     NOT public.catalog_includes_occasion_internal(p_organization_id,v_owner,v_source) THEN RETURN NULL; END IF;
  RETURN public.get_occasion_seo_data(p_link_slug,p_route_type);
END $$;


ALTER FUNCTION public.get_occasion_seo_data(p_link_slug text, p_route_type text, p_organization_id bigint) OWNER TO postgres;

--
-- Name: get_occasion_setup_bank_accounts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_bank_accounts(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 RETURN jsonb_build_object('canManage',public.get_is_manager_on_unit(d.unit),'accounts',coalesce((
  SELECT jsonb_agg(jsonb_build_object('id',b.id,'title',b.title,
    'display',coalesce(nullif(b.account_number_human_readable,''),b.account_number),
    'currencies',b.supported_currencies,'priority',u.priority,'type',b.type,
    'bank_sync',(SELECT jsonb_build_object('state',c.state,'mode',c.mode)
      FROM eshop.bank_sync_connections c WHERE c.bank_account_id=b.id),
    'bank_sync_warning',public.bank_sync_warning(b.id),
    'fingerprint',public.occasion_setup_bank_fingerprint_internal(b.id)) ORDER BY u.priority,b.id)
  FROM eshop.unit_bank_accounts u JOIN eshop.bank_accounts b ON b.id=u.bank_account
  WHERE u.unit=d.unit AND b.type<>'CASH'),'[]'::jsonb));
END $$;


ALTER FUNCTION public.get_occasion_setup_bank_accounts(p_id uuid) OWNER TO postgres;

--
-- Name: get_occasion_setup_blueprint_resources(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_blueprint_resources(p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts; doc jsonb; source_id bigint; resources jsonb; source_resources jsonb;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_draft;
 IF d.id IS NULL OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 source_id:=(d.data->>'sourceId')::bigint;
 IF source_id IS NOT NULL AND (NOT public.can_copy_occasion_source(source_id) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=source_id AND organization=d.organization)) THEN RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
 doc:=coalesce(d.data#>'{blueprintLayoutDraft,layout}',jsonb_build_object(
  'schemaVersion',2,'symbolSetVersion',1,'canvas',jsonb_build_object('x',0,'y',0,'width',2400,'height',1600,'fill','#FFFFFFFF'),
  'styles','{}'::jsonb,'seatingDefaults','{}'::jsonb,'textPolicy',jsonb_build_object('language','und','direction','auto'),
  'nodes','[]'::jsonb,'sections','[]'::jsonb,'selectionUnits','[]'::jsonb,'attachments','[]'::jsonb,'presets','[]'::jsonb));
 IF doc->>'schemaVersion' IS DISTINCT FROM '2' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_MIGRATION_REQUIRED';END IF;
  resources:=public.blueprint_canonical_text_resources_internal(doc,NULL,p_draft,true);
  source_resources:=CASE WHEN source_id IS NULL THEN '{}'::jsonb ELSE public.blueprint_canonical_text_resources_internal(doc,source_id,NULL,true) END;
  resources:=resources||jsonb_build_object(
   'fontFamilies',coalesce(source_resources->'fontFamilies','{}')||(resources->'fontFamilies'),
   'textLayouts',coalesce(source_resources->'textLayouts','{}')||(resources->'textLayouts'),
   'numberSymbols',coalesce(source_resources->'numberSymbols','{}')||(resources->'numberSymbols'),
   'assets',public.blueprint_canonical_asset_resources_internal(doc,source_id,NULL)||public.blueprint_canonical_asset_resources_internal(doc,NULL,d.unit));
  RETURN public.bound_document_data_v1(jsonb_build_object('resources',resources));
END $$;


ALTER FUNCTION public.get_occasion_setup_blueprint_resources(p_draft uuid) OWNER TO postgres;

--
-- Name: get_occasion_setup_communication(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_communication(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts; u public.units; manager boolean; version bigint; snapshot record;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 SELECT row_u,coalesce(v.version,0) AS aggregate_version INTO snapshot FROM public.units row_u
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='unit' AND v.scope_type='unit'
   AND v.scope_id=row_u.id AND v.aggregate_id=row_u.id::text WHERE row_u.id=d.unit;
 u:=snapshot.row_u; version:=snapshot.aggregate_version;
 manager:=public.get_is_manager_on_unit(d.unit);
 RETURN jsonb_build_object('canManage',manager,
  'firstEvent',NOT EXISTS(SELECT 1 FROM public.occasions WHERE unit=d.unit),
  'defaults',jsonb_build_object('replyTo',nullif(btrim(u.data->>'reply_to'),''),
    'tone',CASE WHEN u.data->>'communication_tone'='informal' THEN 'informal' ELSE 'formal' END,
    'remindersEnabled',coalesce((u.data->>'is_reminder_enabled')::boolean,true),
    'leadSeconds',coalesce((u.data->>'reminder_interval_seconds')::bigint,86400)),
  'unit',CASE WHEN manager THEN jsonb_build_object('id',u.id,'title',u.title,'data',u.data,'aggregate_version',coalesce(version,0)) ELSE NULL END);
END $$;


ALTER FUNCTION public.get_occasion_setup_communication(p_id uuid) OWNER TO postgres;

--
-- Name: get_occasion_setup_draft(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_draft(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
  IF NOT FOUND OR auth.uid() IS NULL OR public.can_create_occasion(d.unit) IS NOT TRUE THEN
    RAISE insufficient_privilege USING MESSAGE='Draft access denied';
  END IF;
  RETURN jsonb_set(to_jsonb(d),'{data}',public.normalize_setup_payments_internal(d.data));
END $$;


