--
-- Name: get_occasion_setup_drafts(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_drafts(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(to_jsonb(d) ORDER BY updated_at DESC)
    FROM public.occasion_setup_drafts d WHERE unit = p_unit AND NOT (d.data ? 'finalizedOccasion')), '[]'::jsonb);
END $$;


ALTER FUNCTION public.get_occasion_setup_drafts(p_unit bigint) OWNER TO postgres;

--
-- Name: get_occasion_setup_email_preview(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_email_preview(p_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_occasion_setup_email_preview(p_id,p_expected_revision,'order_confirmation',NULL,NULL);
$$;


ALTER FUNCTION public.get_occasion_setup_email_preview(p_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: get_occasion_setup_email_preview(uuid, bigint, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_email_preview(p_id uuid, p_expected_revision bigint, p_message_type text, p_occasion bigint, p_delivery_mode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE d public.occasion_setup_drafts; unit_data jsonb; resolved jsonb; copied jsonb;
 email_banner text; inherited_banner text; source_id bigint; tone text; reply_to text;
 payment_metadata jsonb; payment_policy jsonb; payment_method text; payment_info jsonb; payment_duration bigint;
 o public.occasions; selected_code text; feature jsonb; ticket_catalog jsonb; template_code text; templates jsonb:='[]'; overrides jsonb; effective jsonb;
BEGIN
 IF p_message_type IS NULL OR p_message_type NOT IN ('order_confirmation','order_tickets') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid preview message type'; END IF;
 selected_code:=CASE p_message_type WHEN 'order_tickets' THEN 'TICKET_ORDER_PAYMENT_DONE' ELSE 'TICKET_ORDER_CONFIRMATION' END;
 IF p_occasion IS NOT NULL THEN
  IF p_id IS NOT NULL OR auth.uid() IS NULL OR public.can_read_ticket_layout(p_occasion) IS NOT TRUE THEN
   RAISE insufficient_privilege USING MESSAGE='Occasion preview denied'; END IF;
  SELECT * INTO o FROM public.occasions WHERE id=p_occasion;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='Occasion preview denied'; END IF;
  d.unit:=o.unit;d.organization:=o.organization;
  SELECT f INTO feature FROM jsonb_array_elements(o.features) f WHERE f->>'code'='ticket';
  d.data:=jsonb_build_object('title',o.title,'ticketDraft',feature,'communicationTone','inherit',
    'replyToMode',CASE WHEN nullif(o.data->>'reply_to','') IS NULL THEN 'inherit' ELSE 'custom' END,'replyToEmail',o.data->>'reply_to');
  ticket_catalog:=public.get_products_and_types(p_occasion)::jsonb;
 ELSE
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR
   public.can_create_occasion(d.unit) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF d.revision IS DISTINCT FROM p_expected_revision THEN
  RAISE SQLSTATE 'PT409' USING MESSAGE='Draft revision conflict'; END IF;
 IF d.data ? 'finalizedOccasion' THEN RAISE invalid_parameter_value USING MESSAGE='Draft is finalized'; END IF;
 END IF;
 SELECT data INTO unit_data FROM public.units WHERE id=d.unit AND organization=d.organization;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='Draft hierarchy denied'; END IF;
 email_banner:=CASE WHEN p_occasion IS NULL THEN d.data->>'emailBanner' END;
 IF nullif(email_banner,'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.images WHERE link=email_banner AND unit=d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft email banner access denied'; END IF;
 SELECT coalesce(unit_data->>'email_banner',data->>'email_banner') INTO inherited_banner FROM public.organizations WHERE id=d.organization;
 tone:=coalesce(nullif(nullif(d.data->>'communicationTone',''),'inherit'),CASE WHEN unit_data->>'communication_tone'='informal' THEN 'informal' ELSE 'formal' END);
 IF tone NOT IN ('formal','informal') THEN RAISE invalid_parameter_value USING MESSAGE='Invalid tone'; END IF;
 IF coalesce(d.data->>'replyToMode','inherit') NOT IN ('inherit','custom') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid reply mode'; END IF;
 reply_to:=CASE WHEN d.data->>'replyToMode'='custom' THEN btrim(d.data->>'replyToEmail') ELSE unit_data->>'reply_to' END;
 IF d.data->>'replyToMode'='custom' AND nullif(reply_to,'') IS NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid reply address'; END IF;
 IF reply_to IS NOT NULL AND (length(reply_to)>254 OR reply_to !~ '^[^[:space:]<>@]+@[^[:space:]<>@]+[.][^[:space:]<>@]+$') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid reply address'; END IF;
 -- Finalization copies occasion templates only. An inherited source template or
 -- source wrapper must not replace the destination hierarchy in this preview.
 IF coalesce((d.data->>'copyEmails')::boolean,false) AND nullif(d.data->>'sourceId','') IS NOT NULL THEN
  source_id:=(d.data->>'sourceId')::bigint;
  IF NOT public.can_copy_occasion_source(source_id) OR NOT EXISTS(
   SELECT 1 FROM public.occasions WHERE id=source_id AND organization=d.organization) THEN
   RAISE insufficient_privilege USING MESSAGE='Source access denied'; END IF;
 END IF;
 overrides:=public.validate_setup_email_templates_internal(d.data->'emailTemplateOverrides');
 FOREACH template_code IN ARRAY ARRAY['TICKET_ORDER_CONFIRMATION','TICKET_ORDER_PAYMENT_DONE','TICKET_ORDER_REMINDER','TICKET_ORDER_STORNO','TICKET_ORDER_UPDATE'] LOOP
  effective:=public.get_email_template_and_wrapper(template_code,jsonb_build_object('unit',d.unit,'organization',d.organization,'occasion',p_occasion));
  IF source_id IS NOT NULL THEN
   SELECT to_jsonb(t) INTO copied FROM public.email_templates t
   WHERE t.occasion=source_id AND t.code=template_code ORDER BY t.id DESC LIMIT 1;
   IF copied IS NOT NULL THEN effective:=jsonb_set(effective,'{template}',copied); END IF;
  END IF;
  IF overrides ? template_code THEN
   effective:=jsonb_set(effective,'{template}',coalesce(effective->'template','{}')||(overrides->template_code));
  END IF;
  templates:=templates||jsonb_build_array(jsonb_build_object('code',template_code,
   'template',effective->'template','customized',overrides ? template_code));
  IF template_code=selected_code THEN resolved:=effective; END IF;
 END LOOP;
 IF email_banner IS NOT NULL THEN
  resolved:=jsonb_set(resolved,'{wrapper}',jsonb_build_object('html',
    public.email_banner_wrapper_internal(email_banner,d.data->>'title')));
 END IF;
 feature:=coalesce(feature,d.data->'ticketDraft');
 IF p_delivery_mode IS NOT NULL THEN PERFORM public.ticket_delivery_mode(jsonb_build_object('delivery_mode',p_delivery_mode)); END IF;
 IF ticket_catalog IS NULL THEN
  SELECT jsonb_build_object('product_types',coalesce(jsonb_agg(t||jsonb_build_object('occasion',0)),'[]'::jsonb),
    'products',coalesce((SELECT jsonb_agg(p||jsonb_build_object('product_type',(pt->>'id')::bigint))
       FROM jsonb_array_elements(coalesce(d.data#>'{formDraft,fields}','[]')) fld
       CROSS JOIN LATERAL (SELECT fld->'product_type_data' pt) x
       CROSS JOIN LATERAL jsonb_array_elements(coalesce(pt->'products','[]')) p),'[]'::jsonb)) INTO ticket_catalog
  FROM (SELECT fld->'product_type_data' t FROM jsonb_array_elements(coalesce(d.data#>'{formDraft,fields}','[]')) fld WHERE jsonb_typeof(fld->'product_type_data')='object') x;
 END IF;
 -- Preview facts use the same SQL policy owner as real checkout. No draft
 -- preview creates an order, reference or payment attempt.
 payment_metadata:=public.normalize_form_metadata_internal(d.data#>'{formDraft,data}');
 payment_metadata:=payment_metadata||jsonb_build_object('payments',public.normalize_setup_payments_internal(d.data)->'payments');
 payment_method:=CASE WHEN payment_metadata#>'{payments,cashEnabled}'='true'::jsonb THEN 'cash' ELSE 'bank' END;
 payment_duration:=coalesce(nullif(d.data#>>'{formDraft,deadline_duration_seconds}','')::numeric,
   nullif(d.data->>'deadline','')::numeric*86400)::bigint;
 payment_policy:=public.resolve_payment_policy_internal(payment_metadata,payment_duration,
   (SELECT elem FROM jsonb_array_elements(coalesce(o.features,'[]')) elem WHERE elem->>'code'='form'),payment_method);
 SELECT jsonb_build_object('account_number',b.account_number,'account_number_human_readable',coalesce(nullif(b.account_number_human_readable,''),b.account_number))
 INTO payment_info FROM eshop.unit_bank_accounts u JOIN eshop.bank_accounts b ON b.id=u.bank_account
 WHERE u.unit=d.unit AND b.id::text=d.data->>'bankAccountId' AND b.type<>'CASH' AND payment_method='bank';
 payment_info:=coalesce(payment_info,'{}')||jsonb_build_object('payment_method',payment_method,
   'data',jsonb_build_object('payment_policy',payment_policy-'durationSeconds'),
   'deadline',CASE WHEN payment_policy->>'mode'='custom' THEN statement_timestamp()+make_interval(secs=>(payment_policy->>'durationSeconds')::bigint) END);
 RETURN jsonb_build_object('messageType',p_message_type,'deliveryMode',coalesce(p_delivery_mode,public.ticket_delivery_mode(feature)),
  'ticketFeature',feature,'ticketCatalog',ticket_catalog,'occasion',CASE WHEN p_occasion IS NOT NULL THEN to_jsonb(o) ELSE jsonb_build_object('id',0,'title',d.data->>'title','start_time',d.data->>'start','end_time',d.data->>'end','data',jsonb_build_object('place_name',d.data->>'placeName')) END,
  'revision' ,d.revision,'title',coalesce(nullif(d.data->>'title',''),'Ukázková událost'),
  'tone',tone,'replyTo',reply_to,'resolved',resolved,
  'emailBanner',email_banner,'inheritedEmailBanner',inherited_banner,
  'emailTemplates',templates,'emailScope',jsonb_build_object(
   'unit',jsonb_build_object('id',d.unit,'title',(SELECT title FROM public.units WHERE id=d.unit)),
   'organization',jsonb_build_object('id',d.organization,'title',(SELECT title FROM public.organizations WHERE id=d.organization))),
  'deadlineDurationSeconds',payment_policy->'durationSeconds',
  'paymentInfo',payment_info,
  'ticketsEnabled',coalesce((feature->>'is_enabled')::boolean,p_occasion IS NULL) AND (p_occasion IS NOT NULL OR coalesce((d.data->>'formEnabled')::boolean,true) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(d.data#>'{formDraft,fields}','[]')) f WHERE f->>'type'='ticket' AND NOT coalesce((f->>'is_hidden')::boolean,false))),
  'sampleProducts',coalesce((SELECT jsonb_agg(p) FROM jsonb_array_elements(coalesce(d.data#>'{formDraft,fields}','[]')) f CROSS JOIN LATERAL (SELECT p FROM jsonb_array_elements(coalesce(f#>'{product_type_data,products}','[]')) p WHERE NOT coalesce((p->>'is_hidden')::boolean,false) LIMIT 1) products(p) WHERE NOT coalesce((f->>'is_hidden')::boolean,false)),'[]'::jsonb),
  'has_custom_template',coalesce((overrides ? selected_code) OR (resolved->'template'->>'occasion') IS NOT NULL
    OR (resolved->'template'->>'unit') IS NOT NULL OR (resolved->'template'->>'organization') IS NOT NULL,false));
END $_$;


ALTER FUNCTION public.get_occasion_setup_email_preview(p_id uuid, p_expected_revision bigint, p_message_type text, p_occasion bigint, p_delivery_mode text) OWNER TO postgres;

--
-- Name: get_occasion_setup_source(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_source(p_unit bigint, p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit)
  OR NOT public.can_copy_occasion_source(p_occasion)
  OR NOT EXISTS(SELECT 1 FROM public.occasions o JOIN public.units u ON u.organization=o.organization
    WHERE o.id=p_occasion AND u.id=p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Source access denied'; END IF;
 RETURN public.occasion_setup_source_internal(p_occasion);
END $$;


ALTER FUNCTION public.get_occasion_setup_source(p_unit bigint, p_occasion bigint) OWNER TO postgres;

--
-- Name: get_occasion_setup_source_list(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_source_list(p_unit bigint, p_source_unit bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Source access denied'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.units target JOIN public.units source ON source.organization=target.organization
   WHERE target.id=p_unit AND (p_source_unit IS NULL OR source.id=p_source_unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='Source tenant denied'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('occasion',jsonb_build_object(
  'id',o.id,'title',o.title,'start_time',o.start_time,'end_time',o.end_time),
  'forms',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'title',f.title)) FROM public.forms f WHERE f.occasion=o.id),'[]'::jsonb),
  'blueprints',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'title',b.title)) FROM eshop.blueprints b WHERE b.occasion=o.id),'[]'::jsonb)) ORDER BY o.start_time DESC,o.id DESC)
  FROM public.occasions o WHERE o.organization=(SELECT organization FROM public.units WHERE id=p_unit) AND (p_source_unit IS NULL OR o.unit=p_source_unit) AND public.can_copy_occasion_source(o.id)),'[]');
END $$;


ALTER FUNCTION public.get_occasion_setup_source_list(p_unit bigint, p_source_unit bigint) OWNER TO postgres;

--
-- Name: get_occasion_setup_sources(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_setup_sources(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Source access denied'; END IF;
 RETURN coalesce((SELECT jsonb_agg(public.occasion_setup_source_internal(o.id) ORDER BY o.start_time DESC,o.id DESC)
  FROM public.occasions o WHERE o.unit=p_unit),'[]');
END $$;


ALTER FUNCTION public.get_occasion_setup_sources(p_unit bigint) OWNER TO postgres;

--
-- Name: get_occasion_sign_in_email_statuses(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_sign_in_email_statuses(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.can_read_occasion_directory(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  WITH evidence AS (
    SELECT le.recipient_user AS "user",le.created_at AS sent_at
    FROM public.log_emails le
    JOIN public.email_templates et ON et.id::text = le.template
    WHERE le.occasion = p_occasion
      AND le.recipient_user IS NOT NULL
      AND et.code = 'SIGN_IN_CODE'
    UNION ALL
    SELECT m.recipient_user,m.accepted_at FROM public.email_messages m
    WHERE m.occasion=p_occasion AND (m.message_kind='sign_in' OR (m.message_kind='custom' AND m.code='TEAM_ACCESS_NOTICE'))
      AND m.recipient_user IS NOT NULL AND m.accepted_at IS NOT NULL
    UNION ALL
    SELECT i.accepted_by,m.accepted_at FROM public.occasion_team_invitations i
    JOIN public.email_messages m ON m.message_id=i.message_id
    WHERE i.occasion=p_occasion AND i.accepted_by IS NOT NULL AND m.accepted_at IS NOT NULL
  ), accepted AS (
    SELECT "user",count(*)::integer send_count,min(sent_at) first_sent_at,max(sent_at) last_sent_at FROM evidence GROUP BY "user"
  )
  SELECT COALESCE(
    jsonb_agg(to_jsonb(accepted) ORDER BY accepted."user"),
    '[]'::jsonb
  )
  INTO v_result
  FROM accepted;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_occasion_sign_in_email_statuses(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_occasion_team_invitation(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_team_invitation(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RETURN NULL; END IF;
 SELECT jsonb_build_object('email',i.email,'title',o.title,'unitTitle',u.title,'organization',i.organization,
  'link',o.link,'role',i.role,'accepted',i.accepted_at IS NOT NULL,'existingAccount',EXISTS(SELECT 1 FROM public.user_info ui
    WHERE ui.organization=i.organization AND lower(btrim(ui.email_readonly))=i.email)) INTO result
 FROM public.occasion_team_invitations i JOIN public.occasions o ON o.id=i.occasion AND o.unit=i.unit AND o.organization=i.organization
 JOIN public.units u ON u.id=i.unit
 WHERE i.token_hash=encode(extensions.digest(p_token,'sha256'),'hex') AND i.expires_at>now()
 AND NOT public.is_demo_occasion(i.occasion)
 AND EXISTS(SELECT 1 FROM public.unit_users uu WHERE uu.unit=i.unit AND uu."user"=i.created_by AND uu.is_manager);
 RETURN result;
END $_$;


ALTER FUNCTION public.get_occasion_team_invitation(p_token text) OWNER TO postgres;

--
-- Name: get_occasion_user_command_data_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_user_command_data_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT to_jsonb(ou)||jsonb_build_object('profile',jsonb_build_object(
    'id',ui.id,'email',ui.email_readonly,'name',ui.name,'surname',ui.surname,
    'sex',ui.sex,'phone',ui.phone,'birthDate',ui.birth_date,'data',ui.data))
  FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user"
  WHERE ou.occasion=p_occasion AND ou."user"=p_user;
$$;


ALTER FUNCTION public.get_occasion_user_command_data_v1(p_occasion bigint, p_user uuid) OWNER TO postgres;

--
-- Name: get_occasion_users_editor_bundle_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_users_editor_bundle_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb; v_users jsonb;
BEGIN
  v_result:=public.get_occasion_users_for_edit(p_occasion)::jsonb;
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN RETURN v_result; END IF;
  WITH companion_owners AS (
    SELECT uc.companion,uc."user" owner_id,uc.origin,
      concat_ws(' ',owner_info.name,owner_info.surname) owner_name
    FROM public.user_companions uc
    JOIN public.user_info owner_info ON owner_info.id=uc."user"
    WHERE uc.occasion=p_occasion AND public.occasion_member_visible_internal(p_occasion,owner_info.id)
  )
  SELECT COALESCE(jsonb_agg(row.value||jsonb_strip_nulls(jsonb_build_object(
      'aggregate_version',COALESCE(v.version,0),
      'companion_owner_id',owners.owner_id,
      'companion_owner_name',owners.owner_name,
      'companion_origin',owners.origin))),'[]'::jsonb)
  INTO v_users
  FROM jsonb_array_elements(v_result#>'{data,occasion_users}') row
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=row.value->>'user'
  LEFT JOIN companion_owners owners ON owners.companion=(row.value->>'user')::uuid;
  RETURN jsonb_set(v_result,'{data,occasion_users}',v_users);
END $$;


ALTER FUNCTION public.get_occasion_users_editor_bundle_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_occasion_users_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_users_for_edit(p_occasion_id bigint) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
  v_users jsonb;
BEGIN
  v_result := public.get_occasion_users_for_edit_invitation_base_v1(
    p_occasion_id
  )::jsonb;
  IF COALESCE((v_result->>'code')::integer, 500) <> 200 THEN
    RETURN v_result::json;
  END IF;

  WITH accepted AS (
    SELECT (entry->>'user')::uuid AS "user" FROM jsonb_array_elements(public.get_occasion_sign_in_email_statuses(p_occasion_id)) entry
  )
  SELECT COALESCE(jsonb_agg(
    row.value || jsonb_build_object(
      'data',
      (CASE WHEN jsonb_typeof(row.value->'data') = 'object'
        THEN row.value->'data' ELSE '{}'::jsonb END - 'is_invited'::text)
      || jsonb_build_object('is_invited', accepted."user" IS NOT NULL)
    )
  ), '[]'::jsonb)
  INTO v_users
  FROM jsonb_array_elements(v_result #> '{data,occasion_users}') row
  LEFT JOIN accepted ON accepted."user" = (row.value->>'user')::uuid;

  RETURN jsonb_set(v_result, '{data,occasion_users}', v_users)::json;
END;
$$;


ALTER FUNCTION public.get_occasion_users_for_edit(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_occasion_users_for_edit_internal_companion_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_users_for_edit_internal_companion_v1(p_occasion_id bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    users_data JSON;
    forms_data JSON;
    services_data JSONB;
    org_id BIGINT;
BEGIN
    -- 0. Retrieve the Organization ID
    -- We need this to check against the organization_users table later
    SELECT organization INTO org_id
    FROM public.occasions
    WHERE id = p_occasion_id;

    -- Authorization check: Ensure the user has editor rights for the occasion.
    IF NOT public.can_read_occasion_directory(p_occasion_id) THEN
        RETURN json_build_object('code', 403, 'message', 'User is not authorized to view this occasion''s data');
    END IF;

    -- 1. Get all users associated with the occasion. Resolve order and group
    -- metadata once for the whole occasion instead of running correlated
    -- subqueries for every user.
    WITH visible_users AS MATERIALIZED (
        SELECT ou.*
        FROM public.occasion_users ou
        LEFT JOIN public.organization_users org_u
          ON org_u."user" = ou."user"
         AND org_u.organization = org_id
        WHERE ou.occasion = p_occasion_id
          AND org_u.is_hidden IS NOT TRUE
    ),
    order_info AS (
        SELECT DISTINCT ON (opt.ticket)
            opt.ticket,
            o.data->>'form' AS form_id,
            o.created_at
        FROM visible_users vu
        JOIN eshop.order_product_ticket opt ON opt.ticket = vu.ticket
        JOIN eshop.orders o ON o.id = opt."order"
        ORDER BY opt.ticket, opt.id
    ),
    standard_groups AS (
        SELECT
            ug."user",
            string_agg(ugi.title, ', ' ORDER BY ugi.title) AS titles
        FROM visible_users vu
        JOIN public.user_groups ug ON ug."user" = vu."user"
        JOIN public.user_group_info ugi ON ugi.id = ug."group"
        WHERE ugi.occasion = p_occasion_id
          AND ugi.type IS NULL
        GROUP BY ug."user"
    )
    SELECT json_agg(row_to_json(user_row))
    INTO users_data
    FROM (
        SELECT
            vu.occasion,
            vu.created_at,
            vu."user",
            vu.is_editor,
            vu.is_manager,
            vu.is_approved,
            vu.is_approver,
            -- Occasion data remains authoritative for event-specific fields.
            -- Overlay only the dedicated global profile columns; user_info.data
            -- also contains historical occasion fields and must not leak across
            -- events. A LEFT JOIN preserves legacy occasion rows without a
            -- matching user_info record.
            COALESCE(vu.data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
                'email', ui.email_readonly,
                'name', ui.name,
                'surname', ui.surname,
                'sex', ui.sex,
                'phone', COALESCE(ui.phone, ui.data->>'phone'),
                'birthDate', COALESCE(
                    to_char(ui.birth_date, 'YYYY-MM-DD'),
                    ui.data->>'birthDate'
                )
            )) AS data,
            vu.role,
            vu.services,
            vu.is_editor_view,
            vu.is_editor_order,
            vu.is_editor_order_view,
            vu.is_cleaning_crew,
            vu.is_cleaning_blocked,
            vu.ticket,
            order_info.form_id,
            order_info.created_at AS order_created_at,
            au.last_sign_in_at,
            standard_groups.titles AS group_title
        FROM visible_users vu
        LEFT JOIN public.user_info ui ON ui.id = vu."user"
        LEFT JOIN auth.users au ON au.id = vu."user"
        LEFT JOIN order_info ON order_info.ticket = vu.ticket
        LEFT JOIN standard_groups ON standard_groups."user" = vu."user"
    ) user_row;

    -- 2. Get all forms associated with the occasion, selecting only the specified fields.
    SELECT json_agg(
        json_build_object(
            'key', f.key,
            'type', f.type,
            'id', f.id,
            'title', f.title,
            'link', f.link
        )
    )
    INTO forms_data
    FROM public.forms f
    WHERE f.occasion = p_occasion_id;

    -- 3. Return the service catalog in the same RPC response. Both the Users
    -- and Stay tabs need these options to render editable accommodation/food
    -- columns; keeping them here avoids extra requests and PostgREST's 1000-row
    -- cap on direct occasion_users queries.
    SELECT catalog.services || jsonb_build_object(
        'accommodation',
        COALESCE((
            SELECT jsonb_agg(
                service_item.item || jsonb_build_object('place_title', p.title)
                ORDER BY service_item.position
            )
            FROM jsonb_array_elements(
                CASE
                    WHEN jsonb_typeof(catalog.services->'accommodation') = 'array'
                        THEN catalog.services->'accommodation'
                    ELSE '[]'::jsonb
                END
            ) WITH ORDINALITY AS service_item(item, position)
            LEFT JOIN public.places p
              ON p.id = CASE
                  WHEN service_item.item->>'reference' ~ '^[0-9]+$'
                      THEN (service_item.item->>'reference')::bigint
                  ELSE NULL
              END
             AND p.occasion = p_occasion_id
        ), '[]'::jsonb)
    )
    INTO services_data
    FROM (
        SELECT CASE
            WHEN jsonb_typeof(o.services) = 'object' THEN o.services
            ELSE '{}'::jsonb
        END AS services
        FROM public.occasions o
        WHERE o.id = p_occasion_id
    ) catalog;

    -- Assemble the final JSON object without reparsing the complete roster as
    -- JSONB. Both the Users and Stay tabs consume this same bundle.
    RETURN json_build_object(
        'code', 200,
        'message', 'Occasion users and forms retrieved successfully.',
        'data', json_build_object(
            'occasion_users', COALESCE(users_data, '[]'::json),
            'forms',          COALESCE(forms_data, '[]'::json),
            'services',       COALESCE(services_data, '{}'::jsonb)
        )
    );
END;
$_$;


ALTER FUNCTION public.get_occasion_users_for_edit_internal_companion_v1(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_occasion_users_for_edit_invitation_base_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_users_for_edit_invitation_base_v1(p_occasion_id bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    users_data JSON;
    forms_data JSON;
    services_data JSONB;
    org_id BIGINT;
BEGIN
    -- 0. Retrieve the Organization ID
    -- We need this to check against the organization_users table later
    SELECT organization INTO org_id
    FROM public.occasions
    WHERE id = p_occasion_id;

    -- Authorization check: Ensure the user has editor rights for the occasion.
    IF NOT public.can_read_occasion_directory(p_occasion_id) THEN
        RETURN json_build_object('code', 403, 'message', 'User is not authorized to view this occasion''s data');
    END IF;

    -- 1. Get all users associated with the occasion. Resolve order and group
    -- metadata once for the whole occasion instead of running correlated
    -- subqueries for every user.
    WITH visible_users AS MATERIALIZED (
        SELECT ou.*
        FROM public.occasion_users ou
        LEFT JOIN public.organization_users org_u
          ON org_u."user" = ou."user"
         AND org_u.organization = org_id
        WHERE ou.occasion = p_occasion_id
          AND org_u.is_hidden IS NOT TRUE
    ),
    order_info AS (
        SELECT DISTINCT ON (opt.ticket)
            opt.ticket,
            o.data->>'form' AS form_id,
            o.created_at
        FROM visible_users vu
        JOIN eshop.order_product_ticket opt ON opt.ticket = vu.ticket
        JOIN eshop.orders o ON o.id = opt."order"
        ORDER BY opt.ticket, opt.id
    ),
    standard_groups AS (
        SELECT
            ug."user",
            string_agg(ugi.title, ', ' ORDER BY ugi.title) AS titles
        FROM visible_users vu
        JOIN public.user_groups ug ON ug."user" = vu."user"
        JOIN public.user_group_info ugi ON ugi.id = ug."group"
        WHERE ugi.occasion = p_occasion_id
          AND ugi.type IS NULL
        GROUP BY ug."user"
    ),
    companion_owners AS (
        SELECT uc.companion, uc."user" AS owner_id, uc.origin,
               concat_ws(' ', owner_info.name, owner_info.surname) AS owner_name
        FROM public.user_companions uc
        JOIN public.user_info owner_info ON owner_info.id = uc."user"
        WHERE uc.occasion = p_occasion_id AND public.occasion_member_visible_internal(p_occasion_id,owner_info.id)
    )
    SELECT json_agg(row_to_json(user_row))
    INTO users_data
    FROM (
        SELECT
            vu.occasion,
            vu.created_at,
            vu."user",
            vu.is_editor,
            vu.is_manager,
            vu.is_approved,
            vu.is_approver,
            -- Occasion data remains authoritative for event-specific fields.
            -- Overlay only the dedicated global profile columns; user_info.data
            -- also contains historical occasion fields and must not leak across
            -- events. A LEFT JOIN preserves legacy occasion rows without a
            -- matching user_info record.
            COALESCE(vu.data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
                'email', ui.email_readonly,
                'name', ui.name,
                'surname', ui.surname,
                'sex', ui.sex,
                'phone', COALESCE(ui.phone, ui.data->>'phone'),
                'birthDate', COALESCE(
                    to_char(ui.birth_date, 'YYYY-MM-DD'),
                    ui.data->>'birthDate'
                )
            )) AS data,
            vu.role,
            vu.services,
            vu.is_editor_view,
            vu.is_editor_order,
            vu.is_editor_order_view,
            vu.is_cleaning_crew,
            vu.is_cleaning_blocked,
            vu.is_receptionist,
            vu.ticket,
            order_info.form_id,
            order_info.created_at AS order_created_at,
            au.last_sign_in_at,
            standard_groups.titles AS group_title,
            companion_owners.owner_id AS companion_owner_id,
            companion_owners.owner_name AS companion_owner_name,
            companion_owners.origin AS companion_origin
        FROM visible_users vu
        LEFT JOIN public.user_info ui ON ui.id = vu."user"
        LEFT JOIN auth.users au ON au.id = vu."user"
        LEFT JOIN order_info ON order_info.ticket = vu.ticket
        LEFT JOIN standard_groups ON standard_groups."user" = vu."user"
        LEFT JOIN companion_owners ON companion_owners.companion = vu."user"
    ) user_row;

    -- 2. Get all forms associated with the occasion, selecting only the specified fields.
    SELECT json_agg(
        json_build_object(
            'key', f.key,
            'type', f.type,
            'id', f.id,
            'title', f.title,
            'link', f.link
        )
    )
    INTO forms_data
    FROM public.forms f
    WHERE f.occasion = p_occasion_id;

    -- 3. Return the service catalog in the same RPC response. Both the Users
    -- and Stay tabs need these options to render editable accommodation/food
    -- columns; keeping them here avoids extra requests and PostgREST's 1000-row
    -- cap on direct occasion_users queries.
    SELECT catalog.services || jsonb_build_object(
        'accommodation',
        COALESCE((
            SELECT jsonb_agg(
                service_item.item || jsonb_build_object('place_title', p.title)
                ORDER BY service_item.position
            )
            FROM jsonb_array_elements(
                CASE
                    WHEN jsonb_typeof(catalog.services->'accommodation') = 'array'
                        THEN catalog.services->'accommodation'
                    ELSE '[]'::jsonb
                END
            ) WITH ORDINALITY AS service_item(item, position)
            LEFT JOIN public.places p
              ON p.id = CASE
                  WHEN service_item.item->>'reference' ~ '^[0-9]+$'
                      THEN (service_item.item->>'reference')::bigint
                  ELSE NULL
              END
             AND p.occasion = p_occasion_id
        ), '[]'::jsonb)
    )
    INTO services_data
    FROM (
        SELECT CASE
            WHEN jsonb_typeof(o.services) = 'object' THEN o.services
            ELSE '{}'::jsonb
        END AS services
        FROM public.occasions o
        WHERE o.id = p_occasion_id
    ) catalog;

    -- Assemble the final JSON object without reparsing the complete roster as
    -- JSONB. Both the Users and Stay tabs consume this same bundle.
    RETURN json_build_object(
        'code', 200,
        'message', 'Occasion users and forms retrieved successfully.',
        'data', json_build_object(
            'occasion_users', COALESCE(users_data, '[]'::json),
            'forms',          COALESCE(forms_data, '[]'::json),
            'services',       COALESCE(services_data, '{}'::jsonb)
        )
    );
END;
$_$;


ALTER FUNCTION public.get_occasion_users_for_edit_invitation_base_v1(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_occasion_users_for_editor(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_occasion_users_for_editor(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    users_data JSONB;
    forms_data JSONB;
BEGIN
    -- Authorization check: Ensure the user has editor rights for the occasion.
    IF NOT public.can_read_occasion_directory(p_occasion_id) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this occasion''s data');
    END IF;

    -- 1. Get all users associated with the occasion.
    -- This query merges the full user_info and occasion_users rows into a single JSON object
    -- for each user, and then adds the form_id and order_created_at from the corresponding order.
    SELECT jsonb_agg(
        to_jsonb(ui) || to_jsonb(ou) ||
        jsonb_build_object(
            'form_id', order_info.form_id,
            'order_created_at', order_info.created_at -- Added order creation date
        )
    )
    INTO users_data
    FROM public.occasion_users ou
    JOIN public.user_info ui ON ou."user" = ui.id
    LEFT JOIN eshop.tickets t ON ou.ticket = t.id
    LEFT JOIN LATERAL (
        SELECT
            o.data->>'form' AS form_id,
            o.created_at AS created_at -- Selecting the order's creation date
        FROM eshop.order_product_ticket opt
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE opt.ticket = t.id
        LIMIT 1
    ) AS order_info ON true
    WHERE ou.occasion = p_occasion_id AND public.occasion_member_visible_internal(p_occasion_id,ui.id);

    -- 2. Get all forms associated with the occasion, selecting only the specified fields.
    SELECT jsonb_agg(
        jsonb_build_object(
            'key', f.key,
            'type', f.type,
            'id', f.id,
            'link', f.link
        )
    )
    INTO forms_data
    FROM public.forms f
    WHERE f.occasion = p_occasion_id;

    -- Assemble the final JSONB object.
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Occasion users and forms retrieved successfully.',
        'data', jsonb_build_object(
            'occasion_users', COALESCE(users_data, '[]'::jsonb),
            'forms',          COALESCE(forms_data, '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION public.get_occasion_users_for_editor(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_operator_access_v1(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_operator_access_v1(p_organization bigint, p_unit bigint DEFAULT NULL::bigint, p_occasion bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info
    WHERE id=auth.uid() AND organization=p_organization) THEN
    RAISE insufficient_privilege USING MESSAGE='operator context unavailable';
  END IF;
  WITH unit_access AS MATERIALIZED (
    SELECT u.id,u.title,
      public.get_is_editor_on_unit(u.id) editor,
      public.get_is_manager_on_unit(u.id) manager,
      public.get_is_editor_view_on_unit(u.id) viewer
    FROM public.units u WHERE u.organization=p_organization
      AND (p_unit IS NULL OR u.id=p_unit)
  ), occasion_access AS MATERIALIZED (
    SELECT o.id,o.title,o.unit,
      public.ticket_layout_rule(true,u.editor) layout_reader
    FROM public.occasions o LEFT JOIN unit_access u ON u.id=o.unit
    WHERE o.organization=p_organization
      AND (p_unit IS NULL OR o.unit=p_unit)
      AND (p_occasion IS NULL OR o.id=p_occasion)
      AND public.operator_occasion_discovery_rule(u.editor,u.manager,u.viewer,
        public.get_is_manager_on_occasion(o.id),public.get_is_editor_on_occasion(o.id),
        public.get_is_editor_view_on_occasion(o.id),public.can_read_orders(o.id))
  ) SELECT jsonb_build_object(
    'units',coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id',u.id,'title',u.title,'canCreateOccasions',
      public.occasion_create_rule(u.manager,u.editor)) ORDER BY u.id)
      FROM unit_access u WHERE public.unit_discovery_rule(u.editor,u.manager,u.viewer)),'[]'::jsonb),
    'occasions',coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id',o.id,'title',o.title,'unitId',o.unit,
      'capabilities',jsonb_build_object('ticket_layouts.read',o.layout_reader)) ORDER BY o.id)
      FROM occasion_access o),'[]'::jsonb)) INTO v_result;
  RETURN v_result;
END $$;


ALTER FUNCTION public.get_operator_access_v1(p_organization bigint, p_unit bigint, p_occasion bigint) OWNER TO postgres;

--
-- Name: get_operator_order_report_v1(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_operator_order_report_v1(p_occasion bigint, p_organization bigint, p_unit bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r jsonb; v_link text;
BEGIN
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit);
 SELECT link INTO v_link FROM public.occasions WHERE id=p_occasion;
 r:=public.get_report_ws(v_link);
 IF (r->>'code')::int<>200 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='order report unavailable'; END IF;
 RETURN jsonb_build_object('occasionId',p_occasion,'report',r->'report',
   'waitingTickets',(SELECT count(*) FROM eshop.tickets WHERE occasion=p_occasion AND state='waitlisted'));
END $$;


ALTER FUNCTION public.get_operator_order_report_v1(p_occasion bigint, p_organization bigint, p_unit bigint) OWNER TO postgres;

--
-- Name: get_operator_order_summaries_v1(bigint, bigint, bigint, integer, bigint, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_operator_order_summaries_v1(p_occasion bigint, p_organization bigint, p_unit bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 25, p_before bigint DEFAULT NULL::bigint, p_state text DEFAULT NULL::text, p_symbol text DEFAULT NULL::text, p_order bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE rows jsonb; v_next bigint;
BEGIN
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR (p_symbol IS NOT NULL AND p_symbol !~ '^[A-Z0-9]{10}$')
   OR (p_state IS NOT NULL AND length(p_state)>40)
   OR (p_order IS NOT NULL AND (p_before IS NOT NULL OR p_state IS NOT NULL OR p_symbol IS NOT NULL OR p_limit<>25)) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid order summary page'; END IF;
 IF p_order IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order unavailable'; END IF;
   RETURN jsonb_build_object('occasionId',p_occasion,'orders',jsonb_build_array(public.operator_order_summary_internal_v1(p_order)),'nextCursor',NULL);
 END IF;
 WITH page AS MATERIALIZED(SELECT id FROM eshop.orders WHERE occasion=p_occasion AND (p_before IS NULL OR id<p_before)
   AND (p_state IS NULL OR state=p_state) AND (p_symbol IS NULL OR order_symbol=p_symbol)
   ORDER BY id DESC LIMIT p_limit+1), visible AS(SELECT id FROM page ORDER BY id DESC LIMIT p_limit)
 SELECT coalesce(jsonb_agg(public.operator_order_summary_internal_v1(id) ORDER BY id DESC),'[]'),
   CASE WHEN p_symbol IS NULL AND (SELECT count(*) FROM page)>p_limit THEN min(id) END INTO rows,v_next FROM visible;
 RETURN jsonb_build_object('occasionId',p_occasion,'orders',rows,'nextCursor',v_next);
END $_$;


ALTER FUNCTION public.get_operator_order_summaries_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_limit integer, p_before bigint, p_state text, p_symbol text, p_order bigint) OWNER TO postgres;

--
-- Name: get_operator_orders_v1(bigint, bigint, bigint, integer, bigint, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_operator_orders_v1(p_occasion bigint, p_organization bigint, p_unit bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 25, p_before bigint DEFAULT NULL::bigint, p_state text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_order bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE rows jsonb; v_next bigint;
BEGIN
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR coalesce(length(p_search),0)>200 THEN RAISE invalid_parameter_value USING MESSAGE='invalid order page'; END IF;
 IF p_order IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order unavailable'; END IF;
   RETURN jsonb_build_object('occasionId',p_occasion,'orders',jsonb_build_array(public.operator_order_snapshot_internal_v1(p_order,true)),'nextCursor',NULL);
 END IF;
 WITH page AS MATERIALIZED(SELECT id FROM eshop.orders WHERE occasion=p_occasion AND (p_before IS NULL OR id<p_before)
   AND (p_state IS NULL OR state=p_state) AND (nullif(p_search,'') IS NULL OR position(lower(p_search) IN lower(concat_ws(' ',order_symbol,data->>'name',data->>'surname',data->>'email')))>0)
   ORDER BY id DESC LIMIT p_limit+1), visible AS(SELECT id FROM page ORDER BY id DESC LIMIT p_limit)
 SELECT coalesce(jsonb_agg(public.operator_order_snapshot_internal_v1(id) ORDER BY id DESC),'[]'),
   CASE WHEN (SELECT count(*) FROM page)>p_limit THEN min(id) END INTO rows,v_next FROM visible;
 RETURN jsonb_build_object('occasionId',p_occasion,'orders',rows,'nextCursor',v_next);
END $$;


ALTER FUNCTION public.get_operator_orders_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_limit integer, p_before bigint, p_state text, p_search text, p_order bigint) OWNER TO postgres;

--
-- Name: orders; Type: TABLE; Schema: eshop; Owner: postgres
--

CREATE TABLE eshop.orders (
    id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    price numeric(10,2),
    state text,
    data jsonb,
    occasion bigint,
    payment_info bigint,
    currency_code character(3) DEFAULT 'CZK'::bpchar NOT NULL,
    note_hidden text,
    form bigint,
    email_payment_version bigint DEFAULT 0 NOT NULL,
    order_symbol text NOT NULL,
    order_sequence bigint NOT NULL,
    source_waitlist_order_id bigint,
    CONSTRAINT orders_order_sequence_positive_check CHECK ((order_sequence > 0)),
    CONSTRAINT orders_order_symbol_format_check CHECK ((order_symbol ~ '^([1-9][ACEFGHIJKLMNPQRUVWXY]){5}$'::text)),
    CONSTRAINT orders_stock_finance CHECK (((state IS DISTINCT FROM 'stock'::text) OR ((price IS NULL) AND (payment_info IS NULL)))),
    CONSTRAINT orders_waitlist_finance CHECK (((state IS DISTINCT FROM 'waitlisted'::text) OR ((price IS NULL) AND (payment_info IS NULL))))
);


ALTER TABLE eshop.orders OWNER TO postgres;

--
-- Name: get_order(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order(order_id bigint) RETURNS eshop.orders
    LANGUAGE plpgsql
    AS $$
DECLARE
  result eshop.orders;
BEGIN
  SELECT *
  INTO result
  FROM eshop.orders
  WHERE id = order_id;

  RETURN result;
END;
$$;


ALTER FUNCTION public.get_order(order_id bigint) OWNER TO postgres;

--
-- Name: get_order_action_summary_internal(text, boolean, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_action_summary_internal(p_state text, p_has_waiting boolean DEFAULT false, p_pending_places bigint DEFAULT 0) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object('isActive',CASE WHEN p_state='waitlisted' THEN
  coalesce(p_has_waiting,false) OR coalesce(p_pending_places,0)>0 ELSE p_state IS DISTINCT FROM 'storno' END,
 'allowedActions',CASE WHEN p_state='waitlisted' THEN jsonb_build_array('view','note','offer','withdraw')
 WHEN p_state IN ('stock','storno','preparing_payment') THEN jsonb_build_array('view')
 WHEN p_state='ordered' THEN jsonb_build_array('view','note','edit','cancel','paid')
 ELSE jsonb_build_array('view','note','edit','cancel','send') END);
$$;


ALTER FUNCTION public.get_order_action_summary_internal(p_state text, p_has_waiting boolean, p_pending_places bigint) OWNER TO postgres;

--
-- Name: get_order_admin_detail(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_admin_detail(p_order bigint, p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; places jsonb; tickets jsonb; plans jsonb; actions jsonb; placement jsonb;
BEGIN
 SELECT * INTO o FROM eshop.orders WHERE id=p_order;
 IF o.id IS NULL OR o.occasion IS DISTINCT FROM p_occasion OR public.can_read_orders(o.occasion) IS NOT TRUE THEN
  RETURN jsonb_build_object('code',404,'message','Order unavailable'); END IF;
 placement:=public.order_admin_placement_internal(o.id);
 places:=placement->'places';tickets:=placement->'tickets';plans:=placement->'plans';
 actions:=public.get_order_allowed_actions_internal_v1(o.id);
 RETURN jsonb_build_object('code',200,'data',jsonb_build_object(
  'order',jsonb_build_object('id',o.id,'occasion',o.occasion,'form_id',o.form,'order_symbol',o.order_symbol,'order_sequence',o.order_sequence,
   'created_at',o.created_at,'updated_at',o.updated_at,'state',o.state,'price',o.price,'currency_code',o.currency_code,
   'data',o.data,'note_hidden',o.note_hidden,'allowedActions',actions,'email_payment_version',o.email_payment_version,
   'email_payment_fingerprint',public.order_email_payment_fingerprint(o.id),
   'payment_method',(SELECT payment_method FROM eshop.payment_info WHERE id=o.payment_info)),
  'capabilities',jsonb_build_object('write',coalesce(public.can_write_orders(o.occasion),false),'allowedActions',actions),
  'payment',public.customer_order_payment_internal(o.id)-'transactions',
  -- Authorized admin metadata stays readable after payment. Never issue or
  -- regenerate instructions as a side effect of viewing an order.
  'bankPaymentDetails',(SELECT jsonb_build_object(
    'account',coalesce(b.account_number_human_readable,b.account_number),
    'iban',b.account_number,'creditorName',b.creditor_name,
    'referenceKind',CASE WHEN o.currency_code='EUR' THEN 'RF' ELSE 'VS' END,
    'reference',CASE WHEN o.currency_code='EUR' THEN pi.creditor_reference ELSE pi.variable_symbol::text END)
    FROM eshop.payment_info pi JOIN eshop.bank_accounts b ON b.id=pi.bank_account
    WHERE pi.id=o.payment_info AND pi.payment_method='bank'
      AND pi.currency_code=o.currency_code),
  'waitlistSummary',CASE WHEN o.state='waitlisted' OR o.source_waitlist_order_id IS NOT NULL THEN public.get_waitlist_summary_internal(o.id) END,
  'tickets',tickets,'places',places,'placesComplete',true,'plans',plans,
  'placementFingerprint',placement->>'placementFingerprint',
  'form',(SELECT jsonb_build_object('id',f.id,'title',f.title) FROM public.forms f WHERE f.id=o.form AND f.occasion=o.occasion),
  'fields',(SELECT coalesce(jsonb_agg(to_jsonb(ff)||jsonb_build_object('product_type_data',
    CASE WHEN pt.id IS NOT NULL THEN jsonb_build_object('id',pt.id,'title',pt.title,'description',pt.description,'type',pt.type) END)
    ORDER BY ff."order",ff.id),'[]') FROM public.form_fields ff
    LEFT JOIN eshop.product_types pt ON pt.id=ff.product_type AND pt.occasion=o.occasion WHERE ff.form=o.form),
  'productCategories',(SELECT coalesce(jsonb_object_agg(p.id::text,p.product_type),'{}') FROM eshop.products p
    WHERE p.occasion=o.occasion AND EXISTS(SELECT 1 FROM jsonb_array_elements(tickets) t
      CROSS JOIN LATERAL jsonb_array_elements(coalesce(t#>'{snapshot,products}','[]')) pr WHERE pr->>'id'=p.id::text)),
  'answers',coalesce(o.data->'fields','[]'),
  'emailSummary',public.get_order_email_summary(o.id)
 ));
END $$;


ALTER FUNCTION public.get_order_admin_detail(p_order bigint, p_occasion bigint) OWNER TO postgres;

--
-- Name: get_order_agreement_data_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_agreement_data_v1(p_order bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM eshop.orders WHERE id=p_order;
 IF occ IS NULL OR NOT (public.is_service_role() OR (auth.uid() IS NOT NULL AND public.can_write_orders(occ))) THEN
  RAISE insufficient_privilege USING MESSAGE='order document access denied'; END IF;
 PERFORM public.check_occasion_writable(occ);
 PERFORM public.admit_ticket_document_internal_v1(occ);
 RETURN public.bound_document_data_v1(public.get_order_details(p_order));
END $$;


ALTER FUNCTION public.get_order_agreement_data_v1(p_order bigint) OWNER TO postgres;

--
-- Name: get_order_allowed_actions_internal_v1(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_allowed_actions_internal_v1(p_order bigint, p_summary jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT (CASE WHEN o.state='stock' THEN jsonb_build_array('view')
 WHEN EXISTS(SELECT 1 FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id WHERE i.sale_order_id=o.id AND t.state<>'storno') THEN jsonb_build_array('view','note','cancel','send')
 ELSE (coalesce(p_summary,(CASE WHEN o.state='waitlisted' OR o.source_waitlist_order_id IS NOT NULL OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=o.id)
    THEN public.get_waitlist_summary_internal(o.id) ELSE public.get_order_action_summary_internal(o.state) END))->'allowedActions') END)
    - CASE WHEN public.payment_method_is_online_internal(p.payment_method) THEN ARRAY['cancel','paid']::text[] ELSE ARRAY[]::text[] END
 FROM eshop.orders o LEFT JOIN eshop.payment_info p ON p.id=o.payment_info WHERE o.id=p_order;
$$;


ALTER FUNCTION public.get_order_allowed_actions_internal_v1(p_order bigint, p_summary jsonb) OWNER TO postgres;

--
-- Name: get_order_blueprint_view(bigint, bigint, bigint, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_blueprint_view(p_order bigint, p_occasion bigint, p_blueprint bigint, p_expected_placement_fingerprint text, p_known_layout_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE core jsonb; o eshop.orders; b eshop.blueprints; spot_ids bigint[]; data jsonb;
BEGIN
 SELECT * INTO o FROM eshop.orders WHERE id=p_order;
 IF o.id IS NULL OR o.occasion IS DISTINCT FROM p_occasion OR public.can_read_orders(o.occasion) IS NOT TRUE THEN
  RETURN jsonb_build_object('code',404,'message','Order unavailable'); END IF;
 core:=public.order_admin_placement_internal(o.id);
 IF p_expected_placement_fingerprint IS DISTINCT FROM core->>'placementFingerprint' THEN
  RETURN jsonb_build_object('code',409,'reason','PLACEMENT_CHANGED'); END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(core->'plans') p WHERE p->>'id'=p_blueprint::text) THEN
  RETURN jsonb_build_object('code',404,'message','Order unavailable'); END IF;
 SELECT * INTO b FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion;
 IF b.id IS NULL OR b.layout->>'schemaVersion' IS DISTINCT FROM '2' THEN RETURN jsonb_build_object('code',422,'reason','CURRENT_PLAN_UNAVAILABLE'); END IF;
 SELECT coalesce(array_agg(spot),'{}'::bigint[]) INTO spot_ids
 FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id;
 data:=jsonb_build_object(
  'id',b.id,'occasion',b.occasion,'title',b.title,'layout_revision',b.layout_revision,
  'placementFingerprint',core->>'placementFingerprint',
  -- Exactly the node/lifecycle facts needed by the shared renderer. No full
  -- orders, customers, products, or reservation secrets leave this reader.
  'seatStates',(SELECT coalesce(jsonb_agg(jsonb_build_object(
    'nodeId',sb.node_id,'title',f.title,'state',f.state,
    'blocked',sb.blocked,'hasProduct',f.product IS NOT NULL) ORDER BY sb.node_id),'[]')
    FROM public.blueprint_spot_facts_internal(b.occasion,spot_ids) f
    JOIN eshop.blueprint_seat_bindings sb ON sb.spot=f.id AND sb.blueprint=b.id),
  'places',(SELECT coalesce(jsonb_agg(p),'[]') FROM jsonb_array_elements(core->'places') p WHERE p->>'blueprintId'=b.id::text)
 );
 IF p_known_layout_revision IS DISTINCT FROM b.layout_revision THEN
  data:=data||jsonb_build_object('layout',b.layout,'resources',public.blueprint_layout_resources_internal(b.layout,b.occasion));
 END IF;
 RETURN jsonb_build_object('code',200,'data',data);
END $$;


ALTER FUNCTION public.get_order_blueprint_view(p_order bigint, p_occasion bigint, p_blueprint bigint, p_expected_placement_fingerprint text, p_known_layout_revision bigint) OWNER TO postgres;

--
-- Name: get_order_change_summary_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_change_summary_v1(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
 v_current jsonb; v_currency text; v_current_price numeric; v_reference eshop.orders_history; v_latest bigint;
 v_sent_at timestamptz; v_ref_tickets jsonb; v_cur_tickets jsonb;
 v_ref jsonb; v_cur jsonb; v_ticket jsonb; v_symbol text; v_state text;
 v_before jsonb; v_after jsonb; v_added jsonb; v_removed jsonb; v_changed jsonb;
 v_cancelled jsonb:='[]'; v_removed_tickets jsonb:='[]'; v_added_tickets jsonb:='[]';
 v_product_changes jsonb:='[]'; v_old_total numeric:=0; v_new_total numeric:=0;
 i integer; j integer; v_has_changes boolean;
BEGIN
 SELECT data,currency_code,price INTO v_current,v_currency,v_current_price FROM eshop.orders WHERE id=p_order_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
 SELECT id INTO v_latest FROM eshop.orders_history WHERE "order"=p_order_id
 ORDER BY created_at DESC,id DESC LIMIT 1;
 SELECT * INTO v_reference FROM eshop.orders_history WHERE "order"=p_order_id
 AND data->>'is_sent_to_customer'='true' ORDER BY created_at DESC,id DESC LIMIT 1;
 IF FOUND THEN v_sent_at:=v_reference.created_at;
 ELSE
  SELECT * INTO v_reference FROM eshop.orders_history WHERE "order"=p_order_id
  ORDER BY created_at ASC,id ASC LIMIT 1;
 END IF;
 v_ref_tickets:=coalesce(v_reference.data->'tickets','[]');
 v_cur_tickets:=coalesce(v_current->'tickets','[]');
 SELECT coalesce(sum(coalesce((p->>'price')::numeric,0)),0) INTO v_old_total
 FROM jsonb_array_elements(v_ref_tickets) t,jsonb_array_elements(coalesce(t->'products','[]')) p;
 SELECT coalesce(sum(coalesce((p->>'price')::numeric,0)),0) INTO v_new_total
 FROM jsonb_array_elements(v_cur_tickets) t,jsonb_array_elements(coalesce(t->'products','[]')) p;
 v_old_total:=coalesce(v_reference.price,v_old_total);
 v_new_total:=coalesce(v_current_price,v_new_total);
 -- Without history there is no evidence from which to invent a change.
 IF v_reference.id IS NOT NULL THEN
  FOR v_ref IN SELECT value FROM jsonb_array_elements(v_ref_tickets) LOOP
   SELECT value INTO v_cur FROM jsonb_array_elements(v_cur_tickets)
   WHERE (v_ref->>'id' IS NOT NULL AND value->>'id'=v_ref->>'id')
      OR (v_ref->>'id' IS NULL AND value=v_ref) LIMIT 1;
   v_symbol:=NULL; v_state:=NULL;
   -- Order membership prevents historical/foreign IDs leaking ticket metadata.
   SELECT t.ticket_symbol,t.state INTO v_symbol,v_state FROM eshop.tickets t
   WHERE t.id::text=v_ref->>'id' AND EXISTS(SELECT 1 FROM eshop.order_product_ticket opt
      WHERE opt.ticket=t.id AND opt."order"=p_order_id);
   v_ticket:=jsonb_build_object('id',v_ref->'id','ticket_symbol',
     coalesce(nullif(v_ref->>'ticket_symbol',''),v_symbol),'products',coalesce(v_ref->'products','[]'));
   IF v_cur IS NULL THEN
    IF v_state='storno' THEN v_cancelled:=v_cancelled||jsonb_build_array(v_ticket);
    ELSE v_removed_tickets:=v_removed_tickets||jsonb_build_array(v_ticket); END IF;
    CONTINUE;
   END IF;
   v_before:=coalesce(v_ref->'products','[]'); v_after:=coalesce(v_cur->'products','[]');
   v_added:='[]'; v_removed:='[]'; v_changed:='[]';
   -- Preserve duplicate instances; never pair products across different tickets.
   IF jsonb_array_length(v_after)>0 THEN
    FOR i IN REVERSE jsonb_array_length(v_after)-1..0 LOOP
     SELECT ordinality::integer-1 INTO j FROM jsonb_array_elements(v_before) WITH ORDINALITY
     WHERE value->>'id' IS NOT DISTINCT FROM v_after->i->>'id'
       AND value->>'title' IS NOT DISTINCT FROM v_after->i->>'title'
       AND abs(coalesce((value->>'price')::numeric,0)-coalesce((v_after->i->>'price')::numeric,0))<0.001
     ORDER BY ordinality LIMIT 1;
     IF j IS NOT NULL THEN v_before:=v_before-j; v_after:=v_after-i; END IF;
    END LOOP;
   END IF;
   IF jsonb_array_length(v_after)>0 THEN
    FOR i IN REVERSE jsonb_array_length(v_after)-1..0 LOOP
     SELECT ordinality::integer-1 INTO j FROM jsonb_array_elements(v_before) WITH ORDINALITY
     WHERE value->>'id' IS NOT DISTINCT FROM v_after->i->>'id' ORDER BY ordinality LIMIT 1;
     IF j IS NOT NULL THEN
      v_changed:=v_changed||jsonb_build_array(jsonb_build_object('from',v_before->j,'to',v_after->i));
      v_before:=v_before-j; v_after:=v_after-i;
     END IF;
    END LOOP;
   END IF;
   v_added:=v_after; v_removed:=v_before;
   IF jsonb_array_length(v_added)+jsonb_array_length(v_removed)+jsonb_array_length(v_changed)>0 THEN
    v_product_changes:=v_product_changes||jsonb_build_array(v_ticket||jsonb_build_object(
     'added',v_added,'removed',v_removed,'changed',v_changed));
   END IF;
  END LOOP;
  FOR v_cur IN SELECT value FROM jsonb_array_elements(v_cur_tickets) LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_ref_tickets) r
     WHERE (v_cur->>'id' IS NOT NULL AND r->>'id'=v_cur->>'id') OR (v_cur->>'id' IS NULL AND r=v_cur)) THEN
    v_added_tickets:=v_added_tickets||jsonb_build_array(v_cur);
   END IF;
  END LOOP;
 END IF;
 v_has_changes:=v_reference.id IS NOT NULL AND (jsonb_array_length(v_cancelled)+jsonb_array_length(v_removed_tickets)
   +jsonb_array_length(v_added_tickets)+jsonb_array_length(v_product_changes)>0 OR v_old_total<>v_new_total);
 RETURN jsonb_build_object('version',1,'cancelledTickets',v_cancelled,'removedTickets',v_removed_tickets,
   'addedTickets',v_added_tickets,'productChanges',v_product_changes,'referenceTotal',v_old_total,
   'currentTotal',v_new_total,'currencyCode',coalesce(v_currency,'CZK'),'hasChanges',v_has_changes,'referenceOrder',to_jsonb(v_reference),
   'referenceHistoryId',v_reference.id,'latestHistoryId',v_latest,'latestSentAt',v_sent_at);
END $$;


ALTER FUNCTION public.get_order_change_summary_v1(p_order_id bigint) OWNER TO postgres;

--
-- Name: get_order_deletion_context_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_deletion_context_v1(p_order bigint, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion bigint; v_unit bigint; v_state text; v_vs bigint;
  v_command text; v_response jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  -- Deletion removes the order, so a lost response is recovered from its receipt.
  IF p_command_id IS NOT NULL THEN
    SELECT CASE WHEN r.status='expired' THEN public.expired_client_mutation_response_v1(r)
      ELSE r.response END INTO v_response FROM public.client_mutation_receipts r
    JOIN public.occasions oc ON oc.id=r.occasion
    WHERE r.command_id=p_command_id AND r.actor_id=auth.uid()
      AND r.command_name='inventory.order.delete' AND r.status IN ('completed','expired')
      AND r.request_sha256=encode(extensions.digest(convert_to(
        jsonb_build_object('order',p_order)::text,'UTF8'),'sha256'),'hex')
      AND public.can_delete_orders(oc.id);
    IF FOUND THEN RETURN jsonb_build_object('response',v_response); END IF;
    IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id) THEN
      RAISE insufficient_privilege USING MESSAGE='command id unavailable';
    END IF;
  END IF;
  SELECT o.occasion,oc.unit,o.state,pi.variable_symbol
    INTO v_occasion,v_unit,v_state,v_vs
  FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion
    LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.id=p_order;
  IF v_occasion IS NULL OR NOT public.can_delete_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  PERFORM public.check_occasion_writable(v_occasion);
  IF v_state IN ('waitlisted','preparing_payment')
    OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.orders WHERE source_waitlist_order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts
      WHERE target_order_id=p_order OR source_order_id=p_order) THEN
    RAISE EXCEPTION 'ORDER_HAS_WAITLIST_HISTORY';
  END IF;
  -- Metadata reads do not charge. External deletion attempts share the order
  -- mutation burst budget before credentials/provider work; final SQL charges
  -- its own mutation and item count through the existing command boundary.
  IF p_command_id IS NOT NULL THEN
    PERFORM public.admit_order_mutation_v1(v_occasion,0);
  END IF;
  SELECT m.data->>'command_id' INTO v_command FROM public.email_messages m
    WHERE m.order_id=p_order AND m.code='TICKET_ORDER_CONFIRMATION'
    ORDER BY m.id DESC LIMIT 1;
  RETURN jsonb_build_object('hasFakturoid',EXISTS(
    SELECT 1 FROM eshop.external_services WHERE unit=v_unit AND type='FAKTUROID'),
    'commandId',v_command,'variableSymbol',v_vs);
END; $$;


ALTER FUNCTION public.get_order_deletion_context_v1(p_order bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: get_order_details(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_details(orderid bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_data jsonb;
    reference_history_data jsonb;
    form_fields_data jsonb;
    form_key uuid;
    latest_history_id bigint;
BEGIN
    -- Retrieve the order, occasion, payment info, and bank account as separate objects
    SELECT jsonb_build_object(
        'order', to_jsonb(o.*),
        'occasion', to_jsonb(occ.*),
        'payment_info', to_jsonb(pi.*),
        'bank_account', to_jsonb(ba.*)
    )
    INTO result_data
    FROM eshop.orders AS o
    LEFT JOIN public.occasions AS occ ON o.occasion = occ.id
    LEFT JOIN eshop.payment_info AS pi ON o.payment_info = pi.id
    LEFT JOIN eshop.bank_accounts AS ba ON pi.bank_account = ba.id
    WHERE o.id = orderId;

    -- Check if the order was found
    IF result_data IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Order not found.');
    END IF;

    -- Find the latest order_history ID for the given order
    SELECT oh.id
    INTO latest_history_id
    FROM eshop.orders_history AS oh
    WHERE oh.order = orderId
    ORDER BY oh.created_at DESC
    LIMIT 1;

    IF latest_history_id IS NOT NULL THEN
        result_data := result_data || jsonb_build_object('latest_history_id', latest_history_id);
    END IF;

    -- Get the data of the latest SENT history entry
    SELECT data INTO reference_history_data
    FROM eshop.orders_history
    WHERE "order" = orderId AND (data->>'is_sent_to_customer')::boolean IS TRUE
    ORDER BY created_at DESC LIMIT 1;

    -- If no sent record was found, get the oldest record as the reference
    IF NOT FOUND THEN
        SELECT data INTO reference_history_data
        FROM eshop.orders_history
        WHERE "order" = orderId
        ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Add the reference data to the result
    IF reference_history_data IS NOT NULL THEN
        result_data := result_data || jsonb_build_object('reference_history', reference_history_data);
    END IF;

    -- Extract the form's unique key from the order's data
    form_key := (result_data->'order'->'data'->>'form')::uuid;

    -- If a form key exists, fetch all associated form fields
    IF form_key IS NOT NULL THEN
        SELECT jsonb_object_agg(ff.id, to_jsonb(ff.*))
        INTO form_fields_data
        FROM public.form_fields AS ff
        JOIN public.forms AS f ON ff.form = f.id
        WHERE f.key = form_key;

        -- If form fields were found, add them to the result data
        IF form_fields_data IS NOT NULL THEN
            result_data := result_data || jsonb_build_object('form_fields', form_fields_data);
        END IF;
    END IF;

    -- Return a success response with the collected data
    RETURN jsonb_build_object('code', 200, 'data', result_data);

EXCEPTION WHEN OTHERS THEN
    -- Handle any unexpected errors and return a detailed error message
    RETURN jsonb_build_object(
        'code', 500,
        'message', 'An unexpected error occurred.',
        'detail', SQLERRM
    );
END;
$$;


ALTER FUNCTION public.get_order_details(orderid bigint) OWNER TO postgres;

--
-- Name: get_order_details_for_email(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_details_for_email(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result_data jsonb;
    v_changes jsonb;
    form_fields_data jsonb;
    form_data jsonb;
    form_key uuid;
    latest_history_id bigint;
    v_reply_to_email TEXT;
BEGIN
    -- Retrieve the order, occasion, payment info, and bank account as separate objects
    SELECT jsonb_build_object(
        'order', to_jsonb(o.*) || jsonb_build_object('data', o.data || jsonb_build_object(
          'tickets', public.order_tickets_with_seating_internal(o.id,o.data->'tickets'))),
        'occasion', to_jsonb(occ.*)||jsonb_build_object('locale',coalesce((SELECT data->>'DEFAULT_LANGUAGE' FROM public.organizations WHERE id=occ.organization),'cs')),
        'payment_info', to_jsonb(pi.*),
        'bank_account', CASE
            WHEN upper(o.currency_code) = 'EUR'
              AND ba.id IS NOT NULL
              AND nullif(trim(ba.creditor_name), '') IS NULL
            THEN jsonb_set(
              to_jsonb(ba.*),
              '{creditor_name}',
              to_jsonb(left(trim(regexp_replace(org.title, '[[:space:][:cntrl:]]+', ' ', 'g')), 70))
            )
            ELSE to_jsonb(ba.*)
        END
    )
    INTO result_data
    FROM eshop.orders AS o
    LEFT JOIN public.occasions AS occ ON o.occasion = occ.id
    LEFT JOIN public.organizations AS org ON occ.organization = org.id
    LEFT JOIN eshop.payment_info AS pi ON o.payment_info = pi.id
    LEFT JOIN eshop.bank_accounts AS ba ON pi.bank_account = ba.id
    WHERE o.id = p_order_id;

    -- Check if the order was found
    IF result_data IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Order not found.');
    END IF;

    -- Call the function you provided to get the email
    SELECT get_reply_to_email_for_order(p_order_id) INTO v_reply_to_email;

    -- Add the email to the result data. jsonb_build_object handles NULLs gracefully.
    result_data := result_data || jsonb_build_object('reply_to', v_reply_to_email);


    v_changes := public.get_order_change_summary_v1(p_order_id);
    latest_history_id := (v_changes->>'latestHistoryId')::bigint;
    result_data := result_data || jsonb_build_object(
      'latest_history_id', latest_history_id,
      'reference_history', v_changes#>'{referenceOrder,data}',
      'order_changes', v_changes);

    -- Extract the form's unique key from the order's data
    form_key := (result_data->'order'->'data'->>'form')::uuid;

    -- If a form key exists, fetch all associated form fields
    IF form_key IS NOT NULL THEN
        -- 2. Modified query to fetch both form_fields and form_data at the same time
        SELECT
            jsonb_object_agg(ff.id, to_jsonb(ff.*)), -- All fields
            public.effective_form_metadata_internal(f.data, u.data) -- Communication metadata without analytics policy
        INTO
            form_fields_data,
            form_data
        FROM
            public.form_fields AS ff
        JOIN
            public.forms AS f ON ff.form = f.id
        JOIN public.occasions form_occasion ON form_occasion.id = f.occasion
        JOIN public.units u ON u.id = form_occasion.unit
        WHERE
            f.key = form_key
        GROUP BY
            f.id, u.data; -- Group by the form used for effective data

        -- If form fields were found, add them to the result data
        IF form_fields_data IS NOT NULL THEN
            result_data := result_data || jsonb_build_object('form_fields', form_fields_data);
        END IF;

        -- 3. Added this block to merge the form_data
        IF form_data IS NOT NULL THEN
            result_data := result_data || jsonb_build_object('form_data', form_data);
        END IF;
    END IF;

    -- Return a success response with the collected data
    RETURN jsonb_build_object('code', 200, 'data', result_data);

END;
$$;


ALTER FUNCTION public.get_order_details_for_email(p_order_id bigint) OWNER TO postgres;

--
-- Name: get_order_email_overview_source_v1(bigint, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_email_overview_source_v1(p_order_id bigint, p_recipient text, p_command_id uuid, p_delivery jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE requested eshop.orders; root eshop.orders; occ public.occasions; f public.forms;
 s eshop.order_overview_sources;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 SELECT * INTO STRICT requested FROM eshop.orders WHERE id=p_order_id;
 SELECT * INTO STRICT root FROM eshop.orders WHERE id=coalesce(requested.source_waitlist_order_id,requested.id) FOR UPDATE;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=root.occasion;
 SELECT * INTO f FROM public.forms WHERE id=root.form AND occasion=occ.id;
 IF requested.occasion IS DISTINCT FROM root.occasion OR requested.form IS DISTINCT FROM root.form
 OR requested.data->>'email' IS DISTINCT FROM p_recipient THEN
  RAISE EXCEPTION 'INVALID_OVERVIEW_RECIPIENT';
 END IF;
 -- A repaired split child must not receive the root capability covering other
 -- orders at its former contact. Omit that optional link; preserve the root
 -- source and every other order/contact unchanged.
 IF root.data->>'email' IS DISTINCT FROM p_recipient THEN RETURN NULL; END IF;
 -- Orders without a public form have no public overview route.
 IF f.id IS NULL THEN RETURN NULL; END IF;
 SELECT src.* INTO s FROM eshop.order_overview_sources src JOIN eshop.waitlist_capabilities cap USING(token_hash)
 WHERE cap.order_id=root.id AND cap.form_id=f.id AND cap.organization_id=occ.organization
 AND cap.kind='order_view' AND cap.revoked_at IS NULL AND cap.expires_at>statement_timestamp()
 AND src.expires_at=cap.expires_at ORDER BY src.created_at DESC LIMIT 1;
 IF s.token_hash IS NULL THEN
  -- Never silently replace an expired/revoked capability with a different link.
  IF EXISTS(SELECT 1 FROM eshop.waitlist_capabilities WHERE order_id=root.id AND kind='order_view') THEN RETURN NULL; END IF;
  IF p_delivery IS NOT NULL THEN
   PERFORM public.issue_order_overview_internal(root.id,p_delivery,p_command_id);
   SELECT * INTO STRICT s FROM eshop.order_overview_sources WHERE command_id=p_command_id;
  END IF;
 END IF;
 RETURN jsonb_build_object('orderId',root.id,'organization',occ.organization,'occasion',occ.id,'unit',occ.unit,
 'recipient',p_recipient,'occasionTitle',occ.title,'orderSymbol',root.order_symbol,
 'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(root.id)),
 'formLink',f.link,'webLink',(SELECT data->>'DEFAULT_URL' FROM public.organizations WHERE id=occ.organization),
 'source',CASE WHEN s.token_hash IS NOT NULL THEN jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash,'expiresAt',s.expires_at) END);
END $$;


ALTER FUNCTION public.get_order_email_overview_source_v1(p_order_id bigint, p_recipient text, p_command_id uuid, p_delivery jsonb) OWNER TO postgres;

--
-- Name: get_order_email_summaries(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_email_summaries(p_occasion bigint, p_orders bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_summary jsonb;
BEGIN
 IF NOT coalesce(public.can_read_orders(p_occasion),false) THEN RAISE EXCEPTION 'email_read_denied'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.orders WHERE id=ANY(p_orders) AND occasion<>p_occasion) THEN RAISE EXCEPTION 'email_scope_mismatch'; END IF;
 WITH messages AS (
 SELECT m.*,public.email_reporting_state(m) reporting_state FROM public.email_messages m WHERE m.order_id=ANY(p_orders) AND m.occasion=p_occasion
  AND workflow_state NOT IN ('cancelled','expired')),
 ranked AS (
 SELECT *,CASE WHEN reporting_state IN ('complaint','bounce','reject','rendering_failure','unknown','dead','suppressed','retry_wait','post_action_failed') THEN 0
 WHEN workflow_state IN ('pending','preparing','sending','blocked') AND target_time<=now() THEN 1
 WHEN workflow_state='accepted' THEN 2 ELSE 3 END rank FROM messages)
 SELECT coalesce(jsonb_object_agg(r.order_id,jsonb_build_object('state',r.reporting_state,'kind',r.message_kind,'recipient',r.recipient,'message_id',r.message_id,'at',coalesce(r.clicked_at,r.opened_at,r.delivered_at,r.accepted_at,r.created_at),
 'current_issues',public.order_email_current_issues(r.order_id),'scheduled_at',r.target_time,'attention_count',(SELECT count(*) FROM ranked n WHERE n.order_id=r.order_id AND rank=0),'loaded_at',now(),
 'messages',(SELECT coalesce(jsonb_agg(jsonb_build_object('kind',message_kind,'state',reporting_state,'at',coalesce(delivered_at,accepted_at,created_at)) ORDER BY created_at DESC),'[]') FROM ranked n WHERE n.order_id=r.order_id))
),'{}'::jsonb) INTO v_summary FROM (SELECT DISTINCT ON (order_id) * FROM ranked ORDER BY order_id,rank,created_at DESC,id DESC) r;
 SELECT v_summary||coalesce(jsonb_object_agg(o.id,jsonb_build_object('state','unavailable','messages','[]'::jsonb,
  'current_issues',public.order_email_current_issues(o.id),'loaded_at',now())),'{}') INTO v_summary
 FROM eshop.orders o WHERE o.id=ANY(p_orders) AND o.occasion=p_occasion AND NOT v_summary ? o.id::text;
 RETURN v_summary;
END $$;


ALTER FUNCTION public.get_order_email_summaries(p_occasion bigint, p_orders bigint[]) OWNER TO postgres;

--
-- Name: get_order_email_summary(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_email_summary(p_order bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_occ bigint;
BEGIN
 SELECT occasion INTO v_occ FROM eshop.orders WHERE id=p_order;
 IF v_occ IS NULL THEN RAISE EXCEPTION 'order_not_found'; END IF;
 RETURN coalesce(public.get_order_email_summaries(v_occ,ARRAY[p_order])->p_order::text,jsonb_build_object('state','unavailable','messages','[]'::jsonb,'loaded_at',now()));
END $$;


ALTER FUNCTION public.get_order_email_summary(p_order bigint) OWNER TO postgres;

--
-- Name: get_order_history(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_order_history(order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_order_data jsonb;
    v_history_data jsonb;
    v_users_data jsonb;
BEGIN
    -- Retrieve the occasion associated with the order
    SELECT o.occasion, to_jsonb(o) || jsonb_build_object('payment_method', pi.payment_method,'email_payment_fingerprint',public.order_email_payment_fingerprint(o.id))
    INTO v_occasion_id, v_order_data
    FROM eshop.orders o
    LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info
    WHERE o.id = order_id;

    -- Check if the order exists
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Order not found');
    END IF;

    -- Verify if the current user is an editor for the order's occasion
    IF NOT can_read_orders(v_occasion_id) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this order history');
    END IF;

    v_order_data:=jsonb_set(v_order_data,'{data,tickets}',public.order_tickets_with_seating_internal(order_id,v_order_data#>'{data,tickets}'));

    -- Fetch history items for the order, ordered by creation date
    SELECT jsonb_agg(to_jsonb(h) || jsonb_build_object('order_symbol', v_order_data->>'order_symbol', 'order_sequence', v_order_data->'order_sequence') ORDER BY h.created_at)
    INTO v_history_data
    FROM eshop.orders_history h
    WHERE h. "order" = order_id;

    -- Fetch unique users who created the history items
    WITH user_ids AS (
        SELECT DISTINCT created_by
        FROM eshop.orders_history
        WHERE "order" = order_id AND created_by IS NOT NULL
    )
    SELECT jsonb_agg(u.*)
    INTO v_users_data
    FROM public.user_info u
    WHERE u.id IN (SELECT created_by FROM user_ids);

    -- Return the combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'order', COALESCE(v_order_data, '{}'::jsonb),
            'history', COALESCE(v_history_data, '[]'::jsonb),
            'users', COALESCE(v_users_data, '[]'::jsonb)
        )
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_order_history(order_id bigint) OWNER TO postgres;

