--
-- Name: tickets; Type: TABLE; Schema: eshop; Owner: postgres
--

CREATE TABLE eshop.tickets (
    id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ticket_symbol text,
    state text,
    occasion bigint NOT NULL,
    note text,
    note_hidden text,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    waitlist_queue_at timestamp with time zone,
    CONSTRAINT tickets_state_check CHECK ((state = ANY (ARRAY['ordered'::text, 'paid'::text, 'sent'::text, 'used'::text, 'storno'::text, 'waitlisted'::text]))),
    CONSTRAINT tickets_waitlist_non_admission CHECK (((state IS DISTINCT FROM 'waitlisted'::text) OR (ticket_symbol IS NULL)))
);


