--
-- Name: get_orders(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_orders(form_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    occasion_id BIGINT;
    spotsData JSONB;
    productsData JSONB;
    productTypesData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    orderProductTicketsData JSONB;
    paymentInfoData JSONB;
    formsData JSONB;
BEGIN
    -- Get the occasion_id based on the provided form_link
    SELECT occasion
    INTO occasion_id
    FROM public.forms
    WHERE id = public.resolve_form_link_internal(form_link);

    -- Check if form_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form key does not exist or is not linked to an occasion');
    END IF;

    -- Authorization check
    IF (SELECT can_read_orders(occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to access this occasion');
    END IF;

    -- Fetch spots where order_product_ticket is not NULL
    SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'product', s.product,
        'order_product_ticket', s.order_product_ticket,
        'state', CASE
            WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
            WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
            ELSE 'available'
        END
    ))
    INTO spotsData
    FROM eshop.spots s
    WHERE s.occasion = occasion_id
      AND s.order_product_ticket IS NOT NULL;

    -- Fetch all products linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'price', p.price,
        'currency_code', p.currency_code,
        'type', pt.type,
        'description', pt.description
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = occasion_id;

    -- Fetch product types for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', pt.id,
        'type', pt.type,
        'title', pt.title,
        'description', pt.description
    ))
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = occasion_id;

    -- Fetch tickets linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'created_at', t.created_at,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden
    ))
    INTO ticketsData
    FROM eshop.tickets t
    WHERE t.occasion = occasion_id;

    -- Fetch orders linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'price', o.price,
        'state', o.state,
        'currency_code', o.currency_code,
        'data', o.data,
        'payment_info', o.payment_info,
        'note_hidden', o.note_hidden
    ))
    INTO ordersData
    FROM eshop.orders o
    WHERE o.occasion = occasion_id;

    -- Extract order IDs from ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(ordersData) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object(
        'id', opt.id,
        'order', opt."order",
        'product', opt.product,
        'ticket', opt.ticket,
        'created_at', opt.created_at
    ))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Fetch payment information linked to the orders
    SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id,
        'created_at', pi.created_at,
        'bank_account', pi.bank_account,
        'variable_symbol', pi.variable_symbol,
        'amount', pi.amount,
        'paid', pi.paid,
        'returned', pi.returned,
        'deadline', pi.deadline,
        'currency_code', pi.currency_code
    ))
    INTO paymentInfoData
    FROM eshop.payment_info pi
    WHERE pi.id IN (
        SELECT DISTINCT (order_obj->>'payment_info')::BIGINT
        FROM jsonb_array_elements(ordersData) order_obj
    );

    -- Fetch forms linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'created_at', f.created_at,
        'data', f.data,
        'key', f.key,
        'occasion', f.occasion,
        'type', f.type,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'is_open', f.is_open,
        'link', f.link,
        'blueprint', f.blueprint,
        'header', f.header,
        'header_off', f.header_off,
        'updated_at', f.updated_at
    ))
    INTO formsData
    FROM public.forms f
    WHERE f.occasion = occasion_id;

    -- Return combined data, including the new product_types key
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'spots', COALESCE(spotsData, '[]'::jsonb),
            'products', COALESCE(productsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb),
            'tickets', COALESCE(ticketsData, '[]'::jsonb),
            'orders', COALESCE(ordersData, '[]'::jsonb),
            'order_product_ticket', COALESCE(orderProductTicketsData, '[]'::jsonb),
            'payment_info', COALESCE(paymentInfoData, '[]'::jsonb),
            'forms', COALESCE(formsData, '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION public.get_orders(form_link text) OWNER TO postgres;

--
-- Name: get_orders(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_orders(p_occasion_link text, p_form_link text DEFAULT NULL::text, p_options jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id BIGINT;
    v_form_id BIGINT;
    spotsData JSONB;
    productsData JSONB;
    productTypesData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    ordersHistoryData JSONB;
    orderProductTicketsData JSONB;
    paymentInfoData JSONB;
    formsData JSONB;
    usersData JSONB; -- ADDED: Variable for user info data
BEGIN
    -- This function retrieves order and reservation details for a given occasion.
    -- It can conditionally include related data like spots, history, and users.
    --
    -- 'include_orders_history': If true, it fetches 'orders_history' and the
    --                           associated 'users' who created those history records.

    -- 1. Input Validation: Ensure at least one link is provided.
    IF p_occasion_link IS NULL AND p_form_link IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Either occasion_link or form_link must be provided');
    END IF;

    -- 2. Determine occasion_id based on the provided link.
    IF p_occasion_link IS NOT NULL THEN
        SELECT id
        INTO v_occasion_id
        FROM public.occasions
        WHERE id = public.resolve_occasion_link_internal(p_occasion_link)
          AND organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid());
    ELSE
        SELECT occasion, id
        INTO v_occasion_id, v_form_id
        FROM public.forms
        WHERE id = public.resolve_form_link_internal(p_form_link)
          AND occasion IN (SELECT o.id FROM public.occasions o WHERE o.organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid()));
    END IF;

    -- 3. Check if a valid occasion was found.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'The provided link is invalid or not linked to any occasion');
    END IF;

    -- 4. Authorization check.
    IF (SELECT can_read_orders(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to access this occasion');
    END IF;

    -- Conditionally fetch spots based on p_options for optimization
    IF (p_options->>'include_spots')::BOOLEAN = TRUE THEN
        SELECT jsonb_agg(jsonb_build_object(
            'id', s.id,
            'title', s.title,
            'product', s.product,
            'order_product_ticket', s.order_product_ticket,
            'state', CASE
                WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
                WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
                ELSE 'available'
            END
        ))
        INTO spotsData
        FROM eshop.spots s
        WHERE s.occasion = v_occasion_id
          AND s.order_product_ticket IS NOT NULL;
    END IF;

    -- Fetch all products linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'price', p.price,
        'currency_code', p.currency_code,
        'type', pt.type
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = v_occasion_id;

    -- Fetch product types for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', pt.id,
        'type', pt.type,
        'title', pt.title,
        'description', pt.description
    ))
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id;

    -- Fetch tickets linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'created_at', t.created_at,
        'updated_at', t.updated_at,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden,
        'batch', (SELECT jsonb_build_object('id',i.batch_id,'title',b.title,'ordinal',i.ordinal,'saleOrderId',i.sale_order_id) FROM eshop.ticket_batch_items i JOIN eshop.ticket_batches b ON b.id=i.batch_id WHERE i.ticket_id=t.id),
        'allowedActions',CASE WHEN EXISTS(SELECT 1 FROM eshop.ticket_batch_items i WHERE i.ticket_id=t.id) THEN
          jsonb_build_array('view') || CASE WHEN EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts d WHERE d.kind='single' AND d.ticket_ids=ARRAY[t.id] AND d.state='ready') THEN jsonb_build_array('download') ELSE '[]'::jsonb END ||
          CASE WHEN public.can_write_orders(t.occasion) THEN jsonb_build_array('note') ||
            CASE WHEN t.state<>'storno' AND EXISTS(SELECT 1 FROM eshop.ticket_batch_items i WHERE i.ticket_id=t.id AND i.sale_order_id IS NOT NULL)
              THEN jsonb_build_array('use','reset','cancel') ELSE '[]'::jsonb END ELSE '[]'::jsonb END END,
        'data', t.data
    ))
    INTO ticketsData
    FROM eshop.tickets t
    WHERE t.occasion = v_occasion_id;

    -- Fetch forms linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'data', f.data,
        'key', f.key,
        'occasion', f.occasion,
        'type', f.type,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'participant_capacity',f.participant_capacity,
        'waitlist_enabled',f.waitlist_enabled,
        'show_remaining_capacity',f.show_remaining_capacity,
        'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
        'capacity',public.get_form_capacity_snapshot_internal(f.id),
        'registrationMode',public.get_form_registration_mode_internal(f.id),
        'is_open', f.is_open,
        'link', f.link,
        'blueprint', f.blueprint,
        'title', f.title
    ))
    INTO formsData
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Ordinary orders need only activity/actions. Resolve ticket/offer lifecycles
    -- once only for orders that expose a full waitlist summary.
    WITH selected_orders AS MATERIALIZED (
        SELECT o.*, CASE WHEN o.state='waitlisted' OR o.source_waitlist_order_id IS NOT NULL
          OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=o.id)
          THEN public.get_waitlist_summary_internal(o.id)
          ELSE public.get_order_action_summary_internal(o.state)
        END AS waitlist_summary
        FROM eshop.orders o
        WHERE o.occasion = v_occasion_id
          AND (v_form_id IS NULL OR o.form = v_form_id)
    )
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id, 'order_symbol', o.order_symbol, 'order_sequence', o.order_sequence, 'created_at', o.created_at, 'updated_at', o.updated_at, 'price', o.price, 'state', o.state, 'currency_code', o.currency_code,
            'waitlistSummary',CASE WHEN o.state='waitlisted' OR o.source_waitlist_order_id IS NOT NULL
              OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=o.id)
              THEN o.waitlist_summary END,
            'isActive',(o.waitlist_summary->>'isActive')::boolean,
            'allowedActions',public.get_order_allowed_actions_internal_v1(o.id,o.waitlist_summary),
            'paymentChannel',CASE WHEN o.data ? 'ticketBatchOrigin' THEN 'cash' END,
            'batchId',(SELECT b.id FROM eshop.ticket_batches b WHERE b.stock_order_id=o.id),
            'source_waitlist_order_id',o.source_waitlist_order_id,
            'form_id', o.form,
            'form', jsonb_build_object('id', o.form),
            'data', CASE
                WHEN (p_options->>'include_full_order_data')::BOOLEAN = TRUE THEN o.data || jsonb_build_object('tickets', public.order_tickets_with_seating_internal(o.id,o.data->'tickets'))
                ELSE jsonb_build_object('name', o.data->>'name', 'surname', o.data->>'surname', 'email', o.data->>'email', 'note', o.data->>'note')
            END,
            'payment_info', o.payment_info, 'note_hidden', o.note_hidden
        ))
        INTO ordersData
        FROM selected_orders o;

    -- Extract order IDs from the (potentially filtered) ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object('id', opt.id, 'order', opt."order", 'product', opt.product, 'ticket', opt.ticket))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Fetch payment information linked to the orders
    SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id, 'payment_method', pi.payment_method, 'bank_account', pi.bank_account, 'variable_symbol', pi.variable_symbol, 'amount', pi.amount, 'deposit_amount', pi.deposit_amount,
        'deposit_deadline', pi.deposit_deadline, 'paid', pi.paid, 'returned', pi.returned, 'deadline', pi.deadline, 'currency_code', pi.currency_code, 'data', pi.data,
        'bank_sync_warning', public.bank_sync_warning(pi.bank_account)
    ))
    INTO paymentInfoData
    FROM eshop.payment_info pi
    WHERE pi.id IN (
        SELECT DISTINCT (order_obj->>'payment_info')::BIGINT
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
        WHERE order_obj->>'payment_info' IS NOT NULL
    );

    -- Conditionally fetch orders history and related users based on p_options
    IF (p_options->>'include_orders_history')::BOOLEAN = TRUE THEN
        -- First, fetch the history records
        WITH order_ids AS (
            SELECT (order_obj->>'id')::BIGINT AS id
            FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
        )
        SELECT jsonb_agg(jsonb_build_object(
            'id', oh.id, 'created_at', oh.created_at, 'created_by', oh.created_by, 'data', oh.data,
            'order', oh."order", 'order_symbol', (SELECT o.order_symbol FROM eshop.orders o WHERE o.id=oh."order"), 'order_sequence', (SELECT o.order_sequence FROM eshop.orders o WHERE o.id=oh."order"), 'state', oh.state, 'price', oh.price, 'currency_code', oh.currency_code
        ))
        INTO ordersHistoryData
        FROM eshop.orders_history oh
        WHERE oh."order" IN (SELECT id FROM order_ids);

        -- Second, fetch the unique users who created those history records
        WITH user_ids AS (
            SELECT DISTINCT (history_obj->>'created_by')::UUID AS id
            FROM jsonb_array_elements(COALESCE(ordersHistoryData, '[]'::jsonb)) history_obj
            WHERE history_obj->>'created_by' IS NOT NULL
        )
        SELECT jsonb_agg(jsonb_build_object(
            'id', ui.id,
            'name', ui.name,
            'surname', ui.surname,
            'email_readonly', ui.email_readonly
        ))
        INTO usersData
        FROM public.user_info ui
        WHERE ui.id IN (SELECT id FROM user_ids);
    END IF;


    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'occasion_id', v_occasion_id,
        'data', jsonb_build_object(
            'spots', COALESCE(spotsData, '[]'::jsonb),
            'products', COALESCE(productsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb),
            'tickets', COALESCE(ticketsData, '[]'::jsonb),
            'orders', COALESCE(ordersData, '[]'::jsonb),
            'order_product_ticket', COALESCE(orderProductTicketsData, '[]'::jsonb),
            'payment_info', COALESCE(paymentInfoData, '[]'::jsonb),
            'forms', COALESCE(formsData, '[]'::jsonb),
            'orders_history', COALESCE(ordersHistoryData, '[]'::jsonb),
            'users', COALESCE(usersData, '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION public.get_orders(p_occasion_link text, p_form_link text, p_options jsonb) OWNER TO postgres;

--
-- Name: get_orders_tab_data(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_orders_tab_data(p_occasion_link text, p_notification_group jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_orders_data JSONB;
    v_forms_data JSONB;
    v_notification_ids JSONB := '[]'::jsonb;
BEGIN

    SELECT get_orders(p_occasion_link, NULL, '{}'::jsonb) INTO v_orders_data;

    IF (v_orders_data->>'code')::INT <> 200 THEN
          RAISE EXCEPTION 'get_orders failed: %', v_orders_data->>'message';
    END IF;

    SELECT get_all_forms_with_fields(p_occasion_link) INTO v_forms_data;

    IF (v_forms_data->>'code')::INT <> 200 THEN
          RAISE EXCEPTION 'get_all_forms_with_fields failed: %', v_forms_data->>'message';
    END IF;

    v_orders_data:=jsonb_set(v_orders_data,'{data,orders}',coalesce((SELECT jsonb_agg(o) FROM jsonb_array_elements(v_orders_data#>'{data,orders}') o WHERE o->>'state' IS DISTINCT FROM 'stock'),'[]'));
    IF p_notification_group IS NOT NULL THEN
      SELECT public.notification_center_order_selection(
        (v_orders_data->>'occasion_id')::bigint,p_notification_group) INTO v_notification_ids;
      -- Keep only records in the independently authorized orders response.
      SELECT coalesce(jsonb_agg(o->'id'),'[]'::jsonb) INTO v_notification_ids
      FROM jsonb_array_elements(v_orders_data#>'{data,orders}') o
      WHERE (o->>'id')::bigint IN (SELECT value::bigint FROM jsonb_array_elements_text(v_notification_ids));
    END IF;
    IF p_notification_group->>'markRead'='true' THEN
      PERFORM public.mark_notification_center_view_item_read(
        (p_notification_group->>'organization')::bigint,p_notification_group);
    END IF;
    -- No orders means no delivery status. Do not resolve an ambiguous event slug.
    RETURN (v_orders_data->'data') || jsonb_build_object('notification_order_ids',v_notification_ids,'forms', v_forms_data->'data', 'email_delivery',
      CASE WHEN jsonb_array_length(v_orders_data#>'{data,orders}') = 0
        THEN '{}'::jsonb
        ELSE public.get_order_email_summaries(
          (v_orders_data->>'occasion_id')::bigint,
          ARRAY(SELECT (ord->>'id')::bigint
            FROM jsonb_array_elements(v_orders_data#>'{data,orders}') ord))
      END);
END;
$$;


ALTER FUNCTION public.get_orders_tab_data(p_occasion_link text, p_notification_group jsonb) OWNER TO postgres;

--
-- Name: organizations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.organizations (
    id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    data jsonb,
    title text NOT NULL,
    phone_prefixes text[]
);


ALTER TABLE public.organizations OWNER TO postgres;

--
-- Name: get_organization_admin(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_organization_admin(organization_id bigint) RETURNS SETOF public.organizations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- Verify admin status
  IF public.can_manage_organization_settings(organization_id) THEN
    -- Return the organization record without server-only delivery secrets.
    RETURN QUERY
    SELECT o.id, o.created_at, o.updated_at,
      o.data - 'ONESIGNAL_REST_API_KEY', o.title, o.phone_prefixes
    FROM organizations o
    WHERE o.id = organization_id;
  ELSE
    -- Raise distinct exception or return nothing
    RAISE EXCEPTION 'Access Denied: User is not an admin of this organization.';
  END IF;
END;
$$;


ALTER FUNCTION public.get_organization_admin(organization_id bigint) OWNER TO postgres;

--
-- Name: get_organization_notification_delivery_config(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_organization_notification_delivery_config(p_organization_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM public.require_service_role();

  SELECT jsonb_build_object(
    'onesignal_app_id', o.data->>'ONESIGNAL_APP_ID',
    'onesignal_rest_api_key', s.onesignal_rest_api_key,
    'default_url', o.data->>'DEFAULT_URL'
  )
  INTO v_result
  FROM public.organizations o
  JOIN public.organization_notification_secrets s
    ON s.organization = o.id
  WHERE o.id = p_organization_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_organization_notification_delivery_config(p_organization_id bigint) OWNER TO postgres;

--
-- Name: get_pending_bank_sync_details(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pending_bank_sync_details(p_bank_account_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.require_service_role();
  RETURN (SELECT jsonb_build_object('id',id,'request',request,'payload_sha256',payload_sha256)
    FROM eshop.bank_sync_operations WHERE bank_account_id=p_bank_account_id AND operation='update_details'
    AND state IN ('pending','running','uncertain') ORDER BY created_at LIMIT 1);
END;
$$;


ALTER FUNCTION public.get_pending_bank_sync_details(p_bank_account_id bigint) OWNER TO postgres;

--
-- Name: get_pending_occasion_media_jobs(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pending_occasion_media_jobs(p_unit bigint, p_organization bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 IF NOT public.can_copy_occasion_target(p_unit) OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE insufficient_privilege USING MESSAGE='organizer manager required'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."createdAt",page."commandId"),'[]') INTO result FROM (
  SELECT command_id AS "commandId",target_occasion AS "occasionId",target_unit AS "targetUnitId",source_unit AS "unitId",state,created_at AS "createdAt"
  FROM public.occasion_media_jobs WHERE actor_id=auth.uid() AND organization=p_organization AND (source_unit=p_unit OR target_unit=p_unit) AND state='pending' ORDER BY created_at,command_id LIMIT p_limit) page;
 RETURN jsonb_build_object('items',result);
END $$;


ALTER FUNCTION public.get_pending_occasion_media_jobs(p_unit bigint, p_organization bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_private_client_sync_v1(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_private_client_sync_v1(p_context jsonb, p_known_private_vector jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_occasion bigint := (p_context->>'occasionId')::bigint;
  v_user uuid := auth.uid();
  v_components jsonb;
  v_vector jsonb;
BEGIN
  IF p_context IS NULL OR jsonb_typeof(p_context) <> 'object'
     OR octet_length(p_context::text) > 4096
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_context) key
       WHERE key NOT IN ('organizationId','occasionId'))
     OR p_known_private_vector IS NULL
     OR jsonb_typeof(p_known_private_vector) <> 'object'
     OR octet_length(p_known_private_vector::text) > 4096
     OR EXISTS (
       SELECT 1 FROM jsonb_each_text(p_known_private_vector) entry
       WHERE entry.key NOT IN ('private_program','private_profile',
         'private_inventory','private_activity','private_news','private_feedback')
         OR entry.value !~ '^[0-9]{1,19}$') THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid private sync request';
  END IF;
  IF NOT public.can_read_private_client_sync((p_context->>'organizationId')::bigint,v_occasion) THEN RETURN jsonb_build_object('code', 403); END IF;

  WITH names(component) AS (VALUES
    ('private_program'),('private_profile'),('private_inventory'),
    ('private_activity'),('private_news'),('private_feedback')
  ), heads AS (
    SELECT n.component, COALESCE(s.source_revision, 0) revision
    FROM names n LEFT JOIN public.client_sync_private_scopes s
      ON s.component=n.component AND s.occasion=v_occasion AND s.user_id=v_user
  ) SELECT jsonb_object_agg(component, revision) INTO v_vector FROM heads;

  WITH changed AS (
    SELECT key component, value::text::bigint revision FROM jsonb_each(v_vector)
    WHERE value::text::bigint > COALESCE((p_known_private_vector->>key)::bigint, -1)
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'component', c.component, 'revision', c.revision, 'payload',
    CASE c.component
      WHEN 'private_program' THEN jsonb_build_object(
        'signedIn', (SELECT COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]') FROM public.event_users eu JOIN public.events e ON e.id=eu.event WHERE eu."user"=v_user AND e.occasion=v_occasion),
        'saved', (SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event),'[]') FROM public.event_users_saved es JOIN public.events e ON e.id=es.event WHERE es."user"=v_user AND e.occasion=v_occasion))
      WHEN 'private_profile' THEN public.get_private_profile_payload_v1(
        v_occasion,v_user)
      WHEN 'private_inventory' THEN public.get_user_inventory_for_occasion_v1(v_occasion)
      WHEN 'private_activity' THEN public.get_my_events_and_activities(v_occasion,true)->'data'
      WHEN 'private_news' THEN (SELECT COALESCE(jsonb_agg(jsonb_build_object('newsId',un.news_id,'readAt',un.created_at) ORDER BY un.news_id),'[]') FROM public.user_news un WHERE un.occasion=v_occasion AND un."user"=v_user)
      WHEN 'private_feedback' THEN public.get_private_feedback_payload_v1(
        v_occasion,v_user)
    END)),'[]') INTO v_components FROM changed c;

  RETURN jsonb_build_object('code',200,'data',jsonb_build_object(
    'serverTime',clock_timestamp(),'vector',v_vector,'components',v_components));
END;
$_$;


ALTER FUNCTION public.get_private_client_sync_v1(p_context jsonb, p_known_private_vector jsonb) OWNER TO postgres;

--
-- Name: get_private_feedback_payload_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_private_feedback_payload_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',f.event,
    'rating',f.rating,'note',f.note,'data',f.data,'updatedAt',f.updated_at)
    ORDER BY f.event),'[]'::jsonb)
  FROM public.event_feedback f
  WHERE f."user"=p_user AND f.occasion=p_occasion;
$$;


ALTER FUNCTION public.get_private_feedback_payload_v1(p_occasion bigint, p_user uuid) OWNER TO postgres;

--
-- Name: get_private_profile_payload_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_private_profile_payload_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT jsonb_build_object(
    'user',(SELECT jsonb_build_object('id',u.id,'email',u.email_readonly,
      'name',u.name,'surname',u.surname,'sex',u.sex,'phone',u.phone,
      'birthDate',u.birth_date,'data',u.data) FROM public.user_info u
      WHERE u.id=p_user),
    'occasion',(SELECT jsonb_build_object('role',ou.role,'services',ou.services,
      'data',ou.data,'isEditor',ou.is_editor,
      'isEditorView',ou.is_editor_view,
      'isEditorOrder',ou.is_editor_order,
      'isEditorOrderView',ou.is_editor_order_view,
      'isApproved',ou.is_approved,'isApprover',ou.is_approver,
      'isManager',ou.is_manager,
      'isCleaningBlocked',ou.is_cleaning_blocked,
      'isCleaningCrew',ou.is_cleaning_crew,
      'isReceptionist',ou.is_receptionist) FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_user),
    'companions',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id',ui.id,'name',ui.name,'surname',COALESCE(ui.surname,''),
      'group_title',COALESCE(groups.titles,''),'origin',uc.origin,
      'can_owner_delete',uc.origin='self_created',
      'services',COALESCE(companion_membership.services,'{}'::jsonb),
      'event_ids',COALESCE((SELECT jsonb_agg(eu.event ORDER BY eu.event)
        FROM public.event_users eu JOIN public.events e ON e.id=eu.event
        WHERE eu."user"=ui.id AND e.occasion=p_occasion),'[]'::jsonb))
      ORDER BY ui.name,ui.surname,ui.id)
      FROM public.user_companions uc
      JOIN public.user_info ui ON ui.id=uc.companion
      JOIN public.occasion_users companion_membership
        ON companion_membership.occasion=uc.occasion
       AND companion_membership."user"=uc.companion
      LEFT JOIN LATERAL (SELECT string_agg(ugi.title,', ' ORDER BY ugi.title) titles
        FROM public.user_groups ug JOIN public.user_group_info ugi ON ugi.id=ug."group"
        WHERE ug."user"=uc.companion AND ugi.occasion=p_occasion
          AND ugi.type IS NULL) groups ON true
      WHERE uc.occasion=p_occasion AND uc."user"=p_user AND public.occasion_member_visible_internal(p_occasion,ui.id)),'[]'::jsonb),
    'groups',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id',g.id,'title',g.title,'description',g.description,'type',g.type,
      'data',g.data,'place',g.place,'isAdmin',mine.is_admin,
      'participants',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'userId',members."user",'isAdmin',members.is_admin,
        'name',ui.name,'surname',ui.surname) ORDER BY members."user")
        FROM public.user_groups members JOIN public.user_info ui
          ON ui.id=members."user" WHERE members."group"=g.id AND public.occasion_member_visible_internal(g.occasion,ui.id)),'[]'::jsonb),
      'placeData',(SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p.id::text),0)) FROM public.places p WHERE p.id=g.place))
      ORDER BY g.id) FROM public.user_groups mine JOIN public.user_group_info g
        ON g.id=mine."group" WHERE mine."user"=p_user
        AND g.occasion=p_occasion),'[]'::jsonb));
$$;


ALTER FUNCTION public.get_private_profile_payload_v1(p_occasion bigint, p_user uuid) OWNER TO postgres;

--
-- Name: get_product_catalog(bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_catalog(p_organization bigint, p_occasion bigint DEFAULT NULL::bigint, p_unit bigint DEFAULT NULL::bigint, p_occasion_link text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint:=p_occasion; result jsonb;
BEGIN
 IF p_occasion_link IS NOT NULL THEN
  oc:=public.resolve_occasion_link_internal(p_occasion_link);
  IF p_occasion IS NOT NULL AND oc IS DISTINCT FROM p_occasion THEN
   RAISE insufficient_privilege USING MESSAGE='product context unavailable'; END IF;
 END IF;
 PERFORM public.check_product_catalog_scope_internal(oc,p_organization,p_unit,false,true);
 result:=jsonb_build_object('occasionId',oc,'catalog',public.get_product_catalog_data_internal(oc));
 PERFORM public.check_product_catalog_scope_internal(oc,p_organization,p_unit,false,true);
 RETURN result;
END $$;


ALTER FUNCTION public.get_product_catalog(p_organization bigint, p_occasion bigint, p_unit bigint, p_occasion_link text) OWNER TO postgres;

--
-- Name: get_product_catalog_data_internal(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_catalog_data_internal(p_occasion bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  product_types json;
  products json;
  inventory_pools_data json;
  inventory_contexts_data json;
  product_inventory_contexts_data json;
  forms_data json;
  occ_id bigint := p_occasion;
  selected_ids bigint[];
  next_id bigint;
BEGIN
  IF p_limit IS NOT NULL AND (p_limit<1 OR p_limit>100) OR p_after IS NOT NULL AND p_after<1 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid catalog page';
  END IF;
  SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO selected_ids
  FROM (SELECT p.id FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
        WHERE pt.occasion=occ_id AND p.occasion=occ_id AND (p_after IS NULL OR p.id>p_after)
        ORDER BY p.id LIMIT CASE WHEN p_limit IS NULL THEN NULL ELSE p_limit+1 END) selected;
  IF cardinality(selected_ids)>p_limit THEN
    selected_ids:=selected_ids[1:p_limit];
    next_id:=selected_ids[p_limit];
  END IF;
  -- A page must never silently truncate inventory assignments. The existing
  -- product DTO supports up to 1000 assignments per product.
  IF p_limit IS NOT NULL AND EXISTS(SELECT 1 FROM eshop.product_inventory_contexts
       WHERE product=ANY(selected_ids) GROUP BY product HAVING count(*)>1000) THEN
    RAISE program_limit_exceeded USING MESSAGE='product inventory assignments exceed catalog page contract';
  END IF;

  product_types:=public.get_product_type_rows_internal(occ_id,
    CASE WHEN p_limit IS NULL THEN NULL ELSE ARRAY(SELECT product_type FROM eshop.products WHERE id=ANY(selected_ids)) END)::json;

  -- Fetch all products for the given occasion, including form IDs
  SELECT json_agg(
           json_build_object(
             'id', p.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=p.occasion AND aggregate_id=p.id::text),0),
             'title', p.title,
             'description', p.description,
             'short_title', p.data->>'short_title',
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'price_changes', (SELECT COALESCE(json_agg(pc ORDER BY pc.change_time,pc.id),'[]'::json)
               FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.change_type='products.price' AND NOT pc.applied),
             'visibility_changes', (SELECT COALESCE(json_agg(pc ORDER BY pc.change_time,pc.id),'[]'::json)
               FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.change_type='products.is_hidden' AND NOT pc.applied),
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'is_used_in_blueprint', EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product=p.id AND s.occasion=occ_id),
             'order', p."order",
             'maximum', p.maximum,
             'form_ids', (
               SELECT COALESCE(json_agg(DISTINCT ff.form ORDER BY ff.form), '[]'::json)
               FROM public.form_fields ff JOIN public.forms f ON f.id=ff.form
               WHERE ff.product_type = p.product_type AND f.occasion=occ_id
             ),
             -- These are product-ticket relationship rows, never unique people
             -- or order counts. Preserve historical all-state ordered_count.
             'ordered_count', sales.ordered_count,
             'paid_count', sales.paid_count,
             'sent_count', sales.sent_count,
             'purchased_count', sales.purchased_count
           ) ORDER BY p.id
         )
    INTO products
  FROM eshop.products p
  CROSS JOIN LATERAL (
    SELECT count(*) ordered_count,
      count(*) FILTER(WHERE o.state='paid') paid_count,
      count(*) FILTER(WHERE o.state='sent') sent_count,
      count(*) FILTER(WHERE o.state IN ('paid','sent')) purchased_count
    FROM eshop.order_product_ticket opt LEFT JOIN eshop.orders o ON o.id=opt."order"
    WHERE opt.product=p.id
  ) sales
  WHERE p.id=ANY(selected_ids);

  -- Fetch all inventory pools for the occasion
  SELECT json_agg(ip.*)
  INTO inventory_pools_data
  FROM public.inventory_pools ip
  WHERE ip.occasion = occ_id AND p_limit IS NULL;

  inventory_contexts_data:=public.get_product_context_rows_internal(occ_id,
    CASE WHEN p_limit IS NULL THEN NULL ELSE ARRAY(SELECT inventory_context FROM eshop.product_inventory_contexts WHERE product=ANY(selected_ids)) END,
    p_limit IS NULL)::json;

  -- Fetch all links between products and inventory contexts for the occasion
  SELECT json_agg(pic.*)
  INTO product_inventory_contexts_data
  FROM eshop.product_inventory_contexts pic
  JOIN eshop.products p ON pic.product = p.id
  JOIN eshop.product_types pt ON p.product_type = pt.id
  WHERE pt.occasion = occ_id AND p.id=ANY(selected_ids);

  -- Fetch only the id, title, and link for each form associated with the occasion
  SELECT json_agg(
           json_build_object(
             'id', f.id,
             'title', f.title
           )::jsonb || CASE WHEN p_limit IS NULL THEN jsonb_build_object('link',f.link) ELSE '{}'::jsonb END
         )
    INTO forms_data
  FROM public.forms f
  WHERE f.occasion = occ_id AND (p_limit IS NULL OR EXISTS(
    SELECT 1 FROM public.form_fields ff JOIN eshop.products p ON p.product_type=ff.product_type
    WHERE ff.form=f.id AND p.id=ANY(selected_ids)));
  IF p_limit IS NOT NULL AND json_array_length(coalesce(forms_data,'[]'::json))>1000 THEN
    RAISE program_limit_exceeded USING MESSAGE='form references exceed catalog page contract';
  END IF;

  RETURN json_build_object(
    'server_time', clock_timestamp(),
    'nextCursor',next_id,
    'price_waves', CASE WHEN p_limit IS NULL THEN public.get_product_price_waves_internal(occ_id)->'waves' ELSE '[]'::jsonb END,
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json),
    'inventory_pools', COALESCE(inventory_pools_data, '[]'::json),
    'inventory_contexts', COALESCE(inventory_contexts_data, '[]'::json),
    'product_inventory_contexts', COALESCE(product_inventory_contexts_data, '[]'::json),
    'forms', COALESCE(forms_data, '[]'::json)
  );
END;
$$;


ALTER FUNCTION public.get_product_catalog_data_internal(p_occasion bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_product_catalog_options(bigint, bigint, bigint, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_catalog_options(p_occasion bigint, p_organization bigint, p_unit bigint, p_kind text, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];next_id bigint;rows jsonb;
BEGIN
 IF p_kind IS NULL OR p_kind NOT IN ('product_types','inventory_contexts') OR p_limit IS NULL OR p_limit<1 OR p_limit>100
  OR p_after IS NOT NULL AND p_after<1 THEN RAISE invalid_parameter_value USING MESSAGE='invalid product option page'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 IF p_kind='product_types' THEN
  SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO ids FROM (
   SELECT id FROM eshop.product_types WHERE occasion=p_occasion AND (p_after IS NULL OR id>p_after)
   ORDER BY id LIMIT p_limit+1) selected;
 ELSE
  SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO ids FROM (
   SELECT ic.id FROM public.inventory_contexts ic JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
   WHERE ip.occasion=p_occasion AND (p_after IS NULL OR ic.id>p_after) ORDER BY ic.id LIMIT p_limit+1) selected;
 END IF;
 IF cardinality(ids)>p_limit THEN ids:=ids[1:p_limit];next_id:=ids[p_limit]; END IF;
 IF p_kind='product_types' THEN rows:=public.get_product_type_rows_internal(p_occasion,ids);
 ELSE rows:=public.get_product_context_rows_internal(p_occasion,ids); END IF;
 IF octet_length(rows::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='product option page exceeds payload limit; use a smaller limit'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'kind',p_kind,'options',rows,'nextCursor',next_id,'readAt',statement_timestamp());
END $$;


ALTER FUNCTION public.get_product_catalog_options(p_occasion bigint, p_organization bigint, p_unit bigint, p_kind text, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_product_catalog_page(bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_catalog_page(p_organization bigint, p_occasion bigint, p_unit bigint DEFAULT NULL::bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE catalog jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR p_after IS NOT NULL AND p_after<1 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid catalog page';
 END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 catalog:=public.get_product_catalog_data_internal(p_occasion,p_after,p_limit)::jsonb;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'nextCursor',catalog->'nextCursor','catalog',
   catalog-ARRAY['nextCursor','server_time','price_waves','inventory_pools']);
END $$;


ALTER FUNCTION public.get_product_catalog_page(p_organization bigint, p_occasion bigint, p_unit bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_product_context_rows_internal(bigint, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_context_rows_internal(p_occasion bigint, p_ids bigint[] DEFAULT NULL::bigint[], p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg((CASE WHEN p_editor THEN to_jsonb(ic) ELSE jsonb_build_object(
  'id',ic.id,'title',ic.title,'inventory_pool',ic.inventory_pool,'block_date',ic.block_date) END)
  ||jsonb_build_object('pool_title',ip.title,'pool_type',ip.type) ORDER BY ic.id),'[]')
 FROM public.inventory_contexts ic JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
 WHERE ip.occasion=p_occasion AND (p_ids IS NULL OR ic.id=ANY(p_ids))
$$;


ALTER FUNCTION public.get_product_context_rows_internal(p_occasion bigint, p_ids bigint[], p_editor boolean) OWNER TO postgres;

--
-- Name: get_product_for_authoring_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_for_authoring_v1(p_product bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint;
BEGIN
 SELECT occasion INTO oc FROM eshop.products WHERE id=p_product;
 IF auth.uid() IS NULL OR oc IS NULL OR public.can_read_orders(oc) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order editor view required'; END IF;
 RETURN (SELECT jsonb_build_object('id',p.id,'occasion',p.occasion,'product_type',p.product_type,
  'title',p.title,'description',p.description,'price',p.price,'currency_code',p.currency_code,'data',p.data,
  'is_hidden',p.is_hidden,'order',p."order",'maximum',p.maximum,'aggregate_version',coalesce(v.version,0),
  'inventory_contexts',coalesce((SELECT jsonb_agg(jsonb_build_object('inventory_context_id',pic.inventory_context,'quantity',pic.quantity) ORDER BY pic.inventory_context)
    FROM eshop.product_inventory_contexts pic WHERE pic.product=p.id),'[]'))
 FROM eshop.products p LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='product' AND v.scope_type='occasion'
 AND v.scope_id=p.occasion AND v.aggregate_id=p.id::text WHERE p.id=p_product);
END $$;


ALTER FUNCTION public.get_product_for_authoring_v1(p_product bigint) OWNER TO postgres;

--
-- Name: get_product_price_waves_internal(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_price_waves_internal(p_occasion bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[]; next_id bigint; waves jsonb;
BEGIN
 IF p_limit IS NOT NULL AND (p_limit<1 OR p_limit>100) OR p_after IS NOT NULL AND p_after<1 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid wave page'; END IF;
 SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) INTO ids FROM (
  SELECT w.id FROM eshop.product_price_waves w WHERE w.occasion=p_occasion AND (p_after IS NULL OR w.id>p_after)
   AND (w.change_time>statement_timestamp() OR EXISTS(SELECT 1 FROM eshop.planned_changes pc WHERE pc.wave_id=w.id AND NOT pc.applied))
   ORDER BY w.id LIMIT CASE WHEN p_limit IS NULL THEN NULL ELSE p_limit+1 END) selected;
 IF cardinality(ids)>p_limit THEN ids:=ids[1:p_limit];next_id:=ids[p_limit]; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',w.id,'occasion',w.occasion,'change_time',w.change_time,'revision',w.revision,
  'pending_product_count',counts.products,'pending_change_count',counts.pending,'applied_change_count',counts.applied) ORDER BY w.id),'[]') INTO waves
 FROM eshop.product_price_waves w CROSS JOIN LATERAL (
  SELECT count(DISTINCT subject_id) FILTER(WHERE NOT applied) products,
    count(*) FILTER(WHERE NOT applied) pending,count(*) FILTER(WHERE applied) applied
  FROM eshop.planned_changes WHERE wave_id=w.id) counts WHERE w.id=ANY(ids);
 RETURN jsonb_build_object('waves',waves,'nextCursor',next_id);
END $$;


ALTER FUNCTION public.get_product_price_waves_internal(p_occasion bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_product_schedule(bigint, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_schedule(p_occasion bigint, p_organization bigint, p_unit bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_limit IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='bounded wave page required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 result:=jsonb_build_object('occasionId',p_occasion)||public.get_product_price_waves_internal(p_occasion,p_after,p_limit);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,false,true);
 RETURN result;
END $$;


ALTER FUNCTION public.get_product_schedule(p_occasion bigint, p_organization bigint, p_unit bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_product_type_rows_internal(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_product_type_rows_internal(p_occasion bigint, p_ids bigint[] DEFAULT NULL::bigint[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',pt.id,'type',pt.type,'title',pt.title) ORDER BY pt.id),'[]')
 FROM eshop.product_types pt WHERE pt.occasion=p_occasion AND (p_ids IS NULL OR pt.id=ANY(p_ids))
$$;


