--
-- Name: get_products_and_types(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_products_and_types(p_occasion_id bigint) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  product_types json;
  products json;
  offered_type_ids bigint[];
  referenced_type_ids bigint[];
  form_metadata jsonb;
BEGIN
  SELECT array_agg(DISTINCT ff.product_type) FILTER(WHERE NOT COALESCE(ff.is_hidden,false)),array_agg(DISTINCT ff.product_type) INTO offered_type_ids,referenced_type_ids FROM public.form_fields ff JOIN public.forms f ON f.id=ff.form WHERE f.occasion=p_occasion_id;
  SELECT jsonb_object_agg(type_id,refs) INTO form_metadata FROM (SELECT ff.product_type type_id,jsonb_agg(jsonb_build_object('title',COALESCE(f.title,ff.title),'fieldTitle',ff.title,'hidden',COALESCE(ff.is_hidden,false)) ORDER BY ff.id) refs FROM public.form_fields ff JOIN public.forms f ON f.id=ff.form WHERE f.occasion=p_occasion_id AND ff.product_type IS NOT NULL GROUP BY ff.product_type) metadata;
  -- Fetch product types filtered by occasion.
  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type,
             'title',pt.title,
             'occasion',pt.occasion,
             'admission',EXISTS(SELECT 1 FROM eshop.products ap JOIN eshop.spots asp ON asp.product=ap.id WHERE ap.product_type=pt.id),
             'forms',COALESCE(form_metadata->pt.id::text,'[]'::jsonb),
             'referenced',COALESCE(pt.id=ANY(referenced_type_ids),false),
             'offered',COALESCE(pt.id=ANY(offered_type_ids),false)
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = p_occasion_id;

  -- Fetch products whose product_type is in the filtered product types.
  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'short_title', p.data->>'short_title',
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'order',p."order"
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = p_occasion_id
  );

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


ALTER FUNCTION public.get_products_and_types(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: get_products_and_types_for_edit(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_products_and_types_for_edit(occasion_link text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint;
BEGIN
 SELECT id INTO oc FROM public.occasions
 WHERE id=public.resolve_occasion_link_internal(occasion_link)
 AND organization=(SELECT ui.organization FROM public.user_info ui WHERE ui.id=auth.uid());
 IF oc IS NULL THEN RAISE EXCEPTION 'Occasion not found for link: %',occasion_link; END IF;
 IF public.can_read_orders(oc) IS DISTINCT FROM TRUE THEN
  RETURN json_build_object('code',403,'message','User is not authorized to view this.');
 END IF;
 RETURN public.get_product_catalog_data_internal(oc);
END $$;


ALTER FUNCTION public.get_products_and_types_for_edit(occasion_link text) OWNER TO postgres;

--
-- Name: get_products_and_types_for_occasion(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_products_and_types_for_occasion(form_link text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  product_types json;
  products json;
  occ_id bigint;
BEGIN
  PERFORM check_is_editor_order_view_via_form_link(form_link);

  SELECT f.occasion
    INTO occ_id
  FROM public.forms f
  WHERE f.id = public.resolve_form_link_internal(form_link);

  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type,
             'title', pt.title
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = occ_id;

  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'description', p.description,
             'title_short', p.title_short,
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'order', p."order",
             'maximum', p.maximum,
             'ordered_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               WHERE opt.product = p.id
             ),
             'paid_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'paid'
             ),
             'sent_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'sent'
             )
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = occ_id
  );

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


ALTER FUNCTION public.get_products_and_types_for_occasion(form_link text) OWNER TO postgres;

--
-- Name: get_products_and_types_from_occasion(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_products_and_types_from_occasion(form_link text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  product_types json;
  products json;
  occ_id bigint;
BEGIN
  PERFORM check_is_editor_order_view_via_form_link(form_link);

  SELECT f.occasion
    INTO occ_id
  FROM public.forms f
  WHERE f.id = public.resolve_form_link_internal(form_link);

  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = occ_id;

  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'title_short', p.title_short,
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'order', p."order",
             'maximum', p.maximum,
             'ordered_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               WHERE opt.product = p.id
             ),
             'paid_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'paid'
             ),
             'sent_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'sent'
             )
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = occ_id
  );

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


