--
-- Name: get_resources_for_inventory_pool(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_resources_for_inventory_pool(p_inventory_pool_id bigint) RETURNS SETOF public.resources
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion_id BIGINT;
BEGIN
  -- First, find the occasion associated with the requested inventory pool.
  -- This is crucial for the permission check.
  SELECT p.occasion
  INTO v_occasion_id
  FROM public.inventory_pools p
  WHERE p.id = p_inventory_pool_id;

  -- If the pool doesn't exist, we can't proceed.
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory Pool with ID % not found.', p_inventory_pool_id;
  END IF;

  -- If the pool isn't linked to an occasion, deny access as we cannot check permissions.
  IF v_occasion_id IS NULL THEN
    RAISE EXCEPTION 'The parent Inventory Pool with ID % is not linked to an occasion.', p_inventory_pool_id;
  END IF;

  -- Perform the security check to ensure the calling user has editor rights on the occasion.
  -- This prevents users from one occasion from viewing data from another.
  PERFORM public.check_is_editor_order_view_on_occasion(v_occasion_id);

  -- If the permission check is successful, return all resources
  -- that belong to the specified inventory pool.
  RETURN QUERY
  SELECT *
  FROM public.resources
  WHERE inventory_pool = p_inventory_pool_id
  ORDER BY id;
END;
$$;


ALTER FUNCTION public.get_resources_for_inventory_pool(p_inventory_pool_id bigint) OWNER TO postgres;

--
-- Name: get_resources_for_inventory_pool_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_resources_for_inventory_pool_v1(p_inventory_pool_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_occasion bigint; v_result jsonb;
BEGIN
  SELECT ip.occasion INTO v_occasion FROM public.inventory_pools ip
    WHERE ip.id=p_inventory_pool_id;
  IF v_occasion IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='inventory pool not found'; END IF;
  PERFORM public.check_is_editor_order_view_on_occasion(v_occasion);
  SELECT COALESCE(jsonb_agg(to_jsonb(r)||jsonb_build_object(
    'aggregate_version',COALESCE(v.version,0)) ORDER BY r.id),'[]'::jsonb)
    INTO v_result FROM public.resources r
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='resource'
      AND v.scope_type='occasion' AND v.scope_id=v_occasion
      AND v.aggregate_id=r.id::text
    WHERE r.inventory_pool=p_inventory_pool_id;
  RETURN v_result;
END; $$;


ALTER FUNCTION public.get_resources_for_inventory_pool_v1(p_inventory_pool_id bigint) OWNER TO postgres;

--
-- Name: get_sale_opening_email_context(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sale_opening_email_context(p_message uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE m public.email_messages; s public.sale_opening_subscriptions; c public.sale_opening_campaigns; f public.forms; o public.occasions;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT m FROM public.email_messages WHERE message_id=p_message AND message_kind ='sale_opening_opened';
 IF NOT public.sale_opening_intent_valid_internal(m) THEN RAISE invalid_parameter_value USING MESSAGE='sale_opening_intent_invalid'; END IF;
 SELECT * INTO STRICT s FROM public.sale_opening_subscriptions WHERE id=(m.data->>'subscription_id')::uuid;
 SELECT * INTO STRICT c FROM public.sale_opening_campaigns WHERE id=s.campaign_id;
 SELECT * INTO STRICT f FROM public.forms WHERE id=c.form_id;
 SELECT * INTO STRICT o FROM public.occasions WHERE id=f.occasion;
 RETURN jsonb_build_object('organization',o.organization,'occasion',o.id,'unit',o.unit,'recipient',s.email_normalized,
  'occasionTitle',o.title,'hasTickets',public.sale_opening_has_tickets_internal(f.id),'formLink',f.link,'lang',s.lang,'tone',public.get_effective_form_data(f.id)->>'communication_tone',
  'webLink',(SELECT data->>'DEFAULT_URL' FROM public.organizations WHERE id=o.organization),
  'replyTo',coalesce(o.data->>'reply_to',(SELECT data->>'reply_to' FROM public.units WHERE id=o.unit)),
  'capabilities',(SELECT jsonb_object_agg(purpose,jsonb_build_object('hash',token_hash,'envelope',envelope))
   FROM public.sale_opening_capabilities WHERE subscription_id=s.id AND source_version=s.version AND revoked_at IS NULL AND expires_at>statement_timestamp()));
END $$;


ALTER FUNCTION public.get_sale_opening_email_context(p_message uuid) OWNER TO postgres;

--
-- Name: get_sale_opening_projection_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sale_opening_projection_internal(p_form bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH input AS (SELECT f.*,public.get_effective_form_data(f.id) metadata,
  public.get_form_availability_snapshot_internal(f.id) availability,c.phase
  FROM public.forms f LEFT JOIN public.sale_opening_campaigns c ON c.form_id=f.id WHERE f.id=p_form),
 reason AS (SELECT *,CASE
  WHEN public.is_demo_occasion(occasion) OR phase IS NULL OR phase<>'armed' OR
   NOT coalesce((metadata#>>'{sale_opening_notifications,enabled}')::boolean,false) THEN 'disabled'
  WHEN coalesce((metadata#>>'{sale_opening_notifications,collection_paused}')::boolean,false) THEN 'paused'
  WHEN NOT is_open THEN 'manual_closed'
  WHEN availability->>'gate'<>'before_start' THEN 'not_before_start'
  ELSE NULL END unavailable FROM input)
 SELECT jsonb_build_object('canSubscribe',unavailable IS NULL,'hasTickets',public.sale_opening_has_tickets_internal(id),'reason',unavailable,
  'startAt',availability->'startAt','timeZone',public.get_waitlist_form_timezone_internal(id),'serverTime',statement_timestamp()) FROM reason;
$$;


ALTER FUNCTION public.get_sale_opening_projection_internal(p_form bigint) OWNER TO postgres;

--
-- Name: get_sale_opening_subscribers(bigint, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sale_opening_subscribers(p_form bigint, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM public.forms WHERE id=p_form;
 IF occ IS NULL OR NOT public.can_read_sale_opening_subscribers(occ) THEN RAISE insufficient_privilege USING MESSAGE='subscriber contacts required'; END IF;
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid subscriber page'; END IF;
 RETURN coalesce((SELECT jsonb_agg(row ORDER BY id) FROM (
 SELECT s.id,s.email_normalized email,s.lang,s.state,s.created_at,
  (SELECT jsonb_agg(jsonb_build_object('message_id',m.message_id,'state',public.email_reporting_state(m),'message_kind',m.message_kind) ORDER BY m.created_at DESC)
   FROM public.email_messages m WHERE m.data->>'subscription_id'=s.id::text AND m.message_kind ='sale_opening_opened') messages
 FROM public.sale_opening_subscriptions s JOIN public.sale_opening_campaigns c ON c.id=s.campaign_id
 WHERE c.form_id=p_form AND (p_after IS NULL OR s.id>p_after) ORDER BY s.id LIMIT p_limit) row),'[]');
END $$;


ALTER FUNCTION public.get_sale_opening_subscribers(p_form bigint, p_after uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_sale_opening_summary(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sale_opening_summary(p_form bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occ bigint; c public.sale_opening_campaigns;
BEGIN
 SELECT occasion INTO occ FROM public.forms WHERE id=p_form;
 IF occ IS NULL OR NOT public.can_author_forms(occ) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 SELECT * INTO c FROM public.sale_opening_campaigns WHERE form_id=p_form;
 RETURN jsonb_build_object('phase',c.phase,'openedAt',c.opened_at,
 'subscribers',coalesce((SELECT jsonb_object_agg(state,n) FROM (SELECT state,count(*) n FROM public.sale_opening_subscriptions WHERE campaign_id=c.id GROUP BY state) x),'{}'),
 'messages',coalesce((SELECT jsonb_object_agg(state,n) FROM (SELECT public.email_reporting_state(m) state,count(*) n FROM public.email_messages m
 WHERE m.message_kind='sale_opening_opened' AND m.data->>'campaign_id'=c.id::text GROUP BY public.email_reporting_state(m)) x),'{}'));
END $$;


ALTER FUNCTION public.get_sale_opening_summary(p_form bigint) OWNER TO postgres;

--
-- Name: get_scan_code(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scan_code(occasion_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    occasion_id BIGINT;
    current_scan_code TEXT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- 2. Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT can_read_orders(occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view scan code for this occasion.'
        );
    END IF;

    -- 4. Retrieve the scan_code from the occasions_hidden table via the foreign key
    SELECT oh.secret
    INTO current_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    -- 4.a. Handle case where scan_code is not found
    IF current_scan_code IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Scan code not found for the specified occasion.'
        );
    END IF;

    -- 5. Return the scan_code
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code retrieved successfully.',
        'scan_code', current_scan_code
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;


ALTER FUNCTION public.get_scan_code(occasion_link text) OWNER TO postgres;

--
-- Name: get_scanner_event_history(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scanner_event_history(p_occasion bigint, p_before timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_is_editor_order_on_occasion(p_occasion);
 SELECT coalesce(jsonb_agg(item),'[]'::jsonb) INTO result FROM (
 SELECT jsonb_build_object('receipt',op.receipt,'captured_at',op.payload->'captured_at','offline',op.payload->>'snapshot_id' IS NOT NULL,'resolved',r.operation_id IS NOT NULL) item
 FROM public.scanner_operations op LEFT JOIN public.scanner_conflict_resolutions r ON r.operation_id=op.operation_id
 WHERE op.occasion_id=p_occasion AND op.committed_at<p_before ORDER BY op.committed_at DESC LIMIT 50) rows;
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $$;


ALTER FUNCTION public.get_scanner_event_history(p_occasion bigint, p_before timestamp with time zone) OWNER TO postgres;

