--
-- Name: get_scanner_receipts(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scanner_receipts(p_session uuid, p_token text, p_operation_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_sessions; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token,true);
 IF coalesce(array_length(p_operation_ids,1),0)>50 THEN RAISE invalid_parameter_value; END IF;
 -- Expired/revoked devices can reconcile their immutable history, never perform a new write.
 SELECT coalesce(jsonb_agg(receipt),'[]'::jsonb) INTO result FROM public.scanner_operations WHERE session_id=p_session AND operation_id=ANY(p_operation_ids);
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $$;


ALTER FUNCTION public.get_scanner_receipts(p_session uuid, p_token text, p_operation_ids uuid[]) OWNER TO postgres;

--
-- Name: get_scanner_settings(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scanner_settings(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_settings;
BEGIN
 PERFORM public.scanner_require_settings_editor_internal(p_occasion);
 INSERT INTO public.scanner_settings(occasion_id,config) VALUES(p_occasion,public.scanner_default_settings_internal(p_occasion)) ON CONFLICT DO NOTHING;
 SELECT * INTO s FROM public.scanner_settings WHERE occasion_id=p_occasion;
 RETURN jsonb_build_object('code',200,'data',jsonb_build_object('revision',s.revision,'config',s.config,
 'occasion_link',(SELECT link FROM public.occasions WHERE id=p_occasion),'occasion_title',(SELECT title FROM public.occasions WHERE id=p_occasion),
 'products',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'type_id',p.product_type,'type_title',pt.title) ORDER BY p."order",p.id),'[]'::jsonb) FROM eshop.products p LEFT JOIN eshop.product_types pt ON pt.id=p.product_type WHERE p.occasion=p_occasion),
 'fields',(SELECT coalesce(jsonb_agg(jsonb_build_object('field_id',ff.id,'form_id',ff.form,'label',ff.title,'type',ff.type,'form_title',coalesce(nullif(btrim(fm.title),''),fm.link),'source',CASE WHEN ff.is_ticket_field THEN 'ticket_field' ELSE 'order_field' END) ORDER BY fm.id,ff."order",ff.id),'[]'::jsonb)
 FROM public.form_fields ff JOIN public.forms fm ON fm.id=ff.form
 WHERE fm.occasion=p_occasion AND NOT ff.is_hidden
 -- Identity, notes, seats and purchased products already have dedicated presentation.
 AND ff.type IN ('text','email','phone','city','birth_year','birth_date','address','nationality','sex','id_document','select_one','select_many')
 AND (NOT ff.is_ticket_field OR EXISTS(SELECT 1 FROM public.form_fields parent WHERE parent.form=fm.id AND parent.type='ticket' AND NOT parent.is_hidden)))),'server_time',now());
END $$;


ALTER FUNCTION public.get_scanner_settings(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_scanner_snapshot_page(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scanner_snapshot_page(p_session uuid, p_token text, p_snapshot uuid, p_page integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_sessions; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 SELECT jsonb_build_object('payload_text',pg.payload_text,'digest',pg.digest,'page_index',pg.page_index) INTO result
 FROM public.scanner_snapshot_pages pg JOIN public.scanner_snapshots sn ON sn.id=pg.snapshot_id
 WHERE sn.id=p_snapshot AND sn.session_id=p_session AND sn.expires_at>now() AND pg.page_index=p_page;
 RETURN jsonb_build_object('code',CASE WHEN result IS NULL THEN 404 ELSE 200 END,'data',result,'server_time',now());
END $$;


ALTER FUNCTION public.get_scanner_snapshot_page(p_session uuid, p_token text, p_snapshot uuid, p_page integer) OWNER TO postgres;

--
-- Name: get_scanner_summary(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_scanner_summary(p_session uuid, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_sessions; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 WITH eligible AS MATERIALIZED (
 SELECT t.id,t.state FROM eshop.tickets t WHERE t.occasion=s.occasion_id AND t.ticket_symbol IS NOT NULL
 AND t.state IN ('used','paid','sent','ordered') AND EXISTS(SELECT 1 FROM eshop.order_product_ticket z WHERE z.ticket=t.id)
 AND NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket z JOIN eshop.orders o ON o.id=z."order" WHERE z.ticket=t.id AND (o.state IN ('stock','storno','waitlisted','preparing_payment') OR o.occasion<>s.occasion_id)))
 SELECT jsonb_build_object('used_current',count(*) FILTER(WHERE state='used'),'unused_eligible',count(*) FILTER(WHERE state IN ('paid','sent')),
 'eligible_total',count(*) FILTER(WHERE state IN ('used','paid','sent')),'unpaid_conditional',count(*) FILTER(WHERE state='ordered'),
 -- Count the same ticket population as the offline projection, including unpaid/stock records.
 'snapshot_ticket_count',(SELECT count(*) FROM eshop.tickets t WHERE t.occasion=s.occasion_id
 AND EXISTS(SELECT 1 FROM eshop.order_product_ticket z JOIN eshop.orders o ON o.id=z."order" WHERE z.ticket=t.id)),
 'definition_version',1,'definition','used + paid/sent; excludes conditional unpaid, cancelled and waitlisted',
 'server_time',now(),'settings_revision',(SELECT revision FROM public.scanner_settings WHERE occasion_id=s.occasion_id)) INTO result FROM eligible;
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $$;


ALTER FUNCTION public.get_scanner_summary(p_session uuid, p_token text) OWNER TO postgres;

--
-- Name: get_seating_transition_context(uuid, text, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_seating_transition_context(p_transition uuid, p_search text DEFAULT ''::text, p_category text DEFAULT NULL::text, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; rows_data jsonb; totals jsonb; cohort jsonb; seats jsonb; compat jsonb; lim integer:=least(greatest(coalesce(p_limit,50),1),200); last_id bigint; read_holders boolean;
BEGIN
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition;
 IF tr.id IS NULL OR NOT public.can_read_seating_status(tr.occasion) THEN RAISE insufficient_privilege USING MESSAGE='seating access required'; END IF;
 IF length(coalesce(p_search,''))>256 THEN RAISE invalid_parameter_value USING MESSAGE='search too long'; END IF;
 read_holders:=coalesce(public.can_read_orders(tr.occasion),false);
 WITH a AS MATERIALIZED(SELECT * FROM public.seating_admissions_internal(p_transition))
 SELECT jsonb_build_object('unassigned',count(*) FILTER(WHERE category='unassigned'),'assigned',count(*) FILTER(WHERE category='assigned'),
 'standing',count(*) FILTER(WHERE category='standing'),'blocked',count(*) FILTER(WHERE category='blocked'),'waiting',count(*) FILTER(WHERE category='waiting'),'offered',count(*) FILTER(WHERE category='offered')) INTO totals FROM a;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'formId',form,'revision',revision) ORDER BY id),'[]') INTO cohort
 FROM public.form_seating_transitions WHERE blueprint=tr.blueprint AND state=tr.state;
 rows_data:='[]';
 IF read_holders THEN
 WITH page AS(SELECT * FROM public.seating_admissions_internal(p_transition) WHERE (p_after IS NULL OR ticket_id>p_after)
 AND (p_category IS NULL OR category=p_category) AND (coalesce(p_search,'')='' OR concat_ws(' ',holder,ticket_symbol,order_symbol,ticket_id::text,order_id::text) ILIKE '%'||p_search||'%') ORDER BY ticket_id LIMIT lim)
 SELECT coalesce(jsonb_agg(jsonb_build_object('ticketId',ticket_id,'admissionItemId',item_id,'orderId',order_id,'formId',form_id,'productId',product_id,'productTitle',product_title,
 'spotId',spot_id,'category',category,'reason',reason,'ticketSymbol',ticket_symbol,'orderSymbol',order_symbol,'holder',holder) ORDER BY ticket_id),'[]'),CASE WHEN count(*)=lim THEN max(ticket_id) END INTO rows_data,last_id FROM page;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'productId',s.product,'available',s.order_product_ticket IS NULL AND NOT sb.blocked AND NOT coalesce(s.secret_expiration_time>clock_timestamp() AND s.secret IS NOT NULL,false),
 'reason',CASE WHEN sb.blocked THEN 'SEAT_UNAVAILABLE' WHEN s.order_product_ticket IS NOT NULL THEN 'SEAT_UNAVAILABLE' WHEN s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp() THEN 'HOLD_ACTIVE' END,
 'unitSpotIds',public.blueprint_selection_unit_spots_internal(s.id)) ORDER BY s.id),'[]') INTO seats
 FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots s ON s.id=sb.spot WHERE sb.blueprint=tr.blueprint;
 WITH a AS MATERIALIZED(SELECT * FROM public.seating_admissions_internal(p_transition))
 SELECT coalesce(jsonb_agg(jsonb_build_object('productId',product_id,'productTitle',product_title,'admissions',n,'seats',seat_count,'standing',area_count>0,
 'reason',CASE WHEN seat_count>0 AND area_count>0 THEN 'PLACEMENT_MODE_AMBIGUOUS' WHEN seat_count=0 AND area_count=0 THEN 'PRODUCT_MISMATCH' WHEN seat_count>0 AND seat_count<n THEN 'INVENTORY_CONFLICT' END) ORDER BY product_id),'[]') INTO compat
 FROM (SELECT product_id,max(product_title) product_title,count(*) n,
 (SELECT count(*) FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots s ON s.id=sb.spot WHERE sb.blueprint=tr.blueprint AND s.product=a.product_id AND NOT sb.blocked) seat_count,
 (SELECT count(*) FROM eshop.blueprint_area_bindings ab WHERE ab.blueprint=tr.blueprint AND ab.product=a.product_id) area_count
 FROM a WHERE category NOT IN ('waiting','offered') AND product_id IS NOT NULL GROUP BY product_id) q;
 RETURN jsonb_build_object('code',200,'data',jsonb_build_object('transitionId',tr.id,'blueprintId',tr.blueprint,'state',tr.state,'revision',tr.revision,
 'layoutRevision',(SELECT layout_revision FROM eshop.blueprints WHERE id=tr.blueprint),'cohort',cohort,'counts',totals,'items',rows_data,'nextCursor',last_id,'seats',seats,'compatibility',compat,
 'publicationAvailable',coalesce(public.can_author_forms(tr.occasion),false),'capabilities',jsonb_build_object('configure',coalesce(public.can_author_forms(tr.occasion),false),'readHolders',read_holders,'assign',public.can_assign_existing_admissions(tr.occasion))));
END $$;


ALTER FUNCTION public.get_seating_transition_context(p_transition uuid, p_search text, p_category text, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_seating_workspace(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_seating_workspace(p_occasion bigint, p_blueprint bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE bp bigint; plans jsonb; trs jsonb; forms_data jsonb; valid boolean; status text;
BEGIN
 IF NOT public.can_read_seating_status(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='seating access required'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'valid',coalesce(layout->>'schemaVersion'='2',false)) ORDER BY id),'[]') INTO plans FROM eshop.blueprints WHERE occasion=p_occasion;
 bp:=p_blueprint;
 IF bp IS NULL AND jsonb_array_length(plans)=1 THEN bp:=(plans->0->>'id')::bigint; END IF;
 IF bp IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=bp AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='seating access required'; END IF;
 SELECT layout->>'schemaVersion'='2' INTO valid FROM eshop.blueprints WHERE id=bp;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'formId',form,'blueprintId',blueprint,'state',state,'revision',revision) ORDER BY started_at DESC),'[]') INTO trs
 FROM public.form_seating_transitions WHERE occasion=p_occasion AND blueprint=bp AND state<>'cancelled';
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'link',f.link,'transitionId',tr.id,'activeBlueprintId',f.blueprint,
 'canStart',coalesce(public.can_author_forms(p_occasion),false) AND f.blueprint IS NULL AND tr.id IS NULL AND coalesce(valid,false)
 AND NOT EXISTS(SELECT 1 FROM public.forms live WHERE live.blueprint=bp),
 'reason',CASE WHEN f.blueprint IS NOT NULL OR EXISTS(SELECT 1 FROM public.forms live WHERE live.blueprint=bp) THEN 'TARGET_ALREADY_PUBLIC'
 WHEN tr.id IS NOT NULL AND tr.blueprint IS DISTINCT FROM bp THEN 'MODE_CHANGED' WHEN NOT coalesce(valid,false) THEN 'BLUEPRINT_LAYOUT_MIGRATION_REQUIRED' END) ORDER BY f.id),'[]') INTO forms_data
 FROM public.forms f LEFT JOIN public.form_seating_transitions tr ON tr.form=f.id AND tr.state='organizer_managed' WHERE f.occasion=p_occasion;
 status:=CASE WHEN bp IS NULL THEN 'choose_plan' WHEN NOT coalesce(valid,false) THEN 'repair_plan'
 WHEN EXISTS(SELECT 1 FROM public.form_seating_transitions WHERE blueprint=bp AND state='organizer_managed') THEN 'organizer_managed'
 WHEN EXISTS(SELECT 1 FROM public.form_seating_transitions WHERE blueprint=bp AND state='published') OR EXISTS(SELECT 1 FROM public.forms live WHERE live.blueprint=bp) THEN 'published'
 WHEN jsonb_array_length(forms_data)=0 THEN 'no_source' ELSE 'choose_plan' END;
 RETURN jsonb_build_object('code',200,'data',jsonb_build_object('blueprintId',bp,'plans',plans,'forms',forms_data,'transitions',trs,'status',status,
 'capabilities',jsonb_build_object('configure',coalesce(public.can_author_forms(p_occasion),false),'readHolders',coalesce(public.can_read_orders(p_occasion),false),'assign',public.can_assign_existing_admissions(p_occasion))));
END $$;


ALTER FUNCTION public.get_seating_workspace(p_occasion bigint, p_blueprint bigint) OWNER TO postgres;

--
-- Name: get_setup_payment_options(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_setup_payment_options(p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts; r record; recipients jsonb; result jsonb:='{}';
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_draft;
 IF d.id IS NULL OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit)
  OR NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=auth.uid() AND organization=d.organization) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 FOR r IN SELECT provider_key FROM eshop.payment_providers WHERE handler IS NOT NULL ORDER BY provider_key LOOP
  BEGIN
   recipients:=public.payment_provider_call_internal(r.provider_key,'setup_recipients',jsonb_build_object('unitId',d.unit));
   IF jsonb_typeof(recipients) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'PAYMENT_PROVIDER_PROJECTION_INVALID'; END IF;
  EXCEPTION WHEN OTHERS THEN recipients:='[]'; END;
  result:=result||jsonb_build_object(r.provider_key,recipients);
 END LOOP;
 RETURN jsonb_build_object('providerRecipients',result,'policy',public.payment_sale_policy_internal());
END $$;


ALTER FUNCTION public.get_setup_payment_options(p_draft uuid) OWNER TO postgres;

--
-- Name: get_sign_in_recipient_context_v1(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
