--
-- Name: get_speakers(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_speakers(p_occasion bigint, p_include_description boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    speakersData      JSONB;
    topicsData        JSONB;
    topicLinksData    JSONB;
    eventSpeakersData JSONB;
BEGIN
    -- (a) visible speakers, description only on request (payload size)
    SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id',          s.id,
        'title',       s.title,
        'subtitle',    s.subtitle,
        'description', CASE WHEN p_include_description THEN s.description ELSE NULL END,
        'image',       s.image,
        'order',       s."order",
        'updated_at',  s.updated_at
    )) ORDER BY s."order", s.title)
    INTO speakersData
    FROM public.speakers s
    WHERE s.occasion = p_occasion
      AND s.is_hidden = FALSE;

    -- (b) visible area catalog (no code/key — only the hidden id)
    SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id',    t.id,
        'title', t.title,
        'order', t."order"
    )) ORDER BY t."order", t.title)
    INTO topicsData
    FROM public.speaker_topics t
    WHERE t.occasion = p_occasion
      AND t.is_hidden = FALSE;

    -- (c) competence links restricted to visible speakers and topics
    SELECT jsonb_agg(jsonb_build_object(
        'speaker', stl.speaker,
        'topic',   stl.topic
    ))
    INTO topicLinksData
    FROM public.speaker_topic_links stl
    JOIN public.speakers s ON s.id = stl.speaker
    JOIN public.speaker_topics t ON t.id = stl.topic
    WHERE s.occasion = p_occasion AND s.is_hidden = FALSE
      AND t.occasion = p_occasion AND t.is_hidden = FALSE;

    -- (d) event links restricted to visible speakers and non-hidden events
    SELECT jsonb_agg(jsonb_build_object(
        'event',   es.event,
        'speaker', es.speaker
    ))
    INTO eventSpeakersData
    FROM public.event_speakers es
    JOIN public.speakers s ON s.id = es.speaker
    JOIN public.events e ON e.id = es.event
    WHERE s.occasion = p_occasion AND s.is_hidden = FALSE
      AND e.occasion = p_occasion AND e.is_hidden = FALSE;

    RETURN jsonb_build_object(
      'code', 200,
      'data', jsonb_build_object(
        'speakers',            COALESCE(speakersData,      '[]'::jsonb),
        'speaker_topics',      COALESCE(topicsData,        '[]'::jsonb),
        'speaker_topic_links', COALESCE(topicLinksData,    '[]'::jsonb),
        'event_speakers',      COALESCE(eventSpeakersData, '[]'::jsonb)
      )
    );
END;
$$;


ALTER FUNCTION public.get_speakers(p_occasion bigint, p_include_description boolean) OWNER TO postgres;

--
-- Name: get_speakers_editor_bundle_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_speakers_editor_bundle_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_speakers jsonb; v_topics jsonb;
BEGIN
  IF NOT public.can_read_speakers_editor(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(q.value ORDER BY q.sort_order,q.sort_title),'[]'::jsonb)
    INTO v_speakers FROM (
    SELECT s."order" sort_order,s.title sort_title,
      to_jsonb(s)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0),
        'topics',COALESCE((SELECT jsonb_agg(l.topic ORDER BY l.topic)
          FROM public.speaker_topic_links l WHERE l.speaker=s.id),'[]'::jsonb),
        'events',COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id',e.id,'title',e.title,'start_time',e.start_time,
          'end_time',e.end_time,'max_participants',e.max_participants,
          'occupied',(SELECT count(*) FROM public.event_users eu WHERE eu.event=e.id),
          'is_counseling_slot',COALESCE((e.data->>'is_counseling_slot')::boolean,false),
          'aggregate_version',COALESCE(ev.version,0)) ORDER BY e.start_time,e.id)
          FROM public.event_speakers es JOIN public.events e ON e.id=es.event
          LEFT JOIN public.client_aggregate_versions ev ON ev.aggregate_type='event'
            AND ev.scope_type='occasion' AND ev.scope_id=p_occasion
            AND ev.aggregate_id=e.id::text WHERE es.speaker=s.id),'[]'::jsonb)
      ) value
    FROM public.speakers s LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='speaker' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=s.id::text
    WHERE s.occasion=p_occasion
  ) q;
  SELECT COALESCE(jsonb_agg(to_jsonb(t)||jsonb_build_object(
      'aggregate_version',COALESCE(v.version,0)) ORDER BY t."order",t.title,t.id),
      '[]'::jsonb) INTO v_topics
  FROM public.speaker_topics t LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='speaker_topic' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=t.id::text
  WHERE t.occasion=p_occasion;
  RETURN jsonb_build_object('code',200,'data',jsonb_build_object(
    'speakers',v_speakers,'speaker_topics',v_topics));
END; $$;


ALTER FUNCTION public.get_speakers_editor_bundle_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_speakers_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_speakers_for_edit(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_speakers JSONB;
    v_topics   JSONB;
BEGIN
    -- Admin read: all speakers and topics, including hidden.
    IF NOT public.can_read_speakers_editor(p_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Speakers (all columns) + competence topic ids + linked events with
    -- occupancy. Ordered by "order", title.
    SELECT COALESCE(jsonb_agg(q.sp ORDER BY q.sp_order, q.sp_title), '[]'::jsonb)
    INTO v_speakers
    FROM (
        SELECT
            to_jsonb(s) || jsonb_build_object(
                'topics', COALESCE((
                    SELECT jsonb_agg(stl.topic ORDER BY stl.topic)
                    FROM public.speaker_topic_links stl
                    WHERE stl.speaker = s.id
                ), '[]'::jsonb),
                'events', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'id',                 e.id,
                        'title',              e.title,
                        'start_time',         e.start_time,
                        'end_time',           e.end_time,
                        'max_participants',   e.max_participants,
                        'occupied',           (SELECT count(*) FROM public.event_users eu WHERE eu.event = e.id),
                        'is_counseling_slot', COALESCE((e.data->>'is_counseling_slot')::boolean, FALSE)
                    ) ORDER BY e.start_time)
                    FROM public.event_speakers es
                    JOIN public.events e ON e.id = es.event
                    WHERE es.speaker = s.id
                ), '[]'::jsonb)
            ) AS sp,
            s."order" AS sp_order,
            s.title   AS sp_title
        FROM public.speakers s
        WHERE s.occasion = p_occasion
    ) q;

    -- Full topic catalog, including hidden.
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t."order", t.title), '[]'::jsonb)
    INTO v_topics
    FROM public.speaker_topics t
    WHERE t.occasion = p_occasion;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'speakers',       v_speakers,
            'speaker_topics', v_topics
        )
    );
END;
$$;


ALTER FUNCTION public.get_speakers_for_edit(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_spot_management_bundle(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_spot_management_bundle(p_inventory_pool_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_spots_data jsonb;
    v_inventory_contexts_data jsonb;
    v_resources_data jsonb;
    v_resource_slots_data jsonb;
    v_order_product_tickets_data jsonb;
    v_orders_data jsonb;
    result jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check (assuming a similar function exists for order view)
    IF NOT can_read_orders(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Aggregate all inventory_contexts for the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.block_date), '[]'::jsonb)
    INTO v_inventory_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Aggregate all spots that belong to any context within the specified pool
    SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inventory_context IN (
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    );

    -- Aggregate all resources for the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.title), '[]'::jsonb)
    INTO v_resources_data
    FROM public.resources r
    WHERE r.inventory_pool = p_inventory_pool_id;

    -- Aggregate all resource slots for all resources within the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(rs) ORDER BY rs.id), '[]'::jsonb)
    INTO v_resource_slots_data
    FROM public.resource_slots rs
    WHERE rs.resource IN (
        SELECT id FROM public.resources WHERE inventory_pool = p_inventory_pool_id
    );

    -- NEW: Aggregate all order_product_tickets related to the spots in the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(opt) ORDER BY opt.id), '[]'::jsonb)
    INTO v_order_product_tickets_data
    FROM eshop.order_product_ticket opt
    WHERE opt.id IN (
        SELECT DISTINCT s.order_product_ticket
        FROM eshop.spots s
        WHERE s.inventory_context IN (
            SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
        ) AND s.order_product_ticket IS NOT NULL
    );

    -- NEW: Aggregate all orders related to those order_product_tickets
    SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.id), '[]'::jsonb)
    INTO v_orders_data
    FROM eshop.orders o
    WHERE o.id IN (
        SELECT DISTINCT opt."order"
        FROM eshop.order_product_ticket opt
        WHERE opt.id IN (
            SELECT DISTINCT s.order_product_ticket
            FROM eshop.spots s
            WHERE s.inventory_context IN (
                SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
            ) AND s.order_product_ticket IS NOT NULL
        ) AND opt."order" IS NOT NULL
    );

    -- Construct the final bundle object with the new data
    result := jsonb_build_object(
        'spots', v_spots_data,
        'inventory_contexts', v_inventory_contexts_data,
        'resources', v_resources_data,
        'resource_slots', v_resource_slots_data,
        'order_product_tickets', v_order_product_tickets_data, -- Added
        'orders', v_orders_data  -- Added
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        -- A more robust error handling for production
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_spot_management_bundle(p_inventory_pool_id bigint) OWNER TO postgres;

--
-- Name: get_spots_for_inclusion_type_group(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_spots_for_inclusion_type_group(p_inclusion_type_group_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion_id bigint;
    v_spots_data jsonb;
    v_inclusion_types_data jsonb;
    result jsonb;
BEGIN
    -- Get occasion for permission check
    SELECT occasion INTO v_occasion_id
    FROM public.inclusion_type_groups
    WHERE id = p_inclusion_type_group_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inclusion Type Group not found.';
    END IF;

    -- Permission check
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Aggregate spots that belong to any inclusion type within the specified group
    SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inclusion_type IN (
        SELECT id FROM public.inclusion_types WHERE inclusion_type_group = p_inclusion_type_group_id
    );

    -- Aggregate all inclusion types for the group
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.created_at), '[]'::jsonb)
    INTO v_inclusion_types_data
    FROM public.inclusion_types t
    WHERE t.inclusion_type_group = p_inclusion_type_group_id;

    -- Construct the final bundle object
    result := jsonb_build_object(
        'spots', v_spots_data,
        'inclusion_types', v_inclusion_types_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.get_spots_for_inclusion_type_group(p_inclusion_type_group_id bigint) OWNER TO postgres;

--
-- Name: get_stripe_disconnect_impact(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_stripe_disconnect_impact(p_unit bigint, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c eshop.stripe_connections; result jsonb;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 SELECT * INTO c FROM eshop.stripe_connections WHERE unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted','revoked')
  ORDER BY (state<>'revoked') DESC,created_at DESC LIMIT 1;
 IF c.id IS NULL THEN RAISE EXCEPTION 'STRIPE_CONNECTION_UNAVAILABLE'; END IF;
 SELECT jsonb_build_object('connectionId',c.id,'businessName',c.business_name,
  'openAttempts',count(*) FILTER(WHERE state IN ('preparing','open','uncertain') OR lease_expires_at>statement_timestamp() OR refund_cursor IS NOT NULL OR session_lookup_cursor IS NOT NULL),
  'historyCount',count(*),'lastSyncedAt',CASE WHEN bool_or(last_synced_at IS NULL) THEN NULL ELSE min(last_synced_at) END,
  'disconnectState',(SELECT state FROM eshop.stripe_disconnect_intents WHERE connection_id=c.id AND state<>'completed')) INTO result
 FROM eshop.stripe_checkout_attempts WHERE connection_id=c.id;
 RETURN result;
END $$;


ALTER FUNCTION public.get_stripe_disconnect_impact(p_unit bigint, p_livemode boolean) OWNER TO postgres;

--
-- Name: get_stripe_order_admin_detail(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_stripe_order_admin_detail(p_order bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; pi eshop.payment_info; a eshop.stripe_checkout_attempts; c eshop.stripe_connections; totals record;
 d eshop.stripe_admission_decisions; revision text; note text; tickets jsonb; card_refunded bigint;
BEGIN
 SELECT * INTO o FROM eshop.orders WHERE id=p_order;
 IF auth.uid() IS NULL OR o.id IS NULL OR NOT coalesce(public.can_write_orders(o.occasion),false)
  OR NOT EXISTS(SELECT 1 FROM public.occasions occasion JOIN public.user_info viewer ON viewer.organization=occasion.organization AND viewer.id=auth.uid() WHERE occasion.id=o.occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 SELECT * INTO pi FROM eshop.payment_info WHERE id=o.payment_info;
 IF pi.payment_method IS DISTINCT FROM 'stripe' THEN RETURN NULL; END IF;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE order_id=o.id ORDER BY created_at DESC LIMIT 1;
 SELECT * INTO STRICT c FROM eshop.stripe_connections WHERE id=a.connection_id;
 SELECT * INTO STRICT totals FROM public.payment_financial_totals_internal(pi.id);
 SELECT coalesce(sum(amount_minor),0) INTO card_refunded FROM eshop.stripe_payment_movements WHERE attempt_id=a.id AND kind='refund';
 SELECT * INTO d FROM eshop.stripe_admission_decisions WHERE attempt_id=a.id AND reason IN ('partial_refund_keep','partial_refund_cancel') ORDER BY created_at DESC,id DESC LIMIT 1;
 SELECT encode(extensions.digest(coalesce(jsonb_agg(jsonb_build_array(provider_id,amount_minor) ORDER BY provider_id)::text,'[]'),'sha256'),'hex')
  INTO revision FROM eshop.stripe_payment_movements WHERE attempt_id=a.id AND kind='refund';
 IF d.id IS NOT NULL THEN
  SELECT data->>'note' INTO note FROM eshop.orders_history WHERE "order"=o.id AND data->>'decisionId'=d.id::text ORDER BY created_at DESC LIMIT 1;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'label',coalesce(t.ticket_symbol,t.id::text),'state',t.state) ORDER BY t.id),'[]'::jsonb)
 INTO tickets FROM public.get_order_tickets_internal(o.id) person JOIN eshop.tickets t ON t.id=person.id;
 RETURN jsonb_build_object('orderId',o.id,'currency',a.currency,'refundedMinor',card_refunded,'amountMinor',a.amount_minor,
  'canDecide',card_refunded>0 AND card_refunded<a.amount_minor AND a.state='paid' AND o.state IN ('paid','sent') AND NOT totals.invalid_identity
   AND a.refund_cursor IS NULL AND a.session_lookup_cursor IS NULL AND pi.id=a.payment_info_id AND pi.stripe_connection_id=a.connection_id,
  'lastSyncedAt',a.last_synced_at,'reconciliationPending',a.refund_cursor IS NOT NULL OR a.session_lookup_cursor IS NOT NULL,
  'decision',CASE WHEN d.id IS NOT NULL THEN jsonb_build_object('action',CASE WHEN d.reason='partial_refund_keep' THEN 'keep' ELSE 'cancel_selected' END,
   'ticketIds',d.ticket_ids,'note',note,'createdAt',d.created_at,'isCurrent',d.provider_revision=revision) END,
  'tickets',tickets,'dashboardUrl',CASE WHEN EXISTS(SELECT 1 FROM public.unit_users WHERE unit=a.unit_id AND "user"=auth.uid() AND is_manager)
   THEN 'https://dashboard.stripe.com/'||c.account_id||CASE WHEN a.livemode THEN '' ELSE '/test' END||'/dashboard' END);
END $$;


ALTER FUNCTION public.get_stripe_order_admin_detail(p_order bigint) OWNER TO postgres;

--
-- Name: get_stripe_order_pay_source_internal(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_stripe_order_pay_source_internal(p_order bigint, p_command uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 PERFORM public.require_service_role();
 SELECT jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash,
  'payment',public.stripe_order_payment_projection_internal(c.order_id),
  'payBaseUrl',(SELECT regexp_replace(return_base_url,'/stripe/return$','/stripe/pay') FROM eshop.stripe_checkout_attempts WHERE order_id=c.order_id ORDER BY created_at DESC LIMIT 1))
 INTO result FROM eshop.stripe_payment_link_sources s JOIN eshop.stripe_capabilities c USING(token_hash)
 WHERE s.command_id=p_command AND c.order_id=p_order AND c.scope='order_pay'
  AND c.revoked_at IS NULL AND c.expires_at>clock_timestamp() AND s.expires_at=c.expires_at;
 IF result IS NULL THEN
  result:=jsonb_build_object('payment',public.stripe_order_payment_projection_internal(p_order));
  IF result#>>'{payment,method}' IS DISTINCT FROM 'stripe' OR result#>>'{payment,status}' IN ('open','preparing') THEN
   RAISE EXCEPTION 'STRIPE_PAYMENT_SOURCE_UNAVAILABLE'; END IF;
 END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.get_stripe_order_pay_source_internal(p_order bigint, p_command uuid) OWNER TO postgres;

--
-- Name: get_stripe_unit_connection(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_stripe_unit_connection(p_unit bigint, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 SELECT jsonb_build_object('connectionId',id,'businessName',business_name,'country',country,'state',state,
  'paused',paused,'chargesEnabled',charges_enabled,'payoutsEnabled',payouts_enabled,'cardPaymentsActive',card_payments_active,
  'modelVerified',model_verified,'checkedAt',checked_at,'statusFailures',status_failures,
  'disconnectState',(SELECT state FROM eshop.stripe_disconnect_intents WHERE connection_id=eshop.stripe_connections.id AND state<>'completed'),
  'dashboardUrl','https://dashboard.stripe.com/'||account_id||CASE WHEN livemode THEN '' ELSE '/test' END||'/dashboard') INTO result FROM eshop.stripe_connections
 WHERE unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted','revoked')
 ORDER BY (state IN ('connected','restricted')) DESC,coalesce(checked_at,created_at) DESC LIMIT 1;
 RETURN result;
END $$;


ALTER FUNCTION public.get_stripe_unit_connection(p_unit bigint, p_livemode boolean) OWNER TO postgres;

--
-- Name: get_sync_occasions(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_sync_occasions(p_organization_id bigint DEFAULT NULL::bigint, p_unit_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', o.id,
            'link', o.link,
            'title', o.title,
            'description', o.description,
            'data', o.data,
            'start_time', o.start_time,
            'end_time', o.end_time,
            'is_open', o.is_open,
            'is_hidden', o.is_hidden,
            'is_promoted', o.is_promoted,
            'features', o.features,
            'created_at', o.created_at,
            'form_link', (
                SELECT f.link
                FROM public.forms f
                WHERE f.occasion = o.id
                ORDER BY f.is_open DESC, f.id
                LIMIT 1
            )
        )
        ORDER BY o.start_time DESC
    ), '[]'::jsonb)
    INTO result
    FROM public.occasions o
    WHERE o.is_open = true
      AND o.is_hidden = false
      AND o.is_promoted = true
      AND (p_organization_id IS NULL OR o.organization = p_organization_id)
      AND (p_unit_id IS NULL OR o.unit = p_unit_id);

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_sync_occasions(p_organization_id bigint, p_unit_id bigint) OWNER TO postgres;

--
-- Name: get_ticket_batch_create_options(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_batch_create_options(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR public.can_write_orders(p_occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'blueprint',f.blueprint,'products',
  (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'price',p.price,'currency',p.currency_code) ORDER BY p.id),'[]')
   FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type WHERE p.occasion=p_occasion AND pt.type='spot' AND NOT p.is_hidden
   AND EXISTS(SELECT 1 FROM public.form_fields ff WHERE ff.form=f.id AND ff.product_type=p.product_type AND NOT ff.is_hidden))) ORDER BY f.id),'[]')
 FROM public.forms f WHERE f.occasion=p_occasion);
END $$;


ALTER FUNCTION public.get_ticket_batch_create_options(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_ticket_batch_detail(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_batch_detail(p_batch uuid, p_after integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; can_edit boolean; can_sell boolean;
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch;
 IF auth.uid() IS NULL OR public.can_read_orders(b.occasion) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order viewer required'; END IF;
 can_edit:=public.can_write_orders(b.occasion);
 can_sell:=can_edit AND public.get_is_manager_on_unit((SELECT unit FROM public.occasions WHERE id=b.occasion))
  AND NOT EXISTS(SELECT 1 FROM eshop.external_services s JOIN public.occasions o ON o.unit=s.unit WHERE o.id=b.occasion AND s.type='FAKTUROID')
  AND b.manifest_hash IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready');
 RETURN jsonb_build_object('id',b.id,'occasion',b.occasion,'form',b.form,'title',b.title,'stockOrderId',b.stock_order_id,
 'currency',b.currency_code,'createdAt',b.created_at,'manifestHash',b.manifest_hash,
 'counts',(SELECT jsonb_build_object('total',count(*),'available',count(*) FILTER(WHERE i.sale_order_id IS NULL AND t.state<>'storno'),
 'soldActive',count(*) FILTER(WHERE i.sale_order_id IS NOT NULL AND t.state<>'storno'),
 'voidedUnsold',count(*) FILTER(WHERE i.sale_order_id IS NULL AND t.state='storno'),
 'cancelledAfterSale',count(*) FILTER(WHERE i.sale_order_id IS NOT NULL AND t.state='storno'))
 FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id WHERE i.batch_id=b.id),
 'stockValue',(SELECT coalesce(sum((p->>'price')::numeric),0) FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id
 CROSS JOIN LATERAL jsonb_array_elements(b.snapshot->'tickets') st CROSS JOIN LATERAL jsonb_array_elements(st->'products') p
 WHERE i.batch_id=b.id AND i.sale_order_id IS NULL AND t.state<>'storno' AND (st->>'id')::bigint=t.id),
 'receivedAmount',(SELECT coalesce(sum(coalesce(pi.paid,0)-coalesce(pi.returned,0)),0) FROM eshop.payment_info pi JOIN eshop.orders o ON o.payment_info=pi.id
 WHERE o.id IN(SELECT sale_order_id FROM eshop.ticket_batch_items WHERE batch_id=b.id)),
 'sales',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'symbol',o.order_symbol,'createdAt',o.created_at,'amount',o.price) ORDER BY o.created_at DESC),'[]')
 FROM (SELECT * FROM eshop.orders WHERE id IN(SELECT sale_order_id FROM eshop.ticket_batch_items WHERE batch_id=b.id) ORDER BY created_at DESC,id LIMIT 20) o),
 'allowedActions',jsonb_build_array('view','download')||CASE WHEN can_edit THEN jsonb_build_array('void','prepare') ELSE '[]' END
  ||CASE WHEN can_sell THEN jsonb_build_array('sell') ELSE '[]' END,
 'items',(SELECT coalesce(jsonb_agg(to_jsonb(row) ORDER BY ordinal),'[]') FROM (
 SELECT i.ordinal,t.id,t.ticket_symbol,t.state,i.sale_order_id,
 (SELECT value FROM jsonb_array_elements(b.snapshot->'tickets') WHERE (value->>'id')::bigint=t.id) snapshot
 FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id WHERE i.batch_id=b.id AND i.ordinal>greatest(0,p_after)
 ORDER BY i.ordinal LIMIT 50) row),
 'documents',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'key',part_key,'kind',kind,'state',state,
 'bytes',byte_count,'pages',page_count,'errorCode',error_code) ORDER BY part_key),'[]') FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id));
END $$;


ALTER FUNCTION public.get_ticket_batch_detail(p_batch uuid, p_after integer) OWNER TO postgres;

--
-- Name: get_ticket_batch_export_manifest(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_batch_export_manifest(p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; docs jsonb; feature jsonb; template jsonb;
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch;
 IF auth.uid() IS NULL OR public.can_read_orders(b.occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 PERFORM public.admit_ticket_batch_document_internal(b.occasion);
 IF b.manifest_hash IS NULL OR EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND kind='single' AND state<>'ready') THEN
  RAISE EXCEPTION 'BATCH_PRINT_NOT_READY'; END IF;
 SELECT jsonb_agg(jsonb_build_object('ordinal',i.ordinal,'objectKey',p.object_key,'digest',p.content_digest,'bytes',p.byte_count) ORDER BY i.ordinal)
 INTO docs FROM eshop.ticket_batch_items i JOIN eshop.ticket_batch_document_parts p ON p.batch_id=i.batch_id AND p.kind='single' AND p.ticket_ids=ARRAY[i.ticket_id]
 WHERE i.batch_id=b.id;
 IF jsonb_array_length(docs) IS DISTINCT FROM (SELECT count(*)::integer FROM eshop.ticket_batch_items WHERE batch_id=b.id) OR docs IS NULL THEN
  RAISE EXCEPTION 'BATCH_PRINT_NOT_READY'; END IF;
 SELECT value INTO feature FROM jsonb_array_elements(b.resource_manifest#>'{snapshot,occasion,features}') WHERE value->>'code'='ticket';
 template:=feature#>ARRAY['layout','templates',CASE WHEN feature->>'ticket_type'='named' THEN 'named' ELSE 'wide' END];
 RETURN public.bound_document_data_v1(jsonb_build_object('batchId',b.id,'documents',docs,'template',template));
END $$;


ALTER FUNCTION public.get_ticket_batch_export_manifest(p_batch uuid) OWNER TO postgres;

--
-- Name: get_ticket_batch_stored_document(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_batch_stored_document(p_ticket bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; part eshop.ticket_batch_document_parts; oc bigint;
BEGIN
 SELECT occasion INTO oc FROM eshop.tickets WHERE id=p_ticket;
 IF auth.role()<>'service_role' AND (auth.uid() IS NULL OR public.can_read_orders(oc) IS NOT TRUE) THEN RAISE insufficient_privilege; END IF;
 SELECT b0.* INTO b FROM eshop.ticket_batches b0 JOIN eshop.ticket_batch_items i ON i.batch_id=b0.id WHERE i.ticket_id=p_ticket;
 IF b.id IS NULL THEN RETURN NULL; END IF;
 IF auth.role()<>'service_role' AND (auth.uid() IS NULL OR public.can_read_orders(b.occasion) IS NOT TRUE) THEN RAISE insufficient_privilege; END IF;
 SELECT * INTO part FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND kind='single' AND ticket_ids=ARRAY[p_ticket];
 IF part.state IS DISTINCT FROM 'ready' THEN RAISE EXCEPTION 'BATCH_PRINT_NOT_READY'; END IF;
 RETURN jsonb_build_object('objectKey',part.object_key,'digest',part.content_digest,'bytes',part.byte_count);
END $$;


ALTER FUNCTION public.get_ticket_batch_stored_document(p_ticket bigint) OWNER TO postgres;

--
-- Name: get_ticket_batches(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_batches(p_occasion bigint, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR public.can_read_orders(p_occasion) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 RETURN (SELECT coalesce(jsonb_agg(public.get_ticket_batch_detail(id) ORDER BY created_at DESC,id),'[]') FROM (
  SELECT id,created_at FROM eshop.ticket_batches WHERE occasion=p_occasion AND (p_before IS NULL OR created_at<p_before)
  ORDER BY created_at DESC,id LIMIT 20) b);
END $$;


ALTER FUNCTION public.get_ticket_batches(p_occasion bigint, p_before timestamp with time zone) OWNER TO postgres;

--
-- Name: get_ticket_details_for_generating(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_details_for_generating(ticket_id_input bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        -- 1. Build the 'ticket' key
        'ticket', (
            SELECT to_jsonb(t_detail)
            FROM (
                SELECT
                    t.id,
                    (SELECT i.batch_id FROM eshop.ticket_batch_items i WHERE i.ticket_id=t.id) AS batch_id,
                    t.ticket_symbol,
                    t.occasion,
                    t.note,
                    t.state,
                    b.title AS table_title,
                    -- Subquery for Spot/Product details
                    (
                        SELECT jsonb_agg(ticket_prod ORDER BY ticket_prod.id)
                        FROM (
                            SELECT
                                opt2.id,
                                opt2.product,
                                s.title AS spot_title,
                                p.data->>'short_title' AS short_title,
                                p.title AS product_title,
                                public.order_spot_metadata_internal(s.id)->>'spot_group_title' AS spot_group_title
                            FROM eshop.order_product_ticket opt2
                            LEFT JOIN eshop.spots s
                                ON s.order_product_ticket = opt2.id
                            LEFT JOIN eshop.products p
                                ON p.id = opt2.product
                            LEFT JOIN eshop.product_types pt
                                ON pt.id = p.product_type
                            LEFT JOIN eshop.blueprints bp
                                ON bp.id = s.blueprint
                            WHERE opt2.ticket = t.id
                              AND NOT (pt.type = 'spot' AND s.title IS NULL)
                        ) ticket_prod
                    ) AS order_product_ticket,

                    -- Subquery for Price (extracting from ord.data)
                    (
                      SELECT COALESCE(SUM((prod->>'price')::numeric), 0)
                      FROM jsonb_array_elements(ord.data->'tickets') ticket_json,
                           jsonb_array_elements(ticket_json->'products') prod
                      WHERE (ticket_json->>'id')::bigint = t.id
                    ) AS price,

                    -- Subquery for Currency (extracting from ord.data)
                    (
                      SELECT (prod->>'currency_code')
                      FROM jsonb_array_elements(ord.data->'tickets') ticket_json,
                           jsonb_array_elements(ticket_json->'products') prod
                      WHERE (ticket_json->>'id')::bigint = t.id
                      LIMIT 1
                    ) AS currency_code
            ) t_detail
        ),

        -- 2. Build the 'occasion' key (dumps the whole occasion row including 'features')
        'occasion', to_jsonb(o)||jsonb_build_object('demo_read_only',public.is_demo_occasion(o.id),'locale',coalesce((SELECT data->>'DEFAULT_LANGUAGE' FROM public.organizations WHERE id=o.organization),'cs')),
        'order_data', jsonb_build_object('name', ord.data->'name', 'surname', ord.data->'surname')
    )
    INTO result
    FROM eshop.tickets t
    -- Join Occasion to get the occasion object
    JOIN public.occasions o
        ON o.id = t.occasion
    -- Join Blueprint for the table title
    LEFT JOIN eshop.blueprints b
        ON b.occasion = o.id
    -- Join Order Tables to expose 'ord.data' for the ticket sub-calculations above
    LEFT JOIN eshop.order_product_ticket opt
        ON opt.ticket = t.id
    LEFT JOIN eshop.orders ord
        ON ord.id = opt."order"
    WHERE t.id = ticket_id_input AND t.state IS DISTINCT FROM 'waitlisted' AND t.ticket_symbol IS NOT NULL
      AND ord.state IS DISTINCT FROM 'waitlisted';

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_ticket_details_for_generating(ticket_id_input bigint) OWNER TO postgres;

--
-- Name: get_ticket_document_data_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_document_data_v1(p_ticket bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM eshop.tickets WHERE id=p_ticket;
 IF occ IS NULL OR NOT (public.is_service_role() OR (auth.uid() IS NOT NULL AND public.can_read_orders(occ))) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket document access denied'; END IF;
 PERFORM public.admit_ticket_document_internal_v1(occ);
 RETURN public.bound_document_data_v1(public.get_ticket_details_for_generating(p_ticket));
END $$;


ALTER FUNCTION public.get_ticket_document_data_v1(p_ticket bigint) OWNER TO postgres;

--
-- Name: get_ticket_layout_for_authoring_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_layout_for_authoring_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 IF NOT public.can_read_ticket_layout(p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 SELECT jsonb_build_object('occasion',o.id,'aggregate_version',coalesce(v.version,0),
  'schemaVersion',3,'appearance',coalesce((SELECT jsonb_build_object('layout',f->'layout',
    'background',f->'background','ticket_type',f->'ticket_type') FROM jsonb_array_elements(o.features) f WHERE f->>'code'='ticket'),'{}'),
  'images',coalesce((SELECT jsonb_agg(i.link ORDER BY i.id) FROM public.images i WHERE i.occasion=o.id OR i.unit=o.unit),'[]'))
 INTO result FROM public.occasions o LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion' AND v.scope_type='occasion' AND v.scope_id=o.id AND v.aggregate_id=o.id::text
 WHERE o.id=p_occasion;
 RETURN result;
END $$;


ALTER FUNCTION public.get_ticket_layout_for_authoring_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_ticket_layout_write_contract_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ticket_layout_write_contract_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ready boolean;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=auth.uid()) THEN
