--
-- Name: get_tickets_with_details(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tickets_with_details(order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    tickets JSONB;
BEGIN
    SELECT jsonb_agg(ticket_detail)
    INTO tickets
    FROM (
        SELECT DISTINCT ON (t.id)
            t.id,
            t.ticket_symbol,
            t.occasion,
            t.note,
            t.state,
            b.title AS table_title,
            (
                SELECT jsonb_agg(ticket_prod)
                FROM (
                    SELECT
                        opt2.id,
                        opt2.product,
                        s.title AS spot_title,
                        public.order_spot_metadata_internal(s.id)->>'spot_group_title' AS spot_group_title
                    FROM eshop.order_product_ticket opt2
                    LEFT JOIN eshop.spots s
                        ON s.order_product_ticket = opt2.id
                    LEFT JOIN eshop.blueprints bp
                        ON bp.id = s.blueprint
                    WHERE opt2.ticket = t.id
                ) ticket_prod
            ) AS order_product_ticket,
            (
              SELECT COALESCE(SUM((prod->>'price')::numeric), 0)
              FROM jsonb_array_elements(ord.data->'tickets') ticket_json,
                   jsonb_array_elements(ticket_json->'products') prod
              WHERE (ticket_json->>'id')::bigint = t.id
            ) AS price,
            (
              SELECT (prod->>'currency_code')
              FROM jsonb_array_elements(ord.data->'tickets') ticket_json,
                   jsonb_array_elements(ticket_json->'products') prod
              WHERE (ticket_json->>'id')::bigint = t.id
              LIMIT 1
            ) AS currency_code
        FROM eshop.order_product_ticket opt
        JOIN eshop.tickets t
            ON t.id = opt.ticket
        JOIN eshop.orders ord
            ON ord.id = order_id
        LEFT JOIN public.occasions o
            ON o.id = t.occasion
        LEFT JOIN eshop.blueprints b
            ON b.occasion = o.id
        WHERE opt."order" = order_id AND t.state IS DISTINCT FROM 'waitlisted' AND t.ticket_symbol IS NOT NULL
        ORDER BY t.id
    ) ticket_detail;

    RETURN tickets;
END;
$$;


ALTER FUNCTION public.get_tickets_with_details(order_id bigint) OWNER TO postgres;

--
-- Name: get_transactions_for_order(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_transactions_for_order(order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion_id bigint;
BEGIN

  SELECT occasion INTO v_occasion_id FROM eshop.orders WHERE id = order_id;
  IF NOT can_read_orders(v_occasion_id) THEN
    RAISE EXCEPTION 'User is not authorized to view transactions for this occasion.' USING ERRCODE = 'P0001';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'order_state', o.state,
      'actions', jsonb_build_object(
        'canAddCash', public.can_manage_unit_bank_accounts(oc.unit)
          AND o.state IN ('created','ordered','paid','sent') AND NOT public.payment_method_is_online_internal(pi.payment_method),
        'canConfigureBank', public.can_manage_unit_bank_accounts(oc.unit),
        'bankState', CASE WHEN NOT public.can_read_unit_bank_accounts(oc.unit) THEN 'restricted'
          WHEN EXISTS(SELECT 1 FROM eshop.unit_bank_accounts l JOIN eshop.bank_accounts b ON b.id=l.bank_account
            WHERE l.unit=oc.unit AND upper(b.type)<>'CASH') THEN 'configured' ELSE 'absent' END,
        'pairingAccountId', CASE WHEN pi.payment_method='bank' AND public.can_manage_bank_account(pi.bank_account)
          AND public.can_write_orders(o.occasion) AND o.state IN ('created','ordered','paid','sent') THEN pi.bank_account END,
        'unitId', oc.unit,
        'removableTransactionIds', (SELECT coalesce(jsonb_agg(t.id),'[]')
          FROM eshop.transactions t JOIN eshop.bank_accounts b ON b.id=t.bank_account_id
          WHERE t.payment_info=o.payment_info AND o.state IN ('created','ordered','paid','sent')
          AND NOT public.payment_method_is_online_internal(pi.payment_method)
          AND CASE WHEN t.transaction_type='manual' THEN upper(b.type)='CASH'
            AND public.can_manage_unit_bank_accounts(oc.unit) AND EXISTS(
              SELECT 1 FROM eshop.unit_bank_accounts l WHERE l.unit=oc.unit AND l.bank_account=b.id)
            ELSE public.can_write_orders(o.occasion) AND public.can_manage_bank_account(b.id) END),
        'historyAccounts', (SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'title',b.title) ORDER BY b.id),'[]')
          FROM public.get_my_admin_bank_accounts() b WHERE upper(b.type)<>'CASH')
      ),
      'payment_info', (
        SELECT to_jsonb(pi)
        FROM eshop.payment_info pi
        WHERE pi.id = o.payment_info
      ),
      'transactions', COALESCE((
        SELECT jsonb_agg(
            to_jsonb(t) || jsonb_build_object('createdByName',
                trim(both from COALESCE(ui.name, '') || ' ' || COALESCE(ui.surname, ''))
            )
        )
        FROM eshop.transactions t
        LEFT JOIN public.user_info ui ON t.created_by = ui.id
        WHERE t.payment_info = o.payment_info
      ), '[]'::jsonb)
    )
    FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion
    LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info
    WHERE o.id = order_id
  );
END;
$$;


ALTER FUNCTION public.get_transactions_for_order(order_id bigint) OWNER TO postgres;

--
-- Name: get_transactions_for_order_all_available(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_transactions_for_order_all_available(payment_info_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    bank_acc bigint;
BEGIN
    SELECT pi.bank_account INTO bank_acc
    FROM eshop.payment_info pi
    WHERE pi.id = payment_info_id
    AND pi.payment_method='bank'
    LIMIT 1;

    IF bank_acc IS NULL THEN RAISE insufficient_privilege USING MESSAGE='Bank payment account required'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.demo_occasions demo_bank WHERE demo_bank.bank_account=bank_acc AND public.can_read_orders(demo_bank.occasion)) THEN
        PERFORM public.check_is_admin_for_bank_account(bank_acc);
    END IF;

    RETURN (
        SELECT jsonb_agg(t ORDER BY t.date DESC)
        FROM eshop.transactions t
        WHERE t.bank_account_id = (
            SELECT pi.bank_account
            FROM eshop.payment_info pi
            WHERE pi.id = payment_info_id
        )
        AND t.payment_info IS NULL
    );
END;
$$;


ALTER FUNCTION public.get_transactions_for_order_all_available(payment_info_id bigint) OWNER TO postgres;

--
-- Name: get_unit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  unit_data jsonb;
BEGIN
  -- Check if the unit exists
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  SELECT jsonb_build_object(
    'id', u.id,
    'created_at', u.created_at,
    'title', u.title,
    'organization', u.organization,
    'data', u.data,
    'features', u.features,
    'occasions', (
       SELECT COALESCE(
         jsonb_agg(
           jsonb_build_object(
             'id', o.id,
             'title', o.title,
             'created_at', o.created_at,
             'updated_at', o.updated_at,
             'data', o.data,
             'description', o.description,
             'is_hidden', o.is_hidden,
             'is_open', o.is_open,
             'start_time', o.start_time,
             'end_time', o.end_time,
             'link', o.link,
             'organization', o.organization,
             'services', o.services,
             'unit', o.unit,
             'features', o.features,
             'form', (
                SELECT jsonb_build_object(
                   'id', f.id,
                   'created_at', f.created_at,
                   'data', f.data,
                   'occasion', f.occasion,
                   'type', f.type,
                   'is_open', f.is_open,
                   'link', f.link,
                   'blueprint', f.blueprint,
                   'header', f.header,
                   'header_off', f.header_off,
                   'updated_at', f.updated_at
                )
                FROM public.forms f
                WHERE f.occasion = o.id
                ORDER BY f.id
                LIMIT 1
             )
           )
           ORDER BY o.start_time DESC
         ),
         '[]'::jsonb
       )
       FROM public.occasions o
       WHERE o.unit = u.id
         AND o.is_hidden = false
    )
  )
  INTO unit_data
  FROM public.units u
  WHERE u.id = unit_id;

  RETURN jsonb_build_object(
    'code', 200,
    'data', unit_data
  );
END;
$$;


ALTER FUNCTION public.get_unit(unit_id bigint) OWNER TO postgres;

