CREATE FUNCTION public.get_unit_abuse_policy_v1(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org bigint;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_unit_abuse_policy(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 SELECT organization INTO v_org FROM public.units WHERE id=p_unit;
 RETURN jsonb_build_object('creation',public.abuse_effective_rules_v1('occasion.creation',p_unit,v_org),
 'draft',public.abuse_effective_rules_v1('occasion.draft',p_unit,v_org),
 'usage',coalesce((SELECT jsonb_agg(jsonb_build_object('rule',u.rule_key,'amount',u.amount,'bucketAt',u.bucket_at,'expiresAt',u.expires_at))
 FROM public.abuse_budget_usage u JOIN public.abuse_policy_rules r USING(rule_key)
 WHERE u.expires_at>statement_timestamp() AND ((r.scope_kind='unit' AND u.scope_id=p_unit::text)
 OR (r.scope_kind='actor' AND u.scope_id=auth.uid()::text))),'[]'::jsonb));
END $$;


ALTER FUNCTION public.get_unit_abuse_policy_v1(p_unit bigint) OWNER TO postgres;

--
-- Name: get_unit_app_landing(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_app_landing(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org bigint;
  v_data jsonb;
  v_occasion bigint;
  v_title text;
  v_admin boolean;
BEGIN
  SELECT organization INTO v_org FROM public.units WHERE id = p_unit;
  v_admin := public.can_manage_unit_app_landing(p_unit);
  IF v_org IS NULL OR NOT public.can_read_unit_app_landing(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE = 'Access denied';
  END IF;
  SELECT data INTO v_data FROM public.organizations WHERE id = v_org;
  v_occasion := (v_data->>'DEFAULT_OCCASION')::bigint;
  SELECT title INTO v_title FROM public.occasions
    WHERE id = v_occasion AND organization = v_org;
  RETURN jsonb_build_object('enabled', coalesce((v_data->>'IS_APP_SUPPORTED')::boolean, false),
    'occasion_id', v_occasion, 'occasion_title', v_title, 'can_manage', v_admin);
END;
$$;


ALTER FUNCTION public.get_unit_app_landing(p_unit bigint) OWNER TO postgres;

--
-- Name: get_unit_edit_data(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_edit_data(p_unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_unit_data jsonb;
BEGIN
    -- 1. Call get_unit_for_edit to get the unit details
    SELECT get_unit_for_edit(p_unit_id) INTO v_unit_data;

    -- Check if get_unit_for_edit returned an error (code != 200)
    IF (v_unit_data->>'code')::INT <> 200 THEN
          RAISE EXCEPTION 'get_unit_for_edit failed: %', v_unit_data->>'message';
    END IF;

    RETURN public.get_unit_occasion_dashboard_internal(p_unit_id) ||
        jsonb_build_object('unit',v_unit_data->'data');
END;
$$;


ALTER FUNCTION public.get_unit_edit_data(p_unit_id bigint) OWNER TO postgres;

--
-- Name: get_unit_edit_data_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_edit_data_v1(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb; v_version bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_result:=public.get_unit_edit_data(p_unit);
  SELECT COALESCE(v.version,0) INTO v_version
    FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='unit' AND v.scope_type='unit'
      AND v.scope_id=p_unit AND v.aggregate_id=p_unit::text;
  RETURN jsonb_set(v_result,'{unit}',(v_result->'unit')||
    jsonb_build_object('aggregate_version',v_version));
END; $$;


ALTER FUNCTION public.get_unit_edit_data_v1(p_unit bigint) OWNER TO postgres;

--
-- Name: get_unit_for_edit(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_for_edit(unit_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    unit_data jsonb;
BEGIN
    -- Check if the current user is authorized (editor or manager) for the provided unit
    IF NOT public.can_read_unit_occasion_catalog(unit_id) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Retrieve the unit data as jsonb
    SELECT jsonb_build_object(
        'id', id,
        'title', title,
        'data', public.form_measurement_unit_data_internal(unit_id,data),
        'features', features,
        'organization', organization,
        'aggregate_version', coalesce((SELECT v.version FROM public.client_aggregate_versions v
          WHERE v.aggregate_type='unit' AND v.scope_type='unit' AND v.scope_id=unit_id
          AND v.aggregate_id=unit_id::text),0)
    ) INTO unit_data
    FROM units
    WHERE id = unit_id;

    -- Return the unit data with a 200 code
    RETURN jsonb_build_object('code', 200, 'data', unit_data);
END;
$$;


ALTER FUNCTION public.get_unit_for_edit(unit_id bigint) OWNER TO postgres;

--
-- Name: get_unit_information_for_edit_v1(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_information_for_edit_v1(p_unit bigint, p_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_unit_information(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor view required'; END IF;
 IF p_type='game' THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
 RETURN coalesce((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) ORDER BY i.id)
 FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information'
 AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=i.id::text
 WHERE i.unit=p_unit AND i.occasion IS NULL AND i.information_hidden IS NULL
 AND coalesce(i.type,'')=coalesce(p_type,'')),'[]');
END $$;


ALTER FUNCTION public.get_unit_information_for_edit_v1(p_unit bigint, p_type text) OWNER TO postgres;

--
-- Name: get_unit_legal_profile(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_legal_profile(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE p public.unit_legal_profiles; org bigint; admin boolean; result jsonb;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit;
 admin:=coalesce(public.check_is_admin_of_organization(org),false);
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.can_read_unit_legal_profile(p_unit) THEN
  RAISE EXCEPTION 'Legal profile access denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit;
 result:=jsonb_build_object('unitId',p_unit,'revision',coalesce(p.revision,0),'status',coalesce(p.status,'unverified'),
 'legalName',coalesce(p.legal_name,''),'countryCode',coalesce(p.country_code,''),
 'registrationNumber',coalesce(p.registration_number,''),'vatId',coalesce(p.vat_id,''),
 'address',jsonb_build_object('street',coalesce(p.street,''),'city',coalesce(p.city,''),'postalCode',coalesce(p.postal_code,'')),
 'contactEmail',coalesce(p.contact_email,''),'phone',coalesce(p.phone,''),'website',coalesce(p.website,''),
 'submittedAt',p.submitted_at,'verifiedAt',CASE WHEN p.status='verified' AND p.reviewed_organization_id=org THEN p.reviewed_at END,
 'feedbackToApplicant',CASE WHEN p.reviewed_organization_id=org THEN p.feedback_to_applicant END);
 IF admin AND p.reviewed_organization_id=org THEN
  result:=result||jsonb_build_object('reviewNote',p.review_note,'reviewSource',p.review_source);
 END IF;
 RETURN jsonb_build_object('code',200,'profile',result);
END $$;


ALTER FUNCTION public.get_unit_legal_profile(p_unit bigint) OWNER TO postgres;

--
-- Name: get_unit_occasion_dashboard_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_occasion_dashboard_internal(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org bigint; v_drafts jsonb := '[]'; v_landing jsonb := NULL;
 v_demos jsonb := '{"hasOwnWork":false,"items":[]}';
BEGIN
 IF NOT public.can_read_unit_occasion_catalog(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Unit dashboard access denied';
 END IF;
 SELECT organization INTO v_org FROM public.units WHERE id=p_unit;
 IF public.can_create_occasion(p_unit) THEN
  v_drafts := public.get_occasion_setup_drafts(p_unit);
 END IF;
 IF public.can_read_unit_app_landing(p_unit) THEN
  v_landing := public.get_unit_app_landing(p_unit);
 END IF;
 IF EXISTS(SELECT 1 FROM public.user_info WHERE id=auth.uid() AND organization=v_org) THEN
  v_demos := public.get_demo_occasions(v_org);
 END IF;
 RETURN jsonb_build_object('unit_id',p_unit,
  'occasions',public.get_all_occasions_for_edit_v212(p_unit),
  'drafts',v_drafts,'app_landing',v_landing,'demo_catalog',v_demos);
END $$;


ALTER FUNCTION public.get_unit_occasion_dashboard_internal(p_unit bigint) OWNER TO postgres;

--
-- Name: get_unit_verification_queue(bigint, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unit_verification_queue(p_organization bigint, p_status text DEFAULT 'pending'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE items jsonb; next_cursor jsonb; lim integer:=greatest(1,least(coalesce(p_limit,50),50));
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.check_is_admin_of_organization(p_organization),false) THEN
  RAISE EXCEPTION 'Verification queue access denied' USING ERRCODE='42501';
 END IF;
 IF p_status IS NULL OR p_status NOT IN ('pending','verified') THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_STATUS','fieldErrors','{}'::jsonb); END IF;
 SELECT coalesce(jsonb_agg(profile ORDER BY submitted_at,unit_id),'[]') INTO items FROM (
  SELECT p.unit_id,p.submitted_at,(public.get_unit_legal_profile(p.unit_id)->'profile')||jsonb_build_object('unitTitle',u.title) AS profile
  FROM public.unit_legal_profiles p JOIN public.units u ON u.id=p.unit_id
  WHERE u.organization=p_organization AND p.status=p_status
   AND (p_status<>'verified' OR p.reviewed_organization_id=p_organization)
   AND (p_cursor IS NULL OR (p.submitted_at,p.unit_id)>((p_cursor->>'submittedAt')::timestamptz,(p_cursor->>'unitId')::bigint))
  ORDER BY p.submitted_at,p.unit_id LIMIT lim+1
 ) page;
 IF jsonb_array_length(items)>lim THEN
  items:=items-(jsonb_array_length(items)-1);
  next_cursor:=jsonb_build_object('submittedAt',items->(lim-1)->'submittedAt','unitId',items->(lim-1)->'unitId');
 END IF;
 RETURN jsonb_build_object('code',200,'items',items,'nextCursor',next_cursor);
END $$;


ALTER FUNCTION public.get_unit_verification_queue(p_organization bigint, p_status text, p_cursor jsonb, p_limit integer) OWNER TO postgres;

