--
-- Name: get_user_groups_by_occasion(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_groups_by_occasion(occasion_id_in bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    -- Retrieve the user ID from the authentication context
    current_user_id UUID := auth.uid();
BEGIN
    -- This function retrieves all groups a user is a member of for a specific occasion,
    -- including their admin status for each group.
    -- It joins the user_groups table (which defines membership and roles)
    -- with the user_group_info table (which contains group details)
    -- and filters the results by the provided occasion ID.
    -- The result is aggregated into a single JSONB array.

    RETURN (
        SELECT
            -- COALESCE ensures that if the user is not in any groups for this occasion,
            -- an empty JSON array '[]' is returned instead of NULL.
            COALESCE(
                jsonb_agg(
                    -- jsonb_build_object constructs a JSON object for each group.
                    jsonb_build_object(
                        'id', ugi.id,
                        'title', ugi.title,
                        'type', ugi.type,
                        'place', ugi.place,
                        'description', ugi.description,
                        'occasion', ugi.occasion,
                        'data', ugi.data,
                        'is_admin', ug.is_admin
                    )
                ),
                '[]'::JSONB
            )
        FROM
            -- ug is the membership link table
            public.user_groups ug
        JOIN
            -- ugi contains the actual information about the group
            public.user_group_info ugi ON ug."group" = ugi.id
        WHERE
            -- Filter to get groups for the currently authenticated user
            ug."user" = current_user_id
            -- AND filter by the specific occasion ID passed to the function
            AND ugi.occasion = occasion_id_in
    );
END;
$$;


ALTER FUNCTION public.get_user_groups_by_occasion(occasion_id_in bigint) OWNER TO postgres;

--
-- Name: get_user_groups_editor_bundle_v1(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_groups_editor_bundle_v1(p_occasion bigint, p_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_groups jsonb; v_places jsonb; v_game_definitions jsonb;
BEGIN
  IF public.can_read_groups_editor(p_occasion) IS NOT TRUE THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_user_group_command_data_v1(g.id)||
    jsonb_build_object('aggregate_version',COALESCE(v.version,0))
    ORDER BY g.title,g.id),'[]'::jsonb) INTO v_groups
  FROM public.user_group_info g LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='user_group' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=g.id::text
  WHERE g.occasion=p_occasion AND (p_type IS NULL AND g.type IS NULL OR g.type=p_type);
  SELECT COALESCE(jsonb_agg(to_jsonb(p)||jsonb_build_object(
    'aggregate_version',COALESCE(v.version,0)) ORDER BY p."order" NULLS LAST,p.title),
    '[]'::jsonb) INTO v_places FROM public.places p
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=p.id::text
  WHERE p.occasion=p_occasion AND NOT p.is_hidden
    AND p.coordinates->'latLng'->>'lat' IS NOT NULL
    AND p.coordinates->'latLng'->>'lng' IS NOT NULL;
  IF p_type='game' THEN
    SELECT jsonb_object_agg(i.id,i.title) INTO v_game_definitions
    FROM public.information i WHERE i.occasion=p_occasion AND i.type='game';
  END IF;
  RETURN jsonb_build_object('groups',v_groups,'places',v_places,
    'game_definitions',v_game_definitions);
END; $$;


ALTER FUNCTION public.get_user_groups_editor_bundle_v1(p_occasion bigint, p_type text) OWNER TO postgres;

--
-- Name: get_user_groups_for_context_internal_v1(bigint, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_groups_for_context_internal_v1(p_occasion bigint, p_editor boolean, p_viewer boolean, p_writable boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(jsonb_object_agg(g.id,jsonb_build_object(
 'id',g.id,'title',g.title,'type',g.type,'place',g.place,'description',g.description,
 'occasion',g.occasion,'data',g.data,'is_admin',mine.is_admin,
 'capabilities',jsonb_build_object(
 'groups.write',public.group_write_rule(p_editor,mine.is_admin,p_writable),
 'groups.editor.read',public.group_editor_read_rule(p_viewer,p_editor,mine.is_admin),
 'map.place.move',public.place_move_rule(p_editor,mine.is_admin,coalesce(p.type='group' AND p.is_hidden,false),p_writable)))),
 '{}'::jsonb)
 FROM public.user_groups mine JOIN public.user_group_info g ON g.id=mine."group"
 LEFT JOIN public.places p ON p.id=g.place AND p.occasion=g.occasion
 WHERE mine."user"=auth.uid() AND g.occasion=p_occasion;
$$;


