--

CREATE FUNCTION public.get_user_id(test_user_alias text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    ret_id uuid;
BEGIN
    SELECT id INTO ret_id FROM _test_user_aliases WHERE alias = test_user_alias;
    IF ret_id IS NULL THEN RAISE EXCEPTION 'Test user alias not found: %', test_user_alias; END IF;
    RETURN ret_id;
END;
$$;


