--
-- Name: get_user_info_for_users(uuid[], bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_info_for_users(user_ids uuid[], oc bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  companions jsonb;
BEGIN
  -- Check if the user is a manager, editor, or approver for the occasion
  IF (SELECT public.can_read_participant_contacts(oc)) <> TRUE THEN
      RETURN jsonb_build_object('code', 403);
  END IF;

  -- Aggregate the user information as JSON
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'created_at', ui.created_at,
      'updated_at', ui.updated_at,
      'email_readonly', ui.email_readonly,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'phone', ui.phone,
      'data', ui.data,
      'birth_date', ui.birth_date,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'created_at', parent_ui.created_at,
          'updated_at', parent_ui.updated_at,
          'email_readonly', parent_ui.email_readonly,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'phone', parent_ui.phone,
          'data', parent_ui.data,
          'birth_date', parent_ui.birth_date
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user" AND public.occasion_member_visible_internal(oc,parent_ui.id)
      )
    )
  ) INTO companions
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oc
  WHERE ui.id = ANY(user_ids) AND public.occasion_member_visible_internal(oc,ui.id);

  -- If no companions are found, return an empty array
  IF companions IS NULL THEN
    companions := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', companions
  );
END;
$$;


ALTER FUNCTION public.get_user_info_for_users(user_ids uuid[], oc bigint) OWNER TO postgres;

--
-- Name: get_user_inventory(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_inventory() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_user_id UUID;
    v_result JSONB;
BEGIN
    -- 1. Get the current user's ID.
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not authenticated. Cannot retrieve inventory.';
    END IF;

    -- 2. Create a definitive list of the user's tickets and associated products.
    -- This is the absolute source of truth for which products the user owns.
    WITH user_ticket_products AS (
        SELECT
            opt.id AS order_product_ticket_id,
            opt.product AS product_id
        FROM public.occasion_users ou
        JOIN eshop.order_product_ticket opt ON ou.ticket = opt.ticket
        WHERE ou."user" = v_user_id
          AND ou.ticket IS NOT NULL
          AND opt.product IS NOT NULL
    ),

    -- 3. Find the user's assigned spots and their context ONLY for the tickets identified above.
    user_assigned_inventory AS (
        SELECT
            s.id AS id, -- Renamed to 'id' to match the provided CTE
            s.title AS title, -- Renamed to 'title'
            s.state AS state, -- Renamed to 'state'
            s.resource_slot AS resource_slot, -- Renamed to 'resource_slot'
            s.resource AS resource, -- Renamed to 'resource'
            s.inventory_context AS inventory_context, -- Renamed to 'inventory_context'
            ic.inventory_pool AS inventory_pool, -- Renamed to 'inventory_pool'
            utp.product_id
        FROM eshop.spots s
        JOIN user_ticket_products utp ON s.order_product_ticket = utp.order_product_ticket_id
        JOIN public.inventory_contexts ic ON s.inventory_context = ic.id
    ),

    -- 4. Fetch the full data for each entity, strictly filtering by the IDs gathered above.

    -- MODIFIED: Fetches products STRICTLY from the user's tickets.
    products_json AS (
        SELECT
            jsonb_object_agg(p.id, jsonb_build_object(
                'id', p.id, 'title', p.title, 'description', p.description, 'price', p.price, 'data', p.data,
                'product_type', p.product_type, 'occasion', p.occasion, 'is_hidden', p.is_hidden,
                'currency_code', p.currency_code, 'order', p."order",
                'maximum', p.maximum, 'is_dynamically_available', is_product_dynamically_available(p.id)
            )) AS data
        FROM eshop.products p
        WHERE p.id IN (SELECT DISTINCT product_id FROM user_ticket_products)
    ),

    -- MODIFIED: Fetches PIC records using a precise (context, product) match from the user's assigned spots.
    -- This is the most minimal possible query for this data.
    product_inventory_contexts_json AS (
        SELECT jsonb_object_agg(pic.id, to_jsonb(pic)) AS data
        FROM eshop.product_inventory_contexts pic
        WHERE (pic.inventory_context, pic.product) IN (
            SELECT DISTINCT inventory_context, product_id FROM user_assigned_inventory -- Updated column name
        )
    ),

    -- Build the JSON for contexts, ensuring the 'spots' array is correctly populated.
    contexts_json AS (
        SELECT
            jsonb_object_agg(ic.id, jsonb_build_object(
                'id', ic.id, 'order', ic."order", 'block_date', ic.block_date, 'title', ic.title,
                'data', ic.data, 'inventory_pool', ic.inventory_pool,
                'spots', (
                    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.id), '[]'::jsonb) -- Updated column name
                    FROM (
                        SELECT uai.id, uai.title, uai.state, uai.resource_slot, uai.resource, uai.product_id -- Updated column names
                        FROM user_assigned_inventory uai
                        WHERE uai.inventory_context = ic.id -- Updated column name
                    ) t
                )
            )) AS data
        FROM public.inventory_contexts ic
        WHERE ic.id IN (SELECT DISTINCT inventory_context FROM user_assigned_inventory) -- Updated column name
    ),

    -- Pools, Places, and Resources are filtered based on the derived inventory.
    pools_json AS (
        SELECT jsonb_object_agg(p.id, jsonb_strip_nulls(jsonb_build_object(
            'id', p.id, 'data', p.data, 'title', p.title, 'description', p.description,
            'type', p.type, 'sellable_capacity', p.sellable_capacity, 'occasion', p.occasion
        ))) AS data
        FROM public.inventory_pools p
        WHERE p.id IN (SELECT DISTINCT inventory_pool FROM user_assigned_inventory) -- Updated column name
    ),
    places_json AS (
        SELECT jsonb_object_agg(pl.id, to_jsonb(pl)) AS data
        FROM public.places pl
        JOIN (
            SELECT DISTINCT (ip.data->>'place_id')::bigint AS id
            FROM public.inventory_pools ip
            WHERE ip.id IN (SELECT DISTINCT inventory_pool FROM user_assigned_inventory) -- Updated column name
              AND ip.data ? 'place_id' AND ip.data->>'place_id' IS NOT NULL
        ) AS place_ids ON pl.id = place_ids.id
    ),
    resources_json AS (
        SELECT jsonb_object_agg(r.id, to_jsonb(r)) AS data
        FROM public.resources r
        WHERE r.id IN (SELECT DISTINCT resource FROM user_assigned_inventory WHERE resource IS NOT NULL) -- Updated column name
    )

    -- 5. Assemble the final, minimal JSON object.
    SELECT jsonb_build_object(
        'inventory_contexts', COALESCE((SELECT data FROM contexts_json), '{}'::jsonb),
        'inventory_pools', COALESCE((SELECT data FROM pools_json), '{}'::jsonb),
        'resources', COALESCE((SELECT data FROM resources_json), '{}'::jsonb),
        'products', COALESCE((SELECT data FROM products_json), '{}'::jsonb),
        'product_inventory_contexts', COALESCE((SELECT data FROM product_inventory_contexts_json), '{}'::jsonb),
        'places', COALESCE((SELECT data FROM places_json), '{}'::jsonb)
    )
    INTO v_result;

    -- 6. Return the final object.
    RETURN v_result;

END;
$$;


ALTER FUNCTION public.get_user_inventory() OWNER TO postgres;

--
-- Name: get_user_inventory_for_occasion_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_inventory_for_occasion_v1(p_occasion bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH user_ticket_products AS (
    SELECT opt.id order_product_ticket_id,opt.product product_id
    FROM public.occasion_users ou
    JOIN eshop.order_product_ticket opt ON opt.ticket=ou.ticket
    WHERE ou."user"=auth.uid() AND ou.occasion=p_occasion
      AND ou.ticket IS NOT NULL AND opt.product IS NOT NULL
  ), assigned AS (
    SELECT s.id,s.title,s.state,s.resource_slot,s.resource,s.inventory_context,
      ic.inventory_pool,utp.product_id
    FROM eshop.spots s
    JOIN user_ticket_products utp
      ON utp.order_product_ticket_id=s.order_product_ticket
    JOIN public.inventory_contexts ic ON ic.id=s.inventory_context
    JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
    WHERE ip.occasion=p_occasion
  )
  SELECT jsonb_build_object(
    'inventory_contexts',COALESCE((SELECT jsonb_object_agg(ic.id,
      jsonb_build_object('id',ic.id,'order',ic."order",'block_date',ic.block_date,
        'title',ic.title,'data',ic.data,'inventory_pool',ic.inventory_pool,
        'spots',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a.id,
          'title',a.title,'state',a.state,'resource_slot',a.resource_slot,
          'resource',a.resource,'product_id',a.product_id) ORDER BY a.id),'[]')
          FROM assigned a WHERE a.inventory_context=ic.id)))
      FROM public.inventory_contexts ic
      WHERE ic.id IN (SELECT DISTINCT a.inventory_context FROM assigned a)),'{}'),
    'inventory_pools',COALESCE((SELECT jsonb_object_agg(ip.id,
      jsonb_strip_nulls(jsonb_build_object('id',ip.id,'data',ip.data,
        'title',ip.title,'description',ip.description,'type',ip.type,
        'sellable_capacity',ip.sellable_capacity,'occasion',ip.occasion)))
      FROM public.inventory_pools ip
      WHERE ip.occasion=p_occasion AND ip.id IN (
        SELECT DISTINCT a.inventory_pool FROM assigned a)),'{}'),
    'resources',COALESCE((SELECT jsonb_object_agg(r.id,to_jsonb(r))
      FROM public.resources r WHERE r.occasion=p_occasion AND r.id IN (
        SELECT DISTINCT a.resource FROM assigned a WHERE a.resource IS NOT NULL)),'{}'),
    'products',COALESCE((SELECT jsonb_object_agg(p.id,jsonb_build_object(
      'id',p.id,'title',p.title,'description',p.description,'price',p.price,
      'data',p.data,'product_type',p.product_type,'occasion',p.occasion,
      'is_hidden',p.is_hidden,'currency_code',p.currency_code,'order',p."order",
      'maximum',p.maximum,'is_dynamically_available',
        public.is_product_dynamically_available(p.id)))
      FROM eshop.products p WHERE p.id IN (
        SELECT DISTINCT a.product_id FROM assigned a)),'{}'),
    'product_inventory_contexts',COALESCE((SELECT jsonb_object_agg(pic.id,to_jsonb(pic))
      FROM eshop.product_inventory_contexts pic
      WHERE (pic.inventory_context,pic.product) IN (
        SELECT DISTINCT a.inventory_context,a.product_id FROM assigned a)),'{}'),
    'places',COALESCE((SELECT jsonb_object_agg(pl.id,to_jsonb(pl))
      FROM public.places pl WHERE pl.occasion=p_occasion AND pl.id IN (
        SELECT DISTINCT (ip.data->>'place_id')::bigint
        FROM public.inventory_pools ip
        WHERE ip.id IN (SELECT DISTINCT a.inventory_pool FROM assigned a)
          AND ip.data ? 'place_id' AND ip.data->>'place_id' IS NOT NULL)),'{}'));
$$;


ALTER FUNCTION public.get_user_inventory_for_occasion_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: get_user_profile_data_patch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_profile_data_patch(p_data jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(jsonb_object_agg(entry.key, entry.value), '{}'::jsonb)
  FROM jsonb_each(
    CASE WHEN jsonb_typeof(p_data) = 'object' THEN p_data ELSE '{}'::jsonb END
  ) AS entry
  WHERE entry.key = ANY (ARRAY[
    'name', 'surname', 'sex', 'phone', 'birthDate'
  ]::text[]);
$$;


ALTER FUNCTION public.get_user_profile_data_patch(p_data jsonb) OWNER TO postgres;

--
-- Name: get_users_from_occasion_with_orders(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_users_from_occasion_with_orders(oc bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  users_data jsonb;
  tickets_data jsonb;
  order_product_tickets_data jsonb;
  orders_data jsonb;
  forms_data jsonb;
  form_fields_data jsonb;
  org_id bigint; -- Variable to store Organization ID
BEGIN
  -- 0. Retrieve Organization ID
  -- We need this to check the organization_users table
  SELECT organization INTO org_id
  FROM public.occasions
  WHERE id = oc;

  -- Security check: If the user lacks permission, raise an exception.
  IF (SELECT get_is_editor_view_on_occasion(oc)) <> TRUE THEN
      RAISE EXCEPTION 'User is not authorized to access this occasion' USING ERRCODE = '42501';
  END IF;

  -- 1. Fetch users as a JSON object, keyed by user ID.
  SELECT jsonb_object_agg(ui.id,
    jsonb_strip_nulls(jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'phone', ui.phone,
      'birth_date', ui.birth_date,
      'data', ui.data,
      'ticket_id', ou.ticket,
      'companions', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', comp_ui.id,
            'name', comp_ui.name,
            'surname', comp_ui.surname
          )
        ), '[]'::jsonb)
        FROM public.user_companions uc
        JOIN public.user_info comp_ui ON uc.companion = comp_ui.id
        WHERE uc."user" = ui.id AND uc.occasion=oc
      )
    ))
  ) INTO users_data
  FROM public.occasion_users ou
  JOIN public.user_info ui ON ou."user" = ui.id

  -- Join to check visibility
  LEFT JOIN public.organization_users org_u ON ui.id = org_u."user" AND org_u.organization = org_id

  WHERE ou.occasion = oc
  -- Filter hidden users
  AND (org_u.is_hidden IS NOT TRUE);

  -- 2. Use CTEs to gather the unique IDs of all related items, preventing duplicates.
  WITH relevant_tickets AS (
      -- Get unique ticket IDs directly linked to users on the occasion
      -- We MUST apply the same hidden filter here, otherwise we might fetch tickets for hidden users
      SELECT DISTINCT ou.ticket AS id
      FROM public.occasion_users ou
      LEFT JOIN public.organization_users org_u ON ou."user" = org_u."user" AND org_u.organization = org_id
      WHERE ou.occasion = oc
        AND ou.ticket IS NOT NULL
        AND (org_u.is_hidden IS NOT TRUE)
  ),
  relevant_orders AS (
      -- From those tickets, get unique order IDs via the join table
      -- (This automatically excludes orders from hidden users because relevant_tickets is filtered)
      SELECT DISTINCT "order" AS id
      FROM eshop.order_product_ticket
      WHERE ticket IN (SELECT id FROM relevant_tickets)
  ),
  relevant_forms AS (
      -- From those orders, get unique form IDs
      SELECT DISTINCT f.id
      FROM public.forms f
      JOIN eshop.orders o ON f.occasion = o.occasion AND f.key::text = o.data->>'form'
      WHERE o.id IN (SELECT id FROM relevant_orders)
  )
  -- 3. Fetch the data as dictionaries, using the de-duplicated ID sets from the CTEs.
  SELECT
    (SELECT jsonb_object_agg(t.id, to_jsonb(t)) FROM eshop.tickets t WHERE t.id IN (SELECT id FROM relevant_tickets)),
    (SELECT jsonb_object_agg(o.id, to_jsonb(o)) FROM eshop.orders o WHERE o.id IN (SELECT id FROM relevant_orders)),
    (SELECT jsonb_object_agg(opt.id, to_jsonb(opt)) FROM eshop.order_product_ticket opt WHERE opt.order IN (SELECT id FROM relevant_orders)),
    (SELECT jsonb_object_agg(f.id, to_jsonb(f)) FROM public.forms f WHERE f.id IN (SELECT id FROM relevant_forms)),
    (SELECT jsonb_object_agg(ff.id, to_jsonb(ff)) FROM public.form_fields ff WHERE ff.form IN (SELECT id FROM relevant_forms))
  INTO
    tickets_data,
    orders_data,
    order_product_tickets_data,
    forms_data,
    form_fields_data;

  -- 4. Return the data object directly.
  RETURN jsonb_build_object(
      'users', COALESCE(users_data, '{}'::jsonb),
      'tickets', COALESCE(tickets_data, '{}'::jsonb),
      'order_product_ticket', COALESCE(order_product_tickets_data, '{}'::jsonb),
      'orders', COALESCE(orders_data, '{}'::jsonb),
      'forms', COALESCE(forms_data, '{}'::jsonb),
      'form_fields', COALESCE(form_fields_data, '{}'::jsonb)
  );
END;
$$;


ALTER FUNCTION public.get_users_from_occasion_with_orders(oc bigint) OWNER TO postgres;

--
-- Name: get_verified_unit_identity_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_verified_unit_identity_internal(p_unit bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE p public.unit_legal_profiles; org bigint;
BEGIN
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit AND status='verified';
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT organization INTO org FROM public.units WHERE id=p_unit;
 IF p.reviewed_organization_id IS DISTINCT FROM org THEN
  RAISE LOG 'Verified identity tenant mismatch for Unit %',p_unit;
  RETURN NULL;
 END IF;
 RETURN jsonb_strip_nulls(jsonb_build_object('unitId',p.unit_id,'revision',p.revision,
 'legalName',p.legal_name,'countryCode',p.country_code,'registrationNumber',p.registration_number,
 'vatId',nullif(p.vat_id,''),'address',jsonb_build_object('street',p.street,'city',p.city,'postalCode',p.postal_code),
 'contactEmail',p.contact_email,'phone',nullif(p.phone,''),'website',nullif(p.website,''),'verifiedAt',p.reviewed_at));
END $$;


ALTER FUNCTION public.get_verified_unit_identity_internal(p_unit bigint) OWNER TO postgres;

--
-- Name: get_waitlist_email_context_v1(text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_email_context_v1(p_operation text, p_payload jsonb, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE fid bigint; f public.forms; occ public.occasions; contexts jsonb; r jsonb; o eshop.orders;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_operation='register' THEN SELECT id INTO fid FROM public.forms WHERE key=(p_payload->>'form')::uuid;
 ELSIF p_operation='send' THEN fid:=(p_payload->>'formId')::bigint;
 ELSE RAISE EXCEPTION 'Invalid email context operation'; END IF;
 SELECT * INTO STRICT f FROM public.forms WHERE id=fid; SELECT * INTO STRICT occ FROM public.occasions WHERE id=f.occasion;
 IF p_operation='send' AND NOT public.can_write_orders_as_actor_internal(p_actor,occ.id) THEN
  RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 contexts:='[]';
 IF p_operation='register' THEN contexts:=jsonb_build_array(jsonb_build_object('recipient',p_payload->>'email','organization',occ.organization,
  'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'participantCount',jsonb_array_length(p_payload->'tickets'),'formLink',f.link));
 ELSE
  FOR r IN SELECT * FROM jsonb_array_elements(p_payload->'recipients') LOOP
   SELECT * INTO STRICT o FROM eshop.orders WHERE id=(r->>'orderId')::bigint AND form=fid;
   contexts:=contexts||jsonb_build_array(jsonb_build_object('orderId',o.id,'recipient',o.data->>'email','organization',occ.organization,
   'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'orderSymbol',o.order_symbol,
   'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
   'offeredCount',(r->>'count')::integer,'formLink',f.link,'expiresAt',p_payload->>'expiresAt'));
  END LOOP;
 END IF;
 RETURN contexts;
END $$;


ALTER FUNCTION public.get_waitlist_email_context_v1(p_operation text, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: get_waitlist_email_render_context_v1(bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_email_render_context_v1(p_order_id bigint, p_offer_id uuid DEFAULT NULL::uuid, p_recipient text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; f public.forms; occ public.occasions; org public.organizations;
 manage_message public.email_messages; manage_cap eshop.waitlist_capabilities;
 source_cap eshop.waitlist_capabilities; v_recipient text; v_timezone text;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 SELECT * INTO o FROM eshop.orders WHERE id=p_order_id;
 SELECT * INTO f FROM public.forms WHERE id=o.form;
 SELECT * INTO occ FROM public.occasions WHERE id=o.occasion;
 SELECT * INTO org FROM public.organizations WHERE id=occ.organization;
 IF o.id IS NULL OR f.id IS NULL OR f.occasion<>occ.id OR o.state<>'waitlisted'
 OR (p_offer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers
  WHERE id=p_offer_id AND order_id=o.id AND form_id=f.id AND expires_at>clock_timestamp()
  AND EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=p_offer_id AND outcome='pending'))) THEN
  RAISE EXCEPTION 'waitlist_email_source_invalid';
 END IF;
 v_timezone:=public.get_waitlist_form_timezone_internal(f.id);
 v_recipient:=coalesce(p_recipient,o.data->>'email');
 SELECT * INTO manage_message FROM public.email_messages m
 WHERE m.order_id=o.id AND m.message_kind='waitlist_confirmation'
 AND m.recipient=v_recipient
 AND m.data ? 'waitlistEnvelope' ORDER BY m.id LIMIT 1;
 SELECT * INTO manage_cap FROM eshop.waitlist_capabilities
 WHERE order_id=o.id AND form_id=f.id AND organization_id=org.id
 AND kind='manage' AND revoked_at IS NULL;
 SELECT * INTO source_cap FROM eshop.waitlist_capabilities
 WHERE order_id=o.id AND form_id=f.id AND organization_id=org.id AND revoked_at IS NULL
 AND CASE WHEN p_offer_id IS NULL THEN kind='manage'
  ELSE kind='offer' AND offer_id=p_offer_id AND expires_at>clock_timestamp() END;
 IF manage_message.id IS NULL OR manage_cap.token_hash IS NULL OR source_cap.token_hash IS NULL THEN
  RAISE EXCEPTION 'waitlist_email_source_invalid';
 END IF;
 RETURN jsonb_build_object('orderId',o.id,'orderSymbol',o.order_symbol,
  'organization',org.id,'occasion',occ.id,'unit',occ.unit,'formLink',f.link,
  'webLink',org.data->>'DEFAULT_URL','replyTo',public.get_reply_to_email_for_order(o.id),
  'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
  'offeredCount',(SELECT count(*) FROM eshop.waitlist_offer_slots
    WHERE offer_id=p_offer_id AND outcome='pending'),
  'timeZone',v_timezone,
  'communicationTone',public.get_effective_form_data(f.id)->>'communication_tone',
  'toneSubstitutions',public.get_waitlist_email_tone_substitutions_internal(f.id),
  'expiresAt',(SELECT expires_at FROM eshop.waitlist_offers WHERE id=p_offer_id),
  'tokenHash',source_cap.token_hash,'manageTokenHash',manage_cap.token_hash,
  'manageEnvelope',manage_message.data->'waitlistEnvelope',
  'overviewSource',(SELECT jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash) FROM eshop.order_overview_sources s JOIN eshop.waitlist_capabilities c USING(token_hash) WHERE c.order_id=o.id AND c.kind='order_view' AND c.revoked_at IS NULL AND c.expires_at>statement_timestamp() ORDER BY s.created_at DESC LIMIT 1),
  'manageContentHash',manage_message.data->>'content_hash');
END $$;


ALTER FUNCTION public.get_waitlist_email_render_context_v1(p_order_id bigint, p_offer_id uuid, p_recipient text) OWNER TO postgres;

--
-- Name: get_waitlist_email_tone_substitutions_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_email_tone_substitutions_internal(p_form bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object(
  'waitlist_offer_button_single','Potvrdit přihlášení',
  'waitlist_offer_button_multiple','Potvrdit vybrané osoby',
  'waitlist_manage_button_label','Spravovat čekání',
  'waitlist_confirmation_heading',CASE WHEN informal THEN 'Jsi mezi náhradníky' ELSE 'Jste mezi náhradníky' END,
  'waitlist_confirmation_explanation',CASE WHEN informal THEN 'Zatím nic neplatíš. Jakmile se uvolní místo, pošleme ti nabídku. Čekání můžeš spravovat nebo ukončit přes tento odkaz:' ELSE 'Zatím nic neplatíte. Jakmile se uvolní místo, pošleme vám nabídku. Čekání můžete spravovat nebo ukončit přes tento odkaz:' END,
  'waitlist_offer_heading',CASE WHEN informal THEN 'Máme pro tebe nabídku' ELSE 'Máme pro vás nabídku' END,
  'waitlist_offer_instructions_single',CASE WHEN informal THEN 'Po otevření nabídky doplníš údaje a vybereš produkty podle aktuální dostupnosti. Přihlášení pak potvrdíš.' ELSE 'Po otevření nabídky doplníte údaje a vyberete produkty podle aktuální dostupnosti. Přihlášení pak potvrdíte.' END,
  'waitlist_offer_instructions',CASE WHEN informal THEN 'Po otevření nabídky vybereš, kdo přijde, a produkty podle aktuální dostupnosti. Objednávku pak potvrdíš.' ELSE 'Po otevření nabídky vyberete, kdo přijde, a produkty podle aktuální dostupnosti. Objednávku pak potvrdíte.' END)
 FROM (SELECT coalesce(public.get_effective_form_data(p_form)->>'communication_tone','formal')='informal' informal) tone;
$$;


ALTER FUNCTION public.get_waitlist_email_tone_substitutions_internal(p_form bigint) OWNER TO postgres;

--
-- Name: get_waitlist_form_timezone_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_form_timezone_internal(p_form bigint) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(occasion_zone.name,unit_zone.name,organization_zone.name,'Europe/Prague')
 FROM public.forms f JOIN public.occasions occ ON occ.id=f.occasion
 LEFT JOIN public.units u ON u.id=occ.unit
 LEFT JOIN public.organizations org ON org.id=occ.organization
 LEFT JOIN pg_timezone_names occasion_zone ON occasion_zone.name=nullif(occ.data->>'timezone','')
 LEFT JOIN pg_timezone_names unit_zone ON unit_zone.name=nullif(u.data->>'timezone','')
 LEFT JOIN pg_timezone_names organization_zone ON organization_zone.name=nullif(org.data->>'timezone','')
 WHERE f.id=p_form;
$$;


ALTER FUNCTION public.get_waitlist_form_timezone_internal(p_form bigint) OWNER TO postgres;

--
-- Name: get_waitlist_offer_email_preview(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_offer_email_preview(p_form_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f public.forms; occ public.occasions; resolved jsonb; tone jsonb;
 v_key text; v_value text; html text; subject text; v_timezone text; instructions_html text;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form_id;
 PERFORM public.check_is_editor_order_on_occasion(f.occasion);
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=f.occasion;
 resolved:=public.get_email_template_and_wrapper('waitlist_offer',
  jsonb_build_object('organization',occ.organization,'occasion',occ.id,'unit',occ.unit));
 -- Match the trusted delivery context's existing occasion/unit/org fallback.
 v_timezone:=public.get_waitlist_form_timezone_internal(f.id);
 -- Older preview clients know order/count/date variables, but not the new
 -- semantic copy keys. Expand only trusted copy here; leave those old keys.
 tone:=public.get_waitlist_email_tone_substitutions_internal(f.id);
 html:=resolved#>>'{template,html}'; subject:=resolved#>>'{template,subject}';
 instructions_html:=html;
 FOR v_key,v_value IN SELECT key,value FROM jsonb_each_text(tone) LOOP
  v_value:=replace(replace(replace(replace(replace(v_value,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;');
  html:=replace(html,'{{'||v_key||'}}',v_value);
  IF v_key<>'waitlist_offer_instructions' THEN
   instructions_html:=replace(instructions_html,'{{'||v_key||'}}',v_value);
  END IF;
  subject:=replace(subject,'{{'||v_key||'}}',v_value);
 END LOOP;
 IF html IS NOT NULL THEN resolved:=jsonb_set(resolved,'{template,html}',to_jsonb(html)); END IF;
 IF subject IS NOT NULL THEN resolved:=jsonb_set(resolved,'{template,subject}',to_jsonb(subject)); END IF;
 RETURN resolved||jsonb_build_object('code',200,'occasionTitle',occ.title,'formLink',f.link,
 'timeZone',v_timezone,'instructionsTemplateHtml',instructions_html,
 'communicationTone',public.get_effective_form_data(f.id)->>'communication_tone',
 'toneSubstitutions',tone);
END $$;


ALTER FUNCTION public.get_waitlist_offer_email_preview(p_form_id bigint) OWNER TO postgres;

--
-- Name: get_waitlist_offer_form(text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_offer_form(p_token text DEFAULT NULL::text, p_offer_id uuid DEFAULT NULL::uuid, p_order_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oid bigint; fid bigint; bundle jsonb; w eshop.waitlist_offers;
BEGIN
 PERFORM set_config('response.headers','[{"Cache-Control":"no-store"},{"Referrer-Policy":"no-referrer"}]',true);
 SELECT * INTO w FROM eshop.waitlist_offers WHERE id=p_offer_id;
 oid:=coalesce(w.order_id,p_order_id);
 fid:=public.check_waitlist_scope_internal(oid,p_offer_id,p_token,auth.uid(),CASE WHEN p_offer_id IS NULL THEN 'withdraw' ELSE 'read' END);
 -- Terminal links explain their own outcome without exposing form answers,
 -- contact data, products, or payment details after capability revocation.
 IF p_offer_id IS NOT NULL AND (w.expires_at<=clock_timestamp() OR NOT EXISTS(
  SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='pending')) THEN
  RETURN jsonb_build_object('code',200,'registrationMode','offer',
   'occasionTitle',(SELECT title FROM public.occasions WHERE id=(SELECT occasion FROM eshop.orders WHERE id=oid)),
   'orderSymbol',(SELECT order_symbol FROM eshop.orders WHERE id=oid),
   'timeZone',public.get_waitlist_form_timezone_internal(fid),
   'communicationTone',public.get_effective_form_data(fid)->>'communication_tone',
   'form',NULL,'formLink',(SELECT link FROM public.forms WHERE id=fid),
   'organizationIdentity',(SELECT CASE WHEN o.organization=u.organization THEN public.get_verified_unit_identity_internal(u.id) END FROM public.forms f JOIN public.occasions o ON o.id=f.occasion JOIN public.units u ON u.id=o.unit WHERE f.id=fid),
   'offerId',w.id,'pendingCount',0,'expiresAt',w.expires_at,'serverTime',clock_timestamp(),
   'offerStatus',CASE
    WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='declined') THEN 'declined'
    WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='cancelled') THEN 'cancelled'
    WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND (outcome='expired' OR outcome='pending' AND w.expires_at<=clock_timestamp())) THEN 'expired'
    ELSE 'accepted' END,'tickets','[]'::jsonb,'slots','[]'::jsonb);
 END IF;
 -- A revoked token can explain a terminal outcome above, never reopen live data.
 IF p_token IS NOT NULL AND EXISTS(SELECT 1 FROM eshop.waitlist_capabilities
  WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') AND revoked_at IS NOT NULL) THEN
  RAISE EXCEPTION 'INVALID_CAPABILITY';
 END IF;
 bundle:=public.get_form_bundle_internal(fid,true)::jsonb;
 bundle:=jsonb_set(bundle,'{data,registrationMode}',to_jsonb(CASE WHEN p_offer_id IS NOT NULL THEN 'offer'::text ELSE 'waitlist' END),true);
 RETURN jsonb_build_object('code',200,'form',bundle->'data','registrationMode',CASE WHEN p_offer_id IS NOT NULL THEN 'offer' ELSE 'waitlist' END,
  'timeZone',public.get_waitlist_form_timezone_internal(fid),
  'orderSymbol',(SELECT order_symbol FROM eshop.orders WHERE id=oid),
  'occasionTitle',(SELECT occ.title FROM public.occasions occ JOIN eshop.orders source ON source.occasion=occ.id WHERE source.id=oid),
  'orderData',(SELECT data FROM eshop.orders WHERE id=oid),'pendingCount',(SELECT count(*) FROM eshop.waitlist_offer_slots WHERE offer_id=p_offer_id AND outcome='pending' AND w.expires_at>clock_timestamp()),
  'orderId',oid,'offerId',p_offer_id,'serverTime',clock_timestamp(),'expiresAt',w.expires_at,
  'tickets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'displayName',public.get_waitlist_ticket_display_name_internal(fid,data,CASE WHEN (SELECT count(*) FROM public.get_order_tickets_internal(oid))=1 THEN (SELECT source.data FROM eshop.orders source WHERE source.id=oid) ELSE '{}'::jsonb END),'answers',public.extract_ticket_answers_internal(fid,data),'lifecycle',public.get_effective_waitlist_ticket_lifecycle_internal(id)) ORDER BY created_at,id),'[]')
   FROM public.get_order_tickets_internal(oid)),
  'slots',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'ticketId',ticket_id,'outcome',CASE WHEN outcome='pending' AND w.expires_at<=clock_timestamp() THEN 'expired' ELSE outcome END)),'[]')
   FROM eshop.waitlist_offer_slots WHERE offer_id=p_offer_id),'waitlistSummary',public.get_waitlist_summary_internal(oid));
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('code',403,'errorCode','INVALID_CAPABILITY');
END $$;


ALTER FUNCTION public.get_waitlist_offer_form(p_token text, p_offer_id uuid, p_order_id bigint) OWNER TO postgres;

--
-- Name: get_waitlist_offer_proposal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_offer_proposal(p_form_id bigint) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.get_waitlist_offer_proposal_internal(p_form_id,NULL,NULL);
$$;


ALTER FUNCTION public.get_waitlist_offer_proposal(p_form_id bigint) OWNER TO postgres;

--
-- Name: get_waitlist_offer_proposal_internal(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_offer_proposal_internal(p_form_id bigint, p_after bigint DEFAULT NULL::bigint, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f public.forms; c jsonb; proposals jsonb; available integer;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form_id;
 PERFORM public.check_is_editor_order_on_occasion(f.occasion);
 PERFORM 1 FROM public.forms WHERE id=f.id FOR UPDATE;
 PERFORM public.expire_waitlist_form_internal(f.id);
 c:=public.get_form_capacity_snapshot_internal(f.id); available:=(c->>'offerablePlaces')::integer;
 -- count is the suggested allocation; waitingCount is the authoritative recipient limit.
 -- Keep unallocated eligible recipients so editors can adjust the allocation safely.
 WITH ranked AS (
  SELECT p.*,o.id order_id,row_number() OVER(ORDER BY p.waitlist_queue_at,p.created_at,p.id) position
  FROM eshop.tickets p
  JOIN LATERAL(SELECT DISTINCT x."order" FROM eshop.order_product_ticket x WHERE x.ticket=p.id) x ON true
  JOIN eshop.orders o ON o.id=x."order" WHERE o.form=f.id AND o.state='waitlisted'
   AND public.get_effective_waitlist_ticket_lifecycle_internal(p.id)='waiting'
 ), grouped AS (
  SELECT order_id,min(waitlist_queue_at) first_queue,count(*) total,count(*) FILTER(WHERE position<=available) offered
  FROM ranked GROUP BY order_id
 ), page AS (
  SELECT * FROM grouped WHERE p_after IS NULL OR order_id>p_after
  ORDER BY CASE WHEN p_limit IS NULL THEN first_queue END,order_id LIMIT p_limit
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',order_id,'count',offered,'waitingCount',total)
  ORDER BY CASE WHEN p_limit IS NULL THEN first_queue END,order_id),'[]') INTO proposals FROM page;
 RETURN jsonb_build_object('code',200,'formId',f.id,'revision',c->'revision','capacity',c,'recipients',proposals,
 'offerDurationSeconds',f.waitlist_offer_duration_seconds,'serverTime',clock_timestamp(),
 'nextCursor',CASE WHEN p_limit IS NOT NULL AND jsonb_array_length(proposals)=p_limit THEN (SELECT max((r->>'orderId')::bigint) FROM jsonb_array_elements(proposals) r) END);
END $$;


ALTER FUNCTION public.get_waitlist_offer_proposal_internal(p_form_id bigint, p_after bigint, p_limit integer) OWNER TO postgres;

--
-- Name: get_waitlist_order_detail(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_order_detail(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order_id;
 IF NOT public.can_read_orders(o.occasion) THEN RAISE insufficient_privilege USING MESSAGE='Order viewer required'; END IF;
 RETURN jsonb_build_object('orderId',o.id,'sourceOrderId',o.source_waitlist_order_id,
 'occasionTitle',(SELECT title FROM public.occasions WHERE id=o.occasion),'waitlistSummary',public.get_waitlist_summary_internal(o.id),
 'capacity',public.get_form_capacity_snapshot_internal(o.form),
 'tickets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'displayName',public.get_waitlist_ticket_display_name_internal(o.form,p.data,CASE WHEN (SELECT count(*) FROM public.get_order_tickets_internal(o.id))=1 THEN o.data ELSE '{}'::jsonb END),'createdAt',p.created_at,'waitlistQueueAt',p.waitlist_queue_at,'answers',public.extract_ticket_answers_internal(o.form,p.data),
  'lifecycle',public.get_effective_waitlist_ticket_lifecycle_internal(p.id)) ORDER BY created_at,id),'[]') FROM public.get_order_tickets_internal(o.id) p),
 'offers',(SELECT coalesce(jsonb_agg(to_jsonb(w)||jsonb_build_object('slots',(SELECT coalesce(jsonb_agg((to_jsonb(s)-'ticket_id')||jsonb_build_object('ticketId',s.ticket_id)),'[]') FROM eshop.waitlist_offer_slots s WHERE offer_id=w.id)) ORDER BY created_at),'[]')
 FROM eshop.waitlist_offers w WHERE order_id=o.id),
 'linkedOrders',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'orderSymbol',order_symbol,'state',state)),'[]') FROM eshop.orders WHERE source_waitlist_order_id=o.id));
END $$;


ALTER FUNCTION public.get_waitlist_order_detail(p_order_id bigint) OWNER TO postgres;

--
-- Name: get_waitlist_summary_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_summary_internal(p_order bigint) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH effective AS (SELECT public.get_effective_waitlist_ticket_lifecycle_internal(person.id) lifecycle
 FROM public.get_order_tickets_internal(p_order) person), p AS (SELECT lifecycle,count(*) n FROM effective GROUP BY lifecycle),
 s AS (SELECT count(*) n,min(w.expires_at) expiry FROM eshop.waitlist_offer_slots x JOIN eshop.waitlist_offers w ON w.id=x.offer_id
 JOIN public.get_order_tickets_internal(p_order) person ON person.id=x.ticket_id WHERE true AND x.outcome='pending' AND w.expires_at>clock_timestamp())
 SELECT jsonb_build_object('counts',coalesce((SELECT jsonb_object_agg(lifecycle,n) FROM p),'{}'),
 'pendingPlaces',s.n,'earliestExpiry',s.expiry) || public.get_order_action_summary_internal(
 o.state,coalesce((SELECT n>0 FROM p WHERE lifecycle='waiting'),false),s.n)
 FROM eshop.orders o CROSS JOIN s WHERE o.id=p_order;
$$;


ALTER FUNCTION public.get_waitlist_summary_internal(p_order bigint) OWNER TO postgres;

--
-- Name: get_waitlist_ticket_display_name_internal(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_ticket_display_name_internal(p_form bigint, p_answers jsonb, p_contact jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT coalesce(nullif((SELECT string_agg(btrim(answer.value#>>'{}'),' ' ORDER BY CASE definition.type WHEN 'name' THEN 0 ELSE 1 END,definition."order" NULLS LAST,definition.id)
 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_answers->'fields')='array' THEN p_answers->'fields' ELSE '[]' END) field
 CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(field)='object' THEN field ELSE '{}' END) answer
 JOIN public.form_fields definition ON definition.id::text=answer.key
 WHERE definition.form=p_form AND definition.is_ticket_field AND NOT definition.is_hidden
 AND definition.type IN ('name','surname') AND jsonb_typeof(answer.value)='string' AND btrim(answer.value#>>'{}')<>''),''),
 nullif(btrim(concat_ws(' ',nullif(btrim(p_contact->>'name'),''),nullif(btrim(p_contact->>'surname'),''))),''));
$$;


ALTER FUNCTION public.get_waitlist_ticket_display_name_internal(p_form bigint, p_answers jsonb, p_contact jsonb) OWNER TO postgres;

