--
-- Name: group_places_read_rule(boolean, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.group_places_read_rule(p_authenticated boolean, p_member boolean, p_editor boolean, p_viewer boolean, p_demo boolean, p_demo_read boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT coalesce(p_authenticated,false) AND (coalesce(p_member,false) OR coalesce(p_editor,false) OR coalesce(p_viewer,false))
   AND (NOT p_demo OR coalesce(p_demo_read,false));
$$;


