-- Name: group_write_rule(boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.group_write_rule(p_editor boolean, p_group_admin boolean, p_writable boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT p_writable AND (p_editor OR coalesce(p_group_admin,false)); $$;


ALTER FUNCTION public.group_write_rule(p_editor boolean, p_group_admin boolean, p_writable boolean) OWNER TO postgres;

--
-- Name: groups_get_user_groups(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.groups_get_user_groups() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    user_id UUID := auth.uid();  -- Retrieve the user ID from the authentication context
    user_groups JSONB := '[]'::JSONB;  -- Initialize an empty JSON array
BEGIN
    -- Step 1: Query groups where the user is the leader in `user_group_info`
    user_groups := (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ug.id,
                'title', ug.title,
                'type', ug.type,
                'leader', ug.leader,
                'place', ug.place,
                'description', ug.description,
                'occasion', ug.occasion,
                'data', ug.data
            )
        ), '[]'::JSONB)
        FROM user_group_info ug
        WHERE ug.leader = user_id
    );

    -- Step 2: Query groups where the user is a member in `user_groups` but not the leader
    user_groups := user_groups || (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ug_info.id,
                'title', ug_info.title,
                'type', ug_info.type,
                'leader', ug_info.leader,
                'place', ug_info.place,
                'description', ug_info.description,
                'occasion', ug_info.occasion,
                'data', ug_info.data
            )
        ), '[]'::JSONB)
        FROM user_groups ug
        JOIN user_group_info ug_info ON ug."group" = ug_info.id
        WHERE ug.user = user_id AND ug_info.leader IS DISTINCT FROM user_id
    );

    -- Return code 200 with the combined array of user groups
    RETURN jsonb_build_object('code', 200, 'data', user_groups);
END;
$$;


ALTER FUNCTION public.groups_get_user_groups() OWNER TO postgres;

--
-- Name: guard_form_payment_write_internal(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.guard_form_payment_write_internal(p_saved jsonb, p_candidate jsonb, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb:=p_candidate; incoming jsonb; merged jsonb;
 explicit_selection boolean:=p_input->>'payment_selection_intent'='replace'; conflict boolean:=false;
BEGIN
 IF p_input ? 'payment_selection_intent' AND p_input->>'payment_selection_intent' IS DISTINCT FROM 'replace' THEN
  RAISE EXCEPTION 'PAYMENT_SELECTION_INTENT_INVALID'; END IF;
 incoming:=coalesce(p_input#>'{settings,payments}',p_input#>'{data,payments}');
 IF NOT coalesce(explicit_selection,false) THEN
  IF p_saved#>'{payments,cashEnabled}'='true'::jsonb AND incoming IS NOT NULL THEN
   BEGIN
    merged:=public.merge_form_payments_internal(p_saved->'payments',incoming);
    conflict:=merged IS DISTINCT FROM public.merge_form_payments_internal(p_saved->'payments',NULL);
   EXCEPTION WHEN raise_exception THEN conflict:=true; END;
  END IF;
  IF incoming IS NULL AND p_saved ? 'payments' THEN result:=result||jsonb_build_object('payments',p_saved->'payments'); END IF;
  IF NOT (coalesce(p_input->'settings',p_input->'data','{}'::jsonb) ? 'payment_deadline') AND p_saved ? 'payment_deadline' THEN
   result:=result||jsonb_build_object('payment_deadline',p_saved->'payment_deadline'); END IF;
  IF conflict
   OR (p_saved#>>'{payment_deadline,mode}'='none' AND result#>>'{payment_deadline,mode}' IS DISTINCT FROM 'none')
   OR (result#>'{payments,cashEnabled}'='true'::jsonb AND p_saved#>'{payments,cashEnabled}' IS DISTINCT FROM 'true'::jsonb)
   OR (result#>>'{payment_deadline,mode}'='none' AND p_saved#>>'{payment_deadline,mode}' IS DISTINCT FROM 'none') THEN
   RAISE EXCEPTION '%',jsonb_build_object('code',409,'errorCode','PAYMENT_CLIENT_UPDATE_REQUIRED',
    'message','Update the editor before changing payment selection.')::text;
  END IF;
 END IF;
 IF result#>'{payments,cashEnabled}'='true'::jsonb THEN
  result:=result||'{"payment_deadline":{"mode":"none"}}'::jsonb;
 END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.guard_form_payment_write_internal(p_saved jsonb, p_candidate jsonb, p_input jsonb) OWNER TO postgres;

--
-- Name: guard_form_presale_write_internal(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.guard_form_presale_write_internal(p_previous jsonb, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb:=p_input; incoming jsonb; candidate jsonb; section text; k text;
 previous jsonb:=public.normalize_form_metadata_internal(p_previous); protected boolean; legacy_schedule jsonb; v jsonb;
BEGIN
 protected:=previous#>>'{design,presale_header}' IS NOT NULL;
 IF NOT (p_input ? 'data' OR p_input ? 'settings') THEN RETURN result; END IF;
 incoming:=CASE WHEN p_input ? 'data' THEN public.normalize_form_metadata_internal(p_input->'data') ELSE p_input->'settings' END;
 -- Only converted/new forms use the canonical contract. Other organizations
 -- retain their bounded installed-client ingress until their own authorized
 -- conversion; a shared backend migration must not cut them over implicitly.
 IF NOT protected THEN
  IF incoming#>>'{design,presale_header}' IS NOT NULL THEN
   RAISE invalid_parameter_value USING MESSAGE='PRESALE_MIGRATION_REQUIRED: convert the form before selecting a presale header';
  END IF;
  legacy_schedule:=incoming->'schedule';
  FOREACH k IN ARRAY ARRAY['before_start_message','show_before_start_message'] LOOP
   v:=legacy_schedule->k;
   IF v IS NULL OR v='null'::jsonb THEN CONTINUE; END IF;
   IF (k='before_start_message' AND (jsonb_typeof(v)<>'string' OR length(v#>>'{}')>65536)) OR
      (k='show_before_start_message' AND jsonb_typeof(v)<>'boolean') THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid legacy presale setting';
   END IF;
  END LOOP;
  IF p_input ? 'settings' THEN
   candidate:=public.apply_form_settings_internal(previous,
    incoming #- '{schedule,before_start_message}' #- '{schedule,show_before_start_message}');
   FOREACH k IN ARRAY ARRAY['before_start_message','show_before_start_message'] LOOP
    IF legacy_schedule='null'::jsonb OR legacy_schedule ? k THEN
     IF legacy_schedule='null'::jsonb OR legacy_schedule->k='null'::jsonb THEN
      candidate:=candidate #- ARRAY['schedule',k];
     ELSE
      candidate:=jsonb_set(candidate,'{schedule}',coalesce(candidate->'schedule','{}')||jsonb_build_object(k,legacy_schedule->k));
     END IF;
    END IF;
   END LOOP;
   RETURN jsonb_set(result-'settings','{data}',candidate);
  END IF;
  RETURN jsonb_set(result,'{data}',incoming);
 END IF;
 IF coalesce(incoming#>>'{schedule,before_start_message}','')<>'' OR
    incoming#>>'{schedule,show_before_start_message}'='true' THEN
  RAISE invalid_parameter_value USING MESSAGE='PRESALE_CLIENT_UPGRADE_REQUIRED: reload the form before editing retired content';
 END IF;
 incoming:=incoming #- '{schedule,before_start_message}' #- '{schedule,show_before_start_message}';
 IF protected THEN
  -- Missing/null headings in old full snapshots must never erase the new key.
  IF p_input ? 'settings' AND incoming->'design'='null'::jsonb THEN
   incoming:=jsonb_set(incoming,'{design}',
    (SELECT jsonb_object_agg(value,'null'::jsonb) FROM jsonb_array_elements_text(public.form_settings_keys_internal()->'design')));
  END IF;
  IF incoming#>>'{design,presale_header}' IS NULL THEN
   incoming:=jsonb_set(incoming,'{design}',coalesce(nullif(incoming->'design','null'),'{}') ||
    jsonb_build_object('presale_header',previous#>'{design,presale_header}'));
  END IF;
  IF p_input ? 'data' THEN
   candidate:=public.apply_form_settings_internal(previous,public.form_settings_from_metadata_internal(incoming));
  ELSE candidate:=public.apply_form_settings_internal(previous,incoming); END IF;
  IF p_input->>'expected_aggregate_version' IS NULL THEN
   FOREACH section IN ARRAY ARRAY['schedule','design','sale_opening_notifications'] LOOP
    FOREACH k IN ARRAY CASE section WHEN 'schedule' THEN ARRAY['countdown_title','enable_countdown']
     WHEN 'design' THEN ARRAY['presale_header'] ELSE ARRAY['enabled','collection_paused'] END LOOP
     IF candidate#>ARRAY[section,k] IS DISTINCT FROM previous#>ARRAY[section,k] THEN
      RAISE invalid_parameter_value USING MESSAGE='PRESALE_VERSION_REQUIRED: reload the form before editing the presale page';
     END IF;
    END LOOP;
   END LOOP;
  END IF;
 END IF;
 RETURN jsonb_set(result,ARRAY[CASE WHEN p_input ? 'data' THEN 'data' ELSE 'settings' END],incoming);
END $$;


ALTER FUNCTION public.guard_form_presale_write_internal(p_previous jsonb, p_input jsonb) OWNER TO postgres;

--
-- Name: hold_ticket_batch_spots_internal(bigint, bigint[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hold_ticket_batch_spots_internal(p_form bigint, p_spots bigint[], p_secret uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f public.forms;
BEGIN
 IF cardinality(p_spots)=0 THEN RETURN; END IF;
 IF p_secret IS NULL OR cardinality(p_spots)>200 THEN RAISE EXCEPTION 'BATCH_SPOT_HOLD_REQUIRED'; END IF;
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(p_spots) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND blueprint=f.blueprint AND occasion=f.occasion
  AND order_product_ticket IS NULL AND (secret IS NULL OR secret=p_secret OR secret_expiration_time<=clock_timestamp()))<>cardinality(p_spots) THEN
  RAISE EXCEPTION 'BATCH_SPOT_UNAVAILABLE'; END IF;
 UPDATE eshop.spots SET secret=p_secret,secret_expiration_time=clock_timestamp()+interval '2 minutes'
 WHERE id=ANY(p_spots) AND (secret IS DISTINCT FROM p_secret OR secret_expiration_time<=clock_timestamp());
END $$;


ALTER FUNCTION public.hold_ticket_batch_spots_internal(p_form bigint, p_spots bigint[], p_secret uuid) OWNER TO postgres;

--
-- Name: impact_companion_owners_v1(bigint, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.impact_companion_owners_v1(p_occasion bigint, p_companions uuid[], p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_impacts jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',owners."user") ORDER BY owners."user"),'[]'::jsonb)
  INTO v_impacts
  FROM (SELECT DISTINCT uc."user" FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc.companion=ANY(p_companions)) owners;
  IF jsonb_array_length(v_impacts)>0 THEN
    PERFORM public.record_client_sync_commit_v1(p_occasion,p_source,'profile',
      '[]','{}',v_impacts,'[]','user',NULL);
  END IF;
END $$;


ALTER FUNCTION public.impact_companion_owners_v1(p_occasion bigint, p_companions uuid[], p_source text) OWNER TO postgres;

--
-- Name: impact_private_profile_users_v1(bigint, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.impact_private_profile_users_v1(p_occasion bigint, p_users uuid[], p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_impacts jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',impacted.id) ORDER BY impacted.id),'[]'::jsonb)
  INTO v_impacts
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_users,'{}'::uuid[])) id) impacted
  JOIN public.occasion_users ou
    ON ou.occasion=p_occasion AND ou."user"=impacted.id;
  IF jsonb_array_length(v_impacts)>0 THEN
    PERFORM public.record_client_sync_commit_v1(p_occasion,p_source,'profile',
      '[]','{}',v_impacts,'[]','user',NULL);
  END IF;
END $$;


ALTER FUNCTION public.impact_private_profile_users_v1(p_occasion bigint, p_users uuid[], p_source text) OWNER TO postgres;

--
-- Name: import_occasion_users_from_csv(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_occasion_users_from_csv(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=public.import_profiles_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),p_rows,p_delete_user_ids);
 RETURN jsonb_build_object('code',result->'code')||result->'data';
EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION 'NOT_AUTHORIZED';
END $$;


ALTER FUNCTION public.import_occasion_users_from_csv(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb) OWNER TO postgres;

--
-- Name: import_occasion_users_from_csv_apply_v1(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_occasion_users_from_csv_apply_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_unit_id bigint;
    v_organization_id bigint;
    v_row jsonb;
    v_data_patch jsonb;
    v_services_patch jsonb;
    v_group_assignments jsonb := '[]'::jsonb;
    v_user_id uuid;
    v_email text;
    v_delivery_email text;
    v_existing_email text;
    v_has_delivery_email boolean;
    v_response jsonb;
    v_is_occasion_member boolean;
    v_created integer := 0;
    v_updated integer := 0;
    v_deleted integer := 0;
    v_global_before jsonb;
BEGIN
    SELECT o.unit, u.organization
      INTO v_unit_id, v_organization_id
      FROM public.occasions o
      JOIN public.units u ON u.id = o.unit
     WHERE o.id = p_occasion_id;

    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;

    IF NOT public.get_can_manage_occasion_users(p_occasion_id) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    IF COALESCE(jsonb_typeof(p_rows), 'null') <> 'array'
       OR COALESCE(jsonb_typeof(p_delete_user_ids), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_IMPORT_PAYLOAD';
    END IF;
    IF jsonb_array_length(p_rows) > 10000
       OR jsonb_array_length(p_delete_user_ids) > 10000 THEN
        RAISE EXCEPTION 'IMPORT_PAYLOAD_TOO_LARGE';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE jsonb_typeof(item) <> 'object'
            OR jsonb_typeof(item->'data') <> 'object'
    ) THEN
        RAISE EXCEPTION 'INVALID_IMPORT_ROW';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(btrim(item->'data'->>'email'), '') IS NULL
    ) THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE length(btrim(item->'data'->>'email')) > 254
            OR lower(btrim(item->'data'->>'email'))
               !~ '^[^[:space:]@]+@[^[:space:]@]+$'
            OR (
                item ? 'email_delivery'
                AND (
                    NULLIF(btrim(item->>'email_delivery'), '') IS NULL
                    OR length(btrim(item->>'email_delivery')) > 254
                    OR lower(btrim(item->>'email_delivery'))
                       !~ '^[^[:space:]@]+@[^[:space:]@]+$'
                )
            )
    ) THEN
        RAISE EXCEPTION 'INVALID_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
         GROUP BY lower(btrim(item->'data'->>'email'))
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_ACCOUNT_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(item->>'user_id', '') IS NOT NULL
         GROUP BY item->>'user_id'
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_USER_ID';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
          JOIN jsonb_array_elements_text(p_delete_user_ids) deleted(id)
            ON deleted.id = item->>'user_id'
    ) THEN
        RAISE EXCEPTION 'CONFLICTING_IMPORT_OPERATION';
    END IF;

    -- Serialize all CSV imports for one occasion. The group RPC uses the same
    -- lock, which is transaction-reentrant for this session.
    PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'user-sign-in-email:' || v_organization_id::text, 0
        )
    );

    FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
    LOOP
        IF COALESCE(jsonb_typeof(v_row), 'null') <> 'object'
           OR COALESCE(jsonb_typeof(v_row->'data'), 'null') <> 'object' THEN
            RAISE EXCEPTION 'INVALID_IMPORT_ROW';
        END IF;

        v_data_patch := v_row->'data';
        v_email := lower(btrim(v_data_patch->>'email'));
        v_has_delivery_email := v_row ? 'email_delivery';
        v_delivery_email := lower(btrim(COALESCE(
            v_row->>'email_delivery', v_data_patch->>'email'
        )));
        IF v_email IS NULL OR v_email = '' THEN
            RAISE EXCEPTION 'EMAIL_REQUIRED';
        END IF;
        IF v_delivery_email IS NULL OR v_delivery_email = '' THEN
            RAISE EXCEPTION 'DELIVERY_EMAIL_REQUIRED';
        END IF;

        v_user_id := NULLIF(v_row->>'user_id', '')::uuid;
        v_is_occasion_member := false;

        IF v_user_id IS NULL THEN
            -- Resolve against the occasion first. This makes a retry or a
            -- stale client safe: add_user_to_occasion must never replace an
            -- existing occasion row with profile data.
            SELECT ou."user"
              INTO v_user_id
              FROM public.occasion_users ou
              JOIN public.user_info ui ON ui.id = ou."user"
             WHERE ou.occasion = p_occasion_id
               AND lower(btrim(COALESCE(ui.email_readonly,
                                        ou.data->>'email'))) = v_email
             ORDER BY ou.created_at
             LIMIT 1;

            v_is_occasion_member := v_user_id IS NOT NULL;

            -- A CSV create may also refer to an organization user who simply
            -- is not on this occasion yet. Reuse that identity before creating
            -- a new Auth user.
            IF v_user_id IS NULL THEN
                SELECT ui.id
                  INTO v_user_id
                 FROM public.user_info ui
                 WHERE ui.organization = v_organization_id
                   AND lower(btrim(ui.email_readonly)) = v_email
                 ORDER BY ui.created_at
                 LIMIT 1;
            END IF;

            IF v_user_id IS NULL AND EXISTS (
                SELECT 1 FROM public.user_info ui
                 WHERE ui.organization = v_organization_id
                   AND lower(btrim(ui.email_readonly)) = v_email
            ) THEN
                -- The client assigns deterministic +N account emails for a
                -- CSV batch. Reassigning one here would make a later retry
                -- point at a different person. Without a stable external ID,
                -- reject the stale/colliding input instead of guessing identity.
                RAISE EXCEPTION 'ACCOUNT_EMAIL_ALREADY_EXISTS';
            END IF;

            IF v_user_id IS NULL THEN
                SELECT au.id
                  INTO v_user_id
                  FROM auth.users au
                 WHERE lower(au.email) = lower(v_organization_id::text || '+' || v_email)
                 ORDER BY au.created_at
                 LIMIT 1;
            END IF;

            IF v_user_id IS NULL THEN
                v_user_id := public.create_user_in_organization_with_data_pure(
                    v_organization_id,
                    v_email,
                    NULLIF(v_delivery_email, v_email),
                    encode(gen_random_bytes(16), 'hex'),
                    v_data_patch
                );
            ELSIF NOT EXISTS (
                SELECT 1 FROM public.user_info ui WHERE ui.id = v_user_id
            ) THEN
                INSERT INTO public.user_info (
                    id, organization, email_readonly, email_delivery, data,
                    name, surname, sex
                ) VALUES (
                    v_user_id,
                    v_organization_id,
                    v_email,
                    v_delivery_email,
                    v_data_patch,
                    v_data_patch->>'name',
                    v_data_patch->>'surname',
                    v_data_patch->>'sex'
                );
            END IF;

            IF v_is_occasion_member THEN
                v_updated := v_updated + 1;
            ELSE
                v_response := public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                IF COALESCE((v_response->>'code')::integer, 500) <> 200 THEN
                    RAISE EXCEPTION 'ADD_USER_TO_OCCASION_FAILED: %',
                        COALESCE(v_response->>'message',
                                 'code ' || (v_response->>'code'));
                END IF;
                v_created := v_created + 1;
            END IF;
        ELSE
            SELECT lower(btrim(COALESCE(ui.email_readonly, ou.data->>'email')))
              INTO v_existing_email
              FROM public.occasion_users ou
              JOIN public.user_info ui ON ui.id = ou."user"
             WHERE ou.occasion = p_occasion_id
               AND ou."user" = v_user_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'USER_NOT_ON_OCCASION';
            END IF;
            IF v_existing_email IS DISTINCT FROM v_email THEN
                RAISE EXCEPTION 'USER_EMAIL_MISMATCH';
            END IF;
            v_updated := v_updated + 1;
        END IF;

        SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user_id FOR UPDATE;
        UPDATE public.user_info ui
           SET data = COALESCE(ui.data, '{}'::jsonb)
                      || public.get_user_profile_data_patch(v_data_patch),
               email_delivery = CASE
                   WHEN v_has_delivery_email
                       THEN NULLIF(v_delivery_email, v_email)
                   ELSE ui.email_delivery
               END,
               name = CASE WHEN v_data_patch ? 'name'
                           THEN v_data_patch->>'name' ELSE ui.name END,
               surname = CASE WHEN v_data_patch ? 'surname'
                              THEN v_data_patch->>'surname' ELSE ui.surname END,
               sex = CASE WHEN v_data_patch ? 'sex'
                          THEN v_data_patch->>'sex' ELSE ui.sex END,
               phone = CASE WHEN v_data_patch ? 'phone'
                            THEN v_data_patch->>'phone' ELSE ui.phone END,
               birth_date = CASE WHEN v_data_patch ? 'birthDate'
                                 THEN NULLIF(v_data_patch->>'birthDate', '')::date
                                 ELSE ui.birth_date END
         WHERE ui.id = v_user_id;

        PERFORM public.publish_user_profile_change_internal_v1(v_user_id,p_occasion_id,v_global_before);

        IF v_row ? 'services' THEN
            IF COALESCE(jsonb_typeof(v_row->'services'), 'null') <> 'object' THEN
                RAISE EXCEPTION 'INVALID_SERVICES_PATCH';
            END IF;
            v_services_patch := v_row->'services';
        ELSE
            v_services_patch := NULL;
        END IF;

        UPDATE public.occasion_users ou
           SET data = COALESCE(ou.data, '{}'::jsonb) || v_data_patch,
               services = CASE
                   WHEN v_services_patch IS NULL THEN ou.services
                   ELSE COALESCE(ou.services, '{}'::jsonb) || v_services_patch
               END
         WHERE ou.occasion = p_occasion_id
           AND ou."user" = v_user_id;

        IF v_row ? 'group_title' THEN
            v_group_assignments := v_group_assignments || jsonb_build_array(
                jsonb_build_object(
                    'user_id', v_user_id,
                    'group_title', v_row->>'group_title'
                )
            );
        END IF;
    END LOOP;

    FOR v_user_id IN
        SELECT value::uuid FROM jsonb_array_elements_text(p_delete_user_ids)
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM public.occasion_users ou
             WHERE ou.occasion = p_occasion_id AND ou."user" = v_user_id
        ) THEN
            RAISE EXCEPTION 'DELETE_USER_NOT_ON_OCCASION';
        END IF;
        PERFORM public.remove_occasion_user_domain_internal_v1(p_occasion_id,v_user_id);
        v_deleted := v_deleted + 1;
    END LOOP;

    IF jsonb_array_length(v_group_assignments) > 0 THEN
        PERFORM public.import_user_group_assignments_internal_v1(
            p_occasion_id,
            v_group_assignments
        );
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'created', v_created,
        'updated', v_updated,
        'deleted', v_deleted,
        'groups', jsonb_array_length(v_group_assignments)
    );
END;
$_$;


ALTER FUNCTION public.import_occasion_users_from_csv_apply_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb) OWNER TO postgres;

--
-- Name: import_occasion_users_from_csv_internal_v1(bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_occasion_users_from_csv_internal_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    PERFORM public.validate_occasion_user_csv_import_v1(
        p_occasion_id, p_rows, p_delete_user_ids);
    RETURN public.import_occasion_users_from_csv_apply_v1(
        p_occasion_id, p_rows, p_delete_user_ids);
END;
$$;


ALTER FUNCTION public.import_occasion_users_from_csv_internal_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb) OWNER TO postgres;

--
-- Name: import_payment_reference(bigint, text, bigint, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_payment_reference(p_bank_account bigint, p_source text, p_symbol bigint, p_payload_sha256 text, p_payment bigint DEFAULT NULL::bigint, p_form bigint DEFAULT NULL::bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE ns eshop.payment_reference_namespaces; old eshop.payment_reference_reservations; result uuid;
BEGIN
 PERFORM public.require_service_role();
 PERFORM public.check_bank_account_writable(p_bank_account);
 IF p_symbol IS NULL OR p_symbol NOT BETWEEN 0 AND 9999999999 OR p_source IS NULL OR length(p_source) NOT BETWEEN 1 AND 255
 OR p_payload_sha256 IS NULL OR p_payload_sha256 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_IMPORT_INVALID'; END IF;
 SELECT n.* INTO STRICT ns FROM eshop.payment_reference_namespaces n JOIN eshop.payment_reference_accounts a ON a.namespace_id=n.id
 WHERE a.bank_account_id=p_bank_account FOR UPDATE OF n;
 IF ns.allocation_enabled THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_IMPORT_REQUIRES_LOCK'; END IF;
 IF p_payment IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=p_payment AND bank_account=p_bank_account AND variable_symbol=p_symbol) THEN
  RAISE EXCEPTION 'PAYMENT_REFERENCE_IMPORT_PAYMENT_MISMATCH'; END IF;
 SELECT * INTO old FROM eshop.payment_reference_reservations WHERE namespace_id=ns.id AND source_ref=p_source;
 IF old.id IS NOT NULL THEN
  IF old.variable_symbol<>p_symbol OR old.payload_sha256<>p_payload_sha256 OR old.original_payment_info_id IS DISTINCT FROM p_payment OR old.form_id IS DISTINCT FROM p_form THEN
   RAISE EXCEPTION 'PAYMENT_REFERENCE_SOURCE_CONFLICT'; END IF;
  RETURN old.id;
 END IF;
 IF EXISTS(SELECT 1 FROM eshop.payment_reference_reservations WHERE namespace_id=ns.id AND variable_symbol=p_symbol) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_HISTORICAL_CONFLICT'; END IF;
 INSERT INTO eshop.payment_reference_reservations(namespace_id,variable_symbol,source_ref,policy,payload_sha256,payment_info_id,original_payment_info_id,form_id)
 VALUES(ns.id,p_symbol,p_source,'{"mode":"historical"}',p_payload_sha256,p_payment,p_payment,p_form) RETURNING id INTO result;
 IF p_form IS NOT NULL THEN
  INSERT INTO eshop.payment_reference_form_watermarks(form_id,high_water) VALUES(p_form,p_symbol)
  ON CONFLICT(form_id) DO UPDATE SET high_water=greatest(eshop.payment_reference_form_watermarks.high_water,excluded.high_water);
 END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.import_payment_reference(p_bank_account bigint, p_source text, p_symbol bigint, p_payload_sha256 text, p_payment bigint, p_form bigint) OWNER TO postgres;

--
-- Name: import_profiles_client_sync_v1(bigint, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_profiles_client_sync_v1(p_occasion bigint, p_command_id uuid, p_rows jsonb, p_delete_user_ids jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_unit bigint;
  v_result jsonb; v_before_users uuid[]; v_after_users uuid[]; v_current_users uuid[];
  v_event_ids bigint[]; v_group_ids bigint[]; v_private_impacts jsonb;
  v_publishable boolean; v_actor_replacements jsonb:='[]'::jsonb; v_before_state jsonb; v_after_state jsonb; v_old_impacts jsonb;
BEGIN
  PERFORM public.lock_people_scope_internal_v1(p_occasion);
  SELECT o.unit,NOT o.is_hidden INTO v_unit,v_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_actor IS NULL OR NOT public.get_can_manage_occasion_users(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='profile import permission required'; END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows)<>'array'
    OR p_delete_user_ids IS NULL OR jsonb_typeof(p_delete_user_ids)<>'array'
    OR jsonb_array_length(p_rows)>10000 OR jsonb_array_length(p_delete_user_ids)>10000
    OR octet_length(p_rows::text)+octet_length(p_delete_user_ids::text)>8388608 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid profile import'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'rows',p_rows,'deleteUserIds',p_delete_user_ids)::text,'UTF8'),'sha256'),'hex');
  PERFORM 1 FROM public.user_info ui WHERE ui.id=ANY(ARRAY(
    SELECT (r->>'user_id')::uuid FROM jsonb_array_elements(p_rows) r
    WHERE nullif(r->>'user_id','') IS NOT NULL))
    OR lower(btrim(ui.email_readonly))=ANY(ARRAY(
      SELECT lower(btrim(r#>>'{data,email}')) FROM jsonb_array_elements(p_rows) r))
    ORDER BY ui.id FOR UPDATE;
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.users.import',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  IF NOT public.get_can_manage_occasion_users(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='profile import permission required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
  PERFORM 1 FROM public.user_group_info g WHERE g.occasion=p_occasion
    ORDER BY g.id FOR UPDATE;
  v_before_state:=public.profile_group_import_state_internal_v1(p_occasion);
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT COALESCE(array_agg(DISTINCT e.id),'{}'::bigint[]) INTO v_event_ids
    FROM public.events e LEFT JOIN public.event_users eu ON eu.event=e.id
    LEFT JOIN public.event_users_saved es ON es.event=e.id
    WHERE e.occasion=p_occasion AND (eu."user"=ANY(ARRAY(SELECT value::uuid
      FROM jsonb_array_elements_text(p_delete_user_ids))) OR
      es."user"=ANY(ARRAY(SELECT value::uuid
      FROM jsonb_array_elements_text(p_delete_user_ids))));
  SELECT COALESCE(array_agg(DISTINCT ug."group"),'{}'::bigint[]) INTO v_group_ids
    FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group"
    JOIN public.user_info ui ON ui.id=ug."user"
    WHERE g.occasion=p_occasion AND (ug."user"=ANY(ARRAY(SELECT value::uuid
      FROM jsonb_array_elements_text(p_delete_user_ids))) OR ug."user"=ANY(
      COALESCE((SELECT array_agg((row->>'user_id')::uuid)
        FROM jsonb_array_elements(p_rows) row
        WHERE NULLIF(row->>'user_id','') IS NOT NULL),'{}'::uuid[])) OR
      lower(btrim(ui.email_readonly))=ANY(COALESCE((SELECT array_agg(
        lower(btrim(row#>>'{data,email}'))) FROM jsonb_array_elements(p_rows) row),
        '{}'::text[])));
  v_old_impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(
    SELECT DISTINCT id FROM (
      SELECT value::uuid id FROM jsonb_array_elements_text(p_delete_user_ids)
      UNION SELECT ug."user" FROM public.user_groups ug WHERE ug."group"=ANY(v_group_ids)
      UNION SELECT ou."user" FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user" WHERE ou.occasion=p_occasion AND (ou."user"=ANY(ARRAY(SELECT (row->>'user_id')::uuid FROM jsonb_array_elements(p_rows) row WHERE NULLIF(row->>'user_id','') IS NOT NULL)) OR lower(btrim(ui.email_readonly))=ANY(ARRAY(SELECT lower(btrim(row#>>'{data,email}')) FROM jsonb_array_elements(p_rows) row)))
    ) impacted));
  v_private_impacts:=public.remove_user_activity_internal_v1(p_occasion,ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(p_delete_user_ids)));
  v_result:=public.import_occasion_users_from_csv_internal_v1(
    p_occasion,p_rows,p_delete_user_ids);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE data_exception USING MESSAGE=COALESCE(v_result->>'message','profile import failed');
  END IF;
  v_after_state:=public.profile_group_import_state_internal_v1(p_occasion);
  IF v_before_state=v_after_state THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,v_result); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_after_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT COALESCE(array_agg(DISTINCT ou."user" ORDER BY ou."user"),'{}'::uuid[])
    INTO v_current_users FROM public.occasion_users ou
    JOIN public.user_info ui ON ui.id=ou."user"
    WHERE ou.occasion=p_occasion AND (ou."user"=ANY(COALESCE((SELECT array_agg(
      (row->>'user_id')::uuid) FROM jsonb_array_elements(p_rows) row
      WHERE NULLIF(row->>'user_id','') IS NOT NULL),'{}'::uuid[])) OR
      lower(btrim(COALESCE(ui.email_readonly,ou.data->>'email')))=ANY(COALESCE((
        SELECT array_agg(lower(btrim(row#>>'{data,email}')))
        FROM jsonb_array_elements(p_rows) row),'{}'::text[])) OR
      NOT ou."user"=ANY(v_before_users));
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_group_ids||COALESCE((
    SELECT array_agg(DISTINCT ug."group") FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    WHERE g.occasion=p_occasion AND ug."user"=ANY(v_current_users)),
    '{}'::bigint[])) id ORDER BY id) INTO v_group_ids;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_current_users||COALESCE((
    SELECT array_agg(DISTINCT ug."user") FROM public.user_groups ug
    WHERE ug."group"=ANY(v_group_ids)),'{}'::uuid[])) id
    JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id
    ORDER BY id) INTO v_current_users;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,id::text,1
    FROM unnest(v_current_users) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'user_group','occasion',p_occasion,key,1 FROM jsonb_each(v_after_state->'groups') WHERE value IS DISTINCT FROM v_before_state->'groups'->key
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  DELETE FROM public.client_aggregate_versions v WHERE v.aggregate_type='occasion_user'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=ANY(ARRAY(SELECT value FROM jsonb_array_elements_text(
      p_delete_user_ids)));
  v_private_impacts:=v_private_impacts||v_old_impacts||public.group_profile_impacts_internal_v1(p_occasion,v_current_users);
  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'component',x->>'userId'),'[]') INTO v_private_impacts FROM (SELECT DISTINCT value x FROM jsonb_array_elements(v_private_impacts) WHERE EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=(value->>'userId')::uuid)) current_impacts;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'component'='private_profile' AND x->>'userId'=v_actor::text) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.users.import','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',NULL,'operation','import',
      'safeLabel','Profile CSV import','changedFields',jsonb_build_array('profiles','services','groups'))),
    CASE WHEN cardinality(v_event_ids)>0 AND v_publishable
      THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    v_private_impacts,CASE WHEN cardinality(v_event_ids)>0 AND v_publishable
      THEN COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'component','live_public','entityId',id)) FROM unnest(v_event_ids) id),'[]'::jsonb)
      ELSE '[]'::jsonb END,v_result,'{}','[]','user',NULL,v_actor_replacements);
END; $$;


ALTER FUNCTION public.import_profiles_client_sync_v1(p_occasion bigint, p_command_id uuid, p_rows jsonb, p_delete_user_ids jsonb) OWNER TO postgres;

--
-- Name: import_ticket_profiles_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_ticket_profiles_internal_v1(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    ticket_record RECORD;
    v_global_before jsonb;
    order_data JSONB;
    user_email TEXT;
    v_sign_in_email TEXT;
    user_name TEXT;
    user_surname TEXT;
    user_sex TEXT;
    user_data JSONB;
    v_user_id UUID;
    v_organization_id BIGINT;
    field_element JSONB;
    field_key TEXT;

    field_info RECORD;
    field_value TEXT;
    v_text1 TEXT;
    v_text2 TEXT;
    v_birthDate TEXT;

    v_occasion_user_row public.occasion_users%ROWTYPE;
    new_email TEXT;

    -- Arrays to store results
    inserted_users JSONB[] := ARRAY[]::JSONB[];
    updated_users JSONB[] := ARRAY[]::JSONB[];
    deleted_users JSONB[] := ARRAY[]::JSONB[];

    storno_record RECORD;
    deleted_user_info RECORD;
    update_report_info RECORD;
BEGIN
    -- 1. Get the organization_id from the occasion
    SELECT organization INTO v_organization_id FROM public.occasions WHERE id = p_occasion_id;

    IF v_organization_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with id % not found or has no organization.', p_occasion_id;
    END IF;

    -- 2. Handle Storno (Canceled) Tickets
    FOR storno_record IN
        SELECT ou."user", ou.ticket
        FROM public.occasion_users ou
        JOIN eshop.tickets t ON ou.ticket = t.id
        WHERE ou.occasion = p_occasion_id
          AND ou.ticket IS NOT NULL
          AND t.state = 'storno'
    LOOP
        SELECT ui.email_readonly, ui.name, ui.surname
        INTO deleted_user_info
        FROM public.user_info ui
        WHERE ui.id = storno_record."user";

        PERFORM public.remove_occasion_user_domain_internal_v1(p_occasion_id, storno_record."user");

        deleted_users := array_append(deleted_users,
            jsonb_build_object(
                'email', deleted_user_info.email_readonly,
                'name', deleted_user_info.name,
                'surname', deleted_user_info.surname,
                'ticket_id', storno_record.ticket
            )
        );
    END LOOP;

    -- 3. IMPORT & SYNC LOGIC
    FOR ticket_record IN
        SELECT DISTINCT ON (t.id)
            t.id as ticket_id,
            o.data as order_data,
            ou."user" as existing_occasion_user_id
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        LEFT JOIN public.occasion_users ou ON t.id = ou.ticket
        WHERE t.occasion = p_occasion_id
          AND t.state IN ('ordered', 'sent', 'used', 'paid')
          AND NOT EXISTS(SELECT 1 FROM eshop.ticket_batch_items i WHERE i.ticket_id=t.id)
        ORDER BY t.id, o.id DESC
    LOOP
        order_data := ticket_record.order_data;
        user_email := lower(trim(order_data->>'email'));
        user_name := order_data->>'name';
        user_surname := order_data->>'surname';
        user_sex := NULL;

        v_text1 := NULL;
        v_text2 := NULL;
        v_birthDate := NULL;

        -- Extract Form Fields (Generic loop, checking specifically for known titles)
        IF jsonb_typeof(order_data->'fields') = 'array' THEN
            FOR field_element IN SELECT * FROM jsonb_array_elements(order_data->'fields')
            LOOP
                field_key := (SELECT * FROM jsonb_object_keys(field_element));
                field_value := field_element->>field_key;

                SELECT ff.type, ff.title
                INTO field_info
                FROM public.form_fields ff
                WHERE ff.id = field_key::bigint;

                -- Basic mappings
                IF field_info.type = 'sex' THEN
                    user_sex := field_value;
                END IF;

--                -- Custom mappings (removed IF ID=36 check to make it generic for the feature)
--                CASE field_info.title
--                    WHEN 'Typ účastníka' THEN
--                        v_text1 := field_value;
--                    WHEN 'Přípravný tým' THEN
--                        v_text2 := field_value;
--                    WHEN 'Datum narození' THEN
--                        v_birthDate := field_value;
--                    ELSE
--                        -- Do nothing
--                END CASE;
            END LOOP;
        END IF;

        -- ========================================================
        -- CASE A: EXISTING OCCASION USER -> UPDATE BY ID
        -- ========================================================
        IF ticket_record.existing_occasion_user_id IS NOT NULL THEN
            DECLARE
                current_ou_data JSONB;
                update_payload JSONB := '{}'::jsonb;
                target_uuid UUID := ticket_record.existing_occasion_user_id; -- STRICT ID DEPENDENCY
            BEGIN
                SELECT ui.email_readonly
                  INTO v_sign_in_email
                  FROM public.user_info ui
                 WHERE ui.id = target_uuid;

                -- Get current occasion data
                SELECT data INTO current_ou_data
                FROM public.occasion_users
                WHERE "user" = target_uuid AND occasion = p_occasion_id;

                -- Build payload comparing Order Data vs Current DB Data
                IF v_sign_in_email IS NOT NULL AND COALESCE(current_ou_data->>'email', 'NULL_FLAG') != v_sign_in_email THEN
                    update_payload := update_payload || jsonb_build_object('email', v_sign_in_email);
                END IF;
                IF user_name IS NOT NULL AND COALESCE(current_ou_data->>'name', 'NULL_FLAG') != user_name THEN
                    update_payload := update_payload || jsonb_build_object('name', user_name);
                END IF;
                IF user_surname IS NOT NULL AND COALESCE(current_ou_data->>'surname', 'NULL_FLAG') != user_surname THEN
                    update_payload := update_payload || jsonb_build_object('surname', user_surname);
                END IF;
                IF user_sex IS NOT NULL AND COALESCE(current_ou_data->>'sex', 'NULL_FLAG') != user_sex THEN
                    update_payload := update_payload || jsonb_build_object('sex', user_sex);
                END IF;
                -- Custom fields
--                IF v_text1 IS NOT NULL AND COALESCE(current_ou_data->>'text1', 'NULL_FLAG') != v_text1 THEN
--                    update_payload := update_payload || jsonb_build_object('text1', v_text1);
--                END IF;
--                IF v_text2 IS NOT NULL AND COALESCE(current_ou_data->>'text2', 'NULL_FLAG') != v_text2 THEN
--                    update_payload := update_payload || jsonb_build_object('text2', v_text2);
--                END IF;
--                IF v_birthDate IS NOT NULL AND COALESCE(current_ou_data->>'birthDate', 'NULL_FLAG') != v_birthDate THEN
--                    update_payload := update_payload || jsonb_build_object('birthDate', v_birthDate);
--                END IF;

                -- Perform Updates if needed
                IF update_payload != '{}'::jsonb THEN
                    -- 1. Update Occasion Specific Data
                    UPDATE public.occasion_users
                    SET data = data || update_payload
                    WHERE "user" = target_uuid
                      AND occasion = p_occasion_id;

                    -- 2. Update Global User Info (Sync core fields)

                    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=target_uuid FOR UPDATE;
UPDATE public.user_info
                    SET
                        name = COALESCE(update_payload->>'name', name),
                        surname = COALESCE(update_payload->>'surname', surname),
                        sex = COALESCE(update_payload->>'sex', sex)
                    WHERE id = target_uuid;
                    PERFORM public.publish_user_profile_change_internal_v1(target_uuid,p_occasion_id,v_global_before);

                    -- Logging
                    SELECT ui.email_readonly, ui.name, ui.surname
                    INTO update_report_info
                    FROM public.user_info ui
                    WHERE ui.id = target_uuid;

                    updated_users := array_append(updated_users,
                        jsonb_build_object(
                            'id', target_uuid, -- Return ID for safety
                            'email', update_report_info.email_readonly,
                            'name', update_report_info.name,
                            'surname', update_report_info.surname,
                            'reason', 'data_sync',
                            'changes', update_payload
                        )
                    );
                END IF;
            END;

        -- ========================================================
        -- CASE B: NO LINKED USER -> CREATE OR LINK (FALLBACK TO EMAIL)
        -- ========================================================
        ELSE
            -- 1. Check if user exists globally by email
            SELECT id INTO v_user_id
            FROM public.user_info
            WHERE email_readonly = user_email AND organization = v_organization_id;

            IF v_user_id IS NOT NULL THEN
                -- USER EXISTS GLOBALLY
                SELECT * INTO v_occasion_user_row
                FROM public.occasion_users
                WHERE "user" = v_user_id AND occasion = p_occasion_id;

                IF v_occasion_user_row."user" IS NOT NULL AND v_occasion_user_row.ticket IS NOT NULL THEN
                    -- User exists on occasion AND has a ticket -> DUPLICATE EMAIL Conflict
                    -- Create new user with +suffix
                    new_email := public.allocate_user_sign_in_email(
                        v_organization_id, user_email
                    );

                    user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', new_email, 'sex', user_sex);
--                    IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                    IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                    IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                    v_user_id := create_user_in_organization_with_data_pure(
                        v_organization_id, new_email, user_email,
                        gen_random_uuid()::text, user_data
                    );
                    PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                    UPDATE public.occasion_users SET ticket = ticket_record.ticket_id WHERE "user" = v_user_id AND occasion = p_occasion_id;

                    inserted_users := array_append(inserted_users, jsonb_build_object('id', v_user_id, 'email', new_email, 'name', user_name, 'surname', user_surname));
                ELSE
                    -- LINK EXISTING USER (User exists, but no ticket on this occasion)

                    user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', user_email, 'sex', user_sex);
--                    IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                    IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                    IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                    -- Update Global Info

                    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user_id FOR UPDATE;
UPDATE public.user_info
                    SET
                        name = user_name,
                        surname = user_surname,
                        sex = user_sex,
                        data = COALESCE(user_info.data, '{}'::jsonb) || user_data
                    WHERE id = v_user_id;
                    PERFORM public.publish_user_profile_change_internal_v1(v_user_id,p_occasion_id,v_global_before);

                    IF v_occasion_user_row."user" IS NULL THEN
                        -- Link to occasion
                        PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                    END IF;

                    -- Update Occasion Data & Ticket
                    UPDATE public.occasion_users
                    SET
                        data = COALESCE(occasion_users.data, '{}'::jsonb) || user_data,
                        ticket = ticket_record.ticket_id
                    WHERE "user" = v_user_id AND occasion = p_occasion_id;

                    updated_users := array_append(updated_users, jsonb_build_object('id', v_user_id, 'email', user_email, 'name', user_name, 'surname', user_surname, 'reason', 'initial_import_link'));
                END IF;
            ELSE
                -- NEW USER CREATION
                user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', user_email, 'sex', user_sex);
--                IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                v_user_id := create_user_in_organization_with_data_pure(
                    v_organization_id, user_email, user_email,
                    gen_random_uuid()::text, user_data
                );
                PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                UPDATE public.occasion_users SET ticket = ticket_record.ticket_id WHERE "user" = v_user_id AND occasion = p_occasion_id;

                inserted_users := array_append(inserted_users, jsonb_build_object('id', v_user_id, 'email', user_email, 'name', user_name, 'surname', user_surname));
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'inserted', to_jsonb(inserted_users),
        'updated', to_jsonb(updated_users),
        'deleted', to_jsonb(deleted_users)
    );
END;
$$;


ALTER FUNCTION public.import_ticket_profiles_internal_v1(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: import_user_group_assignments(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_user_group_assignments(p_occasion_id bigint, p_assignments jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.replace_group_assignments_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),p_assignments);
EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION 'NOT_AUTHORIZED';
END $$;


ALTER FUNCTION public.import_user_group_assignments(p_occasion_id bigint, p_assignments jsonb) OWNER TO postgres;

--
-- Name: import_user_group_assignments_internal_v1(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_user_group_assignments_internal_v1(p_occasion_id bigint, p_assignments jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_assignment record;
    v_group_id bigint;
    v_group_title text;
    v_keep_admin boolean;
    v_unit_id bigint;
BEGIN
    SELECT o.unit INTO v_unit_id
    FROM public.occasions o
    WHERE o.id = p_occasion_id;

    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;

    IF NOT public.can_import_group_assignments(p_occasion_id) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    IF COALESCE(jsonb_typeof(p_assignments), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_ASSIGNMENTS';
    END IF;

    -- Serialize imports for one occasion so normalized group titles cannot be
    -- created twice by concurrent CSV imports.
    PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion_id);

    FOR v_assignment IN
        SELECT assignment.user_id, assignment.group_title
        FROM jsonb_to_recordset(p_assignments)
            AS assignment(user_id uuid, group_title text)
    LOOP
        IF v_assignment.user_id IS NULL OR NOT EXISTS (
            SELECT 1
            FROM public.occasion_users ou
            WHERE ou.occasion = p_occasion_id
              AND ou."user" = v_assignment.user_id
        ) THEN
            RAISE EXCEPTION 'USER_NOT_ON_OCCASION';
        END IF;

        v_group_title := NULLIF(btrim(v_assignment.group_title), '');
        v_group_id := NULL;
        v_keep_admin := false;

        IF v_group_title IS NOT NULL THEN
            SELECT ugi.id
            INTO v_group_id
            FROM public.user_group_info ugi
            WHERE ugi.occasion = p_occasion_id
              AND ugi.type IS NULL
              AND lower(btrim(ugi.title)) = lower(v_group_title)
            ORDER BY ugi.id
            LIMIT 1;

            IF v_group_id IS NULL THEN
                INSERT INTO public.user_group_info (occasion, title)
                VALUES (p_occasion_id, v_group_title)
                RETURNING id INTO v_group_id;
            ELSE
                SELECT COALESCE(ug.is_admin, false)
                INTO v_keep_admin
                FROM public.user_groups ug
                WHERE ug."user" = v_assignment.user_id
                  AND ug."group" = v_group_id;

                v_keep_admin := COALESCE(v_keep_admin, false);
            END IF;
        END IF;

        DELETE FROM public.user_groups ug
        USING public.user_group_info ugi
        WHERE ug."group" = ugi.id
          AND ug."user" = v_assignment.user_id
          AND ugi.occasion = p_occasion_id
          AND ugi.type IS NULL;

        IF v_group_id IS NOT NULL THEN
            INSERT INTO public.user_groups ("user", "group", is_admin)
            VALUES (v_assignment.user_id, v_group_id, v_keep_admin);
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION public.import_user_group_assignments_internal_v1(p_occasion_id bigint, p_assignments jsonb) OWNER TO postgres;

--
-- Name: import_users_from_tickets(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_users_from_tickets(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    ticket_record RECORD;
    order_data JSONB;
    user_email TEXT;
    v_sign_in_email TEXT;
    user_name TEXT;
    user_surname TEXT;
    user_sex TEXT;
    user_data JSONB;
    v_user_id UUID;
    v_organization_id BIGINT;
    field_element JSONB;
    field_key TEXT;

    field_info RECORD;
    field_value TEXT;
    v_text1 TEXT;
    v_text2 TEXT;
    v_birthDate TEXT;

    v_occasion_user_row public.occasion_users%ROWTYPE;
    new_email TEXT;

    -- Arrays to store results
    inserted_users JSONB[] := ARRAY[]::JSONB[];
    updated_users JSONB[] := ARRAY[]::JSONB[];
    deleted_users JSONB[] := ARRAY[]::JSONB[];

    storno_record RECORD;
    deleted_user_info RECORD;
    update_report_info RECORD;
BEGIN
    PERFORM public.lock_activity_aggregate_internal_v1(p_occasion_id);
    -- 1. Get the organization_id from the occasion
    SELECT organization INTO v_organization_id FROM public.occasions WHERE id = p_occasion_id;

    IF v_organization_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with id % not found or has no organization.', p_occasion_id;
    END IF;

    -- 2. Handle Storno (Canceled) Tickets
    FOR storno_record IN
        SELECT ou."user", ou.ticket
        FROM public.occasion_users ou
        JOIN eshop.tickets t ON ou.ticket = t.id
        WHERE ou.occasion = p_occasion_id
          AND ou.ticket IS NOT NULL
          AND t.state = 'storno'
    LOOP
        SELECT ui.email_readonly, ui.name, ui.surname
        INTO deleted_user_info
        FROM public.user_info ui
        WHERE ui.id = storno_record."user";

        PERFORM public.remove_occasion_user_domain_internal_v1(p_occasion_id,storno_record."user");

        deleted_users := array_append(deleted_users,
            jsonb_build_object(
                'email', deleted_user_info.email_readonly,
                'name', deleted_user_info.name,
                'surname', deleted_user_info.surname,
                'ticket_id', storno_record.ticket
            )
        );
    END LOOP;

    -- 3. IMPORT & SYNC LOGIC
    FOR ticket_record IN
        SELECT DISTINCT ON (t.id)
            t.id as ticket_id,
            o.data as order_data,
            ou."user" as existing_occasion_user_id
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        LEFT JOIN public.occasion_users ou ON t.id = ou.ticket
        WHERE t.occasion = p_occasion_id
          AND t.state IN ('ordered', 'sent', 'used', 'paid')
        ORDER BY t.id, o.id DESC
    LOOP
        order_data := ticket_record.order_data;
        user_email := lower(trim(order_data->>'email'));
        user_name := order_data->>'name';
        user_surname := order_data->>'surname';
        user_sex := NULL;

        v_text1 := NULL;
        v_text2 := NULL;
        v_birthDate := NULL;

        -- Extract Form Fields (Generic loop, checking specifically for known titles)
        IF jsonb_typeof(order_data->'fields') = 'array' THEN
            FOR field_element IN SELECT * FROM jsonb_array_elements(order_data->'fields')
            LOOP
                field_key := (SELECT * FROM jsonb_object_keys(field_element));
                field_value := field_element->>field_key;

                SELECT ff.type, ff.title
                INTO field_info
                FROM public.form_fields ff
                WHERE ff.id = field_key::bigint;

                -- Basic mappings
                IF field_info.type = 'sex' THEN
                    user_sex := field_value;
                END IF;

--                -- Custom mappings (removed IF ID=36 check to make it generic for the feature)
--                CASE field_info.title
--                    WHEN 'Typ účastníka' THEN
--                        v_text1 := field_value;
--                    WHEN 'Přípravný tým' THEN
--                        v_text2 := field_value;
--                    WHEN 'Datum narození' THEN
--                        v_birthDate := field_value;
--                    ELSE
--                        -- Do nothing
--                END CASE;
            END LOOP;
        END IF;

        -- ========================================================
        -- CASE A: EXISTING OCCASION USER -> UPDATE BY ID
        -- ========================================================
        IF ticket_record.existing_occasion_user_id IS NOT NULL THEN
            DECLARE
                current_ou_data JSONB;
                update_payload JSONB := '{}'::jsonb;
                target_uuid UUID := ticket_record.existing_occasion_user_id; -- STRICT ID DEPENDENCY
            BEGIN
                SELECT ui.email_readonly
                  INTO v_sign_in_email
                  FROM public.user_info ui
                 WHERE ui.id = target_uuid;

                -- Get current occasion data
                SELECT data INTO current_ou_data
                FROM public.occasion_users
                WHERE "user" = target_uuid AND occasion = p_occasion_id;

                -- Build payload comparing Order Data vs Current DB Data
                IF v_sign_in_email IS NOT NULL AND COALESCE(current_ou_data->>'email', 'NULL_FLAG') != v_sign_in_email THEN
                    update_payload := update_payload || jsonb_build_object('email', v_sign_in_email);
                END IF;
                IF user_name IS NOT NULL AND COALESCE(current_ou_data->>'name', 'NULL_FLAG') != user_name THEN
                    update_payload := update_payload || jsonb_build_object('name', user_name);
                END IF;
                IF user_surname IS NOT NULL AND COALESCE(current_ou_data->>'surname', 'NULL_FLAG') != user_surname THEN
                    update_payload := update_payload || jsonb_build_object('surname', user_surname);
                END IF;
                IF user_sex IS NOT NULL AND COALESCE(current_ou_data->>'sex', 'NULL_FLAG') != user_sex THEN
                    update_payload := update_payload || jsonb_build_object('sex', user_sex);
                END IF;
                -- Custom fields
--                IF v_text1 IS NOT NULL AND COALESCE(current_ou_data->>'text1', 'NULL_FLAG') != v_text1 THEN
--                    update_payload := update_payload || jsonb_build_object('text1', v_text1);
--                END IF;
--                IF v_text2 IS NOT NULL AND COALESCE(current_ou_data->>'text2', 'NULL_FLAG') != v_text2 THEN
--                    update_payload := update_payload || jsonb_build_object('text2', v_text2);
--                END IF;
--                IF v_birthDate IS NOT NULL AND COALESCE(current_ou_data->>'birthDate', 'NULL_FLAG') != v_birthDate THEN
--                    update_payload := update_payload || jsonb_build_object('birthDate', v_birthDate);
--                END IF;

                -- Perform Updates if needed
                IF update_payload != '{}'::jsonb THEN
                    -- 1. Update Occasion Specific Data
                    UPDATE public.occasion_users
                    SET data = data || update_payload
                    WHERE "user" = target_uuid
                      AND occasion = p_occasion_id;

                    -- 2. Update Global User Info (Sync core fields)
                    UPDATE public.user_info
                    SET
                        name = COALESCE(update_payload->>'name', name),
                        surname = COALESCE(update_payload->>'surname', surname),
                        sex = COALESCE(update_payload->>'sex', sex)
                    WHERE id = target_uuid;

                    -- Logging
                    SELECT ui.email_readonly, ui.name, ui.surname
                    INTO update_report_info
                    FROM public.user_info ui
                    WHERE ui.id = target_uuid;

                    updated_users := array_append(updated_users,
                        jsonb_build_object(
                            'id', target_uuid, -- Return ID for safety
                            'email', update_report_info.email_readonly,
                            'name', update_report_info.name,
                            'surname', update_report_info.surname,
                            'reason', 'data_sync',
                            'changes', update_payload
                        )
                    );
                END IF;
            END;

        -- ========================================================
        -- CASE B: NO LINKED USER -> CREATE OR LINK (FALLBACK TO EMAIL)
        -- ========================================================
        ELSE
            -- 1. Check if user exists globally by email
            SELECT id INTO v_user_id
            FROM public.user_info
            WHERE email_readonly = user_email AND organization = v_organization_id;

            IF v_user_id IS NOT NULL THEN
                -- USER EXISTS GLOBALLY
                SELECT * INTO v_occasion_user_row
                FROM public.occasion_users
                WHERE "user" = v_user_id AND occasion = p_occasion_id;

                IF v_occasion_user_row."user" IS NOT NULL AND v_occasion_user_row.ticket IS NOT NULL THEN
                    -- User exists on occasion AND has a ticket -> DUPLICATE EMAIL Conflict
                    -- Create new user with +suffix
                    new_email := public.allocate_user_sign_in_email(
                        v_organization_id, user_email
                    );

                    user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', new_email, 'sex', user_sex);
--                    IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                    IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                    IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                    v_user_id := create_user_in_organization_with_data_pure(
                        v_organization_id, new_email, user_email,
                        gen_random_uuid()::text, user_data
                    );
                    PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                    UPDATE public.occasion_users SET ticket = ticket_record.ticket_id WHERE "user" = v_user_id AND occasion = p_occasion_id;

                    inserted_users := array_append(inserted_users, jsonb_build_object('id', v_user_id, 'email', new_email, 'name', user_name, 'surname', user_surname));
                ELSE
                    -- LINK EXISTING USER (User exists, but no ticket on this occasion)

                    user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', user_email, 'sex', user_sex);
--                    IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                    IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                    IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                    -- Update Global Info
                    UPDATE public.user_info
                    SET
                        name = user_name,
                        surname = user_surname,
                        sex = user_sex,
                        data = COALESCE(user_info.data, '{}'::jsonb) || user_data
                    WHERE id = v_user_id;

                    IF v_occasion_user_row."user" IS NULL THEN
                        -- Link to occasion
                        PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                    END IF;

                    -- Update Occasion Data & Ticket
                    UPDATE public.occasion_users
                    SET
                        data = COALESCE(occasion_users.data, '{}'::jsonb) || user_data,
                        ticket = ticket_record.ticket_id
                    WHERE "user" = v_user_id AND occasion = p_occasion_id;

                    updated_users := array_append(updated_users, jsonb_build_object('id', v_user_id, 'email', user_email, 'name', user_name, 'surname', user_surname, 'reason', 'initial_import_link'));
                END IF;
            ELSE
                -- NEW USER CREATION
                user_data := jsonb_build_object('name', user_name, 'surname', user_surname, 'email', user_email, 'sex', user_sex);
--                IF v_text1 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text1', v_text1); END IF;
--                IF v_text2 IS NOT NULL THEN user_data := user_data || jsonb_build_object('text2', v_text2); END IF;
--                IF v_birthDate IS NOT NULL THEN user_data := user_data || jsonb_build_object('birthDate', v_birthDate); END IF;

                v_user_id := create_user_in_organization_with_data_pure(
                    v_organization_id, user_email, user_email,
                    gen_random_uuid()::text, user_data
                );
                PERFORM public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                UPDATE public.occasion_users SET ticket = ticket_record.ticket_id WHERE "user" = v_user_id AND occasion = p_occasion_id;

                inserted_users := array_append(inserted_users, jsonb_build_object('id', v_user_id, 'email', user_email, 'name', user_name, 'surname', user_surname));
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'inserted', to_jsonb(inserted_users),
        'updated', to_jsonb(updated_users),
        'deleted', to_jsonb(deleted_users)
    );
END;
$$;


ALTER FUNCTION public.import_users_from_tickets(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: import_users_from_tickets_client_sync_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_users_from_tickets_client_sync_v1(p_occasion bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before_users uuid[];
BEGIN
  PERFORM public.lock_people_scope_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'profile.tickets.import',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
  PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT id FROM eshop.orders WHERE occasion=p_occasion));
  PERFORM 1 FROM public.user_info ui WHERE ui.id IN(SELECT "user" FROM public.occasion_users WHERE occasion=p_occasion)
   OR (ui.organization=(SELECT organization FROM public.occasions WHERE id=p_occasion) AND ui.email_readonly IN(
    SELECT lower(btrim(o.data->>'email')) FROM eshop.orders o WHERE o.occasion=p_occasion)) ORDER BY ui.id FOR UPDATE;
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  PERFORM 1 FROM public.user_group_info WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion ORDER BY "user" FOR UPDATE;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  v_result:=public.import_users_from_tickets_ws_internal_v1(p_occasion);
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,p_occasion,'profile.tickets.import',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',NULL,'operation','import',
      'safeLabel','Ticket profile import','changedFields',jsonb_build_array(
        'profile','ticket','membership'))),v_before_users,v_result);
END; $$;


ALTER FUNCTION public.import_users_from_tickets_client_sync_v1(p_occasion bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: import_users_from_tickets_ws(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_users_from_tickets_ws(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN RETURN public.import_users_from_tickets_client_sync_v1(p_occasion_id,extensions.gen_random_uuid()); END $$;


ALTER FUNCTION public.import_users_from_tickets_ws(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: import_users_from_tickets_ws_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_users_from_tickets_ws_internal_v1(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB result from the import function.
    import_results JSONB;
BEGIN
    -- Verify if the user is an editor on the occasion.
    -- If this check fails, it will raise an exception.
    IF (SELECT get_is_editor_on_occasion(p_occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User is not an editor for this occasion.';
    END IF;

    -- Call the original function to import users and store the returned JSONB
    -- in our variable instead of discarding it with PERFORM.
    import_results := public.import_ticket_profiles_internal_v1(p_occasion_id);

    -- Return a new JSONB object that includes the standard success code/message
    -- as well as the 'data' key containing the actual import results.
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Import completed successfully.',
        'data', import_results
    );
END;
$$;


ALTER FUNCTION public.import_users_from_tickets_ws_internal_v1(p_occasion_id bigint) OWNER TO postgres;

--
-- Name: ingest_bank_sync_transaction(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ingest_bank_sync_transaction(p_instance_id text, p_consumer_app_id text, p_body_sha256 text, p_envelope jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_data jsonb := p_envelope->'data';
  v_delivery text := p_envelope->>'delivery_id';
  v_connection eshop.bank_sync_connections%ROWTYPE;
  v_inbox eshop.bank_sync_inbox%ROWTYPE;
  v_tx eshop.transactions%ROWTYPE;
  v_ids bigint[];
  v_identity text := v_data->>'transaction_id';
  v_amount numeric;
  v_date timestamptz;
  v_outcome text;
  v_match jsonb;
  v_receipt jsonb;
  v_source_id bigint;
  v_command_id bigint;
BEGIN
  PERFORM public.require_service_role();
  IF p_consumer_app_id IS DISTINCT FROM 'festapp' OR nullif(p_instance_id,'') IS NULL
    OR p_body_sha256 IS NULL OR p_body_sha256 !~ '^[0-9a-f]{64}$'
    OR p_envelope->>'event' IS DISTINCT FROM 'transaction.received'
    OR p_envelope->>'event_version' IS DISTINCT FROM '2'
    OR v_delivery IS NULL OR v_delivery !~ '^[0-9A-HJKMNP-TV-Z]{26}$'
    OR v_data->>'currency' IS NULL OR v_data->>'currency' NOT IN ('CZK','EUR','USD')
    OR jsonb_typeof(v_data->'amount_cents') IS DISTINCT FROM 'number'
    OR v_data->>'amount_cents' !~ '^-?[0-9]+$'
    OR abs((v_data->>'amount_cents')::numeric)>9007199254740991
    OR v_data->>'id' IS NULL OR v_data->>'bank_account_id' IS NULL
    OR v_data->>'date' IS NULL OR v_data->>'date' !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
    RAISE EXCEPTION 'BANK_SYNC_INVALID_ENVELOPE';
  END IF;
  v_amount := (v_data->>'amount_cents')::numeric/100;
  v_date := (v_data->>'date')::timestamptz;
  IF v_data->>'direction' IS DISTINCT FROM (CASE WHEN v_amount>0 THEN 'incoming' WHEN v_amount<0 THEN 'outgoing' ELSE 'zero' END) THEN
    RAISE EXCEPTION 'BANK_SYNC_INVALID_DIRECTION';
  END IF;

  -- Lock order: delivery advisory -> connection -> identity/ledger -> payment_info.
  -- Legacy writers hold the same account row barrier before any ledger writes.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_instance_id||':'||p_consumer_app_id||':'||v_delivery,0));
  SELECT * INTO v_inbox FROM eshop.bank_sync_inbox
    WHERE instance_id=p_instance_id AND consumer_app_id=p_consumer_app_id AND delivery_id=v_delivery;
  IF FOUND THEN
    IF v_inbox.body_sha256<>p_body_sha256 THEN RAISE EXCEPTION 'BANK_SYNC_DELIVERY_CONFLICT'; END IF;
    RETURN v_inbox.receipt;
  END IF;
  SELECT * INTO v_connection FROM eshop.bank_sync_connections
    WHERE instance_id=p_instance_id AND consumer_app_id=p_consumer_app_id
      AND remote_bank_account_id=v_data->>'bank_account_id' FOR UPDATE;
  INSERT INTO eshop.bank_sync_inbox(instance_id,consumer_app_id,delivery_id,body_sha256,event_version,
    remote_transaction_id,connection_id,epoch,payload)
    VALUES(p_instance_id,p_consumer_app_id,v_delivery,p_body_sha256,'2',v_data->>'id',v_connection.id,v_connection.epoch,p_envelope);

  IF v_connection.id IS NULL THEN v_outcome:='quarantined_scope';
  ELSIF v_connection.state='shadow' THEN v_outcome:='shadow_recorded';
  ELSIF v_connection.state NOT IN ('connected','degraded') OR v_connection.legacy_blocked_at IS NULL THEN v_outcome:='quarantined_scope';
  ELSIF v_data->>'identity_kind' IS DISTINCT FROM 'movement'
    OR v_data->>'identity_provenance' IS DISTINCT FROM 'fio_api_column22'
    OR v_data->>'source' IS DISTINCT FROM 'fio_api'
    OR v_connection.provider<>'FIO' OR nullif(v_identity,'') IS NULL THEN
    v_outcome:='quarantined_identity';
  ELSE
    SELECT t.* INTO v_tx FROM eshop.bank_transaction_identities i
      JOIN eshop.transactions t ON t.id=i.transaction_id
      WHERE i.instance_id=p_instance_id AND i.provider=v_connection.provider
        AND i.physical_account=v_connection.physical_account AND i.identity_kind='movement' AND i.identity_value=v_identity
      FOR UPDATE OF t;
    IF v_tx.id IS NULL AND v_identity ~ '^[0-9]{1,19}$' AND v_identity::numeric<=9223372036854775807 THEN
      v_source_id:=v_identity::bigint;
      SELECT array_agg(id ORDER BY id) INTO v_ids FROM eshop.transactions
        WHERE transaction_id=v_source_id AND ingest_source='fio_api'
          AND (bank_account_id=v_connection.bank_account_id OR bank_account_id IN
            (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=v_connection.id));
      IF cardinality(v_ids)>1 THEN v_outcome:='quarantined_conflict';
      ELSIF cardinality(v_ids)=1 THEN SELECT * INTO v_tx FROM eshop.transactions WHERE id=v_ids[1] FOR UPDATE;
      END IF;
    END IF;
    IF v_outcome IS NULL AND v_tx.id IS NOT NULL THEN
      IF NOT public.bank_sync_existing_facts_match(v_tx,v_data) THEN
        v_outcome:='quarantined_conflict';
      ELSE v_outcome:='already_ingested';
      END IF;
    END IF;
    IF v_outcome IS NULL THEN
      IF v_data->>'command_id' ~ '^[0-9]{1,19}$' AND (v_data->>'command_id')::numeric<=9223372036854775807 THEN
        v_command_id:=(v_data->>'command_id')::bigint;
      END IF;
      INSERT INTO eshop.transactions(transaction_id,bank_account_id,amount,currency,date,vs,ks,ss,
        command_id,payer_reference,message_for_recipient,counter_account,counter_account_name,bank_code,bank_name,
        user_identification,transaction_type,performed_by,comment,ingest_source)
        VALUES(v_source_id,v_connection.bank_account_id,v_amount,v_data->>'currency',v_date AT TIME ZONE 'UTC',
          nullif(v_data->>'raw_vs',''),nullif(v_data->>'ks',''),nullif(v_data->>'ss',''),v_command_id,
          v_data->>'payer_reference',v_data->>'message',v_data->>'counter_account',v_data->>'sender_name',
          v_data->>'bank_code',v_data->>'bank_name',v_data->>'user_identification',v_data->>'transaction_type',
          v_data->>'performed_by',v_data->>'comment','banksync_api') RETURNING * INTO v_tx;
      INSERT INTO eshop.bank_transaction_identities(instance_id,provider,physical_account,identity_kind,identity_value,transaction_id)
        VALUES(p_instance_id,v_connection.provider,v_connection.physical_account,'movement',v_identity,v_tx.id);
      IF v_amount<0 THEN v_outcome:='stored_outgoing';
      ELSIF v_amount=0 THEN v_outcome:='stored_zero';
      ELSE
        v_match:=public.match_bank_transaction(v_tx.id);
        v_outcome:=v_match->>'verdict';
        IF v_outcome NOT IN ('paired','unmatched','ambiguous','ineligible','already_paired') OR v_outcome IS NULL THEN
          RAISE EXCEPTION 'BANK_SYNC_MATCHER_INVALID_RESULT';
        END IF;
        IF v_outcome='already_paired' THEN v_outcome:='already_ingested'; END IF;
      END IF;
    END IF;
    IF v_outcome<>'quarantined_conflict' THEN
      INSERT INTO eshop.bank_transaction_identities(instance_id,provider,physical_account,identity_kind,identity_value,transaction_id)
        VALUES(p_instance_id,v_connection.provider,v_connection.physical_account,'movement',v_identity,v_tx.id)
        ON CONFLICT (instance_id,provider,physical_account,identity_kind,identity_value) DO UPDATE
          SET transaction_id=eshop.bank_transaction_identities.transaction_id
          WHERE eshop.bank_transaction_identities.transaction_id=EXCLUDED.transaction_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'BANK_SYNC_IDENTITY_CONFLICT'; END IF;
      INSERT INTO eshop.bank_transaction_identities(instance_id,provider,physical_account,identity_kind,identity_value,transaction_id)
        VALUES(p_instance_id,v_connection.provider,v_connection.physical_account,'remote_transaction',v_data->>'id',v_tx.id)
        ON CONFLICT (instance_id,provider,physical_account,identity_kind,identity_value) DO UPDATE
          SET transaction_id=eshop.bank_transaction_identities.transaction_id
          WHERE eshop.bank_transaction_identities.transaction_id=EXCLUDED.transaction_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'BANK_SYNC_IDENTITY_CONFLICT'; END IF;
    END IF;
  END IF;
  v_receipt:=jsonb_build_object('ok',true,'receipt_version',1,'delivery_id',v_delivery,'outcome',v_outcome);
  UPDATE eshop.bank_sync_inbox SET outcome=v_outcome,receipt=v_receipt,committed_at=now()
    WHERE instance_id=p_instance_id AND consumer_app_id=p_consumer_app_id AND delivery_id=v_delivery;
  UPDATE eshop.bank_sync_connections SET receiver_commit_at=now(),
    last_error=CASE WHEN v_outcome LIKE 'quarantined_%' THEN v_outcome ELSE last_error END WHERE id=v_connection.id;
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION public.ingest_bank_sync_transaction(p_instance_id text, p_consumer_app_id text, p_body_sha256 text, p_envelope jsonb) OWNER TO postgres;

--
-- Name: ingest_stripe_payment_internal(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ingest_stripe_payment_internal(p_attempt uuid, p_lease uuid, p_event jsonb, p_facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE a eshop.stripe_checkout_attempts; c eshop.stripe_connections; o eshop.orders; pi eshop.payment_info;
 existing eshop.stripe_event_inbox; movement eshop.stripe_payment_movements; d eshop.stripe_disputes;
 fact jsonb; totals record; before_projection jsonb; projection jsonb; v_receipt jsonb; transition jsonb;
 command uuid; input_hash text; mutation_claim jsonb; before_users uuid[]; cancelled bigint[]; payment_time timestamptz;
 card_received numeric; card_refunded numeric; financial_conflict boolean;
 changed boolean:=false; observed timestamptz:=(p_facts->>'observedAt')::timestamptz;
 no_session boolean:=coalesce(p_facts->'noSessionVerified'='true'::jsonb,false);
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE id=p_attempt;
 SELECT * INTO STRICT c FROM eshop.stripe_connections WHERE id=a.connection_id;
 IF p_event->>'id' IS NULL OR p_event->>'id' !~ '^evt_[A-Za-z0-9]+$'
  OR p_event->>'bodyHash' IS NULL OR p_event->>'bodyHash' !~ '^[a-f0-9]{64}$'
  OR p_event->>'accountId' IS DISTINCT FROM c.account_id OR (p_event->>'livemode')::boolean IS DISTINCT FROM a.livemode
  OR nullif(p_event->>'type','') IS NULL OR length(p_event->>'type')>100 THEN RAISE EXCEPTION 'STRIPE_EVENT_IDENTITY_INVALID'; END IF;
 SELECT * INTO existing FROM eshop.stripe_event_inbox WHERE connection_id=c.id AND event_id=p_event->>'id';
 IF FOUND THEN
  IF existing.body_sha256<>p_event->>'bodyHash' OR existing.receipt IS NULL THEN RAISE EXCEPTION 'STRIPE_EVENT_RECEIPT_INVALID'; END IF;
  RETURN existing.receipt;
 END IF;
 command:=(substr(encode(extensions.digest(c.id::text||':'||(p_event->>'id'),'sha256'),'hex'),1,32))::uuid;
 -- Event body identity is immutable; a replay may have newer provider reads.
 input_hash:=encode(extensions.digest(p_event::text,'sha256'),'hex');
 mutation_claim:=public.begin_anonymous_client_mutation_v1(command,'inventory.order.stripe_sync',
  (SELECT occasion FROM eshop.orders WHERE id=a.order_id),command,input_hash);
 IF mutation_claim->>'disposition'='replay' THEN RETURN mutation_claim->'response'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[a.order_id]);
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=a.order_id FOR UPDATE;
 SELECT * INTO STRICT pi FROM eshop.payment_info WHERE id=a.payment_info_id FOR UPDATE;
 SELECT * INTO STRICT a FROM eshop.stripe_checkout_attempts WHERE id=p_attempt FOR UPDATE;
 IF p_lease IS NULL OR a.lease_token IS NULL OR a.lease_expires_at IS NULL OR a.lease_token IS DISTINCT FROM p_lease OR a.lease_expires_at<=clock_timestamp()
  OR observed IS NULL OR observed>clock_timestamp()+interval '1 minute'
  OR observed<coalesce(a.last_synced_at,'-infinity') THEN RAISE EXCEPTION 'STRIPE_SYNC_LEASE_INVALID'; END IF;
 IF pi.id<>o.payment_info OR pi.payment_method<>'stripe' OR pi.stripe_connection_id<>c.id
  OR pi.amount*100<>a.amount_minor OR pi.currency_code<>a.currency
  OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=o.occasion AND organization=a.organization_id AND unit=a.unit_id)
  OR (NOT no_session AND (p_facts->>'sessionId' IS NULL OR p_facts->>'sessionId' !~ '^cs_[A-Za-z0-9_]+$'))
  OR (no_session AND (a.session_id IS NOT NULL OR a.session_lookup_found IS NOT NULL OR p_facts->>'sessionId' IS NOT NULL
   OR p_facts->>'paymentIntentId' IS NOT NULL OR p_facts->>'sessionStatus' IS DISTINCT FROM 'expired'
   OR a.reservation_expires_at>clock_timestamp()
   OR p_event->>'type' IS DISTINCT FROM 'festapp.reconcile' OR p_facts->'movements'<>'[]'::jsonb OR p_facts->'disputes'<>'[]'::jsonb))
  OR (a.session_id IS NOT NULL AND a.session_id<>p_facts->>'sessionId')
  OR (a.payment_intent_id IS NOT NULL AND a.payment_intent_id IS DISTINCT FROM p_facts->>'paymentIntentId')
  OR p_facts->>'sessionStatus' IS NULL OR p_facts->>'sessionStatus' NOT IN ('open','complete','expired')
  OR jsonb_typeof(p_facts->'movements') IS DISTINCT FROM 'array' OR jsonb_array_length(p_facts->'movements')>501
  OR jsonb_typeof(p_facts->'disputes') IS DISTINCT FROM 'array' OR jsonb_array_length(p_facts->'disputes')>100 THEN
  RAISE EXCEPTION 'STRIPE_FACT_IDENTITY_INVALID'; END IF;
 IF p_facts->>'refundCursor' IS NOT NULL AND (p_facts->>'refundCursor' !~ '^re_[A-Za-z0-9]+$'
  OR p_facts->>'refundCursor'=a.refund_cursor) THEN RAISE EXCEPTION 'STRIPE_REFUND_CURSOR_INVALID'; END IF;
 before_projection:=public.stripe_order_payment_projection_internal(o.id);
 SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO before_users FROM public.occasion_users ou WHERE ou.occasion=o.occasion;
 INSERT INTO eshop.stripe_event_inbox(connection_id,event_id,body_sha256,event_type,provider_created_at)
 VALUES(c.id,p_event->>'id',p_event->>'bodyHash',p_event->>'type',to_timestamp((p_event->>'created')::bigint));
 FOR fact IN SELECT value FROM jsonb_array_elements(p_facts->'movements') LOOP
  IF fact->>'kind' IS NULL OR fact->>'kind' NOT IN ('payment','refund') OR fact->>'currency' IS DISTINCT FROM a.currency
   OR (fact->>'amountMinor')::numeric IS NULL OR (fact->>'amountMinor')::numeric<>trunc((fact->>'amountMinor')::numeric)
   OR (fact->>'amountMinor')::bigint NOT BETWEEN 1 AND a.amount_minor
   OR (fact->>'kind'='payment' AND (fact->>'providerId' IS DISTINCT FROM p_facts->>'paymentIntentId' OR fact->>'providerId' !~ '^pi_[A-Za-z0-9]+$' OR (fact->>'amountMinor')::bigint<>a.amount_minor))
   OR (fact->>'kind'='refund' AND (fact->>'providerId' IS NULL OR fact->>'providerId' !~ '^re_[A-Za-z0-9]+$'))
   OR (fact->>'occurredAt')::bigint IS NULL OR (fact->>'occurredAt')::bigint<0 THEN RAISE EXCEPTION 'STRIPE_MOVEMENT_INVALID'; END IF;
  SELECT * INTO movement FROM eshop.stripe_payment_movements WHERE connection_id=c.id AND provider_id=fact->>'providerId' AND kind=fact->>'kind';
  IF FOUND THEN
   IF movement.attempt_id<>a.id OR movement.amount_minor<>(fact->>'amountMinor')::bigint OR movement.currency<>a.currency
    OR movement.occurred_at<>to_timestamp((fact->>'occurredAt')::bigint) THEN RAISE EXCEPTION 'STRIPE_MOVEMENT_CHANGED'; END IF;
  ELSE
   INSERT INTO eshop.stripe_payment_movements(connection_id,provider_id,attempt_id,kind,amount_minor,currency,occurred_at)
   VALUES(c.id,fact->>'providerId',a.id,fact->>'kind',(fact->>'amountMinor')::bigint,a.currency,to_timestamp((fact->>'occurredAt')::bigint));
   changed:=true;
  END IF;
 END LOOP;
 FOR fact IN SELECT value FROM jsonb_array_elements(p_facts->'disputes') LOOP
  IF fact->>'providerId' IS NULL OR fact->>'providerId' !~ '^(dp|du)_[A-Za-z0-9]+$'
   OR (fact->>'amountMinor') IS NULL OR (fact->>'amountMinor')::numeric<>trunc((fact->>'amountMinor')::numeric) OR (fact->>'amountMinor')::bigint NOT BETWEEN 1 AND a.amount_minor OR fact->>'currency' IS DISTINCT FROM a.currency
   OR fact->>'status' IS NULL OR fact->>'status' NOT IN ('warning_needs_response','warning_under_review','warning_closed','needs_response','under_review','won','lost') THEN
   RAISE EXCEPTION 'STRIPE_DISPUTE_INVALID'; END IF;
  SELECT * INTO d FROM eshop.stripe_disputes WHERE connection_id=c.id AND provider_id=fact->>'providerId';
  IF FOUND AND (d.attempt_id<>a.id OR d.amount_minor<>(fact->>'amountMinor')::bigint) THEN RAISE EXCEPTION 'STRIPE_DISPUTE_CHANGED'; END IF;
  IF d.status IS DISTINCT FROM fact->>'status' THEN changed:=true; END IF;
  INSERT INTO eshop.stripe_disputes(connection_id,provider_id,attempt_id,amount_minor,status,observed_at)
  VALUES(c.id,fact->>'providerId',a.id,(fact->>'amountMinor')::bigint,fact->>'status',observed)
  ON CONFLICT(connection_id,provider_id) DO UPDATE SET status=excluded.status,observed_at=excluded.observed_at;
 END LOOP;
 UPDATE eshop.stripe_checkout_attempts SET session_id=p_facts->>'sessionId',payment_intent_id=p_facts->>'paymentIntentId',refund_cursor=p_facts->>'refundCursor',
  session_lookup_cursor=NULL,session_lookup_found=NULL WHERE id=a.id;
 BEGIN
  transition:=public.apply_provider_payment_effects_internal('stripe',a.id,p_event->>'id',before_projection,p_facts->>'sessionStatus'='expired');
 EXCEPTION WHEN raise_exception THEN
  -- Retained service RPC diagnostic; domain behavior still has one owner.
  IF SQLERRM='PAYMENT_PAID_TRANSITION_FAILED' THEN RAISE EXCEPTION 'STRIPE_PAID_TRANSITION_FAILED'; END IF;
  RAISE;
 END;
 projection:=transition->'payment';changed:=changed OR (transition->>'changed')::boolean;
 UPDATE eshop.stripe_checkout_attempts SET last_synced_at=observed,lease_token=NULL,lease_expires_at=NULL,reconcile_failures=0,
  next_reconcile_at=clock_timestamp()+CASE WHEN refund_cursor IS NOT NULL THEN interval '10 seconds' WHEN state IN ('paid','action_required') THEN interval '1 day' ELSE interval '2 minutes' END WHERE id=a.id;
 v_receipt:=public.complete_profile_inventory_membership_mutation_v1(command,o.occasion,'inventory.order.stripe_sync',
  CASE WHEN changed THEN jsonb_build_array(jsonb_build_object('entityType','order','entityId',o.id,'operation','update',
   'safeLabel','Card payment update','changedFields',jsonb_build_array('payment','state','tickets','admission','allocations'))) ELSE '[]'::jsonb END,
  before_users,jsonb_build_object('committed',true,'payment',projection),'service');
 UPDATE eshop.stripe_event_inbox SET committed_at=clock_timestamp(),receipt=v_receipt WHERE connection_id=c.id AND event_id=p_event->>'id';
 PERFORM public.notification_center_order_state_internal(o.id);
 PERFORM public.notification_center_order_capacity_internal(o.id);
 RETURN v_receipt;
END $_$;


ALTER FUNCTION public.ingest_stripe_payment_internal(p_attempt uuid, p_lease uuid, p_event jsonb, p_facts jsonb) OWNER TO postgres;

--
-- Name: initialize_notification_center_internal(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_notification_center_internal(p_organization bigint, p_timezone text DEFAULT 'Europe/Prague'::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE baseline_at timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('notification-center-organization:'||p_organization,0));
 IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_timezone) THEN RAISE EXCEPTION 'notification_timezone_invalid'; END IF;
 IF EXISTS(SELECT 1 FROM public.notification_center_organizations WHERE organization=p_organization) THEN RETURN; END IF;
 baseline_at:=clock_timestamp();
 INSERT INTO public.notification_center_organizations(organization,timezone) VALUES(p_organization,p_timezone);
 -- Baseline once: existing incidents and capacity are not historical alerts.
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT p_organization,'email:'||message_id,jsonb_build_object('reason',public.email_reporting_state(m),'dueAt',m.target_time,'seen',
    CASE WHEN m.workflow_state IN ('pending','preparing','sending','retry_wait','unknown') AND m.target_time<=clock_timestamp()-interval '30 minutes' THEN '["delayed"]'::jsonb WHEN public.email_reporting_state(m) IN ('complaint','bounce','reject','rendering_failure','dead','suppressed')
    THEN jsonb_build_array(CASE WHEN public.email_reporting_state(m) IN ('unknown','retry_wait','delay') THEN 'delayed' ELSE public.email_reporting_state(m) END) ELSE '[]'::jsonb END)
   FROM public.email_messages m WHERE organization=p_organization
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state||jsonb_build_object('seen',coalesce(notification_center_source_state.state->'seen','[]')||(excluded.state->'seen'),'eventId',notification_center_source_state.state->>'eventId','dueAt',coalesce(notification_center_source_state.state->'dueAt',excluded.state->'dueAt')),observed_at=clock_timestamp();
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT DISTINCT p_organization,'bank:'||c.id,jsonb_build_object('problem',c.last_error IS NOT NULL OR
    coalesce(c.bank_pull_at,c.created_at)<clock_timestamp()-interval '30 minutes','reason',CASE WHEN c.last_error IS NOT NULL THEN 'existing_problem' END)
   FROM eshop.bank_sync_connections c JOIN eshop.unit_bank_accounts uba ON uba.bank_account=c.bank_account_id OR uba.bank_account IN
    (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=c.id)
   JOIN public.units u ON u.id=uba.unit WHERE u.organization=p_organization
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state||jsonb_build_object('eventId',notification_center_source_state.state->>'eventId'),observed_at=clock_timestamp();
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT p_organization,'schedule-event:'||e.id,jsonb_build_object('eventId',e.id,'title',e.title,
    'limit',CASE WHEN e.split_for_men_women THEN 2*(e.max_participants/2) ELSE e.max_participants END,
    'full',coalesce(e.max_participants>0 AND CASE WHEN e.split_for_men_women THEN
      count(eu."user") FILTER(WHERE ui.sex='male')>=e.max_participants/2 AND count(eu."user") FILTER(WHERE ui.sex<>'male')>=e.max_participants/2
      ELSE count(eu."user")>=e.max_participants END,false))
   FROM public.events e JOIN public.occasions o ON o.id=e.occasion
   LEFT JOIN public.event_users eu ON eu.event=e.id LEFT JOIN public.user_info ui ON ui.id=eu."user"
   WHERE o.organization=p_organization GROUP BY e.id
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state,observed_at=clock_timestamp();
  -- Seed exact authoritative capacities before enabling publication.
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT p_organization,'form:'||f.id,public.get_form_capacity_snapshot_internal(f.id)||jsonb_build_object('high',
    coalesce((f.participant_capacity-(public.get_form_capacity_snapshot_internal(f.id)->>'remainingPublic')::numeric)/nullif(f.participant_capacity,0)>=0.9,false))
   FROM public.forms f JOIN public.occasions oc ON oc.id=f.occasion WHERE oc.organization=p_organization
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state,observed_at=clock_timestamp();
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT p_organization,'product:'||p.id,jsonb_build_object('limit',p.maximum,'remainingPublic',greatest(p.maximum-count(x.id),0),
     'high',coalesce(count(x.id)::numeric/nullif(p.maximum,0)>=0.9,false)) FROM eshop.products p JOIN public.occasions oc ON oc.id=p.occasion
   LEFT JOIN eshop.order_product_ticket x ON x.product=p.id WHERE oc.organization=p_organization GROUP BY p.id
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state,observed_at=clock_timestamp();
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT p_organization,'inventory:'||ctx.id,jsonb_build_object('limit',least(count(s.id),coalesce(ip.sellable_capacity,count(s.id))),
    'remainingPublic',greatest(least(count(s.id),coalesce(ip.sellable_capacity,count(s.id)))-count(s.id) FILTER(WHERE s.order_product_ticket IS NOT NULL),0),
    'high',coalesce(count(s.id) FILTER(WHERE s.order_product_ticket IS NOT NULL)::numeric/nullif(least(count(s.id),coalesce(ip.sellable_capacity,count(s.id))),0)>=0.9,false))
   FROM public.inventory_contexts ctx JOIN public.inventory_pools ip ON ip.id=ctx.inventory_pool JOIN public.occasions oc ON oc.id=ip.occasion
   LEFT JOIN eshop.spots s ON s.inventory_context=ctx.id WHERE oc.organization=p_organization GROUP BY ctx.id,ip.id
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state,observed_at=clock_timestamp();
  INSERT INTO public.notification_center_source_state(organization,source_key,state)
   SELECT p_organization,'blueprint:'||bp.id,jsonb_build_object('limit',count(s.id),
    'remainingPublic',count(s.id) FILTER(WHERE s.order_product_ticket IS NULL),'high',
    coalesce(count(s.id) FILTER(WHERE s.order_product_ticket IS NOT NULL)::numeric/nullif(count(s.id),0)>=0.9,false))
   FROM eshop.blueprints bp LEFT JOIN eshop.blueprint_seat_bindings sb ON sb.blueprint=bp.id AND NOT sb.blocked
   LEFT JOIN eshop.spots s ON s.id=sb.spot AND s.blueprint=bp.id AND s.occasion=bp.occasion
   WHERE bp.organization=p_organization GROUP BY bp.id
   ON CONFLICT(organization,source_key) DO UPDATE SET state=excluded.state,observed_at=clock_timestamp();
 PERFORM public.notification_center_form_availability_internal(f.id,baseline_at,NULL,true) FROM public.forms f JOIN public.occasions oc ON oc.id=f.occasion WHERE oc.organization=p_organization;
 UPDATE public.notification_center_organizations SET collection_started_at=baseline_at WHERE organization=p_organization;
END $$;


ALTER FUNCTION public.initialize_notification_center_internal(p_organization bigint, p_timezone text) OWNER TO postgres;

--
-- Name: initialize_occasion_setup_draft_defaults(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_occasion_setup_draft_defaults(p_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE d public.occasion_setup_drafts; configuration jsonb; policy jsonb;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF d.data ? 'finalizedOccasion' OR
     (jsonb_typeof(d.data#>'{defaultConfiguration,forms}')='array' AND
      jsonb_array_length(d.data#>'{defaultConfiguration,forms}')>0) THEN RETURN jsonb_set(to_jsonb(d),'{data}',public.normalize_setup_payments_internal(d.data)); END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = 'PT409';
  END IF;
  policy:=public.abuse_effective_rules_v1('occasion.draft',d.unit,d.organization);
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,0,false,true,policy);
  configuration := public.build_occasion_setup_configuration(d.unit,p_id);
  UPDATE public.occasion_setup_drafts SET data =
    public.normalize_setup_payments_internal(jsonb_build_object('defaultConfiguration',configuration,
      'formDraft',configuration->'forms'->0,'formDefaultsFollowEvent',true,
        'paymentMethod',(SELECT CASE WHEN public.payment_method_registered_internal(data->>'DEFAULT_FORM_PAYMENT_METHOD') AND data->>'DEFAULT_FORM_PAYMENT_METHOD'<>'bank' THEN data->>'DEFAULT_FORM_PAYMENT_METHOD' END FROM public.organizations WHERE id=d.organization),
        'paymentChoicesEnabled',EXISTS(SELECT 1 FROM jsonb_each(public.provider_unit_features_internal(d.unit)) x WHERE x.value='true'::jsonb))
    || (d.data-'defaultConfiguration')), revision = revision+1, updated_at=now()
    WHERE id=p_id RETURNING * INTO d;
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,octet_length(d.data::text),false,false,policy);
  RETURN jsonb_set(to_jsonb(d),'{data}',public.normalize_setup_payments_internal(d.data));
END $$;


ALTER FUNCTION public.initialize_occasion_setup_draft_defaults(p_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: initialize_registration_unit_v1(uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_registration_unit_v1(p_user uuid, p_organization bigint, p_raw_email text, p_title text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_unit bigint;
BEGIN
  PERFORM public.admit_unit_creation_v1(p_user,p_organization);
  INSERT INTO public.units(title,organization,data) VALUES(p_title,p_organization,jsonb_build_object('reply_to',lower(btrim(p_raw_email)),'timezone','Europe/Prague')) RETURNING id INTO v_unit;
  INSERT INTO public.unit_users(unit,"user",is_manager,is_editor,is_editor_view) VALUES(v_unit,p_user,true,true,true);
  RETURN v_unit;
END $$;


ALTER FUNCTION public.initialize_registration_unit_v1(p_user uuid, p_organization bigint, p_raw_email text, p_title text) OWNER TO postgres;

--
-- Name: insert_form_for_occasion_internal_v1(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_form_for_occasion_internal_v1(p_occasion_id bigint, p_link text, p_title text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    new_form_id BIGINT;
    new_form JSONB;
    new_product_type_id BIGINT;
    now TIMESTAMPTZ := NOW();
    payment_default text;
    initial_data jsonb := '{"is_reminder_enabled": true,"design":{"presale_header":"event_and_date"}}'::jsonb;
BEGIN
    SELECT org.data->>'DEFAULT_FORM_PAYMENT_METHOD' INTO payment_default
    FROM public.occasions o JOIN public.organizations org ON org.id=o.organization
    WHERE o.id=p_occasion_id;
    IF payment_default='cash' THEN
      initial_data := initial_data || '{"payments":{"bankEnabled":false,"cashEnabled":true,"providerConnections":{}},"payment_deadline":{"mode":"none"}}'::jsonb;
    ELSIF public.payment_method_is_online_internal(payment_default) THEN
      -- A closed draft can await Connect without inventing a recipient or bank.
      initial_data := initial_data || '{"payments":{"bankEnabled":false}}'::jsonb;
    END IF;
    PERFORM public.notification_center_initialized_internal((SELECT organization FROM public.occasions WHERE id=p_occasion_id));
    -- Create the new form
    INSERT INTO public.forms(
        title,
        is_open,
        link,
        occasion,
        created_at,
        updated_at,
        deadline_duration_seconds,
        data
    )
    VALUES (
        p_title,
        false,
        NULL,
        p_occasion_id,
        now,
        now,
        NULL, -- New forms inherit the occasion policy; legacy stored durations stay custom.
        initial_data
    )
    RETURNING to_jsonb(public.forms.*) INTO new_form;

    new_form_id := (new_form->>'id')::BIGINT;

    UPDATE public.forms SET link=public.reserve_public_link_internal('form',new_form_id,p_link,true) WHERE id=new_form_id;
    SELECT to_jsonb(f) INTO new_form FROM public.forms f WHERE id=new_form_id;

    -- Create default 'email' and 'ticket' fields
    INSERT INTO public.form_fields(title, type, is_required, form, "order")
    VALUES ('', 'email', true, new_form_id, 0),
           ('', 'ticket', true, new_form_id, 1);

    -- Ensure 'spot' product type exists for the occasion
    IF NOT EXISTS (SELECT 1 FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot') THEN
        INSERT INTO eshop.product_types(title, type, occasion)
        VALUES ('Spot', 'spot', p_occasion_id)
        RETURNING id INTO new_product_type_id;
    ELSE
        SELECT id INTO new_product_type_id FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot' LIMIT 1;
    END IF;

    -- Ensure the 'spot' product type has at least one product
    IF NOT EXISTS (SELECT 1 FROM eshop.products WHERE occasion = p_occasion_id AND product_type = new_product_type_id) THEN
        INSERT INTO eshop.products(title, price, product_type, occasion, currency_code, "order")
        VALUES ('Variant 1', 100, new_product_type_id, p_occasion_id, 'CZK', 0);
    END IF;

    -- Create the 'product_type' form field linked to 'spot'
    INSERT INTO public.form_fields(title, type, is_required, form, "order", product_type, is_ticket_field)
    VALUES ('Spot', 'product_type', false, new_form_id, 2, new_product_type_id, true);

    -- Return the raw data of the newly created form
    PERFORM public.notification_center_form_created_internal(new_form_id);
    RETURN new_form;
END;
$$;


ALTER FUNCTION public.insert_form_for_occasion_internal_v1(p_occasion_id bigint, p_link text, p_title text) OWNER TO postgres;

--
-- Name: insert_manual_transaction(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_manual_transaction(input_data jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE o eshop.orders; u bigint; begin_result jsonb; transaction_id bigint; users uuid[]; result jsonb;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE payment_info=(input_data->>'paymentInfoId')::bigint;
 SELECT unit INTO u FROM public.occasions WHERE id=o.occasion;
 PERFORM public.check_is_manager_on_unit(u);
 IF u IS DISTINCT FROM (input_data->>'unitId')::bigint OR trim(o.currency_code) IS DISTINCT FROM input_data->>'currency' THEN
  RAISE EXCEPTION 'CASH_ORDER_SCOPE_MISMATCH'; END IF;
 IF jsonb_typeof(input_data->'amount') IS DISTINCT FROM 'string' OR input_data->>'amount' !~ '^-?[0-9]{1,8}(\.[0-9]{1,2})?$' THEN
  RAISE EXCEPTION 'CASH_AMOUNT_INVALID'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[o.id]);
 begin_result:=public.begin_client_mutation_v1(p_command_id,'orders.cash.record',o.occasion,auth.uid(),
  encode(extensions.digest(input_data::text,'sha256'),'hex'));
 IF begin_result->>'disposition'='replay' THEN RETURN jsonb_set(begin_result->'response','{mutation,replayed}','true'); END IF;
 transaction_id:=public.insert_manual_transaction_internal_v1((input_data->>'amount')::numeric,input_data->>'currency',u,NULL,
  (input_data->>'receivedAt')::timestamptz,input_data->>'note',o.payment_info);
 SELECT coalesce(array_agg(DISTINCT "user"),'{}') INTO users FROM public.occasion_users WHERE occasion=o.occasion;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,o.occasion,'orders.cash.record',
  jsonb_build_array(jsonb_build_object('entityType','order','entityId',o.id,'operation','update','changedFields',jsonb_build_array('payment'))),users,
  jsonb_build_object('orderId',o.id,'transactionId',transaction_id,'payment',public.customer_order_payment_internal(o.id)));
END $_$;


ALTER FUNCTION public.insert_manual_transaction(input_data jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: insert_manual_transaction(double precision, text, integer, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_manual_transaction(p_amount double precision, p_currency text, p_unit_id integer, p_variable_symbol text, p_date text, p_note text DEFAULT NULL::text, p_payment_info_id integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    PERFORM public.check_is_manager_on_unit(p_unit_id);
    PERFORM public.insert_manual_transaction_internal_v1(p_amount::numeric,p_currency,p_unit_id::bigint,
      p_variable_symbol,p_date::timestamptz,p_note,p_payment_info_id::bigint);
END;
$$;


ALTER FUNCTION public.insert_manual_transaction(p_amount double precision, p_currency text, p_unit_id integer, p_variable_symbol text, p_date text, p_note text, p_payment_info_id integer) OWNER TO postgres;

--
-- Name: insert_manual_transaction_internal_v1(numeric, text, bigint, text, timestamp with time zone, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_manual_transaction_internal_v1(p_amount numeric, p_currency text, p_unit_id bigint, p_variable_symbol text, p_date timestamp with time zone, p_note text DEFAULT NULL::text, p_payment_info_id bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_account_id bigint;
    v_date timestamp with time zone;
    v_new_transaction_id bigint;
    v_payment_info_id bigint;
    v_candidate_ids bigint[];
    v_order eshop.orders;
    v_unit bigint;
BEGIN
    -- Check permissions (must be Unit Manager)
    PERFORM public.check_is_manager_on_unit(p_unit_id);
    IF p_amount IS NULL OR p_amount=0 OR p_amount::text IN ('NaN','Infinity','-Infinity') OR p_amount*100<>trunc(p_amount*100)
       OR p_currency IS NULL OR p_currency NOT IN ('CZK','EUR','PLN','USD','GBP') OR p_date IS NULL THEN
      RAISE EXCEPTION 'CASH_AMOUNT_INVALID'; END IF;
    IF p_payment_info_id IS NOT NULL THEN
      SELECT * INTO STRICT v_order FROM eshop.orders WHERE payment_info=p_payment_info_id;
      PERFORM public.lock_order_capacity_scope_internal(ARRAY[v_order.id]);
      SELECT unit INTO v_unit FROM public.occasions WHERE id=v_order.occasion;
      IF v_unit IS DISTINCT FROM p_unit_id OR trim(v_order.currency_code) IS DISTINCT FROM p_currency THEN
        RAISE EXCEPTION 'CASH_ORDER_SCOPE_MISMATCH'; END IF;
      PERFORM public.check_order_is_mutable(v_order.id);
    END IF;
    v_date := p_date;
    PERFORM pg_advisory_xact_lock(hashtextextended('cash-account:'||p_unit_id||':'||p_currency,79103));

    -- 1. Find or Create CASH account
    SELECT ba.id INTO v_account_id
    FROM eshop.bank_accounts ba
    JOIN eshop.unit_bank_accounts uba ON ba.id = uba.bank_account
    WHERE uba.unit = p_unit_id
      AND ba.type = 'CASH'
      AND p_currency = ANY(ba.supported_currencies)
    ORDER BY ba.id LIMIT 1;

    IF v_account_id IS NULL THEN
        INSERT INTO eshop.bank_accounts (
            title, type, supported_currencies, account_number, account_number_human_readable
        ) VALUES (
            'Cash Account (' || p_currency || ')', 'CASH', ARRAY[p_currency], '', ''
        )
        RETURNING id INTO v_account_id;

        INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
        VALUES (p_unit_id, v_account_id, 0);
    END IF;

    -- 2. Insert Transaction
    INSERT INTO eshop.transactions (
        bank_account_id,
        amount,
        currency,
        date,
        vs,
        message_for_recipient,
        transaction_type,
        created_by,
        ingest_source
    ) VALUES (
        v_account_id,
        p_amount,
        p_currency,
        v_date,
        p_variable_symbol,
        p_note,
        'manual',
        auth.uid(),
        'manual'
    )
    RETURNING id INTO v_new_transaction_id;

    -- 3. Link to Payment Info & Update Order State
    IF p_payment_info_id IS NOT NULL THEN
         v_payment_info_id := p_payment_info_id;
    ELSIF p_variable_symbol IS NOT NULL AND p_variable_symbol ~ '^[0-9]{1,10}$' THEN
        SELECT array_agg(pi.id ORDER BY pi.id) INTO v_candidate_ids
        FROM eshop.payment_info pi
        JOIN eshop.orders o ON o.payment_info = pi.id
        JOIN public.occasions oc ON oc.id = o.occasion
        WHERE pi.variable_symbol = p_variable_symbol::bigint
          AND upper(trim(pi.currency_code::text)) = upper(trim(p_currency))
          AND oc.unit = p_unit_id;
        IF cardinality(v_candidate_ids) = 1 THEN
          v_payment_info_id := v_candidate_ids[1];
        END IF;
    END IF;

    IF v_payment_info_id IS NOT NULL THEN
        PERFORM public.apply_transaction_pairing(
          v_new_transaction_id, v_payment_info_id, 'manual_insert', 'user'
        );
    END IF;
    RETURN v_new_transaction_id;
END;
$_$;


ALTER FUNCTION public.insert_manual_transaction_internal_v1(p_amount numeric, p_currency text, p_unit_id bigint, p_variable_symbol text, p_date timestamp with time zone, p_note text, p_payment_info_id bigint) OWNER TO postgres;

--
-- Name: inspect_account_deletion_token(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_account_deletion_token(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  IF p_token_hash !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  SELECT * INTO v_request FROM public.account_deletion_requests
  WHERE token_hash = p_token_hash OR used_token_hash = p_token_hash
  LIMIT 1;
  IF v_request.id IS NULL THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.status = 'completed' THEN RETURN jsonb_build_object('status', 'already_completed'); END IF;
  IF v_request.status <> 'email_sent' THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.expires_at <= clock_timestamp() THEN RETURN jsonb_build_object('status', 'expired'); END IF;
  RETURN jsonb_build_object('status', 'valid', 'expiresAt', v_request.expires_at);
END;
$_$;


ALTER FUNCTION public.inspect_account_deletion_token(p_token_hash text) OWNER TO postgres;

--
-- Name: inspect_wix_billing_delivery(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_wix_billing_delivery(p_app uuid, p_receipt text, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE row public.wix_billing_deliveries;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO STRICT row FROM public.wix_billing_deliveries WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind FOR UPDATE;
 IF row.state='sending' AND row.lease_until<=clock_timestamp() THEN
  UPDATE public.wix_billing_deliveries SET state='unknown',lease_until=NULL WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind RETURNING * INTO row;
  UPDATE public.wix_billing_attempts SET outcome='unknown',finished_at=clock_timestamp(),evidence='{"reason":"expired-attempt"}' WHERE id=row.attempt_id;
 END IF;
 RETURN to_jsonb(row)||jsonb_build_object('attempts',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY started_at),'[]') FROM public.wix_billing_attempts a WHERE a.app_id=p_app AND a.receipt_id=p_receipt AND a.kind=p_kind));
END $$;


ALTER FUNCTION public.inspect_wix_billing_delivery(p_app uuid, p_receipt text, p_kind text) OWNER TO postgres;

--
-- Name: internal_storno_tickets_221(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.internal_storno_tickets_221(ticket_ids_to_storno bigint[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    opt_ids BIGINT[];
    nc_changed record;
    nc_changes jsonb;
    nc_products bigint[];
    nc_event uuid;
    nc_contexts bigint[];
    nc_blueprints bigint[];
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(ticket_ids_to_storno)));
    PERFORM public.check_blueprint_selection_units_internal(ARRAY(SELECT s.id FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE opt.ticket=ANY(ticket_ids_to_storno)));
    IF ticket_ids_to_storno IS NULL OR array_length(ticket_ids_to_storno, 1) = 0 THEN
        RETURN; -- Nothing to do
    END IF;

    PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(ticket_ids_to_storno)));
    PERFORM public.lock_ticket_order_products_internal(o.id) FROM eshop.orders o WHERE o.id IN
      (SELECT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(ticket_ids_to_storno)) ORDER BY o.id;
    UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id IN
      (SELECT o.form FROM eshop.order_product_ticket x JOIN eshop.orders o ON o.id=x."order" WHERE x.ticket=ANY(ticket_ids_to_storno));
    UPDATE eshop.waitlist_offer_slots SET outcome='cancelled',updated_at=clock_timestamp()
      WHERE ticket_id=ANY(ticket_ids_to_storno) AND outcome='pending';
    SELECT array_agg(DISTINCT s.inventory_context),array_agg(DISTINCT s.blueprint) INTO nc_contexts,nc_blueprints FROM eshop.spots s JOIN eshop.order_product_ticket x ON x.id=s.order_product_ticket WHERE x.ticket=ANY(ticket_ids_to_storno);
    SELECT array_agg(DISTINCT product) INTO nc_products FROM eshop.order_product_ticket WHERE ticket=ANY(ticket_ids_to_storno) AND product IS NOT NULL;
    SELECT coalesce(jsonb_agg(to_jsonb(changes)),'[]') INTO nc_changes FROM (
      SELECT x."order" order_id,array_agg(DISTINCT t.id ORDER BY t.id) ticket_ids FROM eshop.order_product_ticket x
      JOIN eshop.tickets t ON t.id=x.ticket WHERE t.id=ANY(ticket_ids_to_storno) AND t.state IS DISTINCT FROM 'storno' GROUP BY x."order"
    ) changes;
    -- 1. Get all related order_product_ticket IDs
    SELECT ARRAY_AGG(opt.id) INTO opt_ids
    FROM eshop.order_product_ticket opt
    WHERE opt.ticket = ANY(ticket_ids_to_storno);

    -- 2. (NEW) Delete any occasion_users linked to these tickets.
    -- We delete directly because the parent function already
    -- verified the user has 'editor' permissions.
    PERFORM public.notification_center_prepared_invalidate_user(m."user",m.occasion) FROM public.occasion_users m WHERE m.ticket=ANY(ticket_ids_to_storno);
    DELETE FROM public.occasion_users
    WHERE ticket = ANY(ticket_ids_to_storno);

    -- 3. Update the tickets themselves to 'storno'
    UPDATE eshop.tickets
    SET state = 'storno', updated_at = NOW()
    WHERE id = ANY(ticket_ids_to_storno);

    -- 4. Nullify the relevant spots
    IF opt_ids IS NOT NULL THEN
        UPDATE eshop.spots
        SET order_product_ticket = NULL,
            secret = NULL,
            secret_expiration_time = NULL,
            updated_at = NOW(),
            resource = NULL,
            state = NULL
        WHERE order_product_ticket = ANY(opt_ids);
    END IF;

    -- 5. Nullify the product link on the order_product_ticket records
    UPDATE eshop.order_product_ticket
    SET product = NULL
    WHERE ticket = ANY(ticket_ids_to_storno);

    FOR nc_changed IN SELECT * FROM jsonb_to_recordset(nc_changes) AS r(order_id bigint,ticket_ids bigint[]) LOOP
      PERFORM public.notification_center_order_internal(nc_changed.order_id,'order_cancelled',encode(extensions.digest(array_to_string(nc_changed.ticket_ids,','),'sha256'),'hex'),auth.uid(),
        jsonb_build_object('count',cardinality(nc_changed.ticket_ids)));
      SELECT id INTO nc_event FROM public.notification_center_events WHERE kind='order_cancelled' AND data->>'orderId'=nc_changed.order_id::text
        AND source_key='order_cancelled:'||nc_changed.order_id||':'||encode(extensions.digest(array_to_string(nc_changed.ticket_ids,','),'sha256'),'hex');
      PERFORM public.notification_center_form_capacity_internal((SELECT form FROM eshop.orders WHERE id=nc_changed.order_id),auth.uid(),nc_event);
    END LOOP;
    PERFORM public.notification_center_product_capacity_internal(p) FROM unnest(nc_products) p;
    PERFORM public.notification_center_inventory_capacity_internal(c) FROM unnest(nc_contexts) c WHERE c IS NOT NULL;
    PERFORM public.notification_center_blueprint_capacity_internal(b) FROM unnest(nc_blueprints) b WHERE b IS NOT NULL;
END;
$$;


ALTER FUNCTION public.internal_storno_tickets_221(ticket_ids_to_storno bigint[]) OWNER TO postgres;

