--
-- Name: is_product_dynamically_available(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_product_dynamically_available(p_product_id bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    context_record RECORD;
    occupied_spots BIGINT;
    total_spots BIGINT;
BEGIN
    -- If a product is not linked to any inventory contexts,
    -- it is considered available by default.
    IF NOT EXISTS (SELECT 1 FROM eshop.product_inventory_contexts WHERE product = p_product_id) THEN
        RETURN TRUE;
    END IF;

    -- Iterate through each inventory context required by the product.
    FOR context_record IN
        SELECT
            pic.inventory_context,
            pic.quantity,
            ip.sellable_capacity
        FROM eshop.product_inventory_contexts pic
        JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
        JOIN public.inventory_pools ip ON ic.inventory_pool = ip.id
        WHERE pic.product = p_product_id
    LOOP
        -- Calculate the total number of physical spots available for the context.
        SELECT count(*)
        INTO total_spots
        FROM eshop.spots
        WHERE inventory_context = context_record.inventory_context;

        -- Calculate the number of spots that are currently occupied.
        -- A spot is considered occupied if it's assigned to an order (opt is not null)
        -- or if it has been temporarily reserved via a secret.
        SELECT count(*)
        INTO occupied_spots
        FROM eshop.spots
        WHERE inventory_context = context_record.inventory_context
          AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time > now()));

        -- Check 1: Ensure purchasing does not exceed the total physical spots.
        IF (occupied_spots + context_record.quantity) > total_spots THEN
            RETURN FALSE;
        END IF;

        -- Check 2: If a commercial sellable capacity is set on the pool,
        -- ensure purchasing does not exceed this limit.
        IF context_record.sellable_capacity IS NOT NULL AND (occupied_spots + context_record.quantity) > context_record.sellable_capacity THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    -- If all checks for all contexts pass, the product is available for purchase.
    RETURN TRUE;
END;
$$;


ALTER FUNCTION public.is_product_dynamically_available(p_product_id bigint) OWNER TO postgres;

--
-- Name: is_service_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_service_role() RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_role text := NULLIF(current_setting('request.jwt.claim.role', true), '');
  v_claims text;
BEGIN
  IF v_role IS NULL THEN
    v_claims := NULLIF(current_setting('request.jwt.claims', true), '');
    IF v_claims IS NOT NULL THEN
      BEGIN
        v_role := v_claims::jsonb->>'role';
      EXCEPTION WHEN OTHERS THEN
        RETURN false;
      END;
    END IF;
  END IF;
  IF v_role IS NOT NULL THEN
    RETURN v_role = 'service_role';
  END IF;
  RETURN session_user = 'postgres';
END;
$$;


ALTER FUNCTION public.is_service_role() OWNER TO postgres;

--
-- Name: is_valid_creditor_reference(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_valid_creditor_reference(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_value text := public.normalize_creditor_reference(p_value);
  v_rearranged text;
  v_expanded text := '';
  v_char text;
  v_remainder integer := 0;
  v_index integer;
BEGIN
  IF v_value !~ '^RF[0-9]{2}[A-Z0-9]{1,21}$' THEN
    RETURN false;
  END IF;

  v_rearranged := substring(v_value FROM 5) || substring(v_value FROM 1 FOR 4);
  FOR v_index IN 1..length(v_rearranged) LOOP
    v_char := substring(v_rearranged FROM v_index FOR 1);
    IF v_char ~ '[0-9]' THEN
      v_expanded := v_expanded || v_char;
    ELSE
      v_expanded := v_expanded || (ascii(v_char) - 55)::text;
    END IF;
  END LOOP;

  FOR v_index IN 1..length(v_expanded) LOOP
    v_remainder := (v_remainder * 10 + substring(v_expanded FROM v_index FOR 1)::integer) % 97;
  END LOOP;
  RETURN v_remainder = 1;
END;
$_$;


ALTER FUNCTION public.is_valid_creditor_reference(p_value text) OWNER TO postgres;

--
-- Name: is_valid_iban(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_valid_iban(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_iban text := upper(regexp_replace(p_value, '[[:space:]]', '', 'g'));
  v_rearranged text;
  v_char text;
  v_expanded text;
  v_remainder integer := 0;
  v_index integer;
  v_digit_index integer;
BEGIN
  IF v_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$' THEN RETURN false; END IF;
  v_rearranged := substring(v_iban FROM 5) || substring(v_iban FROM 1 FOR 4);
  FOR v_index IN 1..length(v_rearranged) LOOP
    v_char := substring(v_rearranged FROM v_index FOR 1);
    v_expanded := CASE WHEN v_char ~ '[0-9]' THEN v_char ELSE (ascii(v_char) - 55)::text END;
    FOR v_digit_index IN 1..length(v_expanded) LOOP
      v_remainder := (v_remainder * 10 + substring(v_expanded FROM v_digit_index FOR 1)::integer) % 97;
    END LOOP;
  END LOOP;
  RETURN v_remainder = 1;
END;
$_$;


ALTER FUNCTION public.is_valid_iban(p_value text) OWNER TO postgres;

--
-- Name: issue_order_overview_internal(bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_order_overview_internal(p_order bigint, p_delivery jsonb, p_command uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE o eshop.orders; occ public.occasions; expiry timestamptz;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order AND source_waitlist_order_id IS NULL FOR UPDATE;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=o.occasion;
 IF occ.end_time IS NULL THEN RAISE EXCEPTION 'OVERVIEW_EVENT_END_REQUIRED'; END IF;
 expiry:=greatest(occ.end_time+interval '90 days',statement_timestamp()+interval '30 days');
 IF p_command IS NULL OR p_delivery->>'tokenHash' IS NULL OR p_delivery->>'tokenHash' !~ '^[0-9a-f]{64}$'
 OR p_delivery->>'contentHash' IS NULL OR p_delivery->>'contentHash' !~ '^[0-9a-f]{64}$'
 OR jsonb_typeof(p_delivery->'sealed') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_OVERVIEW_SOURCE'; END IF;
 INSERT INTO eshop.waitlist_capabilities(token_hash,organization_id,form_id,order_id,kind,expires_at)
 VALUES(p_delivery->>'tokenHash',occ.organization,o.form,o.id,'order_view',expiry);
 INSERT INTO eshop.order_overview_sources(token_hash,sealed,content_hash,expires_at,command_id)
 VALUES(p_delivery->>'tokenHash',p_delivery->'sealed',p_delivery->>'contentHash',expiry,p_command);
END $_$;


ALTER FUNCTION public.issue_order_overview_internal(p_order bigint, p_delivery jsonb, p_command uuid) OWNER TO postgres;

--
-- Name: issue_reception_login_qr_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_reception_login_qr_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_token text; v_hash text; v_actor uuid:=auth.uid();
  v_manual text; v_manual_hash text; v_manual_bytes bytea; v_alphabet constant text:='23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN RETURN jsonb_build_object('code',403,'message','reception_unavailable'); END IF;
  IF NOT public.reception_rate_limit_v1('issue') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND ou."user"=p_user)
    OR NOT (public.can_manage_occasion_participants(p_occasion) OR EXISTS(
      SELECT 1 FROM public.reception_registrations r
      WHERE r.occasion=p_occasion AND r."user"=p_user AND r.status='active'
        AND r.created_by=v_actor AND r.created_at>now()-interval '30 minutes')) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  v_token:=translate(encode(gen_random_bytes(32),'base64'),E'+/=\n','-_'); v_hash:=encode(digest(v_token,'sha256'),'hex');
  v_manual_bytes:=gen_random_bytes(8);
  SELECT string_agg(substr(v_alphabet,(get_byte(v_manual_bytes,i)%32)+1,1),'') INTO v_manual FROM generate_series(0,7) i;
  v_manual_hash:=encode(digest(v_manual,'sha256'),'hex');
  INSERT INTO public.user_login_qr_credentials(occasion,"user",token_hash,manual_token_hash,manual_expires_at,created_by)
  VALUES(p_occasion,p_user,v_hash,v_manual_hash,now()+interval '30 minutes',v_actor)
  ON CONFLICT(occasion,"user") DO UPDATE SET token_hash=excluded.token_hash,manual_token_hash=excluded.manual_token_hash,
    manual_expires_at=excluded.manual_expires_at,created_by=excluded.created_by,rotated_at=now(),revoked_at=NULL,last_used_at=NULL,use_count=0;
  RETURN jsonb_build_object('code',200,'payload','festapp-login:v1:'||p_occasion::text||':'||v_token,
    'manualCode',left(v_manual,4)||'-'||right(v_manual,4));
END $$;


ALTER FUNCTION public.issue_reception_login_qr_v1(p_occasion bigint, p_user uuid) OWNER TO postgres;

--
-- Name: issue_stripe_capability_internal(bigint, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_stripe_capability_internal(p_order bigint, p_scope text, p_expires_at timestamp with time zone, p_attempt uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_token text; v_attempt eshop.stripe_checkout_attempts;
BEGIN
 PERFORM public.require_service_role();
 IF p_scope IS NULL OR p_scope NOT IN ('order_pay','handoff','return_read') OR
  p_expires_at IS NULL OR p_expires_at<=clock_timestamp() OR
  (p_scope<>'order_pay' AND p_attempt IS NULL) THEN RAISE EXCEPTION 'STRIPE_CAPABILITY_INVALID'; END IF;
 PERFORM 1 FROM eshop.orders o JOIN eshop.payment_info pi ON pi.id=o.payment_info
 WHERE o.id=p_order AND pi.payment_method='stripe' AND o.state<>'waitlisted' FOR UPDATE OF o;
 IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_CAPABILITY_INVALID'; END IF;
 IF p_attempt IS NOT NULL THEN
  SELECT * INTO v_attempt FROM eshop.stripe_checkout_attempts WHERE id=p_attempt AND order_id=p_order;
  IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_CAPABILITY_INVALID'; END IF;
 END IF;
 IF p_scope IN ('handoff','return_read') AND p_expires_at>least(v_attempt.reservation_expires_at,clock_timestamp()+interval '30 minutes') THEN
  RAISE EXCEPTION 'STRIPE_CAPABILITY_EXPIRY_INVALID'; END IF;
 v_token:=encode(extensions.gen_random_bytes(32),'hex');
 INSERT INTO eshop.stripe_capabilities(token_hash,scope,order_id,attempt_id,expires_at)
 VALUES(encode(extensions.digest(v_token,'sha256'),'hex'),p_scope,p_order,p_attempt,p_expires_at);
 RETURN v_token;
END $$;


ALTER FUNCTION public.issue_stripe_capability_internal(p_order bigint, p_scope text, p_expires_at timestamp with time zone, p_attempt uuid) OWNER TO postgres;

--
-- Name: issue_wix_checkout_origin_internal(text, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_wix_checkout_origin_internal(p_form_link text, p_instance uuid, p_site uuid, p_organization bigint, p_app uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f public.forms; token_payload text; token_signature text; stamp bigint:=extract(epoch FROM clock_timestamp())::bigint;
BEGIN
 PERFORM public.require_service_role();
 IF p_instance IS NULL OR p_site IS NULL OR p_organization IS NULL OR p_app IS NULL
  OR p_form_link IS NULL OR length(p_form_link)>200 THEN RAISE invalid_parameter_value USING MESSAGE='INVALID_CHECKOUT_ORIGIN'; END IF;
 IF NOT EXISTS(SELECT 1 FROM eshop.checkout_origin_signing_key
  WHERE singleton AND organization_id=p_organization AND app_id=p_app) THEN
  RAISE invalid_parameter_value USING MESSAGE='INVALID_CHECKOUT_ORIGIN'; END IF;
 SELECT * INTO f FROM public.forms WHERE id=public.resolve_form_link_internal(p_form_link);
 IF f.id IS NULL OR f.is_open IS DISTINCT FROM true OR NOT EXISTS(
  SELECT 1 FROM public.occasions o WHERE o.id=f.occasion AND o.organization=p_organization
 ) OR public.is_demo_occasion(f.occasion) THEN
  RAISE invalid_parameter_value USING MESSAGE='FORM_UNAVAILABLE'; END IF;
 token_payload:=rtrim(translate(encode(convert_to(jsonb_build_object(
  'v',1,'channel','wix','formId',f.id,'instanceId',p_instance,'siteId',p_site,
  'verifiedAt',stamp,'expiresAt',stamp+86400)::text,'UTF8'),'base64'),E'+/\n','-_'),'=');
 SELECT encode(extensions.hmac(convert_to(token_payload,'UTF8'),secret,'sha256'),'hex')
 INTO STRICT token_signature FROM eshop.checkout_origin_signing_key WHERE singleton;
 RETURN jsonb_build_object('context',token_payload||'.'||token_signature,'expiresAt',stamp+86400);
END $$;


ALTER FUNCTION public.issue_wix_checkout_origin_internal(p_form_link text, p_instance uuid, p_site uuid, p_organization bigint, p_app uuid) OWNER TO postgres;

--
-- Name: link_bank_account_to_unit(bigint, bigint, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.link_bank_account_to_unit(p_bank_account_id bigint, p_unit_id bigint, p_priority integer, p_hard boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_conflict_data jsonb;
    v_is_reordering boolean;
BEGIN
    PERFORM public.check_bank_account_writable(p_bank_account_id);
    v_is_reordering := EXISTS (
        SELECT 1 FROM eshop.unit_bank_accounts
        WHERE unit = p_unit_id AND bank_account = p_bank_account_id
    );
    IF p_priority IS NULL OR v_is_reordering THEN
        IF NOT public.can_manage_unit_bank_accounts(p_unit_id) THEN
            RAISE insufficient_privilege USING MESSAGE='User is not manager.';
        END IF;
    ELSIF NOT public.can_link_bank_account_to_unit(p_bank_account_id,p_unit_id) THEN
        RAISE EXCEPTION 'User is not an admin of this bank account or manager of the target unit.' USING ERRCODE='42501';
    END IF;

    IF p_priority IS NULL THEN
        -- Unlink Logic

        -- Dependency Check (unless hard)
        IF NOT p_hard THEN
            WITH TargetAcc AS (
                SELECT unnest(supported_currencies) as curr FROM eshop.bank_accounts WHERE id = p_bank_account_id
            ),
            OtherAccs AS (
                SELECT unnest(ba.supported_currencies) as curr
                FROM eshop.unit_bank_accounts uba
                JOIN eshop.bank_accounts ba ON uba.bank_account = ba.id
                WHERE uba.unit = p_unit_id AND uba.bank_account != p_bank_account_id AND ba.type IS DISTINCT FROM 'CASH'
            ),
            LostCurrencies AS (
                SELECT curr FROM TargetAcc
                EXCEPT
                SELECT curr FROM OtherAccs
            ),
            ConflictingForms AS (
                SELECT DISTINCT f.title as form_title, f.link as form_link, p.currency_code, o.title as occasion_title
                FROM public.forms f
                JOIN public.occasions o ON f.occasion = o.id
                JOIN public.form_fields ff ON ff.form = f.id
                JOIN eshop.product_types pt ON ff.product_type = pt.id
                JOIN eshop.products p ON p.product_type = pt.id
                JOIN eshop.products p2 ON ff.product_type = p2.product_type
                WHERE o.unit = p_unit_id
                  AND f.is_open = true
                  AND coalesce(f.data#>'{payments,bankEnabled}','true'::jsonb)='true'::jsonb
                  -- AND p.is_hidden = false -- Removed is_hidden check? Original SQL had it. Let's keep it tight.
                  AND p.currency_code IN (SELECT curr FROM LostCurrencies)
            )
            SELECT jsonb_agg(jsonb_build_object('form', form_title, 'link', form_link, 'currency', currency_code, 'occasion', occasion_title))
            INTO v_conflict_data
            FROM ConflictingForms;

            IF v_conflict_data IS NOT NULL THEN
                 RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'LINK_DEPENDENCY_ERROR',
                    'message', 'Cannot unlink bank account because some active forms depend on its currency support.',
                    'conflicts', v_conflict_data
                 )::text;
            END IF;
        END IF;

        DELETE FROM eshop.unit_bank_accounts
        WHERE unit = p_unit_id AND bank_account = p_bank_account_id;
    ELSE
        -- Link or Update Priority
        IF v_is_reordering THEN
            UPDATE eshop.unit_bank_accounts
            SET priority = p_priority
            WHERE unit = p_unit_id AND bank_account = p_bank_account_id;
        ELSE
            INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
            VALUES (p_unit_id, p_bank_account_id, p_priority);

        END IF;
    END IF;
END;
$$;


ALTER FUNCTION public.link_bank_account_to_unit(p_bank_account_id bigint, p_unit_id bigint, p_priority integer, p_hard boolean) OWNER TO postgres;

--
-- Name: list_activity_history(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_activity_history(p_occasion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    history_data JSONB;
BEGIN
    IF (SELECT get_is_editor_on_occasion(p_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view history');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', h.id,
        'created_at', h.created_at,
        'history_type', h.history_type,
        'note', h.note,
        'user_name', u.name,
        'user_surname', u.surname
    ) ORDER BY h.created_at DESC), '[]'::jsonb)
    INTO history_data
    FROM public.activity_history h
    LEFT JOIN public.user_info u ON h.user_id = u.id
    WHERE h.occasion_id = p_occasion_id AND (h.history_type <> 'AUTOSAVE' OR (h.history_type = 'AUTOSAVE' AND h.user_id = auth.uid()));

    RETURN jsonb_build_object(
        'code', 200,
        'message', 'History retrieved successfully',
        'data', history_data
    );
END;
$$;


ALTER FUNCTION public.list_activity_history(p_occasion_id bigint) OWNER TO postgres;

