-- Name: lock_email_template_hierarchy_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_email_template_hierarchy_internal(p_context jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM 1 FROM public.organizations WHERE id=(p_context->>'organization')::bigint FOR SHARE;
 IF p_context->>'occasion' IS NOT NULL THEN
  PERFORM 1 FROM public.units WHERE id=(p_context->>'unit')::bigint FOR SHARE;
  PERFORM 1 FROM public.occasions WHERE id=(p_context->>'occasion')::bigint FOR UPDATE;
 ELSIF p_context->>'unit' IS NOT NULL THEN
  PERFORM 1 FROM public.units WHERE id=(p_context->>'unit')::bigint FOR UPDATE;
 END IF;
END $$;


ALTER FUNCTION public.lock_email_template_hierarchy_internal(p_context jsonb) OWNER TO postgres;

--
-- Name: lock_event_deletion_scope_internal_v1(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_event_deletion_scope_internal_v1(p_occasion bigint, p_ids bigint[]) RETURNS bigint[]
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE children bigint[]; current_children bigint[];
BEGIN
 SELECT ARRAY(SELECT DISTINCT event_child FROM public.event_groups WHERE event_parent=ANY(p_ids) AND NOT event_child=ANY(p_ids) ORDER BY event_child) INTO children;
 IF EXISTS(SELECT 1 FROM public.events WHERE id=ANY(children) AND occasion<>p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='event child outside occasion'; END IF;
 PERFORM 1 FROM public.events WHERE occasion=p_occasion AND id=ANY(p_ids||children) ORDER BY id FOR UPDATE;
 SELECT ARRAY(SELECT DISTINCT event_child FROM public.event_groups WHERE event_parent=ANY(p_ids) AND NOT event_child=ANY(p_ids) ORDER BY event_child) INTO current_children;
 IF children IS DISTINCT FROM current_children THEN RAISE serialization_failure USING MESSAGE='event links changed; retry the same command'; END IF;
 RETURN children;
END $$;


ALTER FUNCTION public.lock_event_deletion_scope_internal_v1(p_occasion bigint, p_ids bigint[]) OWNER TO postgres;

--
-- Name: lock_form_order_internal(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_form_order_internal(p_occasion bigint, p_form bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 -- Same parent order as actual checkout and the administration seat flow.
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 PERFORM 1 FROM public.forms WHERE id=p_form FOR UPDATE;
 PERFORM 1 FROM eshop.product_types WHERE id IN(SELECT product_type FROM public.form_fields WHERE form=p_form) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.products WHERE product_type IN(SELECT product_type FROM public.form_fields WHERE form=p_form) ORDER BY id FOR UPDATE;
END $$;


