--
-- Name: lock_people_scope_internal_v1(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_people_scope_internal_v1(p_occasion bigint, p_organization bigint DEFAULT NULL::bigint, p_unit bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE resource public.occasions%ROWTYPE; organizer public.units%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated identity required'; END IF;
 IF p_occasion IS NOT NULL THEN
  SELECT * INTO resource FROM public.occasions WHERE id=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='occasion unavailable'; END IF;
  IF (p_organization IS NOT NULL AND resource.organization IS DISTINCT FROM p_organization)
    OR (p_unit IS NOT NULL AND resource.unit IS DISTINCT FROM p_unit) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
  SELECT * INTO organizer FROM public.units WHERE id=resource.unit FOR SHARE;
 ELSE
  SELECT * INTO organizer FROM public.units WHERE id=p_unit FOR SHARE;
 END IF;
 IF organizer.id IS NULL OR (p_organization IS NOT NULL AND organizer.organization IS DISTINCT FROM p_organization) THEN
  RAISE insufficient_privilege USING MESSAGE='organizer scope changed'; END IF;
 PERFORM 1 FROM public.organization_users WHERE organization=organizer.organization AND "user"=auth.uid() FOR SHARE;
 PERFORM 1 FROM public.unit_users WHERE unit=organizer.id AND "user"=auth.uid() FOR SHARE;
 IF p_occasion IS NOT NULL THEN
  PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=auth.uid() FOR SHARE;
 END IF;
END $$;


ALTER FUNCTION public.lock_people_scope_internal_v1(p_occasion bigint, p_organization bigint, p_unit bigint) OWNER TO postgres;

--
-- Name: lock_pool_product_dependencies_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_pool_product_dependencies_internal_v1(p_pool bigint) RETURNS bigint[]
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_product_ids bigint[];
BEGIN
 SELECT coalesce(array_agg(DISTINCT pic.product ORDER BY pic.product),'{}') INTO v_product_ids
 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context WHERE ic.inventory_pool=p_pool;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE product=ANY(v_product_ids)));
 PERFORM 1 FROM eshop.products WHERE id=ANY(v_product_ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context
   WHERE ic.inventory_pool=p_pool AND NOT pic.product=ANY(v_product_ids)) THEN
  RAISE serialization_failure USING MESSAGE='inventory product dependencies changed; retry the same command'; END IF;
 RETURN v_product_ids;
END $$;


ALTER FUNCTION public.lock_pool_product_dependencies_internal_v1(p_pool bigint) OWNER TO postgres;

--
-- Name: lock_primary_product_forms_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_primary_product_forms_internal(p_product bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM 1 FROM public.forms f WHERE f.id IN(
   SELECT ff.form FROM public.form_fields ff JOIN eshop.product_types pt ON pt.id=ff.product_type
   JOIN eshop.products p ON p.product_type=pt.id WHERE p.id=p_product AND pt.type='spot')
 ORDER BY f.id FOR UPDATE;
END $$;


ALTER FUNCTION public.lock_primary_product_forms_internal(p_product bigint) OWNER TO postgres;

--
-- Name: lock_product_order_dependencies_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_product_order_dependencies_internal_v1(p_product bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];
BEGIN
 SELECT ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE product=p_product ORDER BY "order") INTO ids;
 PERFORM public.lock_order_capacity_scope_internal(ids);
 PERFORM 1 FROM eshop.products WHERE id=p_product FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE product=p_product AND NOT "order"=ANY(ids)) THEN
  RAISE serialization_failure USING MESSAGE='product order parents changed; retry the same command'; END IF;
END $$;


ALTER FUNCTION public.lock_product_order_dependencies_internal_v1(p_product bigint) OWNER TO postgres;

--
-- Name: lock_resource_pools_internal_v1(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_resource_pools_internal_v1(p_resource bigint, p_target bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE origin bigint; current_pool bigint;
BEGIN
 SELECT inventory_pool INTO origin FROM public.resources WHERE id=p_resource;
 PERFORM 1 FROM public.inventory_pools WHERE id=ANY(ARRAY[origin,p_target]) ORDER BY id FOR UPDATE;
 SELECT inventory_pool INTO current_pool FROM public.resources WHERE id=p_resource FOR UPDATE;
 IF current_pool IS DISTINCT FROM origin THEN
  RAISE serialization_failure USING MESSAGE='resource pool changed; retry the same command'; END IF;
 RETURN origin;
END $$;


ALTER FUNCTION public.lock_resource_pools_internal_v1(p_resource bigint, p_target bigint) OWNER TO postgres;

--
-- Name: lock_speaker_event_dependencies_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_speaker_event_dependencies_internal_v1(p_speaker bigint) RETURNS bigint[]
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[]; current_ids bigint[];
BEGIN
 SELECT ARRAY(SELECT event FROM public.event_speakers WHERE speaker=p_speaker ORDER BY event) INTO ids;
 PERFORM 1 FROM public.events WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.speakers WHERE id=p_speaker FOR UPDATE;
 SELECT ARRAY(SELECT event FROM public.event_speakers WHERE speaker=p_speaker ORDER BY event) INTO current_ids;
 IF ids IS DISTINCT FROM current_ids THEN RAISE serialization_failure USING MESSAGE='speaker event links changed; retry the same command'; END IF;
 RETURN ids;
END $$;


ALTER FUNCTION public.lock_speaker_event_dependencies_internal_v1(p_speaker bigint) OWNER TO postgres;

