CREATE FUNCTION public.lock_spot_assignment_scope_internal_v1(p_spots bigint[], p_resources bigint[] DEFAULT '{}'::bigint[]) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.lock_spot_assignment_scope_internal(p_spots,p_resources,false)
$$;


