--
-- Name: lock_ticket_order_products_internal(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_ticket_order_products_internal(p_order bigint, p_input jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];
BEGIN
 SELECT coalesce(array_agg(DISTINCT id),'{}') INTO ids FROM (
  SELECT product id FROM eshop.order_product_ticket WHERE "order"=p_order
  UNION ALL SELECT (f->>'product_type')::bigint FROM jsonb_array_elements(coalesce(p_input->'ticket','[]')) t
   CROSS JOIN LATERAL jsonb_array_elements(coalesce(t->'fields','[]')) f WHERE f ? 'product_type'
  UNION ALL SELECT s.product FROM jsonb_array_elements(coalesce(p_input->'ticket','[]')) t JOIN eshop.spots s ON s.id=(t->>'spot')::bigint) selected;
 PERFORM 1 FROM eshop.products WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.blueprints WHERE id IN(
  SELECT blueprint FROM public.forms WHERE id IN(SELECT form FROM eshop.orders WHERE id=p_order)
  UNION SELECT blueprint FROM eshop.spots WHERE product=ANY(ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT ic.inventory_pool FROM public.inventory_contexts ic
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id WHERE pic.product=ANY(ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_contexts WHERE id IN(SELECT inventory_context FROM eshop.product_inventory_contexts WHERE product=ANY(ids)) ORDER BY id FOR UPDATE;
END $$;


ALTER FUNCTION public.lock_ticket_order_products_internal(p_order bigint, p_input jsonb) OWNER TO postgres;

--
-- Name: log_canonical_mutation_request_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_canonical_mutation_request_v1() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
 h jsonb; method text; path text; request_id text; fields jsonb; client_info text[];
BEGIN
 method:=current_setting('request.method',true);
 IF method IS NULL OR method NOT IN ('POST','PATCH','PUT','DELETE') THEN RETURN; END IF;
 path:=current_setting('request.path',true);
 -- Never log query strings, bodies, cookies, arbitrary header values or JWTs.
 IF path IS NULL OR length(path)>180 OR path !~ '^/[a-zA-Z0-9_/.-]+$' THEN path:='unidentified'; END IF;
 BEGIN h:=nullif(current_setting('request.headers',true),'')::jsonb;
 EXCEPTION WHEN invalid_text_representation THEN h:='{}'::jsonb; END;
 client_info:=regexp_match(h->>'x-client-info','^festapp/([0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,4})[+]([0-9]{1,10})/(web|pwa|android|ios|js|service|edge|import|cron)$');
 request_id:=gen_random_uuid()::text;
 PERFORM set_config('festapp.mutation_audit_request_id',request_id,true);
 fields:=jsonb_build_object('schemaVersion',1,'event','request','requestId',request_id,
   'pid',pg_backend_pid(),'actor',auth.uid(),'role',current_user,'method',method,'path',path,
   'declaredVersion',client_info[1],'declaredBuild',client_info[2],'declaredPlatform',client_info[3]);
 RAISE LOG 'FESTAPP_MUTATION_OBSERVATION %',fields;
END $_$;


ALTER FUNCTION public.log_canonical_mutation_request_v1() OWNER TO postgres;

--
-- Name: log_canonical_mutation_scope_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_canonical_mutation_scope_internal_v1(p_occasion bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE request_id text:=nullif(current_setting('festapp.mutation_audit_request_id',true),'');
BEGIN
 -- Called only by the existing owner, with its resolved occasion. A client
 -- cannot supply a scope through this hook or invoke this internal function.
 IF request_id IS NOT NULL THEN
  RAISE LOG 'FESTAPP_MUTATION_OBSERVATION %',jsonb_build_object('schemaVersion',1,
    'event','scope','requestId',request_id,'pid',pg_backend_pid(),'occasion',p_occasion);
 END IF;
END $$;


ALTER FUNCTION public.log_canonical_mutation_scope_internal_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: lookup_scanner_ticket(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lookup_scanner_ticket(p_session uuid, p_token text, p_symbol text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; tid bigint; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 SELECT t.id INTO tid FROM eshop.tickets t WHERE t.occasion=s.occasion_id AND t.ticket_symbol=p_symbol LIMIT 1;
 IF tid IS NULL AND p_symbol ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN
  SELECT t.id INTO tid FROM public.occasion_users ou JOIN eshop.tickets t ON t.id=ou.ticket WHERE ou.occasion=s.occasion_id AND ou."user"=p_symbol::uuid AND t.occasion=s.occasion_id LIMIT 1;
 END IF;
 SELECT dto INTO result FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config,tid) WHERE ticket_id=tid;
 IF result IS NOT NULL THEN result:=result||jsonb_build_object('can_reset_password',public.scanner_can_reset_password_internal(s.occasion_id,tid)); END IF;
 RETURN jsonb_build_object('code',CASE WHEN result IS NULL THEN 404 ELSE 200 END,'reason',CASE WHEN result IS NULL THEN 'not_found' ELSE 'found' END,
 'data',result,'settings_revision',cfg.revision,'server_time',now());
END $_$;


ALTER FUNCTION public.lookup_scanner_ticket(p_session uuid, p_token text, p_symbol text) OWNER TO postgres;

--
-- Name: maintain_notification_center(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintain_notification_center(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE m record; maximum bigint; after_id bigint; processed integer:=0; projected integer; availability integer; purge_ids uuid[];
BEGIN
 PERFORM public.notification_center_require_service();
 INSERT INTO public.notification_center_maintenance(name) VALUES('email') ON CONFLICT DO NOTHING;
 SELECT cursor INTO after_id FROM public.notification_center_maintenance WHERE name='email' FOR UPDATE SKIP LOCKED;
 IF FOUND THEN
  FOR m IN SELECT em.id,em.message_id FROM public.email_messages em JOIN public.notification_center_organizations a ON a.organization=em.organization
   LEFT JOIN public.notification_center_source_state ns ON ns.organization=em.organization AND ns.source_key='email:'||em.message_id
   WHERE em.id>after_id AND em.workflow_state IN ('pending','preparing','sending','retry_wait','unknown')
   AND (coalesce((ns.state->>'dueAt')::timestamptz,em.target_time)<=clock_timestamp()-interval '30 minutes' OR (em.message_kind='waitlist_offer' AND em.expires_at<=clock_timestamp()+interval '5 minutes'))
   ORDER BY em.id LIMIT greatest(1,least(p_limit,500)) LOOP
   PERFORM public.notification_center_email_internal(m.message_id); maximum:=m.id; processed:=processed+1;
  END LOOP;
  UPDATE public.notification_center_maintenance SET cursor=coalesce(maximum,0) WHERE name='email';
 END IF;
 availability:=public.notification_center_evaluate_forms_internal(p_limit);
 projected:=public.project_notification_center(p_limit);
 -- Retain active incidents; cleanup is projection-only, never business/email history.
 DELETE FROM public.notification_center_deliveries WHERE (event_id,recipient,attention_revision) IN (
  SELECT d.event_id,d.recipient,d.attention_revision FROM public.notification_center_deliveries d JOIN public.notification_center_events e ON e.id=d.event_id
  WHERE d.delivered_at<clock_timestamp()-interval '90 days' AND (e.status='recovered' OR e.kind NOT IN ('email_problem','bank_problem','capacity_full','capacity_warning')) LIMIT greatest(1,least(p_limit,500)));
 SELECT array_agg(id) INTO purge_ids FROM (SELECT e.id FROM public.notification_center_events e
  WHERE e.occurred_at<clock_timestamp()-interval '90 days' AND (e.status='recovered' OR e.kind NOT IN ('email_problem','bank_problem','capacity_full','capacity_warning'))
  AND NOT EXISTS(SELECT 1 FROM public.notification_center_deliveries WHERE event_id=e.id) AND e.projected_revision=e.attention_revision
  LIMIT greatest(1,least(p_limit,500)) FOR UPDATE SKIP LOCKED) expired;
 -- Retract derived counts and dirty-source debt before recipients cascade away.
 -- A recovered long-running incident may still have an unprocessed repair.
 IF cardinality(purge_ids)>0 THEN
  PERFORM public.notification_center_prepared_delete_events(purge_ids);
  DELETE FROM public.notification_center_events WHERE id=ANY(purge_ids);
 END IF;
 RETURN jsonb_build_object('evaluated',processed,'projected',projected,'availabilityEvaluated',availability);
END $$;


ALTER FUNCTION public.maintain_notification_center(p_limit integer) OWNER TO postgres;

--
-- Name: maintain_sale_opening_notifications(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maintain_sale_opening_notifications(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE f record; c public.sale_opening_campaigns; s record; n integer:=0; a jsonb; counts jsonb; expired_ids uuid[];
BEGIN
 PERFORM public.require_service_role();
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='sale opening batch limit'; END IF;
 FOR f IN SELECT forms.id,forms.occasion FROM public.forms forms JOIN public.sale_opening_campaigns x ON x.form_id=forms.id
  WHERE x.phase IN ('armed','dispatching','completed','cancelled') ORDER BY x.next_maintenance_at,x.id LIMIT p_limit
 LOOP
  -- Scope lock precedes the form lock, matching save and public commands.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('sale-opening-maintenance:'||f.id,0)) THEN CONTINUE; END IF;
  PERFORM public.lock_blueprint_scope_internal(ARRAY[f.occasion]);
  PERFORM 1 FROM public.forms WHERE id=f.id FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE; END IF;
  SELECT * INTO c FROM public.sale_opening_campaigns WHERE form_id=f.id FOR UPDATE;
  UPDATE public.sale_opening_campaigns SET next_maintenance_at=clock_timestamp()+interval '1 minute' WHERE id=c.id;
  a:=public.get_form_availability_snapshot_internal(f.id);
  IF c.phase='armed' AND public.get_form_registration_mode_internal(f.id) IN ('regular','blueprint') THEN
   UPDATE public.sale_opening_campaigns SET phase='dispatching',opened_at=clock_timestamp(),revision=revision+1
    WHERE id=c.id RETURNING * INTO c;
  END IF;
  IF c.phase='dispatching' AND public.get_form_registration_mode_internal(f.id) IN ('regular','blueprint')
   AND c.opened_at+interval '24 hours'>clock_timestamp() THEN
   FOR s IN SELECT sub.id FROM public.sale_opening_subscriptions sub WHERE sub.campaign_id=c.id AND sub.state='active'
    AND NOT EXISTS(SELECT 1 FROM public.email_messages m WHERE m.message_kind='sale_opening_opened'
     AND m.dedupe_key=c.id||':'||sub.id||':opened') ORDER BY sub.created_at,sub.id LIMIT p_limit-n
   LOOP
    BEGIN
     PERFORM public.enqueue_sale_opening_internal(s.id,'sale_opening_opened'); n:=n+1;
    EXCEPTION WHEN SQLSTATE 'PT429' THEN RETURN n; END;
   END LOOP;
   IF NOT EXISTS(SELECT 1 FROM public.sale_opening_subscriptions sub WHERE sub.campaign_id=c.id AND sub.state='active'
    AND NOT EXISTS(SELECT 1 FROM public.email_messages m WHERE m.message_kind='sale_opening_opened' AND m.dedupe_key=c.id||':'||sub.id||':opened')) THEN
    UPDATE public.sale_opening_campaigns SET phase='completed' WHERE id=c.id;
   END IF;
  END IF;
  -- Temporary closures preserve the original intent. Only never-started
  -- cancellations caused by the live gate may be retried; unknown is fenced.
  UPDATE public.email_messages m SET workflow_state='pending',target_time=clock_timestamp(),prepared=NULL,prepared_hash=NULL,prepared_at=NULL,
   lease_token=NULL,lease_until=NULL,last_error=NULL
   WHERE m.message_kind='sale_opening_opened' AND m.data->>'campaign_id'=c.id::text
   AND m.workflow_state='cancelled' AND m.last_error='intent_invalid' AND public.sale_opening_intent_valid_internal(m)
   AND NOT EXISTS(SELECT 1 FROM public.email_attempts at WHERE at.message_id=m.message_id AND at.state IN ('sending','accepted','unknown'));
  IF c.phase='cancelled' OR c.opened_at+interval '24 hours'<=clock_timestamp() OR (a->>'endAt')::timestamptz<clock_timestamp() THEN
   UPDATE public.sale_opening_campaigns SET phase=CASE WHEN phase='cancelled' THEN phase ELSE 'completed' END,
    closed_at=coalesce(closed_at,clock_timestamp()) WHERE id=c.id;
   UPDATE public.sale_opening_subscriptions SET state='closed',closed_at=clock_timestamp()
    WHERE campaign_id=c.id AND state='active';
  END IF;
  -- Retain anonymous totals before deleting contacts and encrypted token sources.
  SELECT array_agg(id) INTO expired_ids FROM (SELECT id FROM public.sale_opening_subscriptions WHERE campaign_id=c.id
   AND closed_at<clock_timestamp()-interval '30 days'
   ORDER BY id LIMIT 100) expired;
  SELECT coalesce(jsonb_object_agg(state,total),'{}') INTO counts FROM (
   SELECT state,count(*) total FROM public.sale_opening_subscriptions WHERE id=ANY(expired_ids) GROUP BY state) totals;
  -- Add this sweep's totals to prior anonymous aggregates, without addresses.
  UPDATE public.sale_opening_campaigns SET retained_counts=(SELECT coalesce(jsonb_object_agg(key,total),'{}') FROM (
   SELECT key,sum(value::bigint) total FROM (SELECT * FROM jsonb_each_text(retained_counts) UNION ALL SELECT * FROM jsonb_each_text(counts)) x GROUP BY key) y) WHERE id=c.id;
  DELETE FROM public.sale_opening_subscriptions WHERE id=ANY(expired_ids);
  IF n>=p_limit THEN EXIT; END IF;
 END LOOP;
 RETURN n;
END $$;


ALTER FUNCTION public.maintain_sale_opening_notifications(p_limit integer) OWNER TO postgres;

--
-- Name: manage_bank_authoring(bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_bank_authoring(p_unit bigint, p_organization bigint, p_action text, p_payload jsonb, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE unit_id bigint:=p_unit; bank bigint:=(p_payload->>'accountId')::bigint; result jsonb; begun jsonb; hash text; lim int:=coalesce((p_payload->>'limit')::int,50); ident bigint;
BEGIN
 IF unit_id IS NULL AND bank IS NOT NULL THEN
  SELECT r.unit INTO unit_id FROM public.client_mutation_receipts r WHERE r.command_id=p_command_id AND r.actor_id=auth.uid() AND r.command_name='unit.bank.'||p_action;
  IF unit_id IS NULL THEN
   SELECT link.unit INTO unit_id FROM eshop.unit_bank_accounts link WHERE link.bank_account=bank
    AND public.can_manage_bank_account(bank) AND public.can_manage_unit_bank_accounts(link.unit) ORDER BY link.unit LIMIT 1;
  END IF;
 END IF;
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,unit_id);
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>16384 OR lim NOT BETWEEN 1 AND 100 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid bank request'; END IF;
 IF p_action='list' THEN
  -- Preserve the ordinary demo read rule, but never its connection secrets.
  IF NOT public.can_read_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='bank reader required'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]') INTO result FROM (
   SELECT b.id,b.title,b.account_number AS "accountNumber",b.account_number_human_readable AS "displayNumber",b.creditor_name AS "creditorName",b.type,b.supported_currencies AS currencies,l.priority,
    public.can_manage_bank_account(b.id) AS "canManage"
   FROM eshop.unit_bank_accounts l JOIN eshop.bank_accounts b ON b.id=l.bank_account
   WHERE l.unit=unit_id AND (p_payload->>'after' IS NULL OR b.id>(p_payload->>'after')::bigint) ORDER BY b.id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action='candidates' THEN
  IF NOT public.can_manage_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]') INTO result FROM (
   SELECT b.id,b.title,b.account_number AS "accountNumber",b.type FROM eshop.bank_accounts b
   WHERE public.can_link_bank_account_to_unit(b.id,unit_id) AND (p_payload->>'after' IS NULL OR b.id>(p_payload->>'after')::bigint) ORDER BY b.id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 END IF;
 -- Stored link is required for every account operation except explicit linking.
 IF p_action='link' THEN
  PERFORM 1 FROM eshop.unit_bank_accounts WHERE unit=unit_id AND bank_account=bank FOR UPDATE;
  IF (p_payload->>'priority' IS NULL OR FOUND) THEN
   IF NOT public.can_manage_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  ELSIF NOT public.can_link_bank_account_to_unit(bank,unit_id) THEN RAISE insufficient_privilege USING MESSAGE='bank admin and target unit manager required'; END IF;
 ELSIF p_action='save' AND bank IS NULL THEN
  IF NOT public.can_manage_unit_bank_accounts(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 ELSE
  PERFORM 1 FROM eshop.unit_bank_accounts WHERE unit=unit_id AND bank_account=bank FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='bank is not linked to selected unit'; END IF;
  PERFORM 1 FROM eshop.bank_account_users WHERE bank_account=bank AND "user"=auth.uid() FOR SHARE;
  IF p_action='users' THEN
   IF NOT public.can_read_bank_account_users(bank,unit_id) THEN RAISE insufficient_privilege USING MESSAGE='bank user reader required'; END IF;
  ELSIF NOT public.can_manage_unit_bank_accounts(unit_id) OR NOT public.can_manage_bank_account(bank) THEN RAISE insufficient_privilege USING MESSAGE='bank admin and selected linked manager required'; END IF;
 END IF;
 IF p_action='users' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.user_id),'[]') INTO result FROM (
   SELECT * FROM public.get_bank_account_users(bank,unit_id) x
   WHERE p_payload->>'afterUser' IS NULL OR x.user_id>(p_payload->>'afterUser')::uuid ORDER BY x.user_id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action='status' THEN
  result:=public.get_bank_sync_connection(bank);
  RETURN jsonb_build_object('connection',CASE WHEN result IS NULL THEN NULL ELSE result-ARRAY['receiving_address','remote_bank_account_id','last_error'] END);
 ELSIF p_action='operations' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."createdAt" DESC,page.id DESC),'[]') INTO result FROM (
   SELECT id,operation,state,created_at AS "createdAt",updated_at AS "updatedAt" FROM eshop.bank_sync_operations
   WHERE bank_account_id=bank AND (p_payload->>'before' IS NULL OR (created_at,id)<((p_payload#>>'{before,createdAt}')::timestamptz,(p_payload#>>'{before,id}')::uuid))
   ORDER BY created_at DESC,id DESC LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action='observations' THEN
  -- The canonical observation owner omits source mail bodies and credentials.
  SELECT coalesce(jsonb_agg(jsonb_build_object('deliveryId',x->'delivery_id','receivedAt',x->'received_at','outcome',x->'outcome')),'[]') INTO result FROM jsonb_array_elements(public.get_bank_sync_observations(bank,lim)) x;
  RETURN jsonb_build_object('items',result);
 END IF;
 IF p_action NOT IN ('save','link','user') OR p_command_id IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='bank command required'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('unit',unit_id,'action',p_action,'payload',p_payload)::text,'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.bank.'||p_action,unit_id,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 IF p_action='save' THEN
  ident:=public.update_bank_account(bank,p_payload->>'accountNumber',p_payload->>'title',p_payload->>'type',
   CASE WHEN p_payload->'currencies' IS NULL OR p_payload->'currencies'='null'::jsonb THEN NULL ELSE ARRAY(SELECT jsonb_array_elements_text(p_payload->'currencies')) END,p_payload->>'displayNumber',unit_id,p_payload->>'creditorName');
  result:=jsonb_build_object('accountId',ident,'detailsSyncPending',EXISTS(SELECT 1 FROM eshop.bank_sync_operations WHERE bank_account_id=ident AND operation='update_details' AND state<>'completed'));
 ELSIF p_action='user' THEN
  PERFORM public.update_bank_account_user(bank,p_payload->>'email',(p_payload->>'isAdmin')::boolean,(p_payload->>'isSupport')::boolean);
  result:=jsonb_build_object('accountId',bank);
 ELSE
  PERFORM public.link_bank_account_to_unit(bank,unit_id,(p_payload->>'priority')::int,coalesce((p_payload->>'force')::boolean,false));
  result:=jsonb_build_object('accountId',bank,'priority',p_payload->'priority');
 END IF;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,unit_id,'unit.bank.'||p_action,'bank_account',coalesce(ident,bank),CASE WHEN p_action='save' AND bank IS NULL THEN 'insert' ELSE 'update' END,result);
END $$;


ALTER FUNCTION public.manage_bank_authoring(p_unit bigint, p_organization bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_blueprint_authoring(bigint, bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_blueprint_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.blueprints%ROWTYPE; result jsonb; payload jsonb:=coalesce(p_payload,'{}'); draft jsonb; lim int:=coalesce((p_payload->>'limit')::int,50);
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF public.can_write_blueprints(p_occasion) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' OR octet_length(payload::text)>8388608 OR lim NOT BETWEEN 1 AND 100 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid blueprint authoring request'; END IF;
 IF p_action='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."blueprintId"),'[]'::jsonb)) INTO result FROM (
   SELECT id AS "blueprintId",title,layout_revision AS "layoutRevision" FROM eshop.blueprints
   WHERE occasion=p_occasion AND (payload->>'after' IS NULL OR id>(payload->>'after')::bigint) ORDER BY id LIMIT lim) page;
  RETURN result;
 ELSIF p_action='authorizeText' THEN RETURN jsonb_build_object('actorId',auth.uid());
 END IF;
 IF p_action='save' THEN PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]); END IF;
 IF payload->>'blueprintId' IS NOT NULL THEN
  SELECT * INTO b FROM eshop.blueprints WHERE id=(payload->>'blueprintId')::bigint AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='blueprint outside scope'; END IF;
 END IF;
 IF p_action='inspect' THEN
  IF b.id IS NULL OR b.layout IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='saved blueprint required'; END IF;
  RETURN jsonb_build_object('blueprintId',b.id,'occasionId',b.occasion,'title',b.title,'layoutRevision',b.layout_revision,'layout',b.layout,
   'textResourceIds',coalesce(to_jsonb(b.layout_text_resource_ids),'[]'),'resources',public.blueprint_layout_resources_internal(b.layout,b.occasion))||public.blueprint_binding_projection_internal(b.id);
 ELSIF p_action='validate' THEN
  PERFORM public.validate_blueprint_layout_internal(payload->'layout');
  -- Advisory document validation grants no reservation, resource registration or save.
  RETURN jsonb_build_object('valid',true,'schemaVersion',2);
 ELSIF p_action='save' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(payload) k WHERE k NOT IN ('blueprintId','title','expectedLayoutRevision','layout','textResourceIds','seatChanges','groupProductChanges','areaBindingChanges')) THEN
   RAISE invalid_parameter_value USING MESSAGE='unsupported blueprint field'; END IF;
  draft:=(payload-'blueprintId'-'expectedLayoutRevision')||jsonb_build_object('occasion',p_occasion,'organization',p_organization,'expected_layout_revision',payload->'expectedLayoutRevision');
  IF b.id IS NOT NULL THEN draft:=draft||jsonb_build_object('id',b.id); END IF;
  result:=public.update_blueprint_client_sync_v1(draft,p_command_id);
  -- Frozen aggregate output is already a narrow binding projection; never reread after replay.
  RETURN result;
 END IF;
 RAISE invalid_parameter_value USING MESSAGE='unknown blueprint operation';
END $$;


ALTER FUNCTION public.manage_blueprint_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_card_refund_authoring(bigint, bigint, bigint, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_card_refund_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_payload jsonb DEFAULT NULL::jsonb, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='order scope changed'; END IF;
 IF p_payload IS NULL THEN
  result:=public.get_stripe_order_admin_detail(p_order);
  IF result IS NULL THEN RETURN NULL; END IF;
  RETURN (result-'dashboardUrl')||jsonb_build_object('tickets',(SELECT coalesce(jsonb_agg(x- 'label'),'[]') FROM jsonb_array_elements(result->'tickets') x));
 END IF;
 RETURN public.decide_stripe_partial_refund_client_sync_v1(p_order,p_payload->>'action',ARRAY(SELECT jsonb_array_elements_text(p_payload->'ticketIds'))::bigint[],p_payload->>'note',(p_payload->>'expectedRefundedMinor')::bigint,p_command_id);
END $$;


ALTER FUNCTION public.manage_card_refund_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_email_banner(text, bigint, bigint, bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_email_banner(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_expected_revision text, p_banner_url text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE context jsonb; state jsonb; started jsonb; hash text; name text; result jsonb;
BEGIN
 context:=public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit,true);
 IF p_expected_revision IS NULL OR p_expected_revision !~ '^[0-9a-f]{64}$'
  OR (p_banner_url IS NOT NULL AND (length(p_banner_url)>8192
    OR p_banner_url !~ '^https://(a\.)?img\.festapp\.net/(images|assets)/[A-Za-z0-9_./-]+$'
    OR p_banner_url LIKE '%/../%')) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid email banner command'; END IF;
 name:=p_entity_type||'.email_banner.save';
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('context',context,
   'expectedRevision',p_expected_revision,'url',p_banner_url)::text,'UTF8'),'sha256'),'hex');
 IF p_entity_type='occasion' THEN
  started:=public.begin_client_mutation_v1(p_command_id,name,p_entity_id,auth.uid(),hash);
 ELSE started:=public.begin_unit_client_mutation_v1(p_command_id,name,p_entity_id,auth.uid(),hash); END IF;
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 PERFORM public.lock_email_template_hierarchy_internal(context);
 PERFORM public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit,true);
 state:=public.get_email_banner_state_internal(context);
 IF state->>'revision' IS DISTINCT FROM p_expected_revision THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','EMAIL_BANNER_CHANGED'));
 END IF;
 PERFORM public.update_entity_email_banner(p_entity_type,p_entity_id,p_banner_url);
 result:=public.get_email_banner(p_entity_type,p_entity_id,p_organization,p_unit);
 IF p_entity_type='unit' THEN
  RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_entity_id,name,'unit',p_entity_id,'update',result);
 END IF;
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_entity_id,name,'configuration',
  jsonb_build_array(jsonb_build_object('entityType','occasion','entityId',p_entity_id,'operation','update',
   'safeLabel','Email banner','changedFields',jsonb_build_array('email_banner'))),ARRAY['occasion_config'],'[]','[]',result,
  '{}'::text[],'[]','user',NULL,'[]',ARRAY[(context->>'unit')::bigint]);
END $_$;


ALTER FUNCTION public.manage_email_banner(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_expected_revision text, p_banner_url text, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_email_template(text, bigint, bigint, bigint, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_email_template(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_action text, p_code text, p_expected_revision text, p_payload jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE context jsonb; state jsonb; started jsonb; hash text; name text; result jsonb; audience uuid[];
BEGIN
 context:=public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit,true);
 IF p_action IS NULL OR p_action NOT IN ('save','reset') OR p_code IS NULL
  OR p_expected_revision IS NULL OR p_expected_revision !~ '^[0-9a-f]{64}$'
  OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>524288
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('title','subject','html'))
  OR (p_action='save' AND (NOT p_payload ?& ARRAY['title','subject','html'] OR EXISTS(
    SELECT 1 FROM jsonb_each(p_payload) e WHERE jsonb_typeof(e.value) NOT IN ('string','null'))))
  OR (p_action='reset' AND p_payload<>'{}'::jsonb) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid email template command'; END IF;
 name:=p_entity_type||'.email_template.'||p_action;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('context',context,'action',p_action,
  'code',p_code,'expectedRevision',p_expected_revision,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');
 IF p_entity_type='occasion' THEN
  started:=public.begin_client_mutation_v1(p_command_id,name,p_entity_id,auth.uid(),hash);
 ELSE started:=public.begin_unit_client_mutation_v1(p_command_id,name,p_entity_id,auth.uid(),hash); END IF;
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 -- Receipt -> hierarchy -> target. Legacy writes use these same hierarchy locks.
 PERFORM public.lock_email_template_hierarchy_internal(context);
 PERFORM public.check_email_template_scope_internal(p_entity_type,p_entity_id,p_organization,p_unit,true);
 SELECT t INTO state FROM jsonb_array_elements(public.get_all_email_templates(context)) t WHERE t->>'code'=p_code;
 IF state IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='template unavailable in this scope'; END IF;
 IF state->>'revision' IS DISTINCT FROM p_expected_revision THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','EMAIL_TEMPLATE_CHANGED'));
 END IF;
 IF p_action='save' THEN
  PERFORM public.update_email_template(p_payload||context||jsonb_build_object('code',p_code));
 ELSE PERFORM public.delete_entity_email_template(p_entity_type,p_entity_id,p_code); END IF;
 result:=public.get_email_template_catalog(p_entity_type,p_entity_id,p_organization,p_unit,p_code);
 IF p_entity_type='unit' THEN
  RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_entity_id,name,'email_template',p_entity_id,'update',result);
 END IF;
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_entity_id,name,'configuration',
  jsonb_build_array(jsonb_build_object('entityType','email_template','entityId',p_entity_id,'operation','update',
   'safeLabel','Email template','changedFields',jsonb_build_array('template'))),'{}'::text[],'[]','[]',result);
END $_$;


ALTER FUNCTION public.manage_email_template(p_entity_type text, p_entity_id bigint, p_organization bigint, p_unit bigint, p_action text, p_code text, p_expected_revision text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_form(bigint, bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_form(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; link text; form_id bigint; source_id bigint; allowed text[]; state jsonb;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('create','save','duplicate','delete','public_link') OR p_payload IS NULL
  OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>1048576 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid form command'; END IF;
 PERFORM public.check_form_authoring_scope_internal(p_occasion,p_organization,p_unit,CASE WHEN p_action='public_link' THEN 'save' ELSE p_action END);
 SELECT o.link INTO link FROM public.occasions o WHERE o.id=p_occasion;
 IF p_action IN ('save','delete','public_link') THEN
  form_id:=(p_payload->>'id')::bigint;
  IF form_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.forms WHERE id=form_id AND occasion=p_occasion)
   AND NOT (p_action='delete' AND EXISTS(SELECT 1 FROM public.client_mutation_receipts
    WHERE command_id=p_command_id AND actor_id=auth.uid() AND occasion=p_occasion AND command_name='inventory.form.delete')) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign form'; END IF;
  IF NOT p_payload ? 'expected_aggregate_version' OR jsonb_typeof(p_payload->'expected_aggregate_version')<>'number'
    OR (p_payload->>'expected_aggregate_version')::bigint<0 THEN
   RAISE invalid_parameter_value USING MESSAGE='original form version required'; END IF;
 END IF;
 allowed:=CASE p_action
  WHEN 'public_link' THEN ARRAY['id','expected_aggregate_version','link']
  WHEN 'create' THEN ARRAY['title']
  WHEN 'save' THEN ARRAY['payment_selection_intent','id','expected_aggregate_version','expected_product_versions','expected_product_type_versions',
   'title','header','header_off','is_open','blueprint','bank_account','deadline_duration_seconds',
   'participant_capacity','waitlist_enabled','show_remaining_capacity','waitlist_offer_duration_seconds',
   'form_fields','deleted_field_ids','deleted_product_ids','settings']
  WHEN 'duplicate' THEN ARRAY['source_form_id','source_occasion_id','source_unit_id','locale']
  WHEN 'delete' THEN ARRAY['id','expected_aggregate_version']
 END;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE NOT k=ANY(allowed)) THEN
  RAISE invalid_parameter_value USING MESSAGE='unsupported form fields'; END IF;
 CASE p_action
 WHEN 'public_link' THEN
  IF jsonb_typeof(p_payload->'link') IS DISTINCT FROM 'string' THEN RAISE invalid_parameter_value USING MESSAGE='public slug required'; END IF;
  result:=public.update_form_client_sync_v1(p_payload||jsonb_build_object('occasion',p_occasion,'expected_product_versions','{}'::jsonb,'expected_product_type_versions','{}'::jsonb),p_command_id);
 WHEN 'create' THEN
  IF NOT p_payload ? 'title' OR jsonb_typeof(p_payload->'title')<>'string' OR length(p_payload->>'title')>500 THEN
   RAISE invalid_parameter_value USING MESSAGE='form title required'; END IF;
  result:=public.create_form_client_sync_v1(link,'',p_payload->>'title',p_command_id);
 WHEN 'save' THEN
  IF jsonb_typeof(p_payload->'expected_product_versions') IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_payload->'expected_product_type_versions') IS DISTINCT FROM 'object' THEN
   RAISE invalid_parameter_value USING MESSAGE='original product versions required'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_payload->'deleted_product_ids','[]')) id
    WHERE NOT (p_payload->'expected_product_versions') ? id) THEN
   RAISE invalid_parameter_value USING MESSAGE='deleted product baseline required'; END IF;
  -- The field transport can edit common definitions and reference a catalog
  -- type; inline product mutation remains in the existing aggregate UI owner.
  IF p_payload ? 'form_fields' AND (jsonb_typeof(p_payload->'form_fields')<>'array' OR
    EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'form_fields') f WHERE
      jsonb_typeof(f)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(f) k WHERE k NOT IN
       ('id','title','description','type','is_required','is_hidden','is_ticket_field','order','data','product_type_id','product_type')))) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid form fields'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_payload->'form_fields','[]')) f
    WHERE f ? 'data' AND f->'data'<>'null'::jsonb AND
     (jsonb_typeof(f->'data')<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(f->'data') k
       WHERE k NOT IN ('options','max_tickets','selection_type','default_value','label','is_group_feature','min_year','max_year','is_hard','message','show_expiry_date','expiry_date_label','show_surcharge_description')))) THEN
   RAISE invalid_parameter_value USING MESSAGE='unsupported field settings'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_payload->'form_fields','[]')) f
    WHERE f ? 'product_type' AND f ? 'product_type_id') THEN RAISE invalid_parameter_value USING MESSAGE='choose product reference or aggregate'; END IF;
  result:=public.update_form_client_sync_v1(p_payload||jsonb_build_object('occasion',p_occasion),p_command_id);
 WHEN 'duplicate' THEN
  source_id:=(p_payload->>'source_occasion_id')::bigint;
  PERFORM public.check_form_authoring_scope_internal(source_id,p_organization,(p_payload->>'source_unit_id')::bigint,'source');
  IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=(p_payload->>'source_form_id')::bigint AND occasion=source_id) THEN
   RAISE insufficient_privilege USING MESSAGE='foreign source form'; END IF;
  IF p_payload->>'locale' IS NULL OR p_payload->>'locale' NOT IN ('cs','en','sk','de','pl','uk') THEN
   RAISE invalid_parameter_value USING MESSAGE='copy locale required'; END IF;
  result:=public.duplicate_form_to_occasion_client_sync_v1((p_payload->>'source_form_id')::bigint,link,p_command_id,p_payload->>'locale');
  PERFORM public.check_form_authoring_scope_internal(source_id,p_organization,(p_payload->>'source_unit_id')::bigint,'source',true);
 WHEN 'delete' THEN
  result:=public.delete_form_client_sync_v1(form_id,p_command_id,(p_payload->>'expected_aggregate_version')::bigint);
 END CASE;
 PERFORM public.check_form_authoring_scope_internal(p_occasion,p_organization,p_unit,CASE WHEN p_action='public_link' THEN 'save' ELSE p_action END,true);
 IF (result->>'code')::int=200 THEN
  state:=result->'data'->'authoring';
  IF octet_length(state::text)>1048576 OR jsonb_array_length(state->'fields')>500 THEN
   RAISE program_limit_exceeded USING MESSAGE='form snapshot too large'; END IF;
  form_id:=coalesce((state->'form'->>'id')::bigint,form_id);
  RETURN result||jsonb_build_object('data',jsonb_build_object('occasionId',p_occasion,'formId',form_id,'authoring',state),
   'sync',jsonb_build_object('replacements','[]'::jsonb))
   ||CASE WHEN p_action='public_link' THEN jsonb_build_object('publicLink',jsonb_build_object('occasionId',p_occasion,'formId',form_id,'slug',result#>>'{data,link}')) ELSE '{}'::jsonb END;
 END IF;
 RETURN result||jsonb_build_object('data',jsonb_build_object('reason','FORM_COMMAND_REJECTED'),
   'sync',jsonb_build_object('replacements','[]'::jsonb));
END $$;


ALTER FUNCTION public.manage_form(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_game_settings(bigint, bigint, bigint, uuid, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_game_settings(p_occasion bigint, p_organization bigint, p_unit bigint, p_command_id uuid DEFAULT NULL::uuid, p_expected_version bigint DEFAULT NULL::bigint, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF p_command_id IS NULL THEN PERFORM 1 FROM public.occasions WHERE id=p_occasion FOR SHARE;
 ELSE PERFORM 1 FROM public.occasions WHERE id=p_occasion FOR UPDATE; END IF;
 IF auth.uid() IS NULL OR NOT public.can_edit_game_settings(p_occasion)
 OR NOT EXISTS(SELECT FROM public.occasions o JOIN public.user_info ui ON ui.id=auth.uid() AND ui.organization=o.organization WHERE o.id=p_occasion AND o.organization=p_organization AND (p_unit IS NULL OR o.unit=p_unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='game settings scope denied'; END IF;
 IF p_command_id IS NULL THEN RETURN public.get_game_settings_for_authoring_v1(p_occasion); END IF;
 RETURN public.game_update_settings_client_sync_v1(p_occasion,p_start,p_end,p_command_id,p_expected_version);
END $$;


ALTER FUNCTION public.manage_game_settings(p_occasion bigint, p_organization bigint, p_unit bigint, p_command_id uuid, p_expected_version bigint, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: manage_inventory(bigint, bigint, bigint, text, jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_inventory(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid, p_editor boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;entity_id bigint;pool_id bigint;expected bigint;entity jsonb;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('save_pool','delete_pool','save_resource','delete_resource')
  OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR p_editor IS NULL
  OR p_command_id IS NULL OR octet_length(p_payload::text)>1048576 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid inventory intention'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true);
 expected:=(p_payload->>'expectedVersion')::bigint;
 IF expected<0 THEN RAISE invalid_parameter_value USING MESSAGE='invalid inventory version'; END IF;
 IF p_action='save_pool' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('bundle','expectedVersion'))
   OR (p_payload#>>'{bundle,pool,occasion}')::bigint IS DISTINCT FROM p_occasion THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid pool intention'; END IF;
  pool_id:=(p_payload#>>'{bundle,pool,id}')::bigint;
 ELSIF p_action='save_resource' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('resource','expectedVersion')) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid resource intention'; END IF;
  entity_id:=(p_payload#>>'{resource,id}')::bigint;pool_id:=(p_payload#>>'{resource,inventory_pool}')::bigint;
  IF NOT EXISTS(SELECT 1 FROM public.inventory_pools WHERE id=pool_id AND occasion=p_occasion) THEN
   RAISE insufficient_privilege USING MESSAGE='inventory pool unavailable'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('id','expectedVersion'))
   OR p_payload->>'id' IS NULL OR expected IS NULL THEN
   RAISE invalid_parameter_value USING MESSAGE='original inventory id/version required'; END IF;
  entity_id:=(p_payload->>'id')::bigint;
  IF p_action='delete_pool' THEN pool_id:=entity_id; END IF;
 END IF;
 -- Reject an existing foreign entity before the domain owner locks dependencies.
 -- Missing deletes still reach the owner for durable unchanged/replay outcomes.
 PERFORM public.check_inventory_entity_scope_internal(p_occasion,pool_id,CASE WHEN p_action IN ('save_resource','delete_resource') THEN entity_id END);
 IF p_action='save_pool' THEN
  result:=public.save_inventory_pool_command_internal(p_occasion,p_command_id,expected,p_payload->'bundle',p_editor);
 ELSIF p_action='delete_pool' THEN
  result:=public.delete_inventory_pool_client_sync_v1(p_occasion,entity_id,p_command_id,expected);
 ELSIF p_action='save_resource' THEN
  result:=public.save_resource_client_sync_v1(p_occasion,p_command_id,expected,p_payload->'resource');
 ELSE
  result:=public.delete_resource_client_sync_v1(p_occasion,entity_id,p_command_id,expected);
 END IF;
 IF p_action='save_pool' THEN pool_id:=coalesce((result#>>'{data,bundle,pool,id}')::bigint,pool_id);
 ELSIF p_action='save_resource' THEN entity_id:=coalesce((result#>>'{data,resource,id}')::bigint,entity_id); END IF;
 PERFORM public.check_inventory_entity_scope_internal(p_occasion,pool_id,CASE WHEN p_action IN ('save_resource','delete_resource') THEN entity_id END);
 -- Includes receipt replay. A late scope failure rolls the entire intention back.
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT p_editor THEN
  IF p_action='save_resource' AND jsonb_typeof(result#>'{data,resource}')='object' THEN
   entity:=result#>'{data,resource}';
   result:=jsonb_set(result,'{data,resource}',jsonb_build_object('id',entity->'id','occasion',entity->'occasion',
    'inventory_pool',entity->'inventory_pool','title',entity->'title','capacity',entity->'capacity',
    'booking_rules',entity->'booking_rules','aggregate_version',entity->'aggregate_version'));
  END IF;
  result:=result-'sync';
 END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.manage_inventory(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid, p_editor boolean) OWNER TO postgres;

--
-- Name: manage_occasion_public_link(bigint, bigint, bigint, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_occasion_public_link(p_occasion bigint, p_organization bigint, p_unit bigint, p_command_id uuid DEFAULT NULL::uuid, p_expected_version bigint DEFAULT NULL::bigint, p_link text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 PERFORM public.check_configuration_scope_internal_v1('occasion',p_occasion,p_organization,p_unit,p_command_id IS NOT NULL);
 IF p_command_id IS NULL THEN
  PERFORM 1 FROM public.occasions WHERE id=p_occasion FOR SHARE;
  PERFORM public.check_configuration_scope_internal_v1('occasion',p_occasion,p_organization,p_unit,false);
  RETURN (SELECT jsonb_build_object('occasionId',o.id,'link',o.link,'aggregateVersion',COALESCE(v.version,0)) FROM public.occasions o LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion' AND v.scope_type='occasion' AND v.scope_id=o.id AND v.aggregate_id=o.id::text WHERE o.id=p_occasion);
 END IF;
 IF p_link IS NULL OR length(p_link)>128 OR p_link !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN RAISE invalid_parameter_value USING MESSAGE='invalid public link'; END IF;
 result:=public.save_occasion_client_sync_v1(p_occasion,p_command_id,p_expected_version,jsonb_build_object('id',p_occasion,'link',p_link));
 PERFORM public.check_configuration_scope_internal_v1('occasion',p_occasion,p_organization,p_unit,true);
 IF result#>'{data,occasion}' IS NOT NULL THEN
  result:=jsonb_set(result,'{data}',jsonb_build_object('occasionId',p_occasion,'link',result#>'{data,occasion,link}','aggregateVersion',result#>'{data,occasion,aggregate_version}'));
 END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.manage_occasion_public_link(p_occasion bigint, p_organization bigint, p_unit bigint, p_command_id uuid, p_expected_version bigint, p_link text) OWNER TO postgres;

--
-- Name: manage_occasion_setup_authoring(bigint, bigint, uuid, bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_occasion_setup_authoring(p_unit bigint, p_organization bigint, p_draft uuid, p_expected_revision bigint DEFAULT NULL::bigint, p_command_id uuid DEFAULT NULL::uuid, p_source_scopes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE draft public.occasion_setup_drafts; source bigint; binding jsonb; source_ids bigint[];
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 IF NOT public.can_create_occasion(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='setup author required'; END IF;
 SELECT * INTO draft FROM public.occasion_setup_drafts WHERE id=p_draft AND unit=p_unit AND organization=p_organization FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='setup draft unavailable'; END IF;
 IF p_command_id IS NULL THEN RETURN public.get_occasion_setup_draft(p_draft); END IF;
 IF draft.data ? 'finalizeResponse' THEN RETURN public.finalize_occasion_setup_draft(p_draft,p_expected_revision,p_command_id); END IF;
 source_ids:=ARRAY(SELECT DISTINCT x::bigint FROM unnest(ARRAY[draft.data->>'sourceId',draft.data->>'formSourceOccasionId',draft.data->>'blueprintSourceOccasionId']) x WHERE nullif(x,'') IS NOT NULL);
 IF jsonb_typeof(p_source_scopes) IS DISTINCT FROM 'array' OR jsonb_array_length(p_source_scopes)<>cardinality(source_ids) THEN RAISE insufficient_privilege USING MESSAGE='source consent required'; END IF;
 FOREACH source IN ARRAY source_ids LOOP
  SELECT x INTO binding FROM jsonb_array_elements(p_source_scopes) x WHERE (x->>'occasionId')::bigint=source;
  IF binding IS NULL THEN RAISE insufficient_privilege USING MESSAGE='source consent required'; END IF;
  PERFORM public.lock_people_scope_internal_v1(source,p_organization,(binding->>'unitId')::bigint);
  IF NOT public.can_copy_occasion_source(source) THEN RAISE insufficient_privilege USING MESSAGE='source read denied'; END IF;
 END LOOP;
 RETURN public.finalize_occasion_setup_draft(p_draft,p_expected_revision,p_command_id);
END $$;


ALTER FUNCTION public.manage_occasion_setup_authoring(p_unit bigint, p_organization bigint, p_draft uuid, p_expected_revision bigint, p_command_id uuid, p_source_scopes jsonb) OWNER TO postgres;

--
-- Name: manage_operator_order_v1(bigint, bigint, bigint, bigint, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_operator_order_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid, p_expected_revision text, p_action text, p_changes jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_order eshop.orders; v_pi eshop.payment_info; v_unit bigint; v_begin jsonb; v_hash text; v_child uuid;
 v_result jsonb; v_actions jsonb; v_item jsonb; v_products jsonb; v_message jsonb; v_users uuid[]; v_data jsonb;
BEGIN
 PERFORM public.check_operator_order_scope_internal_v1(p_occasion,p_organization,p_unit,true);
 IF p_action IS NULL OR p_expected_revision IS NULL OR p_action NOT IN('update','cancel','mark_paid','record_payment','send_tickets') OR p_expected_revision !~ '^[a-f0-9]{64}$'
   OR p_changes IS NULL OR jsonb_typeof(p_changes)<>'object' OR octet_length(p_changes::text)>65536 THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid order command'; END IF;
 IF p_action NOT IN('update','record_payment') AND p_changes<>'{}'::jsonb THEN RAISE invalid_parameter_value USING MESSAGE='unexpected order changes'; END IF;
 IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order unavailable'; END IF;
 v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('order',p_order,'occasion',p_occasion,'organization',p_organization,'unit',p_unit,'revision',p_expected_revision,'action',p_action,'changes',p_changes)::text,'UTF8'),'sha256'),'hex');
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 v_begin:=public.begin_client_mutation_v1(p_command_id,'orders.operator.'||p_action,p_occasion,auth.uid(),v_hash);
 IF v_begin->>'disposition'='replay' THEN RETURN jsonb_set(v_begin->'response','{mutation,replayed}','true'); END IF;
 -- Preserve the domain lock order, including form -> order and blueprint scope.
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 SELECT * INTO v_order FROM eshop.orders WHERE id=p_order AND occasion=p_occasion FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='order unavailable'; END IF;
 SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
 SELECT unit INTO v_unit FROM public.occasions WHERE id=p_occasion;
 IF public.operator_order_revision_internal_v1(p_order) IS DISTINCT FROM p_expected_revision THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('orderId',p_order,'reason','ORDER_CHANGED_RELOAD_REQUIRED')); END IF;
 v_actions:=public.get_order_allowed_actions_internal_v1(p_order);
 IF NOT (v_actions ? CASE p_action WHEN 'update' THEN CASE WHEN p_changes ? 'note' AND p_changes - 'note'='{}'::jsonb THEN 'note' ELSE 'edit' END WHEN 'cancel' THEN 'cancel' WHEN 'mark_paid' THEN 'paid' WHEN 'record_payment' THEN 'edit' ELSE 'send' END) THEN
   RAISE insufficient_privilege USING MESSAGE='order action unavailable'; END IF;
 v_child:=md5(p_command_id::text||':domain')::uuid;
 IF p_action='cancel' THEN
   v_result:=public.storno_order_client_sync_v1(p_order,v_child);
 ELSIF p_action='update' THEN
   IF p_changes - ARRAY['responses','note','tickets','paymentDeadline']::text[]<>'{}'::jsonb OR p_changes='{}' THEN RAISE invalid_parameter_value USING MESSAGE='invalid order changes'; END IF;
   IF p_changes ? 'paymentDeadline' THEN
     IF v_pi.id IS NULL OR public.payment_method_is_online_internal(v_pi.payment_method)
       OR jsonb_typeof(p_changes->'paymentDeadline') NOT IN ('null','string') THEN
       RAISE invalid_parameter_value USING MESSAGE='payment deadline unavailable'; END IF;
     PERFORM public.check_order_is_mutable(p_order);
     PERFORM public.set_payment_deadline(v_pi.id,(p_changes->>'paymentDeadline')::timestamptz);
     INSERT INTO eshop.orders_history("order",data,state,price,currency_code)
     VALUES(p_order,v_order.data||jsonb_build_object('payment',public.customer_order_payment_internal(p_order)),v_order.state,v_order.price,v_order.currency_code);
   END IF;
   IF p_changes ? 'responses' THEN PERFORM public.update_order_responses(p_order,p_changes->'responses'); END IF;
   IF p_changes ? 'note' THEN
     v_result:=public.update_order_note_hidden(p_order,p_changes->>'note');
     IF (v_result->>'code')::int<>200 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='order note rejected'; END IF;
   END IF;
   FOR v_item IN SELECT * FROM jsonb_array_elements(coalesce(p_changes->'tickets','[]')) LOOP
     IF NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE "order"=p_order AND ticket=(v_item->>'ticketId')::bigint) THEN RAISE insufficient_privilege USING MESSAGE='ticket unavailable'; END IF;
     SELECT coalesce(jsonb_agg(jsonb_build_object('id',x->'productId','price',x->'price')),'[]') INTO v_products FROM jsonb_array_elements(v_item->'products') x;
     v_result:=public.update_ticket_products_client_sync_v1((v_item->>'ticketId')::bigint,v_products,md5(p_command_id::text||':ticket:'||(v_item->>'ticketId'))::uuid);
     IF (v_result->>'code')::int<>200 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ticket products rejected'; END IF;
   END LOOP;
 ELSIF p_action='mark_paid' THEN
   v_result:=public.update_order_and_tickets_to_paid_ws(p_order);
   IF (v_result->>'code')::int<>200 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='payment state rejected'; END IF;
   v_result:=NULL;
 ELSIF p_action='record_payment' THEN
   IF NOT (p_changes ?& ARRAY['amount','currency','receivedAt']) OR p_changes - ARRAY['amount','currency','receivedAt','note']::text[]<>'{}'::jsonb
     OR jsonb_typeof(p_changes->'amount') IS DISTINCT FROM 'string' OR jsonb_typeof(p_changes->'currency') IS DISTINCT FROM 'string' OR jsonb_typeof(p_changes->'receivedAt') IS DISTINCT FROM 'string'
     OR v_pi.id IS NULL OR public.payment_method_is_online_internal(v_pi.payment_method) OR (p_changes->>'currency') IS DISTINCT FROM trim(v_order.currency_code)
     OR (p_changes->>'amount') !~ '^[0-9]{1,8}(\.[0-9]{1,2})?$' OR (p_changes->>'amount')::numeric<=0 THEN
     RAISE invalid_parameter_value USING MESSAGE='manual payment unavailable'; END IF;
   PERFORM public.insert_manual_transaction_internal_v1((p_changes->>'amount')::numeric,p_changes->>'currency',v_unit,v_pi.variable_symbol::text,
     (p_changes->>'receivedAt')::timestamptz,p_changes->>'note',v_pi.id);
 ELSIF p_action='send_tickets' THEN
   v_message:=public.enqueue_order_email('ORDER_TICKETS',jsonb_build_object('order_id',p_order,'requested_by',auth.uid()),p_organization,p_occasion,v_unit,now(),'operator:'||p_command_id);
 END IF;
 v_data:=jsonb_build_object('orderId',p_order,'occasionId',p_occasion,'revision',public.operator_order_revision_internal_v1(p_order))
   ||CASE WHEN v_message IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('delivery','queued','messageId',v_message->'message_id') END;
 IF v_result ? 'mutation' THEN
   IF (v_result->>'code')::int<>200 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='cancellation rejected'; END IF;
   v_result:=jsonb_set(v_result,'{data}',v_data);
   v_result:=jsonb_set(v_result,'{mutation,commandId}',to_jsonb(p_command_id));v_result:=jsonb_set(v_result,'{mutation,receiptId}',to_jsonb(p_command_id));
   RETURN public.finish_client_mutation_v1(p_command_id,v_result,(v_result#>>'{mutation,commitId}')::uuid);
 END IF;
 IF p_action='send_tickets' THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,v_data);
 END IF;
 SELECT coalesce(array_agg(DISTINCT "user"),'{}') INTO v_users FROM public.occasion_users WHERE occasion=p_occasion;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,p_occasion,'orders.operator.'||p_action,
   jsonb_build_array(jsonb_build_object('entityType','order','entityId',p_order,'operation','update','safeLabel','Order management','changedFields',jsonb_build_array(p_action))),v_users,v_data);
END $_$;


ALTER FUNCTION public.manage_operator_order_v1(p_occasion bigint, p_organization bigint, p_unit bigint, p_order bigint, p_command_id uuid, p_expected_revision text, p_action text, p_changes jsonb) OWNER TO postgres;

--
-- Name: manage_people(bigint, bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_people(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; payload jsonb:=coalesce(p_payload,'{}'); entity jsonb; usr uuid; gid bigint;
 lim int:=coalesce((p_payload->>'limit')::int,50); item jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF jsonb_typeof(payload)<>'object' OR octet_length(payload::text)>2097152 OR lim NOT BETWEEN 1 AND 100 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid people request'; END IF;
 IF p_action LIKE 'units.%' THEN
  IF p_occasion IS NOT NULL OR NOT public.can_manage_unit_users(p_unit) THEN
   RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  IF p_action='units.list' THEN
   SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."userId"),'[]'::jsonb)) INTO result FROM (
    SELECT uu."user" AS "userId",ui.name,ui.surname,coalesce(uu.is_manager,false) AS "isManager",
      coalesce(uu.is_editor,false) AS "isEditor",coalesce(v.version,0) AS "aggregateVersion",coalesce(uu.is_editor_view,false) AS "isEditorView"
    FROM public.unit_users uu JOIN public.user_info ui ON ui.id=uu."user"
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='unit_user' AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=uu."user"::text
    LEFT JOIN public.organization_users visibility ON visibility.organization=p_organization AND visibility."user"=uu."user"
    WHERE uu.unit=p_unit AND visibility.is_hidden IS NOT TRUE AND (payload->>'after' IS NULL OR uu."user">(payload->>'after')::uuid)
    ORDER BY uu."user" LIMIT lim) page;
   RETURN result;
  ELSIF p_action='units.create' THEN
   PERFORM public.prepare_profile_change_internal_v1('{}',jsonb_build_object('profileChange',(payload->'profile')-'email'));
   IF jsonb_typeof(payload#>'{profile,email}') IS DISTINCT FROM 'string' THEN RAISE invalid_parameter_value USING MESSAGE='email required'; END IF;
   RETURN public.save_unit_user_client_sync_v1(p_unit,NULL,p_command_id,NULL,jsonb_build_object('kind','editor','data',payload->'profile','is_manager',false,'is_editor',false,'is_editor_view',false));
  ELSIF p_action IN ('units.roles','units.profile') THEN
   RETURN public.save_unit_user_client_sync_v1(p_unit,(payload->>'userId')::uuid,p_command_id,(payload->>'expectedVersion')::bigint,
    (payload->'changes')||jsonb_build_object('kind',CASE WHEN p_action='units.roles' THEN 'roles' ELSE 'profile' END));
  ELSIF p_action='units.revoke' THEN
   RETURN public.delete_unit_user_client_sync_v1((payload->>'userId')::uuid,p_unit,p_command_id);
  END IF;
 ELSIF p_action LIKE 'profiles.%' THEN
  IF NOT public.can_manage_occasion_participants(p_occasion) THEN
   RAISE insufficient_privilege USING MESSAGE='participant manager required'; END IF;
  usr:=(payload->>'userId')::uuid;
  IF p_action='profiles.list' THEN
   SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."userId"),'[]'::jsonb)) INTO result FROM (
    SELECT ou."user" AS "userId",ui.name,ui.surname,coalesce(v.version,0) AS "aggregateVersion"
    FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user"
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=ou."user"::text
    WHERE ou.occasion=p_occasion AND (payload->>'after' IS NULL OR ou."user">(payload->>'after')::uuid)
    ORDER BY ou."user" LIMIT lim) page;
   RETURN result;
  ELSIF p_action='profiles.inspect' THEN
   PERFORM 1 FROM public.user_info WHERE id=usr FOR SHARE;
   PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=usr FOR SHARE;
   IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='participant unavailable'; END IF;
   SELECT public.people_profile_projection_internal_v1(public.get_occasion_user_command_data_v1(p_occasion,usr),coalesce(v.version,0)) INTO result
    FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=usr::text;
   RETURN result;
  ELSIF p_action IN ('profiles.save','profiles.roles') THEN
   result:=public.save_profile_client_sync_v1(p_occasion,usr,p_command_id,(payload->>'expectedVersion')::bigint,
    jsonb_build_object('occasion',p_occasion,'user',usr,CASE WHEN p_action='profiles.roles' THEN 'roleChange' ELSE 'profileChange' END,payload->'changes'));
  ELSIF p_action='profiles.create' THEN
   PERFORM public.prepare_profile_change_internal_v1('{}',jsonb_build_object('profileChange',(payload->'profile')-'email'));
   IF jsonb_typeof(payload#>'{profile,email}') IS DISTINCT FROM 'string' THEN RAISE invalid_parameter_value USING MESSAGE='email required'; END IF;
   result:=public.create_occasion_user_client_sync_v1(p_occasion,p_command_id,jsonb_build_object('occasion',p_occasion,'data',payload->'profile'));
  ELSIF p_action='profiles.delete' THEN
   result:=public.delete_occasion_user_client_sync_v1(p_occasion,usr,p_command_id,(payload->>'expectedVersion')::bigint);
  ELSIF p_action='profiles.importTickets' THEN
   result:=public.import_users_from_tickets_client_sync_v1(p_occasion,p_command_id);
  ELSIF p_action='profiles.import' THEN
   IF jsonb_typeof(payload->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'rows')>100 THEN RAISE invalid_parameter_value USING MESSAGE='bounded import required'; END IF;
   FOR item IN SELECT * FROM jsonb_array_elements(payload->'rows') LOOP
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(item) k WHERE k NOT IN ('user_id','data')) THEN RAISE invalid_parameter_value USING MESSAGE='ordinary import fields required'; END IF;
    PERFORM public.prepare_profile_change_internal_v1('{}',jsonb_build_object('profileChange',(item->'data')-'email'));
   END LOOP;
   result:=public.import_profiles_client_sync_v1(p_occasion,p_command_id,payload->'rows','[]');
  END IF;
  -- Project the immutable stored response, never reread the mutated entity after replay.
  IF result#>'{data,profile}' IS NOT NULL AND result#>'{data,profile}'<>'null'::jsonb THEN
   entity:=public.people_profile_projection_internal_v1(result#>'{data,profile}',(result#>>'{data,version}')::bigint);
   result:=jsonb_set(result,'{data}',jsonb_build_object('profile',entity,'version',result#>'{data,version}'));
  END IF;
  IF result IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='unsupported people operation'; END IF;
  RETURN result;
 ELSIF p_action LIKE 'groups.%' THEN
  gid:=(payload->>'groupId')::bigint;
  IF gid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_group_info WHERE id=gid AND occasion=p_occasion) THEN
   RAISE insufficient_privilege USING MESSAGE='group unavailable'; END IF;
  IF p_action='groups.list' THEN
   IF NOT public.can_read_groups_editor(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='group reader required'; END IF;
   SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."groupId"),'[]'::jsonb)) INTO result FROM (
    SELECT g.id AS "groupId",g.title,g.description,g.type,g.place AS "placeId",coalesce(v.version,0) AS "aggregateVersion"
    FROM public.user_group_info g LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='user_group' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=g.id::text
    WHERE g.occasion=p_occasion AND (payload->>'after' IS NULL OR g.id>(payload->>'after')::bigint)
    ORDER BY g.id LIMIT lim) page;
   RETURN result;
  ELSIF p_action='groups.inspect' THEN
   PERFORM 1 FROM public.user_group_info WHERE id=gid AND occasion=p_occasion FOR SHARE;
   IF NOT public.can_read_group_editor(p_occasion,gid) THEN RAISE insufficient_privilege USING MESSAGE='group reader required'; END IF;
   IF (SELECT count(*) FROM public.user_groups WHERE "group"=gid)>500 THEN RAISE invalid_parameter_value USING MESSAGE='group exceeds authoring limit'; END IF;
   result:=public.get_user_group_command_data_v1(gid);
   RETURN jsonb_build_object('groupId',gid,'title',result->'title','description',result->'description','type',result->'type','placeId',result->'place','aggregateVersion',result->'aggregate_version',
    'participants',(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',x->'userId','is_admin',x->'isAdmin')),'[]'::jsonb) FROM jsonb_array_elements(result->'participants') x));
  ELSIF p_action='groups.save' THEN
   IF jsonb_typeof(payload->'group') IS DISTINCT FROM 'object' OR (payload->'group') ?| ARRAY['id','privatePlace','data'] THEN RAISE invalid_parameter_value USING MESSAGE='explicit group fields required'; END IF;
   result:=public.save_user_group_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,(payload->'group')||CASE WHEN gid IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('id',gid) END);
  ELSIF p_action='groups.delete' THEN
   result:=public.delete_user_group_client_sync_v1(p_occasion,gid,p_command_id,(payload->>'expectedVersion')::bigint);
  ELSIF p_action='groups.addMembers' THEN
   result:=public.add_user_group_members_client_sync_v1(p_occasion,gid,ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(payload->'userIds')),p_command_id);
  ELSIF p_action='groups.replaceAssignments' THEN
   result:=public.replace_group_assignments_client_sync_v1(p_occasion,p_command_id,payload->'assignments');
  END IF;
  -- Mutation summaries expose no editor bundle or unrelated member profile data.
  IF result IS NOT NULL THEN RETURN jsonb_set(result,'{data}',(coalesce(result->'data','{}')-'group')||CASE WHEN result#>>'{data,group,id}' IS NOT NULL THEN jsonb_build_object('groupId',result#>'{data,group,id}') ELSE '{}'::jsonb END); END IF;
 END IF;
 IF result IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='unsupported people operation'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.manage_people(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_product(bigint, bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_product(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_product jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint; product_id bigint; receipt_name text; result jsonb;
BEGIN
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true);
 IF p_action IS NULL OR p_action NOT IN ('save','delete','contexts') OR p_product IS NULL
  OR jsonb_typeof(p_product)<>'object' OR octet_length(p_product::text)>524288 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid product command'; END IF;
 product_id:=NULLIF(p_product->>'id','')::bigint;
 receipt_name:=CASE p_action WHEN 'save' THEN 'inventory.product.save' WHEN 'delete' THEN 'inventory.product.delete' ELSE 'inventory.product.contexts' END;
 -- Retained receipt is the authoritative occasion after a successful deletion.
 SELECT occasion INTO oc FROM public.client_mutation_receipts
  WHERE command_id=p_command_id AND actor_id=auth.uid() AND command_name=receipt_name;
 IF NOT FOUND THEN
  IF product_id IS NOT NULL THEN SELECT p.occasion INTO oc FROM eshop.products p WHERE p.id=product_id;
  ELSIF p_action='save' THEN SELECT pt.occasion INTO oc FROM eshop.product_types pt WHERE pt.id=(p_product->>'product_type')::bigint;
  END IF;
 END IF;
 IF oc IS DISTINCT FROM p_occasion OR (p_product->>'occasion' IS NOT NULL AND (p_product->>'occasion')::bigint IS DISTINCT FROM p_occasion)
  OR (p_product->>'product_type' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.product_types pt WHERE pt.id=(p_product->>'product_type')::bigint AND pt.occasion=p_occasion)) THEN
  RAISE insufficient_privilege USING MESSAGE='product unavailable'; END IF;
 IF product_id IS NOT NULL AND (p_product->>'expected_aggregate_version' IS NULL
   OR (p_product->>'expected_aggregate_version')::bigint<0) THEN
  RAISE invalid_parameter_value USING MESSAGE='original product version required'; END IF;
 IF p_action='save' THEN
  result:=public.update_product_client_sync_v1(p_product,p_command_id);
 ELSIF p_action='delete' THEN
  result:=public.delete_product_client_sync_v1(product_id,p_command_id,(p_product->>'expected_aggregate_version')::bigint);
 ELSE
  result:=public.update_product_inventory_contexts_client_sync_v1(product_id,
   jsonb_build_object('expected_aggregate_version',p_product->'expected_aggregate_version','contexts',p_product->'inventory_contexts'),p_command_id);
 END IF;
 -- Validate and lock the live tenant/organizer after domain locking, including
 -- receipt replay. A concurrent move or rights change rolls back ALL effects.
 -- Do not acquire organizer locks before the canonical receipt/order locks.
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 RETURN result;
END $$;


ALTER FUNCTION public.manage_product(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_product jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_product_schedule(bigint, bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_product_schedule(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; started jsonb; hash text; command_name text; link text;
 wave jsonb; change jsonb; wave_id bigint; product_id bigint; allowed text[]; fields text[]; users uuid[]; constraint_name text;
BEGIN
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true);
 IF p_action IS NULL OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>8192 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid product schedule'; END IF;
 CASE p_action
 WHEN 'save_target' THEN
  allowed:=ARRAY['product_id','wave_id','change_time','expected_wave_revision','price','is_hidden','expected_price_revision','expected_visibility_revision'];
  fields:=ARRAY['product_id','price','is_hidden','expected_price_revision','expected_visibility_revision'];
 WHEN 'ensure_wave' THEN allowed:=ARRAY['change_time'];fields:=allowed;
 WHEN 'move_wave' THEN allowed:=ARRAY['wave_id','expected_wave_revision','change_time'];fields:=allowed;
 WHEN 'cancel_wave' THEN allowed:=ARRAY['wave_id','expected_wave_revision'];fields:=allowed;
 WHEN 'save_price_change' THEN allowed:=ARRAY['product_id','price','change_time','change_id','expected_revision'];fields:=ARRAY['product_id','price','change_time'];
 WHEN 'cancel_price_change' THEN allowed:=ARRAY['product_id','change_id','expected_revision'];fields:=allowed;
 ELSE RAISE invalid_parameter_value USING MESSAGE='invalid product schedule action';
 END CASE;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE NOT k=ANY(allowed)) OR NOT p_payload ?& fields THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid product schedule fields'; END IF;
 SELECT o.link INTO link FROM public.occasions o WHERE o.id=p_occasion;
 IF p_action='save_target' THEN
  result:=public.save_product_wave_target_client_sync_v1(p_payload||jsonb_build_object('occasion_link',link),p_command_id);
 ELSE
  command_name:='inventory.schedule.'||p_action;
  hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'action',p_action,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');
  started:=public.begin_client_mutation_v1(p_command_id,command_name,p_occasion,auth.uid(),hash);
  IF started->>'disposition'='replay' THEN
   result:=started->'response';
  ELSE
   BEGIN
    wave_id:=(p_payload->>'wave_id')::bigint;
    product_id:=(p_payload->>'product_id')::bigint;
    -- Lock the actual aggregate after its receipt, in the owner's lock order.
    -- Scope is checked on the locked row, not an earlier Node lookup.
    IF wave_id IS NOT NULL THEN
     PERFORM 1 FROM eshop.product_price_waves WHERE id=wave_id AND occasion=p_occasion FOR UPDATE;
     IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='wave unavailable'; END IF;
    END IF;
    IF product_id IS NOT NULL THEN
     PERFORM 1 FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
      WHERE p.id=product_id AND p.occasion=p_occasion AND pt.occasion=p_occasion FOR UPDATE OF p;
     IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='product unavailable'; END IF;
    END IF;
    CASE p_action
    WHEN 'ensure_wave' THEN
     wave:=public.create_product_price_wave(link,(p_payload->>'change_time')::timestamptz);wave_id:=(wave->>'id')::bigint;
    WHEN 'move_wave' THEN
     wave:=public.move_product_price_wave(wave_id,(p_payload->>'expected_wave_revision')::bigint,(p_payload->>'change_time')::timestamptz);
    WHEN 'cancel_wave' THEN
     PERFORM public.cancel_product_price_wave(wave_id,(p_payload->>'expected_wave_revision')::bigint);
    WHEN 'save_price_change' THEN
     change:=public.save_product_price_change(product_id,(p_payload->>'price')::numeric,(p_payload->>'change_time')::timestamptz,
      (p_payload->>'change_id')::bigint,(p_payload->>'expected_revision')::bigint);
    WHEN 'cancel_price_change' THEN
     PERFORM public.cancel_product_price_change(product_id,(p_payload->>'change_id')::bigint,(p_payload->>'expected_revision')::bigint);
    END CASE;
    -- The existing complete owner publishes one sync/audit receipt. No provider,
    -- mail, historical order price or paid transition is performed here.
    result:=public.complete_private_inventory_mutation_v1(p_command_id,p_occasion,command_name,
     jsonb_build_array(jsonb_build_object('entityType',CASE WHEN wave_id IS NULL THEN 'product' ELSE 'product_price_wave' END,
      'entityId',coalesce(wave_id,product_id),'operation',CASE WHEN p_action LIKE 'cancel%' THEN 'delete' ELSE 'update' END,
      'safeLabel','Product schedule','changedFields',jsonb_build_array('planned_changes'))),'{}'::uuid[],
     jsonb_build_object('waveId',wave_id,'productId',product_id,'wave',wave,'change',change,'targets','[]'::jsonb));
   EXCEPTION WHEN serialization_failure THEN
    IF SQLERRM<>'PRICE_CHANGE_CONFLICT' THEN RAISE; END IF;
    result:=public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','PRICE_CHANGE_CONFLICT'));
   WHEN invalid_parameter_value THEN
    IF SQLERRM NOT IN ('FUTURE_TIME_REQUIRED','INVALID_PRODUCT_PRICE','DEPOSIT_AMOUNT_TOO_HIGH','BLUEPRINT_PRODUCT_VISIBILITY_NOT_SUPPORTED','WAVE_ALREADY_APPLIED','INVALID_REVISION') THEN RAISE; END IF;
    result:=public.complete_client_mutation_outcome_v1(p_command_id,'rejected',422,jsonb_build_object('reason',SQLERRM));
   WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS constraint_name=CONSTRAINT_NAME;
    IF constraint_name<>'product_price_waves_occasion_change_time_key' THEN RAISE; END IF;
    result:=public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','PRICE_CHANGE_CONFLICT'));
   END;
  END IF;
 END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 RETURN result;
END $$;


ALTER FUNCTION public.manage_product_schedule(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_program_authoring(bigint, bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_program_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE domain text:=split_part(p_action,'.',1); verb text:=split_part(p_action,'.',2);
 entity bigint:=(p_payload->>'entityId')::bigint; lim int:=coalesce((p_payload->>'limit')::int,50);
 result jsonb; graph jsonb; draft public.activity_history%ROWTYPE; history jsonb; version bigint; payload jsonb:=coalesce(p_payload,'{}');
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 PERFORM public.require_program_domain_internal_v1(p_occasion,domain,p_command_id IS NOT NULL);
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' OR octet_length(payload::text)>4194304 OR lim NOT BETWEEN 1 AND 100 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid program request'; END IF;
 IF domain='events' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.events x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='events' AND verb='inspect' THEN
  PERFORM 1 FROM public.events WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',public.get_event_command_data_v1(x.id)) INTO result
   FROM public.events x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='exclusiveGroups' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.exclusive_groups x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='exclusive_group' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='exclusiveGroups' AND verb='inspect' THEN
  PERFORM 1 FROM public.exclusive_groups WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',public.get_exclusive_group_command_data_v1(x.id)) INTO result
   FROM public.exclusive_groups x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='exclusive_group' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='places' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.places x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='places' AND verb='inspect' THEN
  PERFORM 1 FROM public.places WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',to_jsonb(x)) INTO result
   FROM public.places x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='placeTypes' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.place_types x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place_type' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='placeTypes' AND verb='inspect' THEN
  PERFORM 1 FROM public.place_types WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',to_jsonb(x)) INTO result
   FROM public.place_types x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place_type' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='paths' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.path_groups x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='path' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='paths' AND verb='inspect' THEN
  PERFORM 1 FROM public.path_groups WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',to_jsonb(x)) INTO result
   FROM public.path_groups x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='path' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='speakers' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.speakers x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='speakers' AND verb='inspect' THEN
  PERFORM 1 FROM public.speakers WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',public.get_speaker_command_data_v1(x.id)) INTO result
   FROM public.speakers x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='topics' AND verb='list' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT x.id,x.title,coalesce(v.version,0) AS "aggregateVersion" FROM public.speaker_topics x
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker_topic' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.occasion=p_occasion AND (payload->>'after' IS NULL OR x.id>(payload->>'after')::bigint) ORDER BY x.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='topics' AND verb='inspect' THEN
  PERFORM 1 FROM public.speaker_topics WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='program entity outside scope'; END IF;
  SELECT jsonb_build_object('entityId',x.id,'aggregateVersion',coalesce(v.version,0),'entity',to_jsonb(x)) INTO result
   FROM public.speaker_topics x LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker_topic' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=x.id::text
   WHERE x.id=entity AND x.occasion=p_occasion;
  RETURN result;
 END IF;
 IF domain='places' AND verb='icons' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT i.id,i.data,i.link,i.unit FROM public.icons i JOIN public.occasions o ON o.id=p_occasion
   WHERE i.organization=o.organization AND (i.unit IS NULL OR i.unit=o.unit) AND (payload->>'after' IS NULL OR i.id>(payload->>'after')::bigint) ORDER BY i.id LIMIT lim) page;
  RETURN result;
 ELSIF domain='events' AND verb='roles' THEN
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT id,title FROM public.role_info WHERE occasion=p_occasion AND (payload->>'after' IS NULL OR id>(payload->>'after')::bigint) ORDER BY id LIMIT lim) page;
  RETURN result;
 ELSIF domain='eventSpeakers' AND verb='inspect' THEN
  PERFORM 1 FROM public.events WHERE id=entity AND occasion=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='event outside scope'; END IF;
  SELECT jsonb_build_object('entityId',entity,'aggregateVersion',coalesce(v.version,0),'speakerIds',coalesce((SELECT jsonb_agg(speaker ORDER BY speaker) FROM public.event_speakers WHERE event=entity),'[]'::jsonb)) INTO result
   FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=entity::text;
  RETURN result;
 ELSIF domain='counseling' AND verb='list' THEN
  IF NOT EXISTS(SELECT 1 FROM public.speakers WHERE id=entity AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='speaker outside scope'; END IF;
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb)) INTO result FROM (
   SELECT e.id,e.title,e.start_time,e.end_time,e.type,coalesce(v.version,0) AS "aggregateVersion" FROM public.events e JOIN public.event_speakers es ON es.event=e.id
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND es.speaker=entity AND (payload->>'after' IS NULL OR e.id>(payload->>'after')::bigint) ORDER BY e.id LIMIT lim) page;
  RETURN result;
 END IF;
 IF domain='services' AND verb='list' THEN
  IF payload->>'type' NOT IN ('food','accommodation') THEN RAISE invalid_parameter_value USING MESSAGE='service family required'; END IF;
  SELECT jsonb_build_object('items',coalesce(jsonb_agg(item ORDER BY item->>'code'),'[]'::jsonb)) INTO result FROM (
   SELECT item FROM public.occasions o CROSS JOIN LATERAL jsonb_array_elements(coalesce(o.services->(payload->>'type'),'[]')) item
   WHERE o.id=p_occasion AND (payload->>'after' IS NULL OR item->>'code'>payload->>'after') ORDER BY item->>'code' LIMIT lim) page;
  RETURN result;
 ELSIF domain='activities' AND verb='inspect' THEN
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  SELECT * INTO draft FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=auth.uid() AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
  graph:=public.current_activity_graph_internal_v1(p_occasion);
  result:=jsonb_build_object('aggregateVersion',coalesce((SELECT v.version FROM public.client_aggregate_versions v WHERE v.aggregate_type='activities' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p_occasion::text),0),
   'latestPublishId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1),
   'draftId',draft.id,'draftParentHistoryId',draft.parent_history_id,'graph',graph,'draftGraph',CASE WHEN draft.id IS NULL THEN NULL ELSE public.activity_history_graph_internal_v1(p_occasion,draft.activities_data,false) END);
  IF octet_length(result::text)>4194304 THEN RAISE program_limit_exceeded USING MESSAGE='activity aggregate exceeds authoring limit'; END IF;
  RETURN result;
 END IF;
 IF p_command_id IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='explicit program command identity required'; END IF;
 -- Scope-bind referenced resources before invoking a command which accepts an ID.
 IF domain IN ('attendance','eventSpeakers') AND NOT EXISTS(SELECT 1 FROM public.events WHERE id=entity AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='event outside scope'; END IF;
 IF domain='counseling' AND NOT EXISTS(SELECT 1 FROM public.speakers WHERE id=entity AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='speaker outside scope'; END IF;
 IF p_action='events.save' THEN result:=public.save_event_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='events.delete' THEN result:=public.delete_event_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='attendance.set' THEN result:=public.set_event_attendance_client_sync_v1(entity,(payload->>'participantId')::uuid,payload->>'action',p_command_id);
 ELSIF p_action='exclusiveGroups.save' THEN result:=public.save_exclusive_group_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='exclusiveGroups.delete' THEN result:=public.delete_exclusive_group_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='places.save' THEN result:=public.save_place_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='places.delete' THEN result:=public.delete_place_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='places.move' THEN result:=public.move_place_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint,(payload->>'lat')::double precision,(payload->>'lng')::double precision);
 ELSIF p_action='placeTypes.save' THEN result:=public.save_place_type_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='placeTypes.delete' THEN result:=public.delete_place_type_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='paths.save' THEN result:=public.save_path_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='paths.delete' THEN result:=public.delete_path_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='speakers.save' THEN result:=public.save_speaker_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='speakers.delete' THEN result:=public.delete_speaker_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='topics.save' THEN result:=public.save_speaker_topic_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'entity');
 ELSIF p_action='topics.delete' THEN result:=public.delete_speaker_topic_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='eventSpeakers.save' THEN result:=public.save_event_speakers_client_sync_v1(p_occasion,entity,p_command_id,(payload->>'expectedVersion')::bigint,ARRAY(SELECT value::bigint FROM jsonb_array_elements_text(payload->'speakerIds')));
 ELSIF p_action='counseling.createSlots' THEN result:=public.create_counseling_slots_client_sync_v1(entity,(payload->>'start')::timestamptz,(payload->>'end')::timestamptz,(payload->>'slotMinutes')::int,(payload->>'placeId')::bigint,(payload->>'capacity')::int,payload->>'title',(payload->>'breakMinutes')::int,p_command_id);
 ELSIF p_action='counseling.deleteEmptySlots' THEN result:=public.delete_empty_counseling_slots_client_sync_v1(entity,(payload->>'from')::timestamptz,p_command_id);
 ELSIF p_action='counseling.deleteSlot' THEN result:=public.delete_counseling_slot_client_sync_v1(entity,(payload->>'eventId')::bigint,p_command_id,(payload->>'expectedVersion')::bigint);
 ELSIF p_action='services.create' THEN result:=public.create_service_item_client_sync_v1(p_occasion,payload->>'type',payload->>'code',payload->>'title',(payload->>'reference')::bigint,p_command_id);
 ELSIF p_action='services.update' THEN result:=public.update_service_item_client_sync_v1(p_occasion,payload->>'type',payload->>'code',payload->>'title',(payload->>'reference')::bigint,p_command_id);
 ELSIF p_action='services.delete' THEN result:=public.delete_service_item_client_sync_v1(p_occasion,payload->>'type',payload->>'code',(payload->>'force')::boolean,p_command_id);
 ELSIF p_action='activities.saveDraft' THEN result:=public.save_activity_draft_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,public.activity_graph_history_internal_v1(payload->'graph'),(payload->>'parentHistoryId')::bigint);
 ELSIF p_action='activities.discardDraft' THEN result:=public.discard_activity_draft_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedDraftId')::bigint);
 ELSIF p_action='activities.publish' THEN result:=public.publish_activities_client_sync_v1(p_occasion,p_command_id,(payload->>'expectedVersion')::bigint,payload->'graph',public.activity_graph_history_internal_v1(payload->'graph'),(payload->>'parentHistoryId')::bigint);
 ELSE RAISE invalid_parameter_value USING MESSAGE='unsupported program command'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.manage_program_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: manage_scanner_authoring(bigint, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_scanner_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE cfg public.scanner_settings%ROWTYPE; projection jsonb; prior public.scanner_operations%ROWTYPE;
 session_data jsonb; session_id uuid; session_token text; op jsonb; expected jsonb; result jsonb; op_id uuid;
 ticket bigint:=(p_payload->>'ticketId')::bigint;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 PERFORM public.scanner_require_settings_editor_internal(p_occasion);
 IF ticket IS NULL OR NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=ticket AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket outside scanner scope'; END IF;
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=p_occasion FOR SHARE;
 IF cfg.occasion_id IS NULL THEN cfg.config:=public.scanner_default_settings_internal(p_occasion);cfg.revision:=1; END IF;
 IF p_action='inspect' THEN
  SELECT dto INTO projection FROM public.scanner_ticket_projection_internal(p_occasion,cfg.config,ticket);
  IF projection IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='issued ticket required'; END IF;
  RETURN jsonb_build_object('ticketId',ticket,'state',projection->'state','settingsRevision',cfg.revision,
   'admissionAllowed',coalesce(projection->'admission_allowed','false'),'requiresUnpaidConfirmation',coalesce(projection->'requires_unpaid_confirmation','false'),
   'eligibilityFingerprint',projection->'eligibility_fingerprint');
 END IF;
 IF p_action<>'admit' OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('ticketId','operationId','eligibilityFingerprint','settingsRevision','confirmUnpaid','capturedAt'))
  OR (p_payload->>'eligibilityFingerprint') !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(p_payload->'confirmUnpaid') IS DISTINCT FROM 'boolean' THEN
  RAISE invalid_parameter_value USING MESSAGE='exact scanner intent required'; END IF;
 op_id:=(p_payload->>'operationId')::uuid;
 PERFORM (p_payload->>'capturedAt')::timestamptz;
 IF op_id IS NULL OR p_payload->>'capturedAt' IS NULL OR p_payload->>'settingsRevision' IS NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='scanner identity/baseline required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(op_id::text,5317));
 SELECT * INTO prior FROM public.scanner_operations WHERE operation_id=op_id;
 IF prior.operation_id IS NOT NULL THEN
  IF prior.occasion_id IS DISTINCT FROM p_occasion OR NOT EXISTS(SELECT 1 FROM public.scanner_sessions WHERE id=prior.session_id AND actor_user_id=auth.uid()) THEN
   RAISE insufficient_privilege USING MESSAGE='scanner receipt actor mismatch'; END IF;
  session_id:=prior.session_id;
 ELSE
  session_data:=public.open_scanner_session(NULL,p_occasion,'MCP confirmed admission');
  IF (session_data->>'code')::int<>200 THEN RETURN session_data; END IF;
  session_id:=(session_data#>>'{data,session_id}')::uuid;session_token:=session_data#>>'{data,token}';
 END IF;
 op:=jsonb_build_object('operation_id',op_id,'origin_session_id',session_id,'occasion_id',p_occasion,'ticket_id',ticket,'action','admit_ticket',
  'snapshot_id',NULL,'settings_revision',p_payload->'settingsRevision','eligibility_fingerprint',p_payload->'eligibilityFingerprint',
  'confirm_unpaid',p_payload->'confirmUnpaid','captured_at',p_payload->'capturedAt');
 IF prior.operation_id IS NOT NULL THEN
  IF prior.payload IS DISTINCT FROM op THEN RAISE invalid_parameter_value USING MESSAGE='scanner receipt payload mismatch'; END IF;
  RETURN jsonb_build_object('code',200,'data',jsonb_build_array(prior.receipt||jsonb_build_object('replayed',true)));
 END IF;
 result:=public.sync_scanner_operations(session_id,session_token,jsonb_build_array(op));
 PERFORM public.revoke_scanner_session(session_id,session_token);
 RETURN result;
END $_$;


ALTER FUNCTION public.manage_scanner_authoring(p_occasion bigint, p_organization bigint, p_unit bigint, p_action text, p_payload jsonb) OWNER TO postgres;

--
-- Name: manage_unit_agenda(bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_unit_agenda(p_unit bigint, p_organization bigint, p_action text, p_payload jsonb, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; begun jsonb; hash text; lim int:=coalesce((p_payload->>'limit')::int,50);
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,p_organization,p_unit);
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>786432 OR lim NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid organizer agenda'; END IF;
 IF p_action='quotes.list' THEN
  IF NOT public.can_read_unit_information(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit information reader required'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]') INTO result FROM (
   SELECT i.id,i.title,i.description,i.type,i.is_hidden AS "isHidden",i."order",i.data,coalesce(v.version,0) AS "aggregateVersion"
   FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information' AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=i.id::text
   WHERE i.unit=p_unit AND i.occasion IS NULL AND i.information_hidden IS NULL AND i.type='quote' AND (p_payload->>'after' IS NULL OR i.id>(p_payload->>'after')::bigint) ORDER BY i.id LIMIT lim) page;
  RETURN jsonb_build_object('items',result);
 ELSIF p_action IN ('quotes.save','quotes.delete') THEN
  IF p_action='quotes.save' THEN
   IF p_payload#>>'{quote,type}' IS DISTINCT FROM 'quote' THEN RAISE invalid_parameter_value USING MESSAGE='quote type required'; END IF;
   IF p_payload#>>'{quote,id}' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.information WHERE id=(p_payload#>>'{quote,id}')::bigint AND unit=p_unit AND occasion IS NULL AND type='quote') THEN RAISE insufficient_privilege USING MESSAGE='quote unavailable'; END IF;
   RETURN public.save_unit_information_client_sync_v1(p_unit,p_command_id,(p_payload->>'expectedVersion')::bigint,p_payload->'quote');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.information WHERE id=(p_payload->>'quoteId')::bigint AND unit=p_unit AND occasion IS NULL AND type='quote') THEN
   -- The original owner must still be able to return a receipt after deletion.
   IF NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid() AND unit=p_unit AND command_name='unit.information.delete') THEN RAISE insufficient_privilege USING MESSAGE='quote unavailable'; END IF;
  END IF;
  RETURN public.delete_unit_information_client_sync_v1(p_unit,(p_payload->>'quoteId')::bigint,p_command_id,(p_payload->>'expectedVersion')::bigint);
 ELSIF p_action='legal.inspect' THEN
  result:=public.get_unit_legal_profile(p_unit);
  RETURN jsonb_set(result,'{profile}',(result->'profile')-ARRAY['reviewNote','reviewSource']);
 ELSIF p_action IN ('legal.save','legal.submit') THEN
  IF NOT public.can_manage_unit_legal_profile(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit legal manager required'; END IF;
  hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit,'action',p_action,'payload',p_payload)::text,'sha256'),'hex');
  begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.'||p_action,p_unit,auth.uid(),hash);
  IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
  result:=CASE WHEN p_action='legal.save' THEN public.save_unit_legal_profile(p_unit,(p_payload->>'expectedRevision')::bigint,p_payload->'profile')
   ELSE public.submit_unit_verification(p_unit,(p_payload->>'expectedRevision')::bigint) END;
  IF result ? 'profile' THEN result:=jsonb_set(result,'{profile}',(result->'profile')-ARRAY['reviewNote','reviewSource']); END IF;
  IF result->>'code'<>'200' THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,CASE WHEN result->>'code'='409' THEN 'conflict' ELSE 'rejected' END,(result->>'code')::int,result); END IF;
  RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.'||p_action,'unit_legal_profile',p_unit,'update',result);
 END IF;
 RAISE invalid_parameter_value USING MESSAGE='unsupported organizer agenda';
END $$;


ALTER FUNCTION public.manage_unit_agenda(p_unit bigint, p_organization bigint, p_action text, p_payload jsonb, p_command_id uuid) OWNER TO postgres;

