--
-- Name: mark_app_links_sent(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_app_links_sent(p_occasion_id bigint, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_already_sent boolean;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'Service role required'
        );
    END IF;

    SELECT COALESCE(ou.data->>'app_links_sent' = 'true', false)
      INTO v_already_sent
      FROM public.occasion_users ou
     WHERE ou.occasion = p_occasion_id
       AND ou."user" = p_user_id
     FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion user not found');
    END IF;

    IF v_already_sent THEN
        RETURN jsonb_build_object(
            'code', 200,
            'message', 'Application links already marked as sent'
        );
    END IF;

    UPDATE public.occasion_users
       SET data = jsonb_set(
           COALESCE(data, '{}'::jsonb),
           '{app_links_sent}',
           'true'::jsonb,
           true
       )
     WHERE occasion = p_occasion_id
       AND "user" = p_user_id;

    INSERT INTO public.client_aggregate_versions
        (aggregate_type, scope_type, scope_id, aggregate_id, version)
    VALUES
        ('occasion_user', 'occasion', p_occasion_id, p_user_id::text, 0)
    ON CONFLICT DO NOTHING;

    UPDATE public.client_aggregate_versions
       SET version = version + 1,
           updated_at = clock_timestamp()
     WHERE aggregate_type = 'occasion_user'
       AND scope_type = 'occasion'
       AND scope_id = p_occasion_id
       AND aggregate_id = p_user_id::text;

    RETURN jsonb_build_object('code', 200, 'message', 'Application links marked as sent');
END;
$$;


ALTER FUNCTION public.mark_app_links_sent(p_occasion_id bigint, p_user_id uuid) OWNER TO postgres;

--
-- Name: mark_news_read_client_sync_v1(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_news_read_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid:=auth.uid();
  v_revision bigint;
  v_begin jsonb;
  v_commit jsonb;
  v_read_at timestamptz;
  v_data jsonb;
  v_response jsonb;
  v_request_sha256 text;
  v_is_member boolean;
BEGIN
  IF v_user IS NULL
     OR NOT public.can_read_news_data_security_v1(p_occasion)
     OR NOT EXISTS (SELECT 1 FROM public.user_info ui JOIN public.occasions o
       ON o.organization=ui.organization WHERE ui.id=v_user AND o.id=p_occasion)
     OR NOT EXISTS (SELECT 1 FROM public.news n
       WHERE n.id=p_news_id AND n.occasion=p_occasion)
  THEN RETURN jsonb_build_object('code',403); END IF;

  v_request_sha256:=encode(extensions.digest(convert_to(
    jsonb_build_object('occasion',p_occasion,'newsId',p_news_id)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'news.mark_read',
    p_occasion,v_user,v_request_sha256);
  IF v_begin->>'disposition'='replay' THEN
    RETURN v_begin->'response';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text||':'||p_occasion::text,0));

  SELECT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=v_user) INTO v_is_member;
  SELECT COALESCE(source_revision,0) INTO v_revision
  FROM (SELECT 1) seed LEFT JOIN public.client_sync_private_scopes s
    ON s.component='private_news' AND s.occasion=p_occasion AND s.user_id=v_user;
  -- A delayed command never moves the high-water mark backwards.
  SELECT greatest(p_news_id,coalesce(max(news_id),0)) INTO p_news_id
    FROM public.user_news WHERE "user"=v_user AND occasion=p_occasion;
  IF (SELECT count(*)=1 AND max(news_id)=p_news_id
      FROM public.user_news
      WHERE "user"=v_user AND occasion=p_occasion) THEN
    v_data:=jsonb_build_object('revision',v_revision,'payload',jsonb_build_array(
      jsonb_build_object('newsId',p_news_id)));
    v_response:=jsonb_build_object('status','unchanged','code',200,'data',v_data,
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  v_read_at:=clock_timestamp();
  v_data:=jsonb_build_object('revision',v_revision+1,'payload',jsonb_build_array(
    jsonb_build_object('newsId',p_news_id,'readAt',v_read_at)));
  DELETE FROM public.user_news WHERE "user"=v_user AND occasion=p_occasion;
  INSERT INTO public.user_news(news_id,"user",occasion) VALUES(p_news_id,v_user,p_occasion);
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'mark_news_read','private',
    jsonb_build_array(jsonb_build_object('entityType','news_marker',
      'entityId',p_news_id,'operation','update','safeLabel','News read marker',
    'changedFields',jsonb_build_array('news_id'))),ARRAY['live_public'],CASE WHEN v_is_member THEN jsonb_build_array(
      jsonb_build_object('component','private_news','userId',v_user)) ELSE '[]'::jsonb END,jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_news_id)),
    'user',NULL);
  SELECT source_revision INTO v_revision FROM public.client_sync_private_scopes
    WHERE component='private_news' AND occasion=p_occasion AND user_id=v_user;
  v_data:=v_data||jsonb_build_object('revision',coalesce(v_revision,0));
  v_response:=jsonb_build_object('status','applied','code',200,'data',v_data,
    'mutation',jsonb_build_object('commandId',p_command_id,
      'receiptId',p_command_id,'commitId',v_commit->>'commitId','replayed',false,
      'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',CASE WHEN v_is_member THEN jsonb_build_array(jsonb_build_object(
      'component','private_news','revision',v_revision,'payload',v_data->'payload')) ELSE '[]'::jsonb END));
  RETURN public.finish_client_mutation_v1(
    p_command_id,v_response,(v_commit->>'commitId')::uuid);
END; $$;


ALTER FUNCTION public.mark_news_read_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: mark_notification_center_view_item_read(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_notification_center_view_item_read(p_organization bigint, p_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE scope jsonb;
BEGIN
 PERFORM public.notification_center_check_context(p_organization);
 PERFORM 1 FROM public.notification_center_projection_scopes WHERE organization=p_organization AND recipient=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.notification_center_user_state WHERE organization=p_organization AND recipient=auth.uid() FOR UPDATE NOWAIT;
 scope:=public.notification_center_prepared_scope(p_organization,p_scope);
 IF scope->>'isRead'='true' THEN RETURN true; END IF;
 RETURN public.notification_center_prepared_record_read(p_organization,scope->>'groupKey',(scope->>'afterSequence')::bigint,(scope->>'throughSequence')::bigint,true);
EXCEPTION WHEN lock_not_available THEN RETURN false;
END $$;


ALTER FUNCTION public.mark_notification_center_view_item_read(p_organization bigint, p_scope jsonb) OWNER TO postgres;

--
-- Name: mark_order_and_tickets_paid_internal_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_order_and_tickets_paid_internal_v1(order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occasion_id bigint; current_state text; provider_guard jsonb;
BEGIN
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    -- Retrieve the occasion associated with the order
    SELECT occasion, state INTO occasion_id, current_state FROM eshop.orders WHERE id = order_id FOR UPDATE;

    -- Check if the order exists and has an associated occasion
    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    provider_guard:=public.provider_paid_guard_internal(order_id);
    IF provider_guard IS NOT NULL THEN RETURN provider_guard; END IF;
    -- Check if the order is in 'ordered' or 'created' state before proceeding
    -- Allow 'created' to support direct payments (e.g. manual cash) without explicit confirmation step
    -- FIX: Allow 'expired' too, as late payments should reactivate the order
    IF current_state != 'ordered' AND current_state != 'created' AND current_state != 'expired' THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Order is not in "ordered", "created" or "expired" state (current: ' || current_state || ')');
    END IF;

    -- Update the state of the order to 'paid'
    UPDATE eshop.orders
    SET state = 'paid', updated_at = now(),email_payment_version=email_payment_version+1
    WHERE id = order_id;

    -- Update the state of all tickets linked to the order to 'paid', except those with state 'storno'
    UPDATE eshop.tickets
    SET state = 'paid', updated_at = now()
    FROM eshop.order_product_ticket
    WHERE eshop.order_product_ticket.ticket = eshop.tickets.id
    AND eshop.order_product_ticket."order" = order_id
    AND eshop.tickets.state IN ('ordered','expired','paid');

    PERFORM public.notification_center_order_state_internal(order_id);
    RETURN jsonb_build_object('code',200,'message','Update successful');
END $$;


ALTER FUNCTION public.mark_order_and_tickets_paid_internal_v1(order_id bigint) OWNER TO postgres;

--
-- Name: mark_payment_reminder_sent(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_payment_reminder_sent(p_payment_info_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- This function updates the 'data' JSONB column in the eshop.payment_info table
  -- for a specific payment record. It marks that a reminder has been sent and
  -- appends the current timestamp to an array of sent reminders.
  UPDATE eshop.payment_info
  SET
    -- This operation updates the 'data' field by merging it with a new JSONB object.
    -- The new object sets 'current_version_reminded' to true and updates the
    -- 'reminder_sent_at' field.
    data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
      'current_version_reminded', true,
      -- The 'reminder_sent_at' value is constructed by taking the existing array
      -- (or an empty array '[]' if it doesn't exist) and appending the current
      -- timestamp to it.
      'reminder_sent_at', COALESCE(data->'reminder_sent_at', '[]'::jsonb) || jsonb_build_array(NOW())
    )
  WHERE
    id = p_payment_info_id;
END;
$$;


ALTER FUNCTION public.mark_payment_reminder_sent(p_payment_info_id bigint) OWNER TO postgres;

