    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  RETURN nextval('public.client_sync_release_revision_seq');
END;
$$;


