--
-- Name: occasion_setup_bank_fingerprint_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.occasion_setup_bank_fingerprint_internal(p_bank bigint) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT encode(extensions.digest(convert_to(jsonb_build_object('id',b.id,'account',b.account_number,
  'currencies',b.supported_currencies)::text,'UTF8'),'sha256'),'hex') FROM eshop.bank_accounts b WHERE b.id=p_bank;
$$;


ALTER FUNCTION public.occasion_setup_bank_fingerprint_internal(p_bank bigint) OWNER TO postgres;

--
-- Name: occasion_setup_default_start_internal(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.occasion_setup_default_start_internal(p_now timestamp with time zone, p_timezone text DEFAULT 'Europe/Prague'::text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT (date_trunc('hour',local_now) + ceil(extract(epoch FROM (local_now-date_trunc('hour',local_now)))/1800)*interval '30 minutes') AT TIME ZONE p_timezone
 FROM (SELECT (p_now AT TIME ZONE p_timezone)+interval '30 days' local_now) x;
$$;


ALTER FUNCTION public.occasion_setup_default_start_internal(p_now timestamp with time zone, p_timezone text) OWNER TO postgres;

