--
-- Name: password_verification_attempt_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.password_verification_attempt_v1(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid; allowed boolean;
BEGIN
 actor:=(event->>'user_id')::uuid;
 IF actor IS NULL OR jsonb_typeof(event->'valid') IS DISTINCT FROM 'boolean'
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor) THEN
  RETURN jsonb_build_object('decision','reject','message','Invalid login attempt','should_logout_user',false);
 END IF;
 allowed:=public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.password',NULL,NULL),
  jsonb_build_object('actor',actor::text),'{}',true);
 RETURN jsonb_build_object('decision',CASE WHEN allowed THEN 'continue' ELSE 'reject' END,
  'message',CASE WHEN allowed THEN '' ELSE 'Too many login attempts. Try again later.' END,
  'should_logout_user',false);
END $$;


ALTER FUNCTION public.password_verification_attempt_v1(event jsonb) OWNER TO postgres;

--
-- Name: payment_financial_totals_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.payment_financial_totals_internal(p_payment bigint) RETURNS TABLE(gross_received numeric, refunded numeric, external_received numeric, disputed numeric, net_received numeric, available numeric, invalid_identity boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH p AS (SELECT * FROM eshop.payment_info WHERE id=p_payment),
 bank AS (SELECT
  coalesce(sum(t.amount) FILTER(WHERE t.transaction_type IS DISTINCT FROM 'return'),0) received,
  abs(coalesce(sum(t.amount) FILTER(WHERE t.transaction_type='return'),0)) returned,
  coalesce(bool_or(t.currency IS DISTINCT FROM p.currency_code),false) invalid
  FROM p JOIN eshop.transactions t ON t.payment_info=p.id),
 provider_raw AS (SELECT CASE WHEN NOT public.payment_method_is_online_internal(payment_method) THEN '{}'::jsonb
   ELSE public.provider_financial_totals_internal(payment_method,id) END facts FROM p),
 provider AS (SELECT coalesce((facts->>'received')::numeric,0) received,
  coalesce((facts->>'returned')::numeric,0) returned,coalesce((facts->>'invalid')::boolean,false) invalid FROM provider_raw),
 holds AS (SELECT coalesce((facts->>'held')::numeric,0) held FROM provider_raw),
 totals AS (SELECT bank.received+provider.received gross,bank.returned+provider.returned returned,
  coalesce(p.paid_externally,0) external,holds.held,bank.invalid OR provider.invalid invalid
  FROM p CROSS JOIN bank CROSS JOIN provider CROSS JOIN holds)
 -- The legacy external field has no attributable movement identity/date.
 -- Preserve it explicitly, without guessing whether it overlaps stored paid.
 SELECT gross,returned,external,held,gross-returned,
  greatest(gross-returned-held,0),invalid FROM totals;
$$;


ALTER FUNCTION public.payment_financial_totals_internal(p_payment bigint) OWNER TO postgres;

