--
-- Name: people_profile_projection_internal_v1(jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.people_profile_projection_internal_v1(p_profile jsonb, p_version bigint) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT jsonb_build_object('userId',p_profile->'user','aggregateVersion',p_version,
  'name',p_profile#>'{profile,name}','surname',p_profile#>'{profile,surname}',
  'profile',coalesce((SELECT jsonb_object_agg(key,value) FROM jsonb_each(coalesce(nullif(p_profile->'data','null'::jsonb),'{}'))
   WHERE key IN ('name','surname','sex','phone','birthDate','note','diet','text1','text2','text3')),'{}'::jsonb),
  'roles',jsonb_build_object('role',p_profile->'role','is_manager',coalesce(nullif(p_profile->'is_manager','null'::jsonb),'false'::jsonb),
   'is_editor',coalesce(nullif(p_profile->'is_editor','null'::jsonb),'false'::jsonb),'is_editor_view',coalesce(nullif(p_profile->'is_editor_view','null'::jsonb),'false'::jsonb),
   'is_editor_order',coalesce(nullif(p_profile->'is_editor_order','null'::jsonb),'false'::jsonb),'is_editor_order_view',coalesce(nullif(p_profile->'is_editor_order_view','null'::jsonb),'false'::jsonb),
   'is_receptionist',coalesce(nullif(p_profile->'is_receptionist','null'::jsonb),'false'::jsonb),'is_approver',coalesce(nullif(p_profile->'is_approver','null'::jsonb),'false'::jsonb),
   'is_approved',coalesce(nullif(p_profile->'is_approved','null'::jsonb),'false'::jsonb),'is_cleaning_crew',coalesce(nullif(p_profile->'is_cleaning_crew','null'::jsonb),'false'::jsonb),
   'is_cleaning_blocked',coalesce(nullif(p_profile->'is_cleaning_blocked','null'::jsonb),'false'::jsonb),'is_volunteer',coalesce(nullif(p_profile#>'{data,is_volunteer}','null'::jsonb),'false'::jsonb)));
$$;


ALTER FUNCTION public.people_profile_projection_internal_v1(p_profile jsonb, p_version bigint) OWNER TO postgres;

--
-- Name: place_move_rule(boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.place_move_rule(p_editor boolean, p_group_admin boolean, p_private_place boolean, p_writable boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT p_writable AND (p_editor OR (coalesce(p_group_admin,false) AND p_private_place)); $$;


ALTER FUNCTION public.place_move_rule(p_editor boolean, p_group_admin boolean, p_private_place boolean, p_writable boolean) OWNER TO postgres;

--
-- Name: prepare_email(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_email(p_message uuid, p_token uuid, p_prepared jsonb, p_post_action jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 IF octet_length(p_prepared::text)>(SELECT (x->>'base_limit')::bigint
  FROM jsonb_array_elements(public.abuse_effective_rules_v1('email.payload',NULL,NULL)->'rules') x LIMIT 1) THEN
  RAISE configuration_limit_exceeded USING MESSAGE='email_payload_too_large'; END IF;
 UPDATE public.email_messages SET prepared=coalesce(prepared,p_prepared),
 prepared_hash=coalesce(prepared_hash,encode(extensions.digest(p_prepared::text,'sha256'),'hex')),prepared_at=coalesce(prepared_at,now()),
 tracking_policy=CASE WHEN prepared IS NULL AND message_kind LIKE 'order_%' AND p_post_action->>'tracking_policy'='engagement' THEN 'engagement' ELSE tracking_policy END,
 post_action=CASE WHEN prepared IS NULL THEN post_action||p_post_action ELSE post_action END
 WHERE message_id=p_message AND lease_token=p_token AND lease_until>now() AND workflow_state='preparing'
 AND (prepared IS NULL OR prepared=p_prepared);
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_email_preparation'; END IF;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=p_message),true);
END $$;


ALTER FUNCTION public.prepare_email(p_message uuid, p_token uuid, p_prepared jsonb, p_post_action jsonb) OWNER TO postgres;

--
-- Name: prepare_notification_center(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_notification_center(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
#variable_conflict use_variable
DECLARE s public.notification_center_projection_scopes; personal public.notification_center_user_state;
 e public.notification_center_events; d public.notification_center_deliveries; item record; job record;
 privacy jsonb; keys text[]; maximum uuid; processed integer:=0; n integer; budget integer:=greatest(1,least(coalesce(p_limit,500),100));
 error_code text;deadline timestamptz:=clock_timestamp()+interval '250 milliseconds'; current_at timestamptz; previous_timeout text:=current_setting('lock_timeout');
BEGIN
 PERFORM public.notification_center_require_service();
 IF NOT pg_try_advisory_xact_lock(5831290471283) THEN RETURN 0; END IF;
 PERFORM set_config('lock_timeout','5ms',true);
 FOR s IN SELECT * FROM public.notification_center_projection_scopes WHERE next_check_at<=clock_timestamp() AND NOT quarantined
  ORDER BY work_requested DESC,next_check_at,organization,recipient LIMIT 8 FOR UPDATE SKIP LOCKED LOOP
  BEGIN
   e:=NULL;
   budget:=greatest(1,least(coalesce(p_limit,500),100)-processed);
   SELECT * INTO personal FROM public.notification_center_user_state WHERE organization=s.organization AND recipient=s.recipient FOR UPDATE SKIP LOCKED;
   IF NOT FOUND THEN
    UPDATE public.notification_center_projection_scopes SET next_check_at=clock_timestamp()+interval '100 milliseconds' WHERE organization=s.organization AND recipient=s.recipient;
    CONTINUE;
   END IF;
   current_at:=clock_timestamp();privacy:=public.notification_center_prepared_privacy(s.organization);
   IF NOT s.delivery_initialized THEN
    SELECT count(*) INTO n FROM public.notification_center_recipients r JOIN public.notification_center_events ev ON ev.id=r.event_id
     WHERE r.recipient=s.recipient AND ev.organization=s.organization AND r.processed_revision<r.eligible_revision;
    UPDATE public.notification_center_projection_scopes SET pending_delivery=n,delivery_initialized=true WHERE organization=s.organization AND recipient=s.recipient;
   END IF;
   IF s.phase IN ('backfill','ready') AND s.phase='backfill' AND s.build_revision<>s.revision THEN
    UPDATE public.notification_center_projection_scopes SET phase='clear_members',build_revision=s.revision WHERE organization=s.organization AND recipient=s.recipient;
    processed:=processed+1;CONTINUE;
   END IF;
   IF s.phase='clear_members' THEN
    DELETE FROM public.notification_center_view_members WHERE (organization,recipient,event_id) IN(
     SELECT organization,recipient,event_id FROM public.notification_center_view_members WHERE organization=s.organization AND recipient=s.recipient ORDER BY event_id LIMIT budget);
    GET DIAGNOSTICS n=ROW_COUNT;
    IF n<budget THEN UPDATE public.notification_center_projection_scopes SET phase='clear_summaries' WHERE organization=s.organization AND recipient=s.recipient; END IF;
    processed:=processed+greatest(n,1);
   ELSIF s.phase='clear_summaries' THEN
    DELETE FROM public.notification_center_batch_summaries WHERE (organization,recipient,id) IN(
     SELECT organization,recipient,id FROM public.notification_center_batch_summaries WHERE organization=s.organization AND recipient=s.recipient ORDER BY id LIMIT budget);
    GET DIAGNOSTICS n=ROW_COUNT;
    IF n<budget THEN
     UPDATE public.notification_center_projection_scopes SET phase='backfill',cursor_sequence=0,prepared_sequence=0,
      build_revision=s.revision,privacy=privacy,pending_events=0,privacy_pending=false,privacy_keys='{}',privacy_cursor=NULL
      WHERE organization=s.organization AND recipient=s.recipient;
    END IF;
    processed:=processed+greatest(n,1);
   ELSIF s.phase='backfill' THEN
    n:=0;
    FOR d IN SELECT * FROM public.notification_center_deliveries WHERE organization=s.organization AND recipient=s.recipient
     AND sequence>s.cursor_sequence ORDER BY sequence LIMIT budget LOOP
     SELECT * INTO e FROM public.notification_center_events WHERE id=d.event_id;
     PERFORM public.notification_center_prepared_apply(e,d,current_at,s.privacy);
     UPDATE public.notification_center_recipients SET view_applied_revision=e.view_revision,view_required_revision=e.view_revision WHERE event_id=e.id AND recipient=s.recipient;
     s.cursor_sequence:=d.sequence;n:=n+1;
    END LOOP;
    UPDATE public.notification_center_projection_scopes SET cursor_sequence=s.cursor_sequence,prepared_sequence=s.cursor_sequence,
     phase=CASE WHEN s.cursor_sequence>=personal.last_delivery_sequence THEN 'ready' ELSE 'backfill' END,
     applied_read_revision=CASE WHEN pending_groups=0 THEN personal.view_read_revision ELSE applied_read_revision END,
     last_ready_at=CASE WHEN s.cursor_sequence>=personal.last_delivery_sequence THEN clock_timestamp() ELSE last_ready_at END
     WHERE organization=s.organization AND recipient=s.recipient;
    processed:=processed+greatest(n,1);
   ELSE
    -- Hidden identity/email changes are detected from a bounded live subject
    -- snapshot. Every contribution is evaluated against an explicit snapshot,
    -- so a transient hide/unhide cannot contaminate a different generation.
    IF s.privacy<>privacy OR s.privacy_pending THEN
     WITH before_keys AS(SELECT key FROM public.notification_center_prepared_privacy_keys(s.privacy) key),
     after_keys AS(SELECT key FROM public.notification_center_prepared_privacy_keys(privacy) key),
     delta AS(SELECT coalesce(b.key,a.key) key FROM before_keys b FULL JOIN after_keys a USING(key) WHERE b.key IS NULL OR a.key IS NULL)
     SELECT array_agg(DISTINCT key) FILTER(WHERE key IS NOT NULL) INTO keys FROM(
      SELECT unnest(s.privacy_keys) key UNION SELECT key FROM delta) q;
     IF NOT s.privacy_pending OR s.repair_privacy<>privacy THEN s.privacy_cursor:=NULL; END IF;
     n:=0;maximum:=s.privacy_cursor;
     FOR item IN SELECT DISTINCT v.event_id FROM unnest(coalesce(keys,'{}')) key
      CROSS JOIN LATERAL(SELECT event_id FROM public.notification_center_member_subjects m
       WHERE m.organization=s.organization AND m.recipient=s.recipient AND m.subject=key
        AND (s.privacy_cursor IS NULL OR m.event_id>s.privacy_cursor) ORDER BY event_id LIMIT budget) v ORDER BY v.event_id LIMIT budget LOOP
      SELECT * INTO e FROM public.notification_center_events WHERE id=item.event_id;
      SELECT * INTO d FROM public.notification_center_deliveries WHERE event_id=item.event_id AND recipient=s.recipient ORDER BY sequence DESC LIMIT 1;
      IF e.id IS NOT NULL AND d.event_id IS NOT NULL THEN PERFORM public.notification_center_prepared_apply(e,d,current_at,privacy); END IF;
      maximum:=item.event_id;n:=n+1;
     END LOOP;
     UPDATE public.notification_center_projection_scopes SET privacy_pending=n>=budget,
      privacy=CASE WHEN n<budget THEN privacy ELSE notification_center_projection_scopes.privacy END,
      repair_privacy=privacy,privacy_cursor=CASE WHEN n>=budget THEN maximum END,
      privacy_keys=CASE WHEN n>=budget THEN coalesce(keys,'{}') ELSE '{}'::text[] END,
      revision=revision+CASE WHEN NOT s.privacy_pending THEN 1 ELSE 0 END
      WHERE organization=s.organization AND recipient=s.recipient;
     processed:=processed+greatest(n,1);
    ELSIF s.pending_events>0 THEN
     n:=0;
     FOR item IN SELECT r.event_id FROM public.notification_center_recipients r JOIN public.notification_center_events ev ON ev.id=r.event_id
      WHERE r.recipient=s.recipient AND ev.organization=s.organization AND r.view_required_revision>r.view_applied_revision
      ORDER BY r.event_id LIMIT budget LOOP
      SELECT * INTO e FROM public.notification_center_events WHERE id=item.event_id FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      PERFORM 1 FROM public.notification_center_recipients WHERE event_id=e.id AND recipient=s.recipient FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      SELECT * INTO d FROM public.notification_center_deliveries WHERE event_id=e.id AND recipient=s.recipient ORDER BY sequence DESC LIMIT 1;
      IF FOUND THEN PERFORM public.notification_center_prepared_apply(e,d,current_at,s.privacy); END IF;
      UPDATE public.notification_center_recipients SET view_applied_revision=e.view_revision,view_required_revision=e.view_revision WHERE event_id=e.id AND recipient=s.recipient;
      n:=n+1;
     END LOOP;
     UPDATE public.notification_center_projection_scopes SET pending_events=greatest(0,pending_events-n) WHERE organization=s.organization AND recipient=s.recipient;
     processed:=processed+n;
    ELSIF s.pending_groups>0 THEN
     SELECT * INTO job FROM public.notification_center_group_repairs WHERE organization=s.organization AND recipient=s.recipient ORDER BY group_key LIMIT 1 FOR UPDATE SKIP LOCKED;
     IF FOUND THEN
      n:=0;maximum:=job.cursor;
      FOR item IN SELECT event_id FROM public.notification_center_view_members WHERE organization=s.organization AND recipient=s.recipient AND group_key=job.group_key
       AND (job.cursor IS NULL OR event_id>job.cursor) ORDER BY event_id LIMIT budget LOOP
       SELECT * INTO e FROM public.notification_center_events WHERE id=item.event_id;
       SELECT * INTO d FROM public.notification_center_deliveries WHERE event_id=item.event_id AND recipient=s.recipient ORDER BY sequence DESC LIMIT 1;
       IF e.id IS NOT NULL AND d.event_id IS NOT NULL THEN PERFORM public.notification_center_prepared_apply(e,d,current_at,s.privacy); END IF;
       maximum:=item.event_id;n:=n+1;
      END LOOP;
      IF n<budget THEN
       DELETE FROM public.notification_center_group_repairs WHERE organization=s.organization AND recipient=s.recipient AND group_key=job.group_key;
       UPDATE public.notification_center_projection_scopes SET pending_groups=greatest(0,pending_groups-1),
        applied_read_revision=CASE WHEN pending_groups<=1 THEN personal.view_read_revision ELSE applied_read_revision END WHERE organization=s.organization AND recipient=s.recipient;
      ELSE UPDATE public.notification_center_group_repairs SET cursor=maximum WHERE organization=s.organization AND recipient=s.recipient AND group_key=job.group_key; END IF;
      processed:=processed+greatest(n,1);
     END IF;
    ELSIF s.prepared_sequence<personal.last_delivery_sequence THEN
     n:=0;
     FOR d IN SELECT * FROM public.notification_center_deliveries WHERE organization=s.organization AND recipient=s.recipient AND sequence>s.prepared_sequence ORDER BY sequence LIMIT budget LOOP
      SELECT * INTO e FROM public.notification_center_events WHERE id=d.event_id;
      PERFORM public.notification_center_prepared_apply(e,d,current_at,s.privacy);
      UPDATE public.notification_center_recipients SET view_applied_revision=e.view_revision,view_required_revision=e.view_revision WHERE event_id=e.id AND recipient=s.recipient;
      s.prepared_sequence:=d.sequence;n:=n+1;
     END LOOP;
     UPDATE public.notification_center_projection_scopes SET prepared_sequence=s.prepared_sequence WHERE organization=s.organization AND recipient=s.recipient;
     processed:=processed+greatest(n,1);
    ELSE
     n:=0;
     FOR item IN SELECT event_id FROM public.notification_center_view_members WHERE organization=s.organization AND recipient=s.recipient AND eligible AND expires_at<current_at ORDER BY expires_at,event_id LIMIT budget LOOP
      SELECT * INTO e FROM public.notification_center_events WHERE id=item.event_id;
      SELECT * INTO d FROM public.notification_center_deliveries WHERE event_id=e.id AND recipient=s.recipient ORDER BY sequence DESC LIMIT 1;
      PERFORM public.notification_center_prepared_apply(e,d,current_at,s.privacy);n:=n+1;
     END LOOP;
     processed:=processed+n;
    END IF;
   END IF;
   SELECT expires_at INTO s.next_expiry FROM public.notification_center_view_members
    WHERE organization=s.organization AND recipient=s.recipient AND eligible AND expires_at IS NOT NULL ORDER BY expires_at,event_id LIMIT 1;
   UPDATE public.notification_center_projection_scopes SET retry_count=0,last_error_code=NULL,failed_event=NULL,
    work_requested=phase<>'ready' OR pending_delivery>0 OR pending_events>0 OR pending_groups>0 OR privacy_pending OR prepared_sequence<personal.last_delivery_sequence OR coalesce(s.next_expiry<current_at,false),
    next_expiry=s.next_expiry,
    requested_at=CASE WHEN phase<>'ready' OR pending_delivery>0 OR pending_events>0 OR pending_groups>0 OR privacy_pending OR prepared_sequence<personal.last_delivery_sequence OR coalesce(s.next_expiry<current_at,false)
     THEN coalesce(requested_at,current_at) END,
    next_check_at=CASE WHEN phase<>'ready' OR pending_delivery>0 OR pending_events>0 OR pending_groups>0 OR privacy_pending OR prepared_sequence<personal.last_delivery_sequence OR coalesce(s.next_expiry<current_at,false)
     THEN clock_timestamp() ELSE coalesce(s.next_expiry,'infinity'::timestamptz) END
    WHERE organization=s.organization AND recipient=s.recipient;
  EXCEPTION WHEN lock_not_available THEN NULL;
   WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS error_code=RETURNED_SQLSTATE;
    UPDATE public.notification_center_projection_scopes SET retry_count=retry_count+1,last_error_code=error_code,failed_event=e.id,
     quarantined=retry_count>=4,next_check_at=clock_timestamp()+make_interval(secs=>least(300,power(2,least(retry_count,8))*(0.9+random()*0.2)))
     WHERE organization=s.organization AND recipient=s.recipient;
    processed:=processed+1;
  END;
  EXIT WHEN processed>=budget OR clock_timestamp()>=deadline;
 END LOOP;
 PERFORM set_config('lock_timeout',previous_timeout,true);
 RETURN processed;
EXCEPTION WHEN lock_not_available THEN
 -- Relation locks (for example concurrent maintenance) can precede row-level
 -- SKIP LOCKED. This entire call rolls back; recovery retries durable work.
 PERFORM set_config('lock_timeout',previous_timeout,true);
 RETURN 0;
END $$;


ALTER FUNCTION public.prepare_notification_center(p_limit integer) OWNER TO postgres;

--
-- Name: prepare_notification_center_views(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_notification_center_views(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
#variable_conflict use_variable
DECLARE work record; s public.notification_center_projection_scopes; v public.notification_center_views;
 r public.notification_center_view_rows; e public.notification_center_events; d public.notification_center_deliveries; m public.notification_center_view_members;
 privacy jsonb; privacy_key text; read_rev bigint; last_id uuid; ids uuid[]; b record;
 n integer; processed integer:=0; budget integer:=greatest(1,least(coalesce(p_limit,100),100));
 error_code text;deadline timestamptz:=clock_timestamp()+interval '250 milliseconds'; previous_timeout text:=current_setting('lock_timeout');
BEGIN
 PERFORM public.notification_center_require_service();
 IF NOT pg_try_advisory_xact_lock(5831290471283) THEN RETURN 0; END IF;
 PERFORM set_config('lock_timeout','5ms',true);
 DELETE FROM public.notification_center_views WHERE token IN(SELECT token FROM public.notification_center_views WHERE expires_at<=clock_timestamp() ORDER BY expires_at LIMIT 100);
 FOR work IN SELECT vr.token,vr.position FROM public.notification_center_view_rows vr JOIN public.notification_center_views vw ON vw.token=vr.token
  JOIN public.notification_center_projection_scopes ps ON ps.organization=vw.organization AND ps.recipient=vw.recipient
  JOIN public.notification_center_user_state us ON us.organization=vw.organization AND us.recipient=vw.recipient
  WHERE vw.expires_at>clock_timestamp() AND (vr.next_attempt_at<=clock_timestamp() OR vr.repair_revision IS DISTINCT FROM ps.revision)
   AND (NOT vr.quarantined OR vr.repair_revision IS DISTINCT FROM ps.revision) AND ps.phase='ready' AND ps.pending_events=0 AND ps.pending_groups=0 AND NOT ps.privacy_pending
   AND (vr.state='preparing' OR vr.revision<>ps.revision OR vr.read_revision<>us.view_read_revision
    OR vr.privacy_key<>md5(public.notification_center_prepared_privacy(vw.organization)::text))
  ORDER BY vw.created_at,vr.position LIMIT 8 FOR UPDATE OF vr SKIP LOCKED LOOP
  BEGIN
   budget:=greatest(1,least(coalesce(p_limit,100),100)-processed);
   SELECT * INTO v FROM public.notification_center_views WHERE token=work.token;
   SELECT * INTO s FROM public.notification_center_projection_scopes WHERE organization=v.organization AND recipient=v.recipient FOR SHARE NOWAIT;
   SELECT * INTO r FROM public.notification_center_view_rows WHERE token=work.token AND position=work.position;
   SELECT view_read_revision INTO read_rev FROM public.notification_center_user_state WHERE organization=v.organization AND recipient=v.recipient;
   privacy:=public.notification_center_prepared_privacy(v.organization);privacy_key:=md5(privacy::text);
   IF r.repair_revision IS DISTINCT FROM s.revision OR r.repair_read_revision IS DISTINCT FROM read_rev OR r.repair_privacy_key IS DISTINCT FROM privacy_key THEN
    r.repair_cursor:=NULL;r.repair_count:=0;r.repair_known:=0;r.repair_places:=0;r.repair_multiple:=0;r.repair_unread:=0;r.repair_previews:='{}';
   END IF;
   n:=0;last_id:=r.repair_cursor;ids:=r.repair_previews;
   FOR m IN SELECT * FROM public.notification_center_view_members WHERE organization=v.organization AND recipient=v.recipient AND group_key=r.group_key
    AND (r.repair_cursor IS NULL OR event_id>r.repair_cursor) ORDER BY event_id LIMIT budget LOOP
    last_id:=m.event_id;n:=n+1;
    SELECT * INTO e FROM public.notification_center_events WHERE id=m.event_id;
    SELECT * INTO d FROM public.notification_center_deliveries WHERE event_id=m.event_id AND recipient=v.recipient AND sequence<=v.snapshot ORDER BY sequence DESC LIMIT 1;
    IF e.id IS NULL OR d.event_id IS NULL OR NOT public.notification_center_prepared_scope_member(e,d,r.group_key,r.id,r.after_sequence,r.through_sequence,v.anchor,r.capture_is_read)
     OR NOT public.notification_center_prepared_policy(e,v.anchor,privacy) THEN CONTINUE; END IF;
    SELECT * INTO b FROM public.notification_center_batch_internal(e,d);
    r.repair_count:=r.repair_count+1;r.repair_known:=r.repair_known+(m.places IS NOT NULL)::int;
    r.repair_places:=r.repair_places+coalesce(m.places,0);r.repair_multiple:=r.repair_multiple+m.multiple::int;r.repair_unread:=r.repair_unread+(NOT b.is_read)::int;
    ids:=array_append(ids,e.id);
   END LOOP;
   SELECT coalesce(array_agg(id ORDER BY occurred_at DESC,id DESC),'{}') INTO ids FROM(SELECT DISTINCT ev.id,ev.occurred_at FROM unnest(ids) p(event_id) JOIN public.notification_center_events ev ON ev.id=p.event_id ORDER BY ev.occurred_at DESC,ev.id DESC LIMIT 3) q;
   UPDATE public.notification_center_view_rows SET state=CASE WHEN n>=budget THEN 'preparing' WHEN r.repair_count=0 THEN 'removed' ELSE 'ready' END,
    repair_cursor=CASE WHEN n>=budget THEN last_id END,repair_revision=s.revision,repair_read_revision=read_rev,repair_privacy_key=privacy_key,
    repair_count=r.repair_count,repair_known=r.repair_known,repair_places=r.repair_places,repair_multiple=r.repair_multiple,repair_unread=r.repair_unread,repair_previews=ids,
    revision=CASE WHEN n<budget THEN s.revision ELSE revision END,read_revision=CASE WHEN n<budget THEN read_rev ELSE read_revision END,
    privacy_key=CASE WHEN n<budget THEN privacy_key ELSE notification_center_view_rows.privacy_key END,
    activity_count=CASE WHEN n<budget THEN r.repair_count ELSE activity_count END,known_count=CASE WHEN n<budget THEN r.repair_known ELSE known_count END,
    places=CASE WHEN n<budget THEN r.repair_places ELSE places END,multiple_count=CASE WHEN n<budget THEN r.repair_multiple ELSE multiple_count END,
    is_read=CASE WHEN n<budget THEN r.repair_unread=0 ELSE is_read END,
    latest_event=CASE WHEN n<budget THEN ids[1] ELSE latest_event END,preview_events=CASE WHEN n<budget THEN ids ELSE preview_events END
    WHERE token=r.token AND position=r.position;
   processed:=processed+greatest(n,1);
  EXCEPTION WHEN lock_not_available THEN NULL;
   WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS error_code=RETURNED_SQLSTATE;
    UPDATE public.notification_center_view_rows SET state='preparing',retry_count=retry_count+1,last_error_code=error_code,
     repair_revision=s.revision,repair_read_revision=read_rev,repair_privacy_key=privacy_key,repair_cursor=NULL,
     repair_count=0,repair_known=0,repair_places=0,repair_multiple=0,repair_unread=0,repair_previews='{}',
     quarantined=retry_count>=4,next_attempt_at=clock_timestamp()+make_interval(secs=>least(300,power(2,least(retry_count,8))*(0.9+random()*0.2)))
     WHERE token=work.token AND position=work.position;
    processed:=processed+1;
  END;
  EXIT WHEN processed>=budget OR clock_timestamp()>=deadline;
 END LOOP;
 PERFORM set_config('lock_timeout',previous_timeout,true);
 RETURN processed;
EXCEPTION WHEN lock_not_available THEN
 -- Relation locks (for example concurrent maintenance) can precede row-level
 -- SKIP LOCKED. This entire call rolls back; recovery retries durable work.
 PERFORM set_config('lock_timeout',previous_timeout,true);
 RETURN 0;
END $$;


ALTER FUNCTION public.prepare_notification_center_views(p_limit integer) OWNER TO postgres;

--
-- Name: prepare_profile_change_internal_v1(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_profile_change_internal_v1(p_current jsonb, p_intent jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE changes jsonb; spec jsonb:= $contract${"profile":{"name":{"type":"string","maxLength":512,"nullable":true},"surname":{"type":"string","maxLength":512,"nullable":true},"phone":{"type":"string","maxLength":512,"nullable":true},"diet":{"type":"string","maxLength":512,"nullable":true},"text1":{"type":"string","maxLength":512,"nullable":true},"text2":{"type":"string","maxLength":512,"nullable":true},"text3":{"type":"string","maxLength":512,"nullable":true},"sex":{"type":"string","maxLength":32,"nullable":true},"note":{"type":"string","maxLength":8192,"nullable":true},"birthDate":{"type":"string","pattern":"^([0-9]{4}-[0-9]{2}-[0-9]{2})?$","nullable":true}},"roles":{"is_editor":{"type":"boolean"},"is_editor_view":{"type":"boolean"},"is_editor_order":{"type":"boolean"},"is_editor_order_view":{"type":"boolean"},"is_cleaning_crew":{"type":"boolean"},"is_cleaning_blocked":{"type":"boolean"},"is_receptionist":{"type":"boolean"},"is_approver":{"type":"boolean"},"is_approved":{"type":"boolean"},"is_manager":{"type":"boolean"},"is_volunteer":{"type":"boolean"},"role":{"type":"integer","minimum":0,"maximum":2147483647,"nullable":true}}}$contract$::jsonb; kind text;
BEGIN
 IF NOT (p_intent ?| ARRAY['profileChange','roleChange']) THEN RETURN p_intent; END IF;
 IF p_intent ? 'profileChange' AND p_intent ? 'roleChange'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_intent) k WHERE k NOT IN ('occasion','user','profileChange','roleChange')) THEN
  RAISE invalid_parameter_value USING MESSAGE='one explicit profile or role intent required'; END IF;
 kind:=CASE WHEN p_intent ? 'roleChange' THEN 'roles' ELSE 'profile' END;
 changes:=coalesce(p_intent->'profileChange',p_intent->'roleChange');
 IF jsonb_typeof(changes) IS DISTINCT FROM 'object' THEN RAISE invalid_parameter_value USING MESSAGE='named profile changes required'; END IF;
 PERFORM public.validate_configuration_value_internal_v1(changes,jsonb_build_object('type','object','properties',spec->kind));
 IF kind='profile' THEN
  RETURN jsonb_build_object('occasion',p_intent->'occasion','user',p_intent->'user',
   'data',coalesce(nullif(p_current->'data','null'::jsonb),'{}')||changes);
 END IF;
 RETURN jsonb_build_object('occasion',p_intent->'occasion','user',p_intent->'user',
   'data',coalesce(nullif(p_current->'data','null'::jsonb),'{}')||CASE WHEN changes ? 'is_volunteer' THEN jsonb_build_object('is_volunteer',changes->'is_volunteer') ELSE '{}'::jsonb END)
   ||(changes-'is_volunteer');
END $_$;


ALTER FUNCTION public.prepare_profile_change_internal_v1(p_current jsonb, p_intent jsonb) OWNER TO postgres;

--
-- Name: prepare_scanner_snapshot(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_scanner_snapshot(p_session uuid, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; sid uuid:=gen_random_uuid(); v_manifest jsonb;
 policy jsonb; max_items bigint; max_bytes bigint; items bigint; bytes bigint;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token); SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT (cfg.config#>>'{offline,enabled}')::boolean OR s.offline_until<=now() THEN RAISE insufficient_privilege USING MESSAGE='offline_disabled'; END IF;
 -- Bound repeated materialization per device, in addition to existing operation/export policy.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_session::text,5318));
 IF EXISTS(SELECT 1 FROM public.scanner_snapshots WHERE session_id=p_session AND created_at>now()-interval '60 seconds') THEN
  RETURN jsonb_build_object('code',429,'reason','snapshot_rate_limit','retry_after_ms',60000,'server_time',now()); END IF;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 policy:=public.abuse_effective_rules_v1('scan.export',(SELECT unit FROM public.occasions WHERE id=s.occasion_id),(SELECT organization FROM public.occasions WHERE id=s.occasion_id));
 SELECT (r->>'base_limit')::bigint INTO max_items FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.items';
 SELECT (r->>'base_limit')::bigint INTO max_bytes FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.bytes';
 IF max_items IS NULL OR max_bytes IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 INSERT INTO public.scanner_snapshots(id,session_id,manifest,expires_at) VALUES(sid,p_session,'{}',s.offline_until);
 -- Exactly one statement snapshot supplies pages AND manifest. Never paginate live tickets.
 WITH projected AS MATERIALIZED (
  SELECT ticket_id,dto,row_number() OVER(ORDER BY ticket_id) rn FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config)
 ), pages AS MATERIALIZED (
  SELECT ((rn-1)/200)::integer idx,jsonb_agg(dto ORDER BY rn)::text payload,count(*) n FROM projected GROUP BY ((rn-1)/200)::integer
 ), stored AS (
  INSERT INTO public.scanner_snapshot_pages(snapshot_id,page_index,payload_text,digest)
  SELECT sid,idx,payload,encode(digest(convert_to(payload,'UTF8'),'sha256'),'hex') FROM pages RETURNING *
 ) SELECT jsonb_build_object('schema_version',1,'snapshot_id',sid,'session_id',p_session,'occasion_id',s.occasion_id,'epoch',s.epoch,
 'settings_revision',cfg.revision,'server_time',now(),'expires_at',s.offline_until,'ticket_count',(SELECT count(*) FROM projected),
 'byte_count',coalesce(sum(octet_length(payload_text)),0),'pages',coalesce(jsonb_agg(jsonb_build_object('index',page_index,'digest',digest) ORDER BY page_index),'[]'::jsonb))
 INTO v_manifest FROM stored;
 items:=(v_manifest->>'ticket_count')::bigint; bytes:=(v_manifest->>'byte_count')::bigint;
 IF items>max_items OR bytes>max_bytes THEN
  DELETE FROM public.scanner_snapshots WHERE id=sid;
  RETURN jsonb_build_object('code',429,'reason','snapshot_policy_limit','server_time',now()); END IF;
 UPDATE public.scanner_snapshots SET manifest=v_manifest WHERE id=sid;
 -- Snapshot cleanup only; receipts and unresolved operations are never TTL deleted.
 DELETE FROM public.scanner_snapshots WHERE expires_at<now()-interval '24 hours';
 RETURN jsonb_build_object('code',200,'data',v_manifest,'server_time',now());
END $$;


ALTER FUNCTION public.prepare_scanner_snapshot(p_session uuid, p_token text) OWNER TO postgres;

--
-- Name: prepare_standing_inventory(bigint, bigint, bigint, bigint, bigint, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_standing_inventory(p_occasion bigint, p_organization bigint, p_unit bigint, p_product_id bigint, p_expected_version bigint, p_capacity integer, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid(); started jsonb; hash text; current_version bigint;
 product_row eshop.products%ROWTYPE; type_title text; pool_id bigint; context_id bigint;
 resource_result jsonb; result jsonb; rejection jsonb; catalog jsonb; snapshot jsonb; pool_snapshot jsonb; users uuid[];
BEGIN
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true);
 IF p_product_id IS NULL OR p_expected_version IS NULL OR p_expected_version<0 OR p_capacity IS NULL
   OR p_capacity NOT BETWEEN 0 AND 1000000 THEN RAISE invalid_parameter_value USING MESSAGE='invalid standing inventory'; END IF;
 -- Reject foreign IDs before acquiring their order/product locks. Retained
 -- receipts still pin replay even if the prepared product was later deleted.
 IF NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id
     AND actor_id=actor AND command_name='inventory.standing.prepare')
   AND NOT EXISTS(SELECT 1 FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
     WHERE p.id=p_product_id AND p.occasion=p_occasion AND pt.occasion=p_occasion AND pt.type='spot') THEN
  RAISE insufficient_privilege USING MESSAGE='standing product unavailable';
 END IF;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'productId',p_product_id,
  'expectedVersion',p_expected_version,'capacity',p_capacity)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.standing.prepare',p_occasion,actor,hash);
 IF started->>'disposition'='replay' THEN
  result:=started->'response';
 ELSE
  -- Checkout/assignment owners lock order parents before the product. New stock
  -- rows do not yet belong to another product, so no inverse pool dependency.
  PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
  SELECT p.* INTO product_row FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
   WHERE p.id=p_product_id AND p.occasion=p_occasion AND pt.occasion=p_occasion AND pt.type='spot' FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='standing product unavailable'; END IF;
  SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product'
   AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_product_id::text),0) INTO current_version;
  IF current_version IS DISTINCT FROM p_expected_version OR EXISTS(SELECT 1 FROM eshop.product_inventory_contexts WHERE product=p_product_id) THEN
   result:=public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
    jsonb_build_object('productId',p_product_id,'aggregate_version',current_version));
  ELSE
   BEGIN
   -- Child failures abort every new object and the product link together.
   pool_id:=public.save_inventory_pool_internal(jsonb_build_object('pool',
    jsonb_build_object('title',product_row.title,'occasion',p_occasion,'sellable_capacity',p_capacity,
     'data',jsonb_build_object('is_auto_resource_assignment',false)),
    'contexts',jsonb_build_array(jsonb_build_object('title',product_row.title))));
   SELECT id INTO STRICT context_id FROM public.inventory_contexts WHERE inventory_pool=pool_id;
   IF pool_id IS NULL OR context_id IS NULL THEN RAISE EXCEPTION 'standing pool creation failed'; END IF;
   PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,pool_id);
   resource_result:=public.save_inventory_resource_internal(p_occasion,NULL,jsonb_build_object(
    'inventory_pool',pool_id,'title',product_row.title,'capacity',p_capacity,'booking_rules','{}'::jsonb));
   IF resource_result->>'status'<>'applied' THEN RAISE EXCEPTION 'standing resource creation failed'; END IF;
   PERFORM public.update_product_inventory_contexts_internal_v1(p_product_id,
    jsonb_build_array(jsonb_build_object('inventory_context_id',context_id,'quantity',1)));
   catalog:=public.get_product_catalog_data_internal(p_occasion,NULLIF(p_product_id-1,0),1)::jsonb;
   SELECT pt.title INTO type_title FROM eshop.product_types pt WHERE pt.id=product_row.product_type;
   snapshot:=catalog#>'{products,0}' || jsonb_build_object('occasion',p_occasion,'type','spot','type_title',type_title,
    'inventory_contexts',jsonb_build_array(jsonb_build_object('inventory_context_id',context_id,'quantity',1)));
   IF (snapshot->>'id')::bigint IS DISTINCT FROM p_product_id THEN RAISE EXCEPTION 'standing product snapshot unavailable'; END IF;
   SELECT to_jsonb(ip)||jsonb_build_object('aggregate_version',v.version) INTO pool_snapshot
    FROM public.inventory_pools ip JOIN public.client_aggregate_versions v ON v.aggregate_type='inventory_pool'
     AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=ip.id::text WHERE ip.id=pool_id;
   -- Union of the existing pool/resource and assignment sync audiences.
   SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
   result:=public.complete_private_inventory_mutation_v1(p_command_id,p_occasion,'inventory.standing.prepare',
    jsonb_build_array(
     jsonb_build_object('entityType','inventory_pool','entityId',pool_id,'operation','insert','safeLabel','Standing inventory','changedFields',jsonb_build_array('aggregate')),
     jsonb_build_object('entityType','resource','entityId',resource_result#>'{data,resource,id}','operation','insert','safeLabel','Standing supply','changedFields',jsonb_build_array('aggregate')),
     jsonb_build_object('entityType','product','entityId',p_product_id,'operation','update','safeLabel','Standing product','changedFields',jsonb_build_array('inventory_contexts'))),users,
    jsonb_build_object('product',snapshot,'pool',pool_snapshot,'context',catalog#>'{inventory_contexts,0}',
      'resource',resource_result#>'{data,resource}','forms',catalog->'forms','readAt',catalog->'server_time'));
   EXCEPTION WHEN invalid_parameter_value THEN
    result:=public.complete_client_mutation_outcome_v1(p_command_id,'rejected',422,jsonb_build_object('reason','INVALID_STANDING_INVENTORY'));
   WHEN raise_exception THEN
    IF left(SQLERRM,1)<>'{' THEN RAISE; END IF;
    rejection:=SQLERRM::jsonb;
    IF rejection->>'code'<>'1017' THEN RAISE; END IF;
    result:=public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','PRODUCT_CAPACITY_EXCEEDED'));
   END;
  END IF;
 END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 RETURN result;
END $$;


ALTER FUNCTION public.prepare_standing_inventory(p_occasion bigint, p_organization bigint, p_unit bigint, p_product_id bigint, p_expected_version bigint, p_capacity integer, p_command_id uuid) OWNER TO postgres;

--
-- Name: presale_conversion_budgets_internal(jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.presale_conversion_budgets_internal(p_data jsonb, p_html text, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH settings AS (SELECT public.form_settings_from_metadata_internal(p_data||jsonb_build_object(
  'schedule',coalesce(p_data->'schedule','{}')||jsonb_build_object('countdown_title',p_html))) patch),
 sizes AS (SELECT length(p_html) characters,
  octet_length(patch::text) settings_bytes,
  octet_length(jsonb_build_object('operation','forms.save','args',jsonb_build_object(
   'occasionId',coalesce(p_snapshot#>'{form,occasion}','1'::jsonb),
   'commandId','00000000-0000-4000-8000-000000000001',
   'form',jsonb_build_object('id',coalesce(p_snapshot#>'{form,id}','1'::jsonb),
    'expected_aggregate_version',coalesce(p_snapshot#>'{form,aggregate_version}','0'::jsonb),
    'expected_product_versions',coalesce(p_snapshot->'productVersions','{}'),
    'expected_product_type_versions',coalesce(p_snapshot->'productTypeVersions','{}'),
    'settings',patch)))::text)+1024 transport_bytes,
  octet_length(p_snapshot::text)+1024 snapshot_bytes FROM settings)
 SELECT jsonb_build_object('characters',characters,'settingsBytes',settings_bytes,
  'transportBytes',transport_bytes,'snapshotBytes',snapshot_bytes,
  'blocked',characters>65536 OR settings_bytes>131072 OR transport_bytes>48000 OR snapshot_bytes>1048576) FROM sizes;
$$;


ALTER FUNCTION public.presale_conversion_budgets_internal(p_data jsonb, p_html text, p_snapshot jsonb) OWNER TO postgres;

--
-- Name: preview_admin_form_order(bigint, bigint, bigint, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_admin_form_order(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.check_form_order_scope_internal(p_occasion,p_organization,p_unit,p_form);
 PERFORM public.lock_form_order_internal(p_occasion,p_form);
 RETURN public.preview_form_order_internal(p_form,p_input)||jsonb_build_object('occasionId',p_occasion,'formId',p_form,'actorId',auth.uid());
END $$;


ALTER FUNCTION public.preview_admin_form_order(p_occasion bigint, p_organization bigint, p_unit bigint, p_form bigint, p_input jsonb) OWNER TO postgres;

--
-- Name: preview_admin_waitlist_acceptance(jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_admin_waitlist_acceptance(p_administration jsonb, p_payload jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE previous_sub text:=current_setting('request.jwt.claim.sub',true); occ bigint;fid bigint;
 facts jsonb;result jsonb;quote jsonb;offer uuid;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_actor IS NULL OR jsonb_typeof(p_payload)<>'object' OR p_payload ? 'token' OR octet_length(p_payload::text)>1048576 THEN
  RAISE insufficient_privilege USING MESSAGE='administrative acceptance actor required'; END IF;
 occ:=(p_administration->>'occasionId')::bigint;fid:=(p_administration->>'formId')::bigint;offer:=(p_payload->>'offerId')::uuid;
 PERFORM set_config('request.jwt.claim.sub',p_actor::text,true);
 PERFORM public.check_form_order_scope_internal(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid);
 PERFORM public.lock_form_order_internal(occ,fid);
 PERFORM public.get_form_waitlist_context(occ,(p_administration->>'organizationId')::bigint,(p_administration->>'unitId')::bigint,fid,'accept',p_payload);
 p_payload:=(p_payload-ARRAY['approvalHash','administrativeApproval'])||jsonb_build_object('orderDetails',public.form_order_input_internal(fid,p_payload->'orderDetails'));
 facts:=jsonb_build_object('form',public.form_order_facts_internal(fid),'offer',(SELECT to_jsonb(w) FROM eshop.waitlist_offers w WHERE id=offer),
  'slots',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM eshop.waitlist_offer_slots s WHERE s.offer_id=offer));
 BEGIN
  result:=public.execute_waitlist_command_client_sync_v1('accept',p_payload,extensions.gen_random_uuid(),extensions.gen_random_uuid(),p_actor,'[]');
  IF (result->>'code')::int=200 THEN quote:=public.form_order_quote_internal((result#>>'{data,order,id}')::bigint); END IF;
  RAISE SQLSTATE 'P0F91' USING MESSAGE='rollback waiting acceptance quote';
 EXCEPTION WHEN SQLSTATE 'P0F91' THEN NULL; END;
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
 IF (result->>'code')::int<>200 THEN RETURN jsonb_build_object('code',422,'reason','ORDER_NOT_CREATABLE','occasionId',occ,'formId',fid,'actorId',p_actor); END IF;
 RETURN jsonb_build_object('code',200,'quote',quote,'occasionId',occ,'formId',fid,'actorId',p_actor,'confirmationHash',
  encode(extensions.digest(jsonb_build_object('actor',p_actor,'scope',p_administration,'payload',p_payload,'facts',facts,'quote',quote)::text,'sha256'),'hex'));
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);RAISE;
END $$;


ALTER FUNCTION public.preview_admin_waitlist_acceptance(p_administration jsonb, p_payload jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: preview_blueprint_hold_release(bigint, bigint, bigint, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_blueprint_hold_release(p_occasion bigint, p_organization bigint, p_unit bigint, p_spots bigint[], p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE bp bigint;rev bigint;ids bigint[];rows jsonb;snapshot text;read_time timestamptz;
BEGIN
 IF p_editor IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='hold preview mode required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 SELECT min(blueprint) INTO bp FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion;
 SELECT layout_revision INTO rev FROM eshop.blueprints WHERE id=bp AND occasion=p_occasion AND layout IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 ids:=public.blueprint_hold_selection_internal(p_occasion,bp,p_spots,CASE WHEN p_editor THEN 20000 ELSE 1000 END);
 -- One locked snapshot for both displayed state and opaque confirmation token.
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids) ORDER BY id FOR SHARE;
 read_time:=clock_timestamp();
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',f.id,'title',f.title,'state',f.state) ORDER BY f.id),'[]') INTO rows
 FROM public.blueprint_spot_facts_internal(p_occasion,ids,read_time) f;
 snapshot:=public.blueprint_hold_snapshot_internal(p_occasion,ids);
 IF octet_length(rows::text)>(CASE WHEN p_editor THEN 8388608 ELSE 1048576 END) THEN RAISE program_limit_exceeded USING MESSAGE='hold preview exceeds payload limit'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'blueprintId',bp,'layoutRevision',rev,'requestedSpotIds',p_spots,
  'affectedSpotIds',ids,'holdSnapshot',snapshot,'seats',rows,
  'activeHoldCount',(SELECT count(*) FROM jsonb_array_elements(rows)r WHERE r->>'state'='selected'),
  'canApply',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rows)r WHERE r->>'state' IN ('ordered','used')),'readAt',read_time);
END $$;


ALTER FUNCTION public.preview_blueprint_hold_release(p_occasion bigint, p_organization bigint, p_unit bigint, p_spots bigint[], p_editor boolean) OWNER TO postgres;

--
-- Name: preview_blueprint_seat_block(bigint, bigint, bigint, bigint, bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_blueprint_seat_block(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_blocked boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];rev bigint;rows jsonb;
BEGIN
 IF p_blocked IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='block target required'; END IF;
 PERFORM public.check_blueprint_admin_scope_internal(p_occasion,p_organization,p_unit,true,true);
 SELECT layout_revision INTO rev FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 ids:=public.blueprint_block_selection_internal(p_occasion,p_blueprint,p_spots);
 rows:=public.blueprint_admin_seat_rows_internal(p_occasion,p_blueprint,ids);
 IF octet_length(rows::text)>1048576 THEN RAISE program_limit_exceeded USING MESSAGE='seat preview exceeds payload limit'; END IF;
 PERFORM public.check_blueprint_admin_scope_internal(p_occasion,p_organization,p_unit,true,true);
 RETURN jsonb_build_object('occasionId',p_occasion,'blueprintId',p_blueprint,'layoutRevision',rev,'requestedSpotIds',p_spots,
  'affectedSpotIds',ids,'blocked',p_blocked,'seats',rows,'canApply',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rows)r WHERE (r->>'canBlock')::boolean IS DISTINCT FROM true),'readAt',statement_timestamp());
END $$;


ALTER FUNCTION public.preview_blueprint_seat_block(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_blocked boolean) OWNER TO postgres;

--
-- Name: preview_blueprint_seat_order(bigint, bigint, bigint, bigint, bigint[], jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_blueprint_seat_order(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_input jsonb DEFAULT NULL::jsonb, p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[];affected bigint[];analysis jsonb;effect jsonb;quote jsonb;result jsonb;conflicts jsonb;items jsonb;failure text;
BEGIN
 IF p_editor IS NULL OR (p_input IS NOT NULL AND (jsonb_typeof(p_input)<>'object'
  OR octet_length(p_input::text)>(CASE WHEN p_editor THEN 4194304 ELSE 1048576 END))) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid order preview'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL) THEN
  RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 ids:=public.blueprint_seat_order_selection_internal(p_occasion,p_blueprint,p_spots,CASE WHEN p_editor THEN 20000 ELSE 1000 END);
 affected:=public.blueprint_order_affected_spots_internal(ids);
 IF cardinality(affected)>(CASE WHEN p_editor THEN 20000 ELSE 1000 END) THEN
  RAISE program_limit_exceeded USING MESSAGE='affected order seats exceed operation limit'; END IF;
 PERFORM public.check_blueprint_swap_scope_internal(p_occasion,affected);
 IF p_input IS NULL THEN
  BEGIN
   analysis:=public.analyze_new_order_spots(ids);
  EXCEPTION WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
   PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
   GET STACKED DIAGNOSTICS failure=PG_EXCEPTION_DETAIL;
   RETURN public.blueprint_order_rejection_internal(SQLERRM,failure);
  END;
  conflicts:=public.blueprint_order_conflicts_internal(analysis);
  SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',i->'spot_id','title',i->'spot_title','productTitle',i->'product_title',
   'amount',i->>'price','currencyCode',upper(btrim(i->>'currency'))) ORDER BY (i->>'spot_id')::bigint),'[]')
  INTO items FROM jsonb_array_elements(analysis->'new_order_items') i;
  result:=jsonb_build_object('code',200,'mode','requirements','actorId',auth.uid(),'occasionId',p_occasion,'blueprintId',p_blueprint,
   'requestedSpotIds',p_spots,'spotIds',ids,'affectedSpotIds',affected,'conflicts',conflicts,'items',items,
   'seatSubtotal',CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(analysis->'new_order_items') i WHERE i->>'price' IS NULL OR i->>'currency' IS NULL)
     THEN NULL ELSE analysis->>'total_price' END,'currencyCode',upper(btrim(analysis->>'currency')),
   'formKey',analysis#>'{order_form,key}','requiredFields',coalesce(analysis#>'{order_form,fields}','[]'),
   'phonePrefixes',analysis#>'{order_form,phone_prefixes}');
 ELSE
  -- The real creation/cancellation and queued side effects are all rolled back.
  -- Generated order/ticket IDs and email keys never enter the stable quote hash.
  BEGIN
   effect:=public.apply_blueprint_seat_order_internal(ids,p_input,extensions.gen_random_uuid());
   quote:=public.blueprint_seat_order_quote_internal(effect);
   RAISE SQLSTATE 'BP001' USING MESSAGE='rollback successful order quote';
  EXCEPTION WHEN SQLSTATE 'BP001' THEN NULL;
  WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
   PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
   GET STACKED DIAGNOSTICS failure=PG_EXCEPTION_DETAIL;
   RETURN public.blueprint_order_rejection_internal(SQLERRM,failure);
  END;
  result:=jsonb_build_object('code',200,'mode','quote','actorId',auth.uid(),'occasionId',p_occasion,'blueprintId',p_blueprint,
   'requestedSpotIds',p_spots,'confirmationHash',effect->>'confirmationHash','quote',quote,
   'conflicts',public.blueprint_order_conflicts_internal(effect->'analysis',quote->'orders'));
 END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF octet_length(result::text)>(CASE WHEN p_editor THEN 8388608 ELSE 1048576 END) THEN
  RAISE program_limit_exceeded USING MESSAGE='order preview exceeds payload limit'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.preview_blueprint_seat_order(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_input jsonb, p_editor boolean) OWNER TO postgres;

--
-- Name: preview_blueprint_seat_swap(bigint, bigint, bigint, bigint, bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_blueprint_seat_swap(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_first bigint, p_second bigint, p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE effect jsonb;rows jsonb;money jsonb;ids bigint[];
BEGIN
 IF p_editor IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='swap preview mode required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 -- The shared occasion advisory scope stabilizes membership. Row locks are
 -- acquired by the financial owner after form/order parents, never before them.
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL) THEN
  RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 ids:=public.blueprint_hold_selection_internal(p_occasion,p_blueprint,ARRAY[p_first,p_second],CASE WHEN p_editor THEN 20000 ELSE 1000 END);
 effect:=public.preview_blueprint_swap(p_first,p_second);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF (effect->>'code')::int<>200 THEN
  RETURN jsonb_build_object('code',409,'reason',CASE WHEN effect->>'reason'=ANY(ARRAY[
   'BLUEPRINT_UNIT_SIZE_MISMATCH','BLUEPRINT_SELECTION_UNIT_USED','BLUEPRINT_CURRENCY_MISMATCH',
   'STRIPE_ORDER_PRICE_IMMUTABLE','BLUEPRINT_SEAT_PROTECTED','SPOT_HELD'])
   THEN effect->>'reason' ELSE 'BLUEPRINT_SWAP_REJECTED' END);
 END IF;
 SELECT coalesce(jsonb_agg(CASE WHEN p_editor THEN s ELSE s-'customer' END ORDER BY (s->>'spotId')::bigint),'[]')
 INTO rows FROM jsonb_array_elements(effect->'sides') s;
 BEGIN
  money:=public.project_order_amount_changes_internal(effect->'orders');
 EXCEPTION WHEN check_violation THEN
  RETURN jsonb_build_object('code',409,'reason','BLUEPRINT_SWAP_MONEY_UNAVAILABLE');
 END;
 effect:=jsonb_build_object('code',200,'occasionId',p_occasion,'blueprintId',p_blueprint,
  'layoutRevision',effect#>'{blueprints,0,revision}','firstSpotId',p_first,'secondSpotId',p_second,
  'sourceSpotIds',effect->'sourceSpotIds','targetSpotIds',effect->'targetSpotIds',
  'confirmationHash',effect->>'confirmationHash','seats',rows,'orders',money);
 IF octet_length(effect::text)>(CASE WHEN p_editor THEN 8388608 ELSE 1048576 END) THEN
  RAISE program_limit_exceeded USING MESSAGE='swap preview exceeds payload limit'; END IF;
 RETURN effect;
END $$;


ALTER FUNCTION public.preview_blueprint_seat_swap(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_first bigint, p_second bigint, p_editor boolean) OWNER TO postgres;

--
-- Name: preview_blueprint_swap(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_blueprint_swap(p_spot_1 bigint, p_spot_2 bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb; occ bigint;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(p_spot_1,p_spot_2);
 IF occ IS NULL THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 BEGIN
  result:=public.apply_blueprint_seat_swap_internal(p_spot_1,p_spot_2);
  RAISE SQLSTATE 'BP001' USING MESSAGE='rollback successful swap preview';
 EXCEPTION WHEN SQLSTATE 'BP001' THEN NULL;
 WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
 WHEN OTHERS THEN result:=jsonb_build_object('code',409,'reason',SQLERRM,'issues',jsonb_build_array(jsonb_build_object('reason',SQLERRM)));
 END;
 RETURN result;
END $$;


ALTER FUNCTION public.preview_blueprint_swap(p_spot_1 bigint, p_spot_2 bigint) OWNER TO postgres;

