-- Name: preview_blueprint_ticket_cancellation(bigint, bigint, bigint, bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preview_blueprint_ticket_cancellation(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[]) RETURNS jsonb
