--
-- Name: publish_activities_client_sync_v1(bigint, uuid, bigint, jsonb, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_activities_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_activities_data jsonb, p_history_data jsonb, p_parent_history_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; graph jsonb; history jsonb; old_graph jsonb; previous_history jsonb; hid bigint; live_changed boolean; deleted int; impacts jsonb; replacements jsonb:='[]'; users uuid[];
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.can_write_activity_plan(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_activities_data IS NULL OR jsonb_typeof(p_activities_data)<>'array' OR p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_activities_data::text)>2097152 OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid activities aggregate'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.publish',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'activities',p_activities_data,'history',p_history_data,'parentHistoryId',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id,activities_data INTO latest,previous_history FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest,'historyId',latest)); END IF;
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_activities_data,true);
 IF graph IS DISTINCT FROM public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave') THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',400,jsonb_build_object('version',v,'latestPublishId',latest,'reason','graph_history_mismatch')); END IF;
 history:=public.activity_graph_history_internal_v1(graph); old_graph:=public.current_activity_graph_internal_v1(p_occasion);
 live_changed:=graph IS DISTINCT FROM old_graph OR latest IS NULL;
 IF NOT live_changed AND public.activity_history_graph_internal_v1(p_occasion,previous_history)=graph THEN
  deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
  IF deleted=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',false)); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',NULL,'operation','delete','changedFields',jsonb_build_array('draft'))),'{}','[]','[]',jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',NULL,'draftConsumed',true));
 END IF;
 SELECT ARRAY(SELECT DISTINCT (x->>'user')::uuid FROM jsonb_array_elements(old_graph||graph) a,LATERAL jsonb_array_elements(a->'assignments') x WHERE x->>'user' IS NOT NULL UNION SELECT actor) INTO users;
 PERFORM public.replace_activities_graph_internal_v1(p_occasion,graph);
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'PUBLISH',latest,'Published via application');
 deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text RETURNING version INTO v;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',u) ORDER BY u),'[]') INTO impacts FROM unnest(users) u JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u;
 replacements:=jsonb_build_array(jsonb_build_object('component','private_activity','userId',actor,'payload',(public.get_my_events_and_activities(p_occasion,true)->'data')));
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activities','entityId',p_occasion,'operation','publish','changedFields',jsonb_build_array('graph','history'))),'{}',impacts,'[]',jsonb_build_object('version',v,'historyId',hid,'latestPublishId',hid,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',deleted>0,'activities',graph),'{}','[]','user',NULL,replacements);
END $$;


ALTER FUNCTION public.publish_activities_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_activities_data jsonb, p_history_data jsonb, p_parent_history_id bigint) OWNER TO postgres;

--
-- Name: publish_news_client_sync_v1(bigint, boolean, text, boolean, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_news_client_sync_v1(p_occasion bigint, p_add_to_news boolean, p_news_message text, p_send_notification boolean, p_notification_heading text, p_notification_content text, p_recipients jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_notification uuid; v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_id bigint; v_version bigint:=0; v_entity jsonb; v_items jsonb:='[]'::jsonb;
  v_is_publishable boolean; v_response jsonb; v_required_revision bigint;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_news(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT o.organization,NOT o.is_hidden INTO v_organization,v_is_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_organization IS NULL OR NOT COALESCE(p_add_to_news,false)
      AND NOT COALESCE(p_send_notification,false)
    OR p_add_to_news AND (p_news_message IS NULL
      OR octet_length(p_news_message) NOT BETWEEN 1 AND 524288)
    OR p_send_notification AND (p_notification_content IS NULL
      OR octet_length(p_notification_content)>65536
      OR octet_length(COALESCE(p_notification_heading,''))>2048
      OR p_recipients IS NOT NULL AND (jsonb_typeof(p_recipients)<>'array'
        OR jsonb_array_length(p_recipients)>5000
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_recipients) value
          WHERE jsonb_typeof(value)<>'string'
            OR octet_length(value#>>'{}')>512))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news publication'; END IF;
  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false)
      AND NOT v_is_publishable THEN
    RAISE invalid_parameter_value
      USING MESSAGE='news push requires a publicly publishable occasion';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'addToNews',p_add_to_news,'newsMessage',p_news_message,
    'sendNotification',p_send_notification,'notificationHeading',p_notification_heading,
    'notificationContent',p_notification_content,'recipients',p_recipients)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.publish',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF coalesce(p_send_notification,false) THEN PERFORM public.charge_notification_intent_v1(p_occasion,v_actor,p_recipients,p_notification_heading,p_notification_content); END IF;
  IF COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.news(message,created_by,occasion)
      VALUES (p_news_message,v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
    SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.news n WHERE n.id=v_id;
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,'operation','insert','safeLabel','News',
      'changedFields',jsonb_build_array('message')));
  END IF;
  IF COALESCE(p_send_notification,false) THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','notification','entityId',NULL,'operation','publish',
      'safeLabel','Notification','changedFields',jsonb_build_array('delivery_request')));
  END IF;

  -- A notification-only test has no news publication to wait for.
  IF COALESCE(p_send_notification,false) AND NOT COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.log_notifications
      (occasion,organization,user_id,"to",heading,content,data,abuse_admitted_at)
    VALUES (p_occasion,v_organization,v_actor,p_recipients,
      p_notification_heading,p_notification_content,jsonb_build_object('path','news'),statement_timestamp()) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
  END IF;

  v_response:=public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.publish','content',v_items,
    CASE WHEN COALESCE(p_add_to_news,false) AND v_is_publishable
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'news',v_entity,
      'notificationQueued',COALESCE(p_send_notification,false)));

  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false) THEN
    SELECT c.resulting_revision INTO v_required_revision
    FROM public.client_commit_components c
    WHERE c.commit_id=(v_response#>>'{mutation,commitId}')::uuid
      AND c.component='content_catalog' AND c.scope_type='occasion'
      AND c.scope_id=p_occasion AND c.user_id IS NULL;
    IF v_required_revision IS NULL THEN
      RAISE EXCEPTION 'news publication did not produce a content revision';
    END IF;
    INSERT INTO public.news_notification_outbox
      (command_id,occasion,organization,user_id,required_content_revision,
       "to",heading,content,data,abuse_admitted_at)
    VALUES (p_command_id,p_occasion,v_organization,v_actor,v_required_revision,
      p_recipients,p_notification_heading,p_notification_content,
      jsonb_build_object('path','news'),statement_timestamp());
  END IF;
  RETURN v_response;
END; $$;


ALTER FUNCTION public.publish_news_client_sync_v1(p_occasion bigint, p_add_to_news boolean, p_news_message text, p_send_notification boolean, p_notification_heading text, p_notification_content text, p_recipients jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: publish_seating_transitions(uuid, uuid[], text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_seating_transitions(p_transition uuid, p_transition_ids uuid[], p_fingerprint text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; started jsonb; preview jsonb; ids uuid[]; f bigint;
BEGIN
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition;
 IF tr.id IS NULL OR NOT coalesce(public.can_author_forms(tr.occasion),false) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 IF cardinality(p_transition_ids) NOT BETWEEN 1 AND 256 THEN RAISE invalid_parameter_value USING MESSAGE='invalid publication cohort'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[tr.occasion]);
 started:=public.begin_client_mutation_v1(p_command_id,'seating.publication.publish',tr.occasion,auth.uid(),encode(extensions.digest(jsonb_build_array(p_transition,p_transition_ids,p_fingerprint)::text,'sha256'),'hex'));
 IF NOT coalesce(public.can_author_forms(tr.occasion),false) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 PERFORM 1 FROM public.forms WHERE occasion=tr.occasion ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.form_seating_transitions WHERE blueprint=tr.blueprint AND state='organizer_managed' ORDER BY id FOR UPDATE;
 SELECT array_agg(id ORDER BY id) INTO ids FROM public.form_seating_transitions WHERE blueprint=tr.blueprint AND state='organizer_managed';
 -- Freeze the full inventory/commercial closure before final semantic recheck.
 PERFORM public.lock_spot_assignment_scope_internal(
 ARRAY(SELECT s.id FROM eshop.spots s WHERE s.blueprint=tr.blueprint OR s.inventory_context IN(
 SELECT pic.inventory_context FROM eshop.product_inventory_contexts pic WHERE pic.product IN(
 SELECT product FROM eshop.spots WHERE blueprint=tr.blueprint UNION SELECT product FROM eshop.blueprint_area_bindings WHERE blueprint=tr.blueprint)) ORDER BY s.id),
 '{}'::bigint[],true,
 ARRAY(SELECT product FROM eshop.spots WHERE blueprint=tr.blueprint UNION SELECT product FROM eshop.blueprint_area_bindings WHERE blueprint=tr.blueprint),false,
 ARRAY(SELECT o.id FROM eshop.orders o WHERE o.form IN(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids)) ORDER BY o.id),
 ARRAY(SELECT x.id FROM eshop.order_product_ticket x JOIN eshop.orders o ON o.id=x."order" WHERE o.form IN(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids)) ORDER BY x.id));
 -- Existing expiry owner handles lifecycle; never cancel a waiting admission.
 FOR f IN SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids) ORDER BY form LOOP PERFORM public.expire_waitlist_form_internal(f); END LOOP;
 preview:=public.seating_publication_preview_internal(p_transition);
 IF preview->>'fingerprint' IS DISTINCT FROM p_fingerprint OR ids IS DISTINCT FROM ARRAY(SELECT x FROM unnest(p_transition_ids)x ORDER BY x) OR jsonb_array_length(preview->'blockers')>0 THEN
 RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','CONTEXT_CHANGED','blockers',preview->'blockers')); END IF;
 UPDATE public.form_seating_transitions SET state='published',revision=revision+1,finished_by=auth.uid(),finished_at=clock_timestamp() WHERE id=ANY(ids);
 UPDATE public.forms SET blueprint=tr.blueprint,participant_capacity=NULL,waitlist_enabled=false,waitlist_offer_duration_seconds=NULL,capacity_revision=capacity_revision+1,updated_at=clock_timestamp() WHERE id IN(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids));
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'form','occasion',tr.occasion,form::text,1 FROM public.form_seating_transitions WHERE id=ANY(ids)
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 PERFORM public.notification_center_form_capacity_internal(form) FROM public.form_seating_transitions WHERE id=ANY(ids);
 PERFORM public.notification_center_blueprint_capacity_internal(tr.blueprint);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,tr.occasion,'seating.publication.publish',
 jsonb_build_array(jsonb_build_object('entityType','form','entityId',NULL,'operation','update','safeLabel','Public seating enabled','changedFields',jsonb_build_array('seating','capacity'))),
 ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=tr.occasion),jsonb_build_object('transitionIds',ids,'sourceFormIds',ARRAY(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids)),'targetBlueprintId',tr.blueprint,'context',jsonb_set(public.get_seating_transition_context(tr.id)->'data','{items}','[]'::jsonb)));
END $$;


ALTER FUNCTION public.publish_seating_transitions(p_transition uuid, p_transition_ids uuid[], p_fingerprint text, p_command_id uuid) OWNER TO postgres;

--
-- Name: publish_unit_user_access_change_internal_v1(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_unit_user_access_change_internal_v1(p_commit_id uuid, p_unit bigint, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_occasion bigint; v_revision bigint;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.client_commits WHERE commit_id=p_commit_id AND unit=p_unit) THEN
  RAISE foreign_key_violation USING MESSAGE='organizer access fanout requires its commit'; END IF;
  FOR v_occasion IN SELECT ou.occasion FROM public.occasion_users ou
    JOIN public.occasions o ON o.id=ou.occasion
    WHERE o.unit=p_unit AND ou."user"=p_user ORDER BY ou.occasion LOOP
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('occasion_user','occasion',v_occasion,p_user::text,1)
    ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE SET
      version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
    INSERT INTO public.client_sync_private_scopes
      (component,occasion,user_id,source_revision)
    VALUES ('private_profile',v_occasion,p_user,1)
    ON CONFLICT (component,occasion,user_id) DO UPDATE SET
      source_revision=public.client_sync_private_scopes.source_revision+1,
      updated_at=now() RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (p_commit_id,'private_profile','occasion',v_occasion,
      p_user,v_revision);
  END LOOP;
END $$;


ALTER FUNCTION public.publish_unit_user_access_change_internal_v1(p_commit_id uuid, p_unit bigint, p_user uuid) OWNER TO postgres;

--
-- Name: publish_user_profile_change_internal_v1(uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_user_profile_change_internal_v1(p_user uuid, p_origin bigint, p_before jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint;
BEGIN
 IF p_before IS NOT DISTINCT FROM (SELECT to_jsonb(ui) FROM public.user_info ui WHERE id=p_user) THEN RETURN; END IF;
 FOR oc IN SELECT occasion FROM public.occasion_users WHERE "user"=p_user AND occasion IS DISTINCT FROM p_origin ORDER BY occasion LOOP
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion_user','occasion',oc,p_user::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  PERFORM public.impact_private_profile_users_v1(oc,ARRAY[p_user],'profile.global.changed');
  PERFORM public.impact_companion_owners_v1(oc,ARRAY[p_user],'profile.companion_identity.changed');
 END LOOP;
END $$;


ALTER FUNCTION public.publish_user_profile_change_internal_v1(p_user uuid, p_origin bigint, p_before jsonb) OWNER TO postgres;

--
-- Name: purge_expired_stripe_sources_internal(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_expired_stripe_sources_internal(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE removed integer;
BEGIN
 PERFORM public.require_service_role();
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'STRIPE_RECOVERY_LIMIT_INVALID'; END IF;
 WITH expired AS (
  SELECT token_hash FROM eshop.stripe_payment_link_sources WHERE expires_at<=clock_timestamp()
   ORDER BY expires_at,token_hash LIMIT p_limit FOR UPDATE SKIP LOCKED
 ) DELETE FROM eshop.stripe_payment_link_sources s USING expired e WHERE s.token_hash=e.token_hash;
 GET DIAGNOSTICS removed=ROW_COUNT;
 RETURN removed;
END $$;


ALTER FUNCTION public.purge_expired_stripe_sources_internal(p_limit integer) OWNER TO postgres;

--
-- Name: purge_hidden_notification_history_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_hidden_notification_history_internal(p_organization bigint) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids uuid[]; removed bigint;
BEGIN
 PERFORM public.notification_center_require_service();
 PERFORM pg_advisory_xact_lock(hashtextextended('notification-center-organization:'||p_organization,0));
 SELECT coalesce(array_agg(e.id),'{}'::uuid[]) INTO ids
 FROM public.notification_center_events e WHERE e.organization=p_organization
 AND NOT public.notification_center_subject_visible_internal(e.organization,e.kind,e.data);
 -- Remove references to the deleted projections while retaining source facts.
 UPDATE public.notification_center_source_state s SET state=s.state-'eventId'
 WHERE s.organization=p_organization AND s.state->>'eventId'=ANY(ids::text[]);
 UPDATE public.notification_center_source_state s SET state=s.state-'notificationId'
 WHERE s.organization=p_organization AND s.state->>'notificationId'=ANY(ids::text[]);
 DELETE FROM public.notification_center_read_batches b WHERE b.organization=p_organization
 AND b.group_key IN (SELECT 'event:'||id FROM unnest(ids) id);
 -- Recipient eligibility and delivery rows have ON DELETE CASCADE event FKs.
 DELETE FROM public.notification_center_events e WHERE e.organization=p_organization AND e.id=ANY(ids);
 GET DIAGNOSTICS removed=ROW_COUNT;
 RETURN removed;
END $$;


ALTER FUNCTION public.purge_hidden_notification_history_internal(p_organization bigint) OWNER TO postgres;

--
-- Name: queue_payment_reminders(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_payment_reminders(p_occasion_id bigint, p_seconds_before_deadline bigint) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.queue_payment_reminders_internal(p_occasion_id,NULL);
$$;


ALTER FUNCTION public.queue_payment_reminders(p_occasion_id bigint, p_seconds_before_deadline bigint) OWNER TO postgres;

--
-- Name: queue_payment_reminders_internal(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_payment_reminders_internal(p_occasion_id bigint, p_payment_info_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
-- NULL payment scope is reserved for explicit occasion-wide settings changes.
-- Checkout and deadline changes only replace reminders for their own payment.
BEGIN
  IF public.is_demo_occasion(p_occasion_id) THEN RETURN; END IF;

  UPDATE public.email_messages SET workflow_state='cancelled',last_error='reminder_superseded',lease_token=NULL,lease_until=NULL
  WHERE ((p_payment_info_id IS NULL AND occasion=p_occasion_id) OR order_id IN (SELECT id FROM eshop.orders WHERE payment_info IN (SELECT payment_info FROM eshop.orders WHERE occasion=p_occasion_id AND (p_payment_info_id IS NULL OR payment_info=p_payment_info_id)))) AND message_kind='order_reminder' AND workflow_state IN ('pending','retry_wait','blocked','preparing');
  UPDATE eshop.payment_info pi SET email_reminder_version=email_reminder_version+1
  WHERE EXISTS(SELECT 1 FROM eshop.orders o WHERE o.payment_info=pi.id AND o.occasion=p_occasion_id AND (p_payment_info_id IS NULL OR pi.id=p_payment_info_id));

  PERFORM public.enqueue_order_email('TICKET_ORDER_REMINDER',jsonb_build_object(
      'order_id', o.id
    ),occ.organization,o.occasion,occ.unit,pi.deadline - make_interval(secs=>coalesce((f.data->>'reminder_interval_seconds')::bigint,(form_settings.feature->>'reminder_interval_seconds')::bigint,86400))) FROM eshop.payment_info pi
  JOIN
    eshop.orders o ON pi.id = o.payment_info
  JOIN
    public.occasions occ ON o.occasion = occ.id

  LEFT JOIN LATERAL (
      SELECT elem AS feature
      FROM jsonb_array_elements(occ.features) elem
      WHERE elem->>'code' = 'form'
  ) form_settings ON TRUE

  LEFT JOIN public.forms f ON f.id = o.form
  WHERE
    o.payment_info IN (SELECT payment_info FROM eshop.orders WHERE occasion=p_occasion_id AND (p_payment_info_id IS NULL OR payment_info=p_payment_info_id))
    AND o.state = 'ordered'
    AND pi.data#>>'{payment_policy,mode}' IS DISTINCT FROM 'none'
    AND pi.deadline IS NOT NULL

    AND (pi.data->>'current_version_reminded')::boolean IS NOT TRUE

    AND (form_settings.feature->>'is_enabled')::boolean IS TRUE

    AND COALESCE((f.data->>'is_reminder_enabled')::boolean, (form_settings.feature->>'reminder_is_enabled')::boolean, TRUE) IS TRUE;

  PERFORM public.enqueue_order_email('TICKET_ORDER_REMINDER',jsonb_build_object(
      'order_id', o.id,
      'is_deposit_reminder', true
    ),occ.organization,o.occasion,occ.unit,(occ.start_time - make_interval(days => (deposit_settings.feature->>'deposit_deadline_days')::int)) - make_interval(secs=>coalesce((f.data->>'reminder_interval_seconds')::bigint,(form_settings.feature->>'reminder_interval_seconds')::bigint,86400))) FROM eshop.payment_info pi
  JOIN
    eshop.orders o ON pi.id = o.payment_info
  JOIN
    public.occasions occ ON o.occasion = occ.id

  LEFT JOIN LATERAL (
      SELECT elem AS feature
      FROM jsonb_array_elements(occ.features) elem
      WHERE elem->>'code' = 'deposit'
  ) deposit_settings ON TRUE

  LEFT JOIN LATERAL (
      SELECT elem AS feature
      FROM jsonb_array_elements(occ.features) elem
      WHERE elem->>'code' = 'form'
  ) form_settings ON TRUE
  LEFT JOIN public.forms f ON f.id = o.form
  WHERE
    o.payment_info IN (SELECT payment_info FROM eshop.orders WHERE occasion=p_occasion_id AND (p_payment_info_id IS NULL OR payment_info=p_payment_info_id))
    -- Schedule the balance reminder before deposit payment, as order creation always did.
    AND o.state IN ('ordered','paid')
    AND pi.data#>>'{payment_policy,mode}' IS DISTINCT FROM 'none'
    AND pi.deposit_amount IS NOT NULL
    AND coalesce(pi.paid,0) < pi.amount

    AND (deposit_settings.feature->>'is_enabled')::boolean IS TRUE

    AND (deposit_settings.feature->>'deposit_deadline') IS DISTINCT FROM 'on_site'

    AND (deposit_settings.feature->>'deposit_deadline_days') IS NOT NULL

    AND occ.start_time IS NOT NULL

    AND (form_settings.feature->>'is_enabled')::boolean IS TRUE
    AND COALESCE((f.data->>'is_reminder_enabled')::boolean, (form_settings.feature->>'reminder_is_enabled')::boolean, TRUE) IS TRUE;

END;
$$;


ALTER FUNCTION public.queue_payment_reminders_internal(p_occasion_id bigint, p_payment_info_id bigint) OWNER TO postgres;

--
-- Name: random_payment_reference_digits_internal(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.random_payment_reference_digits_internal(p_digits integer) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE value text:=''; bytes bytea; n integer; i integer;
BEGIN
 IF p_digits NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
 WHILE length(value)<p_digits LOOP
  bytes:=extensions.gen_random_bytes(32);
  FOR i IN 0..31 LOOP
   n:=get_byte(bytes,i);
   IF n>=250 OR (value='' AND mod(n,10)=0) THEN CONTINUE; END IF;
   value:=value||mod(n,10)::text;
   EXIT WHEN length(value)=p_digits;
  END LOOP;
 END LOOP;
 RETURN value::bigint;
END $$;


ALTER FUNCTION public.random_payment_reference_digits_internal(p_digits integer) OWNER TO postgres;

--
-- Name: random_public_link_internal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.random_public_link_internal() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE alphabet constant text := '23456789abcdefghjkmnpqrstuvwxyz'; result text := ''; b integer;
BEGIN
 -- Rejection sampling avoids modulo bias (31 symbols).
 WHILE length(result)<8 LOOP
  b := get_byte(extensions.gen_random_bytes(1),0);
  IF b < 248 THEN result := result || substr(alphabet,b % 31 + 1,1); END IF;
 END LOOP;
 RETURN result;
END $$;


ALTER FUNCTION public.random_public_link_internal() OWNER TO postgres;

--
-- Name: read_checkout_origin_internal(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_checkout_origin_internal(p_context text, p_form bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE parts text[]; expected bytea; supplied bytea; payload jsonb; stamp bigint:=extract(epoch FROM statement_timestamp())::bigint;
BEGIN
 IF p_context IS NULL THEN RETURN NULL; END IF;
 IF length(p_context)>2048 OR p_context !~ '^[A-Za-z0-9_-]+\.[0-9a-f]{64}$' THEN RETURN NULL; END IF;
 parts:=string_to_array(p_context,'.');
 SELECT extensions.hmac(convert_to(parts[1],'UTF8'),secret,'sha256') INTO STRICT expected
  FROM eshop.checkout_origin_signing_key WHERE singleton;
 supplied:=decode(parts[2],'hex');
 -- Hash before comparing so equality timing reveals no HMAC prefix.
 IF extensions.digest(supplied,'sha256')<>extensions.digest(expected,'sha256') THEN RETURN NULL; END IF;
 payload:=convert_from(decode(translate(parts[1],'-_','+/')||repeat('=',(4-length(parts[1])%4)%4),'base64'),'UTF8')::jsonb;
 IF payload->>'v'<>'1' OR payload->>'channel'<>'wix'
  OR (payload->>'formId')::bigint IS DISTINCT FROM p_form
  OR (payload->>'expiresAt')::bigint<=stamp OR (payload->>'verifiedAt')::bigint>stamp+60
  OR (payload->>'expiresAt')::bigint-(payload->>'verifiedAt')::bigint<>86400
  OR (payload->>'instanceId')::uuid IS NULL OR (payload->>'siteId')::uuid IS NULL THEN RETURN NULL; END IF;
 RETURN payload;
EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire OR numeric_value_out_of_range THEN RETURN NULL;
END $_$;


ALTER FUNCTION public.read_checkout_origin_internal(p_context text, p_form bigint) OWNER TO postgres;

--
-- Name: read_order_identity(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_order_identity(p_order bigint, p_occasion bigint, p_organization bigint) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN (SELECT o.order_symbol FROM eshop.orders o
        JOIN public.occasions oc ON oc.id=o.occasion
        WHERE o.id=p_order AND o.occasion=p_occasion AND oc.organization=p_organization);
END;
$$;


