--
-- Name: reconcile_email_events(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_email_events() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_event record;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 WITH matched AS (UPDATE public.email_delivery_events e SET message_id=m.message_id FROM public.email_messages m
 WHERE e.message_id IS NULL AND lower(e.recipient)=lower(m.recipient)
 AND (m.provider_message_id=e.provider_message_id OR EXISTS(SELECT 1 FROM public.email_attempts a WHERE a.message_id=m.message_id AND a.attempt_id=e.attempt_id AND a.state IN ('sending','unknown','accepted'))) RETURNING e.message_id)
 UPDATE public.email_messages m SET feedback_pending=true WHERE m.message_id IN (SELECT message_id FROM matched);
 FOR v_event IN SELECT message_id,min(provider_time) FILTER(WHERE event_type='delivery') delivery,
 min(provider_time) FILTER(WHERE event_type='bounce') bounce,min(provider_time) FILTER(WHERE event_type='complaint') complaint,
 min(provider_time) FILTER(WHERE event_type='open') opened,min(provider_time) FILTER(WHERE event_type='click') clicked,
 min(provider_time) FILTER(WHERE event_type IN ('send','delivery','open','click','bounce','complaint','delay')) accepted,
 min(provider_message_id) provider_id,max(event_type) FILTER(WHERE event_type IN ('reject','rendering_failure','delay')) failure
 FROM public.email_delivery_events WHERE message_id IN (SELECT message_id FROM public.email_messages WHERE workflow_state IN ('sending','unknown') OR feedback_pending) GROUP BY message_id LOOP
  UPDATE public.email_messages SET delivered_at=least(delivered_at,v_event.delivery),bounced_at=least(bounced_at,v_event.bounce),complained_at=least(complained_at,v_event.complaint),
   opened_at=CASE WHEN tracking_policy<>'disabled' THEN least(opened_at,v_event.opened) ELSE NULL END,
   clicked_at=CASE WHEN tracking_policy='engagement' THEN least(clicked_at,v_event.clicked) ELSE NULL END,provider_failure=v_event.failure,
   accepted_at=coalesce(accepted_at,v_event.accepted),provider_message_id=coalesce(provider_message_id,v_event.provider_id),
   workflow_state=CASE WHEN v_event.accepted IS NOT NULL AND workflow_state IN ('sending','unknown') THEN 'accepted' ELSE workflow_state END,feedback_pending=false
  WHERE message_id=v_event.message_id;
  PERFORM public.notification_center_email_internal(v_event.message_id);
  UPDATE public.email_attempts SET state='accepted',provider_message_id=v_event.provider_id,finished_at=coalesce(finished_at,now())
  WHERE message_id=v_event.message_id AND state IN ('sending','unknown') AND v_event.accepted IS NOT NULL;
 INSERT INTO public.email_suppressions(recipient,reason)
 SELECT lower(recipient),CASE WHEN bool_or(event_type='complaint') THEN 'complaint' ELSE 'hard_bounce' END
 FROM public.email_delivery_events WHERE message_id=v_event.message_id AND (event_type='complaint' OR (event_type='bounce' AND hard_bounce))
 GROUP BY lower(recipient)
 ON CONFLICT(recipient) DO UPDATE SET reason=CASE WHEN email_suppressions.reason='complaint' THEN 'complaint' ELSE excluded.reason END;
 END LOOP;
END $$;


ALTER FUNCTION public.reconcile_email_events() OWNER TO postgres;

--
-- Name: reconcile_order_payment_internal_v1(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_order_payment_internal_v1(p_order_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_order eshop.orders;
    v_payment eshop.payment_info;
    v_eligible boolean;
    v_was_eligible boolean;
    v_transition jsonb;
    v_final_state text;
    v_final_version bigint;
    v_promote boolean;
BEGIN
    IF p_reason IS NULL OR p_reason NOT IN ('payment_fact','product_edit') THEN
        RAISE EXCEPTION 'INVALID_PAYMENT_RECONCILIATION_REASON';
    END IF;
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
    SELECT * INTO v_order FROM eshop.orders WHERE id=p_order_id FOR UPDATE;
    SELECT * INTO v_payment FROM eshop.payment_info WHERE id=v_order.payment_info FOR UPDATE;
    v_was_eligible := coalesce(v_order.state IN ('paid','sent'),false);
    -- Provider facts and non-admission shells retain their existing owners.
    IF v_payment.id IS NULL OR public.payment_method_is_online_internal(v_payment.payment_method)
       OR v_order.state NOT IN ('created','ordered','expired','paid','sent') THEN
        RETURN jsonb_build_object('previous_state',v_order.state,'final_state',v_order.state,
            'eligibility_changed',false,'email_payment_version',v_order.email_payment_version);
    END IF;

    IF p_reason='product_edit' THEN
        PERFORM public.ensure_order_payment_instructions_internal(p_order_id);
        SELECT * INTO v_payment FROM eshop.payment_info WHERE id=v_order.payment_info;
    END IF;

    -- The saved deposit is a commercial snapshot, capped by the current price.
    v_eligible := coalesce(v_order.price,0)<=0 OR coalesce(v_payment.paid,0)>=
        least(coalesce(v_payment.deposit_amount,v_order.price),v_order.price);
    v_promote := v_eligible AND NOT v_was_eligible;

    IF p_reason='product_edit' OR v_eligible IS DISTINCT FROM v_was_eligible THEN
        PERFORM public.cancel_order_email_intents(p_order_id);
        -- The paid primitive owns the single version bump when promoting.
        IF NOT v_promote THEN
            UPDATE eshop.orders SET email_payment_version=email_payment_version+1,updated_at=now()
            WHERE id=p_order_id;
        END IF;
    END IF;

    IF v_promote THEN
        -- Reuse the existing atomic primitive and delivery boundary. A failed
        -- receipt must abort its outer pairing or receipted product command.
        v_transition := public.update_order_and_tickets_to_paid(p_order_id);
        IF v_transition->>'code' IS DISTINCT FROM '200' THEN
            RAISE EXCEPTION 'ORDER_PAID_TRANSITION_FAILED: %',
                coalesce(v_transition->>'message','invalid transition receipt');
        END IF;
    ELSIF NOT v_eligible AND v_was_eligible THEN
        UPDATE eshop.orders SET state='ordered',updated_at=now() WHERE id=p_order_id;
        UPDATE eshop.tickets t SET state='ordered',updated_at=now()
        FROM eshop.order_product_ticket opt
        WHERE opt.ticket=t.id AND opt."order"=p_order_id AND t.state IN ('paid','sent');
    ELSIF p_reason='product_edit' THEN
        -- An eligible paid order needs the edited content at its final version.
        -- Already sent admission stays sent; used/cancelled tickets stay intact.
        PERFORM public.enqueue_paid_order_tickets(p_order_id);
    END IF;

    -- Cancellation above invalidates the old reminder version. Rebuild only this
    -- payment's eligible reminders, including the balance after a paid deposit.
    IF p_reason='product_edit' OR v_eligible IS DISTINCT FROM v_was_eligible THEN
        PERFORM public.queue_payment_reminders_internal(v_order.occasion,v_payment.id);
    END IF;

    PERFORM public.notification_center_order_state_internal(p_order_id);
    SELECT state,email_payment_version INTO v_final_state,v_final_version FROM eshop.orders WHERE id=p_order_id;
    RETURN jsonb_build_object('previous_state',v_order.state,'final_state',v_final_state,
        'eligibility_changed',v_eligible IS DISTINCT FROM v_was_eligible,
        'email_payment_version',v_final_version);
END;
$$;


ALTER FUNCTION public.reconcile_order_payment_internal_v1(p_order_id bigint, p_reason text) OWNER TO postgres;

--
-- Name: reconcile_unknown_email(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_unknown_email(p_message uuid, p_decision text, p_evidence text, p_provider_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE m public.email_messages;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 IF p_evidence IS NULL OR length(p_evidence)<10 OR p_decision NOT IN ('accepted','known_not_accepted','cancelled') THEN RAISE EXCEPTION 'reconciliation_evidence_required'; END IF;
 SELECT * INTO m FROM public.email_messages WHERE message_id=p_message FOR UPDATE;
 IF m.workflow_state<>'unknown' THEN RAISE EXCEPTION 'email_not_unknown'; END IF;
 IF p_decision='accepted' AND p_provider_id IS NULL THEN RAISE EXCEPTION 'provider_receipt_required'; END IF;
 UPDATE public.email_messages SET workflow_state=CASE p_decision WHEN 'accepted' THEN 'accepted' WHEN 'known_not_accepted' THEN 'pending' ELSE 'cancelled' END,
 accepted_at=CASE WHEN p_decision='accepted' THEN now() ELSE accepted_at END,provider_message_id=coalesce(p_provider_id,provider_message_id),
 target_time=now(),lease_token=NULL,lease_until=NULL,post_action=post_action||jsonb_build_object('reconciliation',jsonb_build_object('decision',p_decision,'evidence',left(p_evidence,256),'at',now()))
 WHERE message_id=p_message;
 PERFORM public.wake_email_worker();
END $$;


ALTER FUNCTION public.reconcile_unknown_email(p_message uuid, p_decision text, p_evidence text, p_provider_id text) OWNER TO postgres;

--
-- Name: reconcile_wix_billing_delivery(uuid, text, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_wix_billing_delivery(p_app uuid, p_receipt text, p_kind text, p_attempt uuid, p_digest text, p_resolution text, p_evidence_reference text, p_operator_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE row public.wix_billing_deliveries;
BEGIN
 PERFORM public.require_service_role();
 IF p_resolution IS NULL OR p_resolution NOT IN('accepted','proven-not-accepted')
  OR coalesce(length(btrim(p_evidence_reference)),0) NOT BETWEEN 1 AND 1000
  OR coalesce(length(btrim(p_operator_reference)),0) NOT BETWEEN 1 AND 1000 THEN
  RAISE invalid_parameter_value USING MESSAGE='WIX_RECONCILIATION_EVIDENCE_REQUIRED'; END IF;
 SELECT * INTO STRICT row FROM public.wix_billing_deliveries WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind FOR UPDATE;
 IF row.state NOT IN('unknown','rejected') OR row.attempt_id IS DISTINCT FROM p_attempt OR row.payload_digest IS DISTINCT FROM p_digest THEN
  RAISE check_violation USING MESSAGE='WIX_RECONCILIATION_FENCE'; END IF;
 UPDATE public.wix_billing_deliveries SET state=CASE WHEN p_resolution='accepted' THEN 'confirmed' ELSE 'prepared' END,
  reconciliation=reconciliation||jsonb_build_array(jsonb_build_object('attemptId',p_attempt,'digest',p_digest,'resolution',p_resolution,
   'evidenceReference',p_evidence_reference,'operatorReference',p_operator_reference,'at',clock_timestamp()))
  WHERE app_id=p_app AND receipt_id=p_receipt AND kind=p_kind;
 RETURN jsonb_build_object('state',CASE WHEN p_resolution='accepted' THEN 'confirmed' ELSE 'prepared' END);
END $$;


ALTER FUNCTION public.reconcile_wix_billing_delivery(p_app uuid, p_receipt text, p_kind text, p_attempt uuid, p_digest text, p_resolution text, p_evidence_reference text, p_operator_reference text) OWNER TO postgres;

--
-- Name: record_account_deletion_sync_v1(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_account_deletion_sync_v1(p_user uuid, p_organization bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_commit public.client_commits%ROWTYPE; v_occasion bigint;
  v_revision bigint; v_event bigint; v_member uuid;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_user IS NULL OR p_organization IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_info ui
    WHERE ui.id=p_user AND ui.organization=p_organization) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid account deletion sync scope';
  END IF;
  FOR v_occasion IN SELECT DISTINCT dependency.occasion FROM (
 SELECT occasion FROM public.occasion_users WHERE "user"=p_user
 UNION SELECT gi.occasion FROM public.user_groups g JOIN public.user_group_info gi ON gi.id=g."group" WHERE g."user"=p_user
 UNION SELECT a.occasion FROM public.activity_assignments x JOIN public.activities a ON a.id=x.activity_id WHERE x."user"=p_user
 UNION SELECT occasion_id FROM public.activity_history WHERE user_id=p_user
) dependency JOIN public.occasions o ON o.id=dependency.occasion WHERE o.organization=p_organization ORDER BY dependency.occasion LOOP
    PERFORM public.lock_activity_aggregate_internal_v1(v_occasion);
  END LOOP;
  INSERT INTO public.client_commits
    (organization,actor_id,actor_display,actor_kind,source,change_class,reason)
  VALUES (p_organization,p_user,NULL,'service','account.delete','profile',
    'confirmed account deletion') RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'user',p_user::text,'delete',NULL,
    ARRAY['membership','profile','private_data']);
  FOR v_occasion IN SELECT DISTINCT dependency.occasion FROM (
 SELECT occasion FROM public.occasion_users WHERE "user"=p_user
 UNION SELECT gi.occasion FROM public.user_groups g JOIN public.user_group_info gi ON gi.id=g."group" WHERE g."user"=p_user
 UNION SELECT a.occasion FROM public.activity_assignments x JOIN public.activities a ON a.id=x.activity_id WHERE x."user"=p_user
 UNION SELECT occasion_id FROM public.activity_history WHERE user_id=p_user
) dependency JOIN public.occasions o ON o.id=dependency.occasion WHERE o.organization=p_organization ORDER BY dependency.occasion LOOP
    IF EXISTS (SELECT 1 FROM public.event_users eu JOIN public.events e
        ON e.id=eu.event WHERE eu."user"=p_user AND e.occasion=v_occasion)
      OR EXISTS (SELECT 1 FROM public.event_users_saved es JOIN public.events e
        ON e.id=es.event WHERE es."user"=p_user AND e.occasion=v_occasion) THEN
      INSERT INTO public.client_sync_scopes
        (component,scope_type,scope_id,source_revision)
      VALUES ('live_public','occasion',v_occasion,1)
      ON CONFLICT (component,scope_type,scope_id) DO UPDATE SET
        source_revision=public.client_sync_scopes.source_revision+1,
        updated_at=now() RETURNING source_revision INTO v_revision;
      INSERT INTO public.client_commit_components
        (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
      VALUES (v_commit.commit_id,'live_public','occasion',v_occasion,NULL,v_revision);
      FOR v_event IN SELECT DISTINCT id FROM (
        SELECT eu.event id FROM public.event_users eu JOIN public.events e
          ON e.id=eu.event WHERE eu."user"=p_user AND e.occasion=v_occasion
        UNION SELECT es.event FROM public.event_users_saved es JOIN public.events e
          ON e.id=es.event WHERE es."user"=p_user AND e.occasion=v_occasion
      ) affected ORDER BY id LOOP
        INSERT INTO public.client_projection_dirty_keys
          (component,scope_type,scope_id,entity_id,source_revision)
        VALUES ('live_public','occasion',v_occasion,v_event,v_revision)
        ON CONFLICT (component,scope_type,scope_id,entity_id) DO UPDATE SET
          source_revision=EXCLUDED.source_revision,dirty_since=now(),
          claimed_at=NULL,claim_token=NULL;
      END LOOP;
    END IF;
    IF EXISTS(SELECT 1 FROM public.activity_assignments aa JOIN public.activities a ON a.id=aa.activity_id WHERE a.occasion=v_occasion AND aa."user"=p_user) OR EXISTS(SELECT 1 FROM public.activity_history WHERE occasion_id=v_occasion AND user_id=p_user AND history_type='PUBLISH') THEN
      UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_occasion::text;
      FOR v_member IN SELECT "user" FROM public.occasion_users WHERE occasion=v_occasion AND "user"<>p_user ORDER BY "user" LOOP
        INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision) VALUES('private_activity',v_occasion,v_member,1) ON CONFLICT(component,occasion,user_id) DO UPDATE SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp() RETURNING source_revision INTO v_revision;
        INSERT INTO public.client_commit_components(commit_id,component,scope_type,scope_id,user_id,resulting_revision) VALUES(v_commit.commit_id,'private_activity','occasion',v_occasion,v_member,v_revision);
      END LOOP;
    END IF;
    FOR v_member IN SELECT ou."user" FROM public.occasion_users ou
      WHERE ou.occasion=v_occasion AND ou."user"<>p_user ORDER BY ou."user" LOOP
      INSERT INTO public.client_sync_private_scopes
        (component,occasion,user_id,source_revision)
      VALUES ('private_profile',v_occasion,v_member,1)
      ON CONFLICT (component,occasion,user_id) DO UPDATE SET
        source_revision=public.client_sync_private_scopes.source_revision+1,
        updated_at=now() RETURNING source_revision INTO v_revision;
      INSERT INTO public.client_commit_components
        (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
      VALUES (v_commit.commit_id,'private_profile','occasion',v_occasion,
        v_member,v_revision);
    END LOOP;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='user_group'
      AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id IN (
        SELECT ug."group"::text FROM public.user_groups ug
        WHERE ug."user"=p_user);
  END LOOP;
  RETURN v_commit.commit_id;
END; $$;


ALTER FUNCTION public.record_account_deletion_sync_v1(p_user uuid, p_organization bigint) OWNER TO postgres;

--
-- Name: record_bank_sync_health(bigint, bigint, timestamp with time zone, text, boolean, boolean, boolean, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_bank_sync_health(p_organization_id bigint, p_connection_id bigint, p_success_at timestamp with time zone, p_error text, p_ingest_enabled boolean, p_polling_enabled boolean, p_token_present boolean, p_observation_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_connection eshop.bank_sync_connections; v_code text; v_new_incident boolean;
BEGIN
  PERFORM public.require_service_role();
  SELECT c.* INTO STRICT v_connection FROM eshop.bank_sync_connections c
    WHERE c.id=p_connection_id AND EXISTS (SELECT 1 FROM eshop.unit_bank_accounts ub JOIN public.units u ON u.id=ub.unit
      WHERE u.organization=p_organization_id AND (ub.bank_account=c.bank_account_id OR ub.bank_account IN
        (SELECT a.bank_account_id FROM eshop.bank_sync_account_aliases a WHERE a.connection_id=c.id))) FOR UPDATE;
  IF p_error IS NOT NULL AND p_error NOT IN ('fio_token_invalid_or_inactive','fio_receiving_account_mismatch','bank_sync_retry_required',
    'fio_temporarily_unavailable','bank_sync_unavailable') THEN
    RAISE EXCEPTION 'BANK_SYNC_HEALTH_ERROR_INVALID';
  END IF;
  IF NOT public.record_bank_sync_pull(p_connection_id,p_success_at,p_error,p_observation_id) THEN RETURN; END IF;
  INSERT INTO eshop.bank_sync_health(connection_id,checked_at,ingest_enabled,polling_enabled,token_present)
    VALUES(p_connection_id,now(),p_ingest_enabled,p_polling_enabled,p_token_present)
    ON CONFLICT(connection_id) DO UPDATE SET checked_at=now(),
      ingest_enabled=COALESCE(EXCLUDED.ingest_enabled,eshop.bank_sync_health.ingest_enabled),
      polling_enabled=COALESCE(EXCLUDED.polling_enabled,eshop.bank_sync_health.polling_enabled),
      token_present=COALESCE(EXCLUDED.token_present,eshop.bank_sync_health.token_present);
  IF v_connection.mode='email' AND v_connection.state='degraded' AND p_error IS NULL AND p_ingest_enabled IS TRUE THEN
    UPDATE eshop.bank_sync_connections SET state='connected' WHERE id=p_connection_id;
  END IF;
  v_code:=CASE WHEN v_connection.state IN ('connected','degraded') THEN public.bank_sync_problem(p_connection_id) END;
  -- Preserve the outage clock across changing retry symptoms. An actionable
  -- fault starts its own incident so a prior availability warning cannot hide it.
  SELECT (public.bank_sync_requires_action(v_code) IS DISTINCT FROM public.bank_sync_requires_action(warning_code))
    OR (public.bank_sync_requires_action(v_code) AND v_code IS DISTINCT FROM warning_code)
    INTO v_new_incident FROM eshop.bank_sync_health WHERE connection_id=p_connection_id;
  UPDATE eshop.bank_sync_health SET warning_code=v_code,
    warning_since=CASE WHEN v_code IS NULL THEN NULL WHEN v_new_incident THEN now() ELSE COALESCE(warning_since,now()) END,
    incident_id=CASE WHEN v_code IS NULL THEN NULL WHEN v_new_incident THEN gen_random_uuid() ELSE COALESCE(incident_id,gen_random_uuid()) END,
    notified_at=CASE WHEN v_code IS NULL OR v_new_incident THEN NULL ELSE notified_at END WHERE connection_id=p_connection_id;
END;
$$;


ALTER FUNCTION public.record_bank_sync_health(p_organization_id bigint, p_connection_id bigint, p_success_at timestamp with time zone, p_error text, p_ingest_enabled boolean, p_polling_enabled boolean, p_token_present boolean, p_observation_id bigint) OWNER TO postgres;

--
-- Name: record_bank_sync_pull(bigint, timestamp with time zone, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_bank_sync_pull(p_id bigint, p_success_at timestamp with time zone, p_error text, p_observation_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.require_service_role();
  IF p_observation_id IS NULL OR p_observation_id<=0 THEN RAISE EXCEPTION 'BANK_SYNC_OBSERVATION_REQUIRED'; END IF;
  UPDATE eshop.bank_sync_connections SET observation_id=p_observation_id,
    bank_pull_at=GREATEST(p_success_at,bank_pull_at),last_error=left(p_error,256),
    failure_since=CASE WHEN p_error IS NULL THEN NULL
      WHEN last_error IS NULL OR (p_success_at IS NOT NULL AND (bank_pull_at IS NULL OR p_success_at>bank_pull_at)) THEN now()
      ELSE COALESCE(failure_since,now()) END,
    failure_observed_at=CASE WHEN p_error IS NOT NULL THEN now() END,
    state=CASE WHEN state IN ('connected','degraded') THEN
      CASE WHEN p_error IS NOT NULL THEN 'degraded' WHEN p_success_at IS NOT NULL THEN 'connected' ELSE state END
      ELSE state END WHERE id=p_id AND observation_id<p_observation_id;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.record_bank_sync_pull(p_id bigint, p_success_at timestamp with time zone, p_error text, p_observation_id bigint) OWNER TO postgres;

--
-- Name: record_client_sync_commit_v1(bigint, text, text, jsonb, text[], jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_client_sync_commit_v1(p_occasion bigint, p_source text, p_change_class text, p_items jsonb, p_public_components text[], p_private_impacts jsonb DEFAULT '[]'::jsonb, p_dirty_keys jsonb DEFAULT '[]'::jsonb, p_actor_kind text DEFAULT 'user'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_commit public.client_commits%ROWTYPE;
  v_component text;
  v_revision bigint;
  v_item jsonb;
  v_index integer := 0;
  v_user uuid := auth.uid();
  v_dirty jsonb;
  v_private jsonb;
  v_private_user uuid;
BEGIN
  IF p_actor_kind='user' THEN
    IF v_user IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_info ui
      WHERE ui.id=v_user) THEN
      RAISE insufficient_privilege USING MESSAGE='authenticated actor required';
    END IF;
  ELSIF p_actor_kind IN ('service','break_glass','system') THEN
    PERFORM public.require_client_sync_service_role_v1();
    IF p_actor_kind='break_glass' AND nullif(btrim(p_reason),'') IS NULL THEN
      RAISE EXCEPTION 'break-glass reason is required';
    END IF;
  ELSE
    IF p_actor_kind<>'unknown' OR v_user IS NOT NULL THEN
      RAISE insufficient_privilege USING MESSAGE='unsupported commit actor';
    END IF;
  END IF;
  INSERT INTO public.client_commits
    (occasion, actor_id, actor_display, actor_kind, source, change_class,
     reason)
  SELECT p_occasion, v_user,
    nullif(concat_ws(' ', ui.name, ui.surname), ''), p_actor_kind, p_source,
    p_change_class, p_reason
  FROM (SELECT 1) seed LEFT JOIN public.user_info ui ON ui.id = v_user
  RETURNING * INTO v_commit;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]')) LOOP
    INSERT INTO public.client_commit_items
      (commit_id, item_index, entity_type, entity_id, operation, safe_label, changed_fields)
    VALUES (v_commit.commit_id, v_index, v_item->>'entityType', v_item->>'entityId',
      v_item->>'operation', left(v_item->>'safeLabel', 240),
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_item->'changedFields','[]'))));
    v_index := v_index + 1;
  END LOOP;

  FOREACH v_component IN ARRAY COALESCE(p_public_components, '{}') LOOP
    INSERT INTO public.client_sync_scopes(component, scope_type, scope_id, source_revision)
    VALUES (v_component, 'occasion', p_occasion, 1)
    ON CONFLICT (component, scope_type, scope_id) DO UPDATE
      SET source_revision = public.client_sync_scopes.source_revision + 1,
          updated_at = now()
    RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id, component, scope_type, scope_id, user_id, resulting_revision)
    VALUES (v_commit.commit_id, v_component, 'occasion', p_occasion,
      NULL, v_revision);
    IF v_component<>'live_public' OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(COALESCE(p_dirty_keys,'[]')) impact
      WHERE impact->>'component'=v_component) THEN
      INSERT INTO public.client_projection_dirty_keys
        (component, scope_type, scope_id, entity_id, source_revision)
      VALUES (v_component, 'occasion', p_occasion, 0, v_revision)
      ON CONFLICT (component, scope_type, scope_id, entity_id) DO UPDATE
        SET source_revision = EXCLUDED.source_revision, dirty_since = now(),
            claimed_at = NULL, claim_token = NULL;
    END IF;
  END LOOP;

  FOR v_private IN SELECT DISTINCT value
    FROM jsonb_array_elements(COALESCE(p_private_impacts,'[]')) LOOP
      v_component:=v_private->>'component';
      v_private_user:=(v_private->>'userId')::uuid;
      IF v_component NOT LIKE 'private\_%' OR NOT EXISTS (
        SELECT 1 FROM public.occasion_users ou
        WHERE ou.occasion=p_occasion AND ou."user"=v_private_user) THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid private sync impact';
      END IF;
      INSERT INTO public.client_sync_private_scopes(component, occasion, user_id, source_revision)
      VALUES (v_component, p_occasion, v_private_user, 1)
      ON CONFLICT (component, occasion, user_id) DO UPDATE
        SET source_revision = public.client_sync_private_scopes.source_revision + 1,
            updated_at = now()
      RETURNING source_revision INTO v_revision;
      INSERT INTO public.client_commit_components
        (commit_id, component, scope_type, scope_id, user_id, resulting_revision)
      VALUES (v_commit.commit_id, v_component, 'occasion', p_occasion,
        v_private_user, v_revision);
  END LOOP;

  FOR v_dirty IN SELECT value FROM jsonb_array_elements(COALESCE(p_dirty_keys, '[]')) LOOP
    INSERT INTO public.client_projection_dirty_keys
      (component, scope_type, scope_id, entity_id, source_revision)
    VALUES (v_dirty->>'component', 'occasion', p_occasion,
      (v_dirty->>'entityId')::bigint, COALESCE((v_dirty->>'revision')::bigint,
        (SELECT s.source_revision FROM public.client_sync_scopes s
         WHERE s.component=v_dirty->>'component' AND s.scope_type='occasion'
           AND s.scope_id=p_occasion),0))
    ON CONFLICT (component, scope_type, scope_id, entity_id) DO UPDATE
      SET source_revision = GREATEST(public.client_projection_dirty_keys.source_revision,
          EXCLUDED.source_revision), dirty_since = now(), claimed_at = NULL, claim_token = NULL;
  END LOOP;

  RETURN jsonb_build_object('commitId', v_commit.commit_id,
    'occurredAt', v_commit.occurred_at);
END;
$$;


ALTER FUNCTION public.record_client_sync_commit_v1(p_occasion bigint, p_source text, p_change_class text, p_items jsonb, p_public_components text[], p_private_impacts jsonb, p_dirty_keys jsonb, p_actor_kind text, p_reason text) OWNER TO postgres;

