-- Name: record_email_event(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_email_event(p_event jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM public.record_email_events(jsonb_build_array(p_event));
END $$;


ALTER FUNCTION public.record_email_event(p_event jsonb) OWNER TO postgres;

--
-- Name: record_email_events(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_email_events(p_events jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 IF jsonb_typeof(p_events)<>'array' OR jsonb_array_length(p_events)>100 THEN RAISE EXCEPTION 'invalid_event_batch'; END IF;
 INSERT INTO public.email_delivery_events(event_key,provider_message_id,attempt_id,recipient,event_type,provider_time,hard_bounce,invalid_recipient)
 SELECT e->>'key',e->>'provider_id',(e->>'attempt_id')::uuid,e->>'recipient',e->>'type',(e->>'time')::timestamptz,coalesce((e->>'hard_bounce')::boolean,false),coalesce((e->>'invalid_recipient')::boolean,false)
 FROM jsonb_array_elements(p_events) e ON CONFLICT(event_key) DO NOTHING;
 PERFORM public.reconcile_email_events();
END $$;


ALTER FUNCTION public.record_email_events(p_events jsonb) OWNER TO postgres;

--
-- Name: record_form_conversion_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_form_conversion_internal(p_order bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE o eshop.orders; s jsonb; items jsonb; total numeric; payload jsonb; identity uuid:=gen_random_uuid(); brand text;
BEGIN
 SELECT * INTO o FROM eshop.orders WHERE id=p_order;
 s:=public.form_measurement_status_internal(o.form);
 IF s->'requested_enabled' IS DISTINCT FROM 'true'::jsonb OR s->'organization_allowed' IS DISTINCT FROM 'true'::jsonb OR s->'organization_enabled' IS DISTINCT FROM 'true'::jsonb OR s->'unit_enabled' IS DISTINCT FROM 'true'::jsonb OR coalesce(s->'blocked_reasons' @> '["no_privacy_policy"]'::jsonb,true) THEN RETURN; END IF;
 IF o.state='waitlisted' OR o.price=0 THEN
  payload:=jsonb_build_object('event','generate_lead','event_id',identity,'currency',coalesce(nullif(trim(o.currency_code),''),'CZK'),
   'value',0,'lead_source',CASE WHEN o.state='waitlisted' THEN 'waitlist' ELSE 'free_registration' END);
 ELSIF o.price>0 AND trim(o.currency_code) ~ '^[A-Z]{3}$' THEN
  SELECT title INTO brand FROM public.occasions WHERE id=o.occasion;
  -- Labels stay out of the grouping: they cannot split a line or change the total.
  SELECT jsonb_agg(jsonb_build_object('item_id','product_'||x.id,'item_name',x.title,'price',x.price,'quantity',x.quantity)||
    jsonb_strip_nulls(jsonb_build_object('item_category',nullif(left(btrim(x.category),100),''),'item_brand',nullif(left(btrim(brand),100),''))) ORDER BY x.id,x.price),
   sum(x.price*x.quantity) INTO items,total
  FROM (SELECT p->>'id' id,p->>'title' title,(p->>'price')::numeric price,count(*) quantity,min(p->>'type_title') category
   FROM jsonb_array_elements(o.data->'tickets') t CROSS JOIN LATERAL jsonb_array_elements(t->'products') p
   GROUP BY p->>'id',p->>'title',(p->>'price')::numeric) x;
  IF jsonb_array_length(items) BETWEEN 1 AND 200 AND total=o.price THEN
   payload:=jsonb_build_object('event','purchase','ecommerce',jsonb_build_object('transaction_id',identity,
    'currency',trim(o.currency_code),'value',o.price,'items',items,'payment_type',
    CASE WHEN (SELECT payment_method FROM eshop.payment_info WHERE id=o.payment_info)='stripe' THEN 'card' ELSE 'bank_transfer' END));
  END IF;
 END IF;
 IF payload IS NOT NULL THEN
  INSERT INTO analytics.conversion_facts("order",kind,event_id,payload) VALUES(p_order,coalesce(payload->>'lead_source',payload->>'event'),identity,payload)
   ON CONFLICT("order",kind) DO NOTHING;
 END IF;
-- Measurement failure cannot change checkout. Invalid/incomplete snapshots are
-- intentionally not exported; no second price calculation repairs them.
EXCEPTION WHEN OTHERS THEN RETURN;
END $_$;


ALTER FUNCTION public.record_form_conversion_internal(p_order bigint) OWNER TO postgres;

--
-- Name: record_occasion_media_step(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_occasion_media_step(p_command_id uuid, p_index integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE job public.occasion_media_jobs; step jsonb;
BEGIN
 PERFORM public.get_occasion_media_job(p_command_id);
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id FOR UPDATE;
 IF p_index IS NULL OR p_index<0 OR p_index>=jsonb_array_length(job.media) THEN RAISE invalid_parameter_value USING MESSAGE='invalid media step'; END IF;
 step:=job.media->p_index;
 IF step->>'ready'='true' THEN RETURN public.get_occasion_media_job(p_command_id); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.images WHERE link=step->>'target' AND occasion=job.target_occasion) THEN
  PERFORM public.add_image_record(step->>'target',job.target_occasion,NULL);
 END IF;
 UPDATE public.occasion_media_jobs SET media=jsonb_set(media,ARRAY[p_index::text,'ready'],'true') WHERE command_id=p_command_id;
 RETURN public.get_occasion_media_job(p_command_id);
END $$;


ALTER FUNCTION public.record_occasion_media_step(p_command_id uuid, p_index integer) OWNER TO postgres;

--
-- Name: record_service_fee_settlement(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_service_fee_settlement(p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE ident uuid:=(p_input->>'id')::uuid; agreement public.service_fee_agreements;
 prior public.service_fee_settlements; original public.service_fee_settlements;
 allocation jsonb; origin public.service_fee_allocations; proof eshop.order_checkout_origins;
 digest text:=encode(extensions.digest(p_input::text,'sha256'),'hex'); total numeric:=0;
 expenses numeric; amount numeric; allocation_id uuid; order_at timestamptz; refund_sequence bigint;
BEGIN
 PERFORM public.require_service_role();
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>1048576
  OR jsonb_typeof(p_input->'allocations') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'allocations') NOT BETWEEN 1 AND 1000 THEN
  RAISE invalid_parameter_value USING MESSAGE='INVALID_FEE_SETTLEMENT'; END IF;
 SELECT * INTO STRICT agreement FROM public.service_fee_agreements WHERE id=(p_input->>'agreementId')::uuid;
 -- Serialize imports/refunds for this customer, including aggregate caps.
 PERFORM 1 FROM public.units WHERE id=agreement.unit_id FOR UPDATE;
 -- A termination can commit while the importer waits for the customer lock.
 SELECT * INTO STRICT agreement FROM public.service_fee_agreements WHERE id=(p_input->>'agreementId')::uuid;
 SELECT * INTO prior FROM public.service_fee_settlements WHERE id=ident;
 IF FOUND THEN
  IF prior.input_digest<>digest THEN RAISE check_violation USING MESSAGE='FEE_SETTLEMENT_REPLAY_CONFLICT'; END IF;
  RETURN ident;
 END IF;
 IF NOT public.service_fee_reference_valid_internal(p_input->>'sourceReference')
  OR NOT isfinite((p_input->>'settledAt')::timestamptz) OR NOT isfinite((p_input->>'serviceAt')::timestamptz) THEN
  RAISE invalid_parameter_value USING MESSAGE='INVALID_FEE_SETTLEMENT_EVIDENCE'; END IF;
 IF p_input->>'amountBasis' IS DISTINCT FROM 'settled-service-fee-excluding-tax'
  OR jsonb_typeof(p_input->'feeMinor') IS DISTINCT FROM 'string' OR jsonb_typeof(p_input->'taxMinor') IS DISTINCT FROM 'string'
  OR p_input->>'feeMinor' !~ '^[1-9][0-9]{0,29}$' OR p_input->>'taxMinor' !~ '^(0|[1-9][0-9]{0,29})$'
  OR p_input->>'feeMinor' IS NULL OR p_input->>'taxMinor' IS NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='SETTLED_FEE_FACTS_REQUIRED'; END IF;
 IF NOT ((p_input->>'serviceAt')::timestamptz <@ tstzrange(agreement.valid_from,agreement.valid_until,'[)')) THEN
  RAISE check_violation USING MESSAGE='FEE_AGREEMENT_OUTSIDE_PERIOD'; END IF;
 IF p_input->>'kind'='refund' THEN
  SELECT * INTO STRICT original FROM public.service_fee_settlements WHERE id=(p_input->>'originalSettlementId')::uuid;
  IF original.kind<>'charge' OR original.agreement_id<>agreement.id OR original.currency<>p_input->>'currency'
   OR original.settled_at>(p_input->>'settledAt')::timestamptz OR original.service_at<>(p_input->>'serviceAt')::timestamptz THEN
   RAISE check_violation USING MESSAGE='FEE_REFUND_SCOPE_MISMATCH'; END IF;
  IF (SELECT coalesce(sum(fee_minor),0) FROM public.service_fee_settlements WHERE original_settlement_id=original.id)+(p_input->>'feeMinor')::numeric>original.fee_minor
   OR (SELECT coalesce(sum(tax_minor),0) FROM public.service_fee_settlements WHERE original_settlement_id=original.id)+(p_input->>'taxMinor')::numeric>original.tax_minor THEN
   RAISE check_violation USING MESSAGE='FEE_REFUND_EXCEEDS_SETTLEMENT'; END IF;
 END IF;
 INSERT INTO public.service_fee_settlements VALUES(ident,agreement.id,p_input->>'kind',(p_input->>'originalSettlementId')::uuid,
  p_input->>'sourceReference',p_input->>'invoiceReference',p_input->>'paymentEvidenceReference',p_input->>'allocationEvidenceReference',
  (p_input->>'settledAt')::timestamptz,(p_input->>'serviceAt')::timestamptz,p_input->>'currency',
  (p_input->>'feeMinor')::numeric,(p_input->>'taxMinor')::numeric,digest);
 FOR allocation IN SELECT value FROM jsonb_array_elements(p_input->'allocations') LOOP
  IF jsonb_typeof(allocation->'feeMinor') IS DISTINCT FROM 'string' OR jsonb_typeof(allocation->'agreedExpensesMinor') IS DISTINCT FROM 'string'
   OR allocation->>'feeMinor' IS NULL OR allocation->>'feeMinor' !~ '^[1-9][0-9]{0,29}$'
   OR allocation->>'agreedExpensesMinor' IS NULL OR allocation->>'agreedExpensesMinor' !~ '^(0|[1-9][0-9]{0,29})$' THEN
   RAISE invalid_parameter_value USING MESSAGE='INVALID_FEE_ALLOCATION'; END IF;
  amount:=(allocation->>'feeMinor')::numeric; expenses:=(allocation->>'agreedExpensesMinor')::numeric;
  allocation_id:=(allocation->>'id')::uuid; total:=total+amount;
  proof:=NULL; origin:=NULL; order_at:=NULL; refund_sequence:=0;
  IF expenses>0 AND NOT public.service_fee_reference_valid_internal(allocation->>'expenseApprovalReference') THEN
   RAISE invalid_parameter_value USING MESSAGE='INVALID_FEE_EXPENSE_EVIDENCE'; END IF;
  IF p_input->>'kind'='charge' THEN
   IF allocation->>'originalAllocationId' IS NOT NULL THEN RAISE check_violation USING MESSAGE='INVALID_FEE_ALLOCATION'; END IF;
   IF NOT EXISTS(SELECT 1 FROM eshop.orders o JOIN public.occasions c ON c.id=o.occasion
    WHERE o.created_at <@ tstzrange(agreement.valid_from,agreement.valid_until,'[)') AND o.id=(allocation->>'orderId')::bigint AND c.unit=agreement.unit_id AND c.organization=agreement.organization_id AND NOT public.is_demo_occasion(c.id)) THEN
    RAISE check_violation USING MESSAGE='FEE_ORDER_SCOPE_MISMATCH'; END IF;
   SELECT created_at INTO STRICT order_at FROM eshop.orders WHERE id=(allocation->>'orderId')::bigint;
   SELECT * INTO proof FROM eshop.order_checkout_origins WHERE order_id=(allocation->>'orderId')::bigint;
   IF allocation->>'partnerTermsReference' IS NOT NULL THEN
    IF NOT public.service_fee_reference_valid_internal(agreement.source_reference)
     OR EXISTS(SELECT 1 FROM public.service_fee_customer_acquisitions c WHERE c.unit_id=agreement.unit_id AND NOT public.service_fee_reference_valid_internal(c.evidence_reference))
     OR NOT public.service_fee_reference_valid_internal(allocation->>'partnerTermsReference')
     OR jsonb_typeof(allocation->'fx') IS DISTINCT FROM 'object'
     OR jsonb_typeof(allocation#>'{fx,reference}') IS DISTINCT FROM 'string'
     OR NOT public.service_fee_reference_valid_internal(allocation#>>'{fx,reference}')
     OR jsonb_typeof(allocation#>'{fx,usdMinorNumerator}') IS DISTINCT FROM 'string'
     OR jsonb_typeof(allocation#>'{fx,sourceMinorDenominator}') IS DISTINCT FROM 'string'
     OR coalesce(allocation#>>'{fx,usdMinorNumerator}','') !~ '^[1-9][0-9]{0,29}$'
     OR coalesce(allocation#>>'{fx,sourceMinorDenominator}','') !~ '^[1-9][0-9]{0,29}$'
     OR jsonb_typeof(allocation->'wixShareBps') IS DISTINCT FROM 'number'
     OR coalesce(allocation->>'wixShareBps','') !~ '^(0|[1-9][0-9]{0,3}|10000)$'
     OR (p_input->>'currency'='USD' AND allocation#>>'{fx,usdMinorNumerator}' IS DISTINCT FROM allocation#>>'{fx,sourceMinorDenominator}') THEN
     RAISE invalid_parameter_value USING MESSAGE='INVALID_WIX_FEE_REPORTING_METADATA'; END IF;
   END IF;
  ELSE
   SELECT * INTO STRICT origin FROM public.service_fee_allocations WHERE id=(allocation->>'originalAllocationId')::uuid;
   -- Serialized import order, not provider dates or random UUID order, owns
   -- cumulative rounding. Late facts append without repricing earlier receipts.
   SELECT coalesce(max(a.refund_sequence),0)+1 INTO refund_sequence
    FROM public.service_fee_allocations a WHERE a.original_allocation_id=origin.id;
   IF origin.settlement_id<>original.id OR origin.order_id<>(allocation->>'orderId')::bigint THEN
    RAISE check_violation USING MESSAGE='FEE_REFUND_ALLOCATION_MISMATCH'; END IF;
   IF (SELECT coalesce(sum(fee_minor),0) FROM public.service_fee_allocations WHERE original_allocation_id=origin.id)+amount>origin.fee_minor
    OR (SELECT coalesce(sum(agreed_expenses_minor),0) FROM public.service_fee_allocations WHERE original_allocation_id=origin.id)+expenses>origin.agreed_expenses_minor
    OR (SELECT coalesce(sum(fee_minor-agreed_expenses_minor),0) FROM public.service_fee_allocations WHERE original_allocation_id=origin.id)+amount-expenses>origin.fee_minor-origin.agreed_expenses_minor THEN
    RAISE check_violation USING MESSAGE='FEE_REFUND_EXCEEDS_ALLOCATION'; END IF;
  END IF;
  INSERT INTO public.service_fee_allocations(id,settlement_id,order_id,order_created_at,original_allocation_id,refund_sequence,fee_minor,
   agreed_expenses_minor,expense_approval_reference,instance_id,instance_verification_reference,order_origin_snapshot,fx,wix_share_bps,partner_terms_reference) VALUES(allocation_id,ident,(allocation->>'orderId')::bigint,coalesce(order_at,origin.order_created_at),origin.id,refund_sequence,amount,expenses,
   allocation->>'expenseApprovalReference',coalesce(origin.instance_id,proof.instance_id),
   coalesce(origin.instance_verification_reference,CASE WHEN proof.order_id IS NOT NULL THEN 'public.service_fee_allocations:'||allocation_id||':origin' END),
   CASE WHEN origin.id IS NOT NULL THEN origin.order_origin_snapshot WHEN proof.order_id IS NOT NULL THEN to_jsonb(proof) ELSE NULL END,
   CASE WHEN origin.id IS NULL THEN allocation->'fx' ELSE NULL END,
   CASE WHEN origin.id IS NULL THEN (allocation->>'wixShareBps')::integer ELSE NULL END,
   CASE WHEN origin.id IS NULL THEN allocation->>'partnerTermsReference' ELSE NULL END);
 END LOOP;
 IF total<>(p_input->>'feeMinor')::numeric THEN RAISE check_violation USING MESSAGE='FEE_ALLOCATION_TOTAL_MISMATCH'; END IF;
 RETURN ident;
END $_$;


ALTER FUNCTION public.record_service_fee_settlement(p_input jsonb) OWNER TO postgres;

--
-- Name: recover_email_delivery(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_email_delivery() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 PERFORM public.recover_email_leases();
 UPDATE public.email_messages SET workflow_state='expired',lease_token=NULL,lease_until=NULL
 WHERE expires_at<now() AND workflow_state IN ('pending','retry_wait','blocked','preparing');
 -- Erase sensitive body after terminal state/expiry; retain correlation and dedupe tombstones.
 UPDATE public.email_messages SET prepared=NULL,data=data-'ciphertext'
 WHERE message_kind IN ('registration','sign_in','reset_password','google_mailbox','gotrue','deletion_confirm','deletion_complete','sale_opening_opened')
 AND (workflow_state IN ('accepted','dead','cancelled','suppressed','expired') OR expires_at<now()) AND prepared IS NOT NULL;
 UPDATE public.email_messages SET prepared=NULL,data=jsonb_build_object('command_id',data->'command_id')
 WHERE created_at<now()-interval '30 days' AND workflow_state IN ('accepted','dead','cancelled','suppressed','expired') AND prepared IS NOT NULL;
 PERFORM public.notification_center_prepared_invalidate(e.id) FROM public.email_messages m JOIN public.notification_center_events e
  ON e.organization=m.organization AND e.kind='email_problem' AND e.data->>'messageId'=m.message_id::text
  WHERE m.message_kind='sale_opening_opened' AND m.expires_at<now()-interval '30 days' AND m.workflow_state NOT IN ('sending','unknown') AND m.recipient IS NOT NULL;
 UPDATE public.email_messages SET recipient=NULL,prepared=NULL,data='{}'
 WHERE message_kind IN ('sale_opening_opened') AND expires_at<now()-interval '30 days'
 AND workflow_state NOT IN ('sending','unknown');
 DELETE FROM public.email_confirmation_receipts WHERE expires_at<now();
 DELETE FROM public.email_delivery_events WHERE received_at<now()-interval '90 days';
 PERFORM public.apply_email_post_actions();
 PERFORM public.reconcile_email_events();
 PERFORM public.wake_email_worker();
END $$;


ALTER FUNCTION public.recover_email_delivery() OWNER TO postgres;

--
-- Name: recover_email_leases(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_email_leases() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 -- Sending expiry is ambiguous, preparation expiry is safe to recover.
 UPDATE public.email_attempts a SET state='unknown',finished_at=now(),error_code='lease_expired'
 FROM public.email_messages m WHERE m.message_id=a.message_id AND m.workflow_state='sending' AND m.lease_until<now() AND a.state='sending';
 UPDATE public.email_messages SET workflow_state='unknown',last_error='lease_expired' WHERE workflow_state='sending' AND lease_until<now();
 UPDATE public.email_attempts a SET state='cancelled',finished_at=now() FROM public.email_messages m
 WHERE a.message_id=m.message_id AND a.lease_token=m.lease_token AND a.state='preparing' AND m.lease_until<now();
 UPDATE public.email_messages SET workflow_state='pending',lease_token=NULL,lease_until=NULL WHERE workflow_state='preparing' AND lease_until<now();

END $$;


ALTER FUNCTION public.recover_email_leases() OWNER TO postgres;

--
-- Name: recover_form_save_client_sync_v1(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_form_save_client_sync_v1(p_form jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid := auth.uid(); oc bigint; form_id bigint; request_hash text; receipt jsonb;
BEGIN
  IF p_form IS NULL OR jsonb_typeof(p_form) <> 'object'
    OR octet_length(p_form::text) > 4194304 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid form aggregate';
  END IF;
  oc := NULLIF(p_form->>'occasion','')::bigint;
  form_id := NULLIF(p_form->>'id','')::bigint;
  IF actor IS NULL OR oc IS NULL OR form_id IS NULL
    OR NOT public.can_author_forms(oc) THEN
    RAISE insufficient_privilege USING MESSAGE='form editor required';
  END IF;
  request_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',oc,'form',p_form)::text,'UTF8'),'sha256'),'hex');
  receipt := public.begin_client_mutation_v1(p_command_id,
    'inventory.form.save',oc,actor,request_hash);
  IF receipt->>'disposition' = 'replay' THEN RETURN receipt->'response'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.forms WHERE id=form_id AND occasion=oc) THEN
    RAISE insufficient_privilege USING MESSAGE='foreign form';
  END IF;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,
    jsonb_build_object('message','FORM_SAVE_NOT_APPLIED'));
END;
$$;


ALTER FUNCTION public.recover_form_save_client_sync_v1(p_form jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: refresh_abuse_unit_evidence_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_abuse_unit_evidence_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE u record; cap bigint; n integer:=0; verified bigint;
BEGIN
 PERFORM public.require_service_role();
 SELECT hard_cap/greatest(growth_increment,1)+1 INTO cap FROM public.abuse_policy_rules WHERE rule_key='email.ordinary.unit.day';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 FOR u IN SELECT units.id FROM public.units LEFT JOIN public.abuse_unit_evidence e ON e.unit=units.id
  WHERE e.measured_at IS NULL OR e.measured_at<statement_timestamp()-interval '5 minutes'
  ORDER BY e.measured_at NULLS FIRST,units.id LIMIT 20 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('abuse-growth:'||u.id,0)) THEN CONTINUE; END IF;
  SELECT count(*) INTO verified FROM (
   SELECT ord.id FROM eshop.orders ord JOIN public.occasions occ ON occ.id=ord.occasion
   WHERE occ.unit=u.id AND ord.state IN ('paid','sent') AND ord.price>0
   AND (SELECT coalesce(sum(t.amount),0) FROM eshop.transactions t
    WHERE t.payment_info=ord.payment_info AND t.currency=ord.currency_code
     AND EXISTS(SELECT 1 FROM eshop.bank_transaction_identities i WHERE i.transaction_id=t.id))>=ord.price LIMIT cap
  ) proof;
  INSERT INTO public.abuse_unit_evidence VALUES(u.id,verified,statement_timestamp())
   ON CONFLICT(unit) DO UPDATE SET verified_orders=excluded.verified_orders,measured_at=excluded.measured_at;
  n:=n+1;
 END LOOP;
 RETURN n;
END $$;


ALTER FUNCTION public.refresh_abuse_unit_evidence_v1() OWNER TO postgres;

--
-- Name: refresh_cleaning_public_state_v1(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_cleaning_public_state_v1(p_occasion bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  INSERT INTO public.cleaning_public_state
    (occasion,place,status,open_report_count,revision,projected_at)
  SELECT p.occasion,p.id,
    CASE COALESCE(max(CASE r.problem_type WHEN 'contamination' THEN 3 WHEN 'hygiene' THEN 2 WHEN 'paper' THEN 1 ELSE 0 END),0)
      WHEN 3 THEN 'contamination' WHEN 2 THEN 'hygiene' WHEN 1 THEN 'paper' ELSE 'green' END,
    count(r.id),COALESCE(s.source_revision,0),now()
  FROM public.places p LEFT JOIN public.cleaning_reports r ON r.place=p.id AND r.resolved_at IS NULL
  LEFT JOIN public.client_sync_scopes s ON s.component='live_public' AND s.scope_type='occasion' AND s.scope_id=p.occasion
  WHERE p.occasion=p_occasion AND p.type='toilet'
  GROUP BY p.occasion,p.id,s.source_revision
  ON CONFLICT (occasion,place) DO UPDATE SET status=EXCLUDED.status,
    open_report_count=EXCLUDED.open_report_count,revision=EXCLUDED.revision,
    projected_at=EXCLUDED.projected_at;
  DELETE FROM public.cleaning_public_state c WHERE c.occasion=p_occasion
    AND NOT EXISTS (SELECT 1 FROM public.places p WHERE p.id=c.place AND p.occasion=p_occasion AND p.type='toilet');
END;
$$;


ALTER FUNCTION public.refresh_cleaning_public_state_v1(p_occasion bigint) OWNER TO postgres;

--
-- Name: refresh_email_quota(text, text, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_email_quota(p_account text, p_region text, p_rate numeric, p_daily numeric, p_used numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c public.email_capacity;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO c FROM public.email_capacity FOR UPDATE;
 IF c.account_id IS DISTINCT FROM p_account OR c.region IS DISTINCT FROM p_region OR p_rate IS NULL OR p_daily IS NULL OR p_used IS NULL OR p_rate<=0 OR p_daily<=0 OR p_used<0 THEN RAISE EXCEPTION 'email_quota_identity_mismatch'; END IF;
 UPDATE public.email_capacity SET max_rate=p_rate,daily_quota=p_daily,provider_sent_24h=p_used,quota_at=now(),wake_error=NULL,rate_factor=least(1,rate_factor+0.05) WHERE singleton;
END $$;


ALTER FUNCTION public.refresh_email_quota(p_account text, p_region text, p_rate numeric, p_daily numeric, p_used numeric) OWNER TO postgres;

--
-- Name: refresh_event_public_state_internal_v1(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_event_public_state_internal_v1(p_occasion bigint, p_event_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO public.event_public_state
    (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
  SELECT e.occasion,e.id,COUNT(DISTINCT eu."user"),COUNT(DISTINCT es."user"),
    CASE WHEN e.max_participants IS NULL THEN NULL
      ELSE GREATEST(e.max_participants-COUNT(DISTINCT eu."user"),0) END,
    COALESCE(s.source_revision,0),now()
  FROM public.events e
  LEFT JOIN public.event_users eu ON eu.event=e.id
  LEFT JOIN public.event_users_saved es ON es.event=e.id
  LEFT JOIN public.client_sync_scopes s ON s.component='live_public'
    AND s.scope_type='occasion' AND s.scope_id=e.occasion
  WHERE e.occasion=p_occasion AND NOT e.is_hidden
    AND (p_event_ids IS NULL OR e.id=ANY(p_event_ids))
  GROUP BY e.occasion,e.id,e.max_participants,s.source_revision
  ON CONFLICT (occasion,event) DO UPDATE SET
    participant_count=EXCLUDED.participant_count,
    saved_count=EXCLUDED.saved_count,
    remaining_capacity=EXCLUDED.remaining_capacity,
    revision=EXCLUDED.revision,projected_at=EXCLUDED.projected_at;

  DELETE FROM public.event_public_state state
  WHERE state.occasion=p_occasion
    AND (p_event_ids IS NULL OR state.event=ANY(p_event_ids))
    AND NOT EXISTS (
      SELECT 1 FROM public.events e
      WHERE e.id=state.event AND e.occasion=p_occasion AND NOT e.is_hidden
    );
END;
$$;


ALTER FUNCTION public.refresh_event_public_state_internal_v1(p_occasion bigint, p_event_ids bigint[]) OWNER TO postgres;

--
-- Name: refresh_event_public_state_v1(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_event_public_state_v1(p_occasion bigint, p_event_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.refresh_event_public_state_internal_v1(p_occasion,p_event_ids);
END; $$;


ALTER FUNCTION public.refresh_event_public_state_v1(p_occasion bigint, p_event_ids bigint[]) OWNER TO postgres;

--
-- Name: refresh_order_payment_deadline_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_order_payment_deadline_internal(p_order bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; pi eshop.payment_info; feature jsonb;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order;
 SELECT * INTO STRICT pi FROM eshop.payment_info WHERE id=o.payment_info;
 IF public.payment_method_is_online_internal(pi.payment_method) THEN RETURN; END IF;
 IF pi.data ? 'payment_policy' THEN
  IF pi.data#>>'{payment_policy,mode}'='none' THEN
   UPDATE eshop.payment_info SET deadline=NULL,deposit_deadline=NULL WHERE id=pi.id;
  END IF;
  RETURN;
 END IF;
 SELECT elem INTO feature FROM public.occasions oc CROSS JOIN LATERAL jsonb_array_elements(oc.features) elem
 WHERE oc.id=o.occasion AND elem->>'code'='form';
 -- Historical orders alone retain the former product-editor calculation.
 UPDATE eshop.payment_info SET deadline=CASE WHEN o.price>0 THEN now()+make_interval(secs=>coalesce((feature->>'deadline_duration_seconds')::bigint,604800)) END
 WHERE id=pi.id;
 PERFORM public.queue_payment_reminders_internal(o.occasion,pi.id);
END $$;


ALTER FUNCTION public.refresh_order_payment_deadline_internal(p_order bigint) OWNER TO postgres;

--
-- Name: refresh_payment_info_totals_internal(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_payment_info_totals_internal(p_payment bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE totals record;
BEGIN
 PERFORM 1 FROM eshop.payment_info WHERE id=p_payment FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_INFO_NOT_FOUND'; END IF;
 SELECT * INTO STRICT totals FROM public.payment_financial_totals_internal(p_payment);
 IF totals.invalid_identity THEN RAISE EXCEPTION 'PAYMENT_FACT_IDENTITY_MISMATCH'; END IF;
 UPDATE eshop.payment_info SET paid=totals.gross_received,returned=totals.refunded WHERE id=p_payment;
 -- paid_externally is deliberately not rewritten or converted into a bank movement.
END $$;


ALTER FUNCTION public.refresh_payment_info_totals_internal(p_payment bigint) OWNER TO postgres;

--
-- Name: register_blueprint_image_asset(bigint, text, jsonb, bigint, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_blueprint_image_asset(p_occasion bigint, p_project text, p_asset jsonb, p_issued_at bigint, p_proof text, p_unit bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE secret_value text; message text; expected text; org bigint; image_id bigint; existing public.blueprint_image_assets; ext text; expected_url text;
BEGIN
 IF public.get_blueprint_image_upload_access(p_occasion,p_project,p_unit) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='blueprint image editor required'; END IF;
 IF p_occasion IS NOT NULL THEN PERFORM public.check_occasion_writable(p_occasion); END IF;
 IF jsonb_typeof(p_asset) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_asset))<>8
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_asset) key WHERE key NOT IN ('assetRef','hash','url','width','height','mimeType','byteLength','state')) THEN
  RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_IMAGE_MANIFEST'; END IF;
 IF p_asset ? 'reserved' OR p_asset->>'state' IS DISTINCT FROM 'ready' OR coalesce(p_asset->>'hash','') !~ '^[a-f0-9]{64}$'
  OR p_asset->>'assetRef' IS DISTINCT FROM 'image:'||(p_asset->>'hash')
  OR jsonb_typeof(p_asset->'width') IS DISTINCT FROM 'number' OR jsonb_typeof(p_asset->'height') IS DISTINCT FROM 'number' OR jsonb_typeof(p_asset->'byteLength') IS DISTINCT FROM 'number'
  OR (p_asset->>'width')::numeric<>trunc((p_asset->>'width')::numeric) OR (p_asset->>'height')::numeric<>trunc((p_asset->>'height')::numeric)
  OR (p_asset->>'byteLength')::numeric<>trunc((p_asset->>'byteLength')::numeric)
  OR (p_asset->>'width')::numeric NOT BETWEEN 1 AND 3000 OR (p_asset->>'height')::numeric NOT BETWEEN 1 AND 3000
  OR (p_asset->>'byteLength')::numeric NOT BETWEEN 1 AND 819200 OR p_asset->>'mimeType' NOT IN ('image/png','image/jpeg','image/webp') THEN
  RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_IMAGE_MANIFEST'; END IF;
 ext:=CASE p_asset->>'mimeType' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/webp' THEN 'webp' END;
 expected_url:='https://'||CASE WHEN p_project='a' THEN 'a.img.festapp.net' ELSE 'img.festapp.net' END||'/images/'||CASE WHEN p_unit IS NULL THEN p_occasion::text ELSE 'unit-'||p_unit::text END||'/blueprint/'||(p_asset->>'hash')||'.'||ext;
 IF p_asset->>'url' IS DISTINCT FROM expected_url OR p_issued_at IS NULL OR p_issued_at<extract(epoch FROM statement_timestamp())-600 OR p_issued_at>extract(epoch FROM statement_timestamp())+30
  OR coalesce(p_proof,'') !~ '^[a-f0-9]{64}$' THEN RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_ATTESTATION_REJECTED'; END IF;
 SELECT decrypted_secret INTO secret_value FROM vault.decrypted_secrets WHERE name='blueprint_image_processing_v1';
 IF secret_value IS NULL OR length(secret_value)<32 THEN RAISE configuration_limit_exceeded USING MESSAGE='BLUEPRINT_IMAGE_PROCESSOR_NOT_CONFIGURED'; END IF;
 message:=concat_ws(E'\n','blueprint-image-v1',CASE WHEN p_unit IS NULL THEN 'occasion:'||p_occasion::text ELSE 'unit:'||p_unit::text END,p_project,p_asset->>'assetRef',p_asset->>'hash',p_asset->>'url',p_asset->>'width',p_asset->>'height',p_asset->>'mimeType',p_asset->>'byteLength',p_issued_at::text);
 expected:=encode(extensions.hmac(convert_to(message,'UTF8'),convert_to(secret_value,'UTF8'),'sha256'),'hex');
 IF extensions.digest(convert_to(p_proof,'UTF8'),'sha256')<>extensions.digest(convert_to(expected,'UTF8'),'sha256') THEN RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_ATTESTATION_REJECTED'; END IF;
 IF p_unit IS NULL THEN
  PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
  SELECT organization INTO org FROM public.occasions WHERE id=p_occasion;
 ELSE
  PERFORM pg_advisory_xact_lock(hashtextextended('blueprint-image-unit:'||p_unit,0));
  SELECT organization INTO org FROM public.units WHERE id=p_unit;
 END IF;
 SELECT * INTO existing FROM public.blueprint_image_assets WHERE (occasion=p_occasion OR unit=p_unit) AND asset_ref=p_asset->>'assetRef';
 IF FOUND THEN
  IF existing.organization<>org OR existing.hash<>p_asset->>'hash' OR existing.url<>p_asset->>'url' OR existing.width<>(p_asset->>'width')::integer OR existing.height<>(p_asset->>'height')::integer OR existing.mime_type<>p_asset->>'mimeType' OR existing.byte_length<>(p_asset->>'byteLength')::integer THEN RAISE check_violation USING MESSAGE='BLUEPRINT_IMAGE_IMMUTABLE'; END IF;
  RETURN p_asset;
 END IF;
 image_id:=public.add_image_record_internal(p_asset->>'url',p_occasion,p_unit);
 INSERT INTO public.blueprint_image_assets(occasion,unit,organization,asset_ref,hash,url,width,height,mime_type,byte_length,image)
 VALUES(p_occasion,p_unit,org,p_asset->>'assetRef',p_asset->>'hash',p_asset->>'url',(p_asset->>'width')::integer,(p_asset->>'height')::integer,p_asset->>'mimeType',(p_asset->>'byteLength')::integer,image_id);
 RETURN p_asset;
END $_$;


ALTER FUNCTION public.register_blueprint_image_asset(p_occasion bigint, p_project text, p_asset jsonb, p_issued_at bigint, p_proof text, p_unit bigint) OWNER TO postgres;

--
-- Name: register_blueprint_text_resources(bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_blueprint_text_resources(p_occasion bigint, p_setup_draft uuid, p_resources jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE scope text; item record; old jsonb; kind text; collection text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE insufficient_privilege USING MESSAGE='text service required'; END IF;
 IF (p_occasion IS NULL)=(p_setup_draft IS NULL) OR p_resources->>'protocol' IS DISTINCT FROM '2'
 OR jsonb_typeof(p_resources->'textLayouts') IS DISTINCT FROM 'object' OR jsonb_typeof(p_resources->'numberSymbols') IS DISTINCT FROM 'object'
 OR octet_length(p_resources::text)>16777216 THEN RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_TEXT_RESOURCES'; END IF;
 scope:=CASE WHEN p_occasion IS NOT NULL THEN 'occasion:'||p_occasion::text ELSE 'setup:'||p_setup_draft::text END;
 PERFORM pg_advisory_xact_lock(hashtextextended('blueprint-text:'||scope,0));
 FOREACH collection IN ARRAY ARRAY['textLayouts','numberSymbols'] LOOP
  kind:=CASE collection WHEN 'textLayouts' THEN 'text' ELSE 'number' END;
  FOR item IN SELECT key,value FROM jsonb_each(p_resources->collection) LOOP
   IF jsonb_typeof(item.value) IS DISTINCT FROM 'object' OR item.value->>'id' IS NULL
    OR (kind='text' AND (item.key IS DISTINCT FROM item.value->>'id' OR item.key !~ '^layout-text:[a-f0-9]{64}$' OR item.value#>>'{descriptor,layoutResourceProtocol}' IS DISTINCT FROM '2'))
    OR (kind='number' AND (item.key IS DISTINCT FROM item.value->>'fontFaceId' OR item.value->>'id' !~ '^layout-number:[a-f0-9]{64}$'))
    THEN RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_TEXT_RESOURCE'; END IF;
   SELECT payload INTO old FROM public.blueprint_text_resources WHERE scope_key=scope AND resource_id=item.value->>'id';
   IF FOUND THEN
    IF old IS DISTINCT FROM item.value THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_IMMUTABLE'; END IF;
   ELSE
    INSERT INTO public.blueprint_text_resources(scope_key,occasion,setup_draft,resource_id,resource_kind,payload)
     VALUES(scope,p_occasion,p_setup_draft,item.value->>'id',kind,item.value);
   END IF;
  END LOOP;
 END LOOP;
END $_$;


ALTER FUNCTION public.register_blueprint_text_resources(p_occasion bigint, p_setup_draft uuid, p_resources jsonb) OWNER TO postgres;

--
-- Name: register_delegated_blueprint_text_resources(bigint, bigint, bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_delegated_blueprint_text_resources(p_occasion bigint, p_organization bigint, p_unit bigint, p_actor uuid, p_resources jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o public.occasions%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='resource service required'; END IF;
 SELECT * INTO o FROM public.occasions WHERE id=p_occasion FOR SHARE;
 IF o.id IS NULL OR o.organization IS DISTINCT FROM p_organization OR (p_unit IS NOT NULL AND o.unit IS DISTINCT FROM p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='resource scope changed'; END IF;
 PERFORM 1 FROM public.units WHERE id=o.unit AND organization=p_organization FOR SHARE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='resource organizer changed'; END IF;
 PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_actor FOR SHARE;
 PERFORM 1 FROM public.unit_users WHERE unit=o.unit AND "user"=p_actor FOR SHARE;
 IF NOT public.can_prepare_layout_resources_as_actor_internal_v1(p_actor,p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='resource actor revoked'; END IF;
 PERFORM public.register_blueprint_text_resources(p_occasion,NULL,p_resources);
END $$;


ALTER FUNCTION public.register_delegated_blueprint_text_resources(p_occasion bigint, p_organization bigint, p_unit bigint, p_actor uuid, p_resources jsonb) OWNER TO postgres;

--
-- Name: register_service_fee_acquisition(bigint, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_service_fee_acquisition(p_unit bigint, p_channel text, p_acquired_at timestamp with time zone, p_evidence text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE prior public.service_fee_customer_acquisitions;
BEGIN
 PERFORM public.require_service_role();
 IF NOT public.service_fee_reference_valid_internal(p_evidence) OR NOT isfinite(p_acquired_at) THEN
  RAISE invalid_parameter_value USING MESSAGE='INVALID_FEE_ACQUISITION'; END IF;
 PERFORM 1 FROM public.units WHERE id=p_unit FOR UPDATE;
 SELECT * INTO prior FROM public.service_fee_customer_acquisitions WHERE unit_id=p_unit;
 IF FOUND THEN
  IF ROW(prior.channel,prior.acquired_at,prior.evidence_reference) IS DISTINCT FROM ROW(p_channel,p_acquired_at,p_evidence) THEN
   RAISE check_violation USING MESSAGE='FEE_ACQUISITION_REPLAY_CONFLICT'; END IF;
  RETURN;
 END IF;
 INSERT INTO public.service_fee_customer_acquisitions VALUES(p_unit,p_channel,p_acquired_at,p_evidence);
END $$;


ALTER FUNCTION public.register_service_fee_acquisition(p_unit bigint, p_channel text, p_acquired_at timestamp with time zone, p_evidence text) OWNER TO postgres;

--
-- Name: register_service_fee_agreement(uuid, bigint, text, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_service_fee_agreement(p_id uuid, p_unit bigint, p_reference text, p_rate_bps integer, p_from timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE prior public.service_fee_agreements;
BEGIN
 PERFORM public.require_service_role();
 IF NOT public.service_fee_reference_valid_internal(p_reference) OR NOT isfinite(p_from)
  OR (p_until IS NOT NULL AND NOT isfinite(p_until)) THEN
  RAISE invalid_parameter_value USING MESSAGE='INVALID_FEE_AGREEMENT'; END IF;
 PERFORM 1 FROM public.units WHERE id=p_unit FOR UPDATE;
 IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='FEE_UNIT_NOT_FOUND'; END IF;
 SELECT * INTO prior FROM public.service_fee_agreements WHERE id=p_id;
 IF FOUND THEN
  IF ROW(prior.unit_id,prior.source_reference,prior.fee_rate_bps,prior.valid_from,prior.valid_until)
   IS DISTINCT FROM ROW(p_unit,p_reference,p_rate_bps,p_from,p_until) THEN
   RAISE check_violation USING MESSAGE='FEE_AGREEMENT_REPLAY_CONFLICT'; END IF;
  RETURN p_id;
 END IF;
 IF EXISTS(SELECT 1 FROM public.service_fee_agreements WHERE unit_id=p_unit
  AND tstzrange(valid_from,valid_until,'[)') && tstzrange(p_from,p_until,'[)')) THEN
  RAISE check_violation USING MESSAGE='FEE_AGREEMENT_PERIOD_OVERLAP'; END IF;
 INSERT INTO public.service_fee_agreements(id,unit_id,organization_id,source_reference,fee_rate_bps,valid_from,valid_until) VALUES(p_id,p_unit,(SELECT organization FROM public.units WHERE id=p_unit),p_reference,p_rate_bps,p_from,p_until);
 RETURN p_id;
END $$;


ALTER FUNCTION public.register_service_fee_agreement(p_id uuid, p_unit bigint, p_reference text, p_rate_bps integer, p_from timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

--
-- Name: release_blueprint_holds(bigint, bigint, bigint, bigint, bigint[], bigint[], bigint, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_blueprint_holds(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_affected_spots bigint[], p_expected_revision bigint, p_hold_snapshot text, p_command_id uuid, p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 IF p_editor IS NULL OR p_command_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0
  OR p_hold_snapshot IS NULL OR p_hold_snapshot!~'^[0-9a-f]{64}$' OR coalesce(cardinality(p_affected_spots),0)=0
  OR cardinality(p_affected_spots)>(CASE WHEN p_editor THEN 20000 ELSE 1000 END) THEN RAISE invalid_parameter_value USING MESSAGE='confirmed hold release required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='blueprint unavailable'; END IF;
 -- Validate actual requested binding before a legacy owner can lock foreign scope.
 IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion AND blueprint=p_blueprint)
  IS DISTINCT FROM cardinality(p_spots) THEN RAISE insufficient_privilege USING MESSAGE='hold selection unavailable'; END IF;
 result:=public.release_blueprint_holds_command_internal(p_spots,p_command_id,p_affected_spots,p_expected_revision,p_hold_snapshot);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='blueprint unavailable'; END IF;
 IF NOT p_editor THEN result:=result-'sync'; END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.release_blueprint_holds(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_spots bigint[], p_affected_spots bigint[], p_expected_revision bigint, p_hold_snapshot text, p_command_id uuid, p_editor boolean) OWNER TO postgres;

--
-- Name: release_blueprint_holds_client_sync_v1(bigint[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_blueprint_holds_client_sync_v1(p_spots bigint[], p_command_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.release_blueprint_holds_command_internal(p_spots,p_command_id)
$$;


ALTER FUNCTION public.release_blueprint_holds_client_sync_v1(p_spots bigint[], p_command_id uuid) OWNER TO postgres;

--
-- Name: release_blueprint_holds_command_internal(bigint[], uuid, bigint[], bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_blueprint_holds_command_internal(p_spots bigint[], p_command_id uuid, p_expected_spots bigint[] DEFAULT NULL::bigint[], p_expected_revision bigint DEFAULT NULL::bigint, p_hold_snapshot text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE actor uuid:=auth.uid(); occ bigint; ids bigint[]; bp bigint; started jsonb; users uuid[]; fingerprint text; revision bigint; released bigint; confirmed boolean:=p_expected_revision IS NOT NULL;
BEGIN
 IF (p_expected_spots IS NULL OR p_expected_revision IS NULL OR p_hold_snapshot IS NULL)
  AND (p_expected_spots IS NOT NULL OR p_expected_revision IS NOT NULL OR p_hold_snapshot IS NOT NULL) THEN
  RAISE invalid_parameter_value USING MESSAGE='complete hold confirmation required'; END IF;
 IF actor IS NULL OR coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>256 THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 SELECT min(b.occasion),min(s.blueprint) INTO occ,bp FROM eshop.spots s JOIN eshop.blueprints b ON b.id=s.blueprint WHERE s.id=ANY(p_spots);
 IF occ IS NULL OR public.can_write_orders(occ) IS NOT TRUE OR
  (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND blueprint=bp) <>
  cardinality(ARRAY(SELECT DISTINCT x FROM unnest(p_spots) x)) THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 PERFORM public.check_occasion_writable(occ);
 fingerprint:=encode(extensions.digest(convert_to((jsonb_build_object('spots',p_spots)||CASE WHEN confirmed THEN jsonb_build_object('affected',p_expected_spots,'revision',p_expected_revision,'snapshot',p_hold_snapshot) ELSE '{}'::jsonb END)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.blueprint.holds.release',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 SELECT array_agg(DISTINCT member ORDER BY member) INTO ids FROM unnest(p_spots) requested
 CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(requested)) member;
 SELECT layout_revision INTO revision FROM eshop.blueprints WHERE id=bp AND occasion=occ FOR SHARE;
 IF confirmed AND (revision IS DISTINCT FROM p_expected_revision OR ids IS DISTINCT FROM ARRAY(SELECT x FROM unnest(p_expected_spots)x ORDER BY x)) THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_SELECTION_CHANGED')); END IF;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF confirmed AND public.blueprint_hold_snapshot_internal(occ,ids) IS DISTINCT FROM p_hold_snapshot THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_HOLDS_CHANGED')); END IF;
 IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(ids) AND (blueprint IS DISTINCT FROM bp OR order_product_ticket IS NOT NULL)) THEN
  IF confirmed THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_SEAT_ORDERED')); END IF;
  RAISE check_violation USING MESSAGE='Spot is already ordered'; END IF;
 SELECT count(*) INTO released FROM eshop.spots WHERE id=ANY(ids) AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp();
 SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO users FROM public.occasion_users ou WHERE ou.occasion=occ;
 UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL,updated_at=now()
 WHERE id=ANY(ids) AND order_product_ticket IS NULL;
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,occ,'inventory.blueprint.holds.release',
  jsonb_build_array(jsonb_build_object('entityType','spot','entityId',NULL,'operation','update','safeLabel','Temporary reservation released','changedFields',jsonb_build_array('reservation'))),
  users,jsonb_build_object('spotIds',to_jsonb(ids))||CASE WHEN confirmed THEN jsonb_build_object('releasedCount',released,'blueprintId',bp,'layoutRevision',revision) ELSE '{}'::jsonb END);
END $$;


ALTER FUNCTION public.release_blueprint_holds_command_internal(p_spots bigint[], p_command_id uuid, p_expected_spots bigint[], p_expected_revision bigint, p_hold_snapshot text) OWNER TO postgres;

--
-- Name: release_client_projection_claims_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_client_projection_claims_v1(p_claim_tokens uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_released integer;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_claim_tokens IS NULL OR cardinality(p_claim_tokens)=0
     OR array_position(p_claim_tokens,NULL) IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='non-empty claim tokens required';
  END IF;
  UPDATE public.client_projection_dirty_keys d
  SET claimed_at=NULL,claim_token=NULL
  WHERE d.claim_token=ANY(p_claim_tokens);
  GET DIAGNOSTICS v_released=ROW_COUNT;
  RETURN v_released;
END;
$$;


ALTER FUNCTION public.release_client_projection_claims_v1(p_claim_tokens uuid[]) OWNER TO postgres;

