--
-- Name: release_replacement_invoice_preparation(bigint, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_replacement_invoice_preparation(p_order bigint, p_command uuid, p_token uuid, p_not_created boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_not_created IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invoice outcome required'; END IF;
 UPDATE eshop.replacement_invoice_preparations SET
  dispatch_started=dispatch_started AND NOT p_not_created,
  state=CASE WHEN dispatch_started AND NOT p_not_created THEN 'unknown' ELSE 'retryable' END,
  lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order AND lease_token=p_token AND state='claimed';
 RETURN FOUND;
END $$;


ALTER FUNCTION public.release_replacement_invoice_preparation(p_order bigint, p_command uuid, p_token uuid, p_not_created boolean) OWNER TO postgres;

--
-- Name: remap_blueprint_layout_ids_internal(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remap_blueprint_layout_ids_internal(p_value jsonb, p_ids jsonb, p_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 IF jsonb_typeof(p_value)='object' THEN
  SELECT coalesce(jsonb_object_agg(item.key,public.remap_blueprint_layout_ids_internal(item.value,p_ids,item.key)),'{}') INTO result FROM jsonb_each(p_value) item;
  RETURN result;
 ELSIF jsonb_typeof(p_value)='array' THEN
  SELECT coalesce(jsonb_agg(public.remap_blueprint_layout_ids_internal(item.value,p_ids,p_key) ORDER BY item.position),'[]') INTO result FROM jsonb_array_elements(p_value) WITH ORDINALITY item(value,position);
  RETURN result;
 ELSIF jsonb_typeof(p_value)='string' AND p_key IN ('id','parentId','rootId','assemblyId','seatId','targetId','nodeIds') THEN
  RETURN coalesce(p_ids->(p_value#>>'{}'),p_value);
 END IF;
 RETURN p_value;
END $$;


ALTER FUNCTION public.remap_blueprint_layout_ids_internal(p_value jsonb, p_ids jsonb, p_key text) OWNER TO postgres;

--
-- Name: remove_image_records(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_image_records(p_links text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_row record; v_occasion bigint;
BEGIN
  IF COALESCE(array_length(p_links,1),0)=0 THEN RETURN; END IF;
  FOR v_row IN SELECT DISTINCT i.occasion,i.unit FROM public.images i
    WHERE i.link=ANY(p_links)
  LOOP
    IF v_row.occasion IS NOT NULL THEN
      IF NOT public.can_upload_occasion_media(v_row.occasion) THEN
        RAISE insufficient_privilege USING MESSAGE='occasion editor required';
      END IF;
    ELSIF v_row.unit IS NOT NULL AND NOT public.can_upload_unit_media(v_row.unit) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
  END LOOP;

  FOR v_occasion IN SELECT DISTINCT i.occasion FROM public.images i
    WHERE i.link=ANY(p_links) AND i.occasion IS NOT NULL
  LOOP
    DELETE FROM public.images i
      WHERE i.link=ANY(p_links) AND i.occasion=v_occasion;
    PERFORM public.record_client_sync_commit_v1(
      v_occasion,'image.remove','content',jsonb_build_array(jsonb_build_object(
        'entityType','occasion_image','entityId','batch','operation','delete',
        'safeLabel','occasion media','changedFields',jsonb_build_array('link'))),
      ARRAY['occasion_config'],'[]'::jsonb,'[]'::jsonb,'user',NULL);
  END LOOP;

  DELETE FROM public.images i WHERE i.link=ANY(p_links);
END; $$;


ALTER FUNCTION public.remove_image_records(p_links text[]) OWNER TO postgres;

--
-- Name: remove_occasion_user_domain_internal_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_occasion_user_domain_internal_v1(p_occasion bigint, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE groups bigint[]; impacts jsonb;
BEGIN
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT COALESCE(array_agg(DISTINCT g.id),'{}') INTO groups FROM public.user_group_info g LEFT JOIN public.user_groups ug ON g.id=ug."group" WHERE g.occasion=p_occasion AND (ug."user"=p_user OR g.leader=p_user);
 impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT "user" FROM public.user_groups WHERE "group"=ANY(groups))||ARRAY[p_user]);
 impacts:=(SELECT COALESCE(jsonb_agg(x),'[]') FROM jsonb_array_elements(impacts) x WHERE x->>'userId'<>p_user::text)||public.remove_user_activity_internal_v1(p_occasion,ARRAY[p_user]);
 UPDATE public.news SET created_by=NULL WHERE created_by=p_user AND occasion=p_occasion;
 UPDATE public.user_group_info SET leader=NULL WHERE occasion=p_occasion AND leader=p_user;
 DELETE FROM public.user_groups WHERE "user"=p_user AND "group"=ANY(groups);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.event_users WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.event_users_saved WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.user_news WHERE "user"=p_user AND occasion=p_occasion;
 -- Membership attention belongs to the deleted application, not the account.
 PERFORM public.notification_center_prepared_delete_events(ARRAY(SELECT e.id FROM public.notification_center_events e JOIN public.occasions o ON o.id=p_occasion AND o.organization=e.organization
  WHERE e.occasion=p_occasion AND e.kind='occasion_joined' AND e.data->>'userId'=p_user::text));
 DELETE FROM public.notification_center_events e
 USING public.occasions o
 WHERE o.id=p_occasion AND e.organization=o.organization AND e.occasion=o.id
   AND e.kind='occasion_joined' AND e.data->>'userId'=p_user::text;
 DELETE FROM public.occasion_users WHERE "user"=p_user AND occasion=p_occasion;
 DELETE FROM public.client_sync_private_scopes WHERE occasion=p_occasion AND user_id=p_user;
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text;
 RETURN impacts;
END $$;


ALTER FUNCTION public.remove_occasion_user_domain_internal_v1(p_occasion bigint, p_user uuid) OWNER TO postgres;

--
-- Name: remove_transaction_from_payment_info_ws(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_transaction_from_payment_info_ws(p_transaction_id bigint, p_payment_info_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_bank_account_id bigint;
  v_occasion_id bigint;
BEGIN
  SELECT pi.bank_account, o.occasion INTO v_bank_account_id, v_occasion_id
  FROM eshop.payment_info pi
  JOIN eshop.orders o ON o.payment_info = pi.id
  WHERE pi.id = p_payment_info_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_INFO_NOT_FOUND'; END IF;
  IF NOT public.can_manage_bank_account(v_bank_account_id) THEN
    RAISE insufficient_privilege USING MESSAGE='Bank transaction write access denied'; END IF;
  PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);
  IF NOT EXISTS (SELECT 1 FROM eshop.transactions t
    WHERE t.id = p_transaction_id AND t.payment_info = p_payment_info_id) THEN
    RAISE EXCEPTION 'TRANSACTION_PAIRING_MISMATCH';
  END IF;
  PERFORM public.apply_transaction_pairing(
    p_transaction_id, NULL, 'manual_unlink', 'user'
  );
END;
$$;


ALTER FUNCTION public.remove_transaction_from_payment_info_ws(p_transaction_id bigint, p_payment_info_id bigint) OWNER TO postgres;

--
-- Name: remove_user_activity_internal_v1(bigint, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.remove_user_activity_internal_v1(p_occasion bigint, p_users uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE impacted uuid[]; n int; impacts jsonb;
BEGIN
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT ARRAY(SELECT DISTINCT aa."user" FROM public.activity_assignments aa JOIN public.activities a ON a.id=aa.activity_id WHERE a.occasion=p_occasion) INTO impacted;
 DELETE FROM public.activity_assignments aa USING public.activities a WHERE a.id=aa.activity_id AND a.occasion=p_occasion AND aa."user"=ANY(p_users);
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n=0 THEN RETURN '[]'; END IF;
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',id) ORDER BY id),'[]') INTO impacts FROM unnest(impacted) id JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id WHERE NOT id=ANY(p_users);
 RETURN impacts;
END $$;


ALTER FUNCTION public.remove_user_activity_internal_v1(p_occasion bigint, p_users uuid[]) OWNER TO postgres;

--
-- Name: renew_email_preparation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.renew_email_preparation(p_message uuid, p_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.require_service_role();
 UPDATE public.email_messages SET lease_until=now()+interval '90 seconds'
 WHERE message_id=p_message AND lease_token=p_token AND workflow_state='preparing' AND lease_until>now();
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_email_preparation'; END IF;
END $$;


ALTER FUNCTION public.renew_email_preparation(p_message uuid, p_token uuid) OWNER TO postgres;

--
-- Name: repair_order_email_client_sync_v1(bigint, text, text, bigint, text, uuid, boolean, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_order_email_client_sync_v1(p_order bigint, p_expected_email text, p_expected_state text, p_expected_payment_version bigint, p_email text, p_source_message uuid, p_resend boolean, p_command_id uuid, p_expected_payment_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o eshop.orders; oc public.occasions; src public.email_messages; active public.email_messages;
 v_begin jsonb; v_hash text; v_email text; v_form bigint; v_field bigint; v_fields jsonb;
 v_kind text; v_intent jsonb; v_users uuid[]; v_payload jsonb; v_details jsonb;
BEGIN
 SELECT * INTO o FROM eshop.orders WHERE id=p_order;
 SELECT * INTO oc FROM public.occasions WHERE id=o.occasion;
 IF auth.uid() IS NULL OR o.id IS NULL OR NOT coalesce(public.can_write_orders(o.occasion),false) THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 -- Re-authorize the object relationship even on receipt replay.
 IF p_source_message IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.email_messages m
  WHERE m.message_id=p_source_message AND m.order_id=o.id AND m.occasion=o.occasion
   AND m.organization=oc.organization AND public.email_report_allowed(m.organization,m.occasion,m.recipient_user)) THEN
  RAISE insufficient_privilege USING MESSAGE='order email unavailable'; END IF;
 v_hash:=encode(extensions.digest(jsonb_build_object('order',p_order,'expectedEmail',p_expected_email,
  'expectedState',p_expected_state,'expectedVersion',p_expected_payment_version,'email',p_email,
  'source',p_source_message,'resend',p_resend,'paymentFingerprint',p_expected_payment_fingerprint)::text,'sha256'),'hex');
 v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.order.repair_email',o.occasion,auth.uid(),v_hash);
 IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
 v_form:=o.form;
 -- Same form -> order -> message order as response editing / send fencing.
 IF v_form IS NOT NULL THEN PERFORM 1 FROM public.forms WHERE id=v_form FOR SHARE; END IF;
 SELECT * INTO o FROM eshop.orders WHERE id=p_order FOR UPDATE;
 IF o.id IS NULL OR o.form IS DISTINCT FROM v_form OR o.data->>'email' IS DISTINCT FROM p_expected_email
  OR o.state IS DISTINCT FROM p_expected_state OR o.email_payment_version IS DISTINCT FROM p_expected_payment_version
  OR p_expected_payment_fingerprint IS DISTINCT FROM public.order_email_payment_fingerprint(o.id) THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason','order_changed')); END IF;
 PERFORM public.check_occasion_writable(o.occasion);
 IF o.state NOT IN ('ordered','paid','sent') THEN RAISE EXCEPTION 'ORDER_ACTION_NOT_ALLOWED'; END IF;
 IF p_resend IS NULL OR p_email IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invalid_email_contact'; END IF;
 v_email:=public.normalize_order_email_contact(p_email);
 v_kind:=public.order_checkout_email_kind_internal(o.id);
 PERFORM 1 FROM public.email_messages WHERE order_id=o.id ORDER BY id FOR UPDATE;
 SELECT * INTO src FROM public.email_messages WHERE message_id=p_source_message;
 IF p_resend AND src.id IS NOT NULL AND (src.message_kind<>v_kind OR src.last_error='post_action_failed') THEN
  RAISE EXCEPTION 'source_not_resendable'; END IF;
 -- An issued permit or unknown outcome cannot be bypassed by changing contact.
 IF p_resend AND EXISTS(SELECT 1 FROM public.email_messages WHERE order_id=o.id AND message_kind IN ('order_confirmation','order_tickets')
  AND workflow_state IN ('sending','unknown')) THEN RAISE EXCEPTION 'email_outcome_unresolved'; END IF;
 IF p_resend AND EXISTS(SELECT 1 FROM public.email_suppressions WHERE recipient=lower(v_email)) THEN
  RAISE EXCEPTION 'email_recipient_suppressed'; END IF;
 IF p_resend THEN
  SELECT * INTO active FROM public.email_messages WHERE order_id=o.id AND message_kind=v_kind
   AND workflow_state IN ('pending','preparing','retry_wait','blocked')
   AND recipient=o.data->>'email' AND source_version=o.email_payment_version
   AND (expires_at IS NULL OR expires_at>now())
   ORDER BY id DESC LIMIT 1;
  IF active.id IS NOT NULL THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
    jsonb_build_object('reason','active_email_intent','messageId',active.message_id)); END IF;
 END IF;
 -- Repair chains have one successor per source. A stale source cannot fork
 -- around a newer failed/waiting attempt, even after its active lease ended.
 IF p_resend AND src.id IS NOT NULL AND EXISTS(SELECT 1 FROM public.email_messages
  WHERE order_id=o.id AND data->>'repair_source_message_id'=src.message_id::text) THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
   jsonb_build_object('reason','source_replaced')); END IF;
 -- Update only the existing contact projection, without invoking pricing/stock.
 SELECT min(id) INTO v_field FROM public.form_fields WHERE form=v_form AND type='email';
 IF (SELECT count(*) FROM public.form_fields WHERE form=v_form AND type='email')>1 THEN
  RAISE EXCEPTION 'ambiguous_contact_field'; END IF;
 IF v_field IS NOT NULL THEN
  SELECT coalesce(jsonb_agg(e - v_field::text) FILTER (WHERE e - v_field::text<>'{}'::jsonb),'[]') INTO v_fields
   FROM jsonb_array_elements(coalesce(o.data->'fields','[]')) e;
  o.data:=jsonb_set(o.data,'{fields}',v_fields||jsonb_build_array(jsonb_build_object(v_field::text,v_email)));
 END IF;
 UPDATE eshop.orders SET data=jsonb_set(o.data,'{email}',to_jsonb(v_email)),updated_at=now()
  WHERE id=o.id RETURNING * INTO o;
 PERFORM public.notification_center_prepared_invalidate_order(o.id);
 INSERT INTO eshop.orders_history("order",state,price,currency_code,data,created_by)
  VALUES(o.id,o.state,o.price,o.currency_code,o.data,auth.uid());
 -- A prepared payload is a snapshot of its recipient; retire pre-permit old
 -- contacts explicitly, including legacy manual ticket snapshots.
 UPDATE public.email_messages SET workflow_state='cancelled',last_error='contact_changed',lease_token=NULL,lease_until=NULL
  WHERE order_id=o.id AND recipient IS DISTINCT FROM v_email
   AND workflow_state IN ('pending','preparing','retry_wait','blocked');
 IF p_resend THEN
  v_payload:=jsonb_build_object('order_id',o.id,'requested_by',auth.uid(),'repair_source_message_id',p_source_message,'repair_payment_fingerprint',p_expected_payment_fingerprint);
  IF v_kind='order_confirmation' THEN
   -- The existing confirmation renderer consumes the canonical checkout shape,
   -- not an order ID. Rebuild it from current facts without a checkout mutation.
   v_details:=public.get_order_details_for_email(o.id)->'data';
   -- Each explicit resend owns its command identity. Reusing the checkout
   -- command collides with the unique confirmation-command index.
   v_payload:=v_payload||jsonb_build_object('command_id',p_command_id,
    'ticket_order',jsonb_build_object('order',v_details->'order'||jsonb_build_object(
     'occasion',v_details->'occasion','reply_to',v_details->'reply_to',
     'form',jsonb_build_object('id',o.form,'data',v_details->'form_data'),
     'payment_info',coalesce(v_details->'payment_info','{}')||jsonb_build_object(
      'account_number',v_details#>'{bank_account,account_number}',
      'account_number_human_readable',v_details#>'{bank_account,account_number_human_readable}',
      'creditor_name',v_details#>'{bank_account,creditor_name}'))));
  END IF;
  v_intent:=public.enqueue_order_email(CASE v_kind WHEN 'order_confirmation' THEN 'TICKET_ORDER_CONFIRMATION' ELSE 'ORDER_TICKETS' END,
   v_payload,
   oc.organization,oc.id,oc.unit,now(),'repair:'||p_command_id);
  IF v_intent->>'message_id' IS NULL OR coalesce((v_intent->>'replayed')::boolean,false) THEN
   RAISE EXCEPTION 'email_enqueue_rejected'; END IF;
 END IF;
 SELECT coalesce(array_agg("user"),'{}') INTO v_users FROM public.occasion_users WHERE occasion=o.occasion;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,o.occasion,'inventory.order.repair_email',
  jsonb_build_array(jsonb_build_object('entityType','order','entityId',o.id,'operation','update',
    'safeLabel','Order contact','changedFields',jsonb_build_array('data'))),v_users,
  jsonb_build_object('order',to_jsonb(o)||jsonb_build_object('email_payment_fingerprint',public.order_email_payment_fingerprint(o.id)),'intent',v_intent,'sendingRequested',p_resend));
END $$;


ALTER FUNCTION public.repair_order_email_client_sync_v1(p_order bigint, p_expected_email text, p_expected_state text, p_expected_payment_version bigint, p_email text, p_source_message uuid, p_resend boolean, p_command_id uuid, p_expected_payment_fingerprint text) OWNER TO postgres;

--
-- Name: replace_activities_graph_internal_v1(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replace_activities_graph_internal_v1(p_occasion bigint, p_graph jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a jsonb; x jsonb; graph jsonb; changed int;
BEGIN
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_graph,true);
 DELETE FROM public.activity_assignments aa USING public.activities a WHERE aa.activity_id=a.id AND a.occasion=p_occasion AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph) g,LATERAL jsonb_array_elements(g->'assignments') assignment WHERE assignment->>'id'=aa.id::text);
 DELETE FROM public.activities WHERE occasion=p_occasion AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph) g WHERE g->>'id'=public.activities.id::text);
 FOR a IN SELECT value FROM jsonb_array_elements(graph) LOOP
  INSERT INTO public.activities(id,title,description,type,unit,occasion,is_hidden,"order",data) VALUES((a->>'id')::uuid,a->>'title',a->>'description',a->>'type',(a->>'unit')::bigint,p_occasion,(a->>'is_hidden')::boolean,(a->>'order')::bigint,a->'data') ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,type=excluded.type,unit=excluded.unit,is_hidden=excluded.is_hidden,"order"=excluded."order",data=excluded.data WHERE public.activities.occasion=p_occasion;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE invalid_parameter_value USING MESSAGE='global activity UUID collision'; END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(a->'assignments') LOOP
   INSERT INTO public.activity_assignments(id,activity_id,"user",start_time,end_time,title,description,data) VALUES((x->>'id')::uuid,(a->>'id')::uuid,(x->>'user')::uuid,(x->>'start_time')::timestamptz,(x->>'end_time')::timestamptz,x->>'title',x->>'description',x->'data') ON CONFLICT(id) DO UPDATE SET activity_id=excluded.activity_id,"user"=excluded."user",start_time=excluded.start_time,end_time=excluded.end_time,title=excluded.title,description=excluded.description,data=excluded.data WHERE EXISTS(SELECT 1 FROM public.activities owner WHERE owner.id=public.activity_assignments.activity_id AND owner.occasion=p_occasion);
   GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE invalid_parameter_value USING MESSAGE='global assignment UUID collision'; END IF;
   DELETE FROM public.activity_assignment_places WHERE assignment_id=(x->>'id')::uuid;
   INSERT INTO public.activity_assignment_places(assignment_id,place_id) SELECT (x->>'id')::uuid,value::bigint FROM jsonb_array_elements_text(x->'linked_place_ids');
   DELETE FROM public.activity_assignment_events WHERE assignment_id=(x->>'id')::uuid;
   INSERT INTO public.activity_assignment_events(assignment_id,event_id) SELECT (x->>'id')::uuid,value::bigint FROM jsonb_array_elements_text(x->'linked_event_ids');
  END LOOP;
 END LOOP;
END $$;


ALTER FUNCTION public.replace_activities_graph_internal_v1(p_occasion bigint, p_graph jsonb) OWNER TO postgres;

--
-- Name: replace_blueprint_order_client_sync_v1(bigint[], jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replace_blueprint_order_client_sync_v1(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT public.replace_blueprint_order_command_internal(p_spot_ids,p_input_data,p_command_id,NULL)
$$;


ALTER FUNCTION public.replace_blueprint_order_client_sync_v1(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid) OWNER TO postgres;

--
-- Name: replace_blueprint_order_command_internal(bigint[], jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replace_blueprint_order_command_internal(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid, p_confirmation jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid();occ bigint;started jsonb;fingerprint text;before_users uuid[];
 effect jsonb;result jsonb;quote jsonb;ids bigint[];failure text;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id=ANY(p_spot_ids);
 IF actor IS NULL OR occ IS NULL OR coalesce(cardinality(p_spot_ids),0)=0
  OR (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spot_ids) AND occasion=occ)<>
    cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
  OR public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 fingerprint:=encode(extensions.digest(convert_to((jsonb_build_object('spots',p_spot_ids,'input',p_input_data)
  ||CASE WHEN p_confirmation IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('confirmation',p_confirmation) END)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.order.replace',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  RETURN public.project_local_payment_reference_order_internal(started->'response'); END IF;
 SELECT coalesce(array_agg(ou."user"),'{}') INTO before_users FROM public.occasion_users ou WHERE ou.occasion=occ;
 BEGIN
  ids:=CASE WHEN p_confirmation IS NULL THEN p_spot_ids ELSE
   public.blueprint_seat_order_selection_internal(occ,(p_confirmation->>'blueprint')::bigint,p_spot_ids,20000) END;
  effect:=public.apply_blueprint_seat_order_internal(ids,p_input_data,p_command_id);
  result:=effect->'result'||jsonb_build_object('paymentPreparationPolicy','leased_keep_pending');
  IF p_confirmation IS NOT NULL THEN
   quote:=public.blueprint_seat_order_quote_internal(effect);
   IF effect->>'confirmationHash' IS DISTINCT FROM p_confirmation->>'hash'
    OR quote->'spotIds' IS DISTINCT FROM p_confirmation->'targets'
    OR quote->'affectedSpotIds' IS DISTINCT FROM p_confirmation->'affected'
    OR quote->'blueprints' IS DISTINCT FROM p_confirmation->'blueprints' THEN
    RAISE SQLSTATE 'BP002' USING MESSAGE='BLUEPRINT_ORDER_CHANGED'; END IF;
  END IF;
 EXCEPTION WHEN SQLSTATE 'BP002' THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_ORDER_CHANGED'));
 WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
 WHEN check_violation THEN
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  GET STACKED DIAGNOSTICS failure=PG_EXCEPTION_DETAIL;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',CASE WHEN p_confirmation IS NULL THEN 400 ELSE 409 END,
   CASE WHEN p_confirmation IS NULL AND left(failure,1)='{' THEN failure::jsonb
   ELSE public.blueprint_order_rejection_internal(SQLERRM,failure) END);
 WHEN OTHERS THEN
  IF p_confirmation IS NULL THEN RAISE; END IF;
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,public.blueprint_order_rejection_internal(SQLERRM,NULL));
 END;
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 IF p_confirmation IS NOT NULL THEN result:=result||jsonb_build_object('quote',quote); END IF;
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,occ,'inventory.order.replace',
  jsonb_build_array(jsonb_build_object('entityType','order','entityId',result#>>'{order,id}','operation','insert',
   'safeLabel','Blueprint order replacement','changedFields',jsonb_build_array('cancellations','tickets','products','allocations','membership'))),
  before_users,result);
END $$;


ALTER FUNCTION public.replace_blueprint_order_command_internal(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid, p_confirmation jsonb) OWNER TO postgres;

--
-- Name: replace_group_assignments_client_sync_v1(bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replace_group_assignments_client_sync_v1(p_occasion bigint, p_command_id uuid, p_assignments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_unit bigint;
  v_before jsonb; v_after jsonb; v_changed bigint[];
  v_group_ids bigint[]; v_impacted_users uuid[]; v_private_impacts jsonb;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
  PERFORM public.lock_people_scope_internal_v1(p_occasion);
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  SELECT o.unit INTO v_unit FROM public.occasions o WHERE o.id=p_occasion;
  IF v_actor IS NULL OR NOT public.can_import_group_assignments(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='group import permission required'; END IF;
  IF p_assignments IS NULL OR jsonb_typeof(p_assignments)<>'array'
    OR jsonb_array_length(p_assignments)>10000
    OR octet_length(p_assignments::text)>2097152 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group assignments'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'assignments',p_assignments)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.groups.import',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF NOT public.can_import_group_assignments(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='group import permission required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
  PERFORM 1 FROM public.user_group_info g WHERE g.occasion=p_occasion
    AND g.type IS NULL ORDER BY g.id FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT ug."group"),'{}'::bigint[])
    INTO v_group_ids FROM public.user_groups ug JOIN public.user_group_info g
      ON g.id=ug."group" JOIN jsonb_to_recordset(p_assignments)
      x(user_id uuid,group_title text) ON x.user_id=ug."user"
    WHERE g.occasion=p_occasion AND g.type IS NULL;
  SELECT COALESCE(array_agg(DISTINCT members."user"),'{}'::uuid[])
    INTO v_impacted_users FROM public.user_groups members
    WHERE members."group"=ANY(v_group_ids);
  SELECT COALESCE(jsonb_object_agg(g.id,public.get_user_group_command_data_v1(g.id)-'aggregate_version'),'{}') INTO v_before FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL;
  PERFORM public.import_user_group_assignments_internal_v1(
    p_occasion,p_assignments);
  SELECT COALESCE(jsonb_object_agg(g.id,public.get_user_group_command_data_v1(g.id)-'aggregate_version'),'{}') INTO v_after FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL;
  IF v_before=v_after THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('assignments',jsonb_array_length(p_assignments))); END IF;
  SELECT ARRAY(SELECT key::bigint FROM jsonb_each(v_after) WHERE value IS DISTINCT FROM v_before->key ORDER BY key::bigint) INTO v_changed;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_group_ids||COALESCE((
    SELECT array_agg(ug."group") FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    JOIN jsonb_to_recordset(p_assignments) x(user_id uuid,group_title text)
      ON x.user_id=ug."user" WHERE g.occasion=p_occasion AND g.type IS NULL),
    '{}'::bigint[])) id ORDER BY id) INTO v_group_ids;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_impacted_users||COALESCE((
    SELECT array_agg(members."user") FROM public.user_groups members
    WHERE members."group"=ANY(v_group_ids)),'{}'::uuid[])) id ORDER BY id)
    INTO v_impacted_users;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(v_changed) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,v_impacted_users);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.groups.import','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group_membership','entityId',NULL,'operation','import',
      'safeLabel','Group assignment import','changedFields',jsonb_build_array('memberships'))),
    '{}',v_private_impacts,'[]',jsonb_build_object(
      'assignments',jsonb_array_length(p_assignments)),
    '{}','[]','user',NULL,v_actor_replacements);
END; $$;


ALTER FUNCTION public.replace_group_assignments_client_sync_v1(p_occasion bigint, p_command_id uuid, p_assignments jsonb) OWNER TO postgres;

--
-- Name: report_cleaning_issue(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_cleaning_issue(place_id bigint, problem_type text, note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=public.report_cleaning_issue_client_sync_v1(place_id,problem_type,note,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code','message',result#>'{data,message}','data',result->'data');
END $$;


ALTER FUNCTION public.report_cleaning_issue(place_id bigint, problem_type text, note text) OWNER TO postgres;

--
-- Name: report_cleaning_issue_client_sync_v1(bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_cleaning_issue_client_sync_v1(p_place bigint, p_problem_type text, p_note text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_existing bigint; v_has_note boolean;
BEGIN
  SELECT p.occasion INTO v_occasion FROM public.places p WHERE p.id=p_place;
  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='signed-in occasion participant required';
  END IF;
  v_has_note:=NULLIF(btrim(COALESCE(p_note,'')),'') IS NOT NULL;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'place',p_place,'problemType',p_problem_type,'note',p_note)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.report',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.places p WHERE p.id=p_place FOR UPDATE;
  SELECT cr.id INTO v_existing FROM public.cleaning_reports cr
    WHERE cr.place=p_place AND cr.problem_type=p_problem_type
      AND cr.resolved_at IS NULL ORDER BY cr.created_at LIMIT 1 FOR UPDATE;
  v_result:=public.report_cleaning_issue_internal_v1(p_place,p_problem_type,p_note);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_existing IS NOT NULL AND NOT v_has_note THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'cleaning.report','cleaning',jsonb_build_array(jsonb_build_object(
      'entityType','cleaning_report','entityId',v_result#>>'{data,id}',
      'operation',CASE WHEN v_existing IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Cleaning report','changedFields',CASE WHEN v_existing IS NULL
        THEN jsonb_build_array('place','problemType') ELSE jsonb_build_array('note') END)),
    CASE WHEN v_existing IS NULL THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    '[]',CASE WHEN v_existing IS NULL THEN jsonb_build_array(jsonb_build_object(
      'component','live_public','entityId',p_place)) ELSE '[]'::jsonb END,
    v_result->'data');
END; $$;


ALTER FUNCTION public.report_cleaning_issue_client_sync_v1(p_place bigint, p_problem_type text, p_note text, p_command_id uuid) OWNER TO postgres;

--
-- Name: report_cleaning_issue_internal_v1(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_cleaning_issue_internal_v1(place_id bigint, problem_type text, note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_note text := NULLIF(btrim(COALESCE(note, '')), '');
  v_place public.places%ROWTYPE;
  v_occasion bigint;
  v_organization bigint;
  v_type_label text;
  v_existing public.cleaning_reports%ROWTYPE;
  v_report public.cleaning_reports%ROWTYPE;
  v_crew jsonb;
  v_notification_deferred boolean:=false;
  v_notification uuid;
  v_policy jsonb; v_new_data jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required to report a cleaning issue');
  END IF;

  -- Problem types — keep in sync with: cleaning_reports.problem_type CHECK
  -- (database/tables/tables.sql), CleaningStatusHelper (cleaning_status.dart)
  -- and the report dialog (cleaning_report_dialog.dart).
  IF problem_type NOT IN ('paper', 'hygiene', 'contamination') THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Invalid problem type');
  END IF;

  IF char_length(COALESCE(v_note, '')) > 2000 THEN
    RETURN jsonb_build_object('code', 413, 'message', 'Note is too long');
  END IF;

  SELECT * INTO v_place FROM public.places WHERE id = place_id;
  IF NOT FOUND OR v_place.occasion IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Toilet not found');
  END IF;

  v_occasion := v_place.occasion;

  IF NOT EXISTS (
    SELECT 1
    FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_approved = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Approved occasion participation is required');
  END IF;

  -- Blocked reporters (anti-spam hard ban) cannot file reports on this occasion.
  -- This is the source of truth; the UI also greys the report action out via the
  -- is_blocked flag returned by get_cleaning_status.
  IF EXISTS (
    SELECT 1 FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_cleaning_blocked = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Reporting has been disabled for your account');
  END IF;

  -- Place must be flagged as a toilet (places.type = 'toilet'). This is set by
  -- the "WC / Úklid" checkbox in the admin Places grid — no place_types catalog
  -- row is required.
  IF v_place.type IS DISTINCT FROM 'toilet' THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Place is not a toilet');
  END IF;

  -- Feature "cleaning" must be enabled on the occasion (occasions.features).
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions o
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features, '[]'::jsonb)) feature
    WHERE o.id = v_occasion
      AND feature->>'code' = 'cleaning'
      AND LOWER(COALESCE(feature->>'is_enabled', 'false')) = 'true'
  ) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Cleaning feature is not enabled for this occasion');
  END IF;

  -- Committed accepted work, including appended duplicate notes, shares one
  -- actor identity. Removing a report cannot replenish its rolling budget.
  BEGIN
    v_policy:=public.abuse_effective_rules_v1('cleaning.report',NULL,NULL);
    PERFORM public.abuse_charge_v1(v_policy,
      jsonb_build_object('actor',v_user),jsonb_build_object('cleaning.note.bytes',octet_length(coalesce(v_note,'')), 'cleaning.report.bytes',0));
  EXCEPTION WHEN SQLSTATE 'PT429' THEN RETURN jsonb_build_object('code',429,'message','Too many reports, please wait a moment'); END;
  PERFORM pg_advisory_xact_lock(hashtextextended('cleaning-report:'||place_id::text||':'||problem_type,0));

  -- Push-notification labels are deliberately Czech-only (the crew is Czech;
  -- localizing push messages is out of scope). Keep the type list in sync — see
  -- the problem_type check above.
  v_type_label := CASE problem_type
    WHEN 'paper'         THEN 'Nedostatek toaletního papíru'
    WHEN 'hygiene'       THEN 'Nedostatek hygienických potřeb'
    WHEN 'contamination' THEN 'Totální znečištění ☣️'
  END;

  -- Dedup: reuse an open report of the same place + type.
  SELECT cr.* INTO v_existing
  FROM public.cleaning_reports cr
  WHERE cr.place = place_id
    AND cr.problem_type = report_cleaning_issue_internal_v1.problem_type
    AND cr.resolved_at IS NULL
  ORDER BY cr.created_at ASC
  LIMIT 1;

  IF FOUND THEN
    IF v_note IS NOT NULL THEN
      v_new_data:=COALESCE(v_existing.data,'{}'::jsonb)||jsonb_build_object('extra_notes',coalesce(v_existing.data->'extra_notes','[]'::jsonb)||to_jsonb(v_note));
      IF octet_length(v_new_data::text)>(SELECT (r->>'base_limit')::bigint FROM jsonb_array_elements(v_policy->'rules') r WHERE r->>'rule_key'='cleaning.report.bytes') THEN
        RETURN jsonb_build_object('code',429,'message','Report note capacity is limited'); END IF;
      UPDATE public.cleaning_reports SET data=v_new_data WHERE id=v_existing.id;
    END IF;
    RETURN jsonb_build_object('code',200,'data',jsonb_build_object('duplicate',true,'id',v_existing.id));
  END IF;

  INSERT INTO public.cleaning_reports (occasion, place, problem_type, note, created_by)
  VALUES (v_occasion, place_id, problem_type, v_note, v_user)
  RETURNING * INTO v_report;

  -- Notify the crew (uuid array of is_cleaning_crew users on this occasion),
  -- excluding anyone who muted cleaning notifications for themselves
  -- (occasion_users.data.cleaning_notifications_off).
  SELECT jsonb_agg("user"::text) INTO v_crew
  FROM public.occasion_users
  WHERE occasion = v_occasion
    AND is_cleaning_crew = true
    AND COALESCE((data->>'cleaning_notifications_off')::boolean, false) = false;

  IF v_crew IS NOT NULL AND jsonb_array_length(v_crew) > 0 THEN
    -- organization comes straight from the occasion row (occasions.organization
    -- is NOT NULL) — no magic fallback needed.
    SELECT organization INTO v_organization FROM public.occasions WHERE id = v_occasion;

    BEGIN
      PERFORM public.charge_notification_intent_v1(v_occasion,v_user,v_crew,v_place.title || ' - ' || v_type_label,COALESCE(v_note,v_type_label));
    INSERT INTO public.log_notifications (occasion, organization, user_id, "to", heading, content, data, abuse_admitted_at)
    VALUES (
      v_occasion,
      v_organization,
      v_user,
      v_crew,
      v_place.title || ' — ' || v_type_label,
      COALESCE(v_note, v_type_label),
      jsonb_build_object('path', 'cleaning'), statement_timestamp()
    ) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
    EXCEPTION WHEN SQLSTATE 'PT429' THEN v_notification_deferred:=true; END;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('duplicate', false, 'id', v_report.id, 'notificationDeferred',v_notification_deferred)
  );
END;
$$;


ALTER FUNCTION public.report_cleaning_issue_internal_v1(place_id bigint, problem_type text, note text) OWNER TO postgres;

--
-- Name: request_payment_reconciliation(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_payment_reconciliation(p_project_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
 PERFORM public.require_service_role();
 IF p_project_url IS NULL OR p_project_url !~ '^https://[A-Za-z0-9.-]+(:[0-9]+)?$' THEN RAISE EXCEPTION 'PAYMENT_RECOVERY_ORIGIN_INVALID'; END IF;
 PERFORM net.http_post(url:=p_project_url||'/functions/v1/payment-reconcile',
  body:=jsonb_build_object('requestSecret',public.generate_request_secret(120)),timeout_milliseconds:=90000);
END $_$;


ALTER FUNCTION public.request_payment_reconciliation(p_project_url text) OWNER TO postgres;

