--
-- Name: require_client_sync_artifact_cutoff_v1(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.require_client_sync_artifact_cutoff_v1(p_cutoff timestamp with time zone) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_cutoff IS NULL OR p_cutoff>now()-interval '7 days' THEN
    RAISE invalid_parameter_value
      USING MESSAGE='client-sync artifact cutoff must preserve the seven-day safety floor';
  END IF;
END; $$;


