--
-- Name: resolve_payment_policy_internal(jsonb, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_payment_policy_internal(p_metadata jsonb, p_duration bigint, p_feature jsonb, p_method text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE mode text; seconds bigint;
BEGIN
 mode:=coalesce(p_metadata#>>'{payment_deadline,mode}',CASE WHEN p_duration IS NULL THEN 'inherit' ELSE 'custom' END);
 IF mode NOT IN ('inherit','custom','none') THEN RAISE EXCEPTION 'PAYMENT_DEADLINE_INVALID'; END IF;
 IF p_method='cash' THEN RETURN jsonb_build_object('mode','none','cashInstructions',coalesce(p_metadata#>>'{payments,cashInstructions}','')); END IF;
 IF public.payment_method_is_online_internal(p_method) THEN RETURN '{"mode":"provider"}'::jsonb; END IF;
 IF mode='inherit' THEN mode:=coalesce(p_feature#>>'{payment_deadline,mode}','custom'); END IF;
 IF mode='none' THEN RETURN '{"mode":"none"}'::jsonb; END IF;
 seconds:=coalesce(p_duration,(p_feature->>'deadline_duration_seconds')::bigint,604800);
 IF seconds<0 OR (p_metadata#>>'{payment_deadline,mode}'='custom' AND p_duration IS NULL) THEN
  RAISE EXCEPTION 'PAYMENT_DEADLINE_INVALID'; END IF;
 RETURN jsonb_build_object('mode','custom','durationSeconds',seconds);
END $$;


ALTER FUNCTION public.resolve_payment_policy_internal(p_metadata jsonb, p_duration bigint, p_feature jsonb, p_method text) OWNER TO postgres;

--
-- Name: resolve_reception_login_qr_v1(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_reception_login_qr_v1(p_occasion bigint, p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_user uuid; v_email text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT c."user",(o.organization::text||'+'||au.email_readonly) INTO v_user,v_email
  FROM public.user_login_qr_credentials c JOIN public.occasion_users ou ON (ou.occasion,ou."user")=(c.occasion,c."user")
  JOIN public.user_info au ON au.id=c."user" JOIN public.occasions o ON o.id=c.occasion
  WHERE c.occasion=p_occasion
    AND (c.token_hash=p_token_hash OR (c.manual_token_hash=p_token_hash AND c.manual_expires_at>now()))
    AND c.revoked_at IS NULL
    AND jsonb_path_exists(COALESCE(o.features,'[]'::jsonb),'$[*] ? (@.code == "reception" && @.is_enabled == true)') FOR UPDATE OF c;
  IF v_user IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('userId',v_user,'authEmail',v_email);
END $_$;


ALTER FUNCTION public.resolve_reception_login_qr_v1(p_occasion bigint, p_token_hash text) OWNER TO postgres;

