--
-- Name: search_occasion_content(bigint, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_occasion_content(p_occasion bigint, p_query text, p_limit integer DEFAULT 50) RETURNS TABLE(entity_type text, entity_id bigint, title text, snippet text, rank real, start_time timestamp with time zone, parent_id bigint, extra jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_features        JSONB;
    v_norm_query      TEXT;
    v_effective_limit INT;
BEGIN
    SELECT o.features INTO v_features
    FROM public.occasions o
    WHERE o.id = p_occasion;

    IF v_features IS NULL THEN
        v_features := '[]'::jsonb;
    END IF;

    v_norm_query := public.f_unaccent(coalesce(p_query, ''));

    IF v_norm_query IS NULL OR length(trim(v_norm_query)) = 0 THEN
        RETURN;
    END IF;

    v_effective_limit := LEAST(GREATEST(coalesce(p_limit, 50), 1), 200);

    RETURN QUERY
    SELECT 'event'::TEXT AS entity_type, e.id::BIGINT AS entity_id, e.title,
           public.f_html_snippet(e.description) AS snippet,
           GREATEST(extensions.similarity(e.search_doc, v_norm_query), 0.0)::REAL AS rank,
           e.start_time, e.place AS parent_id,
           jsonb_strip_nulls(jsonb_build_object(
             'end_time', e.end_time,
             'max_participants', e.max_participants,
             'place_title', p.title
           )) AS extra
    FROM public.events e
    LEFT JOIN public.places p ON p.id = e.place
    WHERE e.occasion = p_occasion
      AND e.is_hidden = FALSE
      AND (e.data->>'is_counseling_slot')::boolean IS NOT TRUE
      AND e.search_doc ILIKE '%' || v_norm_query || '%'

    UNION ALL

    SELECT 'place'::TEXT, p.id::BIGINT, p.title,
           public.f_html_snippet(p.description),
           GREATEST(extensions.similarity(p.search_doc, v_norm_query), 0.0)::REAL,
           NULL::TIMESTAMPTZ, NULL::BIGINT, NULL::JSONB
    FROM public.places p
    WHERE p.occasion = p_occasion
      AND p.is_hidden = FALSE
      AND p.search_doc ILIKE '%' || v_norm_query || '%'

    UNION ALL

    SELECT
      CASE
        WHEN i.type = 'song' THEN 'song'
        WHEN i.type = 'game' THEN 'game'
        ELSE 'info'
      END::TEXT,
      i.id::BIGINT, i.title,
      public.f_html_snippet(i.description),
      GREATEST(extensions.similarity(i.search_doc, v_norm_query), 0.0)::REAL,
      NULL::TIMESTAMPTZ, NULL::BIGINT, NULL::JSONB
    FROM public.information i
    WHERE i.occasion = p_occasion
      AND i.is_hidden = FALSE
      AND i.search_doc ILIKE '%' || v_norm_query || '%'
      AND (
        (i.type = 'song' AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_features) f
          WHERE f->>'code' = 'songbook' AND (f->>'is_enabled')::boolean = TRUE
        ))
        OR
        (i.type = 'game' AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_features) f
          WHERE f->>'code' = 'game' AND (f->>'is_enabled')::boolean = TRUE
        ))
        OR
        (i.type IS NULL OR i.type NOT IN ('song', 'game'))
      )

    UNION ALL

    SELECT 'news'::TEXT, n.id::BIGINT, NULL::TEXT,
           public.f_html_snippet(n.message),
           GREATEST(extensions.similarity(n.search_doc, v_norm_query), 0.0)::REAL,
           n.created_at, NULL::BIGINT, NULL::JSONB
    FROM public.news n
    WHERE n.occasion = p_occasion
      AND n.search_doc ILIKE '%' || v_norm_query || '%'

    UNION ALL

    -- Speakers / counselors are core: always searchable, only is_hidden filters.
    -- parent_id carries the speaker's first non-hidden, non-slot event so the
    -- client can open a page where the speaker's medallion is shown.
    SELECT 'speaker'::TEXT, s.id::BIGINT, s.title,
           public.f_html_snippet(coalesce(NULLIF(s.subtitle, ''), s.description)),
           GREATEST(extensions.similarity(s.search_doc, v_norm_query), 0.0)::REAL,
           NULL::TIMESTAMPTZ,
           (SELECT es.event
              FROM public.event_speakers es
              JOIN public.events e2 ON e2.id = es.event
             WHERE es.speaker = s.id
               AND e2.is_hidden = FALSE
               AND (e2.data->>'is_counseling_slot')::boolean IS NOT TRUE
             ORDER BY e2.start_time
             LIMIT 1)::BIGINT AS parent_id,
           NULL::JSONB
    FROM public.speakers s
    WHERE s.occasion = p_occasion
      AND s.is_hidden = FALSE
      AND s.search_doc ILIKE '%' || v_norm_query || '%'

    ORDER BY rank DESC
    LIMIT v_effective_limit;
END;
$$;


ALTER FUNCTION public.search_occasion_content(p_occasion bigint, p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: search_scanner_tickets(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_scanner_tickets(p_session uuid, p_token text, p_query text, p_after bigint DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token); SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT coalesce((cfg.config#>>'{manual_search,tickets}')::boolean,false) THEN RAISE insufficient_privilege USING MESSAGE='manual_search_disabled'; END IF;
 IF length(p_query) NOT BETWEEN 2 AND 100 THEN RETURN jsonb_build_object('code',400,'reason','invalid_query','server_time',now()); END IF;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 SELECT coalesce(jsonb_agg(dto ORDER BY ticket_id),'[]'::jsonb) INTO result FROM (
 SELECT * FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config) WHERE ticket_id>p_after
 AND (strpos(lower(dto->>'holder_name'),lower(p_query))>0 OR strpos(lower(dto->>'batch_title'),lower(p_query))>0 OR strpos(lower(dto->>'symbol'),lower(p_query))>0) ORDER BY ticket_id LIMIT 30) found;
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $$;


ALTER FUNCTION public.search_scanner_tickets(p_session uuid, p_token text, p_query text, p_after bigint) OWNER TO postgres;

--
-- Name: search_scanner_users(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_scanner_users(p_session uuid, p_token text, p_query text, p_after uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE s public.scanner_sessions; cfg jsonb; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 SELECT config INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT coalesce((cfg#>>'{manual_search,users}')::boolean,false) THEN RAISE insufficient_privilege USING MESSAGE='manual_search_disabled'; END IF;
 IF length(p_query) NOT BETWEEN 2 AND 100 THEN RETURN jsonb_build_object('code',400,'reason','invalid_query'); END IF;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded'); END IF;
 SELECT coalesce(jsonb_agg(item ORDER BY id),'[]'::jsonb) INTO result FROM (
 SELECT u.id,jsonb_build_object('user_id',u.id,'holder_name',concat_ws(' ',u.name,u.surname),'symbol',u.id) item
 FROM public.occasion_users ou JOIN public.user_info u ON u.id=ou."user"
 JOIN public.occasions o ON o.id=ou.occasion
 LEFT JOIN public.organization_users orgu ON orgu."user"=u.id AND orgu.organization=o.organization
 WHERE ou.occasion=s.occasion_id AND u.id>p_after AND orgu.is_hidden IS NOT TRUE
 AND strpos(lower(concat_ws(' ',u.name,u.surname)),lower(p_query))>0 ORDER BY u.id LIMIT 30) rows;
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $$;


ALTER FUNCTION public.search_scanner_users(p_session uuid, p_token text, p_query text, p_after uuid) OWNER TO postgres;

--
-- Name: seating_admissions_internal(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seating_admissions_internal(p_transition uuid) RETURNS TABLE(ticket_id bigint, item_id bigint, order_id bigint, form_id bigint, product_id bigint, spot_id bigint, category text, reason text, ticket_symbol text, order_symbol text, holder text, product_title text)
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH scope AS (SELECT * FROM public.form_seating_transitions WHERE id=p_transition),
 sources AS (SELECT tr.* FROM public.form_seating_transitions tr,scope s
 WHERE tr.blueprint=s.blueprint AND tr.state=s.state AND tr.occasion=s.occasion),
 base AS (
 SELECT t.id ticket_id,t.occasion ticket_occasion,o.id order_id,o.form form_id,t.state ticket_state,o.state order_state,
 t.ticket_symbol,o.order_symbol,coalesce(public.get_waitlist_ticket_display_name_internal(o.form,t.data,o.data),'') holder,
 s.blueprint,s.occasion,
 (SELECT count(DISTINCT x."order") FROM eshop.order_product_ticket x WHERE x.ticket=t.id) order_count,
 (SELECT count(*) FROM eshop.order_product_ticket x JOIN eshop.products p ON p.id=x.product
 JOIN eshop.product_types pt ON pt.id=p.product_type WHERE x.ticket=t.id AND x."order"=o.id AND pt.type='spot') primary_count,
 (SELECT min(x.id) FROM eshop.order_product_ticket x JOIN eshop.products p ON p.id=x.product
 JOIN eshop.product_types pt ON pt.id=p.product_type WHERE x.ticket=t.id AND x."order"=o.id AND pt.type='spot') item_id,
 CASE WHEN t.state='waitlisted' OR o.state='waitlisted' THEN public.get_effective_waitlist_ticket_lifecycle_internal(t.id) END waiting_state
 FROM sources s JOIN eshop.orders o ON o.form=s.form JOIN eshop.order_product_ticket own ON own."order"=o.id
 JOIN eshop.tickets t ON t.id=own.ticket
 WHERE t.state IS DISTINCT FROM 'storno' AND o.state NOT IN ('storno','stock')
 GROUP BY t.id,o.id,s.blueprint,s.occasion),
 facts AS (
 SELECT a.*,x.product product_id,p.occasion product_occasion,p.title product_title,
 ARRAY(SELECT sp.id FROM eshop.spots sp JOIN eshop.blueprint_seat_bindings sb ON sb.spot=sp.id
 WHERE sp.order_product_ticket=a.item_id AND sp.product=x.product AND sb.blueprint=a.blueprint AND NOT sb.blocked) placements,
 EXISTS(SELECT 1 FROM eshop.spots sp WHERE sp.order_product_ticket=a.item_id AND sp.blueprint IS NOT NULL AND sp.blueprint<>a.blueprint) foreign_placement,
 EXISTS(SELECT 1 FROM eshop.spots sp JOIN eshop.blueprint_seat_bindings sb ON sb.spot=sp.id WHERE sb.blueprint=a.blueprint AND sp.product=x.product) addressed,
 EXISTS(SELECT 1 FROM eshop.blueprint_area_bindings ab WHERE ab.blueprint=a.blueprint AND ab.product=x.product) standing,
 EXISTS(SELECT 1 FROM eshop.ticket_batch_items bi WHERE bi.ticket_id=a.ticket_id) printed,
 EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(o.data->'tickets','[]')) tj
 WHERE tj->>'id'=a.ticket_id::text AND (SELECT count(*) FROM jsonb_array_elements(coalesce(tj->'products','[]')) pj WHERE pj->>'id'=x.product::text)=1) snapshot_valid,
 EXISTS(SELECT 1 FROM eshop.blueprint_area_bindings ab JOIN eshop.product_inventory_contexts pic ON pic.product=ab.product AND pic.inventory_context=ab.inventory_context
 WHERE ab.blueprint=a.blueprint AND ab.product=x.product AND
 (SELECT count(*) FROM eshop.spots sp WHERE sp.order_product_ticket=a.item_id AND sp.inventory_context=pic.inventory_context)>=pic.quantity)
 AND NOT EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product=x.product AND
 (SELECT count(*) FROM eshop.spots sp WHERE sp.order_product_ticket=a.item_id AND sp.inventory_context=pic.inventory_context)<>pic.quantity) standing_valid
 FROM base a LEFT JOIN eshop.order_product_ticket x ON x.id=a.item_id LEFT JOIN eshop.products p ON p.id=x.product
 JOIN eshop.orders o ON o.id=a.order_id),
 classified AS (
 SELECT f.*,CASE
 WHEN waiting_state IN ('waiting','offered') THEN NULL
 WHEN order_state='preparing_payment' THEN 'PAYMENT_PENDING'
 WHEN primary_count<>1 OR order_count<>1 OR ticket_occasion IS DISTINCT FROM occasion OR product_occasion IS DISTINCT FROM occasion OR NOT snapshot_valid THEN 'ADMISSION_DATA_AMBIGUOUS'
 WHEN foreign_placement THEN 'ADMISSION_ASSIGNED_ELSEWHERE'
 WHEN addressed AND standing THEN 'PLACEMENT_MODE_AMBIGUOUS'
 WHEN cardinality(placements)>1 THEN 'ADMISSION_DATA_AMBIGUOUS'
 WHEN cardinality(placements)=1 THEN NULL
 WHEN standing AND standing_valid THEN NULL
 WHEN ticket_state='used' THEN 'USED_TICKET_PROTECTED'
 WHEN printed THEN 'BATCH_TICKET_PRINT_IMMUTABLE'
 WHEN standing THEN 'INVENTORY_CONFLICT'
 WHEN NOT addressed THEN 'PRODUCT_MISMATCH' END problem
 FROM facts f)
 SELECT DISTINCT ON(ticket_id) ticket_id,item_id,order_id,form_id,product_id,placements[1],
 CASE WHEN waiting_state='offered' THEN 'offered' WHEN waiting_state='waiting' OR ticket_state='waitlisted' OR order_state='waitlisted' THEN 'waiting'
 WHEN problem IS NOT NULL THEN 'blocked' WHEN cardinality(placements)=1 THEN 'assigned'
 WHEN standing THEN 'standing' ELSE 'unassigned' END,CASE WHEN problem IS NULL AND cardinality(placements)=1 AND ticket_state='used' THEN 'USED_TICKET_PROTECTED' WHEN problem IS NULL AND cardinality(placements)=1 AND printed THEN 'BATCH_TICKET_PRINT_IMMUTABLE' ELSE problem END,ticket_symbol,order_symbol,holder,product_title FROM classified ORDER BY ticket_id,order_id
$$;


ALTER FUNCTION public.seating_admissions_internal(p_transition uuid) OWNER TO postgres;

--
-- Name: seating_assignment_preview_internal(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seating_assignment_preview_internal(p_transition uuid, p_mappings jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; v_mapping jsonb; a record; v_spot eshop.spots; why text; blockers jsonb:='[]'; mappings jsonb:='[]'; revisions jsonb; semantic jsonb; affected bigint[]; ids bigint[]; before_ids bigint[]; target_ids bigint[]; rev bigint;
BEGIN
 tr:=public.seating_assignment_scope_internal(p_transition,p_mappings);
 SELECT layout_revision INTO rev FROM eshop.blueprints WHERE id=tr.blueprint;
 SELECT ARRAY(SELECT DISTINCT v FROM jsonb_array_elements(p_mappings) m CROSS JOIN LATERAL unnest(ARRAY[(m->>'expectedSpotId')::bigint,(m->>'targetSpotId')::bigint]) v WHERE v IS NOT NULL ORDER BY v) INTO ids;
 SELECT ARRAY(SELECT DISTINCT member FROM unnest(ids) id CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(id)) member ORDER BY member) INTO affected;
 IF tr.state<>'organizer_managed' THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','MODE_CHANGED')); END IF;
 -- Each side independently covers its complete units. A single item moving
 -- between two members cannot count as the two purchased couch admissions.
 SELECT ARRAY(SELECT (m->>'expectedSpotId')::bigint FROM jsonb_array_elements(p_mappings)m WHERE m->>'expectedSpotId' IS NOT NULL),
 ARRAY(SELECT (m->>'targetSpotId')::bigint FROM jsonb_array_elements(p_mappings)m WHERE m->>'targetSpotId' IS NOT NULL)
 INTO before_ids,target_ids;
 IF EXISTS(SELECT 1 FROM unnest(before_ids) requested CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(requested)) member WHERE NOT member=ANY(before_ids))
 OR EXISTS(SELECT 1 FROM unnest(target_ids) requested CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(requested)) member WHERE NOT member=ANY(target_ids)) THEN
 blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','ATOMIC_UNIT_INCOMPLETE')); END IF;
 FOR v_mapping IN SELECT value FROM jsonb_array_elements(p_mappings) ORDER BY (value->>'admissionItemId')::bigint LOOP
 SELECT * INTO a FROM public.seating_admissions_internal(p_transition) WHERE ticket_id=(v_mapping->>'ticketId')::bigint AND item_id=(v_mapping->>'admissionItemId')::bigint;
 why:=NULL;
 IF NOT FOUND THEN why:='ADMISSION_DATA_AMBIGUOUS';
 ELSIF a.category NOT IN ('assigned','unassigned') THEN why:=coalesce(a.reason,'MODE_CHANGED');
 ELSIF EXISTS(SELECT 1 FROM eshop.tickets WHERE id=a.ticket_id AND state='used') THEN why:='USED_TICKET_PROTECTED';
 ELSIF EXISTS(SELECT 1 FROM eshop.ticket_batch_items WHERE ticket_id=a.ticket_id) THEN why:='BATCH_TICKET_PRINT_IMMUTABLE';
 ELSIF a.spot_id IS DISTINCT FROM (v_mapping->>'expectedSpotId')::bigint THEN why:='CONTEXT_CHANGED'; END IF;
 IF why IS NULL AND v_mapping->>'targetSpotId' IS NOT NULL THEN
 SELECT * INTO v_spot FROM eshop.spots WHERE id=(v_mapping->>'targetSpotId')::bigint;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings WHERE blueprint=tr.blueprint AND spot=v_spot.id AND NOT blocked) THEN why:='SEAT_UNAVAILABLE';
 ELSIF v_spot.product IS DISTINCT FROM a.product_id THEN why:='PRODUCT_MISMATCH';
 ELSIF v_spot.order_product_ticket IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_mappings) other WHERE (other->>'admissionItemId')::bigint=v_spot.order_product_ticket AND (other->>'expectedSpotId')::bigint=v_spot.id) THEN why:='SEAT_UNAVAILABLE';
 ELSIF v_spot.secret IS NOT NULL AND v_spot.secret_expiration_time>clock_timestamp() THEN why:='HOLD_ACTIVE';
 ELSIF v_spot.inventory_context IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.product_inventory_contexts WHERE product=a.product_id AND inventory_context=v_spot.inventory_context) THEN why:='INVENTORY_CONFLICT'; END IF;
 END IF;
 IF why IS NOT NULL THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason',why,'ticketId',v_mapping->'ticketId','spotId',v_mapping->'targetSpotId')); END IF;
 mappings:=mappings||jsonb_build_array(v_mapping||jsonb_build_object('formId',a.form_id,'productId',a.product_id));
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'revision',t.revision) ORDER BY t.id),'[]') INTO revisions
 FROM public.form_seating_transitions t WHERE t.blueprint=tr.blueprint AND t.state='organizer_managed' AND t.form IN (SELECT (m->>'formId')::bigint FROM jsonb_array_elements(mappings) m);
 semantic:=jsonb_build_object('mappings',mappings,'revisions',revisions,'layoutRevision',rev,'blockers',blockers,
 'seats',(SELECT jsonb_agg(to_jsonb(s)-'updated_at'-'created_at' ORDER BY s.id) FROM eshop.spots s WHERE s.id=ANY(affected)),
 'bindings',(SELECT jsonb_agg(to_jsonb(sb) ORDER BY sb.spot) FROM eshop.blueprint_seat_bindings sb WHERE sb.spot=ANY(affected)),
 'admissions',(SELECT jsonb_agg(jsonb_build_object('item',to_jsonb(i),'ticket',to_jsonb(t)-'updated_at','order',to_jsonb(o)-'updated_at','payment',to_jsonb(pi)) ORDER BY i.id)
 FROM eshop.order_product_ticket i JOIN eshop.tickets t ON t.id=i.ticket JOIN eshop.orders o ON o.id=i."order" LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE i.id IN (SELECT (m->>'admissionItemId')::bigint FROM jsonb_array_elements(p_mappings)m)),
 'allocations',(SELECT jsonb_agg(jsonb_build_array(s.id,s.inventory_context,s.resource,s.resource_slot,s.order_product_ticket) ORDER BY s.id) FROM eshop.spots s WHERE s.order_product_ticket IN(SELECT (m->>'admissionItemId')::bigint FROM jsonb_array_elements(p_mappings)m)),
 'requirements',(SELECT jsonb_agg(to_jsonb(pic) ORDER BY pic.product,pic.inventory_context) FROM eshop.product_inventory_contexts pic WHERE product IN(SELECT (m->>'productId')::bigint FROM jsonb_array_elements(mappings)m)));
 RETURN jsonb_build_object('fingerprint',encode(extensions.digest(semantic::text,'sha256'),'hex'),'revisions',revisions,'mappings',mappings,'blockers',blockers,'layoutRevision',rev);
END $$;


ALTER FUNCTION public.seating_assignment_preview_internal(p_transition uuid, p_mappings jsonb) OWNER TO postgres;

--
-- Name: form_seating_transitions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.form_seating_transitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    occasion bigint NOT NULL,
    form bigint,
    blueprint bigint,
    state text DEFAULT 'organizer_managed'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    started_by uuid NOT NULL,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    finished_by uuid,
    finished_at timestamp with time zone,
    CONSTRAINT form_seating_transitions_check CHECK (((state <> 'organizer_managed'::text) OR ((form IS NOT NULL) AND (blueprint IS NOT NULL)))),
    CONSTRAINT form_seating_transitions_check1 CHECK ((((state = 'organizer_managed'::text) AND (finished_at IS NULL) AND (finished_by IS NULL)) OR ((state <> 'organizer_managed'::text) AND (finished_at IS NOT NULL) AND (finished_by IS NOT NULL)))),
    CONSTRAINT form_seating_transitions_revision_check CHECK ((revision > 0)),
    CONSTRAINT form_seating_transitions_state_check CHECK ((state = ANY (ARRAY['organizer_managed'::text, 'published'::text, 'cancelled'::text])))
);


ALTER TABLE public.form_seating_transitions OWNER TO postgres;

--
-- Name: seating_assignment_scope_internal(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seating_assignment_scope_internal(p_transition uuid, p_mappings jsonb) RETURNS public.form_seating_transitions
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; v_mapping jsonb;
BEGIN
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition;
 IF tr.id IS NULL OR NOT public.can_assign_existing_admissions(tr.occasion) THEN RAISE insufficient_privilege USING MESSAGE='order reader and writer required'; END IF;
 IF jsonb_typeof(p_mappings) IS DISTINCT FROM 'array' OR jsonb_array_length(p_mappings) NOT BETWEEN 1 AND least(256,(SELECT hard_cap FROM public.abuse_policy_rules WHERE rule_key='order.mutation.items')) OR octet_length(p_mappings::text)>131072 THEN
 RAISE invalid_parameter_value USING MESSAGE='invalid assignment batch'; END IF;
 FOR v_mapping IN SELECT value FROM jsonb_array_elements(p_mappings) LOOP
 IF jsonb_typeof(v_mapping) IS DISTINCT FROM 'object' OR NOT v_mapping ?& ARRAY['ticketId','admissionItemId','expectedSpotId','targetSpotId']
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(v_mapping) k WHERE k NOT IN ('ticketId','admissionItemId','expectedSpotId','targetSpotId'))
 OR v_mapping->>'ticketId' IS NULL OR v_mapping->>'admissionItemId' IS NULL THEN
 RAISE invalid_parameter_value USING MESSAGE='exact changed item mapping required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket i JOIN eshop.orders o ON o.id=i."order"
 JOIN public.form_seating_transitions v_spot ON v_spot.form=o.form AND v_spot.blueprint=tr.blueprint AND v_spot.state=tr.state
 WHERE i.id=(v_mapping->>'admissionItemId')::bigint AND i.ticket=(v_mapping->>'ticketId')::bigint AND o.occasion=tr.occasion)
 OR EXISTS(SELECT 1 FROM eshop.spots WHERE id IN ((v_mapping->>'expectedSpotId')::bigint,(v_mapping->>'targetSpotId')::bigint) AND (occasion<>tr.occasion OR blueprint IS DISTINCT FROM tr.blueprint)) THEN
 RAISE insufficient_privilege USING MESSAGE='assignment context unavailable'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_mappings) m WHERE m->'expectedSpotId' IS DISTINCT FROM m->'targetSpotId') THEN
 RAISE invalid_parameter_value USING MESSAGE='changed assignment batch required'; END IF;
 IF (SELECT count(DISTINCT value->>'admissionItemId') FROM jsonb_array_elements(p_mappings))<>jsonb_array_length(p_mappings)
 OR (SELECT count(*) FROM jsonb_array_elements(p_mappings) WHERE value->>'targetSpotId' IS NOT NULL)<>(SELECT count(DISTINCT value->>'targetSpotId') FROM jsonb_array_elements(p_mappings)) THEN
 RAISE invalid_parameter_value USING MESSAGE='duplicate assignment identity'; END IF;
 RETURN tr;
END $$;


ALTER FUNCTION public.seating_assignment_scope_internal(p_transition uuid, p_mappings jsonb) OWNER TO postgres;

--
-- Name: seating_publication_preview_internal(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seating_publication_preview_internal(p_transition uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; ids uuid[]; forms_data jsonb; catalog jsonb; blockers jsonb:='[]'; obligations jsonb; revisions jsonb; semantic jsonb; row record;
BEGIN
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition;
 IF tr.id IS NULL OR NOT coalesce(public.can_author_forms(tr.occasion),false) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 SELECT array_agg(id ORDER BY id),coalesce(jsonb_agg(jsonb_build_object('id',id,'revision',revision) ORDER BY id),'[]') INTO ids,revisions
 FROM public.form_seating_transitions WHERE blueprint=tr.blueprint AND state='organizer_managed';
 IF tr.state<>'organizer_managed' THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','MODE_CHANGED')); END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'participantCapacity',f.participant_capacity,'blueprintId',tr.blueprint,
 'capacity',public.get_form_capacity_snapshot_internal(f.id),'available',NULL) ORDER BY f.id),'[]') INTO forms_data
 FROM public.forms f JOIN public.form_seating_transitions t ON t.form=f.id WHERE t.id=ANY(ids);
 FOR row IN SELECT * FROM public.seating_admissions_internal(p_transition) WHERE category IN ('blocked','unassigned','waiting','offered') LOOP
 blockers:=blockers||jsonb_build_array(jsonb_build_object('reason',CASE row.category WHEN 'waiting' THEN 'WAITLIST_PENDING' WHEN 'offered' THEN 'OFFERS_PENDING' WHEN 'unassigned' THEN 'ADMISSION_SOURCE_REQUIRES_SEATING' ELSE row.reason END,'formId',row.form_id));
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=tr.blueprint AND layout->>'schemaVersion'='2') THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','BLUEPRINT_LAYOUT_MIGRATION_REQUIRED')); END IF;
 IF EXISTS(SELECT 1 FROM public.forms WHERE blueprint=tr.blueprint) THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','TARGET_ALREADY_PUBLIC')); END IF;
 FOR row IN SELECT DISTINCT f.id FROM public.forms f JOIN public.form_fields ff ON ff.form=f.id AND NOT ff.is_hidden JOIN eshop.products p ON p.product_type=ff.product_type
 WHERE f.occasion=tr.occasion AND NOT EXISTS(SELECT 1 FROM public.form_seating_transitions t WHERE t.id=ANY(ids) AND t.form=f.id)
 AND p.id IN(SELECT s.product FROM eshop.spots s JOIN eshop.blueprint_seat_bindings sb ON sb.spot=s.id WHERE sb.blueprint=tr.blueprint UNION SELECT product FROM eshop.blueprint_area_bindings WHERE blueprint=tr.blueprint) LOOP
 blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','UNCOVERED_ADMISSION_SOURCE','formId',row.id)); END LOOP;
 -- Products cannot already promise the same entitlement through another live hall.
 IF EXISTS(SELECT 1 FROM eshop.spots s JOIN eshop.blueprint_seat_bindings sb ON sb.spot=s.id JOIN public.forms f ON f.blueprint=sb.blueprint
 WHERE sb.blueprint<>tr.blueprint AND s.product IN(SELECT product FROM eshop.spots WHERE blueprint=tr.blueprint)) THEN
 blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','TARGET_ALREADY_PUBLIC')); END IF;
 IF EXISTS(SELECT 1 FROM eshop.spots WHERE blueprint=tr.blueprint AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','HOLD_ACTIVE')); END IF;
 WITH offerings AS(SELECT s.product product_id,count(*) FILTER(WHERE NOT sb.blocked) seats,false standing
 FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots s ON s.id=sb.spot WHERE sb.blueprint=tr.blueprint GROUP BY s.product
 UNION ALL SELECT product,0,true FROM eshop.blueprint_area_bindings WHERE blueprint=tr.blueprint)
 SELECT coalesce(jsonb_agg(jsonb_build_object('productId',p.id,'title',p.title,'price',p.price,'currencyCode',p.currency_code,'maximum',p.maximum,
 'seats',o.seats,'standing',o.standing,'supply',public.blueprint_product_availability_internal(p.id)) ORDER BY p.id,o.standing),'[]') INTO catalog FROM offerings o JOIN eshop.products p ON p.id=o.product_id;
 SELECT coalesce(jsonb_agg(c||jsonb_build_object('capacity',CASE WHEN (c->>'standing')::boolean THEN (c#>>'{supply,capacity}')::bigint ELSE least((c->>'seats')::bigint,(c#>>'{supply,capacity}')::bigint) END,
 'available',CASE WHEN (c->>'standing')::boolean THEN (c#>>'{supply,available}')::bigint ELSE least((c#>>'{supply,available}')::bigint,(SELECT count(*) FROM eshop.spots s JOIN eshop.blueprint_seat_bindings sb ON sb.spot=s.id WHERE sb.blueprint=tr.blueprint AND s.product=(c->>'productId')::bigint AND NOT sb.blocked AND s.order_product_ticket IS NULL AND NOT coalesce(s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp(),false))) END) ORDER BY (c->>'productId')::bigint),'[]') INTO catalog FROM jsonb_array_elements(catalog)c;
 SELECT coalesce(jsonb_agg(f||jsonb_build_object('capacity',(SELECT coalesce(sum((c->>'capacity')::bigint),0) FROM jsonb_array_elements(catalog)c),
 'available',(SELECT coalesce(sum((c->>'available')::bigint),0) FROM jsonb_array_elements(catalog)c)) ORDER BY (f->>'id')::bigint),'[]') INTO forms_data FROM jsonb_array_elements(forms_data)f;
 IF jsonb_array_length(catalog)=0 OR NOT EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=tr.blueprint AND NOT sb.blocked)
 AND NOT EXISTS(SELECT 1 FROM eshop.blueprint_area_bindings WHERE blueprint=tr.blueprint) THEN blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','INVENTORY_CONFLICT')); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(catalog) c WHERE c->>'price' IS NULL OR c->>'currencyCode' IS NULL OR (c#>>'{supply,capacity}')::bigint=0)
 OR EXISTS(SELECT 1 FROM eshop.blueprint_area_bindings a WHERE a.blueprint=tr.blueprint AND NOT EXISTS(SELECT 1 FROM eshop.product_inventory_contexts WHERE product=a.product AND inventory_context=a.inventory_context)) THEN
 blockers:=blockers||jsonb_build_array(jsonb_build_object('reason','INVENTORY_CONFLICT')); END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY ticket_id,item_id),'[]') INTO obligations FROM public.seating_admissions_internal(p_transition) a;
 semantic:=jsonb_build_object('cohort',revisions,'catalog',catalog,'blockers',blockers,'obligations',obligations,
 'forms',(SELECT jsonb_agg(to_jsonb(f) ORDER BY f.id) FROM public.forms f WHERE f.occasion=tr.occasion),
 'fields',(SELECT jsonb_agg(to_jsonb(ff) ORDER BY ff.id) FROM public.form_fields ff JOIN public.forms f ON f.id=ff.form WHERE f.occasion=tr.occasion),
 'orders',(SELECT jsonb_agg(to_jsonb(o) ORDER BY o.id) FROM eshop.orders o WHERE o.form IN(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids))),
 'tickets',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM eshop.tickets t WHERE t.id IN(SELECT x.ticket FROM eshop.order_product_ticket x JOIN eshop.orders o ON o.id=x."order" WHERE o.form IN(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids)))),
 'layout',(SELECT layout FROM eshop.blueprints WHERE id=tr.blueprint),'revision',(SELECT layout_revision FROM eshop.blueprints WHERE id=tr.blueprint),
 'seats',(SELECT jsonb_agg(to_jsonb(s)-'updated_at'-'created_at' ORDER BY s.id) FROM eshop.spots s WHERE blueprint=tr.blueprint),
 'offers',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM eshop.waitlist_offer_slots s WHERE s.form_id IN(SELECT form FROM public.form_seating_transitions WHERE id=ANY(ids))));
 RETURN jsonb_build_object('fingerprint',encode(extensions.digest(semantic::text,'sha256'),'hex'),'transitionIds',coalesce(to_jsonb(ids),'[]'),'revisions',revisions,
 'forms',forms_data,'catalog',catalog,'blockers',blockers,'layoutRevision',(SELECT layout_revision FROM eshop.blueprints WHERE id=tr.blueprint));
END $$;


ALTER FUNCTION public.seating_publication_preview_internal(p_transition uuid) OWNER TO postgres;

--
-- Name: seed_org_with_admin(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.seed_org_with_admin(admin_email text, admin_password text) RETURNS TABLE(org_id bigint, unit_id bigint, admin_uid uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    -- Security Check
    PERFORM public.require_service_role();
    PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('organization.creation',NULL,NULL),jsonb_build_object('global','all'));

    ----------------------------------------------------------------
    -- 1. Create Organization with registration enabled
    ----------------------------------------------------------------
    INSERT INTO public.organizations (title, data)
    VALUES (
        'Seed Organization',
        '{"IS_REGISTRATION_ENABLED": "true"}'::jsonb
    )
    RETURNING id INTO org_id;

    PERFORM public.initialize_notification_center_internal(org_id);

    ----------------------------------------------------------------
    -- 2. Create a Unit in the Organization
    ----------------------------------------------------------------
    INSERT INTO public.units (title, organization, data)
    VALUES (
        'Seed Unit',
        org_id,
        '{}'::jsonb
    )
    RETURNING id INTO unit_id;

    ----------------------------------------------------------------
    -- 3. Create the Admin User using your provided function
    ----------------------------------------------------------------
    admin_uid := create_user_in_organization_with_data_pure(
        org_id,
        admin_email,
        admin_password,
        '{"name": "Admin", "surname": "User", "sex": "male"}'::jsonb
    );

    ----------------------------------------------------------------
    -- 4. Grant Admin Rights on Organization and Unit levels
    ----------------------------------------------------------------
    PERFORM public.admit_unit_creation_v1(admin_uid,org_id);
    INSERT INTO public.organization_users ("user", organization, is_admin)
    VALUES (admin_uid, org_id, true);

    INSERT INTO public.unit_users (unit, "user", is_manager, is_editor, is_editor_view)
    VALUES (unit_id, admin_uid, true, true, true);

    RETURN;
END;
$$;


ALTER FUNCTION public.seed_org_with_admin(admin_email text, admin_password text) OWNER TO postgres;

--
-- Name: select_spot(uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_spot(form_key uuid, secret_id uuid, spot_id bigint, selecting boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE ids bigint[]; member_id bigint; r jsonb; occ bigint; bp bigint; fid bigint;
BEGIN
 SELECT occasion,blueprint,id INTO occ,bp,fid FROM public.forms WHERE key=form_key;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 PERFORM pg_advisory_xact_lock(hashtextextended('hold:'||secret_id::text,0));
 ids:=public.blueprint_selection_unit_spots_internal(spot_id);
 PERFORM 1 FROM public.forms WHERE id=fid FOR UPDATE;
 PERFORM public.lock_blueprint_hold_scope_internal(ids);
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 BEGIN
  IF selecting AND EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprint_seat_bindings b ON b.spot=s.id
   WHERE s.id=ANY(ids) AND (b.blocked OR s.product IS NULL)
    AND NOT coalesce(s.secret=secret_id AND s.secret_expiration_time>clock_timestamp(),false)) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_UNAVAILABLE'; END IF;
  IF selecting THEN
   r:=public.blueprint_hold_admission_internal(fid,ids,secret_id);
   IF (r->>'code')::integer<>200 THEN RETURN r; END IF;
  END IF;
  FOREACH member_id IN ARRAY ids LOOP
   r:=public.select_spot_single_internal_v1(form_key,secret_id,member_id,selecting);
   IF coalesce((r->>'code')::integer,500)<>200 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_HOLD_REJECTED'; END IF;
  END LOOP;
 EXCEPTION WHEN check_violation THEN
  RETURN coalesce(r,jsonb_build_object('code',409,'reason',SQLERRM,'message',SQLERRM));
 END;
 RETURN r||jsonb_build_object('spotIds',to_jsonb(ids));
END $$;


ALTER FUNCTION public.select_spot(form_key uuid, secret_id uuid, spot_id bigint, selecting boolean) OWNER TO postgres;

--
-- Name: select_spot_single_internal_v1(uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_spot_single_internal_v1(form_key uuid, secret_id uuid, spot_id bigint, selecting boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE bp bigint; occ bigint; org bigint; un bigint; s eshop.spots; policy jsonb; scopes jsonb; costs jsonb; r jsonb; held bigint; duration_seconds integer; form_data jsonb; form_open boolean; fid bigint;
BEGIN
 IF secret_id IS NULL OR selecting IS NULL THEN RETURN jsonb_build_object('code',400,'message','Invalid reservation'); END IF;
 SELECT f.blueprint,f.occasion,o.organization,o.unit,f.id,f.is_open INTO bp,occ,org,un,fid,form_open FROM public.forms f
 JOIN public.occasions o ON o.id=f.occasion WHERE f.key=form_key;
 IF bp IS NULL THEN RETURN jsonb_build_object('code',404,'message','Form blueprint not found'); END IF;
 PERFORM public.check_occasion_writable(occ);
 -- A buyer's active inventory is serialized before the individual spot lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('hold:'||secret_id::text,0));
 SELECT * INTO s FROM eshop.spots WHERE id=spot_id AND blueprint=bp FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','Spot not found'); END IF;
 IF s.order_product_ticket IS NOT NULL THEN RETURN jsonb_build_object('code',409,'message','Spot is already ordered'); END IF;
 IF s.secret_expiration_time<=clock_timestamp() THEN
  UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL WHERE id=spot_id;
  s.secret:=NULL; s.secret_expiration_time:=NULL;
 END IF;
 IF s.secret IS NOT NULL AND s.secret IS DISTINCT FROM secret_id THEN
  RETURN jsonb_build_object('code',403,'message','Spot is held by another buyer'); END IF;
 IF NOT selecting THEN
  UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL,updated_at=now() WHERE id=spot_id;
  RETURN jsonb_build_object('code',200,'message','Spot deselected');
 END IF;
 -- A retry cannot move the original expiration, including after another tab reload.
 IF s.secret=secret_id THEN RETURN jsonb_build_object('code',200,'message','Spot selected','expiresAt',s.secret_expiration_time); END IF;
 r:=public.blueprint_hold_admission_internal(fid,ARRAY[s.id],secret_id);
 IF (r->>'code')::integer<>200 THEN RETURN r; END IF;
 IF selecting AND public.can_write_orders(occ) IS NOT TRUE THEN
  form_data:=public.get_effective_form_data(fid);
  IF form_open IS NOT TRUE OR
   (coalesce(form_data#>>'{schedule,start_time}',form_data->>'start_time'))::timestamptz>clock_timestamp() OR
   (coalesce(form_data#>>'{schedule,end_time}',form_data->>'end_time'))::timestamptz<clock_timestamp() THEN
   RETURN jsonb_build_object('code',403,'message','Form is not open'); END IF;
 END IF;
 policy:=public.abuse_effective_rules_v1('spot.hold',un,org);
 scopes:=jsonb_build_object('recipient',secret_id,'unit',un,'organization',org);
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
 END LOOP;
 SELECT count(*) INTO held FROM eshop.spots WHERE secret=secret_id AND secret_expiration_time>clock_timestamp() AND order_product_ticket IS NULL;
 costs:=jsonb_build_object('hold.active.buyer',held+1);
 PERFORM public.abuse_charge_v1(policy,scopes,costs);
 SELECT (x->>'base_limit')::integer INTO duration_seconds FROM jsonb_array_elements(public.abuse_effective_rules_v1('hold.duration',un,org)->'rules') x;
 IF duration_seconds IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 UPDATE eshop.spots SET secret=secret_id,secret_expiration_time=clock_timestamp()+make_interval(secs=>duration_seconds),updated_at=now() WHERE id=spot_id RETURNING * INTO s;
 RETURN jsonb_build_object('code',200,'message','Spot selected','expiresAt',s.secret_expiration_time);
END $$;


ALTER FUNCTION public.select_spot_single_internal_v1(form_key uuid, secret_id uuid, spot_id bigint, selecting boolean) OWNER TO postgres;

--
-- Name: sell_ticket_batch_items_client_sync_v1(uuid, bigint[], jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sell_ticket_batch_items_client_sync_v1(p_batch uuid, p_tickets bigint[], p_contact jsonb, p_send_tickets boolean, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE b eshop.ticket_batches; occ public.occasions; claimed jsonb; oid bigint; pi bigint; tx bigint;
 v_amount numeric; tickets jsonb; sale_data jsonb; ids bigint[]; email text;
BEGIN
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=b.occasion;
 IF auth.uid() IS NULL OR public.can_write_orders(b.occasion) IS NOT TRUE
 OR public.get_is_manager_on_unit(occ.unit) IS NOT TRUE THEN RAISE insufficient_privilege; END IF;
 ids:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
 IF cardinality(ids) NOT BETWEEN 1 AND 20 OR array_position(ids,NULL) IS NOT NULL
 OR cardinality(ids) IS NULL OR p_send_tickets IS NULL
 OR jsonb_typeof(coalesce(p_contact,'{}'))<>'object' OR octet_length(coalesce(p_contact,'{}')::text)>8192
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(coalesce(p_contact,'{}')) k WHERE k NOT IN ('email','name','surname','phone')) THEN
  RAISE invalid_parameter_value USING MESSAGE='BATCH_SALE_SELECTION_INVALID'; END IF;
 sale_data:=jsonb_strip_nulls(coalesce(p_contact,'{}'));
 email:=nullif(trim(sale_data->>'email'),'');
 IF email IS NULL THEN sale_data:=sale_data-'email';
 ELSIF NOT public.email_address_is_valid(email) THEN RAISE EXCEPTION 'BATCH_CONTACT_INVALID';
 ELSE sale_data:=jsonb_set(sale_data,'{email}',to_jsonb(email)); END IF;
 IF p_send_tickets AND email IS NULL THEN RAISE EXCEPTION 'BATCH_DELIVERY_EMAIL_REQUIRED'; END IF;
 claimed:=public.begin_client_mutation_v1(p_command_id,'inventory.ticket_batch.sell',b.occasion,auth.uid(),
 encode(extensions.digest(jsonb_build_object('batch',b.id,'tickets',ids,'contact',sale_data,'sendTickets',p_send_tickets)::text,'sha256'),'hex'));
 IF claimed->>'disposition'='replay' THEN RETURN claimed->'response'; END IF;
 BEGIN
 PERFORM public.check_ticket_batch_cash_unit_internal(b.occasion);
 PERFORM public.admit_order_mutation_v1(b.occasion,cardinality(ids));
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[b.stock_order_id]);
 SELECT * INTO STRICT b FROM eshop.ticket_batches WHERE id=p_batch FOR UPDATE;
 IF b.manifest_hash IS NULL OR NOT EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND kind='print')
 OR EXISTS(SELECT 1 FROM eshop.ticket_batch_document_parts WHERE batch_id=b.id AND state<>'ready') THEN
  RAISE EXCEPTION 'BATCH_PRINT_NOT_READY'; END IF;
 PERFORM 1 FROM eshop.tickets WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM eshop.ticket_batch_items i JOIN eshop.tickets t ON t.id=i.ticket_id
  WHERE i.batch_id=b.id AND t.id=ANY(ids) AND i.sale_order_id IS NULL AND t.state='ordered'
  AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=t.id AND x."order"=b.stock_order_id)
  AND NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=t.id AND x."order"<>b.stock_order_id))<>cardinality(ids) THEN
  RAISE EXCEPTION 'ITEM_NOT_IN_STOCK'; END IF;
 SELECT jsonb_agg(t ORDER BY (t->>'id')::bigint) INTO tickets FROM jsonb_array_elements(b.snapshot->'tickets') t WHERE (t->>'id')::bigint=ANY(ids);
 SELECT sum((p->>'price')::numeric) INTO v_amount FROM jsonb_array_elements(tickets) t CROSS JOIN LATERAL jsonb_array_elements(t->'products') p;
 IF v_amount IS NULL OR v_amount<0 THEN RAISE EXCEPTION 'BATCH_SNAPSHOT_INVALID'; END IF;
 oid:=public.allocate_ticket_order_identity_internal(b.form);
 INSERT INTO eshop.payment_info(amount,currency_code,payment_method) VALUES(v_amount,b.currency_code,'bank') RETURNING id INTO pi;
 sale_data:=sale_data||jsonb_build_object('tickets',tickets,'ticketBatchOrigin',jsonb_build_object('batchId',b.id,'sendTickets',p_send_tickets));
 UPDATE eshop.orders SET price=v_amount,currency_code=b.currency_code,payment_info=pi,data=sale_data,updated_at=clock_timestamp() WHERE id=oid;
 UPDATE eshop.order_product_ticket SET "order"=oid WHERE ticket=ANY(ids) AND "order"=b.stock_order_id;
 UPDATE eshop.ticket_batch_items SET sale_order_id=oid WHERE batch_id=b.id AND ticket_id=ANY(ids) AND sale_order_id IS NULL;
 UPDATE eshop.orders stock SET data=jsonb_set(stock.data,'{tickets}',coalesce((SELECT jsonb_agg(t) FROM jsonb_array_elements(stock.data->'tickets') t
  WHERE NOT (t->>'id')::bigint=ANY(ids)),'[]')),updated_at=clock_timestamp() WHERE id=b.stock_order_id;
 tx:=public.insert_manual_transaction_internal_v1(v_amount,b.currency_code,occ.unit,NULL,clock_timestamp(),'Ticket batch cash sale',pi);
 IF NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=oid AND state='paid')
 OR NOT EXISTS(SELECT 1 FROM eshop.transactions tr WHERE tr.id=tx AND tr.payment_info=pi AND tr.amount=v_amount) THEN
  RAISE EXCEPTION 'BATCH_PAYMENT_NOT_COMMITTED'; END IF;
 INSERT INTO eshop.orders_history("order",state,data,price,currency_code) VALUES
 (b.stock_order_id,'stock',jsonb_build_object('saleOrderId',oid,'ticketIds',ids),NULL,b.currency_code),
 (oid,'paid',jsonb_build_object('batchId',b.id,'transactionId',tx,'ticketIds',ids),v_amount,b.currency_code);
 UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=b.form;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,b.occasion,'inventory.ticket_batch.sell',
 jsonb_build_array(jsonb_build_object('entityType','order','entityId',b.stock_order_id,'operation','update','safeLabel','Ticket batch',
 'changedFields',jsonb_build_array('tickets','parent')),jsonb_build_object('entityType','order','entityId',oid,'operation','insert',
 'safeLabel','Cash sale','changedFields',jsonb_build_array('tickets','payment','parent'))),
 ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=b.occasion AND is_editor_order_view),
 jsonb_build_object('batchId',b.id,'orderId',oid,'transactionId',tx,'amount',v_amount,'currency',b.currency_code,'ticketIds',ids));
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM=ANY(ARRAY['ITEM_NOT_IN_STOCK','BATCH_PRINT_NOT_READY','CASH_SALE_INVOICE_WORKFLOW_REQUIRED']) THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('errorCode',SQLERRM));
  END IF;
  RAISE;
 END;
END $$;


ALTER FUNCTION public.sell_ticket_batch_items_client_sync_v1(p_batch uuid, p_tickets bigint[], p_contact jsonb, p_send_tickets boolean, p_command_id uuid) OWNER TO postgres;

--
-- Name: service_fee_reference_valid_internal(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.service_fee_reference_valid_internal(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
 SELECT p_value IS NOT NULL
  AND length(btrim(p_value,U&' \00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))>0
  AND p_value !~ '[[:cntrl:]]'
  -- Match JavaScript's UTF-16 length limit, including supplementary characters.
  AND (SELECT coalesce(sum(CASE WHEN ascii(c)>65535 THEN 2 ELSE 1 END),0)
       FROM unnest(string_to_array(p_value,NULL)) AS chars(c))<=1000
$$;


ALTER FUNCTION public.service_fee_reference_valid_internal(p_value text) OWNER TO postgres;

--
-- Name: set_abuse_policy_v1(bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_abuse_policy_v1(p_expected_revision bigint, p_reason text, p_changes jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_revision bigint; c jsonb; r public.abuse_policy_rules; v_old jsonb; v_author text;
BEGIN
 PERFORM public.require_service_role();
 IF length(btrim(p_reason)) NOT BETWEEN 8 AND 1000 OR p_reason IS NULL OR jsonb_typeof(p_changes) IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_changes) NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid abuse policy batch'; END IF;
 SELECT revision INTO v_revision FROM public.abuse_policy_revision FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM v_revision THEN RAISE serialization_failure USING MESSAGE='abuse policy revision conflict'; END IF;
 v_author:=coalesce(auth.uid()::text,session_user::text);
 SELECT jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_rules x),
 'overrides',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_overrides x)) INTO v_old;
 FOR c IN SELECT value FROM jsonb_array_elements(p_changes) LOOP
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(c) k WHERE k NOT IN ('rule_key','base_limit','target_kind','target_id','expires_at')) THEN
   RAISE invalid_parameter_value USING MESSAGE='unsupported abuse policy parameter'; END IF;
  SELECT * INTO r FROM public.abuse_policy_rules WHERE rule_key=c->>'rule_key';
  IF NOT FOUND OR (c->>'base_limit')::bigint IS NULL OR (c->>'base_limit')::bigint NOT BETWEEN 1 AND r.hard_cap THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid abuse policy limit'; END IF;
  IF c ? 'target_kind' THEN
   IF (c->>'target_kind'='unit' AND r.scope_kind<>'unit') OR
    (c->>'target_kind'='organization' AND r.scope_kind NOT IN ('unit','organization')) OR
    c->>'target_kind' NOT IN ('unit','organization') OR (c->>'target_id')::bigint IS NULL OR
    (c->>'expires_at')::timestamptz IS NULL OR (c->>'expires_at')::timestamptz<=statement_timestamp() OR
    (c->>'expires_at')::timestamptz>statement_timestamp()+interval '90 days' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid abuse override scope or expiry'; END IF;
   IF NOT (CASE WHEN c->>'target_kind'='unit' THEN EXISTS(SELECT 1 FROM public.units WHERE id=(c->>'target_id')::bigint)
    ELSE EXISTS(SELECT 1 FROM public.organizations WHERE id=(c->>'target_id')::bigint) END) THEN
    RAISE invalid_parameter_value USING MESSAGE='unknown abuse override target'; END IF;
   INSERT INTO public.abuse_policy_overrides VALUES(r.rule_key,c->>'target_kind',(c->>'target_id')::bigint,
    (c->>'base_limit')::bigint,(c->>'expires_at')::timestamptz,p_reason,v_author)
   ON CONFLICT(rule_key,target_kind,target_id) DO UPDATE SET base_limit=excluded.base_limit,expires_at=excluded.expires_at,reason=excluded.reason,author=excluded.author;
  ELSE
   IF c ? 'target_id' OR c ? 'expires_at' THEN RAISE invalid_parameter_value USING MESSAGE='override target required'; END IF;
   UPDATE public.abuse_policy_rules SET base_limit=(c->>'base_limit')::bigint WHERE rule_key=r.rule_key;
  END IF;
 END LOOP;
 UPDATE public.abuse_policy_revision SET revision=revision+1 RETURNING revision INTO v_revision;
 INSERT INTO public.abuse_policy_audit SELECT v_revision,clock_timestamp(),v_author,p_reason,v_old,
  jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_rules x),
   'overrides',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_overrides x));
 RETURN v_revision;
END $$;


ALTER FUNCTION public.set_abuse_policy_v1(p_expected_revision bigint, p_reason text, p_changes jsonb) OWNER TO postgres;

--
-- Name: set_account_deletion_email_state(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_account_deletion_email_state(p_request_id uuid, p_delivered boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.require_service_role();
  UPDATE public.account_deletion_requests
  SET status = CASE WHEN p_delivered THEN 'email_sent' ELSE 'revoked' END,
      email_sent_at = CASE WHEN p_delivered THEN clock_timestamp() ELSE NULL END,
      token_hash = CASE WHEN p_delivered THEN token_hash ELSE NULL END,
      masked_email = CASE WHEN p_delivered THEN masked_email ELSE NULL END,
      error_class = CASE WHEN p_delivered THEN NULL ELSE 'email_delivery' END,
      updated_at = clock_timestamp()
  WHERE id = p_request_id AND status = 'email_pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'account_deletion_request_state_conflict' USING ERRCODE = '55000'; END IF;
END;
$$;


ALTER FUNCTION public.set_account_deletion_email_state(p_request_id uuid, p_delivered boolean) OWNER TO postgres;

--
-- Name: set_cleaning_notifications_muted(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_cleaning_notifications_muted(p_occasion bigint, p_muted boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE result jsonb;
BEGIN
 result:=public.set_cleaning_notifications_muted_client_sync_v1(p_occasion,p_muted,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',result->'code','message',result#>'{data,message}','data',result->'data');
END $$;


ALTER FUNCTION public.set_cleaning_notifications_muted(p_occasion bigint, p_muted boolean) OWNER TO postgres;

--
-- Name: set_cleaning_notifications_muted_client_sync_v1(bigint, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_cleaning_notifications_muted_client_sync_v1(p_occasion bigint, p_muted boolean, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'muted',COALESCE(p_muted,false))::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.notifications.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE((ou.data->>'cleaning_notifications_off')::boolean,false)
    INTO v_current FROM public.occasion_users ou WHERE ou.occasion=p_occasion
      AND ou."user"=v_actor FOR UPDATE;
  v_result:=public.set_cleaning_notifications_muted_internal_v1(p_occasion,p_muted);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM COALESCE(p_muted,false) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor));
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.notifications.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','cleaning_preference','entityId',v_actor,'operation','update',
      'safeLabel','Cleaning notifications','changedFields',jsonb_build_array('muted'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION public.set_cleaning_notifications_muted_client_sync_v1(p_occasion bigint, p_muted boolean, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_cleaning_notifications_muted_internal_v1(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_cleaning_notifications_muted_internal_v1(p_occasion bigint, p_muted boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  UPDATE public.occasion_users
  SET data = COALESCE(data, '{}'::jsonb)
             || jsonb_build_object('cleaning_notifications_off', COALESCE(p_muted, false))
  WHERE occasion = p_occasion AND "user" = v_user
  RETURNING true INTO v_found;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('muted', COALESCE(p_muted, false))
  );
END;
$$;


ALTER FUNCTION public.set_cleaning_notifications_muted_internal_v1(p_occasion bigint, p_muted boolean) OWNER TO postgres;

