ALTER FUNCTION public.set_cleaning_reporter_blocked(p_occasion bigint, p_user uuid, p_blocked boolean) OWNER TO postgres;

--
-- Name: set_cleaning_reporter_blocked_client_sync_v1(bigint, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_cleaning_reporter_blocked_client_sync_v1(p_occasion bigint, p_user uuid, p_blocked boolean, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user,'blocked',p_blocked)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.reporter.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT ou.is_cleaning_blocked INTO v_current FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.set_cleaning_reporter_blocked_internal_v1(
    p_occasion,p_user,p_blocked);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM p_blocked THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user));
  IF p_user=v_actor THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.reporter.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Cleaning reporter','changedFields',jsonb_build_array('blocked'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION public.set_cleaning_reporter_blocked_client_sync_v1(p_occasion bigint, p_user uuid, p_blocked boolean, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_cleaning_reporter_blocked_internal_v1(bigint, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_cleaning_reporter_blocked_internal_v1(p_occasion bigint, p_user uuid, p_blocked boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  IF p_user IS NULL THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Target user is required');
  END IF;

  -- Blocking needs crew rights; unblocking needs the higher editor right.
  IF p_blocked THEN
    IF NOT public.get_is_cleaning_crew_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
    END IF;
  ELSE
    IF NOT public.get_is_editor_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Editor access required to unblock');
    END IF;
  END IF;

  IF p_blocked THEN
    UPDATE public.occasion_users
    SET is_cleaning_blocked = true,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
          'cleaning_blocked_by', v_caller::text,
          'cleaning_blocked_at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'))
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  ELSE
    UPDATE public.occasion_users
    SET is_cleaning_blocked = false,
        data = COALESCE(data, '{}'::jsonb) - 'cleaning_blocked_by' - 'cleaning_blocked_at'
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  END IF;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('blocked', p_blocked)
  );
END;
$$;


ALTER FUNCTION public.set_cleaning_reporter_blocked_internal_v1(p_occasion bigint, p_user uuid, p_blocked boolean) OWNER TO postgres;

--
-- Name: set_event_attendance_client_sync_v1(bigint, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_event_attendance_client_sync_v1(p_event_id bigint, p_participant_id uuid, p_action text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_occasion bigint; v_event public.events%ROWTYPE;
  v_begin jsonb; v_hash text; v_response jsonb; v_commit jsonb;
  v_private_revision bigint; v_live_revision bigint; v_private_payload jsonb;
  v_live_payload jsonb; v_code integer; v_registration_start timestamptz;
  v_feature jsonb; v_limit integer; v_count bigint; v_group bigint;
  v_is_male boolean; v_changed boolean:=false; v_status text;
  v_needs_occasion_join boolean:=false; v_profile_revision bigint;
  v_profile_payload jsonb; v_private_impacts jsonb; v_items jsonb;
  v_is_publishable boolean; v_companion_owner uuid;
BEGIN
  IF p_action NOT IN ('sign_in','sign_out') OR p_participant_id IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid attendance command';
  END IF;
  SELECT r.occasion INTO v_occasion FROM public.client_mutation_receipts r WHERE r.command_id=p_command_id
    AND r.actor_id=v_actor AND r.command_name='event.attendance.'||p_action;
  IF NOT FOUND THEN
  SELECT e.occasion,NOT o.is_hidden INTO v_occasion,v_is_publishable
  FROM public.events e JOIN public.occasions o ON o.id=e.occasion
  WHERE e.id=p_event_id;
  ELSE
    SELECT NOT is_hidden INTO v_is_publishable FROM public.occasions WHERE id=v_occasion;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL OR NOT (
    v_actor=p_participant_id OR EXISTS (SELECT 1 FROM public.user_companions c
      WHERE c.occasion=v_occasion AND c."user"=v_actor AND c.companion=p_participant_id AND COALESCE((public.get_companion_feature_policy_v1(v_occasion)->>'is_enabled')::boolean,false))
    OR public.can_write_schedule(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='participant attendance permission required';
  END IF;
  SELECT c."user" INTO v_companion_owner FROM public.user_companions c
    JOIN public.occasion_users ou ON ou."user"=c."user" AND ou.occasion=v_occasion
    WHERE c.occasion=v_occasion AND c.companion=p_participant_id ORDER BY c."user" LIMIT 1;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('eventId',p_event_id,
    'participantId',p_participant_id,'action',p_action)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.attendance.'||p_action,
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  PERFORM public.notification_center_initialized_internal((SELECT organization FROM public.occasions WHERE id=v_occasion));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'attendance-user:'||p_participant_id::text||':'||v_occasion::text,0));
  FOR v_group IN SELECT ee."group" FROM public.exclusive_events ee
      WHERE ee.event=p_event_id ORDER BY ee."group" LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'attendance-group:'||v_group::text,0));
  END LOOP;
  SELECT * INTO STRICT v_event FROM public.events e WHERE e.id=p_event_id
    AND e.occasion=v_occasion FOR UPDATE;

  PERFORM public.notification_center_event_capacity_internal(p_event_id,v_actor);
  IF p_action='sign_out' THEN
    IF NOT EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=404;
    ELSIF clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=201;
    ELSE
      DELETE FROM public.event_users WHERE event=p_event_id AND "user"=p_participant_id;
      v_changed:=true; v_code:=200;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
      IF v_actor=p_participant_id AND EXISTS (SELECT 1 FROM public.occasions o
        WHERE o.id=v_occasion AND o.is_open) THEN
        v_needs_occasion_join:=true;
      END IF;
      IF NOT v_needs_occasion_join THEN
        v_status:='rejected'; v_code:=403;
      END IF;
    END IF;
    IF v_code IS NULL AND EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=103;
    END IF;
    IF v_code IS NULL AND clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=100;
    END IF;

    IF v_code IS NULL AND COALESCE((v_event.data->>'is_counseling_slot')::boolean,false) THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='counseling' LIMIT 1;
      IF v_feature IS NULL OR COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
        v_status:='rejected'; v_code:=108;
      ELSE
        v_registration_start:=(v_feature->>'registration_start_time')::timestamptz;
        IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
          v_status:='rejected'; v_code:=104;
        END IF;
        v_limit:=COALESCE((v_feature->>'max_active_bookings')::integer,1);
        IF v_code IS NULL AND v_limit>0 THEN
          SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.events e ON e.id=eu.event
          WHERE eu."user"=p_participant_id AND e.occasion=v_occasion
            AND COALESCE((e.data->>'is_counseling_slot')::boolean,false)
            AND e.end_time>clock_timestamp();
          IF v_count>=v_limit THEN v_status:='rejected'; v_code:=109; END IF;
        END IF;
      END IF;
    ELSIF v_code IS NULL THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='workshops' LIMIT 1;
      IF v_feature IS NOT NULL THEN
        IF COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
          v_status:='rejected'; v_code:=108;
        ELSE
          v_registration_start:=(v_feature->>'start_time')::timestamptz;
          IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
            v_status:='rejected'; v_code:=104;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.exclusive_events target
      JOIN public.exclusive_events occupied ON occupied."group"=target."group"
      JOIN public.event_users eu ON eu.event=occupied.event
      WHERE target.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='rejected'; v_code:=102;
    END IF;
    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.event_users eu JOIN public.events e ON e.id=eu.event
      WHERE eu."user"=p_participant_id AND e.id<>p_event_id
        AND e.start_time<v_event.end_time AND e.end_time>v_event.start_time) THEN
      v_status:='rejected'; v_code:=107;
    END IF;
    IF v_code IS NULL AND COALESCE(v_event.max_participants,0)>0 THEN
      SELECT count(*) INTO v_count FROM public.event_users eu WHERE eu.event=p_event_id;
      IF v_event.split_for_men_women THEN
        SELECT COALESCE(u.sex='male',false) INTO v_is_male
          FROM public.user_info u WHERE u.id=p_participant_id;
        SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.user_info u ON u.id=eu."user" WHERE eu.event=p_event_id
            AND (u.sex='male')=v_is_male;
        IF v_count>=v_event.max_participants/2 THEN
          v_status:='rejected'; v_code:=CASE WHEN v_is_male THEN 105 ELSE 106 END;
        END IF;
      ELSIF v_count>=v_event.max_participants THEN
        v_status:='rejected'; v_code:=101;
      END IF;
    END IF;
    IF v_code IS NULL THEN
      IF v_needs_occasion_join THEN
        PERFORM public.add_user_to_occasion_internal_v1(v_occasion,p_participant_id);
        IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
          WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
          RAISE EXCEPTION 'occasion membership handler did not create membership';
        END IF;
      END IF;
      INSERT INTO public.event_users(event,"user") VALUES(p_event_id,p_participant_id);
      v_changed:=true; v_code:=200;
    END IF;
  END IF;

  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status',v_status,'code',v_code,
      'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
        'isSignedIn',EXISTS(SELECT 1 FROM public.event_users eu
          WHERE eu.event=p_event_id AND eu."user"=p_participant_id),
        'eventsRegistrationStart',v_registration_start),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  PERFORM public.notification_center_event_capacity_internal(p_event_id,v_actor);
  v_items:=jsonb_build_array(jsonb_build_object(
      'entityType','event_attendance','entityId',p_event_id||':'||p_participant_id::text,
      'operation','update','safeLabel','Event attendance',
      'changedFields',jsonb_build_array('is_signed_in')));
  v_private_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_program','userId',p_participant_id));
  IF v_companion_owner IS NOT NULL THEN
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_companion_owner));
  END IF;
  IF v_needs_occasion_join THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','occasion_membership','entityId',p_participant_id,
      'operation','insert','safeLabel','Occasion membership',
      'changedFields',jsonb_build_array('occasion')));
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',p_participant_id));
  END IF;
  v_commit:=public.record_client_sync_commit_v1(v_occasion,
    'event.attendance.'||p_action,'attendance',v_items,
    CASE WHEN v_is_publishable THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    v_private_impacts,CASE WHEN v_is_publishable THEN jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_event_id))
      ELSE '[]'::jsonb END,'user',NULL);
  SELECT source_revision INTO v_private_revision FROM public.client_sync_private_scopes
    WHERE component='private_program' AND occasion=v_occasion AND user_id=p_participant_id;
  IF v_needs_occasion_join OR v_companion_owner IS NOT NULL THEN
    SELECT source_revision INTO STRICT v_profile_revision
    FROM public.client_sync_private_scopes
    WHERE component='private_profile' AND occasion=v_occasion
      AND user_id=COALESCE(v_companion_owner,p_participant_id);
    v_profile_payload:=public.get_private_profile_payload_v1(
      v_occasion,COALESCE(v_companion_owner,p_participant_id));
  END IF;
  SELECT jsonb_build_object(
    'signedIn',COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]'::jsonb),
    'saved',(SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event),'[]'::jsonb)
      FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
      WHERE es."user"=p_participant_id AND e.occasion=v_occasion))
    INTO v_private_payload FROM public.event_users eu JOIN public.events e ON e.id=eu.event
    WHERE eu."user"=p_participant_id AND e.occasion=v_occasion;
  IF v_is_publishable THEN
    SELECT source_revision INTO v_live_revision FROM public.client_sync_scopes
      WHERE component='live_public' AND scope_type='occasion' AND scope_id=v_occasion;
    INSERT INTO public.event_public_state
      (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
    SELECT v_occasion,v_event.id,count(DISTINCT eu."user"),count(DISTINCT es."user"),
      CASE WHEN v_event.max_participants IS NULL THEN NULL
        ELSE GREATEST(v_event.max_participants-count(DISTINCT eu."user"),0) END,
      v_live_revision,clock_timestamp()
    FROM (SELECT 1) seed LEFT JOIN public.event_users eu ON eu.event=v_event.id
    LEFT JOIN public.event_users_saved es ON es.event=v_event.id
    ON CONFLICT (occasion,event) DO UPDATE SET
      participant_count=EXCLUDED.participant_count,saved_count=EXCLUDED.saved_count,
      remaining_capacity=EXCLUDED.remaining_capacity,revision=EXCLUDED.revision,
      projected_at=EXCLUDED.projected_at;
    SELECT jsonb_build_object(
      'events',COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,
        'participantCount',s.participant_count,'savedCount',s.saved_count,
        'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]'::jsonb),
      'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',c.place,
        'status',c.status,'openReportCount',c.open_report_count) ORDER BY c.place),'[]'::jsonb)
        FROM public.cleaning_public_state c WHERE c.occasion=v_occasion))
      INTO v_live_payload FROM public.event_public_state s JOIN public.events e ON e.id=s.event
      WHERE s.occasion=v_occasion AND NOT e.is_hidden;
  END IF;
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
      'isSignedIn',p_action='sign_in'),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',
      CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
        'component','live_public','revision',v_live_revision,
        'payload',v_live_payload)) ELSE '[]'::jsonb END ||
      CASE WHEN v_actor=p_participant_id THEN jsonb_build_array(jsonb_build_object(
        'component','private_program','revision',v_private_revision,
        'payload',v_private_payload)) ELSE '[]'::jsonb END ||
        CASE WHEN v_needs_occasion_join OR v_companion_owner=v_actor
          THEN jsonb_build_array(jsonb_build_object(
          'component','private_profile','revision',v_profile_revision,
          'payload',v_profile_payload)) ELSE '[]'::jsonb END));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $$;


ALTER FUNCTION public.set_event_attendance_client_sync_v1(p_event_id bigint, p_participant_id uuid, p_action text, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_event_speakers(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_event_speakers(p_event bigint, p_speakers bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE oc bigint; ver bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.events WHERE id=p_event;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF public.can_write_speakers(oc) IS NOT TRUE THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.events WHERE id=p_event FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_event::text;
 result:=public.save_event_speakers_client_sync_v1(oc,p_event,extensions.gen_random_uuid(),ver,p_speakers);
 RETURN jsonb_build_object('code',result->'code');
EXCEPTION WHEN invalid_parameter_value THEN RETURN jsonb_build_object('code',400);
END $$;


ALTER FUNCTION public.set_event_speakers(p_event bigint, p_speakers bigint[]) OWNER TO postgres;

--
-- Name: set_notification_center_muted(bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_notification_center_muted(p_organization bigint, p_occasion bigint, p_muted boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.notification_center_check_context(p_organization,p_occasion);
 IF p_occasion IS NULL OR p_muted IS NULL THEN RAISE EXCEPTION 'notification_invalid_preference'; END IF;
 INSERT INTO public.notification_center_preferences VALUES(p_organization,auth.uid(),p_occasion,p_muted)
 ON CONFLICT(organization,recipient,occasion) DO UPDATE SET muted=excluded.muted;
END $$;


ALTER FUNCTION public.set_notification_center_muted(p_organization bigint, p_occasion bigint, p_muted boolean) OWNER TO postgres;

--
-- Name: set_notification_center_prepared_paused(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_notification_center_prepared_paused(p_organization bigint, p_paused boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 PERFORM public.notification_center_require_service();
 UPDATE public.notification_center_organizations SET prepared_paused=coalesce(p_paused,true) WHERE organization=p_organization;
 IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='notification_organization_required'; END IF;
END $$;


ALTER FUNCTION public.set_notification_center_prepared_paused(p_organization bigint, p_paused boolean) OWNER TO postgres;

--
-- Name: set_payment_deadline(bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_payment_deadline(p_payment_info_id bigint, p_new_deadline timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE o record;
BEGIN
  PERFORM public.check_bank_account_writable((SELECT bank_account FROM eshop.payment_info WHERE id=p_payment_info_id));
 PERFORM public.check_payment_info_is_mutable(p_payment_info_id);
 IF p_new_deadline IS NOT NULL AND EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=p_payment_info_id AND payment_method='cash') THEN RAISE EXCEPTION 'CASH_DEADLINE_FORBIDDEN'; END IF;
 UPDATE eshop.payment_info SET deadline=p_new_deadline,
 deposit_deadline=CASE WHEN p_new_deadline IS NULL THEN NULL ELSE deposit_deadline END,
 data=coalesce(data,'{}')||jsonb_build_object('current_version_reminded',false,'payment_policy',coalesce(data->'payment_policy','{}')||jsonb_build_object('mode',CASE WHEN p_new_deadline IS NULL THEN 'none' ELSE 'custom' END)),
 email_reminder_version=email_reminder_version+1 WHERE id=p_payment_info_id;
 FOR o IN SELECT DISTINCT occ.id FROM eshop.orders ord JOIN public.occasions occ ON occ.id=ord.occasion WHERE ord.payment_info=p_payment_info_id LOOP
  PERFORM public.queue_payment_reminders_internal(o.id,p_payment_info_id);
 END LOOP;
END $$;


ALTER FUNCTION public.set_payment_deadline(p_payment_info_id bigint, p_new_deadline timestamp with time zone) OWNER TO postgres;

--
-- Name: set_saved_program(bigint, bigint[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_saved_program(p_occasion bigint, p_event_ids bigint[], p_mode text) RETURNS bigint[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r jsonb;
BEGIN
 r:=public.set_saved_program_client_sync_v1(p_occasion,p_event_ids,p_mode,extensions.gen_random_uuid());
 IF r->>'code'<>'200' THEN RAISE EXCEPTION 'saved program rejected'; END IF;
 RETURN ARRAY(SELECT value::bigint FROM jsonb_array_elements_text(r#>'{data,saved}'));
END $$;


ALTER FUNCTION public.set_saved_program(p_occasion bigint, p_event_ids bigint[], p_mode text) OWNER TO postgres;

--
-- Name: set_saved_program_client_sync_v1(bigint, bigint[], text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_saved_program_client_sync_v1(p_occasion bigint, p_event_ids bigint[], p_mode text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_response JSONB;
  v_revision BIGINT;
  v_payload JSONB;
BEGIN
  v_response := public.set_saved_program_client_sync_v1_transactional(
    p_occasion, p_event_ids, p_mode, p_command_id
  );

  IF jsonb_array_length(v_response #> '{sync,replacements}') = 0 THEN
    SELECT source_revision INTO v_revision
    FROM public.client_sync_private_scopes
    WHERE component = 'private_program'
      AND occasion = p_occasion
      AND user_id = v_actor;

    IF v_revision IS NOT NULL THEN
      SELECT jsonb_build_object(
        'signedIn', (
          SELECT COALESCE(jsonb_agg(eu.event ORDER BY eu.event), '[]'::jsonb)
          FROM public.event_users eu
          JOIN public.events e ON e.id = eu.event
          WHERE eu."user" = v_actor AND e.occasion = p_occasion
        ),
        'saved', (
          SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event), '[]'::jsonb)
          FROM public.event_users_saved es
          JOIN public.events e ON e.id = es.event
          WHERE es."user" = v_actor AND e.occasion = p_occasion
        )
      ) INTO v_payload;

      v_response := jsonb_set(
        v_response,
        '{sync,replacements}',
        jsonb_build_array(jsonb_build_object(
          'component', 'private_program',
          'revision', v_revision,
          'payload', v_payload
        ))
      );
    END IF;
  END IF;

  RETURN v_response;
END;
$$;


ALTER FUNCTION public.set_saved_program_client_sync_v1(p_occasion bigint, p_event_ids bigint[], p_mode text, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_saved_program_client_sync_v1_transactional(bigint, bigint[], text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_saved_program_client_sync_v1_transactional(p_occasion bigint, p_event_ids bigint[], p_mode text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_ids bigint[]; v_before bigint[]; v_after bigint[];
  v_changed_ids bigint[]; v_begin jsonb; v_hash text; v_commit jsonb;
  v_private_revision bigint; v_live_revision bigint; v_private_payload jsonb;
  v_live_payload jsonb; v_response jsonb;
  v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR p_mode NOT IN ('join','remove','replace')
    OR cardinality(COALESCE(p_event_ids,'{}'))>5000
    OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid saved-program command';
  END IF;
  SELECT NOT o.is_hidden INTO STRICT v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  SELECT COALESCE(array_agg(DISTINCT input.event_id ORDER BY input.event_id),'{}')
    INTO v_ids
    FROM unnest(COALESCE(p_event_ids,'{}')) AS input(event_id);
  IF EXISTS (
    SELECT 1
    FROM unnest(v_ids) AS input(event_id)
    LEFT JOIN public.events e
      ON e.id=input.event_id AND e.occasion=p_occasion
    WHERE e.id IS NULL
  ) THEN
    RAISE invalid_parameter_value USING MESSAGE='saved program contains cross-scope events';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'eventIds',to_jsonb(v_ids),'mode',p_mode)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.saved.'||p_mode,
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'saved-program:'||v_actor::text||':'||p_occasion::text,0));
  SELECT COALESCE(array_agg(es.event ORDER BY es.event),'{}') INTO v_before
    FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
    WHERE es."user"=v_actor AND e.occasion=p_occasion;
  IF p_mode='replace' THEN
    DELETE FROM public.event_users_saved es USING public.events e
      WHERE es.event=e.id AND es."user"=v_actor AND e.occasion=p_occasion
        AND NOT es.event=ANY(v_ids);
    INSERT INTO public.event_users_saved(event,"user")
      SELECT input.event_id,v_actor
      FROM unnest(v_ids) AS input(event_id)
      ON CONFLICT DO NOTHING;
  ELSIF p_mode='join' THEN
    INSERT INTO public.event_users_saved(event,"user")
      SELECT input.event_id,v_actor
      FROM unnest(v_ids) AS input(event_id)
      ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.event_users_saved es
      WHERE es."user"=v_actor AND es.event=ANY(v_ids);
  END IF;
  SELECT COALESCE(array_agg(es.event ORDER BY es.event),'{}') INTO v_after
    FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
    WHERE es."user"=v_actor AND e.occasion=p_occasion;
  IF v_before=v_after THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('saved',to_jsonb(v_after)),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;
  SELECT array_agg(DISTINCT changed.event_id ORDER BY changed.event_id)
    INTO v_changed_ids
    FROM (
      (SELECT unnest(v_before) event_id EXCEPT SELECT unnest(v_after))
      UNION
      (SELECT unnest(v_after) event_id EXCEPT SELECT unnest(v_before))
    ) changed;
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'program.saved.'||p_mode,
    'saved_program',jsonb_build_array(jsonb_build_object('entityType','saved_program',
      'entityId',v_actor,'operation','update','safeLabel','Saved program',
      'changedFields',jsonb_build_array('event_ids'))),
    CASE WHEN v_is_publishable THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    jsonb_build_array(jsonb_build_object('component','private_program','userId',v_actor)),
    CASE WHEN v_is_publishable THEN (
      SELECT jsonb_agg(jsonb_build_object(
        'component','live_public','entityId',changed.event_id
      ))
      FROM unnest(v_changed_ids) AS changed(event_id)
    ) ELSE '[]'::jsonb END,'user',NULL);
  SELECT source_revision INTO v_private_revision FROM public.client_sync_private_scopes
    WHERE component='private_program' AND occasion=p_occasion AND user_id=v_actor;
  SELECT jsonb_build_object(
    'signedIn',(SELECT COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]'::jsonb)
      FROM public.event_users eu JOIN public.events e ON e.id=eu.event
      WHERE eu."user"=v_actor AND e.occasion=p_occasion),
    'saved',to_jsonb(v_after)) INTO v_private_payload;
  IF v_is_publishable THEN
    SELECT source_revision INTO v_live_revision FROM public.client_sync_scopes
      WHERE component='live_public' AND scope_type='occasion' AND scope_id=p_occasion;
    INSERT INTO public.event_public_state
      (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
    SELECT e.occasion,e.id,count(DISTINCT eu."user"),count(DISTINCT es."user"),
      CASE WHEN e.max_participants IS NULL THEN NULL
        ELSE GREATEST(e.max_participants-count(DISTINCT eu."user"),0) END,
      v_live_revision,clock_timestamp()
    FROM public.events e LEFT JOIN public.event_users eu ON eu.event=e.id
    LEFT JOIN public.event_users_saved es ON es.event=e.id
    WHERE e.occasion=p_occasion AND e.id=ANY(v_changed_ids)
    GROUP BY e.occasion,e.id,e.max_participants
    ON CONFLICT (occasion,event) DO UPDATE SET participant_count=EXCLUDED.participant_count,
      saved_count=EXCLUDED.saved_count,remaining_capacity=EXCLUDED.remaining_capacity,
      revision=EXCLUDED.revision,projected_at=EXCLUDED.projected_at;
    SELECT jsonb_build_object(
      'events',COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,
        'participantCount',s.participant_count,'savedCount',s.saved_count,
        'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]'::jsonb),
      'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',c.place,
        'status',c.status,'openReportCount',c.open_report_count) ORDER BY c.place),'[]'::jsonb)
        FROM public.cleaning_public_state c WHERE c.occasion=p_occasion))
      INTO v_live_payload FROM public.event_public_state s JOIN public.events e ON e.id=s.event
      WHERE s.occasion=p_occasion AND NOT e.is_hidden;
  END IF;
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('saved',to_jsonb(v_after)),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',
      CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
        'component','live_public','revision',v_live_revision,
        'payload',v_live_payload)) ELSE '[]'::jsonb END ||
      jsonb_build_array(jsonb_build_object('component','private_program',
        'revision',v_private_revision,'payload',v_private_payload))));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $$;


ALTER FUNCTION public.set_saved_program_client_sync_v1_transactional(p_occasion bigint, p_event_ids bigint[], p_mode text, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_stripe_unit_feature(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_stripe_unit_feature(p_unit bigint, p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE org bigint;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit;
 IF org IS NULL OR auth.uid() IS NULL OR NOT public.can_manage_organization_settings(org) THEN
  RAISE insufficient_privilege USING MESSAGE='STRIPE_ORGANIZATION_ADMIN_REQUIRED';
 END IF;
 IF p_enabled IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='Stripe feature setting must be boolean'; END IF;
 IF public.is_demo_unit(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='DEMO_UNIT_READ_ONLY'; END IF;
 -- Serialize with checkout and connection setup. Never alter retained money facts.
 PERFORM 1 FROM public.units WHERE id=p_unit FOR UPDATE;
 INSERT INTO eshop.stripe_unit_features(unit_id,enabled,updated_by)
 VALUES(p_unit,p_enabled,auth.uid()) ON CONFLICT(unit_id) DO UPDATE
 SET enabled=excluded.enabled,updated_by=excluded.updated_by,updated_at=clock_timestamp();
 RETURN p_enabled;
END $$;


ALTER FUNCTION public.set_stripe_unit_feature(p_unit bigint, p_enabled boolean) OWNER TO postgres;

--
-- Name: set_stripe_unit_paused(bigint, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_stripe_unit_paused(p_unit bigint, p_livemode boolean, p_paused boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE conn uuid; prior_pause boolean; org bigint;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 IF p_paused IS NULL THEN RAISE EXCEPTION 'STRIPE_PAUSE_INVALID'; END IF;
 SELECT id,paused,organization_id INTO conn,prior_pause,org FROM eshop.stripe_connections WHERE unit_id=p_unit AND livemode=p_livemode AND state IN ('connected','restricted') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'STRIPE_CONNECTION_UNAVAILABLE'; END IF;
 IF NOT p_paused AND EXISTS(SELECT 1 FROM eshop.stripe_disconnect_intents WHERE connection_id=conn AND state<>'completed') THEN RAISE EXCEPTION 'STRIPE_DISCONNECT_PENDING'; END IF;
 IF prior_pause=p_paused THEN RETURN; END IF;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('stripe.connect',p_unit,org),jsonb_build_object('actor',auth.uid(),'unit',p_unit,'organization',org));
 UPDATE eshop.stripe_connections SET paused=p_paused WHERE id=conn;
 INSERT INTO eshop.stripe_connection_audit(connection_id,actor,action) VALUES(conn,auth.uid(),CASE WHEN p_paused THEN 'paused' ELSE 'resumed' END);
END $$;


ALTER FUNCTION public.set_stripe_unit_paused(p_unit bigint, p_livemode boolean, p_paused boolean) OWNER TO postgres;

--
-- Name: set_stripe_unit_paused_client_sync_v1(bigint, boolean, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_stripe_unit_paused_client_sync_v1(p_unit bigint, p_livemode boolean, p_paused boolean, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE begun jsonb; hash text;
BEGIN
 PERFORM public.check_stripe_unit_manager_internal(p_unit,auth.uid());
 hash:=encode(extensions.digest(jsonb_build_object('unit',p_unit,'live',p_livemode,'paused',p_paused)::text,'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.cards.pause',p_unit,auth.uid(),hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 PERFORM public.set_stripe_unit_paused(p_unit,p_livemode,p_paused);
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.cards.pause','unit',p_unit,'update',jsonb_build_object('state',public.get_stripe_unit_connection(p_unit,p_livemode)));
END $$;


ALTER FUNCTION public.set_stripe_unit_paused_client_sync_v1(p_unit bigint, p_livemode boolean, p_paused boolean, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_ticket_seat_assignments(uuid, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_ticket_seat_assignments(p_transition uuid, p_mappings jsonb, p_fingerprint text, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tr public.form_seating_transitions; started jsonb; preview jsonb; v_orders bigint[]; v_items bigint[]; v_spots bigint[]; v_products bigint[]; v_mapping jsonb; dest eshop.spots; required integer; occupied integer; spare bigint; oid bigint; touched bigint[];
BEGIN
 SELECT * INTO tr FROM public.form_seating_transitions WHERE id=p_transition;
 IF tr.id IS NULL OR NOT public.can_assign_existing_admissions(tr.occasion) THEN RAISE insufficient_privilege USING MESSAGE='order reader and writer required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid() AND command_name='seating.assignment.set') THEN
 tr:=public.seating_assignment_scope_internal(p_transition,p_mappings); END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[tr.occasion]);
 started:=public.begin_client_mutation_v1(p_command_id,'seating.assignment.set',tr.occasion,auth.uid(),encode(extensions.digest(jsonb_build_array(p_transition,p_mappings,p_fingerprint)::text,'sha256'),'hex'));
 IF NOT public.can_assign_existing_admissions(tr.occasion) THEN RAISE insufficient_privilege USING MESSAGE='order reader and writer required'; END IF;
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 tr:=public.seating_assignment_scope_internal(p_transition,p_mappings);
 PERFORM public.admit_order_mutation_v1(tr.occasion,jsonb_array_length(p_mappings));
 SELECT ARRAY(SELECT (m->>'admissionItemId')::bigint FROM jsonb_array_elements(p_mappings)m ORDER BY 1) INTO v_items;
 SELECT array_agg(DISTINCT "order" ORDER BY "order"),array_agg(DISTINCT product ORDER BY product) INTO v_orders,v_products FROM eshop.order_product_ticket WHERE id=ANY(v_items);
 PERFORM 1 FROM public.forms WHERE id IN(SELECT form FROM eshop.orders WHERE id=ANY(v_orders)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.form_seating_transitions WHERE blueprint=tr.blueprint AND state='organizer_managed' AND form IN(SELECT form FROM eshop.orders WHERE id=ANY(v_orders)) ORDER BY id FOR UPDATE;
 -- Lock union of before/after units and all allocation parents before children.
 SELECT ARRAY(SELECT DISTINCT s.id FROM eshop.spots s WHERE s.order_product_ticket=ANY(v_items)
 OR s.inventory_context IN(SELECT inventory_context FROM eshop.product_inventory_contexts WHERE product=ANY(v_products))
 OR s.id IN(SELECT member FROM jsonb_array_elements(p_mappings)m CROSS JOIN LATERAL unnest(ARRAY[(m->>'expectedSpotId')::bigint,(m->>'targetSpotId')::bigint]) id CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(id)) member) ORDER BY s.id) INTO v_spots;
 PERFORM public.lock_spot_assignment_scope_internal(v_spots,'{}',true,v_products,false,v_orders,v_items);
 tr:=public.seating_assignment_scope_internal(p_transition,p_mappings);
 preview:=public.seating_assignment_preview_internal(p_transition,p_mappings);
 IF jsonb_array_length(preview->'blockers')>0 OR preview->>'fingerprint' IS DISTINCT FROM p_fingerprint THEN
 RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('reason',CASE WHEN jsonb_array_length(preview->'blockers')>0 THEN preview#>>'{blockers,0,reason}' ELSE 'CONTEXT_CHANGED' END,'blockers',preview->'blockers')); END IF;
 -- Remove only explicitly reviewed before associations, preserving physical resources.
 UPDATE eshop.spots SET order_product_ticket=NULL,state=NULL,updated_at=clock_timestamp()
 WHERE id IN(SELECT (m->>'expectedSpotId')::bigint FROM jsonb_array_elements(p_mappings)m);
 FOR v_mapping IN SELECT value FROM jsonb_array_elements(p_mappings) ORDER BY (value->>'admissionItemId')::bigint LOOP
 IF v_mapping->>'targetSpotId' IS NULL THEN CONTINUE; END IF;
 SELECT * INTO STRICT dest FROM eshop.spots WHERE id=(v_mapping->>'targetSpotId')::bigint;
 IF dest.inventory_context IS NOT NULL THEN
 SELECT quantity INTO required FROM eshop.product_inventory_contexts WHERE product=dest.product AND inventory_context=dest.inventory_context;
 SELECT count(*) INTO occupied FROM eshop.spots WHERE order_product_ticket=(v_mapping->>'admissionItemId')::bigint AND inventory_context=dest.inventory_context;
 IF occupied>=required THEN
 SELECT id INTO spare FROM eshop.spots WHERE order_product_ticket=(v_mapping->>'admissionItemId')::bigint AND inventory_context=dest.inventory_context AND blueprint IS NULL ORDER BY id LIMIT 1;
 IF spare IS NULL THEN RAISE EXCEPTION 'INVENTORY_CONFLICT'; END IF;
 UPDATE eshop.spots SET order_product_ticket=NULL,state=NULL,resource=NULL,updated_at=clock_timestamp() WHERE id=spare;
 END IF;
 END IF;
 UPDATE eshop.spots SET order_product_ticket=(v_mapping->>'admissionItemId')::bigint,state='ordered',secret=NULL,secret_expiration_time=NULL,updated_at=clock_timestamp() WHERE id=dest.id;
 END LOOP;
 FOREACH oid IN ARRAY v_orders LOOP PERFORM public.apply_allocations(oid); END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.order_product_ticket i JOIN eshop.product_inventory_contexts pic ON pic.product=i.product WHERE i.id=ANY(v_items) AND
 (SELECT count(*) FROM eshop.spots WHERE order_product_ticket=i.id AND inventory_context=pic.inventory_context)<>pic.quantity) THEN RAISE EXCEPTION 'INVENTORY_CONFLICT'; END IF;
 UPDATE public.form_seating_transitions SET revision=revision+1 WHERE blueprint=tr.blueprint AND state='organizer_managed' AND form IN(SELECT form FROM eshop.orders WHERE id=ANY(v_orders));
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,tr.occasion,'seating.assignment.set',
 jsonb_build_array(jsonb_build_object('entityType','blueprint','entityId',tr.blueprint,'operation','update','safeLabel','Admission placement','changedFields',jsonb_build_array('seating'))),
 ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=tr.occasion),jsonb_build_object('transitionId',tr.id,'mappings',preview->'mappings','context',public.get_seating_transition_context(tr.id)->'data'));
END $$;


ALTER FUNCTION public.set_ticket_seat_assignments(p_transition uuid, p_mappings jsonb, p_fingerprint text, p_command_id uuid) OWNER TO postgres;

--
-- Name: set_unit_app_landing(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_unit_app_landing(p_unit bigint, p_occasion bigint, p_expected_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org bigint;
  v_data jsonb;
  v_current bigint;
BEGIN
  SELECT organization INTO v_org FROM public.units WHERE id = p_unit;
  IF v_org IS NULL OR NOT public.can_manage_unit_app_landing(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE = 'Access denied';
  END IF;
  SELECT data INTO v_data FROM public.organizations WHERE id = v_org FOR UPDATE;
  IF NOT coalesce((v_data->>'IS_APP_SUPPORTED')::boolean, false) THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Application is not enabled';
  END IF;
  v_current := (v_data->>'DEFAULT_OCCASION')::bigint;
  IF v_current IS DISTINCT FROM p_expected_occasion THEN
    RAISE serialization_failure USING MESSAGE = 'App landing changed. Refresh and try again.';
  END IF;
  IF p_occasion IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.occasions WHERE id = p_occasion
      AND unit = p_unit AND organization = v_org AND is_open = true
  ) THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Choose an open occasion in this unit';
  END IF;
  -- The representative occasion is a separate application setting; preserve it.
  UPDATE public.organizations
    SET data = (coalesce(data, '{}'::jsonb) - 'DEFAULT_OCCASION')
      || CASE WHEN p_occasion IS NULL THEN '{}'::jsonb
         ELSE jsonb_build_object('DEFAULT_OCCASION', p_occasion) END
    WHERE id = v_org;
  RETURN public.get_unit_app_landing(p_unit);
END;
$$;


ALTER FUNCTION public.set_unit_app_landing(p_unit bigint, p_occasion bigint, p_expected_occasion bigint) OWNER TO postgres;

--
-- Name: set_user_password_token(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_user_password_token(token uuid, password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  declare
  v_user_id uuid;
  token_created_at timestamptz;
  email text;
  encrypted_pw text;
BEGIN
    IF password IS NULL OR length(password)<8 THEN RETURN json_build_object('code',400); END IF;

    DELETE FROM public.user_reset_token urt
    WHERE urt.token=$1
    RETURNING urt."user",urt.created_at INTO v_user_id,token_created_at;
    IF v_user_id IS NULL OR token_created_at < clock_timestamp()-interval '30 minutes' THEN
        RETURN json_build_object('code', 403);
    END IF;


    encrypted_pw := crypt(password, gen_salt('bf'));

    UPDATE auth.users
    SET encrypted_password = encrypted_pw
    WHERE auth.users.id = v_user_id;
    IF NOT FOUND THEN RETURN json_build_object('code',404); END IF;

    UPDATE auth.refresh_tokens SET revoked=true WHERE auth.refresh_tokens.user_id=v_user_id::text;
    DELETE FROM auth.sessions WHERE auth.sessions.user_id=v_user_id;

    SELECT email_readonly INTO email FROM user_info WHERE user_info.id = v_user_id;
    IF email is NULL THEN
        RETURN json_build_object('code', 404);
    END IF;

    RETURN json_build_object('code', 200, 'email', email);
END;
$_$;


ALTER FUNCTION public.set_user_password_token(token uuid, password text) OWNER TO postgres;

--
-- Name: setup_crons(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.setup_crons(p_project_url text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN
  -- Security Check
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
      RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;

  -- Schedule the apply_planned_changes cron job (runs every minute)
  PERFORM cron.schedule(
    'apply_planned_changes',
    '*/1 * * * *',
    'SELECT apply_planned_changes()'
  );

  -- BankSync owns bank polling. This job recovers durable control intents.
  -- Scoped health observation is configured explicitly with configure_bank_sync_health_monitor.
  PERFORM cron.schedule('festapp_canonical_bank_sync_reconcile','*/5 * * * *',
    format($$SELECT net.http_post(url:='%s/functions/v1/bank-sync-reconcile',
      body:=jsonb_build_object('requestSecret',public.generate_request_secret(3600)),
      timeout_milliseconds:=360000)$$,p_project_url));

  -- The protected worker alternates delivery/repair/backfill with a commit per RPC.
  -- Retire direct, co-timed drains to avoid starving a work class on the lease.
  PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname IN ('festapp_canonical_notification_center_delivery','festapp_canonical_notification_center_prepare');
  PERFORM public.configure_notification_center_worker(p_project_url);
  PERFORM cron.schedule('festapp_canonical_notification_center_wake','1 second','SELECT public.wake_notification_center()');
  PERFORM cron.schedule('festapp_canonical_notification_center_project','*/1 * * * *','SELECT public.maintain_notification_center(100)');
  PERFORM cron.schedule('festapp_canonical_sale_opening_notifications','*/1 * * * *','SELECT public.maintain_sale_opening_notifications(100)');
  PERFORM cron.schedule('festapp_canonical_waitlist_expiry','*/1 * * * *','SELECT public.expire_waitlist_offers(100)');
  PERFORM cron.schedule('festapp_canonical_process_email_queue','*/1 * * * *','SELECT public.recover_email_delivery()');
END;
$_$;


ALTER FUNCTION public.setup_crons(p_project_url text) OWNER TO postgres;

