--
-- Name: setup_triggers(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.setup_triggers(p_project_url text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  relation_name text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;
  IF p_project_url !~ '^https://[^/]+$' THEN
    RAISE EXCEPTION 'Project URL must be an HTTPS origin';
  END IF;

  FOREACH relation_name IN ARRAY ARRAY[
    'events', 'icons', 'information', 'news', 'occasions', 'places',
    'user_info', 'speakers', 'speaker_topics', 'cleaning_reports'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS handle_updated_at ON public.%I', relation_name);
    EXECUTE format(
      'CREATE TRIGGER handle_updated_at BEFORE UPDATE ON public.%I '
      'FOR EACH ROW EXECUTE FUNCTION extensions.moddatetime(''updated_at'')',
      relation_name
    );
  END LOOP;

  -- Notification delivery is an explicit domain-command operation.
  UPDATE public.notification_runtime SET endpoint=p_project_url||'/functions/v1/notify' WHERE singleton;
END
$_$;


ALTER FUNCTION public.setup_triggers(p_project_url text) OWNER TO postgres;

--
-- Name: shift_occasion_schedule_backward(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shift_occasion_schedule_backward(p_occasion_id bigint, p_hours_to_subtract integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_shift_interval INTERVAL;
BEGIN
    -- Ensure the number of hours is positive
    IF p_hours_to_subtract <= 0 THEN
        RAISE EXCEPTION 'Number of hours to subtract must be positive.';
    END IF;

    -- Create an interval from the given hours
    v_shift_interval := p_hours_to_subtract * INTERVAL '1 hour';

    -- 1. Shift the main occasion start and end times
    UPDATE public.occasions
    SET
        start_time = start_time - v_shift_interval,
        end_time = end_time - v_shift_interval,
        updated_at = now()
    WHERE id = p_occasion_id;

    -- 2. Shift all events associated with the occasion
    UPDATE public.events
    SET
        start_time = start_time - v_shift_interval,
        end_time = end_time - v_shift_interval,
        updated_at = now()
    WHERE occasion = p_occasion_id;

    -- 3. Shift all activity assignments for the occasion
    UPDATE public.activity_assignments
    SET
        start_time = start_time - v_shift_interval,
        end_time = end_time - v_shift_interval
    WHERE activity_id IN (SELECT id FROM public.activities WHERE occasion = p_occasion_id);


END;
$$;


ALTER FUNCTION public.shift_occasion_schedule_backward(p_occasion_id bigint, p_hours_to_subtract integer) OWNER TO postgres;

