--
-- Name: stage_bank_sync_operation(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_bank_sync_operation(p_id uuid, p_hash text, p_request jsonb, p_token_cipher jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.require_service_role();
  IF p_request ? 'token' OR p_request->>'operation_id' IS DISTINCT FROM p_id::text THEN
    RAISE EXCEPTION 'BANK_SYNC_REQUEST_INVALID';
  END IF;
  UPDATE eshop.bank_sync_operations SET request=COALESCE(request,p_request||jsonb_build_object('expected_pairing',
      (SELECT c.pairing_code FROM eshop.bank_sync_connections c WHERE c.bank_account_id=bank_sync_operations.bank_account_id))),
      token_cipher=COALESCE(token_cipher,p_token_cipher)
    WHERE id=p_id AND payload_sha256=p_hash AND state IN ('pending','uncertain');
  IF NOT FOUND THEN RAISE EXCEPTION 'BANK_SYNC_OPERATION_NOT_STAGEABLE'; END IF;
END;
$$;


ALTER FUNCTION public.stage_bank_sync_operation(p_id uuid, p_hash text, p_request jsonb, p_token_cipher jsonb) OWNER TO postgres;

--
-- Name: stage_wix_billing_delivery(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_wix_billing_delivery(p_app uuid, p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE ident text:=p_event->>'receiptId'; delivery_kind text:=p_event#>>'{requestBody,event,billingType}';
 digest text:=encode(extensions.digest(p_event::text,'sha256'),'hex'); prior public.wix_billing_deliveries;
BEGIN
 PERFORM public.require_service_role();
 IF jsonb_typeof(p_event#>'{basis,refundSequence}') IS DISTINCT FROM 'string'
  OR coalesce(p_event#>>'{basis,refundSequence}','') !~ '^(0|[1-9][0-9]{0,18})$'
  OR (delivery_kind='CHARGE' AND p_event#>>'{basis,refundSequence}'<>'0')
  OR (delivery_kind='REFUND' AND p_event#>>'{basis,refundSequence}'='0') THEN
  RAISE invalid_parameter_value USING MESSAGE='WIX_REPORT_V2_REQUIRED'; END IF;
 IF ident IS NULL OR delivery_kind IS NULL OR p_event->>'instanceId' IS NULL OR jsonb_typeof(p_event#>'{requestBody,event}') IS DISTINCT FROM 'object'
  OR octet_length(p_event::text)>32768 THEN RAISE invalid_parameter_value USING MESSAGE='INVALID_WIX_DELIVERY'; END IF;
 INSERT INTO public.wix_billing_deliveries(app_id,receipt_id,kind,instance_id,payload,payload_digest)
 VALUES(p_app,ident,delivery_kind,(p_event->>'instanceId')::uuid,p_event,digest) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT prior FROM public.wix_billing_deliveries WHERE app_id=p_app AND receipt_id=ident AND wix_billing_deliveries.kind=delivery_kind FOR UPDATE;
 IF prior.payload_digest<>digest THEN RAISE check_violation USING MESSAGE='WIX_DELIVERY_DIGEST_CONFLICT'; END IF;
 RETURN jsonb_build_object('state',prior.state,'digest',prior.payload_digest);
END $_$;


ALTER FUNCTION public.stage_wix_billing_delivery(p_app uuid, p_event jsonb) OWNER TO postgres;

--
-- Name: start_occasion_lifecycle(bigint, bigint, bigint, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_occasion_lifecycle(p_unit bigint, p_organization bigint, p_occasion bigint, p_action text, p_command_id uuid, p_target_unit bigint DEFAULT NULL::bigint, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE source_unit bigint; organization_id bigint; target_unit bigint; hash text; job public.occasion_media_jobs; result jsonb; target bigint; manifest jsonb:='[]'; source_url text; field text; target_url text; row_data public.occasions;
BEGIN
 SELECT unit,organization INTO source_unit,organization_id FROM public.occasions WHERE id=p_occasion;
 IF source_unit IS NULL THEN SELECT j.source_unit,j.organization INTO source_unit,organization_id FROM public.occasion_media_jobs j WHERE j.command_id=p_command_id AND j.actor_id=auth.uid(); END IF;
 IF source_unit IS NULL OR (p_unit IS NOT NULL AND p_unit<>source_unit) OR (p_organization IS NOT NULL AND p_organization<>organization_id) THEN RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
 target_unit:=coalesce(p_target_unit,source_unit);
 PERFORM public.lock_people_scope_internal_v1(NULL,organization_id,source_unit);
 IF p_action NOT IN ('copy','delete') OR p_action IS NULL OR p_command_id IS NULL OR p_locale NOT IN ('en','cs','sk','de','pl','uk') THEN RAISE invalid_parameter_value USING MESSAGE='invalid lifecycle command'; END IF;
 hash:=encode(extensions.digest(jsonb_build_object('unit',source_unit,'organization',organization_id,'occasion',p_occasion,'action',p_action,'targetUnit',target_unit,'locale',p_locale)::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_command_id::text,5319));
 SELECT * INTO job FROM public.occasion_media_jobs WHERE command_id=p_command_id FOR UPDATE;
 IF FOUND THEN
  IF job.request_sha256<>hash OR job.actor_id IS DISTINCT FROM auth.uid() THEN RAISE invalid_parameter_value USING MESSAGE='lifecycle command identity conflict'; END IF;
  PERFORM public.get_occasion_media_job(p_command_id);
  SELECT response INTO result FROM public.client_mutation_receipts WHERE command_id=p_command_id;
  RETURN jsonb_set(result,'{data}',coalesce(result->'data','{}')||jsonb_build_object('mediaJob',public.get_occasion_media_job(p_command_id)));
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion AND unit=source_unit AND organization=organization_id) THEN RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
 IF p_action='copy' THEN
  IF NOT public.can_copy_occasion_source(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='copy source unavailable'; END IF;
  -- Fence organizer moves through the same stored-scope helper as other tools.
  -- Source forms precede its occasion row, matching the canonical save order.
  PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR SHARE;
  PERFORM public.lock_people_scope_internal_v1(p_occasion,organization_id,source_unit);
 END IF;
 IF p_action='delete' THEN
  IF target_unit<>source_unit THEN RAISE invalid_parameter_value USING MESSAGE='delete has no target unit'; END IF;
  result:=public.delete_occasion_client_sync_v1(p_occasion,p_command_id);target:=p_occasion;
  -- The canonical deleter owns its forms/products/occasion lock order. Its
  -- accepted receipt carries the actually locked unit even after row removal.
  -- A move during admission rolls back the entire delete rather than widening consent.
  IF NOT EXISTS(SELECT 1 FROM public.client_mutation_receipts r JOIN public.units u ON u.id=r.unit
    WHERE r.command_id=p_command_id AND r.actor_id=auth.uid() AND r.command_name='occasion.delete'
     AND r.unit=source_unit AND u.organization=organization_id) THEN RAISE insufficient_privilege USING MESSAGE='deleted occasion scope changed'; END IF;
 ELSE
  PERFORM public.lock_people_scope_internal_v1(NULL,organization_id,target_unit);
  result:=public.duplicate_occasion_client_sync_v1(p_occasion,p_command_id,target_unit,p_locale);
  target:=(result#>>'{data,occasionId}')::bigint;
  SELECT * INTO row_data FROM public.occasions WHERE id=target;
  FOREACH field IN ARRAY ARRAY['image','background'] LOOP
   source_url:=CASE WHEN field='image' THEN row_data.data->>'image' ELSE (SELECT f->>'background' FROM jsonb_array_elements(row_data.features) f WHERE f->>'code'='ticket') END;
   IF nullif(source_url,'') IS NULL OR source_url LIKE 'https://img.festapp.net/ticket-presets/v1/%'
    OR EXISTS(SELECT 1 FROM public.images WHERE link=source_url AND occasion=target) THEN CONTINUE; END IF;
   -- Only immutable canonical public objects. Never fetch arbitrary URLs from DB text.
   IF source_url !~ '^https://(a[.])?img[.]festapp[.]net/(images|assets)/[A-Za-z0-9._/-]+$' OR source_url LIKE '%..%' THEN RAISE invalid_parameter_value USING MESSAGE='copy source is not a canonical image'; END IF;
   target_url:='https://img.festapp.net/images/lifecycle/'||p_command_id||'/'||encode(extensions.digest(source_url,'sha256'),'hex');
   manifest:=manifest||jsonb_build_array(jsonb_build_object('field',field,'source',source_url,'target',target_url,'ready',false));
  END LOOP;
 END IF;
 IF result->>'code'<>'200' OR target IS NULL THEN RAISE EXCEPTION 'LIFECYCLE_COMMAND_REJECTED'; END IF;
 INSERT INTO public.occasion_media_jobs(command_id,actor_id,organization,source_unit,target_unit,source_occasion,target_occasion,action,request_sha256,state,media,completed_at)
 VALUES(p_command_id,auth.uid(),organization_id,source_unit,target_unit,p_occasion,target,p_action,hash,CASE WHEN manifest='[]' THEN 'complete' ELSE 'pending' END,manifest,CASE WHEN manifest='[]' THEN now() END);
 RETURN jsonb_set(result,'{data}',coalesce(result->'data','{}')||jsonb_build_object('mediaJob',public.get_occasion_media_job(p_command_id)));
END $_$;


ALTER FUNCTION public.start_occasion_lifecycle(p_unit bigint, p_organization bigint, p_occasion bigint, p_action text, p_command_id uuid, p_target_unit bigint, p_locale text) OWNER TO postgres;

--
-- Name: start_seating_configuration(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_seating_configuration(p_form bigint, p_blueprint bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE occ bigint; started jsonb; tid uuid;
BEGIN
 SELECT occasion INTO occ FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=auth.uid() AND command_name='seating.configuration.start';
 IF NOT FOUND THEN SELECT occasion INTO occ FROM public.forms WHERE id=p_form; END IF;
 IF occ IS NULL OR NOT public.can_author_forms(occ) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 started:=public.begin_client_mutation_v1(p_command_id,'seating.configuration.start',occ,auth.uid(),encode(extensions.digest(jsonb_build_array(p_form,p_blueprint)::text,'sha256'),'hex'));
 IF NOT public.can_author_forms(occ) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 tid:=public.start_seating_configuration_internal(p_form,p_blueprint);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,occ,'seating.configuration.start',
 jsonb_build_array(jsonb_build_object('entityType','form','entityId',p_form,'operation','update','safeLabel','Seating configuration','changedFields',jsonb_build_array('seating'))),
 ARRAY(SELECT "user" FROM public.occasion_users WHERE occasion=occ),jsonb_build_object('transitionId',tid,'context',jsonb_set(public.get_seating_transition_context(tid)->'data','{items}','[]'::jsonb)));
END $$;


ALTER FUNCTION public.start_seating_configuration(p_form bigint, p_blueprint bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: start_seating_configuration_internal(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_seating_configuration_internal(p_form bigint, p_blueprint bigint) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE f public.forms; b eshop.blueprints; tid uuid;
BEGIN
 SELECT * INTO f FROM public.forms WHERE id=p_form;
 IF f.id IS NULL OR NOT coalesce(public.can_author_forms(f.occasion) OR public.can_edit_occasion(f.occasion,NULL),false) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[f.occasion]);
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form FOR UPDATE;
 SELECT * INTO b FROM eshop.blueprints WHERE id=p_blueprint;
 IF b.id IS NULL OR b.occasion<>f.occasion OR b.organization IS DISTINCT FROM (SELECT organization FROM public.occasions WHERE id=f.occasion) THEN
 RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 IF NOT coalesce(public.can_author_forms(f.occasion) OR public.can_edit_occasion(f.occasion,NULL),false) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=f.occasion AND jsonb_path_exists(features,'$[*] ? (@.code == "blueprint" && @.is_enabled == true)')) THEN
 RAISE EXCEPTION 'MODE_CHANGED'; END IF;
 IF b.layout->>'schemaVersion' IS DISTINCT FROM '2' THEN RAISE EXCEPTION 'BLUEPRINT_LAYOUT_MIGRATION_REQUIRED'; END IF;
 SELECT id INTO tid FROM public.form_seating_transitions WHERE form=f.id AND state='organizer_managed';
 IF tid IS NOT NULL THEN
 IF NOT EXISTS(SELECT 1 FROM public.form_seating_transitions WHERE id=tid AND blueprint=b.id) THEN RAISE EXCEPTION 'ASSIGNMENTS_EXIST'; END IF;
 RETURN tid; END IF;
 IF EXISTS(SELECT 1 FROM public.forms WHERE blueprint=b.id) THEN RAISE EXCEPTION 'TARGET_ALREADY_PUBLIC'; END IF;
 IF f.blueprint IS NOT NULL THEN RAISE EXCEPTION 'MODE_CHANGED'; END IF;
 INSERT INTO public.form_seating_transitions(occasion,form,blueprint,started_by) VALUES(f.occasion,f.id,b.id,auth.uid()) RETURNING id INTO tid;
 RETURN tid;
END $_$;


ALTER FUNCTION public.start_seating_configuration_internal(p_form bigint, p_blueprint bigint) OWNER TO postgres;

--
-- Name: store_sign_in_code_v1(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.store_sign_in_code_v1(p_user uuid, p_code text, p_expires timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 IF p_code IS NULL OR p_code !~ '^[0-9]{6}$' OR p_expires IS NULL OR p_expires<=now() THEN RAISE EXCEPTION 'invalid_sign_in_code'; END IF;
 INSERT INTO public.sign_in_codes(user_id,code_hash,expires_at)
 VALUES(p_user,extensions.crypt(p_code,extensions.gen_salt('bf')),least(p_expires,now()+interval '10 minutes'))
 ON CONFLICT(user_id) DO UPDATE SET code_hash=excluded.code_hash,version=gen_random_uuid(),expires_at=excluded.expires_at,attempts=0,consumed_at=NULL;
END $_$;


ALTER FUNCTION public.store_sign_in_code_v1(p_user uuid, p_code text, p_expires timestamp with time zone) OWNER TO postgres;

--
-- Name: storno_order_client_sync_v1(bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storno_order_client_sync_v1(p_order bigint, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[]; v_unchanged boolean:=false;
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=p_order)]);
  SELECT o.occasion INTO v_occasion FROM eshop.orders o WHERE o.id=p_order;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  -- A committed cancellation needs only a receipt, without another admission.
  IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  BEGIN
    -- Preserve admission -> domain locks, also relative to deletion. If another
    -- cancellation wins while waiting, roll back this attempt's admission.
    PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
    IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
      RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
    SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
      FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
    PERFORM public.update_order_and_tickets_to_storno_ws_internal_v1(p_order);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.cancel',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',p_order,
      'operation','update','safeLabel','Order cancellation',
      'changedFields',jsonb_build_array('state','tickets','membership','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order));
END; $$;


ALTER FUNCTION public.storno_order_client_sync_v1(p_order bigint, p_command_id uuid) OWNER TO postgres;

--
-- Name: storno_tickets_bulk(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storno_tickets_bulk(p_ticket_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM public.storno_tickets_client_sync_v1(
    p_ticket_ids,extensions.gen_random_uuid());
END; $$;


ALTER FUNCTION public.storno_tickets_bulk(p_ticket_ids bigint[]) OWNER TO postgres;

--
-- Name: storno_tickets_bulk_internal_v1(bigint[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storno_tickets_bulk_internal_v1(p_ticket_ids bigint[], p_send_email boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_order_id BIGINT;
    v_occasion_id BIGINT;
    v_tickets_in_order BIGINT[];
    v_tickets_to_cancel_in_order BIGINT[];
    v_remaining_count INT;
    v_ticket_id_to_remove BIGINT;
    v_original_data JSONB;
    v_updated_tickets_json JSONB;
    v_ticket_elem JSONB;
    v_product_elem JSONB;
    v_removed_price NUMERIC(10, 2);
    v_current_price NUMERIC(10, 2);
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(p_ticket_ids)));
    PERFORM public.check_blueprint_selection_units_internal(ARRAY(SELECT s.id FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE opt.ticket=ANY(p_ticket_ids)));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_ticket_ids)));
    -- 1. Identify all unique orders involved in this batch AND their occasion
    -- We need the occasion ID to perform the security check
    FOR v_order_id, v_occasion_id IN
        SELECT DISTINCT o.id, o.occasion
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE t.id = ANY(p_ticket_ids)
        ORDER BY o.id
    LOOP
        -- 2. SECURITY CHECK
        -- Verify that the current user has editor permissions on the occasion associated with the order.
        IF NOT public.can_write_orders(v_occasion_id) THEN
            RAISE EXCEPTION 'Permission denied to storno tickets for order % on occasion %', v_order_id, v_occasion_id;
        END IF;

        -- Repeated selected tickets in an otherwise active order are a no-op.
        IF NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
          WHERE opt."order"=v_order_id AND t.id=ANY(p_ticket_ids) AND t.state IS DISTINCT FROM 'storno') THEN
          CONTINUE;
        END IF;
        PERFORM public.check_order_is_mutable(v_order_id);
        IF EXISTS(SELECT 1 FROM eshop.orders o JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.id=v_order_id AND public.payment_method_is_online_internal(pi.payment_method)) THEN
            RAISE EXCEPTION 'STRIPE_USE_REFUND_ADMISSION_DECISION'; END IF;

        -- Serialize cancellations on the same order before counting survivors.
        PERFORM 1 FROM eshop.orders WHERE id = v_order_id FOR UPDATE;

        -- 3. Get all active tickets currently in this order
        SELECT ARRAY_AGG(t.id)
        INTO v_tickets_in_order
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        WHERE opt."order" = v_order_id
        AND (t.state IS NULL OR t.state != 'storno');

        -- 4. Get intersection: Tickets in this order that we want to cancel
        SELECT ARRAY_AGG(id)
        INTO v_tickets_to_cancel_in_order
        FROM UNNEST(v_tickets_in_order) AS id
        WHERE id = ANY(p_ticket_ids);

        -- A replay or a selection containing only cancelled tickets has no effect.
        IF coalesce(cardinality(v_tickets_to_cancel_in_order), 0) = 0 THEN
            CONTINUE;
        END IF;

        -- 5. Calculate how many would remain
        v_remaining_count := array_length(v_tickets_in_order, 1) - array_length(v_tickets_to_cancel_in_order, 1);

        -- -----------------------------------------------------
        -- SCENARIO A: Full Order Cancellation
        -- -----------------------------------------------------
        IF v_remaining_count <= 0 THEN
            -- Helper function to cancel the entire order
            PERFORM public.cancel_order_domain_internal_v1(v_order_id,p_send_email);

        -- -----------------------------------------------------
        -- SCENARIO B: Partial Cancellation (Modify Order)
        -- -----------------------------------------------------
        ELSE
            -- 1. Mark specific tickets as storno in DB
            PERFORM internal_storno_tickets_221(v_tickets_to_cancel_in_order);

            -- 2. Fetch Order Data
            SELECT data, price INTO v_original_data, v_current_price
            FROM eshop.orders WHERE id = v_order_id;

            v_updated_tickets_json := '[]'::JSONB;
            v_removed_price := 0;

            -- 3. Rebuild JSON data, filtering out cancelled tickets and summing price to remove
            FOR v_ticket_elem IN SELECT * FROM jsonb_array_elements(v_original_data->'tickets')
            LOOP
                v_ticket_id_to_remove := (v_ticket_elem->>'id')::BIGINT;

                -- If this ticket is one of the ones being cancelled
                IF v_ticket_id_to_remove = ANY(v_tickets_to_cancel_in_order) THEN
                    -- Sum up price to deduct
                    FOR v_product_elem IN SELECT * FROM jsonb_array_elements(v_ticket_elem->'products')
                    LOOP
                        v_removed_price := v_removed_price + COALESCE((v_product_elem->>'price')::NUMERIC, 0);
                    END LOOP;
                ELSE
                    -- Keep this ticket in the new JSON
                    v_updated_tickets_json := v_updated_tickets_json || v_ticket_elem;
                END IF;
            END LOOP;

            -- Fence unsent snapshots of the previous ticket set, and keep the
            -- payment amount aligned with the new order total.
            PERFORM public.cancel_order_email_intents(v_order_id);
            UPDATE eshop.payment_info SET amount=GREATEST(0, COALESCE(v_current_price,0)-v_removed_price)
            WHERE id=(SELECT payment_info FROM eshop.orders WHERE id=v_order_id);

            -- 4. Update Order (Data & Price)
            UPDATE eshop.orders
            SET
                data = v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                price = GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                email_payment_version = email_payment_version + 1,
                updated_at = NOW()
            WHERE id = v_order_id;

            -- Refresh only this order's existing reminder schedule for its new amount.
            PERFORM public.set_payment_deadline(pi.id,pi.deadline)
            FROM eshop.payment_info pi JOIN eshop.orders o ON o.payment_info=pi.id
            WHERE o.id=v_order_id AND o.state='ordered' AND pi.deadline IS NOT NULL;

            -- Existing delivery policy prepares the surviving tickets if their
            -- paid order has not finished sending yet; sent orders stay untouched.
            PERFORM public.enqueue_paid_order_tickets(v_order_id);

            -- 5. Insert ONE history record for this modification
            INSERT INTO eshop.orders_history (
                "order",
                data,
                state,
                price,
                created_at
            )
            VALUES (
                v_order_id,
                v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                (SELECT state FROM eshop.orders WHERE id=v_order_id),
                GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                NOW()
            );
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION public.storno_tickets_bulk_internal_v1(p_ticket_ids bigint[], p_send_email boolean) OWNER TO postgres;

