--
-- Name: submit_event_feedback(bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_event_feedback(p_event bigint, p_rating text, p_note text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE p_occasion bigint; r jsonb;
BEGIN
 SELECT occasion INTO p_occasion FROM public.events WHERE id=p_event;
 IF p_occasion IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 r:=public.submit_event_feedback_client_sync_v1(p_occasion,p_event,p_rating,p_note,p_client_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',r->'code','data',r#>'{data,feedback}','message',r#>'{data,message}');
END $$;


ALTER FUNCTION public.submit_event_feedback(p_event bigint, p_rating text, p_note text, p_client_id uuid) OWNER TO postgres;

--
-- Name: submit_event_feedback_client_sync_v1(bigint, bigint, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_event_feedback_client_sync_v1(p_occasion bigint, p_event bigint, p_rating text, p_note text, p_client_id uuid, p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_client uuid; v_begin jsonb; v_hash text;
  v_result jsonb; v_before public.event_feedback%ROWTYPE;
  v_after public.event_feedback%ROWTYPE; v_private_impacts jsonb:='[]'::jsonb;
  v_replacements jsonb:='[]'::jsonb; v_operation text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.events e
    WHERE e.id=p_event AND e.occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='feedback event outside occasion'; END IF;
  v_client:=CASE WHEN v_actor IS NULL THEN p_client_id ELSE NULL END;
  IF v_actor IS NULL AND v_client IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='anonymous client id required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'event',p_event,'rating',p_rating,'note',p_note,
    'clientId',v_client)::text,'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'feedback.submit',p_occasion,v_client,v_hash);
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,'feedback.submit',
      p_occasion,v_actor,v_hash);
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=p_event FOR UPDATE;
  IF v_actor IS NULL THEN
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user" IS NULL AND f.client_id=v_client
      FOR UPDATE;
  ELSE
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user"=v_actor FOR UPDATE;
  END IF;
  v_result:=public.submit_event_feedback_internal_v1(
    p_event,p_rating,p_note,v_client);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,400) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,
      jsonb_build_object('message',v_result->>'message'));
  END IF;
  SELECT * INTO STRICT v_after FROM public.event_feedback f
    WHERE f.id=(v_result#>>'{data,id}')::bigint;
  IF v_before.id IS NOT NULL AND v_before.rating IS NOT DISTINCT FROM v_after.rating
      AND v_before.note IS NOT DISTINCT FROM v_after.note
      AND v_before.data IS NOT DISTINCT FROM v_after.data THEN
    UPDATE public.event_feedback SET updated_at=v_before.updated_at
      WHERE id=v_after.id;
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('feedback',public.get_event_feedback_command_data_v1(v_after.id)));
  END IF;
  v_operation:=CASE WHEN v_before.id IS NULL THEN 'insert' ELSE 'update' END;
  IF v_actor IS NOT NULL AND EXISTS (SELECT 1 FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_private_impacts:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor));
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor,
      'payload',public.get_private_feedback_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'feedback.submit','feedback',jsonb_build_array(jsonb_build_object(
      'entityType','event_feedback','entityId',v_after.id,'operation',v_operation,
      'safeLabel','Event feedback','changedFields',jsonb_build_array('rating','note'))),
    '{}',v_private_impacts,'[]',jsonb_build_object(
      'feedback',public.get_event_feedback_command_data_v1(v_after.id)),
    '{}','[]',CASE WHEN v_actor IS NULL THEN 'unknown' ELSE 'user' END,NULL,
    v_replacements);
END; $$;


ALTER FUNCTION public.submit_event_feedback_client_sync_v1(p_occasion bigint, p_event bigint, p_rating text, p_note text, p_client_id uuid, p_command_id uuid) OWNER TO postgres;

--
-- Name: submit_event_feedback_internal_v1(bigint, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_event_feedback_internal_v1(p_event bigint, p_rating text, p_note text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_event public.events%ROWTYPE;
    v_user UUID := auth.uid();
    v_note TEXT := NULLIF(btrim(COALESCE(p_note, '')), '');
    v_is_limited BOOLEAN;
    v_is_editor BOOLEAN;
    v_feedback public.event_feedback%ROWTYPE;
BEGIN
    IF p_rating NOT IN ('happy', 'neutral', 'sad') THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Invalid rating');
    END IF;

    IF char_length(COALESCE(v_note, '')) > 2000 THEN
        RETURN jsonb_build_object('code', 413, 'message', 'Feedback text is too long');
    END IF;

    SELECT *
    INTO v_event
    FROM public.events
    WHERE id = p_event
      AND is_hidden = false;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
    END IF;

    IF NOT public.get_is_event_allowed(p_event) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Event is not available');
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(v_event.occasion) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback feature is not enabled for this occasion');
    END IF;

    IF COALESCE(v_event.data->>'feedback_enabled', 'false') <> 'true' THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback is not enabled for this event');
    END IF;

    v_is_editor := public.get_is_editor_view_on_occasion(v_event.occasion);

    IF now() < v_event.start_time AND NOT v_is_editor THEN
        RETURN jsonb_build_object('code', 409, 'message', 'Feedback is not open yet');
    END IF;

    v_is_limited := COALESCE(v_event.max_participants, 0) > 0;
    IF v_is_limited AND NOT v_is_editor THEN
        IF v_user IS NULL THEN
            RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required for feedback on this event');
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.event_users eu
            WHERE eu.event = p_event
              AND eu."user" = v_user
        ) THEN
            RETURN jsonb_build_object('code', 403, 'message', 'Only signed-in participants can rate this event');
        END IF;
    END IF;

    IF v_user IS NULL AND p_client_id IS NULL THEN
        RETURN jsonb_build_object('code', 401, 'message', 'Client id is required for anonymous feedback');
    END IF;

    IF v_user IS NOT NULL THEN
        INSERT INTO public.event_feedback (event, occasion, "user", rating, note)
        VALUES (p_event, v_event.occasion, v_user, p_rating, v_note)
        ON CONFLICT (event, "user") WHERE "user" IS NOT NULL
        DO UPDATE SET
            rating = EXCLUDED.rating,
            note = EXCLUDED.note,
            updated_at = now()
        RETURNING * INTO v_feedback;
    ELSE
        INSERT INTO public.event_feedback (event, occasion, client_id, rating, note)
        VALUES (p_event, v_event.occasion, p_client_id, p_rating, v_note)
        ON CONFLICT (event, client_id) WHERE "user" IS NULL AND client_id IS NOT NULL
        DO UPDATE SET
            rating = EXCLUDED.rating,
            note = EXCLUDED.note,
            updated_at = now()
        RETURNING * INTO v_feedback;
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', v_feedback.id,
            'event', v_feedback.event,
            'rating', v_feedback.rating,
            'note', v_feedback.note,
            'created_at', v_feedback.created_at,
            'updated_at', v_feedback.updated_at
        )
    );
END;
$$;


ALTER FUNCTION public.submit_event_feedback_internal_v1(p_event bigint, p_rating text, p_note text, p_client_id uuid) OWNER TO postgres;

--
-- Name: submit_unit_verification(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_unit_verification(p_unit bigint, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE p public.unit_legal_profiles; org bigint; errors jsonb:='{}'; k text; v text;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.can_manage_unit_legal_profile(p_unit) THEN
  RAISE EXCEPTION 'Legal profile submission denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile'); END IF;
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(public.get_unit_legal_profile(p_unit)->'profile') WHERE key=ANY(ARRAY['legalName','countryCode','registrationNumber','contactEmail']) LOOP
  IF coalesce(v,'')='' THEN errors:=errors||jsonb_build_object(k,'REQUIRED'); END IF;
 END LOOP;
 IF coalesce(p.street,'')='' OR coalesce(p.city,'')='' OR coalesce(p.postal_code,'')='' THEN errors:=errors||jsonb_build_object('address','REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INCOMPLETE_PROFILE','fieldErrors',errors); END IF;
 IF p.status NOT IN ('unverified','rejected','revoked') THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_TRANSITION','fieldErrors','{}'::jsonb); END IF;
 UPDATE public.unit_legal_profiles SET revision=revision+1,status='pending',submitted_at=statement_timestamp(),submitted_by=auth.uid(),
 reviewed_at=NULL,reviewed_by=NULL,reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL WHERE unit_id=p_unit;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'submit',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 PERFORM public.enqueue_unit_verification_request(p_unit);
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $$;


ALTER FUNCTION public.submit_unit_verification(p_unit bigint, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: suggest_occasion_setup_form_link(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.suggest_occasion_setup_form_link(p_id uuid, p_title text, p_requested_link text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE d public.occasion_setup_drafts; base text; candidate text; suffix integer:=1; year text;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF length(coalesce(p_title,''))>500 OR length(coalesce(p_requested_link,''))>80 THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid public link input'; END IF;
 base:=trim(both '_' from regexp_replace(public.f_unaccent(left(coalesce(p_title,''),500)),'[^a-z0-9]+','_','g'));
 base:=trim(trailing '_' from left(base,64));
 IF base='' THEN base:='akce'; END IF;
 year:=substring(coalesce(d.data->>'start',d.data->>'start_time','') from '^([0-9]{4})-');
 IF year IS NOT NULL AND base !~ '[0-9]{4}' THEN base:=base||'_'||year; END IF;
 candidate:=base;
 WHILE EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=candidate) LOOP
  suffix:=suffix+1; candidate:=base||'_'||suffix;
  IF suffix>1000 THEN candidate:=base||'_'||left(replace(d.id::text,'-',''),8); EXIT; END IF;
 END LOOP;
 -- Deterministic bounded fallback, still checked rather than presumed free.
 IF EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=candidate) THEN
  RAISE unique_violation USING MESSAGE='Public link suggestions exhausted'; END IF;
 RETURN jsonb_build_object('suggestion',candidate,'available',
  CASE WHEN p_requested_link IS NULL OR p_requested_link='' THEN NULL
  ELSE p_requested_link ~ '^[a-z0-9]+([-_][a-z0-9]+)*$'
    AND NOT EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=p_requested_link) END);
END $_$;


ALTER FUNCTION public.suggest_occasion_setup_form_link(p_id uuid, p_title text, p_requested_link text) OWNER TO postgres;

--
-- Name: swap_blueprint_seats(bigint, bigint, bigint, bigint, bigint, bigint, bigint[], bigint[], bigint, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.swap_blueprint_seats(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_first bigint, p_second bigint, p_source_spots bigint[], p_target_spots bigint[], p_expected_revision bigint, p_confirmation_hash text, p_command_id uuid, p_editor boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE result jsonb;
BEGIN
 IF p_editor IS NULL OR p_command_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0
  OR p_confirmation_hash IS NULL OR p_confirmation_hash!~'^[0-9a-f]{64}$'
  OR coalesce(cardinality(p_source_spots),0)=0 OR coalesce(cardinality(p_target_spots),0)=0
  OR cardinality(p_source_spots)+cardinality(p_target_spots)>(CASE WHEN p_editor THEN 20000 ELSE 1000 END) THEN
  RAISE invalid_parameter_value USING MESSAGE='confirmed swap required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL)
  OR (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=p_occasion AND blueprint=p_blueprint)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='swap selection unavailable'; END IF;
 result:=public.swap_blueprint_seats_command_internal(p_first,p_second,p_command_id,
  jsonb_build_object('hash',p_confirmation_hash,'source',to_jsonb(p_source_spots),'target',to_jsonb(p_target_spots),
   'blueprint',p_blueprint,'revision',p_expected_revision));
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=p_occasion AND blueprint=p_blueprint)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='swap selection unavailable'; END IF;
 IF NOT p_editor THEN result:=result-'sync'; END IF;
 RETURN result;
END $_$;


ALTER FUNCTION public.swap_blueprint_seats(p_occasion bigint, p_organization bigint, p_unit bigint, p_blueprint bigint, p_first bigint, p_second bigint, p_source_spots bigint[], p_target_spots bigint[], p_expected_revision bigint, p_confirmation_hash text, p_command_id uuid, p_editor boolean) OWNER TO postgres;

--
-- Name: swap_blueprint_seats_command_internal(bigint, bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.swap_blueprint_seats_command_internal(p_first bigint, p_second bigint, p_command_id uuid, p_confirmation jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE actor uuid:=auth.uid();occ bigint;started jsonb;fingerprint text;users uuid[];
 effect jsonb;affected bigint[];result_data jsonb;money jsonb;
BEGIN
 SELECT occasion INTO occ FROM public.client_mutation_receipts
 WHERE command_id=p_command_id AND actor_id=actor AND command_name='inventory.spots.swap';
 IF NOT FOUND THEN SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(p_first,p_second); END IF;
 IF actor IS NULL OR p_first IS NULL OR p_second IS NULL OR p_first=p_second OR occ IS NULL
  OR public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 fingerprint:=encode(extensions.digest(convert_to((jsonb_build_object('spot1',p_first,'spot2',p_second)
  ||CASE WHEN p_confirmation IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('confirmation',p_confirmation) END)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.spots.swap',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  RETURN started->'response';
 END IF;
 IF (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=occ)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='foreign spot swap'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 affected:=CASE WHEN p_confirmation IS NULL THEN ARRAY[p_first,p_second] ELSE
  public.blueprint_selection_unit_spots_internal(p_first)||public.blueprint_selection_unit_spots_internal(p_second) END;
 SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM eshop.spots s
 JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
 JOIN public.occasion_users ou ON ou.ticket=i.ticket AND ou.occasion=occ WHERE s.id=ANY(affected);
 BEGIN
  effect:=public.apply_blueprint_seat_swap_internal(p_first,p_second);
  IF p_confirmation IS NOT NULL THEN money:=public.project_order_amount_changes_internal(effect->'orders'); END IF;
  IF p_confirmation IS NOT NULL AND
   (effect->>'confirmationHash' IS DISTINCT FROM p_confirmation->>'hash'
    OR effect->'sourceSpotIds' IS DISTINCT FROM p_confirmation->'source'
    OR effect->'targetSpotIds' IS DISTINCT FROM p_confirmation->'target'
    OR effect->'blueprints' IS DISTINCT FROM jsonb_build_array(jsonb_build_object(
     'id',(p_confirmation->>'blueprint')::bigint,'revision',(p_confirmation->>'revision')::bigint))) THEN
   RAISE SQLSTATE 'BP002' USING MESSAGE='confirmed swap changed'; END IF;
 EXCEPTION WHEN SQLSTATE 'BP002' THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_SWAP_CHANGED'));
 WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
 WHEN OTHERS THEN
  IF p_confirmation IS NULL THEN RAISE; END IF;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_SWAP_REJECTED'));
 END;
 -- Legacy adapters share the same late guard, not just the scoped UI/MCP RPC.
 IF public.can_write_orders(occ) IS NOT TRUE OR
  (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=occ)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='swap selection unavailable'; END IF;
 PERFORM public.check_occasion_writable(occ);
 result_data:=jsonb_build_object('spotIds',jsonb_build_array(p_first,p_second));
 IF p_confirmation IS NOT NULL THEN
  result_data:=result_data||jsonb_build_object('blueprintId',(p_confirmation->>'blueprint')::bigint,
   'layoutRevision',(p_confirmation->>'revision')::bigint,'sourceSpotIds',effect->'sourceSpotIds',
   'targetSpotIds',effect->'targetSpotIds','orders',money);
 END IF;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,occ,'inventory.spots.swap',
  jsonb_build_array(jsonb_build_object('entityType','spot_assignment','entityId',NULL,'operation','update',
   'safeLabel','Spot ticket swap','changedFields',jsonb_build_array('order_product_ticket','product'))),users,result_data);
END $$;


ALTER FUNCTION public.swap_blueprint_seats_command_internal(p_first bigint, p_second bigint, p_command_id uuid, p_confirmation jsonb) OWNER TO postgres;

