--
-- Name: update_account_deletion_job(uuid, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_account_deletion_job(p_request_id uuid, p_auth_deleted boolean DEFAULT NULL::boolean, p_onesignal_deleted boolean DEFAULT NULL::boolean, p_error_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_request public.account_deletion_requests%ROWTYPE; v_assets_done boolean;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO v_request FROM public.account_deletion_requests WHERE id=p_request_id FOR UPDATE;
  v_assets_done := COALESCE(v_request.assets_prepared AND
    (SELECT active FROM public.canonical_asset_cutover WHERE singleton) AND
    NOT EXISTS(SELECT 1 FROM public.account_deletion_assets WHERE request_id=p_request_id AND deleted_at IS NULL) AND
    NOT EXISTS(SELECT 1 FROM public.canonical_assets WHERE owner_id=v_request.user_id::text AND deleted_at IS NULL),false);
  UPDATE public.account_deletion_requests SET
    auth_deleted=coalesce(p_auth_deleted,auth_deleted),
    onesignal_deleted=coalesce(p_onesignal_deleted,onesignal_deleted),
    error_class=p_error_class,
    status=CASE
      WHEN v_assets_done AND public_deleted AND coalesce(p_auth_deleted,auth_deleted)
        AND coalesce(p_onesignal_deleted,onesignal_deleted) THEN 'completed'
      WHEN p_error_class IS NOT NULL THEN 'failed' ELSE 'deletion_pending' END,
    completed_at=CASE
      WHEN v_assets_done AND public_deleted AND coalesce(p_auth_deleted,auth_deleted)
        AND coalesce(p_onesignal_deleted,onesignal_deleted) THEN clock_timestamp()
      ELSE completed_at END,
    user_id=CASE
      WHEN v_assets_done AND public_deleted AND coalesce(p_auth_deleted,auth_deleted)
        AND coalesce(p_onesignal_deleted,onesignal_deleted) THEN NULL ELSE user_id END,
    updated_at=clock_timestamp()
  WHERE id=p_request_id AND status IN ('deletion_pending','failed')
  RETURNING * INTO v_request;
  IF v_request.id IS NULL THEN RAISE EXCEPTION 'account_deletion_request_state_conflict' USING ERRCODE = '55000'; END IF;
  RETURN jsonb_build_object('status',v_request.status);
END;
$$;


ALTER FUNCTION public.update_account_deletion_job(p_request_id uuid, p_auth_deleted boolean, p_onesignal_deleted boolean, p_error_class text) OWNER TO postgres;

--
-- Name: update_activities(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_activities(p_occasion bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    eventsData      JSONB;
    placesData      JSONB;
    activitiesData  JSONB;
    apData          JSONB;
    aeData          JSONB;
    aaData          JSONB;
    usersData       JSONB;
BEGIN

   -- Authorization check
    IF (SELECT get_is_editor_view_on_occasion(p_occasion)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    -- (a) all events (including hidden)
    SELECT jsonb_agg(jsonb_build_object(
        'id',                e.id,
        'created_at',        e.created_at,
        'title',             e.title,
        'start_time',        e.start_time,
        'end_time',          e.end_time,
        'max_participants',  e.max_participants,
        'description',       e.description,
        'place',             e.place,
        'split_for_men_women', e.split_for_men_women,
        'is_group_event',    e.is_group_event,
        'updated_at',        e.updated_at,
        'is_hidden',         e.is_hidden,
        'occasion',          e.occasion,
        'type',              e.type,
        'data',              e.data
    )) INTO eventsData
    FROM public.events e
    WHERE e.occasion = p_occasion;

    -- (b) all places for this occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id',           p.id,
        'title',        p.title,
        'description',  p.description,
        'type',         p.type,
        'created_at',   p.created_at,
        'coordinates',  p.coordinates,
        'is_hidden',    p.is_hidden,
        'updated_at',   p.updated_at,
        'occasion',     p.occasion
    )) INTO placesData
    FROM public.places p
    WHERE p.occasion = p_occasion;

    -- (c) all activities
    SELECT jsonb_agg(jsonb_build_object(
        'id',           a.id,
        'created_at',   a.created_at,
        'updated_at',   a.updated_at,
        'title',        a.title,
        'description',  a.description,
        'type',         a.type,
        'occasion',     a.occasion,
        'unit',         a.unit,
        'is_hidden',    a.is_hidden,
        'order',        a.order, -- Assuming 'order' column exists in activities table
        'data',         a.data
    )) INTO activitiesData
    FROM public.activities a
    WHERE a.occasion = p_occasion;

    -- (d) activity_assignment_places links
    SELECT jsonb_agg(jsonb_build_object(
        'activity_id', ap.activity_id,
        'place_id',    ap.place_id
    )) INTO apData
    FROM public.activity_assignment_places ap
    JOIN public.activities a ON ap.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (e) activity_assignment_events links
    SELECT jsonb_agg(jsonb_build_object(
        'activity_id', ae.activity_id,
        'event_id',    ae.event_id
    )) INTO aeData
    FROM public.activity_assignment_events ae
    JOIN public.activities a ON ae.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (f) activity_assignments
    SELECT jsonb_agg(jsonb_build_object(
        'id',          aa.id, -- Include the assignment's own UUID
        'activity_id', aa.activity_id,
        'user_info',   aa.user_info,
        'start_time',  aa.start_time,
        'end_time',    aa.end_time,
        'title',       aa.title,
        'description', aa.description,
        'data',        aa.data
    )) INTO aaData
    FROM public.activity_assignments aa
    JOIN public.activities a ON aa.activity_id = a.id -- Join to ensure assignments are for activities of the p_occasion
    WHERE a.occasion = p_occasion;

    -- (g) users for this occasion who are volunteers
    SELECT jsonb_agg(jsonb_build_object(
        'id',        ui.id,
        'name',      ui.name,
        'surname',   ui.surname,
        'sex',       ui.sex,
        'email',     ui.email_readonly -- Aliasing email_readonly to email
        -- Add other user_info fields here if needed, matching the jsonb_build_object
    )) INTO usersData
    FROM public.user_info ui
    JOIN public.occasion_users ou ON ui.id = ou."user"
    WHERE ou.occasion = p_occasion
      AND (ou.data->>'is_volunteer')::boolean = TRUE;

    -- (h) assemble
    RETURN jsonb_build_object(
      'code', 200,
      'data', jsonb_build_object(
        'events',                  COALESCE(eventsData, '[]'::jsonb),
        'places',                  COALESCE(placesData, '[]'::jsonb),
        'activities',              COALESCE(activitiesData, '[]'::jsonb),
        'activity_places',         COALESCE(apData, '[]'::jsonb),
        'activity_events',         COALESCE(aeData, '[]'::jsonb),
        'activity_assignments',    COALESCE(aaData, '[]'::jsonb),
        'user_info',                   COALESCE(usersData, '[]'::jsonb)
      )
    );
END;
$$;


ALTER FUNCTION public.update_activities(p_occasion bigint) OWNER TO postgres;

--
-- Name: update_activities(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_activities(p_occasion_id bigint, p_activities_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.can_write_activity_plan(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 RETURN jsonb_build_object('code',426,'message','Upgrade required for atomic activity publication');
END $$;


