--
-- Name: canonical_assets; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.canonical_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bucket text NOT NULL,
    object_key text NOT NULL,
    sha256 text NOT NULL,
    bytes bigint NOT NULL,
    content_type text NOT NULL,
    visibility text NOT NULL,
    owner_id text,
    source_bucket text NOT NULL,
    source_key text,
    source_storage_record jsonb NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT canonical_assets_bucket_check CHECK ((bucket = ANY (ARRAY['festapp-images'::text, 'festapp-images-private'::text]))),
    CONSTRAINT canonical_assets_bytes_check CHECK ((bytes >= 0)),
    CONSTRAINT canonical_assets_check CHECK (((deleted_at IS NOT NULL) OR ((source_key IS NOT NULL) AND (NOT (owner_id IS DISTINCT FROM (source_storage_record ->> 'owner_id'::text)))))),
    CONSTRAINT canonical_assets_check1 CHECK (((bucket = 'festapp-images'::text) = (visibility = 'public'::text))),
    CONSTRAINT canonical_assets_check2 CHECK (
CASE
    WHEN (object_key ~~ 'ticket-fonts/%'::text) THEN ((owner_id IS NULL) AND (bucket = 'festapp-images-private'::text))
    ELSE ("right"(object_key, 64) = sha256)
END),
    CONSTRAINT canonical_assets_content_type_check CHECK ((length(content_type) > 0)),
    CONSTRAINT canonical_assets_object_key_check CHECK (((object_key ~ '^(assets|images)/storage/[A-Za-z0-9_-]+/[a-f0-9]{20}/[a-f0-9]{64}/[a-f0-9]{64}$'::text) OR (object_key ~ '^ticket-fonts/sha256/[a-f0-9]{64}\.(ttf|woff)$'::text))),
    CONSTRAINT canonical_assets_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT canonical_assets_source_storage_record_check CHECK ((jsonb_typeof(source_storage_record) = 'object'::text)),
    CONSTRAINT canonical_assets_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'private'::text])))
);


