CREATE TABLE public.user_group_info (
    id bigint NOT NULL,
    occasion bigint DEFAULT '1'::bigint NOT NULL,
    title text NOT NULL,
    leader uuid,
    place bigint,
    description text,
    data jsonb,
    type text
);


ALTER TABLE public.user_group_info OWNER TO postgres;

--
-- Name: user_group_info_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.user_group_info ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.user_group_info_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: user_groups; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_groups (
    "user" uuid NOT NULL,
    "group" bigint NOT NULL,
    is_admin boolean DEFAULT false NOT NULL
);


ALTER TABLE public.user_groups OWNER TO postgres;

--
-- Name: user_info; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_info (
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email_readonly text,
    name text,
    surname text,
    sex text,
    phone text,
    data jsonb,
    birth_date date,
    organization bigint DEFAULT '1'::bigint NOT NULL,
    email_delivery text
);


ALTER TABLE public.user_info OWNER TO postgres;

--
-- Name: COLUMN user_info.email_readonly; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_info.email_readonly IS 'Organization-unique canonical account email; shared mailboxes use +N aliases.';


--
-- Name: COLUMN user_info.email_delivery; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_info.email_delivery IS 'Optional non-unique override used only for outbound account email.';


--
-- Name: user_login_qr_credentials; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_login_qr_credentials (
    occasion bigint NOT NULL,
    "user" uuid NOT NULL,
    token_hash text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    rotated_at timestamp with time zone,
    revoked_at timestamp with time zone,
    last_used_at timestamp with time zone,
    use_count bigint DEFAULT 0 NOT NULL,
    manual_token_hash text,
    manual_expires_at timestamp with time zone,
    CONSTRAINT user_login_qr_credentials_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT user_login_qr_credentials_manual_expiry_check CHECK (((manual_token_hash IS NULL) = (manual_expires_at IS NULL))),
    CONSTRAINT user_login_qr_credentials_manual_hash_check CHECK (((manual_token_hash IS NULL) OR (manual_token_hash ~ '^[0-9a-f]{64}$'::text)))
);


ALTER TABLE public.user_login_qr_credentials OWNER TO postgres;

--
-- Name: user_news; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_news (
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    news_id bigint NOT NULL,
    "user" uuid NOT NULL,
    occasion bigint DEFAULT '23'::bigint NOT NULL
);


ALTER TABLE public.user_news OWNER TO postgres;

