);


ALTER TABLE public.user_reset_token OWNER TO postgres;

--
-- Name: wix_billing_activation; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.wix_billing_activation (
    app_id uuid NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    signed_addendum_reference text,
    activation_reference text,
    settlement_source_reference text,
    acquisition_source_reference text,
    CONSTRAINT wix_billing_activation_check CHECK (((NOT enabled) OR ((COALESCE(length(btrim(signed_addendum_reference)), 0) > 0) AND (COALESCE(length(btrim(activation_reference)), 0) > 0) AND (COALESCE(length(btrim(settlement_source_reference)), 0) > 0) AND (COALESCE(length(btrim(acquisition_source_reference)), 0) > 0))))
);


ALTER TABLE public.wix_billing_activation OWNER TO postgres;

--
-- Name: wix_billing_attempts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.wix_billing_attempts (
    id uuid NOT NULL,
    app_id uuid NOT NULL,
    receipt_id text NOT NULL,
    kind text NOT NULL,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    finished_at timestamp with time zone,
    outcome text,
    evidence jsonb,
    CONSTRAINT wix_billing_attempts_outcome_check CHECK ((outcome = ANY (ARRAY['confirmed'::text, 'rejected'::text, 'unknown'::text])))
);


ALTER TABLE public.wix_billing_attempts OWNER TO postgres;

--
-- Name: wix_billing_deliveries; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.wix_billing_deliveries (
    app_id uuid NOT NULL,
    receipt_id text NOT NULL,
    kind text NOT NULL,
    instance_id uuid NOT NULL,
    payload jsonb NOT NULL,
    payload_digest text NOT NULL,
    state text DEFAULT 'prepared'::text NOT NULL,
    attempt_id uuid,
    lease_until timestamp with time zone,
    reconciliation jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT wix_billing_deliveries_kind_check CHECK ((kind = ANY (ARRAY['CHARGE'::text, 'REFUND'::text]))),
    CONSTRAINT wix_billing_deliveries_receipt_id_check CHECK (((length(receipt_id) >= 1) AND (length(receipt_id) <= 1000))),
    CONSTRAINT wix_billing_deliveries_state_check CHECK ((state = ANY (ARRAY['prepared'::text, 'sending'::text, 'confirmed'::text, 'rejected'::text, 'unknown'::text])))
);


ALTER TABLE public.wix_billing_deliveries OWNER TO postgres;

