--
-- Name: transactions Managers can view transactions for their units; Type: POLICY; Schema: eshop; Owner: postgres
--

CREATE POLICY "Managers can view transactions for their units" ON eshop.transactions FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM (eshop.unit_bank_accounts uba
     JOIN public.unit_users uu ON ((uba.unit = uu.unit)))
  WHERE ((uba.bank_account = transactions.bank_account_id) AND (uu."user" = auth.uid()) AND (uu.is_manager = true)))));


