--
-- Name: bank_accounts demo_bank_read; Type: POLICY; Schema: eshop; Owner: postgres
--

CREATE POLICY demo_bank_read ON eshop.bank_accounts FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.demo_occasions demo_bank
  WHERE ((demo_bank.bank_account = bank_accounts.id) AND public.can_read_orders(demo_bank.occasion)))));


--
-- Name: transactions demo_bank_transaction_read; Type: POLICY; Schema: eshop; Owner: postgres
--

CREATE POLICY demo_bank_transaction_read ON eshop.transactions FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.demo_occasions demo_bank
  WHERE ((demo_bank.bank_account = transactions.bank_account_id) AND public.can_read_orders(demo_bank.occasion)))));


--
-- Name: bank_account_requests demo_read_fence; Type: POLICY; Schema: eshop; Owner: postgres
--

CREATE POLICY demo_read_fence ON eshop.bank_account_requests AS RESTRICTIVE FOR SELECT TO anon, authenticated USING ((((NOT public.demo_entity_is_protected('bank'::text, bank_account)) OR ((NOT public.is_demo_bank_account(bank_account)) OR (EXISTS ( SELECT 1
   FROM public.demo_occasions demo_bank
  WHERE ((demo_bank.bank_account = bank_account_requests.bank_account) AND public.can_read_orders(demo_bank.occasion)))))) AND ((NOT public.demo_entity_is_protected('occasion'::text, occasion)) OR ((NOT public.is_demo_occasion(occasion)) OR public.can_read_orders(occasion))) AND ((NOT public.demo_entity_is_protected('order'::text, "order")) OR (EXISTS ( SELECT 1
   FROM eshop.orders demo_row
  WHERE ((demo_row.id = bank_account_requests."order") AND ((NOT public.is_demo_occasion(demo_row.occasion)) OR public.can_read_orders(demo_row.occasion))))))));


