--

-- Preserve application-owned hardening of provider-managed objects outside the
-- application schemas. Their definitions and ownership remain provider-owned.
DROP POLICY IF EXISTS ticket_fonts_private ON storage.objects;
CREATE POLICY ticket_fonts_private ON storage.objects AS RESTRICTIVE
TO authenticated, anon USING (bucket_id <> 'ticket-fonts') WITH CHECK (bucket_id <> 'ticket-fonts');
DO $$ DECLARE routine regprocedure; target regclass; BEGIN
 FOR routine IN SELECT p.oid::regprocedure FROM pg_proc p
 JOIN pg_depend d ON d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e'
 JOIN pg_extension e ON e.oid=d.refobjid WHERE e.extname IN ('dblink','http') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',routine);
 END LOOP;
 FOR target IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='storage' AND c.relname IN ('buckets','objects','buckets_analytics') LOOP
  EXECUTE format('REVOKE TRUNCATE,REFERENCES,TRIGGER ON TABLE %s FROM PUBLIC,anon,authenticated',target);
 END LOOP;
END $$;

REVOKE ALL ON TABLE storage.buckets,storage.objects FROM anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres REVOKE ALL ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin REVOKE ALL ON FUNCTIONS FROM PUBLIC;

